int main() {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        if (fork() > 0) {
            // Child creates a Grandchild and exits immediately
            _exit(0);
        }
        // Grandchild process continues
        sleep(100);
    } else {
        // Parent process
        // Parent does not call wait() yet
        sleep(100);
    }
    return 0;
}

