#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    int fd[2];
    pipe(fd);
    pid_t p1 = fork();

    if (p1 == 0) {
        // Child 1 (C1)
        close(fd[0]);
        pid_t g1 = fork();
        if (g1 == 0) {
            // Grandchild (G)
            int val = 15;
            write(fd[1], &val, sizeof(val));
            printf("G");
            return 0;
        }
        wait(NULL);
        int val = 25;
        write(fd[1], &val, sizeof(val));
        printf("C1");
        close(fd[1]);
        return 0;
    } else {
        // Parent (P)
        pid_t p2 = fork();
        if (p2 == 0) {
            // Child 2 (C2)
            close(fd[1]);
            int res, sum = 0;
            while(read(fd[0], &res, sizeof(res)) > 0) {
                sum += res;
            }
            printf("%d", sum);
            close(fd[0]);
            return 0;
        }
        close(fd[0]);
        close(fd[1]);
        wait(NULL);
        wait(NULL);
        printf("P");
    }
    return 0;
}

