#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

int g_var = 1;

void signal_handler(int sig) {
    if (sig == SIGUSR1) g_var += 3;
    else if (sig == SIGCHLD) g_var *= 2;
}

int main() {
    signal(SIGUSR1, signal_handler);
    signal(SIGCHLD, signal_handler);

    pid_t p = fork();
    if (p == 0) { // Child process
        g_var += 5;
        if (fork() == 0) { // Grandchild process
            g_var += 10;
            kill(getppid(), SIGUSR1);
            exit(0);
        }
        wait(NULL);
        printf("C: %d\n", g_var);
        exit(0);
    }

    sleep(5);
    printf("P: %d\n", g_var);
    return 0;
}

