#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
#include <stdlib.h>

int main() {
    pid_t root = getpid(); 
    if (fork() || fork()) {
        if (!fork()) {
            printf("A %d %d\n", getpid(), getppid());
            exit(0);
        }
    } else {
        if (fork() && fork()) {
            printf("B %d %d\n", getpid(), getppid());
        }
    }

    while(wait(NULL) > 0);

    if (getpid() == root) {
        printf("Root Done: %d\n", getpid());
    }

    return 0;
}

