void* thread_work(void* arg) {
    pthread_mutex_lock(&lock);
    counter += 50;
    sleep(20); // Hold the lock for a long time
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    pthread_t t1;
    pthread_create(&t1, NULL, thread_work, NULL);

    sleep(2); // Ensure thread_work starts and acquires the lock

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        printf("Child: Attempting to lock...\n");
        pthread_mutex_lock(&lock);
        counter += 10;
        printf("Child counter: %d\n", counter);
        pthread_mutex_unlock(&lock);
    } else {
        // Parent process
        wait(NULL);
        printf("Parent counter: %d\n", counter);
    }
    return 0;
}

#include <pthread.h>
