נתונה המחלקה הבאה ב-C המממשת חוצץ מעגלי (bounded buffer) באמצעות סמפורים:

```c
#include <semaphore.h>
#include <stdio.h>

#define BUFFER_SIZE 5

int buffer[BUFFER_SIZE];
int in = 0;
// int out = 0; // Not directly used in produce, omitted for brevity

sem_t mutex;    // Ensures mutual exclusion for buffer access
sem_t full;     // Counts number of occupied slots
sem_t empty;    // Counts number of empty slots

void init_semaphores() {
    sem_init(&mutex, 0, 1);
    sem_init(&full, 0, 0);
    sem_init(&empty, 0, BUFFER_SIZE);
}

void produce(int item) {
    // סדר פעולות שגוי שעלול לגרום לבעיה
    sem_wait(&mutex);   // 1. תפיסת המנעול ראשונה
    sem_wait(&empty);   // 2. המתנה למקום פנוי (תוך החזקת המנעול)

    // קטע קריטי: הוספת פריט לחוצץ
    buffer[in] = item;
    in = (in + 1) % BUFFER_SIZE;

    sem_post(&full);    // 3. איתות שמקום התמלא
    sem_post(&mutex);   // 4. שחרור המנעול
}

// void consume() { ... } // Omitted for brevity
// int main() { ... } // Omitted for brevity
```

