נתונה מימוש חלקי של מנגנון נעילת קוראים-כותבים (Reader-Writer Lock) ב-C/C++ באמצעות mutex-ים של pthreads. המטרה היא לאפשר לקוראים מרובים לגשת למשאב במקביל, אך לאפשר רק לכותב אחד לגשת למשאב בכל רגע, ולמנוע גישת קוראים בזמן כתיבה.

```c
#include <pthread.h>
#include <semaphore.h>

// Global variables
int readers_count = 0;
pthread_mutex_t mutex_readers; // Protects readers_count
pthread_mutex_t resource_lock; // Protects the shared resource for writers

void init() {
    pthread_mutex_init(&mutex_readers, NULL);
    pthread_mutex_init(&resource_lock, NULL);
}

void reader_acquire() {
    pthread_mutex_lock(&mutex_readers);
    readers_count++;
    if (readers_count == 1) {
        pthread_mutex_lock(&resource_lock); // First reader locks resource for writers
    }
    pthread_mutex_unlock(&mutex_readers);
}

void reader_release() {
    pthread_mutex_lock(&mutex_readers);
    readers_count--;
    if (readers_count == 0) {
        pthread_mutex_unlock(&resource_lock); // Last reader unlocks resource for writers
    }
    pthread_mutex_unlock(&mutex_readers);
}

void writer_acquire() {
    pthread_mutex_lock(&resource_lock); // Writer locks the resource
}

void writer_release() {
    pthread_mutex_unlock(&resource_lock); // Writer unlocks the resource
}
```

