#include <stdio.h>
#include <pthread.h>

#define N 1000000

int counter = 0;

void* incrementer(void* arg) {
    for (int i = 0; i < N; i++) {
        counter++;
    }
    return NULL;
}

void* decrementer(void* arg) {
    for (int i = 0; i < N; i++) {
        counter--;
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_create(&tid1, NULL, incrementer, NULL);
    pthread_create(&tid2, NULL, decrementer, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    printf("Final counter value: %d\n", counter);

    return 0;
}

solution.explanation:
הסבר למצב מרוץ (Race Condition):
פעולות הגידול (`counter++`) וההקטנה (`counter--`) אינן אטומיות. כל אחת מהן מורכבת בדרך כלל ממספר הוראות מעבד:
1. טעינת הערך הנוכחי של `counter` מזיכרון לתוך רגיסטר.
2. ביצוע פעולת הגידול/הקטנה על הרגיסטר.
3. שמירת הערך המעודכן מהרגיסטר בחזרה לזיכרון ב-`counter`.

מצב מרוץ מתרחש כאשר שני החוטים מנסים לבצע פעולות אלו בו-זמנית, והגישה לזיכרון משתלבת ביניהן באופן לא צפוי. לדוגמה, אם `counter` שווה 0:
* חוט `incrementer` טוען את `0` לרגיסטר שלו.
* מתבצע מיתוג הקשר (context switch) לחוט `decrementer`.
* חוט `decrementer` טוען גם הוא את `0` לרגיסטר שלו.
* חוט `decrementer` מקטין את הרגיסטר שלו ל`-1` ושומר את `-1` בחזרה ל-`counter`. כעת `counter` שווה `-1`.
* מתבצע מיתוג הקשר בחזרה לחוט `incrementer`.
* חוט `incrementer` מגדיל את הרגיסטר שלו ל-`1` (זוכרים, הוא התחיל מ-`0`!).
* חוט `incrementer` שומר את `1` בחזרה ל-`counter`. כעת `counter` שווה `1`.

במקרה זה, למרות שבוצעו פעולת גידול אחת ופעולת הקטנה אחת, הערך הסופי אינו `0` אלא `1`. באופן דומה, הערך הסופי יכול להיות `-1`. מכיוון שזה קורה `N` פעמים, הערך הסופי של `counter` יכול להיות כל מספר בין `-N` ל-`N` (כולל), ולא בהכרח `0`.

פתרון באמצעות סמפור (Sub-question 7.1):
כדי למנוע את מצב המרוץ ולהבטיח ש-`counter` יהיה `0` בסיום, יש להגן על האזור הקריטי (הפעולות `counter++` ו-`counter--`) באמצעות מנגנון סנכרון כמו סמפור בינארי (המשמש כמו mutex). הסמפור יבטיח שרק חוט אחד יוכל לגשת לאזור הקריטי בכל רגע נתון.

קוד מעודכן:
```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h> // נדרש עבור סמפורים

#define N 1000000

int counter = 0;
sem_t mutex; // הכרזת סמפור

void* incrementer(void* arg) {
    for (int i = 0; i < N; i++) {
        sem_wait(&mutex); // נכנס לאזור הקריטי
        counter++;
        sem_post(&mutex); // יוצא מהאזור הקריטי
    }
    return NULL;
}

void* decrementer(void* arg) {
    for (int i = 0; i < N; i++) {
        sem_wait(&mutex); // נכנס לאזור הקריטי
        counter--;
        sem_post(&mutex); // יוצא מהאזור הקריטי
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2;
    sem_init(&mutex, 0, 1); // אתחול סמפור בינארי לערך 1 (פתוח)

    pthread_create(&tid1, NULL, incrementer, NULL);
    pthread_create(&tid2, NULL, decrementer, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    printf("Final counter value: %d\n", counter);

    sem_destroy(&mutex); // שחרור משאבי הסמפור
    return 0;
}
```

הסבר השינויים:
1. **הכרזת סמפור:** הוספנו משתנה מסוג `sem_t` בשם `mutex` גלובלי.
2. **אתחול סמפור:** בפונקציית `main`, קראנו ל-`sem_init(&mutex, 0, 1)` כדי לאתחל את הסמפור. הפרמטר `0` מציין שהסמפור ישמש בין חוטים באותו תהליך, והפרמטר `1` מאתחל אותו כסמפור בינארי (mutex) זמין.
3. **כניסה לאזור קריטי:** לפני כל גישה ל-`counter` (בתוך הלולאות של `incrementer` ו-`decrementer`), קראנו ל-`sem_wait(&mutex)`. קריאה זו חוסמת את החוט אם הסמפור אינו זמין, ומאפשרת לו להמשיך רק כאשר הסמפור הופך זמין (ואז מקטינה את ערכו).
4. **יציאה מאזור קריטי:** לאחר סיום הפעולה על `counter`, קראנו ל-`sem_post(&mutex)`. קריאה זו משחררת את הסמפור ומאפשרת לחוט אחר (אם יש כזה שממתין) להיכנס לאזור הקריטי.
5. **שחרור משאבי סמפור:** בסיום `main`, קראנו ל-`sem_destroy(&mutex)` כדי לשחרר את המשאבים שהוקצו לסמפור.

שינויים אלו מבטיחים בלעדיות הדדית (mutual exclusion) על הגישה למשתנה `counter`, ובכך מונעים את מצב המרוץ ומבטיחים שהערך הסופי של `counter` יהיה תמיד `0`.

