#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

int balance = 0; // Shared global variable

void* deposit_thread(void* arg) {
    int i;
    for (i = 0; i < 100000; i++) {
        balance++;
    }
    return NULL;
}

void* withdraw_thread(void* arg) {
    int i;
    for (i = 0; i < 100000; i++) {
        balance--;
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2, tid3, tid4;

    pthread_create(&tid1, NULL, deposit_thread, NULL);
    pthread_create(&tid2, NULL, deposit_thread, NULL);
    pthread_create(&tid3, NULL, withdraw_thread, NULL);
    pthread_create(&tid4, NULL, withdraw_thread, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);
    pthread_join(tid3, NULL);
    pthread_join(tid4, NULL);

    printf("Final balance: %d\n", balance);
    return 0;
}

solution.explanation:
### הסבר לבעיה (שאלה 1):
הבעיה המרכזית בקוד היא תנאי מרוץ (Race Condition) בגישה למשתנה הגלובלי המשותף `balance`. הפעולות `balance++` ו-`balance--` אינן אטומיות. הן מורכבות ממספר פעולות מכונה ברמה נמוכה יותר (לדוגמה, עבור `balance++`:
1. קריאת הערך של `balance` מהזיכרון לתוך רגיסטר.
2. הגדלת הערך ברגיסטר.
3. כתיבת הערך המעודכן מהרגיסטר בחזרה לזיכרון).
כאשר מספר חוטים מנסים לבצע פעולות אלו בו-זמנית, ייתכן שחוט אחד יקרא את הערך של `balance`, יבוצע מיתוג הקשר (context switch) לחוט אחר שישנה את `balance`, וכאשר החוט הראשון יחזור לרוץ הוא יכתוב בחזרה ערך שגוי (מבוסס על הערך הישן שקרא לפני שהחוט השני שינה אותו). כתוצאה מכך, חלק מהעדכונים עלולים 'לאבד' (lost updates) והערך הסופי של `balance` יהיה שגוי ולא צפוי, ובדרך כלל לא יהיה 0 כפי שמצופה (שני חוטי הפקדה ושני חוטי משיכה, כל אחד 100,000 פעמים, אמורים לבטל זה את זה).

### קוד מתוקן באמצעות מנעול (mutex) (שאלה 2):
```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

pthread_mutex_t balance_mutex; // Mutex for synchronization
int balance = 0; // Shared global variable

void* deposit_thread_sync(void* arg) {
    int i;
    for (i = 0; i < 100000; i++) {
        pthread_mutex_lock(&balance_mutex); // Acquire lock
        balance++;
        pthread_mutex_unlock(&balance_mutex); // Release lock
    }
    return NULL;
}

void* withdraw_thread_sync(void* arg) {
    int i;
    for (i = 0; i < 100000; i++) {
        pthread_mutex_lock(&balance_mutex); // Acquire lock
        balance--;
        pthread_mutex_unlock(&balance_mutex); // Release lock
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2, tid3, tid4;

    pthread_mutex_init(&balance_mutex, NULL); // Initialize mutex

    pthread_create(&tid1, NULL, deposit_thread_sync, NULL);
    pthread_create(&tid2, NULL, deposit_thread_sync, NULL);
    pthread_create(&tid3, NULL, withdraw_thread_sync, NULL);
    pthread_create(&tid4, NULL, withdraw_thread_sync, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);
    pthread_join(tid3, NULL);
    pthread_join(tid4, NULL);

    printf("Final balance with sync: %d\n", balance);

    pthread_mutex_destroy(&balance_mutex); // Destroy mutex
    return 0;
}
```

### הסבר לפתרון (שאלה 3):
הפתרון המוצע הוא שימוש במנעול (mutex). מנעול הוא פרימיטיב סנכרון המבטיח הדרה הדדית (mutual exclusion), כלומר, רק חוט אחד יכול להחזיק במנעול בכל רגע נתון. לפני כל גישה למשתנה המשותף `balance` (בין אם לצורך הגדלה או הקטנה), החוט קורא לפונקציה `pthread_mutex_lock(&balance_mutex)` כדי לנעול את המנעול. אם המנעול כבר נעול על ידי חוט אחר, החוט הנוכחי נחסם וממתין עד שהמנעול ישוחרר. לאחר סיום הפעולה על `balance` (הקטע הקריטי), החוט קורא לפונקציה `pthread_mutex_unlock(&balance_mutex)` כדי לשחרר את המנעול, ובכך מאפשר לחוטים אחרים שחסומים לנסות לרכוש אותו. 

בצורה זו, פעולות `balance++` ו-`balance--` הופכות לאטומיות מבחינה לוגית: מרגע שחוט נעל את המנעול ועד ששחרר אותו, אף חוט אחר לא יוכל להיכנס לקטע הקריטי ולשנות את `balance`. זה מונע תנאי מרוץ ומבטיח שכל עדכון ל-`balance` יתבצע באופן מלא וללא הפרעה מחוטים אחרים, ובכך מבטיח שהחישוב הסופי של `balance` יהיה נכון (במקרה זה, 0).

