#include <stdio.h>
#include <pthread.h>

#define NUM_THREADS 5
#define ITERATIONS_PER_THREAD 100000

long long global_counter = 0;

void* increment_counter(void* arg) {
    for (int i = 0; i < ITERATIONS_PER_THREAD; ++i) {
        global_counter++;
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, increment_counter, NULL);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final global_counter value: %lld\n", global_counter);
    printf("Expected value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

    return 0;
}

solution.explanation:
א. הבעיה בקטע הקוד היא תנאי מרוץ (race condition). פעולת ההגדלה של המונה (`global_counter++`) אינה פעולה אטומית (atomic operation). היא מורכבת למעשה משלוש פעולות ברמת המעבד:
1. קריאת הערך הנוכחי של `global_counter` לתוך רגיסטר.
2. הגדלת הערך ברגיסטר.
3. כתיבת הערך המעודכן מהרגיסטר בחזרה ל`global_counter`.
כאשר מספר תהליכונים מבצעים פעולה זו במקביל ללא סנכרון, ייתכן שתהליכון אחד יקרא את הערך, ותהליכון אחר יספיק לקרוא את אותו הערך, להגדיל אותו ולכתוב אותו בחזרה, לפני שהתהליכון הראשון יכתוב את הערך המוגדל שלו. כתוצאה מכך, חלק מההגדלות "יאבדו", והערך הסופי של `global_counter` יהיה נמוך מהצפוי.

ב. פתרון באמצעות מנעול (mutex):
המנעול מבטיח שרק תהליכון אחד יוכל להיכנס לקטע הקריטי (critical section) בו מתבצעת פעולת ההגדלה של המונה בכל רגע נתון. תהליכונים אחרים שינסו להיכנס יחסמו עד שהתהליכון המחזיק במנעול ישחרר אותו.
השינויים כוללים:
1. הצהרה על משתנה `pthread_mutex_t`.
2. אתחול המנעול באמצעות `pthread_mutex_init` לפני יצירת התהליכונים.
3. קריאה ל`pthread_mutex_lock` לפני הכניסה לקטע הקריטי.
4. קריאה ל`pthread_mutex_unlock` לאחר היציאה מהקטע הקריטי.
5. השמדת המנעול באמצעות `pthread_mutex_destroy` בסיום.

```c
#include <stdio.h>
#include <pthread.h>

#define NUM_THREADS 5
#define ITERATIONS_PER_THREAD 100000

long long global_counter = 0;
pthread_mutex_t counter_mutex; // Mutex declaration

void* increment_counter_mutex(void* arg) {
    for (int i = 0; i < ITERATIONS_PER_THREAD; ++i) {
        pthread_mutex_lock(&counter_mutex);   // Acquire mutex
        global_counter++;
        pthread_mutex_unlock(&counter_mutex); // Release mutex
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    pthread_mutex_init(&counter_mutex, NULL); // Initialize mutex

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, increment_counter_mutex, NULL);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final global_counter value (with mutex): %lld\n", global_counter);
    printf("Expected value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

    pthread_mutex_destroy(&counter_mutex); // Destroy mutex

    return 0;
}
```

ג. פתרון באמצעות סמפור בינארי:
סמפור בינארי יכול לשמש למטרות הדדית (mutual exclusion) בדומה למנעול. סמפור המאותחל ל-1 מאפשר רק לתהליכון אחד לבצע `sem_wait` בהצלחה, בעוד שאחרים יחסמו. `sem_post` משחרר את הסמפור ומאפשר לתהליכון אחר להיכנס.
השינויים כוללים:
1. הצהרה על משתנה `sem_t`.
2. אתחול הסמפור לערך 1 באמצעות `sem_init` לפני יצירת התהליכונים. הפרמטר השני 0 מציין שהסמפור משותף רק לתהליכונים בתוך אותו תהליך.
3. קריאה ל`sem_wait` לפני הכניסה לקטע הקריטי (פעולת P).
4. קריאה ל`sem_post` לאחר היציאה מהקטע הקריטי (פעולת V).
5. השמדת הסמפור באמצעות `sem_destroy` בסיום.

```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h> // For sem_t

#define NUM_THREADS 5
#define ITERATIONS_PER_THREAD 100000

long long global_counter = 0;
sem_t counter_semaphore; // Semaphore declaration

void* increment_counter_semaphore(void* arg) {
    for (int i = 0; i < ITERATIONS_PER_THREAD; ++i) {
        sem_wait(&counter_semaphore);   // Acquire semaphore (P operation)
        global_counter++;
        sem_post(&counter_semaphore); // Release semaphore (V operation)
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    // Initialize semaphore to 1 (binary semaphore)
    sem_init(&counter_semaphore, 0, 1);

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, increment_counter_semaphore, NULL);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final global_counter value (with semaphore): %lld\n", global_counter);
    printf("Expected value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

    sem_destroy(&counter_semaphore); // Destroy semaphore

    return 0;
}
```

ד. השוואה בין מנעול לסמפור בינארי:
עבור בעיה ספציפית זו של הדדית (mutual exclusion) עבור קטע קריטי בודד, הן מנעול והן סמפור בינארי מספקים פתרון נכון ויעיל. בפועל, ברוב מערכות ההפעלה המודרניות, מנעולים ממוטבים במיוחד למטרה זו ונוטים להיות קלים ויעילים יותר לשימוש עבור הדדית בלבד.
**מנעול (Mutex):**
*   מיועד ספציפית להדדית.
*   לרוב, רק התהליכון שרכש את המנעול יכול לשחרר אותו (בעל "בעלות").
*   מנגנוני זיהוי שגיאות מובנים (לדוגמה, ניסיון לשחרר מנעול שלא נרכש).
*   יכול לתמוך בפרוטוקולי עדיפויות (priority inheritance) למניעת priority inversion.
**סמפור בינארי (Binary Semaphore):**
*   כלי כללי יותר, שיכול לשמש גם להדדית וגם לסנכרון מורכב יותר (למשל, סמפורי ספירה לתבנית מפיק-צרכן).
*   כל תהליכון יכול לבצע `sem_post` גם אם לא הוא ביצע `sem_wait` (אין "בעלות"). זה יכול להיות יתרון במצבים מסוימים, אך גם מקור לשגיאות.
*   במקרה של הדדית פשוטה, מנעול עשוי להיות קצת יותר יעיל או בטוח לשימוש עקב הייעוד הספציפי שלו והתכונות הנוספות שהוזכרו.

