#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For usleep, to simulate work

// Structure for the synchronization mechanism
typedef struct {
  pthread_mutex_t mutex;
  pthread_cond_t cv_workers_ready_to_start_batch;          // Coordinator signals workers to start. Workers wait.
  pthread_cond_t cv_coordinator_notified_of_batch_completion; // Last worker signals coordinator. Coordinator waits.
  int N;                                // Total number of worker threads
  int workers_finished_current_batch;   // Counter for workers completing tasks in the *current* batch
  int current_batch_num;                // The batch number currently being processed by workers (or waiting to be started)
  int total_batches;                    // Total batches to process for the entire system
} BatchCoordinator;

// Arguments for worker threads
typedef struct {
  int id;
  int M; // Number of tasks per worker per batch
  BatchCoordinator* coordinator;
} WorkerArgs;

// Function to initialize the BatchCoordinator
void init_batch_coordinator(BatchCoordinator* bc, int N_workers, int total_batches_system) {
  pthread_mutex_init(&bc->mutex, NULL);
  pthread_cond_init(&bc->cv_workers_ready_to_start_batch, NULL);
  pthread_cond_init(&bc->cv_coordinator_notified_of_batch_completion, NULL);
  bc->N = N_workers;
  bc->workers_finished_current_batch = 0;
  bc->current_batch_num = 0; // Initialize to 0, so workers can start batch 0 immediately
  bc->total_batches = total_batches_system;
}

// Function to destroy the BatchCoordinator
void destroy_batch_coordinator(BatchCoordinator* bc) {
  pthread_mutex_destroy(&bc->mutex);
  pthread_cond_destroy(&bc->cv_workers_ready_to_start_batch);
  pthread_cond_destroy(&bc->cv_coordinator_notified_of_batch_completion);
}

// Worker thread function
void* worker_thread_func(void* arg) {
    WorkerArgs* args = (WorkerArgs*)arg;
    BatchCoordinator* bc = args->coordinator;
    int worker_id = args->id;
    int M = args->M;

    for (int b = 0; b < bc->total_batches; ++b) {
        // --- Phase 1: Worker waits for coordinator to allow starting batch 'b' ---
        pthread_mutex_lock(&bc->mutex);
        while (bc->current_batch_num < b) {
            pthread_cond_wait(&bc->cv_workers_ready_to_start_batch, &bc->mutex);
        }
        pthread_mutex_unlock(&bc->mutex);

        // --- Phase 2: Process M tasks ---
        // Simulate work (e.g., sleep for a short random time)
        usleep(rand() % 100000);

        // --- Phase 3: Worker signals completion and (implicitly) waits for others ---
        pthread_mutex_lock(&bc->mutex);
        bc->workers_finished_current_batch++;

        if (bc->workers_finished_current_batch == bc->N) {
            // Last worker to finish. Signal coordinator.
            pthread_cond_signal(&bc->cv_coordinator_notified_of_batch_completion);
        }
        pthread_mutex_unlock(&bc->mutex);
    }
    return NULL;
}

// Coordinator thread function
void* coordinator_thread_func(void* arg) {
    BatchCoordinator* bc = (BatchCoordinator*)arg;

    for (int b = 0; b < bc->total_batches; ++b) {
        // Phase 1: Coordinator ensures workers are ready for batch 'b' and signals them.
        pthread_mutex_lock(&bc->mutex);
        bc->current_batch_num = b; // Allow workers to start batch 'b'
        pthread_cond_broadcast(&bc->cv_workers_ready_to_start_batch); // Wake up all workers for batch 'b'
        pthread_mutex_unlock(&bc->mutex);

        // Simulate coordinator doing some preparatory work for the batch if any
        usleep(rand() % 50000);

        // Phase 2: Coordinator waits for all workers to finish batch 'b'.
        pthread_mutex_lock(&bc->mutex);
        while (bc->workers_finished_current_batch < bc->N) {
            pthread_cond_wait(&bc->cv_coordinator_notified_of_batch_completion, &bc->mutex);
        }
        // All workers finished batch 'b'. Reset counter for the next batch.
        bc->workers_finished_current_batch = 0;
        pthread_mutex_unlock(&bc->mutex);

        // Simulate coordinator doing some work between batches
        usleep(rand() % 50000);
    }
    return NULL;
}

