    static _Thread_local int local_sense = 0;
    local_sense = !local_sense; // היפוך ה-sense המקומי לכל חוט

    if (atomic_fetch_sub(&b->count, 1) == 1) {
        // החוט האחרון שהגיע
        atomic_store(&b->count, b->N); // הכנה לסבב הבא
        atomic_store(&b->sense, local_sense); // שחרור כל החוטים ע"י שינוי ה-sense הגלובלי
    } else {
        // חוטים שאינם האחרונים מחכים לשינוי ה-sense
        while (atomic_load(&b->sense) != local_sense) {
