void enter_A(ResourceControl *rc);
void leave_A(ResourceControl *rc);
void enter_B(ResourceControl *rc);
void leave_B(ResourceControl *rc);

solution.explanation:
הפתרון משתמש בטכניקת Pass the Baton. הרעיון המרכזי הוא שחוט שנכנס או יוצא בודק אם יש חוטים אחרים שיכולים להיכנס. אם כן, הוא משחרר את הסמפור שלהם מבלי לשחרר את ה-mutex (החוט המשוחרר 'יורש' את ה-mutex). רק אם אין אף חוט שיכול להיכנס, ה-mutex משוחרר.

10.1:
void init(ResourceControl *rc, int M, int K) {
    rc->M = M; rc->K = K;
    rc->inA = 0; rc->inB = 0;
    rc->waitA = 0; rc->waitB = 0;
    sem_init(&rc->lock, 0, 1);
    sem_init(&rc->semA, 0, 0);
    sem_init(&rc->semB, 0, 0);
}

10.2:
void release_next(ResourceControl *rc) {
    if (rc->waitB > 0 && (rc->inA + rc->inB < rc->M)) {
        rc->waitB--; rc->inB++;
        sem_post(&rc->semB);
    } else if (rc->waitA > 0 && (rc->inA + rc->inB < rc->M) && (rc->inA < rc->K) && !(rc->waitB > 0 && rc->inA == rc->K - 1)) {
        rc->waitA--; rc->inA++;
        sem_post(&rc->semA);
    } else {
        sem_post(&rc->lock);
    }
}

void enter_A(ResourceControl *rc) {
    sem_wait(&rc->lock);
    if ((rc->inA + rc->inB < rc->M) && (rc->inA < rc->K) && !(rc->waitB > 0 && rc->inA == rc->K - 1)) {
        rc->inA++;
        release_next(rc);
    } else {
        rc->waitA++;
        sem_post(&rc->lock);
        sem_wait(&rc->semA);
        release_next(rc);
    }
}

void leave_A(ResourceControl *rc) {
    sem_wait(&rc->lock);
    rc->inA--;
    release_next(rc);
}

void enter_B(ResourceControl *rc) {
    sem_wait(&rc->lock);
    if (rc->inA + rc->inB < rc->M) {
        rc->inB++;
        release_next(rc);
    } else {
        rc->waitB++;
        sem_post(&rc->lock);
        sem_wait(&rc->semB);
        release_next(rc);
    }
}

void leave_B(ResourceControl *rc) {
    sem_wait(&rc->lock);
    rc->inB--;
    release_next(rc);
}

המימוש משתמש ב-mutex אחד וב-condition variable אחד כדי לסנכרן את כל N החוטים. המפתח להבטחת פעולה נכונה במחסום דו-שלבי שניתן לשימוש חוזר הוא ניהול מצב המחזור הנוכחי (current_wave) ומונה החוטים שהגיעו (count).

**מבנה `TwoPhaseBarrier`:**
```c
#include <pthread.h>

typedef struct {
    int N;
    int count;          // Threads arrived at the current active wave
    int current_wave;   // 0 for phase1, 1 for phase2. Increments after all threads pass a phase.
                        // So, it will be 0 when waiting for phase1_checkin, then 1 for phase2_checkin, then 0 again.
    pthread_mutex_t mutex;
    pthread_cond_t cond; // Single condition variable is often sufficient for reusable barriers
} TwoPhaseBarrier;
```

**פונקציות המימוש:**
```c
void init_two_phase_barrier(TwoPhaseBarrier *bar, int N) {
    bar->N = N;
    bar->count = 0;
    bar->current_wave = 0; // Start with phase 0 (phase1_checkin)
    pthread_mutex_init(&bar->mutex, NULL);
    pthread_cond_init(&bar->cond, NULL);
}

void destroy_two_phase_barrier(TwoPhaseBarrier *bar) {
    pthread_mutex_destroy(&bar->mutex);
    pthread_cond_destroy(&bar->cond);
}

// Internal helper function for both phases
void phase_checkin(TwoPhaseBarrier *bar, int expected_wave) {
    pthread_mutex_lock(&bar->mutex);

    // Wait if this thread is too fast and arrived for a future wave
    // Or if it's too slow and arrived for a past wave (should not happen with correct usage)
    while (bar->current_wave != expected_wave) {
        pthread_cond_wait(&bar->cond, &bar->mutex);
    }

    bar->count++;
    if (bar->count < bar->N) {
        // Not the last thread, wait for others in the same wave
        while (bar->current_wave == expected_wave) { // Wait until the current_wave changes (signaling completion)
            pthread_cond_wait(&bar->cond, &bar->mutex);
        }
    } else {
        // Last thread for this wave
        bar->count = 0; // Reset for the next wave
        bar->current_wave = (bar->current_wave + 1) % 2; // Advance to the next wave (0 -> 1, 1 -> 0)
        pthread_cond_broadcast(&bar->cond); // Wake up all waiting threads
    }
    pthread_mutex_unlock(&bar->mutex);
}

void phase1_checkin(TwoPhaseBarrier *bar) {
    phase_checkin(bar, 0);
}

void phase2_checkin(TwoPhaseBarrier *bar) {
    phase_checkin(bar, 1);
}
```

**לוגיקת הפעולה:**
1.  **נעילת mutex**: כל חוט נועל את ה-mutex בכניסה לפונקציה כדי להגן על משתני המצב המשותפים.
2.  **המתנה לשלב הנכון**: 
    *   `while (bar->current_wave != expected_wave)`: חוטים ממתינים כאן אם הם מנסים להיכנס לשלב שאינו השלב הפעיל כרגע. לדוגמה, אם `current_wave` הוא 0 (מצפה ל-`phase1_checkin`) וחוט מנסה לקרוא ל-`phase2_checkin` (עם `expected_wave` של 1), הוא ימתין. זה מונע מחוטים מהירים להקדים את זמנם לשלב הבא או למחזור הבא.
3.  **קידום מונה והמתנה**: 
    *   `bar->count++`: החוט מקדם את מונה ההגעה לשלב הנוכחי.
    *   `if (bar->count < bar->N)`: אם זה לא החוט האחרון שהגיע, הוא ממתין על משתנה התנאי. התנאי `while (bar->current_wave == expected_wave)` מבטיח שהחוט ימשיך להמתין עד שהחוט האחרון ישנה את `current_wave` (כלומר, השלב הנוכחי הושלם).
4.  **החוט האחרון**: 
    *   `else`: אם זהו החוט ה-N שהגיע לשלב, הוא מבצע את הפעולות הבאות:
        *   `bar->count = 0`: מאפס את המונה עבור השלב הבא.
        *   `bar->current_wave = (bar->current_wave + 1) % 2`: מקדם את השלב הפעיל. אם היינו בשלב 0, עוברים לשלב 1; אם היינו בשלב 1, חוזרים לשלב 0 עבור המחזור הבא.
        *   `pthread_cond_broadcast(&bar->cond)`: מעיר את כל החוטים הממתינים על משתנה התנאי. כעת הם יבדקו מחדש את תנאי ההמתנה שלהם וימשיכו (אלו שחיכו באותו שלב).
5.  **שחרור mutex**: החוט משחרר את ה-mutex ויוצא מהפונקציה.

**הימנעות מבעיות:**
*   **Race Conditions**: ה-mutex מגן על כל הגישות למשתני המצב המשותפים (`count`, `current_wave`).
*   **Deadlock**: לא קיים deadlock מכיוון שכל החוטים פועלים באותו אופן, ורק האחרון מביניהם משחרר את כולם. אין תלות מעגלית במשאבים.
*   **Starvation**: כל החוטים מעוררים באמצעות `pthread_cond_broadcast`, כך שאף חוט לא נשאר תקוע לנצח.
*   **Reusability**: ה-`current_wave` ואיפוס ה-`count` מבטיחים שהמחסום עובד נכון למחזורים עוקבים.

**הערה**: המימוש מניח שכל N החוטים אכן יקראו ל-`phase1_checkin` ולאחר מכן ל-`phase2_checkin` (בסדר הנכון) במחזור נתון. אם חוט ינסה לדלג על שלב או לקרוא לשלב לא נכון, הוא ימתין עד שה-`current_wave` יתאים לדרישתו.

