#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int N;                      // Total threads required for a batch
    int arrived_count;          // Threads that have arrived in the current "wave"
    int passed_count;           // Threads that have passed the barrier in the current "wave"
    int wave;                   // Current wave number for reusability
    pthread_mutex_t mutex;
    pthread_cond_t cond_arrival;   // Threads wait here until batch is full AND condition met
    pthread_cond_t cond_departure; // Threads wait here until all N have departed
    bool condition_met;         // The external condition state
} ConditionalTurnstile;

void init(ConditionalTurnstile *ts, int N);
void destroy(ConditionalTurnstile *ts);
void wait_for_batch(ConditionalTurnstile *ts);
void set_condition(ConditionalTurnstile *ts, bool condition_state);

solution.explanation:
פתרון:
המימוש משתמש באלגוריתם מחסום דו-שלבי (two-phase barrier) בשילוב עם מונה דורות (generation counter) על מנת לאפשר שימוש חוזר במחסום ולמנוע תנאי מרוץ כגון "הנוסע הממהר" (early-departer).

מבנה `ConditionalTurnstile`:
*   `N`: מספר החוטים הנדרשים לקבוצה אחת.
*   `arrived_count`: מונה את מספר החוטים שהגיעו לשלב הראשון של המחסום בקבוצה הנוכחית.
*   `passed_count`: מונה את מספר החוטים שעברו את שלב השחרור ומתקדמים לשלב האיפוס בקבוצה הנוכחית.
*   `wave`: מונה דורות, מזהה איזו קבוצה של חוטים נמצאת כרגע במחסום. מתקדם כל פעם שקבוצה שלמה עוברת.
*   `mutex`: מנעול להגנה על משתני המצב (`arrived_count`, `passed_count`, `wave`, `condition_met`).
*   `cond_arrival`: משתנה תנאי עליו ממתינים חוטים בשלב ההגעה, עד שכל `N` החוטים הגיעו וגם `condition_met` נכון.
*   `cond_departure`: משתנה תנאי עליו ממתינים חוטים בשלב העזיבה, עד שהחוט האחרון בקבוצה איפס את המחסום.
*   `condition_met`: דגל בוליאני המייצג את מצב התנאי החיצוני.

```c
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>

typedef struct {
    int N;
    int arrived_count;
    int passed_count;
    int wave;
    pthread_mutex_t mutex;
    pthread_cond_t cond_arrival;
    pthread_cond_t cond_departure;
    bool condition_met;
} ConditionalTurnstile;

void init(ConditionalTurnstile *ts, int N) {
    ts->N = N;
    ts->arrived_count = 0;
    ts->passed_count = 0;
    ts->wave = 0;
    pthread_mutex_init(&ts->mutex, NULL);
    pthread_cond_init(&ts->cond_arrival, NULL);
    pthread_cond_init(&ts->cond_departure, NULL);
    ts->condition_met = false;
}

void destroy(ConditionalTurnstile *ts) {
    pthread_mutex_destroy(&ts->mutex);
    pthread_cond_destroy(&ts->cond_arrival);
    pthread_cond_destroy(&ts->cond_departure);
}

void wait_for_batch(ConditionalTurnstile *ts) {
    pthread_mutex_lock(&ts->mutex);

    int my_wave = ts->wave; // Captures the current wave number for this thread

    ts->arrived_count++;

    // Phase 1: Arrival - threads wait for N arrivals AND the external condition
    if (ts->arrived_count == ts->N) { // This is the N-th thread to arrive
        // The N-th thread waits until the external condition is met
        while (!ts->condition_met) {
            pthread_cond_wait(&ts->cond_arrival, &ts->mutex);
        }
        // Condition is met, and N threads have arrived. Release all threads in this batch.
        // No need to increment wave here, it's done by the last departing thread.
        pthread_cond_broadcast(&ts->cond_arrival);
    } else { // Not the N-th thread to arrive
        // Wait until the N-th thread signals that the batch is ready to proceed
        // and the condition was met. We use 'my_wave' to ensure we wait for the current batch.
        while (my_wave == ts->wave) {
            pthread_cond_wait(&ts->cond_arrival, &ts->mutex);
        }
    }

    // All N threads have now passed the arrival barrier and are released.
    // Phase 2: Departure - threads decrement count and wait for the last thread to reset
    ts->passed_count++;

    if (ts->passed_count == ts->N) { // This is the N-th thread to depart
        // Reset counts and advance the wave for the next batch
        ts->arrived_count = 0;
        ts->passed_count = 0;
        ts->wave++; // Advance wave for the next batch of threads
        // Signal all threads waiting in the departure phase that the barrier is reset
        pthread_cond_broadcast(&ts->cond_departure);
    } else { // Not the N-th thread to depart
        // Wait until the last thread of this batch signals that the barrier is reset
        while (my_wave == ts->wave) {
            pthread_cond_wait(&ts->cond_departure, &ts->mutex);
        }
    }

    pthread_mutex_unlock(&ts->mutex);
}

void set_condition(ConditionalTurnstile *ts, bool condition_state) {
    pthread_mutex_lock(&ts->mutex);
    ts->condition_met = condition_state;
    // If the condition becomes true AND a full batch of threads is waiting,
    // wake them up. This is crucial if the N-th thread is waiting for the condition.
    if (condition_state && ts->arrived_count == ts->N) {
        pthread_cond_broadcast(&ts->cond_arrival);
    }
    pthread_mutex_unlock(&ts->mutex);
}
```

הסבר:

**פונקציה `init(ConditionalTurnstile *ts, int N)`:**
*   מאתחלת את המשתנים `N`, `arrived_count` (מונה חוטים שהגיעו), `passed_count` (מונה חוטים שעזבו), `wave` (מונה דורות לשימוש חוזר במחסום), ואת המנעול ומשתני התנאי. `condition_met` מאותחל ל-`false`.

**פונקציה `destroy(ConditionalTurnstile *ts)`:**
*   משחררת את המשאבים על ידי השמדת המנעול ומשתני התנאי.

**פונקציה `wait_for_batch(ConditionalTurnstile *ts)`:**
1.  **נעילה ורישום גל הדור:** החוט נועל את המוטקס ושומר את מספר ה"גל" (wave) הנוכחי במשתנה מקומי `my_wave`. זה מאפשר לו לזהות מתי המחסום התקדם ל"גל" הבא, ומונע תנאי מרוץ במחסום הניתן לשימוש חוזר.
2.  **שלב ההגעה (Arrival Phase):**
    *   `ts->arrived_count` מקודם. זהו מונה החוטים שהגיעו למחסום ב"גל" הנוכחי.
    *   **אם החוט הוא החוט ה-N-י שמגיע (`ts->arrived_count == ts->N`):**
        *   הוא ממתין (באמצעות `pthread_cond_wait` על `cond_arrival`) עד ש-`condition_met` יהפוך ל-`true`. הוא האחראי לשחרר את הקבוצה.
        *   ברגע שהתנאי מתקיים, הוא משחרר את כל `N-1` החוטים הממתינים (באמצעות `pthread_cond_broadcast` על `cond_arrival`).
    *   **אם החוט אינו החוט ה-N-י שמגיע (`ts->arrived_count < ts->N`):**
        *   הוא ממתין (באמצעות `pthread_cond_wait` על `cond_arrival`) כל עוד `my_wave` שווה ל-`ts->wave`. הוא ישוחרר כאשר החוט ה-N-י ישדר `broadcast` וישנה את `my_wave` (על ידי קידום `ts->wave` בשלב העזיבה של הקבוצה).
3.  **שלב העזיבה (Departure Phase):**
    *   לאחר שכל `N` החוטים שוחררו משלב ההגעה, הם מקדמים את `ts->passed_count`. זהו מונה החוטים שעברו את שלב השחרור ב"גל" הנוכחי.
    *   **אם החוט הוא החוט ה-N-י שעובר (`ts->passed_count == ts->N`):**
        *   הוא מאפס את `arrived_count` ו-`passed_count` ל-0. פעולה זו "מנקה" את המחסום לקבוצה הבאה.
        *   הוא מקדם את `ts->wave` (כדי לסמן שהמחסום מוכן לקבוצה הבאה).
        *   הוא משחרר את כל `N-1` החוטים הממתינים בשלב העזיבה (באמצעות `pthread_cond_broadcast` על `cond_departure`).
    *   **אם החוט אינו החוט ה-N-י שעובר (`ts->passed_count < ts->N`):**
        *   הוא ממתין (באמצעות `pthread_cond_wait` על `cond_departure`) כל עוד `my_wave` שווה ל-`ts->wave`. הוא ישוחרר כאשר החוט האחרון יקדם את `ts->wave` ויבצע `broadcast`.
4.  **שחרור:** החוט משחרר את המוטקס.

**פונקציה `set_condition(ConditionalTurnstile *ts, bool condition_state)`:**
1.  נועלת את המוטקס.
2.  מעדכנת את `ts->condition_met` למצב החדש.
3.  אם `condition_state` הפך ל-`true` וגם `ts->arrived_count` שווה ל-`ts->N` (כלומר, קבוצה מלאה של חוטים ממתינה על `cond_arrival`): היא משחררת את כל החוטים הממתינים על `cond_arrival` (באמצעות `pthread_cond_broadcast`). זה מאפשר לחוט ה-N-י (אם הוא ממתין על התנאי) או לשאר החוטים להתקדם.
4.  משחררת את המוטקס.

**טיפול במצבים מיוחדים:**
1.  **`set_condition` נקראת כאשר אין חוטים ממתינים:** הפונקציה תעדכן את `condition_met`. אם `condition_state` הוא `true`, היא תבצע `broadcast` אך לא יהיו חוטים שיושפעו מכך באופן מיידי. החוטים שיגיעו מאוחר יותר ימצאו את `condition_met` כבר כ-`true` ויפעלו בהתאם.
2.  **`set_condition` נקראת מספר פעמים ברצף:** רק הערך הסופי של `condition_state` יהיה רלוונטי. כל קריאה עשויה לבצע `broadcast` אם התנאי הופך ל-`true` וקבוצה מלאה ממתינה. אין בכך בעיה מבחינת נכונות, שכן `pthread_cond_broadcast` הוא אידמפוטנטי במובן זה של חוטים ממתינים.
3.  **שחרור `N` חוטים יחד ואיפוס בטוח (מניעת "הנוסע הממהר"):**
    *   מנגנון ה"גל" (`wave` counter) ומשתני התנאי `cond_arrival` ו-`cond_departure` מבטיחים זאת.
    *   `cond_arrival` מבטיח שכל `N` החוטים יגיעו ושהתנאי יתקיים לפני שמישהו ימשיך. החוט ה-N-י הוא זה שמבצע `broadcast` כדי לשחרר את כולם.
    *   `cond_departure` ומנגנון ה-`passed_count` מבטיחים שכל `N` החוטים יעברו את המחסום לפני ש-`ts->wave` יתקדם שוב. החוט האחרון שעוזב מאפס את המחסום ומקדם את ה"גל", ובכך מונע מחוטים מהגל הבא להתחיל לפני שהגל הקודם סיים את כל שלבי המחסום.
    *   השימוש ב-`my_wave` המקומי בכל חוט מבטיח שחוט שקדם ל"גל" הבא לא ישוחרר בטעות על ידי `broadcast` המיועד ל"גל" קודם, וכן שחוט שפיגר לא ייתקע לנצח.

