#include <stdio.h>
#include <pthread.h>

#define NUM_THREADS 5
#define INCREMENTS_PER_THREAD 100000

int counter = 0;

void* increment_counter(void* arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        counter++;
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, increment_counter, NULL);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final counter value: %d\n", counter);
    return 0;
}

solution.explanation:
101.1: הערך הסופי הצפוי של המונה `counter` הוא `NUM_THREADS * INCREMENTS_PER_THREAD`. במקרה זה, `5 * 100000 = 500000`.

101.2: ערך זה אינו מובטח בפועל. התופעה המתוארת היא מצב מרוץ (Race Condition). מצב מרוץ מתרחש כאשר מספר חוטים ניגשים למשאב משותף (במקרה זה, המשתנה `counter`) ומנסים לשנות אותו במקביל, ללא מנגנון סנכרון מתאים, מה שעלול להוביל לתוצאות בלתי צפויות ושגויות. פעולת הקידום `counter++` אינה אטומית; היא מורכבת משלוש פעולות בסיסיות: קריאת הערך הנוכחי של `counter`, הגדלת הערך, וכתיבת הערך החדש בחזרה ל-`counter`. אם שני חוטים או יותר מבצעים פעולות אלה בו זמנית, חלק מהעדכונים עלולים ללכת לאיבוד.
דוגמה לתזמון שגוי:
1. חוט A קורא את `counter` (לדוגמה, הערך הוא 100).
2. חוט B קורא את `counter` (גם הוא קורא את הערך 100, לפני שחוט A הספיק לכתוב בחזרה).
3. חוט A מגדיל את הערך שקרא (100+1=101) וכותב אותו בחזרה ל-`counter`. כעת `counter` שווה 101.
4. חוט B מגדיל את הערך שקרא (100+1=101) וכותב אותו בחזרה ל-`counter`. כעת `counter` שווה 101.
במקרה זה, למרות שבוצעו שתי פעולות קידום, המונה גדל באחד בלבד במקום בשניים, וקידום אחד אבד.

101.3: כדי לתקן את הקוד ולהבטיח שהמונה יגיע לערכו הצפוי, יש להגן על הקטע הקריטי (הגישה ל-`counter` ושינויו) באמצעות מנגנון סנכרון כמו mutex. התיקון כולל הוספת משתנה mutex גלובלי, אתחולו, נעילתו לפני הגישה למונה ושחרורו לאחריה, ולבסוף השמדתו.

```c
#include <stdio.h>
#include <pthread.h>

#define NUM_THREADS 5
#define INCREMENTS_PER_THREAD 100000

int counter = 0;
pthread_mutex_t mutex; // הצהרה על משתנה mutex גלובלי

void* increment_counter(void* arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        pthread_mutex_lock(&mutex);   // נעילת ה-mutex לפני הגישה לקטע הקריטי
        counter++;                     // הקטע הקריטי
        pthread_mutex_unlock(&mutex); // שחרור ה-mutex לאחר היציאה מהקטע הקריטי
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    pthread_mutex_init(&mutex, NULL); // אתחול ה-mutex

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, increment_counter, NULL);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final counter value: %d\n", counter);

    pthread_mutex_destroy(&mutex); // השמדת ה-mutex
    return 0;
}
```

