#include <stdio.h>
#include <pthread.h>
#include <unistd.h> // For sleep

pthread_mutex_t mutex1 = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex2 = PTHREAD_MUTEX_INITIALIZER;

int resource1 = 0;
int resource2 = 0;

void* thread_func1(void* arg) {
    printf("Thread 1: Trying to lock mutex1...\n");
    pthread_mutex_lock(&mutex1);
    printf("Thread 1: Locked mutex1. Trying to lock mutex2...\n");
    sleep(1); 
    pthread_mutex_lock(&mutex2);
    printf("Thread 1: Locked mutex2. Accessing resources.\n");

    resource1++;
    resource2++;

    pthread_mutex_unlock(&mutex2);
    printf("Thread 1: Unlocked mutex2.\n");
    pthread_mutex_unlock(&mutex1);
    printf("Thread 1: Unlocked mutex1. Exiting.\n");
    return NULL;
}

void* thread_func2(void* arg) {
    printf("Thread 2: Trying to lock mutex2...\n");
    pthread_mutex_lock(&mutex2);
    printf("Thread 2: Locked mutex2. Trying to lock mutex1...\n");
    sleep(1); 
    pthread_mutex_lock(&mutex1);
    printf("Thread 2: Locked mutex1. Accessing resources.\n");

    resource1--;
    resource2--;

    pthread_mutex_unlock(&mutex1);
    printf("Thread 2: Unlocked mutex1.\n");
    pthread_mutex_unlock(&mutex2);
    printf("Thread 2: Unlocked mutex2. Exiting.\n");
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_create(&tid1, NULL, thread_func1, NULL);
    pthread_create(&tid2, NULL, thread_func2, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    printf("Main: Final resource1 = %d, resource2 = %d\n", resource1, resource2);

    pthread_mutex_destroy(&mutex1);
    pthread_mutex_destroy(&mutex2);

    return 0;
}

solution.explanation:
פתרון:

א. כן, קיים פוטנציאל למצב של קיפאון (Deadlock) בתוכנית זו.
ההסבר: קיפאון יכול להתרחש כאשר Thread 1 רוכש את mutex1 ולאחר מכן מנסה לרכוש את mutex2, ובמקביל Thread 2 רוכש את mutex2 ולאחר מכן מנסה לרכוש את mutex1. אם התזמון של ריצת התהליכונים מאפשר לכל אחד מהם לרכוש את המנעול הראשון שלו לפני שהשני רכש את שניהם, שניהם יכנסו למצב המתנה אינסופי זה לזה.
התנאים ההכרחיים לקיפאון שמתקיימים כאן הם (תנאי קופמן):
1.  **הדדיות (Mutual Exclusion)**: המנעולים (mutexes) מבטיחים שרק תהליכון אחד יכול להחזיק במשאב (מנעול) בכל רגע נתון.
2.  **החזק והמתן (Hold and Wait)**: כל תהליכון מחזיק במנעול אחד (לדוגמה, Thread 1 מחזיק ב-mutex1) וממתין למנעול נוסף (mutex2).
3.  **אי-הפקעה (No Preemption)**: לא ניתן להפקיע מנעול מתהליכון שמחזיק בו; המנעול ישוחרר רק מרצון על ידי התהליכון המחזיק בו.
4.  **המתנה מעגלית (Circular Wait)**: נוצרת שרשרת המתנה מעגלית: Thread 1 ממתין ל-mutex2 שמוחזק על ידי Thread 2, ו-Thread 2 ממתין ל-mutex1 שמוחזק על ידי Thread 1.
הקריאות ל-sleep(1) מגבירות את הסיכוי לתזמון שיגרום לקיפאון.

ב. בהנחה שהתוכנית רצה ללא קיפאון ומסיימת את ריצתה בהצלחה, שני התהליכונים יבצעו את פעולותיהם באופן מלא.
*   Thread 1 מגדיל את resource1 ואת resource2 באחד (resource1 = 1, resource2 = 1).
*   Thread 2 מקטין את resource1 ואת resource2 באחד (resource1 = 0, resource2 = 0).
לכן, הערכים הסופיים יהיו:
resource1 = 0
resource2 = 0

ג. ניתן למנוע קיפאון על ידי שבירת תנאי 'המתנה מעגלית' (Circular Wait) באמצעות קביעת סדר קבוע לרכישת המנעולים. השינוי המינימלי ביותר הוא לגרום לשני התהליכונים לרכוש את המנעולים באותו הסדר. לדוגמה, שניהם ירכשו תמיד את mutex1 ואז את mutex2.

שינוי מוצע בקוד (בפונקציה thread_func2 בלבד):
```c
void* thread_func2(void* arg) {
    printf("Thread 2: Trying to lock mutex1...\n");
    pthread_mutex_lock(&mutex1); // שינוי כאן: קודם mutex1
    printf("Thread 2: Locked mutex1. Trying to lock mutex2...\n");
    sleep(1); 
    pthread_mutex_lock(&mutex2); // ואז mutex2
    printf("Thread 2: Locked mutex2. Accessing resources.\n");

    resource1--;
    resource2--;

    pthread_mutex_unlock(&mutex2);
    printf("Thread 2: Unlocked mutex2.\n");
    pthread_mutex_unlock(&mutex1);
    printf("Thread 2: Unlocked mutex1. Exiting.\n");
    return NULL;
}
```
ההיגיון מאחורי השינוי: כאשר כל התהליכונים רוכשים את המנעולים באותו סדר (לדוגמה, תמיד mutex1 ואז mutex2), לא יכולה להיווצר המתנה מעגלית. אם תהליכון אחד מחזיק ב-mutex1 וממתין ל-mutex2, אף תהליכון אחר לא יכול להחזיק ב-mutex2 ולחכות ל-mutex1, מכיוון שהוא היה צריך לרכוש קודם את mutex1 (שכבר מוחזק). זה מבטיח שאם יתרחש חסימה, היא תהיה ליניארית ולא מעגלית, ובסופו של דבר אחד מהתהליכונים יתקדם וישחרר את המשאבים.

