נתונה תוכנית C הבאה המשתמשת ב-pthreads, mutexes, ו-condition variables. התוכנית מדמה תהליך יצרן-צרכן עם משאב משותף (מונה `count`) וגודל חיץ מוגבל (`MAX_COUNT`).

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h> // For usleep

#define MAX_COUNT 5
#define NUM_OPERATIONS 10

int count = 0;
pthread_mutex_t mutex;
pthread_cond_t cond_producer; // Condition for producer to wait if buffer is full
pthread_cond_t cond_consumer; // Condition for consumer to wait if buffer is empty

void* producer(void* arg) {
    for (int i = 0; i < NUM_OPERATIONS; ++i) {
        pthread_mutex_lock(&mutex);
        while (count == MAX_COUNT) {
            printf("Producer waiting (count=%d)...\n", count);
            pthread_cond_wait(&cond_producer, &mutex);
        }
        count++;
        printf("Producer: count = %d\n", count);
        pthread_cond_signal(&cond_consumer);
        pthread_mutex_unlock(&mutex);
        usleep(100000); // Simulate work
    }
    return NULL;
}

void* consumer(void* arg) {
    for (int i = 0; i < NUM_OPERATIONS; ++i) {
        pthread_mutex_lock(&mutex);
        while (count == 0) {
            printf("Consumer waiting (count=%d)...\n", count);
            pthread_cond_wait(&cond_consumer, &mutex);
        }
        count--;
        printf("Consumer: count = %d\n", count);
        pthread_cond_signal(&cond_producer);
        pthread_mutex_unlock(&mutex);
        usleep(150000); // Simulate work
    }
    return NULL;
}

int main() {
    pthread_t prod_tid, cons_tid;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond_producer, NULL);
    pthread_cond_init(&cond_consumer, NULL);

    pthread_create(&prod_tid, NULL, producer, NULL);
    pthread_create(&cons_tid, NULL, consumer, NULL);

    pthread_join(prod_tid, NULL);
    pthread_join(cons_tid, NULL);

    printf("Final count value: %d\n", count);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond_producer);
    pthread_cond_destroy(&cond_consumer);

    return 0;
}
```

