#include <stdio.h>
#include <pthread.h>
#include <unistd.h> // for sleep

#define NUM_INCREMENTERS 2
#define NUM_DECREMENTERS 2
#define NUM_MONITORS 1
#define ITERATIONS 5

int counter = 0;
pthread_mutex_t mutex;
pthread_cond_t can_decrement; // For decrementers to wait if counter is 0
pthread_cond_t counter_is_even; // For monitors to wait if counter is odd

// To handle starvation for decrementers
int waiting_decrementers = 0; // Number of decrementers waiting
pthread_cond_t incrementers_block; // For incrementers to wait if decrementers are starving

void* incrementer_thread(void* arg) {
    for (int i = 0; i < ITERATIONS; ++i) {
        pthread_mutex_lock(&mutex);
        // FLAW related to starvation avoidance for decrementers.
        // If there are waiting decrementers and counter is 0, incrementers should wait.
        // But what if counter is > 0 and decrementers are waiting? They should run first.
        while (waiting_decrementers > 0 && counter == 0) {
            printf("Incrementer: Waiting due to starving decrementers. Counter: %d\n", counter);
            pthread_cond_wait(&incrementers_block, &mutex);
        }

        counter++;
        printf("Incrementer: Counter is now %d\n", counter);

        // Signal decrementers if counter became positive
        pthread_cond_signal(&can_decrement); 

        // Signal monitors if counter became even
        if (counter % 2 == 0) {
            pthread_cond_broadcast(&counter_is_even);
        }
        pthread_mutex_unlock(&mutex);
        usleep(50000); // Simulate work
    }
    return NULL;
}

void* decrementer_thread(void* arg) {
    for (int i = 0; i < ITERATIONS; ++i) {
        pthread_mutex_lock(&mutex);
        waiting_decrementers++; 

        while (counter == 0) {
            printf("Decrementer: Waiting, counter is %d\n", counter);
            // Signal incrementers that we are waiting.
            pthread_cond_signal(&incrementers_block); 
            pthread_cond_wait(&can_decrement, &mutex);
        }
        waiting_decrementers--; 

        counter--;
        printf("Decrementer: Counter is now %d\n", counter);

        // Signal monitors if counter became even (or odd, which means they might need to wait again)
        if (counter % 2 == 0) {
            pthread_cond_broadcast(&counter_is_even);
        }
        // If decrementer allowed an incrementer to run, signal it.
        if (waiting_decrementers == 0) { 
            pthread_cond_signal(&incrementers_block);
        }
        pthread_mutex_unlock(&mutex);
        usleep(70000); // Simulate work
    }
    return NULL;
}

void* monitor_thread(void* arg) {
    for (int i = 0; i < (NUM_INCREMENTERS + NUM_DECREMENTERS) * ITERATIONS / 2 + 1; ++i) { // Run for a bit longer
        pthread_mutex_lock(&mutex);
        while (counter % 2 != 0) {
            printf("Monitor: Waiting, counter is %d (odd)\n", counter);
            pthread_cond_wait(&counter_is_even, &mutex);
        }
        printf("Monitor: Current counter is %d (even)\n", counter);
        pthread_mutex_unlock(&mutex);
        usleep(100000); // Simulate work
    }
    return NULL;
}

int main() {
    pthread_t incrementers[NUM_INCREMENTERS];
    pthread_t decrementers[NUM_DECREMENTERS];
    pthread_t monitors[NUM_MONITORS];

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&can_decrement, NULL);
    pthread_cond_init(&counter_is_even, NULL);
    pthread_cond_init(&incrementers_block, NULL);

    for (int i = 0; i < NUM_INCREMENTERS; ++i) {
        pthread_create(&incrementers[i], NULL, incrementer_thread, NULL);
    }
    for (int i = 0; i < NUM_DECREMENTERS; ++i) {
        pthread_create(&decrementers[i], NULL, decrementer_thread, NULL);
    }
    for (int i = 0; i < NUM_MONITORS; ++i) {
        pthread_create(&monitors[i], NULL, monitor_thread, NULL);
    }

    for (int i = 0; i < NUM_INCREMENTERS; ++i) {
        pthread_join(incrementers[i], NULL);
    }
    for (int i = 0; i < NUM_DECREMENTERS; ++i) {
        pthread_join(decrementers[i], NULL);
    }
    pthread_join(monitors[0], NULL); // Join monitors[0] assuming only one monitor

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&can_decrement);
    pthread_cond_destroy(&counter_is_even);
    pthread_cond_destroy(&incrementers_block);

    printf("Final counter: %d\n", counter);
    return 0;
}

