#include <stdio.h>
#include <pthread.h>
#include <unistd.h>
#include <stdbool.h>

#define T 3 // Number of threads
#define N 2 // Number of iterations per thread

pthread_mutex_t mutex_phaseA;
pthread_cond_t cond_phaseA_done;
int phaseA_counter = 0;

pthread_mutex_t mutex_phaseB;

int global_work_counter = 0;

void* thread_func(void* arg) {
    long thread_id = (long)arg;

    for (int i = 0; i < N; ++i) {
        printf("Thread %ld: Iteration %d, starting Phase A\n", thread_id, i);
        usleep(1000 * (thread_id + 1)); // Simulate work

        pthread_mutex_lock(&mutex_phaseA);
        phaseA_counter++;
        printf("Thread %ld: Iteration %d, finished Phase A. phaseA_counter = %d\n", thread_id, i, phaseA_counter);

        if (phaseA_counter < T) {
            pthread_cond_wait(&cond_phaseA_done, &mutex_phaseA);
        } else {
            // Last thread to finish Phase A, reset counter and broadcast
            printf("Thread %ld: Iteration %d, ALL threads finished Phase A. Broadcasting!\n", thread_id, i);
            phaseA_counter = 0;
            pthread_cond_broadcast(&cond_phaseA_done);
        }
        pthread_mutex_unlock(&mutex_phaseA);

        // Phase B critical section
        pthread_mutex_lock(&mutex_phaseB);
        printf("Thread %ld: Iteration %d, entering Phase B critical section. global_work_counter = %d\n", thread_id, i, global_work_counter);
        global_work_counter++;
        usleep(500 * (T - thread_id)); // Simulate work
        printf("Thread %ld: Iteration %d, exiting Phase B critical section. global_work_counter = %d\n", thread_id, i, global_work_counter);
        pthread_mutex_unlock(&mutex_phaseB);
    }
    return NULL;
}

int main() {
    pthread_t threads[T];

    pthread_mutex_init(&mutex_phaseA, NULL);
    pthread_cond_init(&cond_phaseA_done, NULL);
    pthread_mutex_init(&mutex_phaseB, NULL);

    for (long i = 0; i < T; ++i) {
        pthread_create(&threads[i], NULL, thread_func, (void*)i);
    }

    for (int i = 0; i < T; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final global_work_counter = %d\n", global_work_counter);

    pthread_mutex_destroy(&mutex_phaseA);
    pthread_cond_destroy(&cond_phaseA_done);
    pthread_mutex_destroy(&mutex_phaseB);

    return 0;
}

