#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

#define N_THREADS 3 
#define K_ITERATIONS 2 

int global_counter = 0; 

// Barrier synchronization
pthread_mutex_t barrier_mutex;
pthread_cond_t barrier_cond;
int threads_at_barrier = 0;

// Turn-based synchronization
sem_t turn_semaphores[N_THREADS]; // One semaphore per thread

void* worker_thread(void* arg) {
    long thread_id = (long)arg;

    // Phase 1: Local Setup
    printf("Thread %ld: Starting setup...\n", thread_id);
    // Simulate setup time if needed
    printf("Thread %ld: Setup complete.\n", thread_id);

    // Phase 2: Barrier synchronization - wait for all threads to complete setup
    pthread_mutex_lock(&barrier_mutex);
    threads_at_barrier++;
    if (threads_at_barrier == N_THREADS) {
        printf("All threads reached barrier. Signaling...\n");
        pthread_cond_broadcast(&barrier_cond); // Signal all waiting threads
    } else {
        while (threads_at_barrier < N_THREADS) {
            pthread_cond_wait(&barrier_cond, &barrier_mutex); // Wait for signal
        }
    }
    pthread_mutex_unlock(&barrier_mutex);
    printf("Thread %ld: Passed barrier.\n", thread_id);

    // Phase 3: Coordinated Work - ordered increment of global_counter
    for (int i = 0; i < K_ITERATIONS; ++i) {
        sem_wait(&turn_semaphores[thread_id]); // Wait for my turn

        // Critical section
        global_counter++;
        printf("Thread %ld: Incrementing global_counter to %d (iteration %d)\n", thread_id, global_counter, i);

        sem_post(&turn_semaphores[(thread_id + 1) % N_THREADS]); // Signal next thread
    }

    printf("Thread %ld: Finished all work.\n", thread_id);
    return NULL;
}

int main() {
    pthread_t threads[N_THREADS];

    // Initialize synchronization primitives
    pthread_mutex_init(&barrier_mutex, NULL);
pthread_cond_init(&barrier_cond, NULL);

    for (int i = 0; i < N_THREADS; ++i) {
        sem_init(&turn_semaphores[i], 0, 0); // All initially 0
    }
    sem_post(&turn_semaphores[0]); // Grant turn to thread 0 to start

    // Create threads
    for (long i = 0; i < N_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, (void*)i) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    // Join threads
    for (int i = 0; i < N_THREADS; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return 1;
        }
    }

    printf("Main: All threads finished. Final global_counter = %d\n", global_counter);

    // Destroy synchronization primitives
    pthread_mutex_destroy(&barrier_mutex);
pthread_cond_destroy(&barrier_cond);
    for (int i = 0; i < N_THREADS; ++i) {
        sem_destroy(&turn_semaphores[i]);
    }

    return 0;
}

