    }
    return NULL;
}

int main() {
    pthread_t tid[2]; // נניח שני תהליכונים

    // יצירת התהליכונים
    pthread_create(&tid[0], NULL, increment_thread, NULL);
    pthread_create(&tid[1], NULL, increment_thread, NULL);

    // המתנה לסיום התהליכונים
    pthread_join(tid[0], NULL);
    pthread_join(tid[1], NULL);

    printf("Final counter value: %d\n", shared_counter);

