#include <stdio.h>
#include <pthread.h>

#define NUM_THREADS 5
#define INCREMENTS_PER_THREAD 100000

long long global_counter = 0;

void *thread_function(void *arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; i++) {
        global_counter++;
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Final counter value: %lld\n", global_counter);
    printf("Expected value: %lld\n", (long long)NUM_THREADS * INCREMENTS_PER_THREAD);

    return 0;
}

solution.explanation:
הבעיה בקוד המקורי היא תנאי מירוץ (race condition). מספר חוטים ניגשים ומשנים את המשתנה המשותף `global_counter` בו זמנית. הפעולה `global_counter++` אינה אטומית; היא מורכבת מקריאת הערך הנוכחי, הגדלתו באחד, וכתיבת הערך החדש בחזרה. אם שני חוטים או יותר מנסים לבצע פעולה זו במקביל, ייתכן שחוט אחד יקרא את הערך, חוט שני יקרא את אותו ערך לפני שהחוט הראשון הספיק לכתוב את הערך המוגדל, ושניהם יגדילו את אותו ערך ויכתבו אותו בחזרה, מה שיוביל לאובדן עדכונים ולתוצאה סופית שגויה (נמוכה מהצפוי).

כדי לפתור את תנאי המירוץ, נשתמש במוטקס (mutex) כדי להבטיח שרק חוט אחד יוכל לגשת לקטע הקריטי (העדכון של `global_counter`) בכל רגע נתון. המוטקס יגן על המשתנה המשותף. לפני עדכון המונה, כל חוט ינעל את המוטקס באמצעות `pthread_mutex_lock`. לאחר העדכון, החוט ישחרר את המוטקס באמצעות `pthread_mutex_unlock`. בנוסף, יש לאתחל את המוטקס לפני השימוש ולשחרר את המשאבים שלו בסיום.

הקוד המתוקן:
```c
#include <stdio.h>
#include <pthread.h>

#define NUM_THREADS 5
#define INCREMENTS_PER_THREAD 100000

long long global_counter = 0;
pthread_mutex_t counter_mutex; // הצהרה על מוטקס

void *thread_function(void *arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; i++) {
        pthread_mutex_lock(&counter_mutex); // נעילת המוטקס
        global_counter++;
        pthread_mutex_unlock(&counter_mutex); // שחרור המוטקס
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    pthread_mutex_init(&counter_mutex, NULL); // אתחול המוטקס

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Final counter value: %lld\n", global_counter);
    printf("Expected value: %lld\n", (long long)NUM_THREADS * INCREMENTS_PER_THREAD);

    pthread_mutex_destroy(&counter_mutex); // שחרור משאבי המוטקס

    return 0;
}
```

מטרתו העיקרית של mutex (קיצור של Mutual Exclusion) היא להבטיח שרק תהליך או תהליכון אחד יגש לקטע קוד קריטי (critical section) או למשאב משותף בזמן נתון. זה מונע תנאי מירוץ (race conditions) ומוודא עקביות נתונים בסביבה מקבילית. כאשר תהליכון רוצה לגשת למשאב מוגן, הוא מנסה 'לנעול' את ה-mutex (באמצעות `mtx.lock()`). אם ה-mutex פנוי, הוא ננעל והתהליכון ממשיך. אם ה-mutex כבר נעול על ידי תהליכון אחר, התהליכון המבקש ממתין עד שה-mutex ישוחרר. לאחר סיום השימוש במשאב, התהליכון 'משחרר' את ה-mutex (באמצעות `mtx.unlock()`).

דוגמת קוד המדגימה שימוש ב-mutex להגנה על משתנה גלובלי משותף:
```cpp
#include <iostream>
#include <thread>
#include <mutex>

// משתנה גלובלי משותף
int shared_counter = 0;

// Mutex להגנה על shared_counter
std::mutex mtx;

void increment_counter() {
    for (int i = 0; i < 100000; ++i) {
        mtx.lock(); // נעל את ה-mutex
        shared_counter++; // קטע קריטי
        mtx.unlock(); // שחרר את ה-mutex
    }
}

int main() {
    // צור מספר תהליכונים
    std::thread t1(increment_counter);
    std::thread t2(increment_counter);

    // המתן לסיום התהליכונים
    t1.join();
    t2.join();

    // הדפס את הערך הסופי
    std::cout << "Final counter value: " << shared_counter << std::endl;

    return 0;
}
```
בדוגמה זו, שני תהליכונים `t1` ו-`t2` מנסים להגדיל משתנה גלובלי `shared_counter` במקביל. ללא ה-mutex, קיימת סבירות גבוהה לתנאי מירוץ ולערך סופי שגוי של `shared_counter`. השימוש ב-`mtx.lock()` ו-`mtx.unlock()` מבטיח שרק תהליכון אחד יגדיל את המונה בכל רגע נתון, ובכך מונע תנאי מירוץ ומבטיח שהערך הסופי יהיה נכון (200,000 במקרה זה).

Mutex (קיצור של Mutual Exclusion) הוא מנגנון סנכרון המשמש במערכות מרובות חוטים (multi-threaded) כדי להבטיח שרק חוט אחד יוכל לגשת לקטע קוד קריטי או למשאב משותף (כמו משתנה גלובלי, קובץ, או מבנה נתונים) בכל רגע נתון. זה מונע 'תנאי מירוץ' (race conditions) שבהם סדר הגישה הלא מבוקר של חוטים מרובים למשאב משותף יכול להוביל לתוצאות שגויות או בלתי צפויות. Mutex פועל על ידי מתן 'נעילה' (lock) לחוט המבקש לגשת למשאב. אם המשאב נעול, חוטים אחרים המנסים לגשת אליו ימתינו עד שהחוט הנוכחי ישחרר את הנעילה (unlock).

דוגמת קוד ב-C/C++ הממחישה שימוש ב-Mutex להגנה על מונה משותף:

```c
#include <iostream>
#include <pthread.h>
#include <vector>

// משאב משותף
int shared_counter = 0;

// Mutex להגנה על המונה המשותף
pthread_mutex_t counter_mutex;

// פונקציית החוט
void* increment_counter(void* arg) {
    for (int i = 0; i < 100000; ++i) {
        // נעל את המוטקס לפני הגישה לקטע הקריטי
        pthread_mutex_lock(&counter_mutex);
        shared_counter++; // קטע קריטי
        // שחרר את המוטקס לאחר סיום הגישה לקטע הקריטי
        pthread_mutex_unlock(&counter_mutex);
    }
    return NULL;
}

int main() {
    // אתחול המוטקס
    pthread_mutex_init(&counter_mutex, NULL);

    const int NUM_THREADS = 5;
    std::vector<pthread_t> threads(NUM_THREADS);

    // יצירת והפעלת החוטים
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, increment_counter, NULL);
    }

    // המתנה לסיום כל החוטים
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // השמדת המוטקס
    pthread_mutex_destroy(&counter_mutex);

    // הדפסת הערך הסופי של המונה המשותף
    std::cout << "Final shared counter value: " << shared_counter << std::endl;
    // הערך הצפוי הוא 5 * 100000 = 500000

    return 0;
}
```
בדוגמה זו, `pthread_mutex_lock` מבטיח שרק חוט אחד יכול להיכנס לקטע שבו `shared_counter` מוגדל. חוטים אחרים שינסו לקרוא ל-`pthread_mutex_lock` כאשר המוטקס כבר נעול, ימתינו עד שהמוטקס ישוחרר על ידי `pthread_mutex_unlock`.

Mutex (מנעול הדדי) הוא אובייקט סנכרון בסיסי המשמש להבטחת בלעדיות הדדית (mutual exclusion) בגישה למשאבים משותפים (כמו משתנים גלובליים, מבני נתונים, קבצים ועוד) בסביבת ריבוי תהליכונים (multi-threading).
מטרתו העיקרית היא למנוע תנאי מירוץ (Race Conditions), מצב שבו מספר תהליכונים ניגשים למשאב משותף בו-זמנית, ולפחות אחד מהם מבצע שינוי, מה שעלול להוביל לתוצאות בלתי צפויות ולא עקביות.
Mutex מבטיח שרק תהליכון אחד יכול "לנעול" (lock) את המשאב, לגשת אליו ולבצע עליו פעולות, ולאחר מכן "לשחרר" (unlock) אותו. כל תהליכון אחר שינסה לנעול את ה-Mutex כשהוא כבר נעול ימתין עד שהתהליכון הנוכחי ישחרר אותו.

דוגמה לקטע קוד ב-C/C++ המשתמש ב-Mutex להגנה על מונה גלובלי:
```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

#define NUM_THREADS 5
#define ITERATIONS_PER_THREAD 100000

int shared_counter = 0;
pthread_mutex_t counter_mutex;

// פונקציית התהליכון המגדילה את המונה המשותף
void* increment_counter(void* arg) {
    for (int i = 0; i < ITERATIONS_PER_THREAD; ++i) {
        pthread_mutex_lock(&counter_mutex); // נעל את ה-Mutex לפני גישה למשאב המשותף
        shared_counter++; // אזור קריטי: גישה למשתנה משותף
        pthread_mutex_unlock(&counter_mutex); // שחרר את ה-Mutex לאחר סיום הגישה
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    // אתחול ה-Mutex
    if (pthread_mutex_init(&counter_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        return 1;
    }

    // יצירת תהליכונים
    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, increment_counter, NULL) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            return 1;
        }
    }

    // המתנה לסיום כל התהליכונים
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // השמדת ה-Mutex (שחרור משאבי מערכת)
    pthread_mutex_destroy(&counter_mutex);

    printf("Final shared_counter value: %d\n", shared_counter);
    printf("Expected value: %d\n", NUM_THREADS * ITERATIONS_PER_THREAD);

    return 0;
}
```

