#include <iostream>
#include <thread>
#include <mutex>
#include <chrono>

std::mutex mutexA;
std::mutex mutexB;

int shared_data_A = 0;
int shared_data_B = 0;

void thread_func1() {
    std::cout << "Thread 1: Trying to lock mutexA" << std::endl;
    mutexA.lock();
    std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate work
    std::cout << "Thread 1: Locked mutexA, trying to lock mutexB" << std::endl;
    mutexB.lock();

    // Critical section
    shared_data_A++;
    shared_data_B++;
    std::cout << "Thread 1: Acquired both locks. Data A: " << shared_data_A << ", Data B: " << shared_data_B << std::endl;

    mutexB.unlock();
    mutexA.unlock();
    std::cout << "Thread 1: Released both locks" << std::endl;
}

void thread_func2() {
    std::cout << "Thread 2: Trying to lock mutexB" << std::endl;
    mutexB.lock();
    std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate work
    std::cout << "Thread 2: Locked mutexB, trying to lock mutexA" << std::endl;
    mutexA.lock();

    // Critical section
    shared_data_A++;
    shared_data_B++;
    std::cout << "Thread 2: Acquired both locks. Data A: " << shared_data_A << ", Data B: " << shared_data_B << std::endl;

    mutexA.unlock();
    mutexB.unlock();
    std::cout << "Thread 2: Released both locks" << std::endl;
}

int main() {
    std::thread t1(thread_func1);
    std::thread t2(thread_func2);

    t1.join();
    t2.join();

    std::cout << "Final Data A: " << shared_data_A << ", Final Data B: " << shared_data_B << std::endl;
    return 0;
}

