#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>

#define MAX_TICKETS 1024 // Maximum number of unique tickets that can be simultaneously outstanding

typedef struct fair_mutex {
    atomic_uint next_ticket; // Next available ticket number
    atomic_uint now_serving; // Ticket number of the thread currently holding the lock
    sem_t wait_semaphores[MAX_TICKETS]; // Each thread waits on its specific semaphore
    sem_t state_guard; // Binary semaphore to protect access to next_ticket, now_serving, and sem_post operations.
} fair_mutex_t;

void fair_mutex_init(fair_mutex_t *mutex) {
    atomic_init(&mutex->next_ticket, 0);
    atomic_init(&mutex->now_serving, 0);
    sem_init(&mutex->state_guard, 0, 1); // Initialize state_guard as a binary semaphore (unlocked)
    for (int i = 0; i < MAX_TICKETS; ++i) {
        sem_init(&mutex->wait_semaphores[i], 0, 0); // All waiting semaphores start at 0 (locked)
    }
}

void fair_mutex_destroy(fair_mutex_t *mutex) {
    sem_destroy(&mutex->state_guard);
    for (int i = 0; i < MAX_TICKETS; ++i) {
        sem_destroy(&mutex->wait_semaphores[i]);
    }
}

void fair_mutex_lock(fair_mutex_t *mutex) {
    sem_wait(&mutex->state_guard); // Acquire guard to get a ticket and protect state updates
    unsigned int my_ticket = atomic_fetch_add(&mutex->next_ticket, 1); // Atomically get next ticket
    sem_post(&mutex->state_guard); // Release entry gate

    // Check if it's my turn immediately
    if (my_ticket == atomic_load(&mutex->now_serving)) {
        // It's my turn, proceed without waiting on a semaphore
        return;
    } else {
        // Not my turn, wait on my specific semaphore
        sem_wait(&mutex->wait_semaphores[my_ticket % MAX_TICKETS]);
    }
}

void fair_mutex_unlock(fair_mutex_t *mutex) {
    sem_wait(&mutex->state_guard); // Acquire guard to update now_serving and potentially post to next waiter
    unsigned int current_ticket = atomic_load(&mutex->now_serving); // Get current serving ticket
    atomic_fetch_add(&mutex->now_serving, 1); // Increment now_serving for the next thread

    unsigned int next_waiter_ticket = current_ticket + 1;

    // If there's a thread waiting for the next ticket, unblock it
    // This check ensures we only post if a thread has already acquired that ticket
    if (next_waiter_ticket < atomic_load(&mutex->next_ticket)) {
        sem_post(&mutex->wait_semaphores[next_waiter_ticket % MAX_TICKETS]);
    }
    sem_post(&mutex->state_guard); // Release guard
}

