    // Add necessary synchronization primitives here
} ResourceManager;

void init_resource_manager(ResourceManager *rm, int n_resources);
void destroy_resource_manager(ResourceManager *rm);
void acquire_two_resources(ResourceManager *rm, int i, int j);
void release_two_resources(ResourceManager *rm, int i, int j);
```

solution.explanation:
פתרון זה משתמש בשני מנגנוני סנכרון עיקריים כדי לעמוד בדרישות:

1.  **מניעת קיפאון (Deadlock Prevention):** כדי למנוע קיפאון, אנו נוקטים בגישה של רכישת משאבים בסדר קנוני (קבוע). כאשר חוט מבקש לרכוש את משאב `i` ומשאב `j`, הוא תמיד ירכוש קודם את המשאב בעל האינדקס הנמוך יותר, ולאחר מכן את המשאב בעל האינדקס הגבוה יותר. לדוגמה, אם חוט מבקש (3, 7), הוא ירכוש קודם את `resource_locks[3]` ולאחר מכן את `resource_locks[7]`. אם חוט אחר מבקש (7, 3), הוא גם ירכוש קודם את `resource_locks[3]` ואז את `resource_locks[7]`. גישה זו מבטיחה שמעגל המתנה לעולם לא ייווצר, ובכך מונעת קיפאון.

2.  **הוגנות (Fairness):** כדי להבטיח הוגנות ולמנוע הרעבה, אנו משתמשים ב-`request_serializer_mutex` גלובלי. כל חוט המבקש לרכוש זוג משאבים חייב קודם לרכוש את `request_serializer_mutex`. מנעול זה מבטיח שרק חוט אחד בכל רגע נתון יוכל לנסות לרכוש את זוג המשאבים שלו. לאחר שהחוט רכש את `request_serializer_mutex`, הוא ממשיך לרכוש את שני המשאבים הספציפיים שלו בסדר הקנוני שתואר לעיל. רק לאחר ששני המשאבים נרכשו בהצלחה, `request_serializer_mutex` משוחרר. מנגנון זה יוצר תור FIFO (First-In, First-Out) עבור כל הבקשות לרכישת זוגות משאבים, ובכך מבטיח שאף חוט לא יורעב – כל בקשה תקבל את תורה ותטופל בסופו של דבר.

3.  **יעילות:** הפתרון ממזער המתנה מיותרת במובן זה שאחרי שחוט רוכש את `request_serializer_mutex`, הוא ירכוש את המשאבים הנדרשים שלו מיד כשהם פנויים. עם זאת, יש לציין שהשימוש ב-`request_serializer_mutex` גלובלי מפחית את המקביליות האפשרית במערכת, מכיוון שכל בקשות הרכישה נסגרות לסדרה (מועברות בתור אחת אחרי השנייה). לדוגמה, אם חוט אחד מבקש את (R0, R1) וחוט אחר מבקש את (R2, R3) – משאבים שאינם חופפים – הם עדיין יצטרכו לחכות זה לזה ב-`request_serializer_mutex`. זוהי פשרה נפוצה כאשר דורשים הוגנות מחמירה עם מנעולים בלבד, ללא שימוש במשתני תנאי (condition variables) המאפשרים המתנה חכמה יותר.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int N; // Number of resources
    pthread_mutex_t *resource_locks; // Array of mutexes, one per resource
    pthread_mutex_t request_serializer_mutex; // Global mutex to ensure fairness for acquisition attempts
} ResourceManager;

// Initialization function
void init_resource_manager(ResourceManager *rm, int n_resources) {
    rm->N = n_resources;
    rm->resource_locks = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t) * n_resources);
    if (rm->resource_locks == NULL) {
        perror("Failed to allocate resource_locks");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < n_resources; ++i) {
        if (pthread_mutex_init(&rm->resource_locks[i], NULL) != 0) {
            perror("Failed to initialize resource mutex");
            exit(EXIT_FAILURE);
        }
    }
    if (pthread_mutex_init(&rm->request_serializer_mutex, NULL) != 0) {
        perror("Failed to initialize request serializer mutex");
        exit(EXIT_FAILURE);
    }
}

// Destruction function
void destroy_resource_manager(ResourceManager *rm) {
    for (int i = 0; i < rm->N; ++i) {
        pthread_mutex_destroy(&rm->resource_locks[i]);
    }
    free(rm->resource_locks);
    pthread_mutex_destroy(&rm->request_serializer_mutex);
}

// Acquire two resources
void acquire_two_resources(ResourceManager *rm, int i, int j) {
    // Ensure valid indices
    if (i < 0 || i >= rm->N || j < 0 || j >= rm->N || i == j) {
        fprintf(stderr, "Invalid resource indices: %d, %d\n", i, j);
        return;
    }

    // Use the request_serializer_mutex to ensure fairness for acquisition attempts
    // This mutex is held for the entire duration of acquiring both resource locks.
    // This serializes all attempts to acquire a pair of resources.
    pthread_mutex_lock(&rm->request_serializer_mutex);

    // Acquire resources in canonical order to prevent deadlock
    int idx1 = (i < j) ? i : j;
    int idx2 = (i < j) ? j : i;

    pthread_mutex_lock(&rm->resource_locks[idx1]);
    pthread_mutex_lock(&rm->resource_locks[idx2]);

    // Release the request_serializer_mutex ONLY AFTER both resources are acquired.
    // This makes the entire acquisition process (for a pair) atomic from the perspective
    // of other threads trying to acquire any resources.
    pthread_mutex_unlock(&rm->request_serializer_mutex);
}

// Release two resources
void release_two_resources(ResourceManager *rm, int i, int j) {
    // Ensure valid indices
    if (i < 0 || i >= rm->N || j < 0 || j >= rm->N || i == j) {
        fprintf(stderr, "Invalid resource indices: %d, %d\n", i, j);
        return;
    }

    // Release resources in reverse canonical order (or any order, as release order doesn't cause deadlock)
    // For consistency, releasing in reverse order of acquisition is good practice.
    int idx1 = (i < j) ? i : j;
    int idx2 = (i < j) ? j : i;

    pthread_mutex_unlock(&rm->resource_locks[idx2]);
    pthread_mutex_unlock(&rm->resource_locks[idx1]);
}
```

המימוש של `PermitMutex` ידרוש מבנה נתונים שיכיל מונה של הרשאות זמינות (`available_permits`), מנעול (`pthread_mutex_t`) להגנה על מונה זה, ומשתנה תנאי (`pthread_cond_t`) לתהליכים הממתינים להרשאה. הנה המימוש:

```c
#include <pthread.h>
#include <stdlib.h> // For malloc, free (though not strictly needed for this snippet)

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int available_permits;
    int max_permits; // Store N for completeness, though not strictly used in logic
} PermitMutex;

// Initialize the PermitMutex with a maximum number of permits
void init_permit_mutex(PermitMutex *pm, int N) {
    pthread_mutex_init(&pm->mutex, NULL);
    pthread_cond_init(&pm->cond, NULL);
    pm->available_permits = N;
    pm->max_permits = N; 
}

// Destroy the PermitMutex, releasing associated resources
void destroy_permit_mutex(PermitMutex *pm) {
    pthread_mutex_destroy(&pm->mutex);
    pthread_cond_destroy(&pm->cond);
}

// Acquire a permit (enter critical section if available)
void acquire_permit(PermitMutex *pm) {
    pthread_mutex_lock(&pm->mutex);
    // Loop is crucial to handle spurious wakeups and re-check condition
    while (pm->available_permits == 0) {
        pthread_cond_wait(&pm->cond, &pm->mutex);
    }
    pm->available_permits--;
    pthread_mutex_unlock(&pm->mutex);
}

// Release a permit (exit critical section)
void release_permit(PermitMutex *pm) {
    pthread_mutex_lock(&pm->mutex);
    pm->available_permits++;
    // Signal one waiting thread. For this specific problem, signal is generally sufficient
    // as only one thread can acquire a permit at a time when one becomes available.
    // In other scenarios, pthread_cond_broadcast might be considered if multiple
    // threads could simultaneously proceed.
    pthread_cond_signal(&pm->cond);
    pthread_mutex_unlock(&pm->mutex);
}
```

**הסבר:**

1.  **מבנה `PermitMutex`**: המבנה מכיל `pthread_mutex_t` להבטחת הדדיות (Mutual Exclusion) בעת גישה למשתנים המשותפים, `pthread_cond_t` לתזמון והמתנה של תהליכים, ו-`available_permits` שהוא מונה של ההרשאות הפנויות כרגע.

2.  **`init_permit_mutex(PermitMutex *pm, int N)`**: פונקציה זו מאתחלת את המוטקס, את משתנה התנאי, ומגדירה את מספר ההרשאות הזמינות הראשוני ל-N.

3.  **`acquire_permit(PermitMutex *pm)`**: 
    *   התהליך נועל את המוטקס (`pthread_mutex_lock`) כדי להגן על הגישה ל-`available_permits` ועל הקריאה ל-`pthread_cond_wait`.
    *   הוא נכנס ללולאת `while (pm->available_permits == 0)`. לולאה זו היא קריטית ממספר סיבות: ראשית, היא מבטיחה שתהליך ימתין *רק* כאשר אין הרשאות זמינות. שנית, היא מטפלת ב"התעוררויות שווא" (spurious wakeups) שבהן `pthread_cond_wait` עשוי לחזור למרות שהתנאי עדיין לא מתקיים. הלולאה מבטיחה שהתנאי ייבדק שוב לאחר כל התעוררות.
    *   אם יש הרשאה זמינה (כלומר, `available_permits > 0`), התהליך מקטין את המונה ב-1 וממשיך בדרכו, לאחר ששחרר את המוטקס (`pthread_mutex_unlock`).

4.  **`release_permit(PermitMutex *pm)`**: 
    *   התהליך נועל את המוטקס.
    *   הוא מגדיל את `available_permits` ב-1, משמע הרשאה אחת התפנתה.
    *   הוא קורא ל-`pthread_cond_signal(&pm->cond)` כדי להעיר תהליך אחד הממתין על משתנה התנאי (אם יש כזה). התהליך שהתעורר יוכל כעת לבדוק את התנאי בלולאת ה-`while` שלו ב-`acquire_permit`.
    *   לבסוף, התהליך משחרר את המוטקס. 

**נכונות ודיון:**
*   **מניעה הדדית מורחבת**: המוטקס מבטיח שהגישה למונה `available_permits` היא הדדית, ומונעת מצבי מירוץ (race conditions) בשינוי ערכו. המונה עצמו מבטיח שכל היותר N תהליכים יחזיקו הרשאה בו-זמנית.
*   **חופש מקיפאון (Deadlock-free)**: המימוש אינו מכיל תנאים לקיפאון. תהליכים ממתינים רק אם אין הרשאות, ומשתחררים כאשר הרשאה מתפנה. אין תלות מעגלית במשאבים.
*   **הוגנות (Fairness)**: המימוש עם `pthread_cond_signal` לא מבטיח הוגנות חזקה (לדוגמה, בסדר FIFO) בין התהליכים הממתינים. מערכת ההפעלה קובעת איזה תהליך ממתין יתעורר. עבור הוגנות חזקה יותר, ייתכן שיהיה צורך במנגנוני תור מורכבים יותר או שימוש ב-`pthread_cond_broadcast` יחד עם מונה תהליכים ממתינים, אם כי זה פחות יעיל ויכול להוביל ל"עדר מתעורר" (thundering herd) אם רק אחד יכול להמשיך.

