#include <pthread.h>
#include <stdio.h>
#include <stdlib.h> // For exit

int counter = 0;
pthread_mutex_t my_mutex;

void* increment_thread(void* arg) {
    for (int i = 0; i < 100000; ++i) {
        // Critical section: incrementing counter
        counter++;
    }
    return NULL;
}

int main() {
    pthread_t tids[2];

    pthread_mutex_init(&my_mutex, NULL); // Initialize mutex

    // Create two threads
    pthread_create(&tids[0], NULL, increment_thread, NULL);
    pthread_create(&tids[1], NULL, increment_thread, NULL);

    // Wait for threads to finish
    pthread_join(tids[0], NULL);
    pthread_join(tids[1], NULL);

    printf("Final counter value: %d\n", counter);

    pthread_mutex_destroy(&my_mutex); // Destroy mutex

    return 0;
}

solution.explanation:
הבעיה העיקרית בקוד היא תנאי מרוץ (race condition). שני החוטים מנסים לגשת ולשנות את המונה הגלובלי `counter` במקביל ללא כל מנגנון סנכרון. הפעולה `counter++` אינה אטומית; היא מורכבת משלושה שלבים: קריאת ערך המונה, הגדלתו ב-1, וכתיבת הערך החדש בחזרה לזיכרון. כאשר שני חוטים מבצעים פעולה זו במקביל, ייתכן ששניהם יקראו את אותו ערך של `counter` לפני שאחד מהם יספיק לכתוב את הערך המוגדל בחזרה. לדוגמה, אם `counter` הוא 0, חוט א' קורא 0, חוט ב' קורא 0. חוט א' מגדיל ל-1 וכותב 1. חוט ב' מגדיל ל-1 וכותב 1. התוצאה הסופית תהיה 1 במקום 2. כתוצאה מכך, הערך הסופי של `counter` יהיה בדרך כלל נמוך מ-200,000 (הערך הצפוי של 2 חוטים * 100,000 איטרציות) וישתנה בין הרצות שונות.

כדי לתקן את הבעיה, יש להגן על הקטע הקריטי (הגדלת המונה) באמצעות המוטקס `my_mutex`. יש לנעול את המוטקס לפני הגישה למשתנה המשותף ולשחרר אותו לאחר מכן. התיקון לקוד ייראה כך:

```c
void* increment_thread(void* arg) {
    for (int i = 0; i < 100000; ++i) {
        pthread_mutex_lock(&my_mutex);   // נעל את המוטקס לפני הגישה למשתנה המשותף
        counter++;                       // קטע קריטי
        pthread_mutex_unlock(&my_mutex); // שחרר את המוטקס לאחר הגישה
    }
    return NULL;
}
```

