#define NUM_THREADS 5
#define INCREMENTS_PER_THREAD 100000

int counter = 0;

void *increment_counter(void *arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        counter++;
    }
    pthread_exit(NULL);
}

int main() {
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, increment_counter, NULL) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            exit(EXIT_FAILURE);
        }
    }

    printf("Final counter value: %d\n", counter);

    return 0;
}

solution.explanation:
הפלט הצפוי התיאורטי של התוכנית הוא 500000 (כלומר, NUM_THREADS * INCREMENTS_PER_THREAD). אולם, בפועל, הפלט יהיה לרוב נמוך יותר מ-500000 וגם לא יהיה זהה בין ריצות שונות של התוכנית. הסיבה לכך היא תנאי מרוץ (Race Condition).

פעולת `counter++` אינה אטומית. היא מורכבת משלוש פעולות ברמה נמוכה יותר (קריאת ערך המונה לתוך רגיסטר, הגדלת הערך ברגיסטר, וכתיבת הערך המעודכן בחזרה לזיכרון). כאשר מספר תהליכונים מבצעים פעולה זו במקביל ללא סנכרון, ייתכן שתהליכון אחד יקרא את ערך המונה, יגדיל אותו, אך לפני שיספיק לכתוב אותו בחזרה לזיכרון, תהליכון אחר יקרא את אותו ערך ישן של המונה. כתוצאה מכך, אחת מההגדלות (increments) תאבד, והמונה לא יגיע לערכו הסופי הנכון.

כדי לתקן את הקוד ולהבטיח שהמונה יגיע תמיד לערך הנכון, יש להשתמש ב-mutex (מנעול הדדי) כדי להגן על הגישה למשתנה המשותף `counter`. יש לאתחל את ה-mutex לפני יצירת התהליכונים, לנעול אותו לפני הגישה ל-`counter++` ולשחרר אותו מיד לאחר מכן, ולבסוף להרוס את ה-mutex בסיום התוכנית. התיקון ייראה כך:

```c
#include <stdio.h>
#include <pthread.h>
#include <stdlib.h>

#define NUM_THREADS 5
#define INCREMENTS_PER_THREAD 100000

int counter = 0;
pthread_mutex_t mutex; // הצהרה על mutex גלובלי

void *increment_counter(void *arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        pthread_mutex_lock(&mutex);   // נעילת ה-mutex לפני גישה למשתנה המשותף
        counter++;
        pthread_mutex_unlock(&mutex); // שחרור ה-mutex לאחר הגישה
    }
    pthread_exit(NULL);
}

int main() {
    pthread_t threads[NUM_THREADS];
    pthread_mutex_init(&mutex, NULL); // אתחול ה-mutex

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, increment_counter, NULL) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            exit(EXIT_FAILURE);
        }
    }

    printf("Final counter value: %d\n", counter);

    pthread_mutex_destroy(&mutex); // השמדת ה-mutex
    return 0;
}
```

