#define CACHE_SIZE 5

typedef struct CacheEntry {
    int key;
    int value;
    pthread_mutex_t item_mutex; // Protects 'value' and 'key' of this specific entry
    int in_use; // 0 if empty, 1 if in use
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER; // Protects global cache structure (e.g., 'in_use' flags, finding empty slots)

void cache_init() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        cache[i].key = -1;
        cache[i].value = -1;
        pthread_mutex_init(&cache[i].item_mutex, NULL);
        cache[i].in_use = 0;
    }
}

// Function to add or update an item in the cache
void cache_put(int key, int value) {
    pthread_mutex_lock(&cache_mutex); // Lock global cache structure

    int found_idx = -1;
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].in_use && cache[i].key == key) {
            found_idx = i;
            break;
        }
    }

    if (found_idx != -1) {
        // Item exists, update its value.
        pthread_mutex_lock(&cache[found_idx].item_mutex); // Lock item
        cache[found_idx].value = value;
        pthread_mutex_unlock(&cache[found_idx].item_mutex); // Unlock item
        pthread_mutex_unlock(&cache_mutex); // Unlock global cache
        return;
    }

    // Item does not exist, find an empty slot
    int empty_idx = -1;
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (!cache[i].in_use) {
            empty_idx = i;
            break;
        }
    }

    if (empty_idx != -1) {
        // Found an empty slot
        pthread_mutex_lock(&cache[empty_idx].item_mutex); // Lock new item slot
        cache[empty_idx].key = key;
        cache[empty_idx].value = value;
        cache[empty_idx].in_use = 1;
        pthread_mutex_unlock(&cache[empty_idx].item_mutex); // Unlock new item slot
        pthread_mutex_unlock(&cache_mutex); // Unlock global cache
        return;
    }

    // Cache is full. For simplicity, we don't handle eviction here.
    // In a real scenario, an eviction policy would be applied.
    pthread_mutex_unlock(&cache_mutex); // Unlock global cache
    printf("Cache is full, cannot add key %d\n", key);
}

// Function to clear all items in the cache
void cache_clear_and_reset() {
    printf("Clearing cache...\n");
    for (int i = 0; i < CACHE_SIZE; ++i) {
        pthread_mutex_lock(&cache[i].item_mutex); // Acquire item mutex
        // Simulate some cleanup work for the item
