content.text:
נתונה רשימה מקושרת מוגנת מנעולים, בה כל צומת מכיל מנעול (mutex) משלו (`node_mutex`), ובנוסף קיים מנעול גלובלי (`head_ptr_mutex`) המגן על המצביע לראש הרשימה (`head`). הרשימה מאותחלת על ידי `init_list()`.

להלן מימוש חלקי של פונקציות `add_node` ו-`remove_node`. פונקציית `add_node` מוסיפה צומת חדש לסוף הרשימה ומשתמשת במנגנון "נעילה ידנית" (hand-over-hand locking) באופן סטנדרטי (כלומר, נועלת צומת נוכחי P ואז את הצומת הבא N, ומשחררת את המנעול של P). פונקציית `remove_node` מנסה להסיר צומת בעל ערך נתון.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
    pthread_mutex_t node_mutex; // Mutex protecting this node's data and next pointer
} Node;

Node* head = NULL;
pthread_mutex_t head_ptr_mutex; // Mutex protecting the global 'head' pointer

void init_list() {
    pthread_mutex_init(&head_ptr_mutex, NULL);
    head = NULL;
}

void destroy_list() {
    Node* current = head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        pthread_mutex_destroy(&temp->node_mutex);
        free(temp);
    }
    pthread_mutex_destroy(&head_ptr_mutex);
}

// פונקציה להוספת צומת לסוף הרשימה (מימוש סטנדרטי עם hand-over-hand locking)
void add_node(int data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->node_mutex, NULL);

    pthread_mutex_lock(&head_ptr_mutex);
    if (head == NULL) {
        head = new_node;
        pthread_mutex_unlock(&head_ptr_mutex);
    } else {
        Node* current = head;
        pthread_mutex_lock(&current->node_mutex); // Lock current (P)
        pthread_mutex_unlock(&head_ptr_mutex); // Release head_ptr_mutex

        while (current->next != NULL) {
            Node* next_node = current->next;
            pthread_mutex_lock(&next_node->node_mutex); // Lock next (N)
            pthread_mutex_unlock(&current->node_mutex); // Unlock current (P)
            current = next_node;
        }
        // 'current' is now the last node, holding its mutex (P)
        current->next = new_node; // Modify P->next
        pthread_mutex_unlock(&current->node_mutex); // Unlock P
    }
}

// פונקציה בעייתית להסרת צומת מהרשימה
// פונקציה זו משתמשת בסדר נעילה לא עקבי שעלול להוביל לקיפאון (deadlock).
int remove_node(int value) {
    pthread_mutex_lock(&head_ptr_mutex);
    Node* current = head;
    Node* prev = NULL;

    // טיפול במקרה של הסרת צומת הראש
    if (current != NULL && current->data == value) {
        pthread_mutex_lock(&current->node_mutex); // נועלים את צומת הראש (N)
        head = current->next; // משנים את מצביע ה-head
        pthread_mutex_unlock(&current->node_mutex); // משחררים את N
        pthread_mutex_destroy(&current->node_mutex);
        free(current);
        pthread_mutex_unlock(&head_ptr_mutex);
        return 1; // הצומת הוסר
    }

    // משחררים את מנעול ה-head_ptr_mutex כדי לאפשר פעולות אחרות על ה-head
    // בזמן שאנו עוברים על הרשימה. (לדוגמה, add_node) 
    pthread_mutex_unlock(&head_ptr_mutex);

    // עוברים על הרשימה למצוא את הצומת להסרה
    // שימו לב: בשלב זה, אין מנעולי צומת נעולים במהלך המעבר עד למציאת הצומת.
    current = head;
    while (current != NULL) {
        if (current->data == value) {
            // מצאנו את הצומת (N) שיש להסיר. 'prev' הוא קודמו (P).
            // סדר נעילה לא עקבי שגורם לקיפאון: נועלים את N ואז את P.
            pthread_mutex_lock(&current->node_mutex); // נועלים את N
            if (prev != NULL) {
                pthread_mutex_lock(&prev->node_mutex); // נועלים את P (סדר הפוך!)
                prev->next = current->next; // משנים את P->next
                pthread_mutex_unlock(&prev->node_mutex); // משחררים את P
            }
            // אם prev הוא NULL, המשמעות היא ש-current הוא ה-head, 
            // אך מקרה זה אמור להיות מטופל כבר למעלה.
            pthread_mutex_unlock(&current->node_mutex); // משחררים את N
            pthread_mutex_destroy(&current->node_mutex);
            free(current);
            return 1; // הצומת הוסר
        }
        prev = current;
        current = current->next;
    }

    return 0; // הצומת לא נמצא
}
```

