#include <iostream>
#include <pthread.h>
#include <unistd.h> // For sleep

// Global mutex for lazy initialization of Logger
pthread_mutex_t logger_init_mutex = PTHREAD_MUTEX_INITIALIZER;
// Global mutex for configuration access (used by Logger constructor and update_configuration)
pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;

class Logger {
public:
    Logger() {
        // Simulate expensive initialization requiring config_mutex
        pthread_mutex_lock(&config_mutex);
        std::cout << "Logger constructor: Acquiring config_mutex for expensive initialization..." << std::endl;
        sleep(2); // Simulate long initialization
        std::cout << "Logger constructor: Finished expensive initialization and releasing config_mutex." << std::endl;
        pthread_mutex_unlock(&config_mutex);
    }

    void log(const char* message) {
        std::cout << "Log message: " << message << std::endl;
    }
};

// The singleton instance
Logger* g_logger_instance = NULL;

// Function to get the singleton Logger instance
Logger* get_logger() {
    if (g_logger_instance == NULL) { // First check (no lock)
        pthread_mutex_lock(&logger_init_mutex);
        if (g_logger_instance == NULL) { // Second check (with lock)
            std::cout << "Thread " << pthread_self() << ": Initializing Logger..." << std::endl;
            g_logger_instance = new Logger(); // Calls Logger constructor
            std::cout << "Thread " << pthread_self() << ": Logger initialized." << std::endl;
        }
        pthread_mutex_unlock(&logger_init_mutex);
    }
    return g_logger_instance;
}

// Another function that needs config_mutex then logger_init_mutex
void update_configuration() {
    std::cout << "Thread " << pthread_self() << ": Entering update_configuration()..." << std::endl;
    pthread_mutex_lock(&config_mutex);
    std::cout << "Thread " << pthread_self() << ": Acquired config_mutex in update_configuration()." << std::endl;
    sleep(1); // Simulate some work

    pthread_mutex_lock(&logger_init_mutex); // Potential deadlock here
    std::cout << "Thread " << pthread_self() << ": Acquired logger_init_mutex in update_configuration()." << std::endl;
    // Perform configuration update that might involve checking logger state or similar
    // For simplicity, just simulate work.
    sleep(1);

    pthread_mutex_unlock(&logger_init_mutex);
    std::cout << "Thread " << pthread_self() << ": Released logger_init_mutex in update_configuration()." << std::endl;

    pthread_mutex_unlock(&config_mutex);
    std::cout << "Thread " << pthread_self() << ": Released config_mutex in update_configuration()." << std::endl;
}

// Example thread functions
void* thread_logger_task(void* arg) {
    Logger* logger = get_logger();
    logger->log("Hello from logger thread!");
    return NULL;
}

void* thread_config_task(void* arg) {
    update_configuration();
    return NULL;
}

int main() {
    pthread_t t1, t2;

    std::cout << "Starting threads..." << std::endl;
    pthread_create(&t1, NULL, thread_logger_task, NULL);
    pthread_create(&t2, NULL, thread_config_task, NULL);

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    std::cout << "Threads finished." << std::endl;

    // Clean up
    delete g_logger_instance; // Only if initialized
    pthread_mutex_destroy(&logger_init_mutex);
    pthread_mutex_destroy(&config_mutex);

    return 0;
}

solution.explanation:
### 101.1 זיהוי הבעיה והסבר:
הבעיה היא **קיפאון (Deadlock)**. קיפאון יכול להתרחש כאשר שני חוטים או יותר ממתינים זה לזה למשאב שהשני מחזיק בו, ויוצרים מעגל המתנה.

**רצף אירועים המוביל לקיפאון:**
1.  **חוט t1 (מריץ את `thread_logger_task`):** קורא לפונקציה `get_logger()`. הוא מגלה ש-`g_logger_instance` הוא `NULL`.
2.  **חוט t1:** נועל את `logger_init_mutex`. (כעת t1 מחזיק ב-`logger_init_mutex`).
3.  **חוט t1:** מתחיל את יצירת אובייקט `Logger` על ידי קריאה ל-`new Logger()`.
4.  **חוט t1 (בתוך הקונסטרוקטור של `Logger`):** מנסה לנעול את `config_mutex`. כעת הוא ממתין ל-`config_mutex`.

5.  **חוט t2 (מריץ את `thread_config_task`):** קורא לפונקציה `update_configuration()`.
6.  **חוט t2:** נועל את `config_mutex`. (כעת t2 מחזיק ב-`config_mutex`).
7.  **חוט t2:** מנסה לנעול את `logger_init_mutex`. כעת הוא ממתין ל-`logger_init_mutex`.

**תוצאה:**
*   חוט t1 מחזיק ב-`logger_init_mutex` וממתין ל-`config_mutex`.
*   חוט t2 מחזיק ב-`config_mutex` וממתין ל-`logger_init_mutex`.

שני החוטים חסומים באופן הדדי, ונוצר מצב של קיפאון. אף אחד מהם לא יכול להמשיך, והתוכנית תיתקע.

### 101.2 תיקון הקוד:
הבעיה נובעת מכך שהחוטים מנסים לנעול את המנעולים בסדר שונה: `get_logger` נועל את `logger_init_mutex` ואז מנסה לנעול את `config_mutex` (דרך הקונסטרוקטור), בעוד ש-`update_configuration` נועל את `config_mutex` ואז מנסה לנעול את `logger_init_mutex`. כדי למנוע קיפאון, יש להקפיד על סדר אחיד של נעילת מנעולים בכל מקום בתוכנית.

**פתרון:** נשנה את סדר נעילת המנעולים בפונקציה `update_configuration()` כך שתמיד ינעל קודם את `logger_init_mutex` ולאחר מכן את `config_mutex`. לחלופין, ניתן לשנות את הקונסטרוקטור של `Logger` כך שינעל את `config_mutex` רק *לאחר* ש-`logger_init_mutex` שוחרר, אך זה מסובך יותר ודורש שינוי לוגיקה של Double-Checked Locking. הסדר העדיף הוא לשנות את `update_configuration` כדי להתאים לסדר של `get_logger` (או להיפך), תוך שמירה על סדר עקבי.

**שינויים שבוצעו:**
הקוד של `update_configuration()` שונה כך שסדר נעילת המנעולים יהיה זהה לסדר המרומז ב-`get_logger()` (כלומר, קודם `logger_init_mutex` ואז `config_mutex`).

```c
#include <iostream>
#include <pthread.h>
#include <unistd.h> // For sleep

// Global mutex for lazy initialization of Logger
pthread_mutex_t logger_init_mutex = PTHREAD_MUTEX_INITIALIZER;
// Global mutex for configuration access (used by Logger constructor and update_configuration)
pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;

class Logger {
public:
    Logger() {
        // Simulate expensive initialization requiring config_mutex
        pthread_mutex_lock(&config_mutex); // This is still the internal order for Logger init
        std::cout << "Logger constructor: Acquiring config_mutex for expensive initialization..." << std::endl;
        sleep(2); // Simulate long initialization
        std::cout << "Logger constructor: Finished expensive initialization and releasing config_mutex." << std::endl;
        pthread_mutex_unlock(&config_mutex);
    }

    void log(const char* message) {
        std::cout << "Log message: " << message << std::endl;
    }
};

// The singleton instance
Logger* g_logger_instance = NULL;

// Function to get the singleton Logger instance
Logger* get_logger() {
    if (g_logger_instance == NULL) { // First check (no lock)
        pthread_mutex_lock(&logger_init_mutex);
        if (g_logger_instance == NULL) { // Second check (with lock)
            std::cout << "Thread " << pthread_self() << ": Initializing Logger..." << std::endl;
            g_logger_instance = new Logger(); // Calls Logger constructor
            std::cout << "Thread " << pthread_self() << ": Logger initialized." << std::endl;
        }
        pthread_mutex_unlock(&logger_init_mutex);
    }
    return g_logger_instance;
}

// Another function that needs config_mutex then logger_init_mutex
void update_configuration() {
    std::cout << "Thread " << pthread_self() << ": Entering update_configuration()..." << std::endl;

    // FIX: Changed lock order to prevent deadlock. 
    // Now it always locks logger_init_mutex first, then config_mutex.
    pthread_mutex_lock(&logger_init_mutex);
    std::cout << "Thread " << pthread_self() << ": Acquired logger_init_mutex in update_configuration()." << std::endl;
    sleep(1); // Simulate some work

    pthread_mutex_lock(&config_mutex);
    std::cout << "Thread " << pthread_self() << ": Acquired config_mutex in update_configuration()." << std::endl;
    // Perform configuration update that might involve checking logger state or similar
    // For simplicity, just simulate work.
    sleep(1);

    pthread_mutex_unlock(&config_mutex);
    std::cout << "Thread " << pthread_self() << ": Released config_mutex in update_configuration()." << std::endl;

    pthread_mutex_unlock(&logger_init_mutex);
    std::cout << "Thread " << pthread_self() << ": Released logger_init_mutex in update_configuration()." << std::endl;
}

// Example thread functions
void* thread_logger_task(void* arg) {
    Logger* logger = get_logger();
    logger->log("Hello from logger thread!");
    return NULL;
}

void* thread_config_task(void* arg) {
    update_configuration();
    return NULL;
}

int main() {
    pthread_t t1, t2;

    std::cout << "Starting threads..." << std::endl;
    pthread_create(&t1, NULL, thread_logger_task, NULL);
    pthread_create(&t2, NULL, thread_config_task, NULL);

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    std::cout << "Threads finished." << std::endl;

    // Clean up
    delete g_logger_instance; // Only if initialized
    pthread_mutex_destroy(&logger_init_mutex);
    pthread_mutex_destroy(&config_mutex);

    return 0;
}
```

**הערה:** חשוב לציין שהפתרון הזה (שינוי סדר הנעילה ב-`update_configuration`) עובד מכיוון שהוא מייצר סדר נעילה גלובלי אחיד: תמיד `logger_init_mutex` ואז `config_mutex` (או רק אחד מהם). אם היה צורך אמיתי לנעול את `config_mutex` לפני `logger_init_mutex` ב-`update_configuration` מסיבות לוגיות אחרות, היה צריך לשקול פתרונות מורכבים יותר כמו `trylock` או שימוש ב-`std::call_once` ב-C++11 ומעלה כדי להימנע מנעילת `logger_init_mutex` באופן ישיר ב-`get_logger` לאחר האתחול הראשון.

