```c
#include <pthread.h>
#include <unistd.h> // for sleep

// משאבים משותפים
int resourceA = 100;
int resourceB = 100;

// מוטקסים להגנה על המשאבים
pthread_mutex_t mutexA;
pthread_mutex_t mutexB;

// פונקציה להעברת כמות מ-A ל-B
void transfer_A_to_B(int amount) {
    pthread_mutex_lock(&mutexA);
    sleep(1); // מדמה עבודה או החלפת הקשר
    pthread_mutex_lock(&mutexB);

    resourceA -= amount;
    resourceB += amount;

    pthread_mutex_unlock(&mutexB);
    pthread_mutex_unlock(&mutexA);
}

// פונקציה להעברת כמות מ-B ל-A
void transfer_B_to_A(int amount) {
    pthread_mutex_lock(&mutexB);
    sleep(1); // מדמה עבודה או החלפת הקשר
    pthread_mutex_lock(&mutexA);

    resourceB -= amount;
    resourceA += amount;

    pthread_mutex_unlock(&mutexA);
    pthread_mutex_unlock(&mutexB);
}
```

solution.explanation:
1. הבעיה: קיפאון (Deadlock).
   הבעיה יכולה להתרחש כאשר שני חוטים מנסים לבצע פעולות העברה במקביל, כאשר כל אחד מהם תופס מוטקס אחד וממתין למוטקס השני שנתפס על ידי החוט האחר. לדוגמה:

   *   **חוט 1** קורא ל-`transfer_A_to_B(10)`:
       *   תופס את `mutexA`.
       *   מתבצעת `sleep(1)` (מדמה עבודה או החלפת הקשר).
   *   **חוט 2** קורא ל-`transfer_B_to_A(10)` (במקביל לחוט 1, בזמן שחוט 1 ב-`sleep`):
       *   תופס את `mutexB`.
       *   מתבצעת `sleep(1)` (מדמה עבודה או החלפת הקשר).
   *   **חוט 1** מנסה כעת לתפוס את `mutexB` אך הוא חסום, מכיוון ש-`mutexB` נתפס על ידי חוט 2.
   *   **חוט 2** מנסה כעת לתפוס את `mutexA` אך הוא חסום, מכיוון ש-`mutexA` נתפס על ידי חוט 1.

   בנקודה זו, שני החוטים חסומים באופן הדדי וממתינים זה לזה לשחרר את המוטקס שהם זקוקים לו. אף אחד מהם לא יכול להמשיך, והמערכת נכנסת למצב של קיפאון.

2. תיקון: כדי למנוע קיפאון, יש להקפיד על סדר אחיד של תפיסת מוטקסים בכל הפונקציות שצריכות לתפוס מספר מוטקסים. במקרה זה, נקבע שכל הפונקציות יתפסו תמיד את `mutexA` לפני `mutexB`.

   ```c
// פונקציה להעברת כמות מ-A ל-B (ללא שינוי בסדר תפיסת המוטקסים)
void transfer_A_to_B(int amount) {
    pthread_mutex_lock(&mutexA);
    pthread_mutex_lock(&mutexB); // תמיד תופסים את mutexA לפני mutexB

    resourceA -= amount;
    resourceB += amount;

    pthread_mutex_unlock(&mutexB);
    pthread_mutex_unlock(&mutexA);
}

// פונקציה להעברת כמות מ-B ל-A (תיקון סדר תפיסת המוטקסים)
void transfer_B_to_A(int amount) {
    pthread_mutex_lock(&mutexA); // תופסים קודם את mutexA
    pthread_mutex_lock(&mutexB); // ואז את mutexB

    resourceB -= amount;
    resourceA += amount;

    pthread_mutex_unlock(&mutexB);
    pthread_mutex_unlock(&mutexA);
}
   ```
   הסבר לתיקון: על ידי אכיפת סדר קבוע (למשל, תמיד `mutexA` ואז `mutexB`), אנו מבטיחים שלעולם לא ייווצר מצב שבו חוט אחד מחזיק ב-`mutexA` וממתין ל-`mutexB` בעוד חוט אחר מחזיק ב-`mutexB` וממתין ל-`mutexA`. חוטים תמיד ינסו לתפוס את המוטקסים באותו סדר, וכך אם חוט אחד כבר תפס את `mutexA`, כל חוט אחר שינסה לתפוס את `mutexA` יחסם עד ש-`mutexA` ישוחרר, ובכך נמנע את מעגל ההמתנה ההדדית שגורם לקיפאון.

