sem_t mutex; // Global semaphore variable

void init_sem() {
    sem_init(&mutex, 0, 1); // Initialize mutex to 1 (binary semaphore)
}

void P1_task() {
    sem_wait(&mutex); // Wait for the semaphore
    // Critical Section: Access shared resource X
    printf("Process P1 is accessing shared resource X.\n");
    sem_post(&mutex); // Signal (release) the semaphore
}

void P2_task() {
    sem_wait(&mutex); // Wait for the semaphore
    // Critical Section: Access shared resource X
    printf("Process P2 is accessing shared resource X.\n");
    sem_post(&mutex); // Signal (release) the semaphore
}

// Assuming init_sem() is called once before P1_task and P2_task are run concurrently.

#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>

