// pthread_mutex_init(&count_mutex, NULL); // מוטקס מאותחל ל-1

void barrier_wait() {
    pthread_mutex_lock(&count_mutex); // תפוס מנעול
    count++;
    if (count == N) {
        // התהליך האחרון הגיע
        for (int i = 0; i < N; ++i) {
            sem_post(&barrier_sem); // שחרר את כל התהליכים
