/* Conceptual C/C++ code demonstrating semaphore usage for mutual exclusion */

// הגדרת סמפור בינארי, מאותחל ל-1
// (בהתאם לספרייה או מימוש, זה עשוי להיות sem_t mutex; sem_init(&mutex, 0, 1);)
Semaphore mutex = 1; 

void critical_section_access() {
    wait(mutex); // פעולת P: הקטנת הסמפור, המתנה אם ערכו 0

    // תחילת הקטע הקריטי
    // קוד שניגש למשאב משותף (לדוגמה: עדכון משתנה גלובלי)
    // ...
    // סוף הקטע הקריטי

    signal(mutex); // פעולת V: הגדלת הסמפור, שחרור תהליכים ממתינים
}

// בתוכנית מרובת תרדדים, כל תרד יקרא ל-critical_section_access()
// ויוודא גישה בלעדית למשאב המשותף.

/* C/C++ style pseudocode using POSIX semaphores */
#include <semaphore.h>
#include <stdio.h>

sem_t mutex; // A binary semaphore (mutex)

// Initialize the semaphore
void init_semaphore() {
    // sem_init(semaphore, pshared, value)
    // pshared = 0 for threads in the same process
    // value = 1 for a binary semaphore (mutex) initially unlocked
    sem_init(&mutex, 0, 1);
}

// Function demonstrating critical section protection
void access_critical_section() {
    // P operation: acquire the lock
    sem_wait(&mutex);

    // Critical section: code that accesses shared resources
    printf("Thread/Process entered critical section.\n");
    // ... perform operations on shared data ...
    printf("Thread/Process exiting critical section.\n");

    // V operation: release the lock
    sem_post(&mutex);
}

// Example of how it might be used
int main() {
    init_semaphore();
    // Multiple threads/processes could call access_critical_section()
    access_critical_section();
    // ... other calls ...
    sem_destroy(&mutex); // Clean up the semaphore
    return 0;
}

solution.explanation:
סמפור הוא משתנה שלם (integer variable) המאפשר שליטה על גישה למשאבים משותפים בין תהליכים מקבילים. הוא משמש לפתרון בעיות סנכרון ותיאום במערכות הפעלה.

הפעולות הבסיסיות של סמפור הן:
1.  **wait (נקרא גם P או down)**: פעולה זו מקטינה את ערך הסמפור באחד. אם ערך הסמפור הופך שלילי, התהליך המבצע את הפעולה נחסם (מוכנס לרשימת המתנה) עד שסמפור יגדל. פעולה זו היא אטומית.
2.  **signal (נקרא גם V או up)**: פעולה זו מגדילה את ערך הסמפור באחד. אם יש תהליכים חסומים ברשימת ההמתנה של הסמפור, אחד מהם משוחרר (מועבר למצב מוכן). פעולה זו היא אטומית.

שימושים עיקריים:
*   **הדדיות (Mutual Exclusion)**: כדי להבטיח שרק תהליך אחד ייכנס לקטע קריטי (critical section) בכל רגע נתון, ניתן להשתמש בסמפור בינארי (מוטקס - mutex) המאותחל ל-1. לפני הכניסה לקטע הקריטי, תהליך יבצע `wait()` על הסמפור. לאחר היציאה מהקטע הקריטי, הוא יבצע `signal()` על הסמפור.
    ```c
    semaphore mutex = 1;

    void process() {
        // ...
        wait(mutex); // Enter critical section
        // Critical Section Code
        signal(mutex); // Exit critical section
        // ...
    }
    ```
*   **סנכרון (Synchronization)**: סמפורים יכולים לשמש לסנכרון אירועים בין תהליכים. לדוגמה, תהליך א' יכול לאותת לתהליך ב' שאירוע מסוים התרחש. סמפור ספירה (counting semaphore) יכול לאותחל ל-0. תהליך א' יבצע `signal()` כשהאירוע מתרחש, ותהליך ב' יבצע `wait()` לפני שהוא ממשיך, ובכך יבטיח שהאירוע התרחש.
    ```c
    semaphore event_occurred = 0; // Initialize to 0

    // Process A
    void producer() {
        // ... produce item
        signal(event_occurred); // Signal that item is ready
        // ...
    }

    // Process B
    void consumer() {
        // ...
        wait(event_occurred); // Wait for item to be ready
        // ... consume item
    }
    ```

סמפור בינארי הוא סמפור שיכול לקבל רק את הערכים 0 או 1. הוא משמש בדרך כלל למניעה הדדית (mutual exclusion), כלומר להבטיח שרק תהליכון אחד (או תהליך) יוכל לגשת למשאב משותף או להיכנס לקטע קריטי בנקודת זמן נתונה.

כדי להבטיח מניעה הדדית לקטע קריטי באמצעות סמפור בינארי, נבצע את השלבים הבאים:
1.  **אתחול הסמפור**: ניצור סמפור בינארי אחד ונאתחל אותו לערך 1. ערך זה מציין שהקטע הקריטי פנוי וזמין לכניסה.
2.  **כניסה לקטע הקריטי**: לפני הכניסה לקטע הקריטי, כל תהליכון המעוניין לגשת אליו יבצע את פעולת ה-`wait()` (או `P()`) על הסמפור. פעולה זו בודקת את ערך הסמפור:
    *   אם ערך הסמפור הוא 1, הוא מוקטן ל-0, והתהליכון רשאי להיכנס לקטע הקריטי.
    *   אם ערך הסמפור הוא 0, זה אומר שהקטע הקריטי תפוס על ידי תהליכון אחר. במקרה זה, התהליכון המנסה להיכנס נחסם (מוכנס לתור המתנה) עד שערך הסמפור יחזור ל-1.
3.  **יציאה מהקטע הקריטי**: לאחר שהתהליכון סיים את עבודתו בתוך הקטע הקריטי, הוא יבצע את פעולת ה-`signal()` (או `V()`) על הסמפור. פעולה זו מגדילה את ערך הסמפור ב-1 (מחזירה אותו ל-1). אם היו תהליכונים חסומים הממתינים על הסמפור, אחד מהם ישוחרר (יועבר למצב 'מוכן') ויוכל לנסות להיכנס לקטע הקריטי.

**דוגמה קוד (C/C++):**
```c
semaphore mutex = 1; // אתחול הסמפור הבינארי ל-1

void worker_thread() {
    // ... עבודה אחרת שהתהליכון מבצע ...

    wait(mutex); // נסה להיכנס לקטע הקריטי (P(mutex))

    // ===================================
    // קטע קריטי: גישה למשאב משותף
    // רק תהליכון אחד יכול להיות כאן בו-זמנית
    // ===================================

    signal(mutex); // צא מהקטע הקריטי (V(mutex))

    // ... עבודה אחרת שהתהליכון מבצע ...
}
```
בצורה זו, הסמפור `mutex` משמש כמנעול. כאשר ערכו 1, המנעול פתוח. כאשר תהליכון נכנס, הוא 'נועל' את המנעול (מציב את הערך 0). תהליכונים אחרים שמגיעים למנעול 'נעול' נחסמים. כאשר התהליכון היוצא 'פותח' את המנעול (מציב את הערך 1), תהליכון חסום אחד יכול להיכנס.

