sem_t consumed_for_logging;
pthread_mutex_t buffer_mutex;

// Function to initialize synchronization primitives
void init_sync_primitives() {
    sem_init(&empty_slots, 0, N); // N empty slots initially
    sem_init(&full_slots, 0, 0); // 0 full slots initially
    sem_init(&consumed_for_logging, 0, 0); // 0 consumed items for logging initially
    pthread_mutex_init(&buffer_mutex, NULL);
}

// Function to destroy synchronization primitives (for completeness)
void destroy_sync_primitives() {
    sem_destroy(&empty_slots);
    sem_destroy(&full_slots);
    sem_destroy(&consumed_for_logging);
    pthread_mutex_destroy(&buffer_mutex);
}

void produce_item(item_type item_to_produce) {
    sem_wait(&empty_slots); // Wait for an empty slot

    pthread_mutex_lock(&buffer_mutex); // Protect buffer access
    buffer[tail] = item_to_produce;
    tail = (tail + 1) % N;
    pthread_mutex_unlock(&buffer_mutex);

    sem_post(&full_slots); // Signal that a slot is full
}

item_type consume_item() {
    item_type consumed_item;

    sem_wait(&full_slots); // Wait for a full slot

    pthread_mutex_lock(&buffer_mutex); // Protect buffer access
    consumed_item = buffer[head];
    head = (head + 1) % N;
    pthread_mutex_unlock(&buffer_mutex);

    sem_post(&empty_slots); // Signal that a slot is empty
    sem_post(&consumed_for_logging); // Signal that an item has been consumed and is ready for logging

    return consumed_item; // Return the consumed item (conceptually)
}

void log_item() {
    sem_wait(&consumed_for_logging); // Wait for an item to be consumed and ready for logging

    // Conceptual logging operation (e.g., printf, write to file)
    // For this problem, we just need to ensure the timing is correct.
    // printf("Logger: An item was consumed and logged.\n");
}
```

**הסבר:**

*   **תהליך היצרן (`produce_item`):** לפני הוספת פריט, היצרן ממתין (באמצעות `sem_wait(&empty_slots)`) לוודא שיש מקום פנוי במאגר. לאחר מכן, הוא נועל את ה-`buffer_mutex` כדי לגשת למאגר בבטחה, מוסיף את הפריט, משחרר את המנעול, ומסמן (באמצעות `sem_post(&full_slots)`) שיש כעת פריט נוסף במאגר.

*   **תהליך הצרכן (`consume_item`):** לפני הוצאת פריט, הצרכן ממתין (באמצעות `sem_wait(&full_slots)`) לוודא שיש פריט זמין במאגר. לאחר מכן, הוא נועל את ה-`buffer_mutex` כדי לגשת למאגר בבטחה, מוציא את הפריט, משחרר את המנעול, ומסמן (באמצעות `sem_post(&empty_slots)`) שמקום התפנה במאגר. הדבר החשוב כאן הוא שהצרכן גם מסמן (באמצעות `sem_post(&consumed_for_logging)`) פריט נוסף זמין לרישום ללוג, וזאת *לאחר* שהפריט יצא מהמאגר והמנעול שוחרר, כדי לאפשר ללוגר לפעול באופן בלתי תלוי בגישה למאגר.

*   **תהליך הלוגר (`log_item`):** הלוגר ממתין (באמצעות `sem_wait(&consumed_for_logging)`) עד שפריט יוצא מהמאגר על ידי צרכן. רק כאשר יש פריט שהוצא וטרם נרשם, הסמפור מאפשר לו להמשיך ולבצע את פעולת הרישום ללוג. אין צורך במנעול הדדי בלוגר עצמו מכיוון שהוא התהליך היחיד שאמור לבצע את פעולת הרישום ללוג, ואין לו גישה ישירה למאגר המשותף.

