#define MAX_CONCURRENT_DB_ACCESS 3
#define NUM_THREADS 5

// Global variables
int active_db_queries = 0;
sem_t db_access_sem; // Semaphore for controlling concurrent DB access
sem_t mutex_sem;     // Mutex for protecting active_db_queries

void *thread_function(void *arg) {
    int thread_id = *(int *)arg;

    while (1) {
        printf("Thread %d: Waiting to access DB...\n", thread_id);

        // Simulate some work before accessing DB
        sleep(rand() % 2);

        // --- Synchronization Start ---

        // 1. Acquire mutex for active_db_queries
        sem_wait(&mutex_sem);
        // 2. Increment active_db_queries
        active_db_queries++;
        printf("Thread %d: active_db_queries incremented to %d.\n", thread_id, active_db_queries);
        // 3. Release mutex
        sem_post(&mutex_sem);

        // 4. Acquire access to DB (limited by MAX_CONCURRENT_DB_ACCESS)
        sem_wait(&db_access_sem);

        printf("Thread %d: Accessing DB. Current active: %d\n", thread_id, active_db_queries);
        // Simulate DB operation
        sleep(rand() % 3 + 1); // DB operation takes 1-3 seconds

        printf("Thread %d: Done with DB access.\n", thread_id);

        // 6. Release DB access
        sem_post(&db_access_sem);

        // 7. Acquire mutex for active_db_queries
        sem_wait(&mutex_sem);
        // 8. Decrement active_db_queries
        active_db_queries--;
        printf("Thread %d: active_db_queries decremented to %d.\n", thread_id, active_db_queries);
        // 9. Release mutex
        sem_post(&mutex_sem);

