solution.explanation:
הפתרון דורש שימוש בסמפור מונה (counting semaphore). סמפור זה מאותחל לערך K, המייצג את מספר המקומות הפנויים במקטע הקריטי. כל חוט שמעוניין להיכנס למקטע הקריטי מבצע פעולת wait (או P) על הסמפור. פעולה זו מקטינה את מונה הסמפור באחד. אם מונה הסמפור הופך שלילי (כלומר, כל K המקומות תפוסים), החוט נחסם עד שחוט אחר ישחרר מקום. לאחר שהחוט מסיים את ביצוע המקטע הקריטי, הוא מבצע פעולת signal (או V) על הסמפור. פעולה זו מגדילה את מונה הסמפור באחד. אם היו חוטים חסומים שממתינים למקום, אחד מהם ישוחרר ויורשה לו להיכנס למקטע הקריטי.

להלן מימוש ב-C/C++:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For sleep

// הגדרת סמפור גלובלי
sem_t resource_access;

void *thread_function(void *arg) {
    int thread_id = *(int*)arg;

    // קוד לפני המקטע הקריטי
    printf("חוט %d מנסה להיכנס למקטע הקריטי.\n", thread_id);

    // פעולת wait (P) על הסמפור לפני הכניסה למקטע הקריטי
    // אם מספר המשאבים הפנויים (K) הוא 0, החוט ייחסם כאן.
    sem_wait(&resource_access);

    // המקטע הקריטי (critical section)
    int val;
    sem_getvalue(&resource_access, &val); // בדיקת ערך הסמפור (לצורך הדגמה)
    printf("חוט %d נכנס למקטע הקריטי. מקומות פנויים נותרו: %d\n", thread_id, val);
    sleep(2); // סימולציה של עבודה במקטע הקריטי
    printf("חוט %d יוצא מהמקטע הקריטי.\n", thread_id);

    // פעולת signal (V) על הסמפור לאחר היציאה מהמקטע הקריטי
    // משחרר \"מקום\" אחד במקטע הקריטי, ואם יש חוטים חסומים, אחד מהם ישוחרר.
    sem_post(&resource_access);

    // קוד אחרי המקטע הקריטי
    return NULL;
}

int main() {
    int N_THREADS = 10; // לדוגמה, 10 חוטים
    int K_LIMIT = 3;    // לדוגמה, לכל היותר 3 חוטים במקביל
    pthread_t threads[N_THREADS];
    int thread_ids[N_THREADS];

    // אתחול הסמפור:
    // הארגומנט הראשון הוא מצביע לסמפור.
    // הארגומנט השני הוא 0 אם הסמפור משמש חוטים באותו תהליך, או 1 אם הוא משותף בין תהליכים.
    // הארגומנט השלישי הוא הערך ההתחלתי של הסמפור, שהוא K_LIMIT במקרה זה.
    // K_LIMIT מייצג את מספר ה\"היתרים\" או ה\"מקומות\" הזמינים במקטע הקריטי.
    if (sem_init(&resource_access, 0, K_LIMIT) != 0) {
        perror("sem_init failed");
        return 1;
    }

    // יצירת והפעלת החוטים
    for (int i = 0; i < N_THREADS; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]) != 0) {
            perror("pthread_create failed");
            return 1;
        }
    }

    // המתנה לסיום החוטים
    for (int i = 0; i < N_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // שחרור משאבים - השמדת הסמפור
    sem_destroy(&resource_access);

    printf("כל החוטים סיימו את פעולתם.\n");

    return 0;
}
