#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>

#define BUFFER_SIZE 10

// Shared buffer and indices
int buffer[BUFFER_SIZE];
int in = 0;  // Next write position
int out = 0; // Next read position

// Semaphores
sem_t mutex;    // For mutual exclusion to buffer
sem_t empty;    // Counts empty slots
sem_t full;     // Counts full slots

// Initialization function for semaphores and buffer state
void init_buffer_sync() {
    sem_init(&mutex, 0, 1);             // Binary semaphore, initialized to 1
    sem_init(&empty, 0, BUFFER_SIZE);   // Counting semaphore, initialized to BUFFER_SIZE
    sem_init(&full, 0, 0);              // Counting semaphore, initialized to 0
}

// Producer function to add an item to the buffer
void enqueue(int item) {
    sem_wait(&empty); // Wait if buffer is full
    sem_wait(&mutex); // Acquire lock for buffer access

    // Critical section: Add item to buffer
    buffer[in] = item;
    in = (in + 1) % BUFFER_SIZE;
    // printf("Producer added: %d\n", item); // Optional print for debugging

    sem_post(&mutex); // Release lock
    sem_post(&full);  // Signal that a slot is now full
}

// Consumer function to remove an item from the buffer
int dequeue() {
    int item;
    sem_wait(&full);  // Wait if buffer is empty
    sem_wait(&mutex); // Acquire lock for buffer access

    // Critical section: Remove item from buffer
    item = buffer[out];
    out = (out + 1) % BUFFER_SIZE;
    // printf("Consumer removed: %d\n", item); // Optional print for debugging

    sem_post(&mutex); // Release lock
    sem_post(&empty); // Signal that a slot is now empty
    return item;
}

solution.explanation:
הפתרון מבוסס על מנגנון "מחסום דו-שלבי" (Double Turnstile Barrier), המשתמש בשני סמפורים (turnstiles) ובמנעול (mutex) כדי להבטיח סנכרון נכון ושימוש חוזר.

**1. משתנים גלובליים ואתחול:**
```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For sleep (in example tasks)

// הגדרת מספר החוטים הכולל
#define NUM_THREADS 5 // N לדוגמה

int N = NUM_THREADS;
int count = 0;
pthread_mutex_t mutex;
sem_t barrier;
sem_t barrier_reset;

void init_barrier() {
    pthread_mutex_init(&mutex, NULL);
    sem_init(&barrier, 0, 0);       // סמפור ראשי (סגור בהתחלה)
    sem_init(&barrier_reset, 0, 1); // סמפור איפוס (פתוח בהתחלה)
}

void destroy_barrier() {
    pthread_mutex_destroy(&mutex);
    sem_destroy(&barrier);
    sem_destroy(&barrier_reset);
}
```

**2. פונקציית `barrier_wait()`:**
פונקציה זו מממשת את ההמתנה במחסום:
```c
void barrier_wait() {
    // שלב 1: איסוף החוטים במחסום הראשון
    pthread_mutex_lock(&mutex);
    count++;
    if (count == N) {
        // החוט האחרון שהגיע: סוגר את מחסום האיפוס ופותח את המחסום הראשי
        sem_wait(&barrier_reset); 
        for (int i = 0; i < N; i++) {
            sem_post(&barrier);
        }
    }
    pthread_mutex_unlock(&mutex);
    sem_wait(&barrier); // כל החוטים ממתינים כאן עד שהמחסום הראשי ייפתח

    // שלב 2: איפוס המחסום עבור המחזור הבא
    pthread_mutex_lock(&mutex);
    count--;
    if (count == 0) {
        // החוט האחרון שיוצא: סוגר את המחסום הראשי ופותח את מחסום האיפוס
        for (int i = 0; i < N; i++) {
            sem_post(&barrier_reset);
        }
    }
    pthread_mutex_unlock(&mutex);
    sem_wait(&barrier_reset); // כל החוטים ממתינים כאן עד שמחסום האיפוס ייפתח
}
```

**3. פונקציית `worker_thread`:**
כל חוט מבצע את המשימות שלו ומשתמש ב-`barrier_wait`:
```c
// פונקציות לדוגמה למשימות A ו-B (אין צורך לממשן במבחן, רק לצורך הדגמה)
void taskA(int thread_id) {
    printf("Thread %d: Starting Task A\n", thread_id);
    sleep(rand() % 2); // הדמיית עבודה
    printf("Thread %d: Finished Task A\n", thread_id);
}

void taskB(int thread_id) {
    printf("Thread %d: Starting Task B\n", thread_id);
    sleep(rand() % 2); // הדמיית עבודה
    printf("Thread %d: Finished Task B\n", thread_id);
}

void *worker_thread(void *arg) {
    int thread_id = *(int *)arg;
    free(arg); // שחרור הזיכרון שהוקצה למזהה החוט

    while (1) { // לולאה אינסופית עבור מחזורים חוזרים
        taskA(thread_id);
        barrier_wait(); // המתן עד שכל N החוטים יסיימו את Task A
        taskB(thread_id);
        printf("Thread %d: Cycle complete.\n", thread_id);
        sleep(1); // השהייה קטנה לפני המחזור הבא
    }
    return NULL;
}
```

**הסבר מפורט:**

*   **משתנים גלובליים:**
    *   `N`: קבוע המגדיר את מספר החוטים הכולל במערכת. יש לאתחל אותו לפני יצירת החוטים.
    *   `count`: מונה את מספר החוטים שהגיעו לנקודת הסנכרון בשלב הנוכחי. מאופס בכל מחזור.
    *   `mutex`: מנעול `pthread_mutex_t` המשמש להגנה על הגישה למשתנה `count` המשותף, ובכך מבטיח עדכון אטומי (atomic) של המונה. מאותחל ל-1 (פתוח).
    *   `barrier`: סמפור `sem_t` המשמש לחסימת חוטים בשלב הראשון של המחסום, עד שכל `N` החוטים מגיעים. מאותחל ל-0 (סגור לחלוטין).
    *   `barrier_reset`: סמפור `sem_t` נוסף המשמש לחסימת חוטים בשלב השני, ומונע מהם להתחיל מחזור חדש לפני שכל החוטים סיימו את המחזור הקודם. מאותחל ל-1 (פתוח עבור המחזור הראשון).

*   **פעולת `barrier_wait()`:**
    1.  **שלב ראשון (איסוף):** כל חוט שמגיע קורא ל-`pthread_mutex_lock(&mutex)`, מגדיל את `count`, ומשחרר את ה-`mutex`. כאשר החוט ה-`N` מגיע (כלומר, `count` מגיע ל-`N`), הוא מזהה שהוא האחרון. חוט זה מבצע `sem_wait(&barrier_reset)` כדי "לסגור" את שער האיפוס (ובכך למנוע מחזורים עתידיים להתקדם בטרם עת) ולאחר מכן מבצע `sem_post(&barrier)` `N` פעמים. פעולה זו משחררת את כל `N` החוטים שייתכן שממתינים או שיגיעו בקרוב ל-`sem_wait(&barrier)`. כל החוטים, כולל החוט ה-`N`, ממתינים ב-`sem_wait(&barrier)` עד שהסמפור ייפתח.
    2.  **שלב שני (איפוס):** לאחר שכל החוטים עברו את `sem_wait(&barrier)`, הם נכנסים לשלב השני. כל חוט נועל שוב את ה-`mutex`, מקטין את `count`, ומשחרר את ה-`mutex`. כאשר החוט האחרון שיוצא (כלומר, `count` מגיע ל-`0`) מזהה שהוא האחרון. חוט זה מבצע `sem_post(&barrier_reset)` `N` פעמים כדי "לפתוח" מחדש את שער האיפוס עבור המחזור הבא. כל החוטים ממתינים ב-`sem_wait(&barrier_reset)` עד שהסמפור ייפתח. זה מבטיח שכל החוטים סיימו לחלוטין את המחזור הנוכחי (כולל איפוס המונה) לפני שמישהו יתחיל את השלב הראשון של המחזור הבא.

*   **פונקציית `worker_thread`:** כל חוט מבצע בלולאה אינסופית את `taskA`, ולאחר מכן קורא ל-`barrier_wait()` כדי להמתין לשאר החוטים. רק לאחר שכל `N` החוטים סיימו את `taskA` ועברו את המחסום, כולם ממשיכים יחד ל-`taskB`. הדבר מבטיח את דרישת הסנכרון ואת יכולת השימוש החוזר של המחסום.

