```c
#include <semaphore.h>
#include <stdlib.h> // For malloc, free (though not directly used in the Barrier struct itself here)

typedef struct {
    int N; // Total number of threads for the barrier
    int count; // Number of threads arrived at the barrier
    sem_t mutex; // Protects 'count'
    sem_t turnstile; // Blocks threads until all arrive
    sem_t turnstile2; // Used to reset the barrier for reuse
} Barrier;

void barrier_init(Barrier *b, int num_threads) {
    b->N = num_threads;
    b->count = 0;
    sem_init(&b->mutex, 0, 1); // Mutex initially open
    sem_init(&b->turnstile, 0, 0); // Turnstile initially locked
    sem_init(&b->turnstile2, 0, 1); // Turnstile2 initially open
}

void barrier_destroy(Barrier *b) {
    sem_destroy(&b->mutex);
    sem_destroy(&b->turnstile);
    sem_destroy(&b->turnstile2);
}

void barrier_wait(Barrier *b) {
    // Phase 1: Gathering threads and releasing them
    sem_wait(&b->mutex);
    b->count++;
    if (b->count == b->N) {
        sem_wait(&b->turnstile2); // Close turnstile2 to prevent early reset
        for (int i = 0; i < b->N; i++) {
            sem_post(&b->turnstile); // Open turnstile to release all threads
        }
    }
    sem_post(&b->mutex);

    sem_wait(&b->turnstile); // All threads wait here until released

    // Phase 2: Resetting the barrier for reuse
    sem_wait(&b->mutex);
    b->count--;
    if (b->count == 0) {
        for (int i = 0; i < b->N; i++) {
            sem_post(&b->turnstile2); // Reopen turnstile2 for the next cycle
        }
    }
    sem_post(&b->mutex);
}
```

