solution.explanation:
לפתרון בעיית המאגר החסום באמצעות סמפורים נדרשים שלושה סמפורים:
1.  **`mutex` (סמפור בינארי / סמפור הדדיות):** מגן על הגישה לקטעים הקריטיים של המאגר (הפונקציות `insert_item` ו-`remove_item`) כדי להבטיח שרק תהליך אחד יבצע שינויים במאגר בכל רגע נתון. ערך אתחול: 1 (המאגר פנוי לגישה).
2.  **`empty` (סמפור ספירה):** עוקב אחר מספר המקומות הריקים במאגר. תהליך יצרן ימתין על סמפור זה אם אין מקום פנוי. ערך אתחול: `BUFFER_SIZE` (בהתחלה כל המאגר ריק).
3.  **`full` (סמפור ספירה):** עוקב אחר מספר הפריטים המלאים במאגר. תהליך צרכן ימתין על סמפור זה אם המאגר ריק מפריטים. ערך אתחול: 0 (בהתחלה המאגר ריק מפריטים).

המימוש של הפונקציות `producer` ו-`consumer` ישתמש בסמפורים אלו באופן הבא:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For sleep

#define BUFFER_SIZE 5

int buffer[BUFFER_SIZE];
int in = 0; // Next empty slot
int out = 0; // Next item to remove

sem_t mutex; // For mutual exclusion
sem_t empty; // Counts empty slots
sem_t full;  // Counts full slots

// Initialize buffer items to -1 for clarity (empty)
void init_buffer() {
    for (int i = 0; i < BUFFER_SIZE; ++i) {
        buffer[i] = -1;
    }
}

void init_semaphores() {
    sem_init(&mutex, 0, 1); // Binary semaphore for mutual exclusion, initial value 1
    sem_init(&empty, 0, BUFFER_SIZE); // Counting semaphore for empty slots, initial value BUFFER_SIZE
    sem_init(&full, 0, 0); // Counting semaphore for full slots, initial value 0
}

void insert_item(int item) {
    buffer[in] = item;
    in = (in + 1) % BUFFER_SIZE;
    printf("Producer inserted item %d. Buffer state: ", item);
    for (int i=0; i<BUFFER_SIZE; ++i) {
        printf("%d ", buffer[i]);
    }
    printf("]\n");
}

int remove_item() {
    int item = buffer[out];
    buffer[out] = -1; // Mark as empty for clarity
    out = (out + 1) % BUFFER_SIZE;
    printf("Consumer removed item %d. Buffer state: ", item);
    for (int i=0; i<BUFFER_SIZE; ++i) {
        printf("%d ", buffer[i]);
    }
    printf("]\n");
    return item;
}

void *producer(void *param) {
    int item;
    while (1) {
        item = rand() % 100; // Simulate producing an item

        sem_wait(&empty); // Wait if buffer is full (no empty slots)
        sem_wait(&mutex); // Acquire lock for critical section

        insert_item(item);

        sem_post(&mutex); // Release lock
        sem_post(&full);  // Signal that a slot is now full

        sleep(1); // Simulate work
    }
    return NULL;
}

void *consumer(void *param) {
    int item;
    while (1) {
        sem_wait(&full);  // Wait if buffer is empty (no full slots)
        sem_wait(&mutex); // Acquire lock for critical section

        item = remove_item();

        sem_post(&mutex); // Release lock
        sem_post(&empty); // Signal that a slot is now empty

        sleep(2); // Simulate work
    }
    return NULL;
}
```

