#include <semaphore.h>
#include <unistd.h> // for usleep

sem_t sem_A;
sem_t sem_B;
sem_t sem_concurrent;
sem_t mutex_resource_alloc; // להגנה על הקצאת משאבים מרובים

void init_synchronization(int MAX_A, int MAX_B, int MAX_CONCURRENT_TASKS) {
    sem_init(&sem_A, 0, MAX_A);
    sem_init(&sem_B, 0, MAX_B);
    sem_init(&sem_concurrent, 0, MAX_CONCURRENT_TASKS);
    sem_init(&mutex_resource_alloc, 0, 1);
}

void destroy_synchronization() {
    sem_destroy(&sem_A);
    sem_destroy(&sem_B);
    sem_destroy(&sem_concurrent);
    sem_destroy(&mutex_resource_alloc);
}

/* פונקציות שיש לממש */
void acquire_resources(int req_A, int req_B);
void release_resources(int req_A, int req_B);

solution.explanation:
פתרון:

**א. חתימות הפונקציות:**
```c
void acquire_resources(int req_A, int req_B);
void release_resources(int req_A, int req_B);
```

**ב. יישום הפונקציות:**
```c
void acquire_resources(int req_A, int req_B) {
    // 1. תפוס מקום למשימה מקבילה. זה מגביל את המספר הכולל של משימות שיכולות לנסות לרכוש משאבים.
    sem_wait(&sem_concurrent);

    // 2. היכנס לקטע קריטי להקצאת משאבים. זה מבטיח שרק תהליך אחד בכל פעם יבדוק וירכוש משאבים.
    while (1) {
        sem_wait(&mutex_resource_alloc);

        int val_A, val_B;
        // בדוק את כמות המשאבים הזמינים. `sem_getvalue` אינה אטומית עם `sem_wait`.
        // לכן, אנחנו בתוך critical section המוגן על ידי `mutex_resource_alloc`.
        sem_getvalue(&sem_A, &val_A);
        sem_getvalue(&sem_B, &val_B);

        if (val_A >= req_A && val_B >= req_B) {
            // כל המשאבים זמינים. רכוש אותם.
            // רכישה ביחידות בודדות בתוך הקטע הקריטי.
            for (int i = 0; i < req_A; ++i) {
                sem_wait(&sem_A);
            }
            for (int i = 0; i < req_B; ++i) {
                sem_wait(&sem_B);
            }
            sem_post(&mutex_resource_alloc); // שחרר את המוטקס לאחר רכישה מוצלחת
            break; // יצא מהלולאה, המשאבים נרכשו בהצלחה
        } else {
            // המשאבים אינם זמינים במלואם. שחרר את המוטקס זמנית ואז נסה שוב.
            sem_post(&mutex_resource_alloc);
            usleep(1000); // המתן זמן קצר כדי למנוע busy-waiting ולאפשר לתהליכים אחרים לנסות
        }
    }
}

void release_resources(int req_A, int req_B) {
    // שחרר יחידות של ResourceA
    for (int i = 0; i < req_A; ++i) {
        sem_post(&sem_A);
    }
    // שחרר יחידות של ResourceB
    for (int i = 0; i < req_B; ++i) {
        sem_post(&sem_B);
    }
    // שחרר את המקום של המשימה המקבילה
    sem_post(&sem_concurrent);
}
```

**ג. הסבר על מניעת קיפאון והרעבה:**

**מניעת קיפאון (Deadlock Prevention):**
קיפאון מתרחש כאשר מתקיימים ארבעה תנאים: מניעה הדדית (Mutual Exclusion), החזקה והמתנה (Hold and Wait), אי-הפקעה (No Preemption), והמתנה מעגלית (Circular Wait). הפתרון המוצע מונע קיפאון על ידי שבירת תנאי ה"החזקה והמתנה" וה"המתנה מעגלית" באופן הבא:

1.  **מניעת הקצאה חלקית (Acquire All or None):** הפונקציה `acquire_resources` משתמשת בסמפור בינארי `mutex_resource_alloc` כדי להגן על קטע קריטי שבו מתבצעת הבדיקה והרכישה של המשאבים `ResourceA` ו-`ResourceB`. תהליך חייב לרכוש את `mutex_resource_alloc` לפני שהוא יכול לבדוק אם המשאבים זמינים. בתוך הקטע הקריטי, התהליך בודק אם *כל* המשאבים הנדרשים (req_A ו-req_B) זמינים באמצעות `sem_getvalue`. רק אם כל המשאבים זמינים, הוא רוכש אותם (באמצעות לולאות של `sem_wait`). אם לא כל המשאבים זמינים, התהליך משחרר את `mutex_resource_alloc` וחוזר לנסות מאוחר יותר. גישה זו מבטיחה שתהליך רוכש את כל המשאבים הנדרשים לו או אף אחד מהם, ובכך נמנע מצב של "החזקה והמתנה" שבו תהליך מחזיק במשאב אחד וממתין למשאב אחר, מה שיכול להוביל לקיפאון. מכיוון שרק תהליך אחד יכול לבצע את שלב הבדיקה והרכישה האטומית בכל רגע נתון, לא ייתכן מצב שבו שני תהליכים יחזיקו חלקים מהמשאבים וימתינו זה לזה באופן מעגלי.
2.  **מניעת המתנה מעגלית (Circular Wait):** למרות שההקצאה האטומית היא המנגנון העיקרי למניעת קיפאון, אם היינו רוכשים את המשאבים בנפרד, היה נדרש סדר קבוע. בפתרון זה, הסדר שבו נרכשים `sem_A` ואז `sem_B` בתוך הקטע הקריטי תורם גם הוא למניעת המתנה מעגלית, אך כאמור, המנגנון של "הקצה הכל או כלום" הוא המשמעותי יותר.

**מניעת הרעבה (Starvation Prevention):**
סמפורי POSIX (כמו אלה המשמשים כאן) בדרך כלל מיישמים תור המתנה הוגן (FIFO - First-In, First-Out) עבור קריאות `sem_wait`. המשמעות היא שתהליכים שממתינים לסמפור יתעוררו בסדר שבו הם נכנסו לתור ההמתנה. זה מסייע במניעת הרעבה במספר דרכים:

1.  **הוגנות ב-`sem_concurrent`:** תהליכים הממתינים למקום במגבלת המשימות המקבילות (`sem_concurrent`) יקבלו את מקומם בסדר הוגן, מה שמבטיח שכל משימה תקבל בסופו של דבר הזדמנות לנסות לרכוש משאבים.
2.  **הוגנות ב-`mutex_resource_alloc`:** תהליכים הממתינים להיכנס לקטע הקריטי של הקצאת המשאבים (המוגן על ידי `mutex_resource_alloc`) יקבלו את הגישה בסדר הוגן. זה מבטיח שכל תהליך יקבל הזדמנות לבדוק את זמינות המשאבים.
3.  **הוגנות בסמפורי המשאבים (`sem_A`, `sem_B`):** כאשר תהליך מצליח להיכנס לקטע הקריטי ומוצא שכל המשאבים זמינים, הוא מבצע סדרת קריאות `sem_wait` כדי לרכוש אותם. אם אחד מהסמפורים הללו נחסם, התהליך ימתין בתור הוגן.
4.  **הפחתת Busy-Waiting:** השימוש ב-`usleep(1000)` בתוך לולאת ה-`while(1)` כאשר המשאבים אינם זמינים, מפחית את ה-busy-waiting. במקום שתהליך ינסה שוב ושוב באופן מיידי, הוא ממתין זמן קצר, מה שמפנה את המעבד לתהליכים אחרים ומאפשר למשאבים להשתחרר. זה גם נותן לתהליכים אחרים (אשר ממתינים ל-`mutex_resource_alloc`) הזדמנות לרכוש את המוטקס ולנסות את מזלם.

למרות שהפתרון אינו מבטיח מניעת הרעבה אבסולוטית (לדוגמה, תהליך הדורש כמות גדולה מאוד של משאבים עלול למצוא את עצמו ממתין זמן רב אם משימות קטנות יותר ממשיכות להגיע ולרכוש את המשאבים הזמינים), הוא מקטין משמעותית את הסיכון להרעבה על ידי שילוב של הוגנות מובנית בסמפורי POSIX והפחתת busy-waiting.

