sem_t empty; /* Counts empty slots in buffer */
sem_t full;  /* Counts full slots in buffer */
sem_t active_producers_limit; /* Limits concurrent active producers */

/* Assume semaphores are initialized as follows:
 * sem_init(&mutex, 0, 1);
