void *producer_thread_func(void *arg) {
    int item;
    while (1) {
        // Step 1: Limit active producers
        // Acquire a slot to be an active producer for item production
        sem_wait(&active_producers_limit);

        // Simulate item production (critical section for production)
        // This is the phase where the producer is "actively trying to produce"
        item = rand() % 100; // Placeholder for produce_item()

        // Release the active producer slot once item is produced.
        // This allows another producer to start producing while this one waits for buffer space.
        sem_post(&active_producers_limit);

        // Step 2: Add item to buffer (standard bounded buffer logic)
        sem_wait(&empty); // Wait for an empty slot in the buffer
        sem_wait(&mutex); // Acquire buffer access lock

        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;

        sem_post(&mutex); // Release buffer access lock
        sem_post(&full);  // Signal that a slot is now full

        // Simulate some delay or other work after adding to buffer
    }
    return NULL;
}

void *consumer_thread_func(void *arg) {
    int item;
    while (1) {
        // Step 1: Remove item from buffer (standard bounded buffer logic)
        sem_wait(&full);  // Wait for a full slot in the buffer
        sem_wait(&mutex); // Acquire buffer access lock

        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;

        sem_post(&mutex); // Release buffer access lock
        sem_post(&empty); // Signal that a slot is now empty

        // Simulate some delay or other work after consuming
    }
