}

#define N_SLOTS 10 // מספר כולל של תאי זיכרון
sem_t slot_sem[N_SLOTS]; // סמפור בינארי לכל תא, מאותחל ל-1

// פונקציית אתחול (נקראת פעם אחת בתחילת הריצה)
void init_resources() {
    for (int i = 0; i < N_SLOTS; ++i) {
        sem_init(&slot_sem[i], 0, 1);
    }
}

// פונקציה להקצאת k תאי זיכרון רציפים
int acquire_contiguous_slots(int k) {
    int start_idx = -1;
    while (start_idx == -1) { // לולאת busy-wait
        for (int i = 0; i <= N_SLOTS - k; ++i) {
            bool all_acquired = true;
            for (int j = 0; j < k; ++j) {
                if (sem_trywait(&slot_sem[i+j]) != 0) { // ניסיון לרכוש
                    all_acquired = false;
                    // שחרור סמפורים שכבר נרכשו בבלוק הנוכחי
                    for (int l = 0; l < j; ++l) {
                        sem_post(&slot_sem[i+l]);
                    }
                    break;
                }
            }
            if (all_acquired) {
                start_idx = i;
                break; // נמצא בלוק וכולו נרכש
            }
        }
    }
    return start_idx; // מחזיר את אינדקס ההתחלה של הבלוק
}

// פונקציה לשחרור k תאי זיכרון רציפים
void release_contiguous_slots(int start_idx, int k) {
    for (int j = 0; j < k; ++j) {
        sem_post(&slot_sem[start_idx + j]);
    }
}

