solution.explanation:
פתרון:

**1. השלמת קטעי הקוד:**

```c
#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <unistd.h> // For sleep

// Global semaphores and counters (to be initialized)
sem_t resource_access;        // Controls access to the shared resource
sem_t mutex_read_count;     // Protects read_count
sem_t mutex_write_count;    // Protects write_count
sem_t readers_queue_block;  // Blocks new readers if writers are waiting

int read_count = 0;   // Number of readers currently reading
int write_count = 0;  // Number of writers currently writing (should be 0 or 1)

// Shared resource (simplified)
int shared_data = 0;

void reader_task() {
    sem_wait(&readers_queue_block); // Wait if writers are waiting/writing
    sem_wait(&mutex_read_count);
    read_count++;
    if (read_count == 1) { // First reader
        sem_wait(&resource_access); // Acquire resource_access
    }
    sem_post(&mutex_read_count);
    sem_post(&readers_queue_block); // Allow other readers to pass readers_queue_block

    // Critical Section: Reading
    printf("Reader %lu is reading: %d\n", pthread_self(), shared_data);
    sleep(1); // Simulate reading time

    sem_wait(&mutex_read_count);
    read_count--;
    if (read_count == 0) { // Last reader
        sem_post(&resource_access); // Release resource_access
    }
    sem_post(&mutex_read_count);
}

void writer_task() {
    sem_wait(&mutex_write_count);
    write_count++;
    if (write_count == 1) { // First writer
        sem_wait(&readers_queue_block); // Block new readers from entering
    }
    sem_post(&mutex_write_count);

    sem_wait(&resource_access); // Get exclusive access

    // Critical Section: Writing
    shared_data++;
    printf("Writer %lu is writing: %d\n", pthread_self(), shared_data);
    sleep(2); // Simulate writing time

    sem_post(&resource_access); // Release exclusive access

    sem_wait(&mutex_write_count);
    write_count--;
    if (write_count == 0) { // Last writer
        sem_post(&readers_queue_block); // Allow readers to enter again
    }
    sem_post(&mutex_write_count);
}

// Main function for initialization and thread creation (not part of the answer)
// int main() {
//     sem_init(&resource_access, 0, 1);
//     sem_init(&mutex_read_count, 0, 1);
//     sem_init(&mutex_write_count, 0, 1);
//     sem_init(&readers_queue_block, 0, 1);
//     // ... create threads ...
//     return 0;
