/* כלולות: <semaphore.h>, <pthread.h>, <stdio.h>, <stdlib.h>, <unistd.h> */

#define BUFFER_SIZE_A 5 // גודל חוצץ חלקים מורכבים
#define BUFFER_SIZE_T 5 // גודל חוצץ חלקים מבוקרים

sem_t mutex_A, full_A, empty_A; // סמפורים לחוצץ חלקים מורכבים
sem_t mutex_T, full_T, empty_T; // סמפורים לחוצץ חלקים מבוקרים

// במציאות, אלו יהיו מבני נתונים של חוצצים. לצורך הבעיה, נשתמש במונים פשוטים.
int assembled_parts_count = 0;
int tested_parts_count = 0;

// פונקציות assembler ו-packer לא מוצגות במלואן, אך פועלות כצרכן/יצרן סטנדרטי.
