// פונקציית עובד הבדיקה (Tester) - מכילה את הפגם
void *tester(void *arg) {
    while (1) {
        // שלב 1: צריכת חלק מורכב מ-assembled_parts_buffer
        sem_wait(&full_A);  // ממתין לחלק מורכב זמין
        sem_wait(&mutex_A); // נועל גישה לחוצץ assembled_parts_buffer

        assembled_parts_count--; // צורך חלק
        printf("Tester: Consumed assembled part. Remaining: %d\n", assembled_parts_count);

        // מדמה פעולת בדיקה
        usleep(rand() % 100000 + 50000); 

        // שלב 2: ייצור חלק מבוקר והכנסתו ל-tested_parts_buffer
        // ** פגם לוגי פוטנציאלי מתרחש כאן **
        sem_wait(&empty_T); // ממתין למקום פנוי בחוצץ tested_parts_buffer
        sem_wait(&mutex_T); // נועל גישה לחוצץ tested_parts_buffer

        // רק לאחר שקיבלנו את שני הסמפורים לחוצץ T, אנו משחררים את הסמפורים של חוצץ A.
        sem_post(&mutex_A); // שחרור נעילה לחוצץ assembled_parts_buffer
        sem_post(&empty_A); // איתות על מקום פנוי בחוצץ assembled_parts_buffer

        tested_parts_count++; // מייצר חלק מבוקר
        printf("Tester: Added tested part. Total tested: %d\n", tested_parts_count);

        sem_post(&mutex_T); // שחרור נעילה לחוצץ tested_parts_buffer
        sem_post(&full_T);  // איתות על חלק מבוקר זמין

        usleep(rand() % 100000 + 50000);
    }
    return NULL;
}

solution.explanation:
הבעיה בקוד של פונקציית ה-`tester` היא פוטנציאל לקיפאון (Deadlock) כתוצאה מסדר שגוי של פעולות `sem_wait` ו-`sem_post`.

**הסבר הקיפאון:**
1.  **תנאים מקדימים לקיפאון:** נניח שכל המקומות ב-`tested_parts_buffer` מלאים (כלומר, `empty_T` שווה ל-0) ו/או עובדי האריזה (Packers) אינם צורכים מספיק מהר. במקביל, נניח שעובדי ההרכבה (Assemblers) מילאו את רוב ה-`assembled_parts_buffer` (כלומר, `empty_A` קרוב ל-0 או שווה לו).
2.  **תרחיש קיפאון:**
    *   תהליכון `tester` כלשהו מצליח לצרוך חלק מורכב מ-`assembled_parts_buffer`. הוא מבצע `sem_wait(&full_A)` ו-`sem_wait(&mutex_A)` בהצלחה, צורך את החלק, ומגיע לשלב 2 בקוד.
    *   כעת, תהליכון ה-`tester` מנסה להכניס את החלק המבוקר ל-`tested_parts_buffer`. הוא מבצע `sem_wait(&empty_T)`. מכיוון ש-`empty_T` שווה ל-0 (בהתאם לתנאים המקדימים), תהליכון ה-`tester` נכנס למצב חסימה וממתין שמקום יתפנה ב-`tested_parts_buffer`.
    *   **הבעיה המרכזית:** בזמן שתהליכון ה-`tester` חסום בהמתנה ל-`empty_T`, הוא עדיין מחזיק בסמפור `mutex_A` (הוא לא שחרר אותו עדיין). הוא גם מחזיק בעצם את ה"חלק" שצרך מ-`assembled_parts_buffer` (הוא עדיין לא ביצע `sem_post(&empty_A)`).
    *   כתוצאה מכך:
        *   **עובדי הרכבה (Assemblers):** אם `assembled_parts_buffer` מלא, או אם `empty_A` קרוב ל-0, עובדי ההרכבה יצטרכו לבצע `sem_wait(&empty_A)`. אם הם יצליחו, הם יצטרכו לבצע `sem_wait(&mutex_A)`. אך `mutex_A` מוחזק על ידי תהליכון ה-`tester` החסום, ולכן עובדי ההרכבה ייחסמו.
        *   **עובדי אריזה (Packers):** כדי ש-`empty_T` יגדל ויאפשר ל-`tester` להמשיך, עובדי האריזה צריכים לצרוך חלקים מ-`tested_parts_buffer`. אך אם אין חלקים ב-`tested_parts_buffer` (כי ה-`tester` חסום ולא יכול לייצר), או אם הם צריכים לגשת ל-`mutex_T` שגם הוא עלול להיות מוחזק (אם תהליכונים אחרים של `tester` הגיעו לשלב זה וגם הם חסומים על `empty_T` או `mutex_T`), הם לא יוכלו להתקדם.
    *   נוצר מעגל המתנה: ה-`tester` ממתין ל-`packer` שיפנה מקום ב-`tested_parts_buffer`, אך ה-`packer` לא יכול לפנות מקום כי ה-`tester` לא ייצר, וה-`tester` לא יכול לייצר כי הוא חסום על `empty_T` (תוך כדי שהוא חוסם את ה-`assemblers` מלהתקדם על ידי החזקת `mutex_A`).

**התיקון המוצע:**
הפתרון הוא לשחרר את הסמפורים של חוצץ `assembled_parts_buffer` מיד לאחר סיום השימוש בהם (כלומר, לאחר צריכת החלק המורכב), ורק לאחר מכן לנסות לרכוש את הסמפורים של חוצץ `tested_parts_buffer`. זה מבטיח שתהליכון ה-`tester` לא יחזיק נעילה מיותרת על משאב אחד (`mutex_A`) בזמן שהוא ממתין למשאב אחר (`empty_T`).

**קוד מתוקן עבור פונקציית `tester`:**
```c
void *tester(void *arg) {
    while (1) {
        // שלב 1: צריכת חלק מורכב מ-assembled_parts_buffer
        sem_wait(&full_A);  // ממתין לחלק מורכב זמין
        sem_wait(&mutex_A); // נועל גישה לחוצץ assembled_parts_buffer

        assembled_parts_count--; // צורך חלק
        printf("Tester: Consumed assembled part. Remaining: %d\n", assembled_parts_count);

        // שחרור הסמפורים של חוצץ A מיד לאחר השימוש בהם
        sem_post(&mutex_A); // שחרור נעילה לחוצץ assembled_parts_buffer
        sem_post(&empty_A); // איתות על מקום פנוי בחוצץ assembled_parts_buffer

        // מדמה פעולת בדיקה
        usleep(rand() % 100000 + 50000); 

        // שלב 2: ייצור חלק מבוקר והכנסתו ל-tested_parts_buffer
        sem_wait(&empty_T); // ממתין למקום פנוי בחוצץ tested_parts_buffer
        sem_wait(&mutex_T); // נועל גישה לחוצץ tested_parts_buffer

        tested_parts_count++; // מייצר חלק מבוקר
        printf("Tester: Added tested part. Total tested: %d\n", tested_parts_count);

        sem_post(&mutex_T); // שחרור נעילה לחוצץ tested_parts_buffer
        sem_post(&full_T);  // איתות על חלק מבוקר זמין

        usleep(rand() % 100000 + 50000);
    }
    return NULL;
}
```
תיקון זה מבטיח שהתהליכון `tester` ישחרר את המשאבים מחוצץ A לפני שהוא ינסה לרכוש משאבים מחוצץ T, ובכך מונע את התנאי המרכזי לקיפאון בשרשרת זו.

