#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <semaphore.h>
#include <sys/mman.h> // For shared memory with semaphore

#define NUM_CHILDREN 3

sem_t *shared_semaphore; // Pointer to shared semaphore

void child_task(int id) {
    printf("Child %d (PID %d): Trying to access resource.\n", id, getpid());
    sem_wait(shared_semaphore); // Acquire lock
    // Critical Section
    printf("Child %d (PID %d): *** Entered Critical Section ***\n", id, getpid());
    sleep(1); // Simulate work
    printf("Child %d (PID %d): --- Exiting Critical Section ---\n", id, getpid());
    sem_post(shared_semaphore); // Release lock
    exit(0);
}

int main() {
    setbuf(stdout, NULL); // Disable buffering for immediate output

    // Allocate shared memory for the semaphore
    shared_semaphore = mmap(NULL, sizeof(sem_t), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (shared_semaphore == MAP_FAILED) {
        perror("mmap failed");
        return 1;
    }

    // Initialize semaphore for process sharing (1), initial value 1 (mutual exclusion)
    if (sem_init(shared_semaphore, 1, 1) == -1) {
        perror("sem_init failed");
        return 1;
    }

    pid_t pids[NUM_CHILDREN];

    for (int i = 0; i < NUM_CHILDREN; i++) {
        pids[i] = fork();
        if (pids[i] == -1) {
            perror("fork failed");
            return 1;
        } else if (pids[i] == 0) { // Child process
            child_task(i);
        }
    }

    // Parent waits for all children
    for (int i = 0; i < NUM_CHILDREN; i++) {
        wait(NULL);
    }

    printf("Parent: All children finished. Cleaning up.\n");

    // Destroy the semaphore
    if (sem_destroy(shared_semaphore) == -1) {
        perror("sem_destroy failed");
        return 1;
    }

    // Unmap shared memory
    if (munmap(shared_semaphore, sizeof(sem_t)) == -1) {
        perror("munmap failed");
        return 1;
    }

    return 0;
}

