#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For sleep

sem_t A;
sem_t B;

void* thread_X(void* arg) {
    printf("Thread X: Trying to acquire semaphore A\n");
    sem_wait(&A);
    printf("Thread X: Acquired semaphore A, trying to acquire B\n");
    sleep(1); // Simulate work or context switch
    sem_wait(&B);
    printf("Thread X: Acquired both A and B\n");
    // Critical section
    printf("Thread X: Releasing semaphores\n");
    sem_post(&B);
    sem_post(&A);
    return NULL;
}

void* thread_Y(void* arg) {
    printf("Thread Y: Trying to acquire semaphore B\n");
    sem_wait(&B);
    printf("Thread Y: Acquired semaphore B, trying to acquire A\n");
    sleep(1); // Simulate work or context switch
    sem_wait(&A);
    printf("Thread Y: Acquired both B and A\n");
    // Critical section
    printf("Thread Y: Releasing semaphores\n");
    sem_post(&A);
    sem_post(&B);
    return NULL;
}

int main() {
    sem_init(&A, 0, 1);
    sem_init(&B, 0, 1);

    pthread_t tid_x, tid_y;

    printf("Main: Creating threads...\n");
    pthread_create(&tid_x, NULL, thread_X, NULL);
    pthread_create(&tid_y, NULL, thread_Y, NULL);

    pthread_join(tid_x, NULL);
    pthread_join(tid_y, NULL);

    sem_destroy(&A);
    sem_destroy(&B);

    printf("Main: Both threads finished (or deadlocked)\n");
    return 0;
}

solution.explanation:
הקוד הנתון סובל מבעיית קיפאון (Deadlock). נסביר את התרחיש הבעייתי ואת הפתרון הנכון.

**1. זיהוי הבעיה ותיאור התרחיש הבעייתי:**
הקוד הנתון אינו פותר נכונה את בעיית הסנכרון והוא מוביל למצב של קיפאון (Deadlock). הסיבה לכך היא ששני סוגי התהליכונים מנסים לרכוש את המשאבים (הסמפורים) בסדר שונה:
*   `thread_X` מנסה לרכוש את A ואז את B.
*   `thread_Y` מנסה לרכוש את B ואז את A.

תרחיש ספציפי המוביל לקיפאון:
1.  `thread_X` מתחיל לרוץ ומבצע בהצלחה `sem_wait(&A)`. כעת `thread_X` מחזיק בסמפור A.
2.  `thread_X` מבצע `sleep(1)`, מה שמאפשר ל-`thread_Y` לקבל הקצאת מעבד ולהתחיל לרוץ.
3.  `thread_Y` מתחיל לרוץ ומבצע בהצלחה `sem_wait(&B)`. כעת `thread_Y` מחזיק בסמפור B.
4.  `thread_Y` מבצע `sleep(1)`.
5.  כאשר `thread_X` מתעורר מהשינה, הוא מנסה לבצע `sem_wait(&B)`. מכיוון ש-`thread_Y` מחזיק כעת בסמפור B, `thread_X` נחסם וממתין לשחרור B.
6.  כאשר `thread_Y` מתעורר מהשינה, הוא מנסה לבצע `sem_wait(&A)`. מכיוון ש-`thread_X` מחזיק כעת בסמפור A, `thread_Y` נחסם וממתין לשחרור A.

בשלב זה, `thread_X` מחכה ל-`thread_Y` שישחרר את B, ו-`thread_Y` מחכה ל-`thread_X` שישחרר את A. נוצר מעגל המתנה הדדית (circular wait), והמערכת נכנסת למצב קיפאון. שני התהליכונים חסומים ולא יוכלו להמשיך.

**2. פתרון מתוקן:**
הדרך הנפוצה למנוע קיפאון במקרה זה היא לוודא שכל התהליכונים מנסים לרכוש את המשאבים באותו סדר קבוע (resource hierarchy). לדוגמה, שניהם ירכשו תמיד את A ואז את B. במימוש זה, אם `thread_X` רוכש את A, הוא ינסה לרכוש את B. אם `thread_Y` גם רוצה את A, הוא יחסם עד ש-`thread_X` ישחרר אותו (לאחר שסיים את כל המקטע הקריטי ושחרר את B ואז את A). כך נמנעת המתנה מעגלית.

**קוד מתוקן לדוגמה (שינוי ב-`thread_Y`):**
```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For sleep

sem_t A;
sem_t B;

void* thread_X_corrected(void* arg) { // Renamed for clarity, logic is same as original thread_X
    printf("Thread X (Corrected): Trying to acquire semaphore A\n");
    sem_wait(&A);
    printf("Thread X (Corrected): Acquired semaphore A, trying to acquire B\n");
    sleep(1); // Simulate work or context switch
    sem_wait(&B);
    printf("Thread X (Corrected): Acquired both A and B\n");
    // Critical section
    printf("Thread X (Corrected): Releasing semaphores\n");
    sem_post(&B);
    sem_post(&A);
    return NULL;
}

void* thread_Y_corrected(void* arg) { // Corrected to acquire A then B
    printf("Thread Y (Corrected): Trying to acquire semaphore A\n"); // Changed order
    sem_wait(&A); // Always acquire A first
    printf("Thread Y (Corrected): Acquired semaphore A, trying to acquire B\n");
    sleep(1); // Simulate work or context switch
    sem_wait(&B);
    printf("Thread Y (Corrected): Acquired both A and B\n");
    // Critical section
    printf("Thread Y (Corrected): Releasing semaphores\n");
    sem_post(&B);
    sem_post(&A);
    return NULL;
}

int main() {
    sem_init(&A, 0, 1);
    sem_init(&B, 0, 1);

    pthread_t tid_x, tid_y;

    printf("Main: Creating corrected threads...\n");
    pthread_create(&tid_x, NULL, thread_X_corrected, NULL);
    pthread_create(&tid_y, NULL, thread_Y_corrected, NULL);

    pthread_join(tid_x, NULL);
    pthread_join(tid_y, NULL);

    sem_destroy(&A);
    sem_destroy(&B);

    printf("Main: Both corrected threads finished successfully\n");
    return 0;
}
```
**הסבר לפתרון המתוקן:**
על ידי אכיפת סדר רכישה אחיד (A ואז B) לכל התהליכונים, אנו מבטלים את התנאי של המתנה מעגלית, שהוא אחד מארבעת התנאים ההכרחיים לקיפאון. אם `thread_X` מחזיק ב-A וממתין ל-B, ו-`thread_Y` מנסה לרכוש את A, הוא יחסם ב-`sem_wait(&A)` עד ש-`thread_X` ישחרר את A (לאחר שסיים את כל המקטע הקריטי ושחרר את B ואז את A). כך, אף פעם לא ייווצר מצב שבו `thread_X` מחכה ל-B ו-`thread_Y` מחכה ל-A בו-זמנית.

