#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define BUFFER_SIZE 5
#define MAX_CONCURRENT_PRODUCTION 2 // מספר היצרנים המקסימלי שיכולים להיות בשלב יצירה והוספה

int buffer[BUFFER_SIZE];
int in = 0;
int out = 0;

sem_t mutex; // להגנה הדדית על גישה לחוצץ
sem_t full;  // סופר מקומות מלאים בחוצץ
sem_t empty; // סופר מקומות פנויים בחוצץ
sem_t production_limit; // מגביל יצרנים פעילים בו-זמנית

// מדמה יצירת פריט (למשל, עבודה חישובית)
int produce_item_sim() {
    // sleep(1); // לדמות עבודה
    return rand() % 100;
}

// מדמה צריכת פריט (למשל, עבודה חישובית)
void consume_item_sim(int item) {
    // sleep(1); // לדמות עבודה
    (void)item; // למנוע אזהרת משתנה שאינו בשימוש
}

void *producer(void *arg) {
    int item;
    for (int i = 0; i < 10; ++i) { // כל יצרן מייצר 10 פריטים
        // שלב 1: יצירת פריט והוספה לחוצץ, מוגבל ע"י production_limit
        sem_wait(&production_limit); // (1) רכישת production_limit

        item = produce_item_sim(); // יצירת הפריט

        sem_wait(&empty); // (2) המתנה למקום פנוי
        sem_wait(&mutex);  // (3) רכישת mutex לגישה לחוצץ

        // קטע קריטי: הוספת פריט לחוצץ
        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        printf("Producer %ld: Added item %d. Buffer state: full=%d\n", (long)arg, item, sem_getvalue(&full));

        sem_post(&mutex); // (4) שחרור mutex
        sem_post(&full);  // (5) איתות על מקום מלא

        sem_post(&production_limit); // (6) שחרור production_limit
    }
    return NULL;
}

void *consumer(void *arg) {
    int item;
    for (int i = 0; i < 10; ++i) { // כל צרכן צורך 10 פריטים
        sem_wait(&full);  // (7) המתנה למקום מלא
        sem_wait(&mutex);  // (8) רכישת mutex לגישה לחוצץ

        // קטע קריטי: הסרת פריט מהחוצץ
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        printf("Consumer %ld: Removed item %d. Buffer state: full=%d\n", (long)arg, item, sem_getvalue(&full));

        sem_post(&mutex);  // (9) שחרור mutex
        sem_post(&empty); // (10) איתות על מקום פנוי

        consume_item_sim(item); // צריכת הפריט (ניתן לעשות במקביל)
    }
    return NULL;
}

int main() {
    sem_init(&mutex, 0, 1);
    sem_init(&full, 0, 0);
    sem_init(&empty, 0, BUFFER_SIZE);
    sem_init(&production_limit, 0, MAX_CONCURRENT_PRODUCTION);

    pthread_t prod_threads[3], cons_threads[3];

    for (long i = 0; i < 3; ++i) {
        pthread_create(&prod_threads[i], NULL, producer, (void *)(i + 1));
        pthread_create(&cons_threads[i], NULL, consumer, (void *)(i + 1));
    }

    for (int i = 0; i < 3; ++i) {
        pthread_join(prod_threads[i], NULL);
        pthread_join(cons_threads[i], NULL);
    }

    sem_destroy(&mutex);
    sem_destroy(&full);
    sem_destroy(&empty);
    sem_destroy(&production_limit);

    return 0;
}

sem_t sem_A; // initialized to 1
sem_t sem_B; // initialized to 1
int shared_counter = 0;

void* thread_A_then_B(void* arg) {
    sem_wait(&sem_A);
    // Simulate some work or context switch
    // usleep(10000);
    sem_wait(&sem_B);

    // Critical section
    shared_counter++;

    sem_post(&sem_B);
    sem_post(&sem_A);
    return NULL;
}

void* thread_B_then_A(void* arg) {
    sem_wait(&sem_B);
    // Simulate some work or context switch
    // usleep(10000);
    sem_wait(&sem_A);

    // Critical section
    shared_counter++;

    sem_post(&sem_A);
    sem_post(&sem_B);
    return NULL;
}

solution.explanation:
כן, קטע הקוד הנתון יכול להוביל למצב של קיפאון (deadlock). קיפאון מתרחש כאשר שני חוטים או יותר ממתינים זה לזה באופן בלתי הפיך, כאשר כל אחד מהם מחזיק במשאב שהאחר זקוק לו וממתין למשאב המוחזק על ידי האחר.

**תרחיש קיפאון ספציפי:**
1.  **חוט `thread_A_then_B` רץ:** הוא מבצע `sem_wait(&sem_A)` ומצליח לתפוס את `sem_A`. בשלב זה, `sem_A` מוחזק על ידו ו-`sem_B` חופשי.
2.  **מתרחש מעבר הקשר (context switch) לחוט `thread_B_then_A`:**
3.  **חוט `thread_B_then_A` רץ:** הוא מבצע `sem_wait(&sem_B)` ומצליח לתפוס את `sem_B`. בשלב זה, `sem_B` מוחזק על ידו ו-`sem_A` מוחזק על ידי `thread_A_then_B`.
4.  **מתרחש מעבר הקשר בחזרה לחוט `thread_A_then_B`:**
5.  **חוט `thread_A_then_B` מנסה להמשיך:** הוא מנסה לבצע `sem_wait(&sem_B)`. אך `sem_B` מוחזק כעת על ידי `thread_B_then_A`, ולכן `thread_A_then_B` נכנס למצב המתנה על `sem_B`.
6.  **מתרחש מעבר הקשר בחזרה לחוט `thread_B_then_A`:**
7.  **חוט `thread_B_then_A` מנסה להמשיך:** הוא מנסה לבצע `sem_wait(&sem_A)`. אך `sem_A` מוחזק כעת על ידי `thread_A_then_B`, ולכן `thread_B_then_A` נכנס למצב המתנה על `sem_A`.

בנקודה זו, שני החוטים נמצאים במצב המתנה הדדית: `thread_A_then_B` ממתין ל-`sem_B` המוחזק על ידי `thread_B_then_A`, ו-`thread_B_then_A` ממתין ל-`sem_A` המוחזק על ידי `thread_A_then_B`. אף אחד מהם לא יכול להמשיך, והמערכת נכנסת לקיפאון.

**פתרון למניעת קיפאון (שינוי מינימלי):**
כדי למנוע קיפאון במצב כזה, יש להבטיח שכל החוטים תופסים את המשאבים באותו סדר. שינוי זה מונע את התנאי של 'המתנה מעגלית' (Circular Wait), שהוא אחד מארבעת התנאים ההכרחיים לקיפאון (על פי תנאי קופמן). לדוגמה, נוכל לשנות את `thread_B_then_A` כך שתתפוס את `sem_A` לפני `sem_B`.

**קוד מתוקן (שינוי ב-`thread_B_then_A`):**
```c
sem_t sem_A; // initialized to 1
sem_t sem_B; // initialized to 1
int shared_counter = 0;

void* thread_A_then_B(void* arg) {
    sem_wait(&sem_A);
    // usleep(10000);
    sem_wait(&sem_B);

    shared_counter++;

    sem_post(&sem_B);
    sem_post(&sem_A);
    return NULL;
}

void* thread_B_then_A(void* arg) {
    sem_wait(&sem_A); // שינוי: תופסים את sem_A קודם
    // usleep(10000);
    sem_wait(&sem_B); // ואז את sem_B

    shared_counter++;

    sem_post(&sem_B);
    sem_post(&sem_A); // משחררים בסדר הפוך: B ואז A
    return NULL;
}
```

**הסבר מדוע הפתרון מונע קיפאון:**
על ידי אכיפת סדר תפיסת משאבים אחיד (תמיד קודם `sem_A` ואז `sem_B`) עבור כל החוטים שצריכים את שני המשאבים, אנו מבטלים את האפשרות ל'המתנה מעגלית'. אם חוט אחד תפס את `sem_A` וממתין ל-`sem_B`, החוט השני לא יוכל לתפוס את `sem_B` לפני שהוא תפס את `sem_A` (אשר אולי כבר מוחזק על ידי החוט הראשון). במקרה כזה, החוט השני פשוט ימתין ל-`sem_A` עד שיתפנה, ולא יוכל לתפוס את `sem_B` ולגרום להמתנה מעגלית. כאשר `sem_A` ישוחרר, החוט השני יוכל לתפוס אותו, ואז לתפוס את `sem_B` (אשר יהיה זמין ברגע שהחוט הראשון ישחרר אותו), וכך שניהם יוכלו להשלים את פעולתם ללא קיפאון.

