pthread_mutex_t mutex_resA = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex_resB = PTHREAD_MUTEX_INITIALIZER;

// Function to simulate a process acquiring resources
void* acquire_resources(void* arg) {
    long thread_id = (long)arg;
    int first_res_id = (thread_id == 0) ? 0 : 1; // Thread 0 tries A then B, Thread 1 tries B then A
    int second_res_id = (thread_id == 0) ? 1 : 0;

    pthread_mutex_t* first_mutex = (first_res_id == 0) ? &mutex_resA : &mutex_resB;
    pthread_mutex_t* second_mutex = (second_res_id == 0) ? &mutex_resA : &mutex_resB;

    printf("Thread %ld trying to acquire mutex %d\n", thread_id, first_res_id);
    pthread_mutex_lock(first_mutex);
    printf("Thread %ld acquired mutex %d\n", thread_id, first_res_id);

    sleep(1); // Simulate some work/hold time

    printf("Thread %ld trying to acquire mutex %d\n", thread_id, second_res_id);
    while (pthread_mutex_trylock(second_mutex) != 0) {
        printf("Thread %ld failed to acquire mutex %d, releasing mutex %d and retrying...\n", thread_id, second_res_id, first_res_id);
        pthread_mutex_unlock(first_mutex);
        sleep(1); // Wait a bit before retrying
        pthread_mutex_lock(first_mutex);
        printf("Thread %ld re-acquired mutex %d\n", thread_id, first_res_id);
    }
    printf("Thread %ld acquired mutex %d\n", thread_id, second_res_id);

    // Critical section
    printf("Thread %ld in critical section with both mutexes\n", thread_id);
    sleep(1);

    pthread_mutex_unlock(second_mutex);
    pthread_mutex_unlock(first_mutex);
    printf("Thread %ld released both mutexes and finished\n", thread_id);
    return NULL;
}

int main() {
    pthread_t t0, t1;
    pthread_create(&t0, NULL, acquire_resources, (void*)0);
    pthread_create(&t1, NULL, acquire_resources, (void*)1);

    pthread_join(t0, NULL);
    pthread_join(t1, NULL);

    printf("Main: All threads completed.\n");
    return 0;
}

