    pthread_mutex_lock(&mutex_B);
    printf("Thread 1: Acquired Mutex B. Performing operation...\n");
    // Critical section
    printf("Thread 1: Releasing Mutex B...\n");
    pthread_mutex_unlock(&mutex_B);
    printf("Thread 1: Releasing Mutex A...\n");
    pthread_mutex_unlock(&mutex_A);
