pthread_mutex_t mutexA;
pthread_mutex_t mutexB;

void transfer_A_to_B() {
    pthread_mutex_lock(&mutexA);
    printf("Thread %lu acquired mutexA in A_to_B.\n", pthread_self());
    // Simulate work or data transfer
    sleep(1);
    pthread_mutex_lock(&mutexB);
    printf("Thread %lu acquired mutexB in A_to_B.\n", pthread_self());
    // Perform data transfer from A to B
    printf("Thread %lu performing A_to_B transfer.\n", pthread_self());
    pthread_mutex_unlock(&mutexB);
    pthread_mutex_unlock(&mutexA);
    printf("Thread %lu released both mutexes in A_to_B.\n", pthread_self());
}

void transfer_B_to_A() {
    pthread_mutex_lock(&mutexB);
    printf("Thread %lu acquired mutexB in B_to_A.\n", pthread_self());
    // Simulate work or data transfer
    sleep(1);
    pthread_mutex_lock(&mutexA);
    printf("Thread %lu acquired mutexA in B_to_A.\n", pthread_self());
    // Perform data transfer from B to A
    printf("Thread %lu performing B_to_A transfer.\n", pthread_self());
    pthread_mutex_unlock(&mutexA);
    pthread_mutex_unlock(&mutexB);
    printf("Thread %lu released both mutexes in B_to_A.\n", pthread_self());
}

/* Example main function to demonstrate:
int main() {
    pthread_mutex_init(&mutexA, NULL);
    pthread_mutex_init(&mutexB, NULL);
    pthread_t t1, t2;
    pthread_create(&t1, NULL, (void*(*)(void*))transfer_A_to_B, NULL);
    pthread_create(&t2, NULL, (void*(*)(void*))transfer_B_to_A, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    pthread_mutex_destroy(&mutexA);
    pthread_mutex_destroy(&mutexB);
    return 0;
