#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <map>
#include <chrono>

// Assume Account IDs are integers
std::map<int, std::mutex> account_locks;
std::map<int, double> account_balances;

// Initialize accounts (for example purposes)
void init_accounts(int num_accounts) {
    for (int i = 0; i < num_accounts; ++i) {
        account_locks[i]; // Default constructs mutex for each account ID
        account_balances[i] = 100.0;
    }
}

// Transaction function
void transfer(int from_account_id, int to_account_id, double amount) {
    // Simulate some work before locking
    std::this_thread::sleep_for(std::chrono::milliseconds(10));

    std::cout << "Thread " << std::this_thread::get_id() << ": Trying to lock " << from_account_id << " and " << to_account_id << std::endl;

    // Acquire locks for the source and destination accounts
    account_locks[from_account_id].lock();
    account_locks[to_account_id].lock();

    // Check for sufficient balance and perform transfer
    if (account_balances[from_account_id] >= amount) {
        account_balances[from_account_id] -= amount;
        account_balances[to_account_id] += amount;
        std::cout << "Thread " << std::this_thread::get_id() << ": Transferred " << amount
                  << " from " << from_account_id << " to " << to_account_id << std::endl;
    } else {
        std::cout << "Thread " << std::this_thread::get_id() << ": Insufficient balance in "
                  << from_account_id << " to transfer " << amount << std::endl;
    }

    // Release locks
    account_locks[to_account_id].unlock();
    account_locks[from_account_id].unlock();
}

int main() {
    init_accounts(3); // Initialize accounts 0, 1, 2

    // Create multiple threads attempting transfers
    // This specific combination is designed to demonstrate deadlock potential
    std::thread t1(transfer, 0, 1, 10.0);
    std::thread t2(transfer, 1, 0, 20.0);
    std::thread t3(transfer, 0, 2, 5.0);
    std::thread t4(transfer, 2, 0, 15.0);

    t1.join();
    t2.join();
    t3.join();
    t4.join();

    std::cout << "\nFinal Balances:" << std::endl;
    for (int i = 0; i < 3; ++i) {
        std::cout << "Account " << i << ": " << account_balances[i] << std::endl;
    }

    return 0;
}

solution.explanation:
### פתרון סעיף א' - זיהוי דדלוק

**כן, בקוד הנתון קיים פוטנציאל לדדלוק.**

**תיאור מצב ספציפי לדדלוק:**
נניח ששני חוטים, T1 ו-T2, מבצעים טרנזקציות בו-זמנית:
*   חוט T1 קורא ל-`transfer(0, 1, 10.0)` (מעביר מחשבון 0 לחשבון 1).
*   חוט T2 קורא ל-`transfer(1, 0, 20.0)` (מעביר מחשבון 1 לחשבון 0).

התרחיש שיוביל לדדלוק הוא כדלקמן:
1.  חוט T1 מבצע `account_locks[0].lock()` ותופס את המנעול של חשבון 0.
2.  חוט T2 מבצע `account_locks[1].lock()` ותופס את המנעול של חשבון 1.
3.  חוט T1 מנסה לבצע `account_locks[1].lock()` אך המנעול תפוס על ידי T2. T1 נכנס למצב המתנה.
4.  חוט T2 מנסה לבצע `account_locks[0].lock()` אך המנעול תפוס על ידי T1. T2 נכנס למצב המתנה.

במצב זה, T1 מחזיק במנעול ש-T2 זקוק לו, ו-T2 מחזיק במנעול ש-T1 זקוק לו. שני החוטים ממתינים זה לזה לנצח, ולכן מתרחש דדלוק.

**הסבר על בסיס ארבעת התנאים ההכרחיים לדדלוק:**
1.  **מניעה הדדית (Mutual Exclusion):** כל מנעול (mutex) של חשבון יכול להיות מוחזק על ידי חוט אחד בלבד בכל רגע נתון. זה מתקיים בקוד כי `std::mutex` הוא אובייקט סנכרון בלעדי.
2.  **החזק והמתן (Hold and Wait):** חוטים מחזיקים במשאב אחד (מנעול של חשבון) וממתינים למשאב נוסף שתפוס על ידי חוט אחר. בדוגמה לעיל, T1 מחזיק את מנעול 0 וממתין למנעול 1, ו-T2 מחזיק את מנעול 1 וממתין למנעול 0.
3.  **אי-הפקעה (No Preemption):** משאבים (מנעולים) אינם ניתנים להפקעה בכוח מחוט שמחזיק בהם. חוט חייב לשחרר אותם מרצונו. זה מתקיים עם `std::mutex`.
4.  **המתנה מעגלית (Circular Wait):** קיימת שרשרת של חוטים, שבה כל חוט ממתין למשאב שמוחזק על ידי החוט הבא בשרשרת, והחוט האחרון ממתין למשאב שמוחזק על ידי החוט הראשון. בדוגמה שלנו, T1 ממתין ל-T2, ו-T2 ממתין ל-T1, ויוצרים מעגל המתנה.

### פתרון סעיף ב' - מניעת דדלוק

כדי למנוע דדלוק, ניתן להטיל סדר גלובלי על רכישת המשאבים (המנעולים). במקרה זה, נגדיר כי יש לרכוש תמיד את המנעול של החשבון בעל המזהה הקטן יותר, ורק לאחר מכן את המנעול של החשבון בעל המזהה הגדול יותר. זה מבטל את תנאי ה'המתנה מעגלית'.

**קוד `transfer` מתוקן:**
```c++
void transfer(int from_account_id, int to_account_id, double amount) {
    std::this_thread::sleep_for(std::chrono::milliseconds(10));

    // קביעת סדר נעילה עקבי על בסיס מזהי החשבונות
    // תמיד ננעל קודם את המזהה הקטן יותר, ואז את הגדול יותר
    std::mutex& lock1 = (from_account_id < to_account_id) ? account_locks[from_account_id] : account_locks[to_account_id];
    std::mutex& lock2 = (from_account_id < to_account_id) ? account_locks[to_account_id] : account_locks[from_account_id];

    int first_id = (from_account_id < to_account_id) ? from_account_id : to_account_id;
    int second_id = (from_account_id < to_account_id) ? to_account_id : from_account_id;

    std::cout << "Thread " << std::this_thread::get_id() << ": Trying to lock " << first_id << " then " << second_id << std::endl;

    // רכישת המנעולים בסדר קבוע
    lock1.lock();
    lock2.lock();

    // לאחר הנעילה, נשמור על ההתייחסות המקורית לחשבונות המקור והיעד
    double* actual_from_balance = &account_balances[from_account_id];
    double* actual_to_balance = &account_balances[to_account_id];

    // בדיקת יתרה מספקת וביצוע ההעברה
    if (*actual_from_balance >= amount) {
        *actual_from_balance -= amount;
        *actual_to_balance += amount;
        std::cout << "Thread " << std::this_thread::get_id() << ": Transferred " << amount
                  << " from " << from_account_id << " to " << to_account_id << std::endl;
    } else {
        std::cout << "Thread " << std::this_thread::get_id() << ": Insufficient balance in "
                  << from_account_id << " to transfer " << amount << std::endl;
    }

    // שחרור המנעולים בסדר הפוך לסדר הרכישה (פרקטיקה מומלצת)
    lock2.unlock();
    lock1.unlock();
}
```

**הסבר מדוע השינוי מונע דדלוק:**
השינוי מבטל את תנאי ה'המתנה מעגלית' (Circular Wait). על ידי הטלת סדר גלובלי ועקבי לרכישת מנעולים (תמיד קודם המנעול של החשבון בעל המזהה הקטן יותר, ואז את המנעול של החשבון בעל המזהה הגדול יותר), אנו מבטיחים שלעולם לא תיווצר שרשרת המתנה מעגלית. אם חוט T1 מנסה להעביר מ-0 ל-1, וחוט T2 מנסה להעביר מ-1 ל-0, שניהם ינסו לרכוש קודם את המנעול של חשבון 0 (מכיוון ש-0 < 1). החוט שיצליח לתפוס את מנעול 0 ראשון, ימשיך לנסות לתפוס את מנעול 1. החוט השני ימתין למנעול 0. במצב זה, תמיד אחד החוטים יתקדם, ולא ייתכן מצב שבו כל חוט מחזיק במשאב שחוט אחר זקוק לו, ובו בזמן ממתין למשאב שמוחזק על ידי אותו חוט אחר, בסבב מעגלי.

