#include <stdio.h>
#include <pthread.h>
#include <unistd.h> // For sleep

pthread_mutex_t mutex_X;
pthread_mutex_t mutex_Y;

void* thread_A_func(void* arg) {
    printf("Thread A: Attempting to lock mutex_X...\n");
    pthread_mutex_lock(&mutex_X);
    printf("Thread A: Locked mutex_X. Sleeping...\n");
    sleep(1); // Simulate work or delay

    printf("Thread A: Attempting to lock mutex_Y...\n");
    pthread_mutex_lock(&mutex_Y);
    printf("Thread A: Locked mutex_Y. Critical section A...\n");

    // Critical section A
    printf("Thread A: Releasing mutex_Y...\n");
    pthread_mutex_unlock(&mutex_Y);
    printf("Thread A: Releasing mutex_X...\n");
    pthread_mutex_unlock(&mutex_X);
    printf("Thread A: Exiting.\n");
    return NULL;
}

void* thread_B_func(void* arg) {
    printf("Thread B: Attempting to lock mutex_Y...\n");
    pthread_mutex_lock(&mutex_Y);
    printf("Thread B: Locked mutex_Y. Sleeping...\n");
    sleep(1); // Simulate work or delay

    printf("Thread B: Attempting to lock mutex_X...\n");
    pthread_mutex_lock(&mutex_X);
    printf("Thread B: Locked mutex_X. Critical section B...\n");

    // Critical section B
    printf("Thread B: Releasing mutex_X...\n");
    pthread_mutex_unlock(&mutex_X);
    printf("Thread B: Releasing mutex_Y...\n");
    pthread_mutex_unlock(&mutex_Y);
    printf("Thread B: Exiting.\n");
    return NULL;
}

int main() {
    pthread_t thread_A, thread_B;

    pthread_mutex_init(&mutex_X, NULL);
    pthread_mutex_init(&mutex_Y, NULL);

    pthread_create(&thread_A, NULL, thread_A_func, NULL);
    pthread_create(&thread_B, NULL, thread_B_func, NULL);

    pthread_join(thread_A, NULL);
    pthread_join(thread_B, NULL);

    pthread_mutex_destroy(&mutex_X);
    pthread_mutex_destroy(&mutex_Y);

    printf("Main: Program finished.\n");
    return 0;
}

solution.explanation:
כן, קטע קוד זה יכול להוביל למצב של קיפאון (deadlock). קיפאון הוא מצב שבו שני חוטים או יותר ממתינים זה לזה באופן בלתי הפיך למשאבים שהם צריכים כדי להמשיך.

במקרה זה, התנאים לקיפאון מתקיימים:
1.  **מניעה הדדית (Mutual Exclusion)**: המנעולים (mutex_X, mutex_Y) מבטיחים שרק חוט אחד יכול להחזיק במשאב (המנעול) בכל רגע נתון.
2.  **החזקה והמתנה (Hold and Wait)**: חוט A מחזיק במנעול X וממתין למנעול Y. במקביל, חוט B מחזיק במנעול Y וממתין למנעול X.
3.  **אין שחרור מוקדם (No Preemption)**: אף חוט לא יכול לקחת בכוח מנעול מחוט אחר. המנעולים משוחררים רק על ידי החוט שתפס אותם.
4.  **המתנה מעגלית (Circular Wait)**: קיים מעגל המתנה: חוט A ממתין למנעול Y שמוחזק על ידי חוט B, וחוט B ממתין למנעול X שמוחזק על ידי חוט A.

**תרחיש לדוגמה לקיפאון:**
1.  חוט A נועל את `mutex_X`.
2.  חוט B נועל את `mutex_Y`.
3.  חוט A מנסה לנעול את `mutex_Y` אך הוא תפוס על ידי חוט B, ולכן חוט A נחסם וממתין.
4.  חוט B מנסה לנעול את `mutex_X` אך הוא תפוס על ידי חוט A, ולכן חוט B נחסם וממתין.
במצב זה, שני החוטים חסומים באופן הדדי, וכל אחד מהם מחזיק במשאב שהשני זקוק לו, וכך נוצר קיפאון.

**מניעת קיפאון:**
הדרך הנפוצה ביותר למנוע קיפאון במקרה זה היא על ידי אכיפת סדר קבוע ללקיחת המנעולים. אם כל החוטים ינסו לתפוס את המנעולים באותו סדר (לדוגמה, תמיד קודם `mutex_X` ואז `mutex_Y`), אזי תנאי ההמתנה המעגלית לא יכול להתקיים.

**תיקון הקוד:**
יש לשנות את הפונקציה `thread_B_func` כך שתנסה לנעול את `mutex_X` לפני `mutex_Y`, בדיוק כמו `thread_A_func`.

**קוד מתוקן לדוגמה עבור `thread_B_func`:**
```c
void* thread_B_func(void* arg) {
    printf("Thread B: Attempting to lock mutex_X...\n");
    pthread_mutex_lock(&mutex_X); // סדר המנעולים שונה
    printf("Thread B: Locked mutex_X. Sleeping...\n");
    sleep(1);

    printf("Thread B: Attempting to lock mutex_Y...\n");
    pthread_mutex_lock(&mutex_Y); // סדר המנעולים שונה
    printf("Thread B: Locked mutex_Y. Critical section B...\n");

    printf("Thread B: Releasing mutex_Y...\n");
    pthread_mutex_unlock(&mutex_Y);
    printf("Thread B: Releasing mutex_X...\n");
    pthread_mutex_unlock(&mutex_X);
    printf("Thread B: Exiting.\n");
    return NULL;
}
```

