    pthread_mutex_lock(&mutexA);
    printf("Thread 1: Acquired mutexA. Waiting a bit...\n");
    sleep(1); // Simulate work or context switch
    printf("Thread 1: Trying to acquire mutexB...\n");
    pthread_mutex_lock(&mutexB);
    printf("Thread 1: Acquired mutexB. Doing work...\n");
    // Critical section
    printf("Thread 1: Releasing mutexB...\n");
    pthread_mutex_unlock(&mutexB);
    printf("Thread 1: Releasing mutexA...\n");
    pthread_mutex_unlock(&mutexA);
    printf("Thread 1: Finished.\n");
    return NULL;
}

void* thread_func2(void* arg) {
    printf("Thread 2: Trying to acquire mutexB...\n");
    pthread_mutex_lock(&mutexB);
    printf("Thread 2: Acquired mutexB. Waiting a bit...\n");
    sleep(1); // Simulate work or context switch
    printf("Thread 2: Trying to acquire mutexA...\n");
    pthread_mutex_lock(&mutexA);
    printf("Thread 2: Acquired mutexA. Doing work...\n");
    // Critical section
    printf("Thread 2: Releasing mutexA...\n");
    pthread_mutex_unlock(&mutexA);
    printf("Thread 2: Releasing mutexB...\n");
    pthread_mutex_unlock(&mutexB);
    printf("Thread 2: Finished.\n");
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_mutex_init(&mutexA, NULL);
    pthread_mutex_init(&mutexB, NULL);

    pthread_create(&tid1, NULL, thread_func1, NULL);
    pthread_create(&tid2, NULL, thread_func2, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    pthread_mutex_destroy(&mutexA);
    pthread_mutex_destroy(&mutexB);

    printf("Main: All threads finished.\n");
    return 0;
}

solution.explanation:
כן, קיפאון (deadlock) יכול להתרחש בקטע קוד זה.

**מדוע קיפאון יכול להתרחש:**
הקיפאון מתרחש עקב תנאי 'המתנה מעגלית' (Circular Wait) בשילוב עם שלושת התנאים הנוספים לקיפאון:
1.  **מניעה הדדית (Mutual Exclusion):** המנעולים (mutexA ו-mutexB) מבטיחים שרק חוט אחד יכול להחזיק בהם בכל רגע נתון.
2.  **החזקה והמתנה (Hold and Wait):**
    *   חוט 1 תופס את `mutexA` ולאחר מכן מנסה לתפוס את `mutexB`. אם `mutexB` מוחזק על ידי חוט 2, חוט 1 ימתין תוך כדי שהוא מחזיק ב-`mutexA`.
    *   חוט 2 תופס את `mutexB` ולאחר מכן מנסה לתפוס את `mutexA`. אם `mutexA` מוחזק על ידי חוט 1, חוט 2 ימתין תוך כדי שהוא מחזיק ב-`mutexB`.
3.  **אי-הפקעה (No Preemption):** חוט אינו יכול להפקיע מנעול מחוט אחר; המנעול ישוחרר רק על ידי החוט שתפס אותו.
4.  **המתנה מעגלית (Circular Wait):** זהו התנאי המרכזי שגורם לקיפאון במקרה זה. חוט 1 ממתין למשאב (`mutexB`) שמוחזק על ידי חוט 2, בעוד חוט 2 ממתין למשאב (`mutexA`) שמוחזק על ידי חוט 1. נוצר מעגל המתנה שבו אף חוט אינו יכול להתקדם.

**כיצד ניתן למנוע קיפאון:**
הדרך הנפוצה והפשוטה ביותר למנוע קיפאון במקרה זה היא על ידי אכיפת סדר עקבי וקבוע לרכישת המשאבים (המנעולים). אם כל החוטים ינסו לתפוס את המנעולים באותו סדר, תנאי ההמתנה המעגלית יישבר.

**שינוי קוד מינימלי:**
יש לשנות את הפונקציה `thread_func2` כך שתתפוס את `mutexA` לפני `mutexB`, בדומה ל-`thread_func1`.

```c
