    pthread_mutex_lock(&mutex1);
    printf("Thread 1: Locked mutex1. Trying to lock mutex2...\n");
    pthread_mutex_lock(&mutex2);
    printf("Thread 1: Locked mutex2. Critical section...\n");
    pthread_mutex_unlock(&mutex2);
    pthread_mutex_unlock(&mutex1);
    printf("Thread 1: Unlocked mutexes.\n");
    return NULL;
}

void* thread_func2(void* arg) {
    printf("Thread 2: Trying to lock mutex1...\n"); // Changed order
    pthread_mutex_lock(&mutex1);
    printf("Thread 2: Locked mutex1. Trying to lock mutex2...\n"); // Changed order
    pthread_mutex_lock(&mutex2);
    printf("Thread 2: Locked mutex2. Critical section...\n");
    pthread_mutex_unlock(&mutex2); // Unlocked in correct order
    pthread_mutex_unlock(&mutex1); // Unlocked in correct order
    printf("Thread 2: Unlocked mutexes.\n");
    return NULL;
}
```

