#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For sleep

#define NUM_UNITS 5 // N

pthread_mutex_t units_mutex[NUM_UNITS];

void* worker_thread(void* arg) {
    int id = *(int*)arg;
    int unit1 = id;
    int unit2 = (id + 1) % NUM_UNITS;

    printf("Thread %d trying to acquire unit %d and unit %d\n", id, unit1, unit2);

    pthread_mutex_lock(&units_mutex[unit1]);
    printf("Thread %d acquired unit %d\n", id, unit1);

    // Simulate some work or contention
    usleep(10000); // 10ms

    pthread_mutex_lock(&units_mutex[unit2]);
    printf("Thread %d acquired unit %d and unit %d\n", id, unit1, unit2);

    // Simulate work in critical section
    printf("Thread %d working with units %d and %d\n", id, unit1, unit2);
    usleep(50000); // 50ms

    pthread_mutex_unlock(&units_mutex[unit2]);
    printf("Thread %d released unit %d\n", id, unit2);

    pthread_mutex_unlock(&units_mutex[unit1]);
    printf("Thread %d released unit %d\n", id, unit1);

    free(arg);
    return NULL;
}

int main() {
    pthread_t threads[NUM_UNITS];
    int* thread_ids[NUM_UNITS];

    for (int i = 0; i < NUM_UNITS; ++i) {
        pthread_mutex_init(&units_mutex[i], NULL);
    }

    for (int i = 0; i < NUM_UNITS; ++i) {
        thread_ids[i] = (int*)malloc(sizeof(int));
        *thread_ids[i] = i;
        pthread_create(&threads[i], NULL, worker_thread, thread_ids[i]);
    }

    for (int i = 0; i < NUM_UNITS; ++i) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < NUM_UNITS; ++i) {
        pthread_mutex_destroy(&units_mutex[i]);
    }

    printf("All threads finished.\n");
    return 0;
}

solution.explanation:
1.1: כן, הקוד הנתון עלול לסבול מקיפאון. תרחיש קיפאון קלאסי יכול להתרחש כאשר כל החוטים מתחילים לפעול בערך באותו זמן ומנסים לרכוש את המנעולים שלהם.

הקיפאון מתרחש מכיוון שמתקיימים ארבעת התנאים ההכרחיים לקיפאון:
1.  **מניעה הדדית (Mutual Exclusion):** כל מנעול (`units_mutex[i]`) מגן על יחידת עיבוד אחת וניתן להחזיק בו על ידי חוט אחד בלבד בכל רגע נתון.
2.  **החזק והמתן (Hold and Wait):** כל חוט רוכש את המנעול הראשון שלו (`units_mutex[id]`) ומחזיק בו, ואז מנסה לרכוש את המנעול השני (`units_mutex[(id+1)%NUM_UNITS]`). בזמן שהוא ממתין למנעול השני, הוא ממשיך להחזיק במנעול הראשון.
3.  **אין דריסה (No Preemption):** מנעולים אינם ניתנים לדריסה. ברגע שחוט רוכש מנעול, הוא יכול לשחרר אותו רק מרצונו.
4.  **המתנה מעגלית (Circular Wait):** זהו התנאי הקריטי ביותר במקרה זה. אם כל `NUM_UNITS` החוטים יתחילו בו זמנית, כל חוט `id` ירכוש את `units_mutex[id]`. לאחר מכן, חוט `id` ינסה לרכוש את `units_mutex[(id+1)%NUM_UNITS]`, אשר מוחזק על ידי חוט `(id+1)%NUM_UNITS`. כך נוצרת שרשרת המתנה מעגלית: חוט 0 ממתין למנעול 1 (שמוחזק על ידי חוט 1), חוט 1 ממתין למנעול 2 (שמוחזק על ידי חוט 2), וכן הלאה, עד שחוט `NUM_UNITS-1` ממתין למנעול 0 (שמוחזק על ידי חוט 0). כתוצאה מכך, אף חוט לא יכול להתקדם, וכל המערכת נכנסת לקיפאון.

1.2: כדי למנוע קיפאון, יש לשבור את תנאי ההמתנה המעגלית. הדרך הנפוצה והיעילה ביותר לעשות זאת במקרה זה, תוך שימוש במשאבים הקיימים בלבד, היא על ידי אכיפת סדר רכישת משאבים (Resource Ordering).
הרעיון הוא להגדיר סדר גלובלי למנעולים ולדרוש מכל החוטים לרכוש אותם לפי סדר זה. במקרה שלנו, נבצע רכישה תמיד מהמנעול בעל האינדקס הנמוך יותר למנעול בעל האינדקס הגבוה יותר.

עבור חוט `id` המבקש את יחידות `unit1_idx = id` ו-`unit2_idx = (id + 1) % NUM_UNITS`:
1.  אם `unit1_idx < unit2_idx` (לדוגמה, חוט 0 רוצה יחידות 0 ו-1), החוט ירכוש קודם את `units_mutex[unit1_idx]` ואז את `units_mutex[unit2_idx]`.
2.  אם `unit1_idx > unit2_idx` (המקרה המיוחד של חוט `NUM_UNITS-1` שרוצה יחידות `NUM_UNITS-1` ו-0), החוט ירכוש קודם את `units_mutex[unit2_idx]` (שהוא 0) ואז את `units_mutex[unit1_idx]` (שהוא `NUM_UNITS-1`).

יישום זה מבטיח שאין המתנה מעגלית. אף חוט לא ימתין למשאב שמוחזק על ידי חוט אחר שימתין בעצמו למשאב שמוחזק על ידי החוט הראשון, מכיוון שסדר הרכישה גלובלי ומונע יצירת מעגל. לדוגמה, חוט `NUM_UNITS-1` לא ימתין למשאב 0 שמוחזק על ידי חוט 0, בעוד שחוט 0 ממתין למשאב 1. במקום זאת, חוט `NUM_UNITS-1` ינסה לרכוש קודם את משאב 0 (שמוחזק על ידי חוט 0), יחסם וימתין, בעוד שחוט 0 ירכוש את משאב 0 ולאחר מכן את משאב 1. הסדר המוגדר מראש מבטיח שכל חוט יצליח בסופו של דבר לרכוש את שני המנעולים שלו.

הקוד המעודכן עבור `worker_thread`:
```c
void* worker_thread(void* arg) {
    int id = *(int*)arg;
    int unit1_idx = id;
    int unit2_idx = (id + 1) % NUM_UNITS;

    int first_lock_idx, second_lock_idx;

    if (unit1_idx < unit2_idx) { 
        first_lock_idx = unit1_idx;
        second_lock_idx = unit2_idx;
    } else { // Handles the case where unit1_idx is NUM_UNITS-1 and unit2_idx is 0
        first_lock_idx = unit2_idx; 
        second_lock_idx = unit1_idx;
    }

    printf("Thread %d trying to acquire unit %d and unit %d (ordered: %d then %d)\n", id, unit1_idx, unit2_idx, first_lock_idx, second_lock_idx);

    pthread_mutex_lock(&units_mutex[first_lock_idx]);
    printf("Thread %d acquired unit %d\n", id, first_lock_idx);

    usleep(10000); // 10ms

    pthread_mutex_lock(&units_mutex[second_lock_idx]);
    printf("Thread %d acquired unit %d and unit %d (original: %d and %d)\n", id, first_lock_idx, second_lock_idx, unit1_idx, unit2_idx);

    printf("Thread %d working with units %d and %d\n", id, unit1_idx, unit2_idx);
    usleep(50000); // 50ms

    pthread_mutex_unlock(&units_mutex[second_lock_idx]);
    printf("Thread %d released unit %d\n", id, second_lock_idx);

    pthread_mutex_unlock(&units_mutex[first_lock_idx]);
    printf("Thread %d released unit %d\n", id, first_lock_idx);

    free(arg);
    return NULL;
}
```

