#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For usleep

// Define a BankAccount structure
typedef struct {
    int id;
    long balance;
    pthread_mutex_t mutex;
} BankAccount;

// Function to initialize a bank account
void init_account(BankAccount* account, int id, long initial_balance) {
    account->id = id;
    account->balance = initial_balance;
    pthread_mutex_init(&account->mutex, NULL);
}

// Function to destroy a bank account
void destroy_account(BankAccount* account) {
    pthread_mutex_destroy(&account->mutex);
}

// Function to transfer money between two accounts (BUGGY VERSION)
void transfer_money(BankAccount* source, BankAccount* destination, long amount) {
    if (source == destination) {
        return; // Cannot transfer to self
    }

    // Acquire locks in a potentially problematic order
    pthread_mutex_lock(&source->mutex);
    printf("Thread %lu locked account %d (source)\n", pthread_self(), source->id);

    // Simulate some work or delay to increase deadlock probability
    usleep(10000); // 10ms delay

    pthread_mutex_lock(&destination->mutex);
    printf("Thread %lu locked account %d (destination)\n", pthread_self(), destination->id);

    if (source->balance >= amount) {
        source->balance -= amount;
        destination->balance += amount;
        printf("Transfer %ld from %d to %d successful. Balances: %d=%ld, %d=%ld\n", 
               amount, source->id, destination->id, source->id, source->balance, destination->id, destination->balance);
    } else {
        printf("Transfer %ld from %d to %d failed: insufficient funds.\n", amount, source->id, destination->id);
    }

    pthread_mutex_unlock(&destination->mutex);
    printf("Thread %lu unlocked account %d (destination)\n", pthread_self(), destination->id);
    pthread_mutex_unlock(&source->mutex);
    printf("Thread %lu unlocked account %d (source)\n", pthread_self(), source->id);
}

solution.explanation:
כן, קיימת אפשרות לקיפאון (Deadlock) במימוש הנוכחי של transfer_money.

**תרחיש הקיפאון:**
נניח שני חוטים, Thread 1 ו-Thread 2, ושני חשבונות, Account A ו-Account B.
*   Thread 1 מנסה להעביר כסף מ-Account A ל-Account B (קורא ל-transfer_money(A, B, amount1)).
*   Thread 2 מנסה להעביר כסף מ-Account B ל-Account A (קורא ל-transfer_money(B, A, amount2)).

**השתלשלות אירועים אפשרית לקיפאון:**
1.  Thread 1 נועל את mutex של Account A.
2.  Thread 2 נועל את mutex של Account B.
3.  Thread 1 מנסה כעת לנעול את mutex של Account B, אך הוא כבר נעול על ידי Thread 2. Thread 1 נחסם וממתין.
4.  Thread 2 מנסה כעת לנעול את mutex של Account A, אך הוא כבר נעול על ידי Thread 1. Thread 2 נחסם וממתין.

בשלב זה, שני החוטים חסומים וממתינים זה לזה לשחרור המשאב שהם צריכים, ונוצר קיפאון.

**תנאי הקיפאון המתקיימים:**
*   **מניעה הדדית (Mutual Exclusion):** כל מנעול (mutex) יכול להיות מוחזק על ידי חוט אחד בלבד בכל רגע נתון.
*   **החזקה והמתנה (Hold and Wait):** כל חוט מחזיק במנעול אחד (למשל, Thread 1 מחזיק ב-mutex של Account A) וממתין למנעול נוסף (למשל, Thread 1 ממתין ל-mutex של Account B).
*   **אי-הפקעה (No Preemption):** מנעול שהוחזק על ידי חוט לא יכול להילקח ממנו בכוח; הוא חייב לשחרר אותו מרצונו.
*   **המתנה מעגלית (Circular Wait):** קיים מעגל של חוטים, כאשר כל חוט במעגל ממתין למשאב המוחזק על ידי החוט הבא במעגל. בתרחיש לעיל, Thread 1 ממתין ל-mutex של Account B שמוחזק על ידי Thread 2, ו-Thread 2 ממתין ל-mutex של Account A שמוחזק על ידי Thread 1.

**פתרון מוצע:**
כדי למנוע קיפאון במקרה של צורך בנעילת מספר משאבים, הגישה הנפוצה היא להבטיח שכל החוטים ירכשו את המשאבים באותו סדר קבוע (Global Ordering). במקרה זה, ניתן להחליט על סדר רכישת מנעולים לפי כתובות הזיכרון של אובייקטי BankAccount, או לפי מזהה ייחודי (ID) אם קיים. הפתרון יכלול השוואה בין כתובות הזיכרון של חשבונות המקור והיעד, ונעילה תמיד של החשבון בעל הכתובת הנמוכה יותר תחילה, ולאחר מכן את החשבון בעל הכתובת הגבוהה יותר.

**מימוש מתוקן של transfer_money:**
```c
void transfer_money_safe(BankAccount* source, BankAccount* destination, long amount) {
    if (source == destination) {
        printf("Cannot transfer to self (account %d).\n", source->id);
        return; 
    }

    pthread_mutex_t *first_mutex, *second_mutex;
    BankAccount *first_account, *second_account;

    // Determine a consistent locking order based on memory addresses
    // This ensures that all threads attempting to lock these two specific accounts
    // will always try to acquire them in the same sequence, preventing circular wait.
    if (source < destination) { // Compare memory addresses of the account objects
        first_mutex = &source->mutex;
        second_mutex = &destination->mutex;
        first_account = source;
        second_account = destination;
    } else {
        first_mutex = &destination->mutex;
        second_mutex = &source->mutex;
        first_account = destination;
        second_account = source;
    }

    // Acquire locks in the consistent order
    pthread_mutex_lock(first_mutex);
    printf("Thread %lu locked account %d (first in order)\n", pthread_self(), first_account->id);

    // Simulate some work or delay
    usleep(10000); // 10ms delay

    pthread_mutex_lock(second_mutex);
    printf("Thread %lu locked account %d (second in order)\n", pthread_self(), second_account->id);

    // Perform the transfer logic with both locks held
    // The source and destination pointers remain as they were passed to the function,
    // only the order of mutex acquisition changes.
    if (source->balance >= amount) {
        source->balance -= amount;
        destination->balance += amount;
        printf("Transfer %ld from %d to %d successful. Balances: %d=%ld, %d=%ld\n", 
               amount, source->id, destination->id, source->id, source->balance, destination->id, destination->balance);
    } else {
        printf("Transfer %ld from %d to %d failed: insufficient funds. Balances: %d=%ld, %d=%ld\n", 
               amount, source->id, destination->id, source->id, source->balance, destination->id, destination->balance);
    }

    // Release locks in reverse order of acquisition (or simply both, order doesn't matter for unlock)
    pthread_mutex_unlock(second_mutex);
    printf("Thread %lu unlocked account %d (second in order)\n", pthread_self(), second_account->id);
    pthread_mutex_unlock(first_mutex);
    printf("Thread %lu unlocked account %d (first in order)\n", pthread_self(), first_account->id);
}
```

