#include <iostream>
#include <vector> // For dynamic array elements on heap implicitly

void exampleFunction() {
    // Stack allocation: 'x' is allocated on the stack
    int x = 10;
    std::cout << "Stack variable x: " << x << std::endl;

    // Heap allocation: 'ptr_heap_int' points to memory on the heap
    int* ptr_heap_int = new int; // Explicit heap allocation
    *ptr_heap_int = 20;
    std::cout << "Heap variable pointed by ptr_heap_int: " << *ptr_heap_int << std::endl;

    // Another stack allocation: 'arr_stack' is a fixed-size array on the stack
    int arr_stack[5] = {1, 2, 3, 4, 5};
    std::cout << "Stack array element: " << arr_stack[0] << std::endl;

    // Another heap allocation: 'vec_heap' object itself is on stack,
    // but its elements are stored on the heap.
    std::vector<int> vec_heap; 
    vec_heap.push_back(30);
    std::cout << "Heap vector element: " << vec_heap[0] << std::endl;

    // Deallocate explicitly allocated heap memory
    delete ptr_heap_int;
    // 'vec_heap' destructor will automatically deallocate its heap memory when it goes out of scope
}

int main() {
    exampleFunction();
    // After exampleFunction returns, all stack-allocated variables within it
    // (like x, arr_stack, ptr_heap_int pointer, and vec_heap object) are deallocated.
    // The memory pointed to by ptr_heap_int was explicitly deleted.
    // The memory used by vec_heap for its elements was implicitly deleted by its destructor.

    return 0;
}

