#define N 4096 // גודל המטריצה N x N

int matrix[N][N]; // מטריצה גלובלית שלמים

void init_matrix() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            matrix[i][j] = i + j;
        }
    }
}

// פונקציה 1: סריקה בסדר שורות (row-major)
void process_row_major() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            matrix[i][j] *= 2;
        }
    }
}

// פונקציה 2: סריקה בסדר עמודות (column-major)
void process_col_major() {
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < N; i++) {
            matrix[i][j] *= 2;
        }
    }
}

