#include <stddef.h> // For size_t
#include <sys/mman.h> // For mmap, munmap
#include <unistd.h> // For sysconf (page size)
#include <pthread.h> // For pthread_mutex_t
#include <stdio.h> // For perror, fprintf

#define HEAP_SIZE (1 * 1024 * 1024 * 1024UL) // 1GB
#define MIN_ALLOC_USER_SIZE 16 // Minimum user data size to ensure block can hold pointers for free list
#define ALIGNMENT sizeof(long) // General alignment for malloc

// Block header structure (for both free and allocated blocks)
typedef struct block_header {
    size_t size; // Size of the block (including header and footer). MSB indicates allocated/free.
    struct block_header *next_free; // Used only if block is free. Points to next free block in address order.
    struct block_header *prev_free; // Used only if block is free. Points to previous free block in address order.
} block_header_t;

// A block also has a footer, which is just a size_t storing the block's total size (without flag).
// This allows traversing backwards.

static void *heap_start = NULL;
static block_header_t *free_list_head = NULL; // Head of the doubly linked list of FREE blocks, sorted by address.
static pthread_mutex_t allocator_mutex = PTHREAD_MUTEX_INITIALIZER; // Statically initialize mutex

// Helper to get the footer pointer for a given block header
static size_t *get_footer(block_header_t *block) {
    return (size_t *)((char *)block + (block->size & ~(1UL << (sizeof(size_t)*8 - 1))) - sizeof(size_t));
}

// Helper to check if a block is allocated (MSB of size is set)
static int is_allocated(block_header_t *block) {
    return (block->size & (1UL << (sizeof(size_t)*8 - 1))) != 0;
}

// Helper to get the true size of a block (without allocated flag)
static size_t get_block_total_size(block_header_t *block) {
    return block->size & ~(1UL << (sizeof(size_t)*8 - 1));
}

// Helper to mark a block as allocated
static void mark_allocated(block_header_t *block, size_t size) {
    block->size = size | (1UL << (sizeof(size_t)*8 - 1)); // Set MSB
    *get_footer(block) = size; // Update footer
}

// Helper to mark a block as free
static void mark_free(block_header_t *block, size_t size) {
    block->size = size; // Clear MSB
    *get_footer(block) = size; // Update footer
}

// Helper to remove a block from the free list
static void remove_from_free_list(block_header_t *block) {
    if (block->prev_free) {
        block->prev_free->next_free = block->next_free;
    } else {
        free_list_head = block->next_free;
    }
    if (block->next_free) {
        block->next_free->prev_free = block->prev_free;
    }
    block->next_free = NULL; // Clear pointers
    block->prev_free = NULL;
}

// Helper to insert a block into the free list (maintaining address order)
static void insert_into_free_list(block_header_t *block) {
    block_header_t *current = free_list_head;
    block_header_t *prev = NULL;

    while (current != NULL && current < block) {
        prev = current;
        current = current->next_free;
    }

    if (prev == NULL) { // Insert at head
        block->next_free = free_list_head;
        if (free_list_head) free_list_head->prev_free = block;
        free_list_head = block;
    } else { // Insert in middle or at end
        block->next_free = current;
        block->prev_free = prev;
        prev->next_free = block;
        if (current) current->prev_free = block;
    }
}

// Helper to get actual aligned size needed for user data + header + footer
static size_t calculate_aligned_block_size(size_t user_size) {
    // Minimum block size must accommodate header, footer, and MIN_ALLOC_USER_SIZE
    // This ensures that even small user requests result in a block large enough to be split later
    size_t min_effective_user_size = (user_size < MIN_ALLOC_USER_SIZE) ? MIN_ALLOC_USER_SIZE : user_size;
    size_t total_size = sizeof(block_header_t) + min_effective_user_size + sizeof(size_t); // Header + user_data + Footer
    return (total_size + ALIGNMENT - 1) & ~(ALIGNMENT - 1); // Align total block size
}

// Function to initialize the allocator
void init_allocator() {
    if (heap_start != NULL) {
        return; // Already initialized
    }

    // Allocate the heap using mmap
    heap_start = mmap(NULL, HEAP_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (heap_start == MAP_FAILED) {
        perror("mmap failed");
        // In a real system, handle this gracefully, perhaps by exiting or throwing an exception.
        return;
    }

    // Initialize the first (and only) free block spanning the entire heap
    block_header_t *initial_block = (block_header_t *)heap_start;
    mark_free(initial_block, HEAP_SIZE); // Mark free, set size in header and footer
    initial_block->next_free = NULL;
    initial_block->prev_free = NULL;
    free_list_head = initial_block;
}

// Function to allocate memory
void *my_malloc(size_t size) {
    if (size == 0) {
        return NULL;
    }

    pthread_mutex_lock(&allocator_mutex);

    // Calculate the total block size needed (user_size + header + footer), aligned
    size_t required_block_total_size = calculate_aligned_block_size(size);

    block_header_t *current = free_list_head;
    block_header_t *best_fit = NULL; // Best-fit strategy

    // Search for the best-fit free block
    while (current != NULL) {
        if (get_block_total_size(current) >= required_block_total_size) {
            if (best_fit == NULL || get_block_total_size(current) < get_block_total_size(best_fit)) {
                best_fit = current;
            }
        }
        current = current->next_free;
    }

    if (best_fit == NULL) {
        // No suitable block found
        pthread_mutex_unlock(&allocator_mutex);
        return NULL;
    }

    block_header_t *block_to_allocate = best_fit;
    size_t original_block_total_size = get_block_total_size(block_to_allocate);

    // Remove block_to_allocate from the free list
    remove_from_free_list(block_to_allocate);

    // Check if the remaining part after allocation is large enough to form a new free block
    if (original_block_total_size - required_block_total_size >= calculate_aligned_block_size(1)) { // Check against minimal block size
        // Split the block
        mark_allocated(block_to_allocate, required_block_total_size); // Mark the allocated part

        block_header_t *new_free_block = (block_header_t *)((char *)block_to_allocate + required_block_total_size);
        mark_free(new_free_block, original_block_total_size - required_block_total_size); // Mark the new free part

        // Insert the new free block back into the free list, maintaining address order
        insert_into_free_list(new_free_block);
    } else {
        // Not enough space to split, allocate the entire block
        mark_allocated(block_to_allocate, original_block_total_size);
    }

    pthread_mutex_unlock(&allocator_mutex);
    return (void *)((char *)block_to_allocate + sizeof(block_header_t)); // Return pointer to user data area
}

// Function to free memory
void my_free(void *ptr) {
    if (ptr == NULL) {
        return;
    }

    pthread_mutex_lock(&allocator_mutex);

    // Get the block header from the user pointer
    block_header_t *block_to_free = (block_header_t *)((char *)ptr - sizeof(block_header_t));

    // Basic validation: ensure it's within our heap and marked as allocated
    if ((void*)block_to_free < heap_start || (void*)block_to_free >= (char*)heap_start + HEAP_SIZE || !is_allocated(block_to_free)) {
        fprintf(stderr, "Error: Attempt to free an invalid or unallocated block at %p.\n", ptr);
        pthread_mutex_unlock(&allocator_mutex);
        return;
    }

    // Mark the current block as free
    size_t current_block_total_size = get_block_total_size(block_to_free);
    mark_free(block_to_free, current_block_total_size);

    // Attempt to coalesce with physically adjacent free blocks

    // Check previous physical block using its footer
    block_header_t *prev_phys_block = NULL;
    if (block_to_free > (block_header_t *)heap_start) { // If not the very first block in the heap
        size_t *prev_footer_ptr = (size_t *)((char *)block_to_free - sizeof(size_t));
        size_t prev_phys_size = *prev_footer_ptr; // Get size of previous block from its footer
        prev_phys_block = (block_header_t *)((char *)block_to_free - prev_phys_size);

        // Ensure prev_phys_block is valid and free
        if ((void*)prev_phys_block >= heap_start && !is_allocated(prev_phys_block)) {
            // Merge current block into prev_phys_block
            remove_from_free_list(prev_phys_block); // Remove prev_phys_block from free list
            mark_free(prev_phys_block, get_block_total_size(prev_phys_block) + current_block_total_size);
            block_to_free = prev_phys_block; // Now block_to_free refers to the merged block
            current_block_total_size = get_block_total_size(block_to_free); // Update size
        }
    }

    // Check next physical block
    block_header_t *next_phys_block = (block_header_t *)((char *)block_to_free + current_block_total_size);
    if ((void *)next_phys_block < (char *)heap_start + HEAP_SIZE && !is_allocated(next_phys_block)) {
        // Ensure next_phys_block is valid and free
        // Merge next_phys_block into block_to_free
        remove_from_free_list(next_phys_block); // Remove next_phys_block from free list
        mark_free(block_to_free, get_block_total_size(block_to_free) + get_block_total_size(next_phys_block));
    }

    // Insert the (potentially merged) block into the free list
    insert_into_free_list(block_to_free);

    pthread_mutex_unlock(&allocator_mutex);
}
