// Custom malloc - first fit
void* my_malloc(size_t size) {
    size = align_size(size);
    size_t total_required_size = size + BLOCK_HEADER_SIZE;

    Block *current = free_list_head;
    Block *prev = NULL;

    while (current != NULL) {
        if (current->size >= total_required_size) {
            // Found a suitable block
            if (current->size - total_required_size >= BLOCK_HEADER_SIZE + ALIGNMENT) { // If enough space to split
                // Split the block
                Block *new_free_block = (Block*)((char*)current + total_required_size);
                new_free_block->size = current->size - total_required_size;
                new_free_block->next = current->next; // The new free block inherits the rest of the list

                current->size = total_required_size; // 'current' is now the allocated block

                // Update the free list: 'new_free_block' replaces 'current'
                if (prev == NULL) {
                    free_list_head = new_free_block;
                } else {
                    prev->next = new_free_block;
                }
            } else { // Not enough space to split, take the whole block
                // Remove 'current' from the free list
                if (prev == NULL) {
                    free_list_head = current->next;
                } else {
                    prev->next = current->next;
                }
