    Block *new_block = (Block*)sbrk(total_required_size);
    if (new_block == (void*)-1) {
        return NULL; // sbrk failed
    }
    new_block->size = total_required_size;
    new_block->next = NULL; // This block is fully allocated, not part of free list yet

