```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

#define PAGE_SIZE 4096 // 4KB
#define ARRAY_SIZE (1024 * 1024) // 4MB total array size (1024 pages of integers)

int global_array[ARRAY_SIZE]; // Array of integers

int main() {
    // 1. Initialize first part of the array
    for (int i = 0; i < ARRAY_SIZE / 2; ++i) {
        global_array[i] = i;
    }

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // Child process
        // 2. Child modifies the second half of the array
        for (int i = ARRAY_SIZE / 2; i < ARRAY_SIZE; ++i) {
            global_array[i] = i * 2;
        }
        exit(0);
    } else { // Parent process
        // 3. Parent modifies the first half of the array
        for (int i = 0; i < ARRAY_SIZE / 2; ++i) {
            global_array[i] = i * 3;
        }
        wait(NULL); // Wait for child to finish
    }

    return 0;
}
```

בהתעלם מזיכרון הנדרש לקוד, למחסנית, לערימה או למבני נתונים של מערכת ההפעלה (כגון טבלאות דפים), כמה דפים פיזיים בסך הכל יוקצו על ידי מערכת ההפעלה עבור המערך `global_array` לאחר ששני התהליכים (האב והבן) סיימו את פעולותיהם? הסבירו את חישוביכם לפרטי פרטים.

