    for (int i = 0; i < ARRAY_SIZE / sizeof(int); ++i) {
        global_array[i] = i;
    }

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // תהליך הבן
        printf("Child process (PID: %d) modifying memory...\n", getpid());
        // הבן משנה את חציו הראשון של המערך
        for (int i = 0; i < (ARRAY_SIZE / sizeof(int)) / 2; ++i) {
            global_array[i] = -i;
        }
        printf("Child finished modifications.\n");
    } else { // תהליך האב
        printf("Parent process (PID: %d) modifying memory...\n", getpid());
        // האב משנה את חציו השני של המערך
        for (int i = (ARRAY_SIZE / sizeof(int)) / 2; i < ARRAY_SIZE / sizeof(int); ++i) {
            global_array[i] = i * 2;
        }
        printf("Parent finished modifications.\n");
        wait(NULL); // המתן לבן שיסיים
        printf("Child exited. Parent exiting.\n");
    }

    return 0;
}
