solution.code_snippet:
#include <stdio.h>

#define PAGE_SIZE_BYTES 4096 // 4KB
#define PAGE_SHIFT 12        // log2(4096)
#define PAGE_MASK 0xFFF      // Mask for the offset (12 bits)

// Structure for a Page Table Entry (PTE)
typedef struct {
    unsigned int physical_frame_number; // The physical frame number
    unsigned int present : 1;           // 1 if page is in physical memory, 0 otherwise
} PageTableEntry;

// Function to implement:
unsigned int translate_address(unsigned int virtual_address, PageTableEntry* page_table) {
    // 1. Extract virtual page number (VPN)
    unsigned int virtual_page_number = virtual_address >> PAGE_SHIFT;

    // 2. Extract offset within the page
    unsigned int offset = virtual_address & PAGE_MASK;

    // 3. Look up the Page Table Entry (PTE) using the VPN
    //    We assume page_table is an array of PageTableEntry
    PageTableEntry pte = page_table[virtual_page_number];

    // 4. Combine the physical frame number (PFN) with the offset to get the physical address
    unsigned int physical_address = (pte.physical_frame_number << PAGE_SHIFT) | offset;

    return physical_address;
}

