#include <stdio.h>
#include <stdlib.h>

#define ARRAY_SIZE (256 * 1024 * 1024) // 256 MB
#define PAGE_SIZE 4096 // 4 KB

int main() {
    char *arr = (char *)malloc(ARRAY_SIZE);
    if (arr == NULL) {
        perror("malloc failed");
        return 1;
    }

    // Ensure all pages are mapped and resident in physical memory.
    // This loop forces initial page faults for all pages.
    for (long i = 0; i < ARRAY_SIZE; i += PAGE_SIZE) {
        arr[i] = 0;
    }

    // --- Loop 1: Sequential Access ---
    printf("Starting sequential access (Loop 1)...\n");
    for (long i = 0; i < ARRAY_SIZE; ++i) {
        arr[i] = (char)(i % 256);
    }
    printf("Sequential access finished.\n");

    // --- Loop 2: Strided Access ---
    // Stride is PAGE_SIZE * 2 to ensure we hit different pages frequently
    printf("Starting strided access (Loop 2)...\n");
    for (long i = 0; i < ARRAY_SIZE; i += (PAGE_SIZE * 2)) {
        arr[i] = (char)(i % 256);
    }
    printf("Strided access finished.\n");

    free(arr);
    return 0;
}
```

