// Define constants for address translation
#define PAGE_OFFSET_BITS 12
#define PTE_INDEX_BITS 10
#define PDE_INDEX_BITS 10

#define PAGE_SIZE (1 << PAGE_OFFSET_BITS) // 4KB

// Masks for extracting parts of the virtual address
#define PAGE_OFFSET_MASK ((1 << PAGE_OFFSET_BITS) - 1)
#define PTE_INDEX_MASK (((1 << PTE_INDEX_BITS) - 1) << PAGE_OFFSET_BITS)
#define PDE_INDEX_MASK (((1 << PDE_INDEX_BITS) - 1) << (PAGE_OFFSET_BITS + PTE_INDEX_BITS))

// Bit for the 'Present' flag in PTE/PDE
#define PRESENT_BIT 0x1

// Simplified Page Table Entry structure
typedef uint32_t PageTableEntry; // PFN is bits 31-12, flags are 11-0

// Function to simulate reading from physical memory (for page table walk)
// In a real OS, this would access actual memory. Here, it's a placeholder.
uint32_t read_physical_memory(uint32_t p_addr) {
    // For this problem, assume it works and returns a valid 32-bit entry
    // from the specified physical address, if the address is valid.
    // In a real simulation, this might involve an array representing physical memory.
    // For code analysis, we focus on the logic of translate_virtual_to_physical.
    (void)p_addr; // Suppress unused parameter warning
    // A real implementation might look like: return simulated_physical_memory[p_addr / sizeof(uint32_t)];
    // For this problem, assume it returns the correct PageTableEntry/PageDirectoryEntry value.
    return 0; // Placeholder return
}

// Function to translate a virtual address to a physical address
// Returns -1 (or some error code) if a page fault occurs.
uint32_t translate_virtual_to_physical(uint32_t virtual_address, uint32_t cr3_register) {
    // 1. Extract PDI, PTI, and Offset
    uint32_t pdi = (virtual_address & PDE_INDEX_MASK) >> (PAGE_OFFSET_BITS + PTE_INDEX_BITS);
    uint32_t pti = (virtual_address & PTE_INDEX_MASK) >> PAGE_OFFSET_BITS;
    uint32_t offset = virtual_address & PAGE_OFFSET_MASK;

    // 2. Get Page Directory Entry (PDE)
    uint32_t pde_address = (cr3_register & ~PAGE_OFFSET_MASK) + (pdi * sizeof(PageTableEntry));
    PageTableEntry pde = read_physical_memory(pde_address);

    // Check if PDE is present
    if (!(pde & PRESENT_BIT)) {
        return (uint32_t)-1; // Page fault: PDE not present
    }

    // 3. Get Page Table Entry (PTE)
    // The physical address of the next page table is in the upper bits of the PDE
    uint32_t pt_base_physical_address = pde & ~PAGE_OFFSET_MASK; // Extract PFN from PDE
    uint32_t pte_address = pt_base_physical_address + (pti * sizeof(PageTableEntry));
    PageTableEntry pte = read_physical_memory(pte_address);

    // Check if PTE is present
    if (!(pte & PRESENT_BIT)) {
        return (uint32_t)-1; // Page fault: PTE not present
    }

    // 4. Calculate Physical Address
    // The physical address of the page frame is in the upper bits of the PTE
    uint32_t page_frame_physical_address = pte & ~PAGE_OFFSET_MASK; // Extract PFN from PTE
    uint32_t physical_address = page_frame_physical_address + offset;

    return physical_address;
}

solution.explanation:
1.1: כן, קיימת סיטואציה כזו. אם אחת מהרשומות בטבלת העמודים (PDE או PTE) מוגדרת עם דגל ה-`Present` על 1, אך ערך ה-PFN (הכתובת הפיזית של טבלת העמודים הבאה או של ה-Page Frame) הוא 0 (כלומר, כל ה-20 הסיביות העליונות הן 0), הפונקציה תנסה לגשת לכתובת פיזית 0. ברוב מערכות ההפעלה, כתובת פיזית 0 שמורה או אינה ניתנת לשימוש עבור טבלאות עמודים או עמודי נתונים, וניסיון גישה אליה עלול לגרום לקריסה של המערכת או ל-Page Fault נוסף שלא מטופל כראוי במסגרת פונקציה זו. הפונקציה הנוכחית בודקת רק את דגל ה-`Present` אך לא את תקינות הכתובת הפיזית עצמה.

**תיקון מוצע:**
יש להוסיף בדיקה שערך הכתובת הפיזית שהופק מתוך ה-PDE או ה-PTE אינו 0 (אלא אם כן, במערכת ספציפית, כתובת פיזית 0 היא לגיטימית לשימוש כבסיס לטבלת עמודים או כ-Page Frame). התיקון ייראה כך:
```c
// ... inside translate_virtual_to_physical function ...

    // Check if PDE is present AND its physical address is not zero (if 0 is invalid)
    // (pde & PRESENT_BIT) ensures we only check the address if present is 1
    if (!(pde & PRESENT_BIT) || ((pde & ~PAGE_OFFSET_MASK) == 0 && (pde & PRESENT_BIT))) {
        return (uint32_t)-1; // Page fault: PDE not present or points to invalid zero address
    }
    uint32_t pt_base_physical_address = pde & ~PAGE_OFFSET_MASK;

    // ...
    // Check if PTE is present AND its physical address is not zero (if 0 is invalid)
    if (!(pte & PRESENT_BIT) || ((pte & ~PAGE_OFFSET_MASK) == 0 && (pte & PRESENT_BIT))) {
        return (uint32_t)-1; // Page fault: PTE not present or points to invalid zero address
    }
    uint32_t page_frame_physical_address = pte & ~PAGE_OFFSET_MASK;

// ...
```
הערה: בדיקה זו מבוססת על ההנחה שכתובת פיזית 0 אינה מותרת כבסיס לטבלת עמודים או כ-Page Frame. במערכות מסוימות, ייתכן שכתובת 0 היא לגיטימית ויש להתאים את הבדיקה בהתאם.

1.2: ה-TLB (Translation Lookaside Buffer) הוא זיכרון מטמון קטן ומהיר השומר תרגומי כתובות וירטואליות-פיזיות שבוצעו לאחרונה. הוא נועד להאיץ את תהליך תרגום הכתובות על ידי הימנעות מהצורך לבצע 'הליכה' מלאה בטבלאות העמודים שבזיכרון הראשי עבור כל גישה לזיכרון.

*   **פגיעת TLB (TLB Hit):** כאשר תרגום הכתובת הווירטואלית כבר נמצא ב-TLB, המערכת יכולה לקבל את הכתובת הפיזית באופן מיידי מה-TLB, ללא צורך לבצע את הפעולות שמתוארות בפונקציה `translate_virtual_to_physical` (קריאות ל-`read_physical_memory`). זה משפר באופן דרמטי את ביצועי גישת הזיכרון, שכן אין צורך לגשת לזיכרון הראשי (שתי גישות במקרה של טבלה דו-שכבתית) כדי לבצע את התרגום. הפונקציה `translate_virtual_to_physical` לא תופעל כלל במקרה של TLB Hit.

*   **החטאת TLB (TLB Miss):** כאשר תרגום הכתובת הווירטואלית אינו נמצא ב-TLB, המערכת נאלצת לבצע את 'הליכת טבלת העמודים' המלאה (Page Table Walk) באמצעות ה-MMU (או במקרה שלנו, באמצעות הפונקציה `translate_virtual_to_physical`). זה כרוך במספר גישות לזיכרון הראשי (שתי גישות במקרה של טבלה דו-שכבתית: אחת ל-PDE ואחת ל-PTE). לאחר שהתרגום נמצא, הוא נטען ל-TLB עבור גישות עתידיות. החטאת TLB מאטה משמעותית את גישת הזיכרון הראשונית לאותו עמוד, מכיוון שהיא דורשת יותר גישות לזיכרון הראשי מאשר גישה ישירה לנתונים. הפונקציה `translate_virtual_to_physical` מתארת בדיוק את העבודה שמתבצעת בעת TLB Miss.

