#include <stdio.h>
#include <stdlib.h> // For malloc, free

#define BLOCK_SIZE 4096 // 4KB
#define POINTERS_PER_BLOCK (BLOCK_SIZE / sizeof(int)) // Assuming int is 4 bytes, so 1024 pointers
#define NUM_DIRECT_BLOCKS 12

typedef struct {
    int direct_blocks[NUM_DIRECT_BLOCKS];
    int single_indirect_block;            // Pointer to a block of pointers
    int double_indirect_block;            // Pointer to a block of pointers to blocks of pointers
} inode_t;

// Mock helper function for demonstration. In a real scenario, this would interact with disk.
// For the purpose of the exam question, it's just a signature.
// For the solution, we assume it exists and works as described.
int read_block_pointers(int block_address, int* buffer) {
    // In a real system, this would read from disk into the buffer.
    // For this problem, we just need to know it provides the array of pointers.
    // We'll return 0 for success, and -1 for an invalid address or read error.
    if (block_address <= 0) { // Assuming block addresses are positive integers
        return -1; 
    }
    // Simulate populating buffer with some values if necessary for testing,
    // but for the logic of getBlockAddress, we just need the function signature.
    return 0; // Success
}

int getBlockAddress(inode_t* inode, int logical_block_num) {
    // 1. Direct blocks
    if (logical_block_num < NUM_DIRECT_BLOCKS) {
        // Ensure the direct block pointer is valid (not 0 or -1, assuming 0 is invalid)
        if (inode->direct_blocks[logical_block_num] <= 0) {
            return -1;
        }
        return inode->direct_blocks[logical_block_num];
    }

    // 2. Single Indirect blocks
    int single_indirect_start = NUM_DIRECT_BLOCKS;
    int single_indirect_end = single_indirect_start + POINTERS_PER_BLOCK;
    if (logical_block_num >= single_indirect_start && logical_block_num < single_indirect_end) {
        // Check if the single indirect block pointer itself is valid
        if (inode->single_indirect_block <= 0) {
            return -1;
        }

        int* ptr_block = (int*)malloc(BLOCK_SIZE);
        if (ptr_block == NULL) {
            return -1; // Memory allocation failed
        }

        // Read the single indirect block from disk
        if (read_block_pointers(inode->single_indirect_block, ptr_block) == -1) {
            free(ptr_block);
            return -1; // Failed to read indirect block
        }

        int offset_in_indirect_block = logical_block_num - single_indirect_start;
        // Ensure the pointer within the indirect block is valid
        if (ptr_block[offset_in_indirect_block] <= 0) {
            free(ptr_block);
            return -1;
        }

        int block_address = ptr_block[offset_in_indirect_block];
        free(ptr_block);
        return block_address;
    }

    // 3. Double Indirect blocks
    int double_indirect_start = single_indirect_end;
    int double_indirect_end = double_indirect_start + (POINTERS_PER_BLOCK * POINTERS_PER_BLOCK);
    if (logical_block_num >= double_indirect_start && logical_block_num < double_indirect_end) {
        // Check if the double indirect block pointer itself is valid
        if (inode->double_indirect_block <= 0) {
            return -1;
        }

        int* ptr_block_lvl1 = (int*)malloc(BLOCK_SIZE);
        if (ptr_block_lvl1 == NULL) {
            return -1; // Memory allocation failed
        }

        // Read the first level indirect block (which contains pointers to other indirect blocks)
        if (read_block_pointers(inode->double_indirect_block, ptr_block_lvl1) == -1) {
            free(ptr_block_lvl1);
            return -1; // Failed to read first level indirect block
        }

        int offset_from_double_indirect_start = logical_block_num - double_indirect_start;
        int idx1 = offset_from_double_indirect_start / POINTERS_PER_BLOCK; // Index in the first level indirect block
        int idx2 = offset_from_double_indirect_start % POINTERS_PER_BLOCK; // Index in the second level indirect block

        // Check if the pointer at idx1 in the first level indirect block is valid
        if (idx1 >= POINTERS_PER_BLOCK || ptr_block_lvl1[idx1] <= 0) {
            free(ptr_block_lvl1);
            return -1;
        }

        int* ptr_block_lvl2 = (int*)malloc(BLOCK_SIZE);
        if (ptr_block_lvl2 == NULL) {
            free(ptr_block_lvl1); // Clean up previously allocated memory
            return -1; // Memory allocation failed
        }

        // Read the second level indirect block (which contains pointers to data blocks)
        if (read_block_pointers(ptr_block_lvl1[idx1], ptr_block_lvl2) == -1) {
            free(ptr_block_lvl1);
            free(ptr_block_lvl2);
            return -1; // Failed to read second level indirect block
        }

        // Ensure the pointer within the second level indirect block is valid
        if (ptr_block_lvl2[idx2] <= 0) {
            free(ptr_block_lvl1);
            free(ptr_block_lvl2);
            return -1;
        }

        int block_address = ptr_block_lvl2[idx2];
        free(ptr_block_lvl1);
        free(ptr_block_lvl2);
        return block_address;
    }

    // Logical block number is out of the range supported by this inode structure
    return -1;
}

