    if (link(file_orig, hard_link_name) == -1) { perror("link hardlink.txt"); return 1; }

    // 3. Create a symbolic link to original.txt
    if (symlink(file_orig, soft_link_name) == -1) { perror("symlink softlink.txt"); return 1; }

    // 4. Append "Second line." via the hard link
    fd = open(hard_link_name, O_WRONLY | O_APPEND);
    if (fd == -1) { perror("open hardlink.txt for append"); return 1; }
    write(fd, "Second line.\n", 13);
    close(fd);

    // 5. Unlink the original file
    if (unlink(file_orig) == -1) { perror("unlink original.txt"); return 1; }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
