#include <sys/stat.h>

#define FILENAME "sparse_file_test.bin"

int main() {
    int fd;
    char initial_data[] = "START"; // 5 bytes
    char final_data = 'E';         // 1 byte
    off_t seek_offset = 100 * 1024 * 1024; // 100 MB

    // Open the file for writing, create if it doesn't exist, truncate if it does
    fd = open(FILENAME, O_CREAT | O_TRUNC | O_WRONLY, 0644);
    if (fd == -1) {
        perror("Error opening file");
        return 1;
    }

    // Write initial data
    if (write(fd, initial_data, strlen(initial_data)) == -1) {
        perror("Error writing initial data");
        close(fd);
        return 1;
    }

    // Seek to a large offset
    if (lseek(fd, seek_offset, SEEK_SET) == (off_t)-1) {
        perror("Error seeking");
        close(fd);
        return 1;
    }

    // Write a single byte at the new offset
    if (write(fd, &final_data, 1) == -1) {
        perror("Error writing final data");
        close(fd);
        return 1;
    }

    // Close the file
    close(fd);

    // The program ends here.
    return 0;
}

