נתונה תוכנית C הבאה המדגימה יצירת קובץ, קישורים קשיחים (hard links), פעולות מחיקה (unlink) וגישה לקובץ מתהליכים שונים.
קראו את הקוד בעיון וענו על השאלות הבאות.
יש להניח שכל קריאות המערכת מצליחות, ואין שגיאות I/O.
יש להתייחס למערכת הפעלה מבוססת POSIX.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <string.h>
#include <sys/wait.h>

#define FILENAME_ORIG "exam_file_orig.txt"
#define FILENAME_LINK "exam_file_link.txt"
#define BUF_SIZE 10

int main() {
    int fd_parent;
    char buffer[BUF_SIZE];
    pid_t pid;

    // 1. Create a file and write initial content
    fd_parent = open(FILENAME_ORIG, O_CREAT | O_TRUNC | O_RDWR, 0644);
    if (fd_parent == -1) {
        perror("open FILENAME_ORIG");
        return EXIT_FAILURE;
    }
    write(fd_parent, "AAAABBBBCC", BUF_SIZE); // Write 10 bytes
    printf("Parent[%d]: Wrote 'AAAABBBBCC' to %s, fd_parent = %d\n", getpid(), FILENAME_ORIG, fd_parent);
    fflush(stdout);

    // 2. Create a hard link
    if (link(FILENAME_ORIG, FILENAME_LINK) == -1) {
        perror("link");
        close(fd_parent);
        unlink(FILENAME_ORIG); // Clean up if link fails
        return EXIT_FAILURE;
    }
    printf("Parent[%d]: Created hard link %s to %s\n", getpid(), FILENAME_LINK, FILENAME_ORIG);
    fflush(stdout);

    // 3. Unlink the original path name
    if (unlink(FILENAME_ORIG) == -1) {
        perror("unlink FILENAME_ORIG");
        close(fd_parent);
        unlink(FILENAME_LINK); // Clean up
        return EXIT_FAILURE;
    }
    printf("Parent[%d]: Unlinked original file path %s\n", getpid(), FILENAME_ORIG);
    fflush(stdout);
    // At this point, the file's link count is 1 (due to FILENAME_LINK)
    // and it's still open via fd_parent.

    // 4. Fork a child process
    pid = fork();

    if (pid == -1) {
        perror("fork");
        close(fd_parent);
        unlink(FILENAME_LINK); // Clean up
        return EXIT_FAILURE;
    }

    if (pid == 0) { // Child process
        int fd_child;
        printf("Child[%d]: Starting.\n", getpid());
        fflush(stdout);

        // Child closes its inherited fd_parent to ensure it opens a new one
        close(fd_parent);

        // Child opens the file via the hard link path
        fd_child = open(FILENAME_LINK, O_RDWR);
        if (fd_child == -1) {
            perror("Child: open FILENAME_LINK");
            exit(EXIT_FAILURE);
        }
        printf("Child[%d]: Opened %s, fd_child = %d\n", getpid(), FILENAME_LINK, fd_child);
        fflush(stdout);

        // Child seeks and writes
        lseek(fd_child, 0, SEEK_SET); // Seek to beginning
        write(fd_child, "XXXX", 4);   // Overwrite first 4 bytes
        printf("Child[%d]: Wrote 'XXXX' to file via fd_child\n", getpid());
        fflush(stdout);

        lseek(fd_child, 8, SEEK_SET); // Seek to offset 8
        write(fd_child, "YY", 2);     // Overwrite bytes at offset 8, 9
        printf("Child[%d]: Wrote 'YY' to file via fd_child\n", getpid());
        fflush(stdout);

        close(fd_child);
        printf("Child[%d]: Closed fd_child.\n", getpid());
        fflush(stdout);
        exit(EXIT_SUCCESS);

    } else { // Parent process
        printf("Parent[%d]: Forked child with PID = %d\n", getpid(), pid);
        fflush(stdout);

        // Parent waits for child to finish
        wait(NULL);
        printf("Parent[%d]: Child finished.\n", getpid());
        fflush(stdout);

        // Parent writes to the file *after* child is done
        // Parent's fd_parent still points to the file. Its offset is still at BUF_SIZE (10).
        lseek(fd_parent, 4, SEEK_SET); // Seek to offset 4
        write(fd_parent, "ZZZ", 3);    // Overwrite bytes at offset 4, 5, 6
        printf("Parent[%d]: Wrote 'ZZZ' to file via fd_parent\n", getpid());
        fflush(stdout);

        // Parent reads the final content of the file
        lseek(fd_parent, 0, SEEK_SET); // Seek to beginning to read
        ssize_t bytes_read = read(fd_parent, buffer, BUF_SIZE);
        if (bytes_read == -1) {
            perror("Parent: read final content");
        } else {
            buffer[bytes_read] = '\0';
            printf("Parent[%d]: Final content of the file: '%s'\n", getpid(), buffer);
            fflush(stdout);
        }

        // 5. Unlink the hard link path
        if (unlink(FILENAME_LINK) == -1) {
            perror("unlink FILENAME_LINK");
        }
        printf("Parent[%d]: Unlinked hard link path %s.\n", getpid(), FILENAME_LINK);
        fflush(stdout);
        // Now link count is 0. File data will be deallocated upon closing all FDs.

        // 6. Close the parent's file descriptor
        close(fd_parent);
        printf("Parent[%d]: Closed fd_parent. File data should now be deallocated.\n", getpid());
        fflush(stdout);

        // Try to open the file paths to confirm they are gone
        if (open(FILENAME_ORIG, O_RDONLY) == -1) {
            printf("Parent[%d]: Confirmed %s is gone.\n", getpid(), FILENAME_ORIG);
            fflush(stdout);
        }
        if (open(FILENAME_LINK, O_RDONLY) == -1) {
            printf("Parent[%d]: Confirmed %s is gone.\n", getpid(), FILENAME_LINK);
            fflush(stdout);
        }
    }

    return EXIT_SUCCESS;
}
