נתונה התוכנית הבאה, המדגימה פעולות על מערכת קבצים בסביבת יוניקס. יש להניח שכל קריאות המערכת מצליחות, ואין שגיאות I/O למעט אלו שעשויות להיות צפויות מלוגיקת התוכנית עצמה.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <string.h>
#include <sys/wait.h>
#include <errno.h>

int main() {
    const char *original_file = "data.txt";
    const char *hard_link = "hlink.txt";
    const char *sym_link = "slink.txt";
    char buffer[50];
    int fd;

    // 1. יצירת קובץ מקורי וכתיבת תוכן אליו
    fd = open(original_file, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    write(fd, "Hello World", strlen("Hello World"));
    close(fd);

    // 2. יצירת קישור קשיח (hard link) לקובץ המקורי
    link(original_file, hard_link);

    // 3. יצירת קישור סימלי (symbolic link) לקובץ המקורי
    symlink(original_file, sym_link);

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); return 1; }

    if (pid == 0) { // תהליך הבן
        // 4. הבן מוחק את הקובץ המקורי (מבטל את הקישור בספרייה)
        unlink(original_file);

        // 5. הבן מנסה לפתוח/ליצור מחדש את הקובץ המקורי עם דגל O_CREAT | O_EXCL
        fd = open(original_file, O_CREAT | O_EXCL | O_WRONLY, 0600);
        if (fd != -1) { // בהנחה שהפעולה מצליחה
            write(fd, "Child's new data", strlen("Child's new data"));
            close(fd);
        }
        exit(0);
    } else { // תהליך האב
        wait(NULL); // ממתין שהבן יסיים

        // 6. האב קורא מתוך הקישור הקשיח
        fd = open(hard_link, O_RDONLY);
        if (fd != -1) {
            memset(buffer, 0, sizeof(buffer));
            ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) buffer[bytes_read] = '\0';
            printf("Content of '%s': '%s'\n", hard_link, buffer);
            close(fd);
        }

        // 7. האב קורא מתוך הקישור הסימלי
        fd = open(sym_link, O_RDONLY);
        if (fd != -1) {
            memset(buffer, 0, sizeof(buffer));
            ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) buffer[bytes_read] = '\0';
            printf("Content of '%s': '%s'\n", sym_link, buffer);
            close(fd);
        }

        // 8. האב קורא מתוך הקובץ המקורי (שייתכן שהבן יצר מחדש)
        fd = open(original_file, O_RDONLY);
        if (fd != -1) {
            memset(buffer, 0, sizeof(buffer));
            ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
            if (bytes_read > 0) buffer[bytes_read] = '\0';
            printf("Content of '%s': '%s'\n", original_file, buffer);
            close(fd);
        }

        // ניקוי קבצים (לא חלק מהפלט המבוקש)
        unlink(hard_link);
        unlink(sym_link);
        unlink(original_file);
    }
    return 0;
}
```

הסבירו מה יהיה הפלט המודפס למסך על ידי תהליך האב (Parent) עבור שלבי הקריאה (6, 7 ו-8). פרטו את ההסבר לכל שלב, כולל שינויים במבנה מערכת הקבצים (כגון מונים של קישורים (link count) ואינודים (inodes)) כתוצאה מפעולות התוכנית.

