// פונקציית עזר להדפסת מידע על קובץ/קישור
void print_file_info(const char* path, const char* label) {
    struct stat st;
    printf("--- %s (%s) ---\n", label, path);
    if (lstat(path, &st) == -1) { // שימוש ב-lstat כדי להבחין בין קישור סימבולי למטרה שלו
        if (errno == ENOENT) {
            printf("File/Link '%s' does not exist.\n", path);
        } else {
            perror("lstat error");
        }
        return;
    }
    printf("Inode: %ld\n", (long)st.st_ino);
    printf("Links: %ld\n", (long)st.st_nlink);
    if (S_ISLNK(st.st_mode)) {
        char buf[256];
        ssize_t len = readlink(path, buf, sizeof(buf) - 1);
        if (len != -1) {
            buf[len] = '\0';
            printf("Symlink points to: %s\n", buf);
        } else {
            perror("readlink error");
        }
    }
    // מדפיס תוכן אם זה קובץ רגיל או קישור סימבולי תקין לקובץ רגיל
    // stat(path, &st) עוקב אחר קישורים סימבוליים. אם הוא נכשל, זה אומר שהיעד לא קיים.
    if (S_ISREG(st.st_mode) || (S_ISLNK(st.st_mode) && stat(path, &st) != -1 && S_ISREG(st.st_mode))) {
        FILE* f = fopen(path, "r");
        if (f) {
            printf("Content: \"");
            int c;
            while ((c = fgetc(f)) != EOF) {
                putchar(c);
            }
            printf("\"\n");
            fclose(f);
        } else {
            perror("fopen for content read error");
        }
    }
}

int main() {
    const char* fileA = "fileA.txt";
    const char* linkH = "linkH.txt";
    const char* linkS = "linkS.txt";

    // ניקוי ריצות קודמות
    unlink(fileA);
    unlink(linkH);
    unlink(linkS);

    // 1. יצירת fileA.txt וכתיבת "Hello" אליו
    FILE* f_a = fopen(fileA, "w");
    if (!f_a) { perror("fopen fileA"); return 1; }
    fprintf(f_a, "Hello");
    fclose(f_a);

    printf("Initial state:\n");
    print_file_info(fileA, "fileA");

    // 2. יצירת קישור קשיח linkH.txt ל-fileA.txt
    if (link(fileA, linkH) == -1) { perror("link hard"); return 1; }

    // 3. יצירת קישור סימבולי linkS.txt המצביע על fileA.txt
    if (symlink(fileA, linkS) == -1) { perror("symlink soft"); return 1; }

    printf("\nAfter creating links:\n");
    print_file_info(fileA, "fileA");
    print_file_info(linkH, "linkH");
    print_file_info(linkS, "linkS");

    pid_t pid = fork();

    if (pid == -1) {
        perror("fork error");
        return 1;
    } else if (pid == 0) { // תהליך הבן
        printf("\n--- Child Process (%d) ---\n", getpid());
        // פתיחת fileA.txt לכתיבה, כתיבת " child"
        f_a = fopen(fileA, "a"); // הוספה לתוכן קיים
        if (!f_a) { perror("child fopen fileA"); exit(1); }
        fprintf(f_a, " child");
        fclose(f_a);
        printf("Child wrote to %s.\n", fileA);

        // מחיקת linkH.txt
        if (unlink(linkH) == -1) { perror("child unlink linkH"); exit(1); }
        printf("Child unlinked %s.\n", linkH);

        exit(0);
    } else { // תהליך האב
        printf("\n--- Parent Process (%d) ---\n", getpid());
        int status;
        wait(&status); // המתנה שהבן יסיים
        printf("Parent finished waiting for child.\n");

        // פתיחת linkS.txt לכתיבה, כתיבת " parent"
        f_a = fopen(linkS, "a"); // הוספה לתוכן קיים, עוקב אחר הקישור הסימבולי
        if (!f_a) { perror("parent fopen linkS"); return 1; }
        fprintf(f_a, " parent");
        fclose(f_a);
        printf("Parent wrote to %s (via symlink).\n", linkS);

        // מחיקת fileA.txt
        if (unlink(fileA) == -1) { perror("parent unlink fileA"); return 1; }
        printf("Parent unlinked %s.\n", fileA);

        printf("\nFinal state (from parent):\n");
        print_file_info(fileA, "fileA (after unlink)");
        print_file_info(linkH, "linkH (after child unlink)");
        print_file_info(linkS, "linkS");
    }

    return 0;
}

