solution.explanation:
הפתרון דורש חישוב מדורג של הבלוקים הנדרשים בכל רמה של מצביעים (ישירים, עקיפים יחידים, עקיפים כפולים). יש לזכור שבלוקים עקיפים (single/double indirect blocks) עצמם תופסים מקום על הדיסק וצריך לספור אותם בנוסף לבלוקי הנתונים.

1.  **חישוב בלוקי נתונים:** תחילה, נחשב כמה בלוקי נתונים נדרשים עבור הקובץ. אם גודל הקובץ הוא 0, אין צורך בבלוקי נתונים. אחרת, נשתמש בחישוב תקרה: `(i_size + BLOCK_SIZE - 1) / BLOCK_SIZE`.
2.  **מצביעים ישירים:** עד `NUM_DIRECT_PTRS` בלוקים מטופלים על ידי מצביעים ישירים. בלוקים אלו אינם דורשים בלוקים נוספים עבור המצביעים עצמם.
3.  **מצביעים עקיפים יחידים:** אם מספר בלוקי הנתונים גדול מ-`NUM_DIRECT_PTRS`, נצטרך להשתמש במצביע העקיף היחיד. בלוק זה יכול להכיל `PTRS_PER_BLOCK` מצביעים. אם יש צורך בבלוק זה (כלומר, אם ישנם בלוקי נתונים שחורגים מיכולת הכיסוי של המצביעים הישירים), הוא עצמו תופס בלוק פיזי אחד על הדיסק.
4.  **מצביעים עקיפים כפולים:** אם מספר בלוקי הנתונים גדול ממה שיכולים לכסות המצביעים הישירים והעקיפים היחידים יחד (`NUM_DIRECT_PTRS + PTRS_PER_BLOCK`), נצטרך להשתמש במצביע העקיף הכפול. בלוק זה מכיל מצביעים לבלוקים עקיפים יחידים. הוא עצמו תופס בלוק פיזי אחד על הדיסק. בנוסף, כל אחד מבלוקי המצביעים העקיפים היחידים שהוא מצביע אליהם תופס גם הוא בלוק פיזי אחד. יש לחשב כמה בלוקים עקיפים יחידים כאלה נדרשים.

**מימוש:**
```c
#include <stdio.h>
#include <stdlib.h> 

#define BLOCK_SIZE 4096       // גודל בלוק בבתים
#define NUM_DIRECT_PTRS 12    // מספר מצביעים ישירים ב-inode
#define PTRS_PER_BLOCK (BLOCK_SIZE / sizeof(int)) // מספר מצביעים בבלוק עקיף (בהנחה שמצביע הוא int)

// מבנה Inode פשוט
typedef struct inode {
    long i_size; // גודל הקובץ בבתים
    // לצורך שאלה זו, אין צורך במימוש בפועל של המצביעים,
    // אלא רק בהבנת המבנה הלוגי וחישוב המקום
} inode_t;

int calculate_total_blocks(inode_t *inode) {
    if (inode->i_size == 0) {
        return 0;
    }

    // מספר בלוקי הנתונים הנדרשים עבור הקובץ
    long num_data_blocks = (inode->i_size + BLOCK_SIZE - 1) / BLOCK_SIZE;
    long total_physical_blocks = num_data_blocks; // מתחילים עם בלוקי הנתונים עצמם

    // בדיקה עבור בלוק מצביעים עקיפים יחידים
    // אם יש יותר בלוקי נתונים מאשר המצביעים הישירים יכולים לכסות
    if (num_data_blocks > NUM_DIRECT_PTRS) {
        total_physical_blocks += 1; // מוסיפים בלוק אחד עבור בלוק המצביעים העקיפים היחידים עצמו
    }

    // בדיקה עבור בלוק מצביעים עקיפים כפולים
    // ויש גם לחשב את בלוקי המצביעים העקיפים היחידים שמתחתיו
    // היכולת הכוללת של מצביעים ישירים ועקיפים יחידים
    long covered_by_direct_and_single_indirect = NUM_DIRECT_PTRS + PTRS_PER_BLOCK;

    if (num_data_blocks > covered_by_direct_and_single_indirect) {
        total_physical_blocks += 1; // מוסיפים בלוק אחד עבור בלוק המצביעים העקיפים הכפולים עצמו

        // נחשב כמה בלוקי מצביעים עקיפים יחידים נדרשים תחת הבלוק העקיף הכפול
        // אלו הבלוקים שחורגים מיכולת הכיסוי של המצביעים הישירים והעקיפים היחידים
        long remaining_data_blocks_for_double = num_data_blocks - covered_by_direct_and_single_indirect;
        // חישוב תקרה של כמה בלוקי מצביעים עקיפים יחידים נדרשים כדי להצביע ל-remaining_data_blocks_for_double
        long num_single_indirect_blocks_under_double = (remaining_data_blocks_for_double + PTRS_PER_BLOCK - 1) / PTRS_PER_BLOCK;
        total_physical_blocks += num_single_indirect_blocks_under_double; // מוסיפים את בלוקי המצביעים העקיפים היחידים האלה
    }

    return (int)total_physical_blocks;
}
```

