#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <string.h>

#define FILENAME "output.txt"
#define NUM_CHILDREN 2
#define CHUNK_SIZE 4 // Each process writes 4 bytes
#define FILE_LENGTH (CHUNK_SIZE * (NUM_CHILDREN + 1)) // Total length of 12 bytes

int main() {
    int fd;
    pid_t pid;
    int i;
    char buffer[CHUNK_SIZE + 1];

    fd = open(FILENAME, O_CREAT | O_RDWR | O_TRUNC, 0644);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Initialize file with 'X' characters up to FILE_LENGTH
    for (i = 0; i < FILE_LENGTH; ++i) {
        if (write(fd, "X", 1) == -1) {
            perror("initial write");
            exit(EXIT_FAILURE);
        }
    }
    lseek(fd, 0, SEEK_SET); // Reset offset to beginning for subsequent writes

    // Fork children
    for (i = 0; i < NUM_CHILDREN; ++i) {
        pid = fork();
        if (pid == -1) {
            perror("fork");
            exit(EXIT_FAILURE);
        }

        if (pid == 0) { // Child process
            char child_char = '0' + i; // '0' for child 0, '1' for child 1
            memset(buffer, child_char, CHUNK_SIZE);
            buffer[CHUNK_SIZE] = '\0';

            // Child 0 targets offset 0, Child 1 targets offset 2
            off_t target_offset = (off_t)(i * (CHUNK_SIZE / 2)); 

            // Critical section: lseek + write
            lseek(fd, target_offset, SEEK_SET); 
            usleep(10000); // Small delay to increase chance of interleaving
            write(fd, buffer, CHUNK_SIZE);

            close(fd); // Child closes its copy of the file descriptor
            exit(EXIT_SUCCESS);
        }
    }

    // Parent also writes
    char parent_char = 'P';
    memset(buffer, parent_char, CHUNK_SIZE);
    buffer[CHUNK_SIZE] = '\0';

    // Parent targets offset 4
    off_t parent_target_offset = (off_t)(NUM_CHILDREN * (CHUNK_SIZE / 2)); 

    // Critical section: lseek + write
    lseek(fd, parent_target_offset, SEEK_SET); 
    usleep(10000); // Small delay to increase chance of interleaving
    write(fd, buffer, CHUNK_SIZE);

    // Parent waits for children to finish
    for (i = 0; i < NUM_CHILDREN; ++i) {
        wait(NULL);
    }

    close(fd); // Parent closes its copy of the file descriptor

    // Read and print final file content
    fd = open(FILENAME, O_RDONLY);
    if (fd == -1) {
        perror("open for read");
        exit(EXIT_FAILURE);
    }

    char final_content[FILE_LENGTH + 1];
    ssize_t bytes_read = read(fd, final_content, FILE_LENGTH);
    if (bytes_read == -1) {
        perror("read final");
        exit(EXIT_FAILURE);
    }
    final_content[bytes_read] = '\0'; // Null-terminate

    printf("Final file content: '%s'\n", final_content);

    close(fd);
    unlink(FILENAME); // Clean up the file

    return 0;
}

