#include <stdio.h>
#include <stdbool.h>

// Represents a simplified Process Control Block (PCB)
typedef struct {
    int pid;
    int burst_time;
    int priority; // Higher number = higher priority
    int remaining_time;
} PCB;

// Global variables simulating current running process state
int current_running_pid = -1;
int context_switches_count = 0;

// Simulates a scheduler's decision for one time unit
// Assumes all processes arrive at time 0.
void schedule_and_run_unit(PCB processes[], int num_processes) {
    int chosen_idx = -1;
    int highest_priority_found = -1;

    // Find the highest priority ready process
    for (int i = 0; i < num_processes; ++i) {
        if (processes[i].remaining_time > 0) { // Process is not finished
            if (chosen_idx == -1 || // First ready process found
                processes[i].priority > highest_priority_found ||
                (processes[i].priority == highest_priority_found && processes[i].pid < processes[chosen_idx].pid)) { // Tie-breaking: lower PID

highest_priority_found = processes[i].priority;
                chosen_idx = i;
            }
        }
    }

    if (chosen_idx != -1) {
        if (processes[chosen_idx].pid != current_running_pid) {
            // Context switch occurred
            if (current_running_pid != -1) { // Only count if there was a previous process running
                context_switches_count++;
            }
            current_running_pid = processes[chosen_idx].pid;
        }
        processes[chosen_idx].remaining_time--; // Run for one unit
    }
}

int main() {
    PCB processes[3] = {
        {.pid = 1, .burst_time = 5, .priority = 2, .remaining_time = 5}, 
        {.pid = 2, .burst_time = 3, .priority = 3, .remaining_time = 3},
        {.pid = 3, .burst_time = 4, .priority = 1, .remaining_time = 4}
    };
    int num_processes = 3;

    int total_finished_processes = 0;
    while (total_finished_processes < num_processes) {
        schedule_and_run_unit(processes, num_processes);

        total_finished_processes = 0;
        for (int i = 0; i < num_processes; ++i) {
            if (processes[i].remaining_time == 0) {
                total_finished_processes++;
            }
        }
    }
    return 0;
}

