// Function to simulate CPU-bound work
void do_cpu_work(long iterations) {
    volatile long i; // volatile to prevent aggressive compiler optimization
    for (i = 0; i < iterations; ++i);
}

void child_task(int id) {
    for (int i = 0; i < 3; ++i) {
        printf("Child %d: Step %d\n", id, i);
        do_cpu_work(50000000); // More significant CPU work
    }
