    pid_t p1, p2, p3;

    printf("Parent: Starting\n");
    do_cpu_work(10000000); // Parent initial work

    p1 = fork();
    if (p1 == 0) { // Child 1
        child_task(1);
    } else {
        p2 = fork();
        if (p2 == 0) { // Child 2
            char *args[] = {"echo", "Child 2 execs: Hello from exec!", NULL};
            execvp(args[0], args);
            perror("execvp failed"); // Should not reach here
            exit(1);
        } else {
            p3 = fork();
            if (p3 == 0) { // Child 3
                child_task(3);
            } else { // Parent
                do_cpu_work(10000000); // Parent work after forks
                printf("Parent: All children forked.\n");

                // Parent waits for children
                waitpid(p1, NULL, 0);
                waitpid(p2, NULL, 0);
                waitpid(p3, NULL, 0);
                printf("Parent: All children finished.\n");
            }
        }
    }
    return 0;
}

