#include <sys/types.h>
#include <errno.h>
#include <sys/resource.h> // For setpriority() and getpriority()

#define NUM_CHILDREN 3
#define WORK_ITERATIONS 1000000000LL // Use LL for long long literal

void child_work(int child_id, int nice_val) {
    printf("Child %d (PID: %d, nice: %d) starting work...\n", child_id, getpid(), nice_val);
    long long sum = 0;
    for (long long i = 0; i < WORK_ITERATIONS; ++i) {
        sum += i; // Simple CPU-bound operation
    }
    // To prevent compiler optimizing sum away if not used
    volatile long long dummy_sum = sum; 
    (void)dummy_sum; // Suppress unused variable warning

    printf("Child %d (PID: %d, nice: %d) finished work.\n", child_id, getpid(), nice_val);
    exit(0);
}

int main() {
    setbuf(stdout, NULL); // Unbuffered output

    int nice_values[NUM_CHILDREN] = {0, 10, -5}; // Desired nice values
    pid_t pids[NUM_CHILDREN];
    int i;

    printf("Parent (PID: %d) starting.\n", getpid());

    for (i = 0; i < NUM_CHILDREN; ++i) {
        pids[i] = fork();

        if (pids[i] < 0) {
            perror("fork failed");
            exit(1);
        } else if (pids[i] == 0) { // Child process
            int ret = setpriority(PRIO_PROCESS, 0, nice_values[i]); // 0 means current process
            if (ret == -1) {
                // If setpriority fails, it usually means permissions. For exam, assume success.
                perror("setpriority failed"); 
            }
            child_work(i, nice_values[i]); // Pass the set nice value
        }
    }

    // Parent waits for all children to finish
    for (i = 0; i < NUM_CHILDREN; ++i) {
        wait(NULL);
    }

    printf("Parent (PID: %d) finished.\n", getpid());
    return 0;
}
