#include <pthread.h>
#include <stdio.h>
#include <unistd.h>

#define MAX_VAL 5

int shared_counter = 0;
pthread_mutex_t mtx;
pthread_cond_t cond_full;   // Condition for counter reaching MAX_VAL
pthread_cond_t cond_empty;  // Condition for counter being reset

// Thread type 1: Increments shared_counter
void* incrementer(void* arg) {
    for (int i = 0; i < 3; ++i) { // Each incrementer tries 3 times
        pthread_mutex_lock(&mtx);
        while (shared_counter == MAX_VAL) { // Wait if counter is full
            pthread_cond_wait(&cond_empty, &mtx);
        }
        shared_counter++;
        printf("Incrementer: shared_counter = %d\n", shared_counter);
        if (shared_counter == MAX_VAL) { // If counter is full, signal the watcher
            pthread_cond_signal(&cond_full);
        }
        pthread_mutex_unlock(&mtx);
        // Simulate some work outside mutex
        usleep(50000);
    }
    return NULL;
}

// Thread type 2: Watches for counter to be full, then resets it
void* watcher(void* arg) {
    for (int i = 0; i < 2; ++i) { // Watcher resets twice
        pthread_mutex_lock(&mtx);
        while (shared_counter < MAX_VAL) { // Wait until counter is full
            pthread_cond_wait(&cond_full, &mtx);
        }
        printf("Watcher: Resetting shared_counter from %d to 0\n", shared_counter);
        shared_counter = 0;
        // This is the critical line for the question:
        pthread_cond_signal(&cond_empty); // Signalling only one waiting incrementer
        pthread_mutex_unlock(&mtx);
        // Simulate some work outside mutex
        usleep(100000);
    }
    return NULL;
}

int main() {
    pthread_t inc_threads[3]; // 3 incrementer threads
    pthread_t w_thread;       // 1 watcher thread

    pthread_mutex_init(&mtx, NULL);
    pthread_cond_init(&cond_full, NULL);
    pthread_cond_init(&cond_empty, NULL);

    for (int i = 0; i < 3; ++i) {
        pthread_create(&inc_threads[i], NULL, incrementer, NULL);
    }
    pthread_create(&w_thread, NULL, watcher, NULL);

    for (int i = 0; i < 3; ++i) {
        pthread_join(inc_threads[i], NULL);
    }
    pthread_join(w_thread, NULL);

    pthread_mutex_destroy(&mtx);
    pthread_cond_destroy(&cond_full);
    pthread_cond_destroy(&cond_empty);

    return 0;
}

