bool producer_done_adding = false; // דגל המציין שהיצרן סיים להוסיף פריטים

void* consumer_thread_func(void* arg) {
    pthread_mutex_lock(&mutex);
    while (true) {
        // הצרכן ממתין אם התור ריק והיצרן עדיין עשוי להוסיף פריטים
        while (shared_queue.empty() && !producer_done_adding) {
            pthread_cond_wait(&consumer_wait_cond, &mutex);
        }

        // תנאי יציאה לצרכן: התור ריק והיצרן סיים להוסיף פריטים
        if (shared_queue.empty() && producer_done_adding) {
            pthread_mutex_unlock(&mutex);
            return NULL; // הצרכן יוצא
        }

        // עיבוד פריט
        shared_queue.pop();
        items_processed++;

        // הצרכן מסמן ליצרן רק אם כל הפריטים עובדו *וגם* היצרן סיים להוסיף.
