    std::cout << "Thread B: Trying to lock m2...\n";
    m2.lock();
    std::cout << "Thread B: Locked m2, trying to lock m1...\n";
    std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Potential context switch
    m1.lock();
    std::cout << "Thread B: Locked m1.\n";
    // ... critical section ...
    m1.unlock();
    m2.unlock();
    std::cout << "Thread B: Unlocked m1 and m2.\n";
}

// Usage example:
// int main() {
//     std::thread t1(thread_func_A);
//     std::thread t2(thread_func_B);
//     t1.join();
