/* מבנה הנתונים של מנעול קוראים-כותבים הוגן */
typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t readers_cv;
    pthread_cond_t writers_cv;
    int readers_active;     // מספר הקוראים הפעילים כרגע
    int writers_active;     // 0 או 1 (רק כותב אחד בו-זמנית)
    int writers_waiting;    // מספר הכותבים הממתינים לתפוס את המנעול
    long writer_ticket_counter; // מונה גלובלי להקצאת 'כרטיסים' לכותבים
    long writer_serving_ticket; // מספר 'הכרטיס' של הכותב הבא בתור לשרת
} FairRWLock;

/* אתחול המנעול */
void init(FairRWLock *rwl) {
    pthread_mutex_init(&rwl->lock, NULL);
    pthread_cond_init(&rwl->readers_cv, NULL);
    pthread_cond_init(&rwl->writers_cv, NULL);
    rwl->readers_active = 0;
    rwl->writers_active = 0;
    rwl->writers_waiting = 0;
    rwl->writer_ticket_counter = 0;
    rwl->writer_serving_ticket = 0;
}

/* ניסיון לתפוס את המנעול לקריאה */
void read_lock(FairRWLock *rwl) {
    pthread_mutex_lock(&rwl->lock);
    // קורא ממתין אם יש כותב פעיל או כותבים שממתינים (עדיפות לכותבים)
    while (rwl->writers_active > 0 || rwl->writers_waiting > 0) {
        pthread_cond_wait(&rwl->readers_cv, &rwl->lock);
    }
    rwl->readers_active++;
    pthread_mutex_unlock(&rwl->lock);
}

/* שחרור המנעול מקריאה */
void read_unlock(FairRWLock *rwl) {
    pthread_mutex_lock(&rwl->lock);
    rwl->readers_active--;
    // אם זה הקורא האחרון וקיימים כותבים ממתינים, יש לאותת לכותבים
    if (rwl->readers_active == 0 && rwl->writers_waiting > 0) {
        pthread_cond_signal(&rwl->writers_cv);
    }
    pthread_mutex_unlock(&rwl->lock);
}

/* ניסיון לתפוס את המנעול לכתיבה */
void write_lock(FairRWLock *rwl) {
    pthread_mutex_lock(&rwl->lock);
    long my_ticket = rwl->writer_ticket_counter++; // מקבל 'כרטיס' לפי סדר הגעה
    rwl->writers_waiting++; // מגדיל את מונה הכותבים הממתינים
    // כותב ממתין אם יש קוראים פעילים, כותב פעיל, או אם זה לא תורו (FIFO)
    while (rwl->readers_active > 0 || rwl->writers_active > 0 || my_ticket != rwl->writer_serving_ticket) {
        pthread_cond_wait(&rwl->writers_cv, &rwl->lock);
    }
    rwl->writers_waiting--; // סיים להמתין, עכשיו הוא פעיל
    rwl->writers_active = 1;
    pthread_mutex_unlock(&rwl->lock);
}

/* שחרור המנעול מכתיבה */
void write_unlock(FairRWLock *rwl) {
    pthread_mutex_lock(&rwl->lock);
    rwl->writers_active = 0;
    rwl->writer_serving_ticket++; // מקדם את התור לכותב הבא
    // אם קיימים כותבים ממתינים, יש לאותת לכותב הבא בתור
    if (rwl->writers_waiting > 0) {
        pthread_cond_signal(&rwl->writers_cv);
    } 
    // אחרת, אם אין כותבים ממתינים, יש לאותת לכל הקוראים הממתינים
    else {
        pthread_cond_broadcast(&rwl->readers_cv);
    }
    pthread_mutex_unlock(&rwl->lock);
}

/* השמדת המנעול */
void destroy(FairRWLock *rwl) {
    pthread_mutex_destroy(&rwl->lock);
    pthread_cond_destroy(&rwl->readers_cv);
    pthread_cond_destroy(&rwl->writers_cv);
}

