solution.explanation:
הסבר:
המימוש יעשה שימוש ב-`pthread_mutex_t` ו-`pthread_cond_t` כדי להבטיח סנכרון נכון ולמנוע המתנה פעילה.
*   **`manager_mutex`**: מנעול יחיד זה ישמש להגנה על מבנה הנתונים של `ResourceManager`, ובעיקר על המערך `available_counts`. כל גישה או שינוי של `available_counts` תהיה מוגנת על ידי מנעול זה. זה מבטיח אטומיות בבדיקת זמינות ובהקצאת משאבים.
*   **`resources_available_cond`**: משתנה תנאי זה ישמש כדי לגרום לתהליכים להמתין ביעילות. כאשר תהליך מנסה לרכוש משאבים ומוצא שהם אינם זמינים, הוא ישחרר את ה-`manager_mutex` וימתין על משתנה התנאי. כאשר תהליך אחר משחרר משאבים, הוא יודיע לכל התהליכים הממתינים על ידי קריאה ל-`pthread_cond_broadcast`, מה שיעיר אותם כדי שיבדקו שוב את זמינות המשאבים.

**מניעת מצבי מרוץ וקיפאון:**
*   **מצבי מרוץ**: המנעול `manager_mutex` מונע מצבי מרוץ על ידי הבטחה שרק תהליך אחד יכול לבדוק ולשנות את `available_counts` בכל רגע נתון.
*   **קיפאון (Deadlock)**: בפתרון זה, קיפאון נמנע מכיוון שתהליך לעולם אינו מחזיק במשאבים חלקיים וגם ממתין למשאבים אחרים. תהליך רוכש את המנעול `manager_mutex`, בודק אם *כל* המשאבים הנדרשים זמינים.
    *   אם כן, הוא מקצה אותם (מפחית מהמונה), משחרר את המנעול וממשיך.
    *   אם לא, הוא משחרר את המנעול ומיד נכנס למצב המתנה על `resources_available_cond`. הוא לא מחזיק באף משאב (רק במנעול `manager_mutex` לזמן קצר מאוד לבדיקה), ובכך מונע מצב שבו הוא יחסום תהליכים אחרים מלהתקדם.
    *   סדר הרכישה של משאבים בתוך `acquire_resources` אינו משנה לבעיית הקיפאון, מכיוון שהבדיקה וההקצאה נעשות כולן תחת מנעול יחיד, ובאופן אטומי. אם לא ניתן להקצות את כולם, אף אחד לא מוקצה.

**הימנעות מהמתנה פעילה:**
השימוש ב-`pthread_cond_wait` מבטיח שתהליכים הממתינים למשאבים לא יבזבזו זמן מעבד על סריקה חוזרת ונשנית (spinning) אלא ייכנסו למצב שינה עד שיאותתו להם על ידי `pthread_cond_broadcast`.

```c
#include <pthread.h>
#include <stdlib.h> // For malloc, free
#include <stdio.h>  // For printf (optional, for debugging)
#include <string.h> // For memcpy

// Represents a request for resources.
// resource_id_to_count[i] specifies the number of units required for resource type i.
typedef struct {
    int K; // Number of resource types
    int *resource_id_to_count; // Array of size K
} ResourceRequest;

// The resource manager structure
typedef struct {
    int K; // Number of resource types
    int *available_counts; // Array of size K, current available units for each type
    pthread_mutex_t manager_mutex;
    pthread_cond_t resources_available_cond;
} ResourceManager;

// Initializes the resource manager
void init_resource_manager(ResourceManager *manager, int K, const int *initial_counts) {
    manager->K = K;
    manager->available_counts = (int*) malloc(sizeof(int) * K);
    if (manager->available_counts == NULL) {
        perror("malloc failed for available_counts");
        exit(EXIT_FAILURE);
    }
    memcpy(manager->available_counts, initial_counts, sizeof(int) * K);

    pthread_mutex_init(&manager->manager_mutex, NULL);
    pthread_cond_init(&manager->resources_available_cond, NULL);
}

// Destroys the resource manager
void destroy_resource_manager(ResourceManager *manager) {
    free(manager->available_counts);
    pthread_mutex_destroy(&manager->manager_mutex);
    pthread_cond_destroy(&manager->resources_available_cond);
}

// Helper function to check if all resources in a request are available
static int check_availability(ResourceManager *manager, const ResourceRequest *request) {
    for (int i = 0; i < manager->K; ++i) {
        if (request->resource_id_to_count[i] > 0 && 
            manager->available_counts[i] < request->resource_id_to_count[i]) {
            return 0; // Not all resources are available
        }
    }
    return 1; // All resources are available
}

// Acquires all resources specified in the request atomically.
// If not all resources are available, the calling thread waits.
void acquire_resources(ResourceManager *manager, const ResourceRequest *request) {
    pthread_mutex_lock(&manager->manager_mutex);

    while (!check_availability(manager, request)) {
        // Resources not available, wait for a signal
        pthread_cond_wait(&manager->resources_available_cond, &manager->manager_mutex);
    }

    // Resources are available, acquire them
    for (int i = 0; i < manager->K; ++i) {
        if (request->resource_id_to_count[i] > 0) {
            manager->available_counts[i] -= request->resource_id_to_count[i];
        }
    }

    pthread_mutex_unlock(&manager->manager_mutex);
}

// Releases all resources specified in the request.
void release_resources(ResourceManager *manager, const ResourceRequest *request) {
    pthread_mutex_lock(&manager->manager_mutex);

    // Release resources
    for (int i = 0; i < manager->K; ++i) {
        if (request->resource_id_to_count[i] > 0) {
            manager->available_counts[i] += request->resource_id_to_count[i];
        }
    }

    // Notify all waiting threads that resources might now be available
    pthread_cond_broadcast(&manager->resources_available_cond);

    pthread_mutex_unlock(&manager->manager_mutex);
}

// Helper function to create a ResourceRequest (optional, for testing)
ResourceRequest* create_request(int K, const int *counts) {
    ResourceRequest *req = (ResourceRequest*) malloc(sizeof(ResourceRequest));
    if (req == NULL) {
        perror("malloc failed for ResourceRequest");
        exit(EXIT_FAILURE);
    }
    req->K = K;
    req->resource_id_to_count = (int*) malloc(sizeof(int) * K);
    if (req->resource_id_to_count == NULL) {
        perror("malloc failed for resource_id_to_count in request");
        free(req);
        exit(EXIT_FAILURE);
    }
    memcpy(req->resource_id_to_count, counts, sizeof(int) * K);
    return req;
}

// Helper function to destroy a ResourceRequest (optional, for testing)
void destroy_request(ResourceRequest *request) {
    free(request->resource_id_to_count);
    free(request);
}
```

