typedef struct __FairMutex {
    // השלימו את המבנה
} FairMutex;

void fair_mutex_init(FairMutex *fm);
void fair_mutex_destroy(FairMutex *fm);
void fair_mutex_lock(FairMutex *fm);
void fair_mutex_unlock(FairMutex *fm);

solution.explanation:
לשם מימוש מנעול הוגן, נשתמש בגישת ה"כרטיסים" (tickets). כל חוט שמבקש לרכוש את המנעול מקבל מספר כרטיס ייחודי, והחוטים רוכשים את המנעול לפי הסדר העולה של מספרי הכרטיסים שלהם. נשתמש בשני מונים: `next_ticket` שיקצה את הכרטיס הבא לחוט שמבקש את המנעול, ו-`current_serving_ticket` שיציין איזה כרטיס תורו להיכנס למקטע הקריטי.

המבנה `FairMutex` יכלול:
*   `pthread_mutex_t guard_mutex`: מנעול פנימי שיגן על הגישה למונים (`next_ticket`, `current_serving_ticket`) ולמשתנה התנאי. זהו מנעול קצר-טווח שנועד להבטיח אטומיות בגישה למשתני המצב של המנעול ההוגן עצמו.
*   `pthread_cond_t cond_var`: משתנה תנאי שעליו ימתינו חוטים שתורם עדיין לא הגיע.
*   `int next_ticket`: מונה עולה שמקצה כרטיסים לחוטים המבקשים את המנעול.
*   `int current_serving_ticket`: מונה עולה שמציין את מספר הכרטיס של החוט שתורו להיכנס למקטע הקריטי או של החוט שמחזיק כרגע את המנעול.

**פעולת `fair_mutex_init`:**
מאתחלת את המנעולים והמונים לערכי ההתחלה שלהם.

**פעולת `fair_mutex_destroy`:**
משחררת את המשאבים של המנעולים והמשתנים התנאיים.

**פעולת `fair_mutex_lock`:**
1.  החוט רוכש את ה-`guard_mutex` כדי לגשת בבטחה למשתני המצב של המנעול ההוגן.
2.  הוא מקבל כרטיס ייחודי על ידי העתקת הערך הנוכחי של `next_ticket` והגדלתו (`my_ticket = fm->next_ticket++;`).
3.  החוט נכנס ללולאת המתנה: כל עוד מספר הכרטיס שלו (`my_ticket`) אינו שווה ל-`current_serving_ticket`, הוא ממתין על `cond_var`. המתנה זו משחררת אוטומטית את `guard_mutex` ומחזירה אותו כשהחוט מתעורר.
4.  כאשר `my_ticket == fm->current_serving_ticket`, החוט יודע שתורו הגיע, והוא "רוכש" את המנעול ההוגן. הוא יוצא מלולאת ההמתנה.
5.  החוט משחרר את ה-`guard_mutex` וממשיך בביצוע המקטע הקריטי.

**פעולת `fair_mutex_unlock`:**
1.  החוט רוכש את ה-`guard_mutex`.
2.  הוא מגדיל את `current_serving_ticket` ב-1. פעולה זו למעשה מעבירה את ה"תור" לחוט הבא בתור.
3.  הוא מאותת לחוט אחד שממתין על `cond_var` (`pthread_cond_signal`). חוט זה (אם קיים) יתעורר, יבדוק את התנאי (`my_ticket == fm->current_serving_ticket`), יגלה שתורו הגיע, וירכוש את המנעול.
4.  החוט משחרר את ה-`guard_mutex`.

```c
#include <pthread.h>
#include <stdlib.h> // For malloc/free

typedef struct __FairMutex {
    pthread_mutex_t guard_mutex;
    pthread_cond_t  cond_var;
    int             next_ticket;
    int             current_serving_ticket;
} FairMutex;

void fair_mutex_init(FairMutex *fm) {
    pthread_mutex_init(&fm->guard_mutex, NULL);
    pthread_cond_init(&fm->cond_var, NULL);
    fm->next_ticket = 0;
    fm->current_serving_ticket = 0;
}

void fair_mutex_destroy(FairMutex *fm) {
    pthread_mutex_destroy(&fm->guard_mutex);
    pthread_cond_destroy(&fm->cond_var);
}

void fair_mutex_lock(FairMutex *fm) {
    pthread_mutex_lock(&fm->guard_mutex);
    int my_ticket = fm->next_ticket++;
    while (my_ticket != fm->current_serving_ticket) {
        pthread_cond_wait(&fm->cond_var, &fm->guard_mutex);
    }
    pthread_mutex_unlock(&fm->guard_mutex);
}

void fair_mutex_unlock(FairMutex *fm) {
    pthread_mutex_lock(&fm->guard_mutex);
    fm->current_serving_ticket++;
    pthread_cond_signal(&fm->cond_var); // Signal one waiting thread
    pthread_mutex_unlock(&fm->guard_mutex);
}
```

