    int local_val = shared_value; // קריאה של הערך המשותף
    local_val = local_val + 1;    // הגדלה מקומית
    shared_value = local_val;     // כתיבה חזרה לערך המשותף
    return NULL;
}

int main() {
    pthread_t t1, t2;

    pthread_create(&t1, NULL, my_thread_func, NULL);
    pthread_create(&t2, NULL, my_thread_func, NULL);

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    printf("Final shared_value: %d\n", shared_value);

    return 0;
}

