#include <stdio.h>
#include <pthread.h>

#define NUM_THREADS 4 // מספר החוטים הכולל
#define INCREMENTS_PER_THREAD 100000 // מספר ההגדלות שכל חוט מבצע

int counter = 0; // המונה הגלובלי המשותף
pthread_mutex_t mutex; // אובייקט ה-mutex לסנכרון

// פונקציית חוט המבצעת הגדלה בטוחה (עם mutex)
void* thread_func_safe(void* arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        pthread_mutex_lock(&mutex); // נעל את ה-mutex
        counter++; // הגדל את המונה
        pthread_mutex_unlock(&mutex); // שחרר את ה-mutex
    }
    return NULL;
}

// פונקציית חוט המבצעת הגדלה לא בטוחה (ללא mutex)
void* thread_func_unsafe(void* arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        counter++; // הגדל את המונה - מצב מרוץ!
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS]; // מערך לטיפול בחוטים
    pthread_mutex_init(&mutex, NULL); // אתחל את ה-mutex

    // צור חצי מהחוטים כחוטים בטוחים (עם mutex)
    for (int i = 0; i < NUM_THREADS / 2; ++i) {
        pthread_create(&threads[i], NULL, thread_func_safe, NULL);
    }
    // צור את החצי השני כחוטים לא בטוחים (ללא mutex)
    for (int i = NUM_THREADS / 2; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, thread_func_unsafe, NULL);
    }

    // המתן לסיום כל החוטים
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final counter value: %d\n", counter); // הדפס את הערך הסופי של המונה

    pthread_mutex_destroy(&mutex); // השמד את ה-mutex
    return 0;
}

#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define NUM_THREADS 5
#define MAX_INCREMENTS 3 // Semaphore initial value

int shared_counter = 0;
pthread_mutex_t mutex;
sem_t limit_sem; // Limits how many times shared_counter can be incremented

void* thread_func(void* arg) {
    long thread_id = (long)arg;

    printf("Thread %ld trying to increment...\n", thread_id);

    // Try to acquire permission to increment
    if (sem_trywait(&limit_sem) == 0) { // Non-blocking attempt
        pthread_mutex_lock(&mutex);
        shared_counter++;
        printf("Thread %ld successfully incremented counter to %d\n", thread_id, shared_counter);
        pthread_mutex_unlock(&mutex);
        // The semaphore is not released by this thread, as it limits total increments
    } else {
        printf("Thread %ld failed to acquire increment permission.\n", thread_id);
    }

    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    pthread_mutex_init(&mutex, NULL);
    sem_init(&limit_sem, 0, MAX_INCREMENTS); // Initialize semaphore to MAX_INCREMENTS

    for (long i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, thread_func, (void*)i);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final shared_counter value: %d\n", shared_counter);

    pthread_mutex_destroy(&mutex);
    sem_destroy(&limit_sem);

    return 0;
}

content.text:
נתונה מערכת המורכבת מ-N חוטי עובד (workers) וחוט מתאם (coordinator) יחיד. חוטי העובד מבצעים משימות, כאשר כל משימה מקדמת מונה גלובלי `task_count`. כאשר `task_count` מגיע לערך סף `BATCH_SIZE`, חוט המתאם אמור להתעורר, לבצע עיבוד אצווה (batch processing) ולאפס את `task_count`. חוטי העובד צריכים להמתין שהמתאם יסיים את עיבוד האצווה לפני שימשיכו לבצע משימות נוספות עבור האצווה הבאה.
להלן קוד C המממש את המערכת, אך הוא מכיל שגיאות תזמון (concurrency bugs):

```c
#include <stdio.h>
#include <pthread.h>
#include <unistd.h> // for sleep

#define NUM_WORKERS 3
#define TASKS_PER_WORKER 2 // כל עובד מבצע 2 משימות
#define BATCH_SIZE 5      // מתאם מעבד כאשר task_count מגיע לערך זה

int task_count = 0;
pthread_mutex_t mutex;
pthread_cond_t workers_cond;     // עובדים ממתינים על משתנה תנאי זה
pthread_cond_t coordinator_cond; // מתאם ממתין על משתנה תנאי זה

int coordinator_is_processing = 0; // דגל המציין אם המתאם עסוק בעיבוד

void* worker_thread(void* arg) {
    long id = (long)arg;
    for (int i = 0; i < TASKS_PER_WORKER; ++i) {
        pthread_mutex_lock(&mutex);

        // BUG: חוטים לא ממתינים אם task_count כבר הגיע ל-BATCH_SIZE
        // או אם המתאם כבר בעיצומו של עיבוד, והם עלולים לקדם את המונה מעבר ל-BATCH_SIZE.

        task_count++;
        printf("Worker %ld: task_count = %d\n", id, task_count);

        if (task_count == BATCH_SIZE) {
            coordinator_is_processing = 1; // סמן שהמתאם עסוק
            printf("Worker %ld: Signalling coordinator to process batch.\n", id);
            pthread_cond_signal(&coordinator_cond); // אותת למתאם להתחיל בעיבוד
        }

        pthread_mutex_unlock(&mutex);
        usleep(100000 + (id * 10000)); // הדמיית עבודה
    }
    return NULL;
}

void* coordinator_thread(void* arg) {
    int batches_processed = 0;
    int total_tasks = NUM_WORKERS * TASKS_PER_WORKER;
    int max_expected_batches = (total_tasks + BATCH_SIZE - 1) / BATCH_SIZE; // חישוב מספר האצוות המקסימלי
    if (max_expected_batches == 0) max_expected_batches = 1;

    while (batches_processed < max_expected_batches + NUM_WORKERS) { // +NUM_WORKERS למרווח ביטחון
        pthread_mutex_lock(&mutex);

        // המתאם ממתין עד ש-task_count מגיע ל-BATCH_SIZE ודגל העיבוד מסומן
        while (task_count < BATCH_SIZE || !coordinator_is_processing) {
            pthread_cond_wait(&coordinator_cond, &mutex);
        }

        printf("Coordinator: BATCH_SIZE reached, processing batch %d...\n", batches_processed + 1);
        pthread_mutex_unlock(&mutex); // שחרר מנעול בזמן עיבוד ארוך
        sleep(1); // הדמיית עיבוד אצווה
        pthread_mutex_lock(&mutex);

        task_count = 0; // אפס את מונה המשימות
        coordinator_is_processing = 0; // המתאם סיים עיבוד
        batches_processed++;
        printf("Coordinator: Batch %d processing finished, task_count reset.\n", batches_processed);

        pthread_cond_broadcast(&workers_cond); // העיר את כל חוטי העובד הממתינים
        pthread_mutex_unlock(&mutex);
        usleep(50000); // השהייה קלה לפני בדיקת המחזור הבא
    }
    printf("Coordinator: Finished all expected batches and exiting.\n");
    return NULL;
}

int main() {
    pthread_t workers[NUM_WORKERS];
    pthread_t coordinator;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&workers_cond, NULL);
    pthread_cond_init(&coordinator_cond, NULL);

    for (long i = 0; i < NUM_WORKERS; ++i) {
        pthread_create(&workers[i], NULL, worker_thread, (void*)i);
    }
    pthread_create(&coordinator, NULL, coordinator_thread, NULL);

    for (int i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(workers[i], NULL);
    }
    pthread_join(coordinator, NULL); // המתן למתאם שיסיים

    printf("Main: All threads finished. Final task_count = %d\n", task_count);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&workers_cond);
    pthread_cond_destroy(&coordinator_cond);

    return 0;
}
```

