#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For usleep

#define NUM_WORKERS 5 
#define NUM_STATIONS 5 

sem_t station_mutex[NUM_STATIONS]; // One mutex per station

void* worker_task(void* arg) {
    long worker_id = (long)arg;
    int station1_idx = worker_id;
    int station2_idx = (worker_id + 1) % NUM_STATIONS;

    printf("Worker %ld trying to acquire station %d and %d\n", worker_id, station1_idx, station2_idx);

    // Acquire resources
    sem_wait(&station_mutex[station1_idx]);
    printf("Worker %ld acquired station %d\n", worker_id, station1_idx);

    // Simulate some delay between acquisitions to increase deadlock probability
    usleep(1000 * ((worker_id + 1) % 3)); 

    sem_wait(&station_mutex[station2_idx]);
    printf("Worker %ld acquired station %d and %d. Performing task...\n", worker_id, station1_idx, station2_idx);

    // Simulate task execution
    usleep(50000);

    printf("Worker %ld releasing station %d and %d\n", worker_id, station1_idx, station2_idx);
    sem_post(&station_mutex[station2_idx]);
    sem_post(&station_mutex[station1_idx]);

    return NULL;
}

int main() {
    // Initialize semaphores
    for (int i = 0; i < NUM_STATIONS; ++i) {
        sem_init(&station_mutex[i], 0, 1); // 0 for shared between threads in same process, 1 for initial value
    }

    pthread_t workers[NUM_WORKERS];

    // Create worker threads
    for (long i = 0; i < NUM_WORKERS; ++i) {
        pthread_create(&workers[i], NULL, worker_task, (void*)i);
    }

    // Join worker threads
    for (int i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(workers[i], NULL);
    }

    printf("All workers finished.\n");

    // Destroy semaphores
    for (int i = 0; i < NUM_STATIONS; ++i) {
        sem_destroy(&station_mutex[i]);
    }

    return 0;
}

