content.text:
נתונה מערכת המנהלת N משאבים מסוג `long`, המיוצגים על ידי המערך `resources[N]`. כל משאב `resources[i]` מוגן על ידי מנעול ייעודי `resource_mutexes[i]`. בנוסף, קיים משתנה גלובלי `global_total_value` המייצג את סכום כל המשאבים במערכת (כלומר, `global_total_value == sum(resources[i])`). משתנה זה מוגן על ידי המנעול `total_value_mutex`.

להלן שתי פונקציות המבצעות פעולות על המערכת:

1.  `update_resource(int id, long new_value)`: מעדכנת את הערך של משאב בודד `resources[id]` ל-`new_value` ומתאימה את `global_total_value` בהתאם.
2.  `transfer_value(int from_id, int to_id, long amount)`: מעבירה `amount` מ-`resources[from_id]` ל-`resources[to_id]`. הפונקציה אינה אמורה לשנות את `global_total_value`.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define NUM_RESOURCES 5

long resources[NUM_RESOURCES];
pthread_mutex_t resource_mutexes[NUM_RESOURCES];
long global_total_value = 0;
pthread_mutex_t total_value_mutex;

void initialize_system() {
    for (int i = 0; i < NUM_RESOURCES; ++i) {
        resources[i] = i * 100;
        global_total_value += resources[i];
        pthread_mutex_init(&resource_mutexes[i], NULL);
    }
    pthread_mutex_init(&total_value_mutex, NULL);
}

// Function A: Updates a single resource and reflects change in global_total_value
void update_resource(int id, long new_value) {
    if (id < 0 || id >= NUM_RESOURCES) return;

    pthread_mutex_lock(&resource_mutexes[id]); // Lock M_id
    pthread_mutex_lock(&total_value_mutex);    // Lock M_total

    long old_value = resources[id];
    resources[id] = new_value;
    global_total_value = global_total_value - old_value + new_value;

    pthread_mutex_unlock(&total_value_mutex);
    pthread_mutex_unlock(&resource_mutexes[id]);
}

// Function B: Transfers value between two resources.
void transfer_value(int from_id, int to_id, long amount) {
    if (from_id == to_id || from_id < 0 || from_id >= NUM_RESOURCES || to_id < 0 || to_id >= NUM_RESOURCES) {
        return;
    }

    pthread_mutex_lock(&total_value_mutex);            // Lock M_total
    pthread_mutex_lock(&resource_mutexes[from_id]);    // Lock M_from_id
    pthread_mutex_lock(&resource_mutexes[to_id]);      // Lock M_to_id

    resources[from_id] -= amount;
    resources[to_id] += amount;

    pthread_mutex_unlock(&resource_mutexes[to_id]);
    pthread_mutex_unlock(&resource_mutexes[from_id]);
    pthread_mutex_unlock(&total_value_mutex);
}
```

