void initialize_global_resource() {
    // הדמיית לוגיקת אתחול מורכבת ואיטית
    usleep(100000); // 100ms
    int* temp_ptr = (int*)malloc(sizeof(int));
    if (temp_ptr != NULL) {
        *temp_ptr = 123; // אתחול הערך
    }
    g_resource_ptr = temp_ptr; // השמת המצביע למשאב הגלובלי
    // פה טמונה הבעיה הפוטנציאלית: g_initialized יכול להיכתב לפני ש-g_resource_ptr
    // באמת מצביע לזיכרון תקין באופן גלוי לכל התהליכונים, עקב אופטימיזציות מעבד/קומפיילר.
