#include <stdio.h>
#include <pthread.h>

#define MAX_VALUE 10
int shared_counter = 0;
pthread_mutex_t m;

void* thread_func(void* arg) {
    for (int i = 0; i < 100000; ++i) {
        pthread_mutex_lock(&m); // Lock 1
        int current_value = shared_counter; // Read shared_counter
        pthread_mutex_unlock(&m); // Unlock 1 - DANGER ZONE

        // At this point, current_value holds a potentially stale value.
        // Another thread could increment shared_counter between the unlock and the next lock.

        if (current_value < MAX_VALUE) { // Check based on potentially stale value
            pthread_mutex_lock(&m); // Lock 2
            // The condition (shared_counter < MAX_VALUE) might no longer be true
            // but this thread will increment regardless because it passed the check outside the critical section.
            shared_counter++; // Act
            pthread_mutex_unlock(&m); // Unlock 2
        }
    }
    return NULL;
}

int main() {
    pthread_t t1, t2;
    pthread_mutex_init(&m, NULL);
    pthread_create(&t1, NULL, thread_func, NULL);
    pthread_create(&t2, NULL, thread_func, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("Final counter: %d\n", shared_counter);
    pthread_mutex_destroy(&m);
    return 0;
}

