#include <iostream>
#include <pthread.h>
#include <unistd.h> // For sleep, though not strictly necessary for the race condition itself

int shared_counter = 0;
const int ITERATIONS = 100000;

void* increment_thread(void* arg) {
    for (int i = 0; i < ITERATIONS; ++i) {
        shared_counter++;
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_create(&tid1, NULL, increment_thread, NULL);
    pthread_create(&tid2, NULL, increment_thread, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    std::cout << "Final counter value: " << shared_counter << std::endl;

    return 0;
}

solution.explanation:
פתרון:

**1.1. זיהוי והסבר תנאי המירוץ (Race Condition):**
תנאי המירוץ מתרחש סביב המשתנה הגלובלי המשותף `shared_counter`. שני התהליכונים ניגשים למשתנה זה ומבצעים עליו פעולת הגדלה (`shared_counter++`) ללא כל מנגנון סנכרון. פעולת ההגדלה אינה אטומית ברמת המעבד (CPU), אלא מורכבת מכמה שלבים:
א. קריאת הערך הנוכחי של `shared_counter` מהזיכרון לרגיסטר של המעבד.
ב. הגדלת הערך ברגיסטר באחד.
ג. כתיבת הערך המעודכן מהרגיסטר בחזרה לזיכרון.
כאשר שני תהליכונים מבצעים את הרצף הזה במקביל, סדר הפעולות יכול להשתנות באופן לא-דטרמיניסטי, מה שעלול להוביל לאובדן עדכונים ולתוצאה שגויה.

**1.2. דוגמה לרצף פעולות שגוי:**
נניח ש-`shared_counter` שווה ל-0. התוצאה הצפויה לאחר ששני התהליכונים יסיימו את כל האיטרציות היא 2 * 100,000 = 200,000.
הנה רצף פעולות אפשרי שיוביל לתוצאה שגויה:

*   **תהליכון 1:** קורא את `shared_counter` (ערך = 0) לרגיסטר שלו.
*   **תהליכון 2:** קורא את `shared_counter` (ערך = 0) לרגיסטר שלו.
*   **תהליכון 1:** מגדיל את הערך ברגיסטר שלו (0 + 1 = 1).
*   **תהליכון 2:** מגדיל את הערך ברגיסטר שלו (0 + 1 = 1).
*   **תהליכון 1:** כותב את הערך המעודכן (1) בחזרה ל-`shared_counter`. כעת `shared_counter = 1`.
*   **תהליכון 2:** כותב את הערך המעודכן (1) בחזרה ל-`shared_counter`. כעת `shared_counter = 1`.

במקרה זה, למרות ששני התהליכונים ביצעו פעולת הגדלה, המונה הוגדל רק פעם אחת בפועל במקום פעמיים, וכך אבד עדכון אחד. רצף כזה יתרחש פעמים רבות במהלך 200,000 ההגדלות, ולכן התוצאה הסופית של `shared_counter` תהיה נמוכה מ-200,000.

**1.3. פתרון קוד באמצעות Mutexes:**

```c
#include <iostream>
#include <pthread.h>

int shared_counter = 0;
const int ITERATIONS = 100000;
pthread_mutex_t counter_mutex; // הצהרה על mutex

void* increment_thread_safe(void* arg) {
    for (int i = 0; i < ITERATIONS; ++i) {
        pthread_mutex_lock(&counter_mutex);   // נעילת ה-mutex
        shared_counter++;                     // קטע קריטי - גישה למשתנה המשותף
        pthread_mutex_unlock(&counter_mutex); // שחרור ה-mutex
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_mutex_init(&counter_mutex, NULL); // אתחול ה-mutex

    pthread_create(&tid1, NULL, increment_thread_safe, NULL);
    pthread_create(&tid2, NULL, increment_thread_safe, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    std::cout << "Final counter value: " << shared_counter << std::endl;

    pthread_mutex_destroy(&counter_mutex); // השמדת ה-mutex

    return 0;
}
```

**הסבר הפתרון:**
הפתרון מונע את תנאי המירוץ על ידי הגנה על הקטע הקריטי (הגישה למשתנה `shared_counter`) באמצעות `mutex` (קיצור של Mutual Exclusion).
1.  **`pthread_mutex_t counter_mutex;`**: מצהירים על משתנה מסוג `pthread_mutex_t` שישמש כמנעול.
2.  **`pthread_mutex_init(&counter_mutex, NULL);`**: מאתחלים את ה-mutex לפני יצירת התהליכונים. זה מכין את המנעול לשימוש.
3.  **`pthread_mutex_lock(&counter_mutex);`**: לפני שכל תהליכון ניגש למשתנה המשותף `shared_counter` (כלומר, לפני הקטע הקריטי), הוא מנסה לנעול את ה-mutex. אם ה-mutex כבר נעול על ידי תהליכון אחר, התהליכון הנוכחי נחסם וממתין עד שה-mutex ישוחרר. רק תהליכון אחד יכול להחזיק במנעול בכל רגע נתון.
4.  **`shared_counter++;`**: זוהי הפעולה בקטע הקריטי. מכיוון שהיא מוגנת על ידי ה-mutex, מובטח שרק תהליכון אחד יבצע אותה בכל רגע נתון. זה מבטיח שאף אובדן עדכונים לא יתרחש כתוצאה מהפרעות של תהליכונים אחרים.
5.  **`pthread_mutex_unlock(&counter_mutex);`**: לאחר שחרור ה-mutex, תהליכונים אחרים שממתינים יכולים כעת לנסות לנעול אותו ולהיכנס לקטע הקריטי.
6.  **`pthread_mutex_destroy(&counter_mutex);`**: משחרר את המשאבים שהוקצו ל-mutex בסיום התוכנית.

על ידי שימוש ב-mutex, אנו מבטיחים שכל פעולת `shared_counter++` תתבצע באופן בלעדי על ידי תהליכון אחד בכל פעם, וכך נמנעים תנאי המירוץ ואובדן עדכונים. התוצאה הסופית של `shared_counter` תהיה תמיד 200,000.

