    printf("Initial shared_counter value: %lld\n", shared_counter);

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, increment_counter, NULL) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            exit(EXIT_FAILURE);
        }
    }

    printf("Final shared_counter value: %lld\n", shared_counter);
    printf("Expected shared_counter value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

    return 0;
