#include <stdio.h>
#include <pthread.h>

int shared_counter = 0; // Global shared resource

void* incrementer(void* arg) {
    for (int i = 0; i < 100000; i++) {
        shared_counter++;
    }
    return NULL;
}

void* decrementer(void* arg) {
    for (int i = 0; i < 100000; i++) {
        shared_counter--;
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_create(&tid1, NULL, incrementer, NULL);
    pthread_create(&tid2, NULL, decrementer, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    printf("Final value of shared_counter: %d\n", shared_counter);

    return 0;
}

solution.explanation:
1. **זיהוי מצב מרוץ:** כן, קטע הקוד סובל ממצב מרוץ (Race Condition). הפעולות `shared_counter++` ו-`shared_counter--` אינן אטומיות. כל אחת מהן מורכבת משלושה שלבים:
    א. קריאת הערך הנוכחי של `shared_counter` מהזיכרון.
    ב. ביצוע פעולת החיבור/חיסור על הערך שנשמר באוגר (CPU register).
    ג. כתיבת הערך המעודכן בחזרה לזיכרון.

    כאשר שני תהליכונים מבצעים פעולות אלו במקביל, סדר הביצוע של השלבים הללו יכול להשתנות (interleaving), מה שעלול לגרום לאיבוד עדכונים. לדוגמה, אם `shared_counter` הוא 0:
    *   תהליכון A קורא 0.
    *   תהליכון B קורא 0.
    *   תהליכון A מגדיל את הערך באוגר שלו ל-1.
    *   תהליכון B מקטין את הערך באוגר שלו ל-1-.
    *   תהליכון A כותב 1 ל-`shared_counter`.
    *   תהליכון B כותב 1- ל-`shared_counter`.
    במקרה זה, העדכון של תהליכון A אבד. הערך הסופי שיתקבל יהיה בלתי צפוי ולא בהכרח 0.

    הערך הסופי הצפוי של `shared_counter` אם לא היה קיים מצב מרוץ הוא **0**, מכיוון שיש 100,000 הגדלות ו-100,000 הקטנות, אשר אמורות לבטל זו את זו.

2. **פתרון עם Mutex:** כדי למנוע מצב מרוץ, יש להגן על הגישה למשתנה המשותף `shared_counter` באמצעות מנגנון סנכרון, כגון mutex (מנעול הדדי). Mutex מבטיח שרק תהליכון אחד יוכל להיכנס לקטע קריטי (Critical Section) בכל רגע נתון ולגשת למשאב המשותף.

    הפתרון המוצע הוא להשתמש ב-`pthread_mutex_t` ובפונקציות `pthread_mutex_lock()` ו-`pthread_mutex_unlock()` סביב הגישה למשתנה `shared_counter`:

    ```c
#include <stdio.h>
#include <pthread.h>

int shared_counter = 0; // Global shared resource
pthread_mutex_t counter_mutex; // Mutex for protecting shared_counter

void* incrementer(void* arg) {
    for (int i = 0; i < 100000; i++) {
        pthread_mutex_lock(&counter_mutex); // Lock before accessing shared_counter
        shared_counter++;
        pthread_mutex_unlock(&counter_mutex); // Unlock after accessing shared_counter
    }
    return NULL;
}

void* decrementer(void* arg) {
    for (int i = 0; i < 100000; i++) {
        pthread_mutex_lock(&counter_mutex); // Lock before accessing shared_counter
        shared_counter--;
        pthread_mutex_unlock(&counter_mutex); // Unlock after accessing shared_counter
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_mutex_init(&counter_mutex, NULL); // Initialize the mutex

    pthread_create(&tid1, NULL, incrementer, NULL);
    pthread_create(&tid2, NULL, decrementer, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    printf("Final value of shared_counter: %d\n", shared_counter);

    pthread_mutex_destroy(&counter_mutex); // Destroy the mutex

    return 0;
}
    ```
    בקוד המתוקן, כל גישה (קריאה ועדכון) ל-`shared_counter` מתבצעת בתוך קטע קריטי המוגן על ידי ה-mutex. זה מבטיח שרק תהליכון אחד יוכל לבצע את פעולת ה-`shared_counter++` או `shared_counter--` בכל רגע נתון, ובכך נמנעים מצבי מרוץ ואיבוד עדכונים. הערך הסופי שיודפס יהיה 0, כצפוי.

content.code_snippet:
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define NUM_THREADS 5
#define ITERATIONS_PER_THREAD 100000

long long shared_counter = 0;

void *increment_counter(void *arg) {
    for (int i = 0; i < ITERATIONS_PER_THREAD; i++) {
        shared_counter++;
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    printf("Initial shared_counter value: %lld\n", shared_counter);

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, increment_counter, NULL);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Final shared_counter value: %lld\n", shared_counter);
    printf("Expected value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

    return 0;
}

solution.explanation:
1.  **זיהוי תנאי מרוץ וקטע קריטי**: כן, הקוד סובל מתנאי מרוץ (Race Condition). הקטע הקריטי הוא הפעולה `shared_counter++`. הסיבה לכך היא שפעולה זו אינה אטומית. ברמת המעבד, היא מורכבת בדרך כלל משלוש פקודות נפרדות:
    א.  קריאת ערך המונה מהזיכרון לתוך רגיסטר.
    ב.  הגדלת הערך ברגיסטר.
    ג.  כתיבת הערך המוגדל מהרגיסטר בחזרה לזיכרון.
    כאשר מספר תהליכונים מנסים לבצע את הפעולה הזו בו-זמנית ללא סנכרון, ייתכן שתהליכון אחד יקרא את הערך, יבוצע מיתוג הקשר (context switch) לתהליכון אחר שיקרא גם הוא את אותו הערך (לפני שהתהליכון הראשון הספיק לכתוב בחזרה), ושניהם יגדילו ויכתבו בחזרה את אותו ערך מוגדל. בכך, למרות שבוצעו שתי פעולות הגדלה, המונה גדל בפועל רק באחד.

2.  **תוצאה לא צפויה**: התוצאה הלא צפויה היא שהערך הסופי של `shared_counter` יהיה נמוך מהערך הצפוי (`NUM_THREADS * ITERATIONS_PER_THREAD`). במקום לקבל סכום מדויק של כל ההגדלות, חלק מההגדלות 'ילכו לאיבוד' עקב התנגשויות בין התהליכונים על הגישה למשתנה המשותף.

3.  **פתרון עם Mutex**: כדי למנוע את תנאי המרוץ, יש להגן על הקטע הקריטי באמצעות מנגנון סנכרון כמו Mutex (מיוטקס). כל תהליכון יצטרך לנעול את המיוטקס לפני הכניסה לקטע הקריטי (`pthread_mutex_lock`), ולשחרר אותו בסיום הפעולה (`pthread_mutex_unlock`). זה מבטיח שרק תהליכון אחד יוכל לבצע את פעולות הקריאה, ההגדלה והכתיבה של המונה בכל רגע נתון, ובכך הופך את פעולת ההגדלה לאטומית.

    **הקוד המתוקן:**
    ```c
    #include <stdio.h>
    #include <stdlib.h>
    #include <pthread.h>

    #define NUM_THREADS 5
    #define ITERATIONS_PER_THREAD 100000

    long long shared_counter = 0;
    pthread_mutex_t counter_mutex; // הצהרה על מיוטקס

    void *increment_counter(void *arg) {
        for (int i = 0; i < ITERATIONS_PER_THREAD; i++) {
            pthread_mutex_lock(&counter_mutex); // נעל את המיוטקס לפני הקטע הקריטי
            shared_counter++; // הקטע הקריטי
            pthread_mutex_unlock(&counter_mutex); // שחרר את המיוטקס אחרי הקטע הקריטי
        }
        return NULL;
    }

    int main() {
        pthread_t threads[NUM_THREADS];

        // אתחל את המיוטקס
        pthread_mutex_init(&counter_mutex, NULL);

        printf("Initial shared_counter value: %lld\n", shared_counter);

        for (int i = 0; i < NUM_THREADS; i++) {
            pthread_create(&threads[i], NULL, increment_counter, NULL);
        }

        for (int i = 0; i < NUM_THREADS; i++) {
            pthread_join(threads[i], NULL);
        }

        printf("Final shared_counter value: %lld\n", shared_counter);
        printf("Expected value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

        // השמד את המיוטקס
        pthread_mutex_destroy(&counter_mutex);

        return 0;
    }
    ```

