typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* head = NULL;
int global_count = 0;

pthread_mutex_t list_mutex;
pthread_mutex_t count_mutex;

void add_item(int value) {
    pthread_mutex_lock(&count_mutex);
    global_count++;
    pthread_mutex_unlock(&count_mutex);

    pthread_mutex_lock(&list_mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = value;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&list_mutex);
}

void remove_item(int value) {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    Node* prev = NULL;

    while (current != NULL && current->data != value) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) {
        if (prev == NULL) {
            head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
        pthread_mutex_unlock(&list_mutex);

        pthread_mutex_lock(&count_mutex);
        global_count--;
        pthread_mutex_unlock(&count_mutex);
    } else {
        pthread_mutex_unlock(&list_mutex);
    }
}

solution.explanation:
1.1: תנאי מירוץ המוביל לאי-עקביות (global_count גדול ממספר האיברים בפועל):
תנאי המירוץ מתרחש בפונקציה `add_item` כאשר העדכון של `global_count` והוספת הצומת לרשימה אינם מהווים פעולה אטומית אחת. למרות שכל אחת מהפעולות מוגנת על ידי מנעול נפרד (`count_mutex` ו-`list_mutex`), הסדר וההפרדה ביניהן מאפשרים מצב ביניים לא עקבי.

תרחיש לדוגמה:
1.  `global_count` = 0, הרשימה ריקה.
2.  **תהליך A** קורא ל-`add_item(5)`.
3.  תהליך A נועל את `count_mutex`, מגדיל את `global_count` ל-1, ומשחרר את `count_mutex`.
4.  **מתרחשת החלפת הקשר (context switch).** תהליך B קורא לפונקציה `get_actual_list_count()` (נניח שפונקציה זו, בדומה ל-`remove_item`, נועלת את `list_mutex` וסופרת את האיברים ברשימה).
5.  תהליך B נועל את `list_mutex`, עובר על הרשימה (שעדיין ריקה כיוון שתהליך A לא הספיק להוסיף את הצומת בפועל), ומקבל `actual_count` = 0. תהליך B משחרר את `list_mutex` ומחזיר 0.
6.  **מתרחשת החלפת הקשר.** תהליך A ממשיך.
7.  תהליך A נועל את `list_mutex`, מוסיף את הצומת 5 לראש הרשימה, ומשחרר את `list_mutex`.

בנקודה זו, `global_count` שווה 1, אך תהליך B צפה ברשימה כשהייתה ריקה ודיווח על 0 איברים. מצב זה מפר את האינווריאנט, ו-`global_count` יהיה גדול ממספר האיברים בפועל ברגע ש-`get_actual_list_count()` נשלפה. גם אם נבדוק את המצב לאחר ששני התהליכים סיימו, תהליך B דיווח על אי-עקביות בעת ריצתו.

1.2: תיקון הקוד:
הבעיה נובעת מכך שעדכון המונה ועדכון מבנה הנתונים של הרשימה אינם אטומים יחד. הפתרון הנכון הוא להגן על שתי הפעולות באמצעות מנעול יחיד ומשותף, המבטיח ששום תהליך אחר לא יוכל לצפות במצב ביניים לא עקבי. במקרה זה, המנעול שמגן על הרשימה (`list_mutex`) יכול לשמש גם להגנה על `global_count`, מכיוון ש-`global_count` הוא מטא-דאטה שקשור ישירות למצב הרשימה.

קוד מתוקן:
```c
void add_item(int value) {
    pthread_mutex_lock(&list_mutex); // נועלים את המנעול המשותף לשתי הפעולות

    // שלב 1: הוספת הצומת לרשימה
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = value;
    new_node->next = head;
    head = new_node;

    // שלב 2: עדכון המונה
    global_count++; // מעדכנים את המונה תחת אותו מנעול

    pthread_mutex_unlock(&list_mutex); // משחררים את המנעול
}

void remove_item(int value) {
    pthread_mutex_lock(&list_mutex); // נועלים את המנעול המשותף לשתי הפעולות

    Node* current = head;
    Node* prev = NULL;

    while (current != NULL && current->data != value) {
        prev = current;
        current = current->next;
    }

    if (current != NULL) { // הצומת נמצא
        if (prev == NULL) {
            head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);

        // שלב 2: עדכון המונה
        global_count--; // מעדכנים את המונה תחת אותו מנעול
    }
    // אם הצומת לא נמצא, אין צורך לעדכן את המונה או לשחרר זיכרון

    pthread_mutex_unlock(&list_mutex); // משחררים את המנעול
}
```

**הסבר לתיקון:**
על ידי שימוש במנעול יחיד (`list_mutex`) המקיף את כל הפעולות שמשנות הן את מבנה הרשימה והן את המונה `global_count`, אנו מבטיחים ששתי הפעולות הללו יבוצעו כאטום אחד מבחינת כל תהליך אחר. כלומר, אף תהליך לא יוכל לצפות ברשימה או במונה במצב ביניים שבו אחד מהם עודכן אך השני עדיין לא. תהליך שירצה לגשת למונה או לרשימה יצטרך להמתין עד שהמנעול ישוחרר, ובכך יראה תמיד מצב עקבי של שניהם. אין צורך ב-`count_mutex` נפרד יותר, וניתן להסירו.

