        exit(EXIT_FAILURE);
    }
    new_node->data = value;
    new_node->next = head;
    head = new_node;
}

// פונקציית התהליכון
void* thread_func(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 1000; ++i) {
