#define NUM_THREADS 5
#define INCREMENTS_PER_THREAD 100000

int counter = 0; // Global shared variable

void* increment_thread(void* arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        // This operation is not atomic and causes a race condition
        counter++;
    }
    return NULL;
}

int main() {
    std::vector<pthread_t> tids(NUM_THREADS);

    // Create threads
    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&tids[i], NULL, increment_thread, NULL) != 0) {
            std::cerr << "Error creating thread " << i << std::endl;
            return 1;
        }
    }

    // Wait for threads to finish
    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(tids[i], NULL) != 0) {
            std::cerr << "Error joining thread " << i << std::endl;
            return 1;
        }
    }

    std::cout << "Final counter value: " << counter << std::endl;

    return 0;
}

solution.explanation:
1.  **הפלט הצפוי:** כל אחד מ-5 התהליכונים מגדיל את המונה `counter` 100,000 פעמים. לכן, הפלט הצפוי הוא `5 * 100,000 = 500,000`.

2.  **פלט אפשרי בפועל והסבר:** הפלט בפועל יהיה כמעט בוודאות *נמוך* מ-500,000, וגם יהיה *לא דטרמיניסטי* (כלומר, ישתנה בין הרצות שונות של התוכנית). הסיבה לכך היא **מרוץ תחרות (Race Condition)**.
    הפעולה `counter++` אינה אטומית. היא מורכבת למעשה משלושה שלבים ברמה נמוכה יותר:
    *   קריאת הערך הנוכחי של `counter` מהזיכרון לתוך אוגר במעבד.
    *   הגדלת הערך באוגר.
    *   כתיבת הערך החדש מהאוגר בחזרה ל`counter` בזיכרון.
    כאשר מספר תהליכונים מבצעים פעולה זו בו זמנית, הם עלולים להפריע זה לזה. לדוגמה, תהליכון A קורא את `counter` (נניח 100), ואז לפני שהוא מספיק לכתוב בחזרה, תהליכון B גם קורא את `counter` (עדיין 100). שניהם מגדילים את הערך באוגרים שלהם ל-101 וכותבים בחזרה לזיכרון. התוצאה הסופית ב`counter` תהיה 101, למרות שבוצעו שתי הגדלות, וכך אבדה אחת מהן. זה מוביל ל"עדכונים אבודים" (Lost Updates) ולערך סופי נמוך מהצפוי.

3.  **תיקון הבעיה:** כדי לתקן את מרוץ התחרות ולהבטיח שהמונה יגיע לערך הצפוי, יש להשתמש במנגנון סנכרון כמו **mutex (mutual exclusion lock)**. Mutex מבטיח שרק תהליכון אחד יוכל לגשת לקטע קריטי (Critical Section) של הקוד, במקרה זה הפעולה `counter++`, בכל רגע נתון. כך, הפעולות על `counter` הופכות להיות אטומיות מבחינה לוגית.

    **דוגמת קוד מתוקנת:**
    ```c++
    #include <iostream>
    #include <pthread.h>
    #include <vector>

    #define NUM_THREADS 5
    #define INCREMENTS_PER_THREAD 100000

    int counter = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Initialize mutex

    void* increment_thread(void* arg) {
        for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
            pthread_mutex_lock(&mutex); // Acquire lock before critical section
            counter++;                 // Critical section
            pthread_mutex_unlock(&mutex); // Release lock after critical section
        }
        return NULL;
    }

    int main() {
        std::vector<pthread_t> tids(NUM_THREADS);

        for (int i = 0; i < NUM_THREADS; ++i) {
            if (pthread_create(&tids[i], NULL, increment_thread, NULL) != 0) {
                std::cerr << "Error creating thread " << i << std::endl;
                return 1;
            }
        }

        for (int i = 0; i < NUM_THREADS; ++i) {
            if (pthread_join(tids[i], NULL) != 0) {
                std::cerr << "Error joining thread " << i << std::endl;
                return 1;
            }
        }

        pthread_mutex_destroy(&mutex); // Destroy mutex at the end
        std::cout << "Final counter value: " << counter << std::endl;

        return 0;
    }
    ```

