    במצב זה, במקום ש-`shared_counter` יהיה 12, הוא נשאר 11, והגדלה אחת אבדה.

3.  כדי לפתור את בעיית מרוץ התנאים ולהבטיח שהמונה יגיע לערך הנכון, יש להשתמש במנגנון סנכרון, כגון Mutex (מנעול הדדי). Mutex יבטיח שרק תהליכון אחד יוכל לגשת לקטע הקוד הקריטי (הגדלת המונה) בכל רגע נתון.

    **שינויים נדרשים בקוד:**

    ```c
    #include <stdio.h>
    #include <pthread.h>

    int shared_counter = 0;
    pthread_mutex_t counter_mutex; // הגדרת mutex
    #define NUM_THREADS 5
    #define ITERATIONS_PER_THREAD 100000

    void *increment_counter(void *arg) {
        for (int i = 0; i < ITERATIONS_PER_THREAD; ++i) {
            pthread_mutex_lock(&counter_mutex); // נעל את ה-mutex לפני גישה לקטע הקריטי
            shared_counter++;
            pthread_mutex_unlock(&counter_mutex); // שחרר את ה-mutex לאחר סיום הקטע הקריטי
        }
        return NULL;
    }

    int main() {
        pthread_t threads[NUM_THREADS];

        pthread_mutex_init(&counter_mutex, NULL); // אתחל את ה-mutex

        for (int i = 0; i < NUM_THREADS; ++i) {
            if (pthread_create(&threads[i], NULL, increment_counter, NULL) != 0) {
                perror("Failed to create thread");
                pthread_mutex_destroy(&counter_mutex); // נקה את ה-mutex במקרה של כשל
                return 1;
            }
        }

        for (int i = 0; i < NUM_THREADS; ++i) {
            if (pthread_join(threads[i], NULL) != 0) {
