#define N_TASKS 3
#define N_THREADS 2

int results[N_TASKS];
int next_task_id = 0;

void* worker(void* arg) {
    for (int i = 0; i < N_TASKS; ++i) { // Each thread attempts N_TASKS increments
        int current_task;
        current_task = next_task_id++; // Race condition here

        if (current_task < N_TASKS) {
            results[current_task]++;
        }
    }
    return NULL;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define NUM_SLOTS 3 // מספר משבצות המשאב
#define NUM_THREADS 3 // מספר חוטים

int slots[NUM_SLOTS]; // 0 = פנוי, >0 = נתפס ע"י חוט (מזהה החוט)
int claimed_count = 0; // מונה גלובלי של משבצות שנטענו

void* worker_thread(void* arg) {
    long thread_id = (long)arg;
    for (int attempt = 0; attempt < 2; ++attempt) { // כל חוט מנסה לתפוס משבצת פעמיים
        int found_slot_idx = -1;
        // לולאה למציאת משבצת פנויה
        for (int i = 0; i < NUM_SLOTS; ++i) {
            if (slots[i] == 0) { // בדיקה אם פנוי
                found_slot_idx = i;
                break; // נמצאה משבצת, יוצאים מהלולאה הפנימית
            }
        }

        if (found_slot_idx != -1) {
            // תפיסת המשבצת והגדלת המונה
            // כאן עשויה להתרחש החלפת הקשר לפני ששתי הפעולות מתבצעות יחד
            slots[found_slot_idx] = thread_id; // סימון המשבצת כנתפסת
            claimed_count++; // הגדלת מונה המשאבים שנטענו
            // printf("Thread %ld claimed slot %d. Current claimed_count: %d\n", thread_id, found_slot_idx, claimed_count);
        } else {
            // printf("Thread %ld found no available slots in attempt %d.\n", thread_id, attempt + 1);
        }
    }
    return NULL;
}

int main() {
    for (int i = 0; i < NUM_SLOTS; ++i) {
        slots[i] = 0; // אתחול כל המשבצות כפנויות
    }

    pthread_t threads[NUM_THREADS];

    for (long i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker_thread, (void*)(i + 1)); // מזהי חוטים 1, 2, 3
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // חישוב מספר המשבצות הייחודיות שנתפסו בפועל
    int actual_unique_claimed_slots = 0;
    for (int i = 0; i < NUM_SLOTS; ++i) {
        if (slots[i] != 0) {
            actual_unique_claimed_slots++;
        }
    }

    printf("\nFinal state:\n");
    for (int i = 0; i < NUM_SLOTS; ++i) {
        printf("Slot %d: %d\n", i, slots[i]);
    }
    printf("Final claimed_count: %d\n", claimed_count);
    printf("Actual unique claimed slots: %d\n", actual_unique_claimed_slots);


    return 0;
}

solution.explanation:
1.1: קיימים שני תנאי מירוץ עיקריים בפונקציה `worker_thread`:
    1.  **תנאי מירוץ על המערך `slots` (Check-Then-Act):** כאשר חוט מזהה שמשבצת `slots[i]` פנויה (כלומר `slots[i] == 0`), הוא ממשיך לתפוס אותה באמצעות `slots[found_slot_idx] = thread_id`. אולם, בין שלב הבדיקה (`if (slots[i] == 0)`) לבין שלב הפעולה (`slots[found_slot_idx] = thread_id`) עשויה להתרחש החלפת הקשר (context switch). חוט אחר יכול גם הוא לבדוק את אותה משבצת, למצוא אותה פנויה, ולתפוס אותה. כתוצאה מכך, שני חוטים יכולים לחשוב שהם תפסו את אותה משבצת, כאשר בפועל רק אחד מהם ישנה את ערכה במערך `slots`, והעדכון של השני יאבד. זהו מצב של "עדכון אבוד" (Lost Update).
    2.  **תנאי מירוץ על המונה `claimed_count` (Read-Modify-Write):** הפעולה `claimed_count++` אינה אטומית. היא מורכבת משלוש פעולות בסיסיות: קריאת הערך הנוכחי של `claimed_count`, הגדלת הערך, וכתיבת הערך החדש בחזרה לזיכרון. אם שני חוטים או יותר מנסים להגדיל את המונה בו-זמנית, ייתכן ששניהם יקראו את אותו ערך התחלתי, יגדילו אותו בנפרד, ולאחר מכן יכתבו בחזרה את הערך המוגדל. לדוגמה, אם `claimed_count` הוא 0, חוט A קורא 0, חוט B קורא 0. חוט A כותב 1, חוט B כותב 1. במקום שהמונה יהיה 2, הוא נשאר 1. זה גם מצב של "עדכון אבוד".

1.2: תרחיש ריצה שמוביל למצב בו `claimed_count` גדול מ-`actual_unique_claimed_slots`:

    *   **מצב התחלתי:** `slots = {0,0,0}`, `claimed_count = 0`
    *   **חוט 1 (T1) מתחיל (ID=1):**
        *   T1: נכנס ל-`worker_thread` (ניסיון 0).
        *   T1: מוצא `slots[0] == 0`. `found_slot_idx = 0`.
    *   **החלפת הקשר.**
    *   **חוט 2 (T2) מתחיל (ID=2):**
        *   T2: נכנס ל-`worker_thread` (ניסיון 0).
        *   T2: מוצא `slots[0] == 0`. `found_slot_idx = 0`.
    *   **החלפת הקשר.**
    *   **חוט 3 (T3) מתחיל (ID=3):**
        *   T3: נכנס ל-`worker_thread` (ניסיון 0).
        *   T3: מוצא `slots[1] == 0`. `found_slot_idx = 1`.
    *   **החלפת הקשר.**
    *   **T1 ממשיך:**
        *   T1: `slots[0] = 1`. `slots = {1,0,0}`.
        *   T1: `claimed_count++`. `claimed_count = 1`.
    *   **החלפת הקשר.**
    *   **T2 ממשיך:**
        *   T2: `slots[0] = 2`. `slots = {2,0,0}` (העדכון של T1 על `slots[0]` נדרס).
        *   T2: `claimed_count++`. `claimed_count = 2`.
    *   **החלפת הקשר.**
    *   **T3 ממשיך:**
        *   T3: `slots[1] = 3`. `slots = {2,3,0}`.
        *   T3: `claimed_count++`. `claimed_count = 3`.
    *   **החלפת הקשר.**
    *   **T1 ממשיך (ניסיון 1):**
        *   T1: מוצא `slots[2] == 0`. `found_slot_idx = 2`.
        *   T1: `slots[2] = 1`. `slots = {2,3,1}`.
        *   T1: `claimed_count++`. `claimed_count = 4`.
    *   **T1 מסיים.**
    *   **T2 ממשיך (ניסיון 1):**
        *   T2: אין משבצות פנויות (`slots` הוא ` {2,3,1}`). `found_slot_idx = -1`.
    *   **T2 מסיים.**
    *   **T3 ממשיך (ניסיון 1):**
        *   T3: אין משבצות פנויות (`slots` הוא ` {2,3,1}`). `found_slot_idx = -1`.
    *   **T3 מסיים.**

    **מצב סופי:**
    *   `slots = {2,3,1}`
    *   `claimed_count = 4`
    *   `actual_unique_claimed_slots = 3` (משבצות 0, 1, 2 נתפסו). 
    במצב זה, `claimed_count` (4) גדול מ-`actual_unique_claimed_slots` (3).

1.3: כדי לתקן את תנאי המירוץ, נשתמש במוטקס (mutex) כדי להגן על כל הקטע הקריטי שבו מתבצעת בדיקת זמינות המשבצת, תפיסתה, ועדכון המונה הגלובלי. הקטע הקריטי יכלול את לולאת החיפוש, את תפיסת המשבצת ואת הגדלת המונה.

    **שינויים בפונקציה `main`:**
    יש לאתחל את המוטקס לפני יצירת החוטים ולשחרר אותו בסיום התוכנית:

    ```c
    // הגדרה גלובלית של המוטקס (ניתן להגדיר גם בתוך main אם אין צורך לגשת אליו מחוץ ל-main)
    pthread_mutex_t mutex;

    int main() {
        for (int i = 0; i < NUM_SLOTS; ++i) {
            slots[i] = 0; // אתחול כל המשבצות כפנויות
        }

        // אתחול המוטקס
        pthread_mutex_init(&mutex, NULL);

        pthread_t threads[NUM_THREADS];

        for (long i = 0; i < NUM_THREADS; ++i) {
            pthread_create(&threads[i], NULL, worker_thread, (void*)(i + 1)); // מזהי חוטים 1, 2, 3
        }

        for (int i = 0; i < NUM_THREADS; ++i) {
            pthread_join(threads[i], NULL);
        }

        // שחרור המוטקס
        pthread_mutex_destroy(&mutex);

        // ... שאר קוד ההדפסה והחישובים ...

        return 0;
    }
    ```

    **פונקציה `worker_thread` מתוקנת:**

    ```c
    void* worker_thread(void* arg) {
        long thread_id = (long)arg;
        for (int attempt = 0; attempt < 2; ++attempt) {
            int found_slot_idx = -1;

            pthread_mutex_lock(&mutex); // ננעל את המוטקס לפני גישה למשתנים המשותפים

            // לולאה למציאת משבצת פנויה ותפיסתה
            for (int i = 0; i < NUM_SLOTS; ++i) {
                if (slots[i] == 0) { // בדיקה אם פנוי
                    found_slot_idx = i;
                    slots[found_slot_idx] = thread_id; // סימון המשבצת כנתפסת
                    claimed_count++; // הגדלת מונה המשאבים שנטענו
                    break; // נמצאה ונתפסה משבצת, יוצאים מהלולאה הפנימית
                }
            }

            pthread_mutex_unlock(&mutex); // נשחרר את המוטקס לאחר סיום הגישה למשתנים המשותפים

            if (found_slot_idx != -1) {
                // printf("Thread %ld claimed slot %d. Current claimed_count: %d\n", thread_id, found_slot_idx, claimed_count);
            } else {
                // printf("Thread %ld found no available slots in attempt %d.\n", thread_id, attempt + 1);
            }
        }
        return NULL;
    }
    ```
    המוטקס מבטיח שרק חוט אחד יוכל לבצע את פעולות הבדיקה, התפיסה והעדכון של המונה בכל רגע נתון, ובכך מונע את תנאי המירוץ שזוהו.

