#include <vector>

int global_val = 0;
int global_sum = 0;

const int N_THREADS = 2;
const int ITERS_PER_THREAD = 2;

void* thread_func(void* arg) {
    for (int i = 0; i < ITERS_PER_THREAD; ++i) {
        // These three lines are not atomic as a block.
        // Each line itself is atomic.
        int local_val = global_val; // Line X
        global_val = local_val + 1; // Line Y
        global_sum = global_sum + local_val; // Line Z
    }
    return NULL;
}

int main() {
    pthread_t threads[N_THREADS];
    for (int i = 0; i < N_THREADS; ++i) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }
    for (int i = 0; i < N_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
    // printf("global_val = %d, global_sum = %d\n", global_val, global_sum);
    return 0;
}

