        ssize_t bytes_written = write(fd, child_msg, strlen(child_msg));
        if (bytes_written == -1) {
            perror("child write");
            _exit(1);
        }
        _exit(0);
    }
    // Parent logic (not directly relevant to the child's write outcome, but good practice)
    close(fd);
    return 0;
}

