#include <stdio.h>
#include <stdlib.h>
#include <string.h> // For strlen

int main() {
    int pipefd[2];
    pid_t pid;

    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    }

    pid = fork();

    if (pid == -1) {
        perror("fork");
        return 1;
    }

    if (pid == 0) { // תהליך הבן
        close(pipefd[1]); // סגירת קצה הכתיבה של הצינור בתהליך הבן

        // ניתוב stdin (FD 0) לקצה הקריאה של הצינור
        if (dup2(pipefd[0], STDIN_FILENO) == -1) {
            perror("dup2");
            return 1;
        }
        close(pipefd[0]); // סגירת מתאר הקובץ המקורי של קצה הקריאה

        // הגדרת הדגל FD_CLOEXEC על STDIN_FILENO
        if (fcntl(STDIN_FILENO, F_SETFD, fcntl(STDIN_FILENO, F_GETFD) | FD_CLOEXEC) == -1) {
            perror("fcntl FD_CLOEXEC on STDIN_FILENO");
            return 1;
        }

        // ביצוע execve לתוכנית 'cat' שתנסה לקרוא מ-stdin
        char *args[] = {"/usr/bin/cat", NULL};
        execve(args[0], args, NULL);
        perror("execve"); // אם execve נכשל
        return 1;
    } else { // תהליך האב
        close(pipefd[0]); // סגירת קצה הקריאה של הצינור בתהליך האב

        const char *msg = "Hello from parent!\n";
        write(pipefd[1], msg, strlen(msg));
        close(pipefd[1]); // סגירת קצה הכתיבה, מאותת על EOF לבן

        wait(NULL); // המתנה לסיום תהליך הבן
    }

    return 0;
}

