int main() {
    int fd;
    pid_t pid;
    char *args[] = {"./child_program", NULL};

    // Open a file
    fd = open("output.txt", O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd == -1) {
        perror("open");
        exit(1);
    }
    printf("Parent: File 'output.txt' opened with fd %d.\n", fd);

    // Write something from parent before fork
    dprintf(fd, "Parent writes before fork.\n");

    pid = fork();

    if (pid == -1) {
        perror("fork");
        exit(1);
    } else if (pid == 0) { // Child process
        printf("Child: Process ID %d, Parent ID %d.\n", getpid(), getppid());
        dprintf(fd, "Child writes after fork, before exec.\n");
        // DO NOT close fd here, so it is inherited by execve'd program
        printf("Child: Not closing fd %d before exec, it should be inherited.\n", fd);
        // Execute a new program
        execve(args[0], args, NULL);
        perror("execve"); // execve only returns on error
        exit(1);
    } else { // Parent process
        printf("Parent: Process ID %d, Child ID %d.\n", getpid(), pid);
        dprintf(fd, "Parent writes after fork.\n");
        wait(NULL); // Wait for the child to finish
        printf("Parent: Child finished.\n");
        dprintf(fd, "Parent writes after child finished.\n");
        close(fd);
        printf("Parent: Closed fd %d.\n", fd);
    }

    return 0;
}

