/* main.c */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <string.h>

int main() {
    int pipefd[2]; // pipefd[0] for read, pipefd[1] for write
    pid_t pid;
    char *message = "Hello from parent via pipe!";
    char *argv[] = {"./child_program", NULL};
    char *envp[] = {NULL};

    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        close(pipefd[1]); // Close write end in child

        // Redirect stdin to read from the pipe
        if (dup2(pipefd[0], STDIN_FILENO) == -1) {
            perror("dup2");
            exit(EXIT_FAILURE);
        }
        close(pipefd[0]); // Close the original read end

        // Execute child_program
        if (execve(argv[0], argv, envp) == -1) {
            perror("execve");
            exit(EXIT_FAILURE);
        }
    } else { // Parent process
        close(pipefd[0]); // Close read end in parent

        // Write message to the pipe
        write(pipefd[1], message, strlen(message));
        close(pipefd[1]); // Close write end after writing

        // Wait for child to terminate
        wait(NULL);
        printf("Parent: Child process finished.\n");
    }

    return 0;
}

