/* main_prog.c */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <string.h>

int main() {
    int fd;
    pid_t pid;
    char *filename = "output.txt";
    char fd_str[10];

    // 1. Parent opens file with O_CLOEXEC
    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
    if (fd == -1) {
        perror("Parent: open failed");
        return 1;
    }
    printf("Parent: Opened %s with fd %d\n", filename, fd);

    // 2. Parent initial write
    write(fd, "Parent initial write\n", strlen("Parent initial write\n"));

    pid = fork();
    if (pid == -1) {
        perror("Parent: fork failed");
        close(fd);
        return 1;
    }

    if (pid == 0) { // Child process
        printf("Child: In child process, inherited fd %d\n", fd);
        // 3. Child attempts to write to inherited FD
        ssize_t bytes_written_child = write(fd, "Child direct write\n", strlen("Child direct write\n"));
        if (bytes_written_child == -1) {
            perror("Child: write to inherited fd failed");
        } else {
            printf("Child: Wrote %zd bytes to inherited fd %d\n", bytes_written_child, fd);
        }

        // Prepare arguments for execv
        sprintf(fd_str, "%d", fd);
        char *args[] = {"./writer_prog", fd_str, NULL};

        // 4. Child execs writer_prog
        printf("Child: Executing writer_prog with fd %s\n", fd_str);
        execv("./writer_prog", args);
        perror("Child: execv failed"); // Should only reach here if execv fails
        _exit(1); // Use _exit in child after fork/exec failure
    } else { // Parent process
        // 5. Parent waits for child
        printf("Parent: Waiting for child %d\n", pid);
        wait(NULL);

        // 6. Parent final write
        write(fd, "Parent final write\n", strlen("Parent final write\n"));

        // 7. Parent closes FD
        close(fd);
        printf("Parent: Closed fd %d\n", fd);
    }

    return 0;
}

/* writer_prog.c */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h> // For errno

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <file_descriptor_number>\n", argv[0]);
        return 1;
    }

    int fd_from_parent = atoi(argv[1]);
    printf("Writer_prog: Received fd %d\n", fd_from_parent);

    // 8. writer_prog tries to write to the received FD
    ssize_t bytes_written_writer = write(fd_from_parent, "Writer prog write\n", strlen("Writer prog write\n"));
    if (bytes_written_writer == -1) {
        perror("Writer_prog: write to received fd failed");
        // Check if errno indicates Bad file descriptor
        if (errno == EBADF) {
            printf("Writer_prog: write failed because fd %d is a bad file descriptor.\n", fd_from_parent);
        }
    } else {
        printf("Writer_prog: Wrote %zd bytes to fd %d\n", bytes_written_writer, fd_from_parent);
    }

    return 0;
}

#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/wait.h>
#include <string.h>

int main() {
    int pipefd[2];
    pid_t pid1, pid2;

    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // Fork first child (for 'ls')
    pid1 = fork();
    if (pid1 == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid1 == 0) { // Child 1: 'ls'
        close(pipefd[0]); // Close unused read end

        // Redirect stdout to pipe write end
        if (dup2(pipefd[1], STDOUT_FILENO) == -1) {
            perror("dup2 child 1");
            exit(EXIT_FAILURE);
        }
        close(pipefd[1]); // Close original pipe write end

        char *args[] = {"/bin/ls", "-1", NULL};
        execve(args[0], args, NULL);
        perror("execve ls"); // Should not reach here if execve succeeds
        exit(EXIT_FAILURE);
    }

    // Fork second child (for 'grep')
    pid2 = fork();
    if (pid2 == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid2 == 0) { // Child 2: 'grep .c'
        close(pipefd[1]); // Close unused write end

        // Redirect stdin to pipe read end
        if (dup2(pipefd[0], STDIN_FILENO) == -1) {
            perror("dup2 child 2");
            exit(EXIT_FAILURE);
        }
        close(pipefd[0]); // Close original pipe read end

        char *args[] = {"/bin/grep", ".c", NULL};
        execve(args[0], args, NULL);
        perror("execve grep"); // Should not reach here
        exit(EXIT_FAILURE);
    }

    // Parent process
    close(pipefd[0]); // Close both pipe ends in parent
    close(pipefd[1]);

    // Wait for both children
    waitpid(pid1, NULL, 0);
    waitpid(pid2, NULL, 0);

    printf("Parent finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <string.h>
#include <fcntl.h> // For open flags

#define NUM_CHILDREN 3
#define FILENAME "output.txt"

int main() {
    int fd;
    pid_t pid;
    char buffer[100];
    int i;

    // Open the file for writing. If it exists, truncate it.
    fd = open(FILENAME, O_CREAT | O_TRUNC | O_WRONLY, 0644);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    printf("Parent PID: %d\n", getpid());

    for (i = 0; i < NUM_CHILDREN; i++) {
        pid = fork();

        if (pid == -1) {
            perror("fork");
            exit(EXIT_FAILURE);
        } else if (pid == 0) { // Child process
            sprintf(buffer, "Child %d (PID %d) writing message %d.\n", i + 1, getpid(), i + 1);
            ssize_t bytes_written = write(fd, buffer, strlen(buffer));
            if (bytes_written == -1) {
                perror("child write");
            }
            // Child exits after writing
            _exit(EXIT_SUCCESS); // Use _exit to avoid flushing parent's stdio buffers
        }
    }

    // Parent waits for all children
    for (i = 0; i < NUM_CHILDREN; i++) {
        wait(NULL);
    }
    printf("All children finished.\n");

    // Parent reads the file content
    // First, rewind the file pointer to the beginning
    off_t seek_result = lseek(fd, 0, SEEK_SET);
    if (seek_result == -1) {
        perror("parent lseek");
        close(fd);
        exit(EXIT_FAILURE);
    }

    printf("\nFile content after all writes:\n");
    ssize_t bytes_read;
    while ((bytes_read = read(fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytes_read] = '\0'; // Null-terminate the read data
        printf("%s", buffer);
    }
    if (bytes_read == -1) {
        perror("parent read");
    }

    close(fd);
    printf("File descriptor closed.\n");

    return 0;
}

solution.explanation:
1.  **תוכן הקובץ:**
    התוכן הסופי של הקובץ `output.txt` יכלול את כל ההודעות מכל תהליכי הבן, אך **בסדר לא דטרמיניסטי** (לא ניתן לחזות מראש את סדר ההודעות). עם זאת, כל ההודעות יופיעו בקובץ במלואן, **זו אחר זו, ללא חפיפה**. כלומר, כל הודעה תתחיל מהנקודה שבה הסתיימה ההודעה הקודמת שנכתבה (על ידי כל תהליך בן אחר). הסיבה לכך היא שמצביע הקובץ (file offset) **משותף** בין תהליך האב לתהליכי הבן לאחר `fork()`.
    לדוגמה, אם Child 1 כותב "Child 1...", ואז Child 2 כותב "Child 2...", ההודעה של Child 2 תופיע מיד אחרי ההודעה של Child 1. הסדר שבו ההודעות של הילדים השונים מופיעות בקובץ הוא הלא דטרמיניסטי.

2.  **הסבר מנגנוני מערכת:**
    *   כאשר תהליך האב מבצע `open()`, נוצר מזהה קובץ (file descriptor) חדש. מזהה זה הוא אינדקס לטבלת מזהי הקבצים הייחודית לתהליך (per-process file descriptor table).
    *   ערך זה בטבלת מזהי הקבצים, בתורו, מצביע על ערך בטבלת הקבצים של הקרנל (per-system/kernel file table entry). ערך זה בטבלה מכיל מידע על הקובץ הפתוח, כולל מצביע הקובץ הנוכחי (current file offset), מצביעי הגישה (read/write access modes), וספירת התייחסויות (reference count).
    *   כאשר מתבצעת קריאת המערכת `fork()`, תהליך הבן מקבל עותק של טבלת מזהי הקבצים של האב. עם זאת, מזהי הקבצים המועתקים בטבלת הבן **מצביעים על אותם ערכים בטבלת הקבצים של הקרנל** כמו אלה של האב. הם אינם מקבלים עותק נפרד של ה-file table entry.
    *   משמעות הדבר היא שכל תהליכי הבן, וכן תהליך האב, חולקים את אותו מצביע קובץ (file offset) עבור הקובץ `output.txt`. זהו מצב של "copy-on-fork" עבור טבלת מזהי הקבצים, אך "share-on-fork" עבור ה-file table entries.
    *   לכן, כאשר תהליך בן כלשהו קורא או כותב לקובץ, מצביע הקובץ המשותף מתקדם. תהליך הבן הבא שיכתוב יתחיל לכתוב מהמיקום החדש של מצביע הקובץ, ובכך נמנעת דריסה חלקית של נתונים.
    *   הסדר הלא דטרמיניסטי של ההודעות בקובץ נובע מכך שתזמון המעבדים (CPU scheduling) קובע איזה תהליך בן יקבל את המעבד ויבצע את קריאת ה- `write()` בכל רגע נתון. אין ערובה לסדר ביצוע בין תהליכים נפרדים.

3.  **פתרון לבעיה:**
    כדי להבטיח שכל תהליך בן יכתוב לחלק נפרד ולא חופף בקובץ מבלי לפתוח מחדש את הקובץ, ניתן להשתמש בקריאת המערכת `lseek()` לפני כל פעולת כתיבה. כל תהליך בן יכול לחשב את המיקום הייחודי שלו בקובץ (לדוגמה, על בסיס האינדקס של הבן `i` או ה-PID שלו, בתוספת אורך ההודעות הקודמות). יש לוודא שהאורך המקסימלי של הודעה ידוע מראש או מחושב באופן דינמי כדי להבטיח מרווחים מספקים.

    **שינוי בקוד (בתוך בלוק ה-`else if (pid == 0)`):**
    נניח אורך מקסימלי קבוע להודעה, למשל 60 בתים (כולל תו רווח ושורת סיום). כל תהליך בן יקבל בלוק כתיבה במיקום ייחודי.

    ```c
    else if (pid == 0) { // Child process
        // Calculate a unique offset for each child based on its index (i)
        // We assume a fixed maximum message length (e.g., 60 bytes) for simplicity.
        // In a real-world scenario, dynamic allocation or more robust coordination
        // (e.g., using file locks or IPC for offset management) might be needed.
        int child_index = i; // 0, 1, 2
        off_t desired_offset = child_index * 60; // 0, 60, 120

        // Move the file pointer to the unique offset for this child
        if (lseek(fd, desired_offset, SEEK_SET) == -1) {
            perror("child lseek");
            _exit(EXIT_FAILURE);
        }

        sprintf(buffer, "Child %d (PID %d) writing message %d at offset %ld.\n", i + 1, getpid(), i + 1, (long)desired_offset);
        ssize_t bytes_written = write(fd, buffer, strlen(buffer));
        if (bytes_written == -1) {
            perror("child write");
        }
        _exit(EXIT_SUCCESS);
    }
    ```

    **הסבר הפתרון:**
    לפני שכל תהליך בן כותב, הוא מזיז את מצביע הקובץ באמצעות `lseek()` למיקום מחושב מראש שמיועד לו. לדוגמה, אם יש 3 בנים וכל הודעה היא באורך מקסימלי של 60 בתים, הבן עם אינדקס `i=0` יכתוב ממיקום 0, הבן עם `i=1` ממיקום 60, והבן עם `i=2` ממיקום 120. זה מבטיח שהכתיבות לא ידרסו זו את זו, וכל הודעה תשמור על מיקומה הייחודי. השימוש ב-`lseek()` מאפשר לתהליכים שחולקים את אותו file table entry לגשת למיקומים שונים בקובץ באופן עצמאי לפני כל פעולת כתיבה. יש לוודא שהקובץ גדול מספיק כדי להכיל את כל הכתיבות במיקומים אלו. אם המיקום המבוקש רחוק מה-EOF הנוכחי, `lseek` יכול ליצור "חורים" (sparse file) בקובץ, ופעולת ה-`write` תמלא אותם.

