        // Redirect stdout to the opened file
        if (dup2(fd, STDOUT_FILENO) == -1) {
            perror("dup2 failed in child");
            close(fd);
            exit(1);
        }
        close(fd); // Close the original fd, stdout now points to the file

        // Execute a new program
        execve(args[0], args, NULL);
        perror("execve failed"); // Should not reach here if execve succeeds
        exit(1);
    } else { // Parent process
        printf("Parent: PID = %d, Child PID = %d\n", getpid(), pid);
        // Write directly to the file using the original file descriptor
        char *parent_msg = "Hello from parent!\n";
        if (write(fd, parent_msg, strlen(parent_msg)) == -1) {
            perror("parent write failed");
        }
        close(fd); // Parent closes its copy of the file descriptor

        wait(NULL); // Wait for child to terminate
        printf("Parent: Child finished.\n");
    }

    return 0;
}

