#include <iostream>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>

const int MAX_ITEMS = 5;
std::queue<int> shared_queue;
std::mutex mtx;
std::condition_variable cv; // Single condition variable for both producers and consumers

void producer(int id) {
    for (int i = 0; i < 3; ++i) { // Each producer adds 3 items
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [] { return shared_queue.size() < MAX_ITEMS; }); // Wait if full

        int item = id * 100 + i;
        shared_queue.push(item);
        std::cout << "Producer " << id << " produced " << item << ". Queue size: " << shared_queue.size() << std::endl;
        cv.notify_one(); // Notify *one* waiting thread (could be producer or consumer)
    }
}

void consumer(int id) {
    for (int i = 0; i < 2; ++i) { // Each consumer consumes 2 items
        std::this_thread::sleep_for(std::chrono::milliseconds(15));
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [] { return !shared_queue.empty(); }); // Wait if empty

        int item = shared_queue.front();
        shared_queue.pop();
        std::cout << "Consumer " << id << " consumed " << item << ". Queue size: " << shared_queue.size() << std::endl;
        cv.notify_one(); // Notify *one* waiting thread (could be producer or consumer)
    }
}

int main() {
    std::vector<std::thread> threads;
    for (int i = 0; i < 2; ++i) { // 2 producers
        threads.emplace_back(producer, i + 1);
    }
    for (int i = 0; i < 3; ++i) { // 3 consumers
        threads.emplace_back(consumer, i + 1);
    }

    for (auto& t : threads) {
        t.join();
    }
    std::cout << "Final queue size: " << shared_queue.size() << std::endl;
    return 0;
}

