#define BUFFER_SIZE 10

int buffer[BUFFER_SIZE];
int count = 0;
int in = 0;
int out = 0;

pthread_mutex_t mutex;
pthread_cond_t cond_not_empty; // Signaled when buffer is not empty
pthread_cond_t cond_not_full;  // Signaled when buffer is not full

void *producer(void *arg) {
    int item;
    for (int i = 0; i < 20; i++) {
        item = i;
        pthread_mutex_lock(&mutex);

        // PROBLEM: Using IF instead of WHILE
        if (count == BUFFER_SIZE) { // Buffer is full, wait
            printf("Producer waiting: buffer full\n");
            pthread_cond_wait(&cond_not_full, &mutex);
        }

        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        count++;
        printf("Produced: %d, count: %d\n", item, count);

        pthread_cond_signal(&cond_not_empty); // Signal consumer
        pthread_mutex_unlock(&mutex);
        usleep(rand() % 100000); // Simulate work
    }
    return NULL;
}

void *consumer(void *arg) {
    int item;
    for (int i = 0; i < 20; i++) {
        pthread_mutex_lock(&mutex);

        // PROBLEM: Using IF instead of WHILE
        if (count == 0) { // Buffer is empty, wait
            printf("Consumer waiting: buffer empty\n");
            pthread_cond_wait(&cond_not_empty, &mutex);
        }

        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count--;
        printf("Consumed: %d, count: %d\n", item, count);

        pthread_cond_signal(&cond_not_full); // Signal producer
        pthread_mutex_unlock(&mutex);
        usleep(rand() % 200000); // Simulate work
    }
    return NULL;
}

