    pthread_cond_init(&cond_not_full, NULL);

    pthread_create(&prod_tid, NULL, producer, NULL);
    pthread_create(&cons_tid, NULL, consumer, NULL);

    pthread_join(prod_tid, NULL);
    pthread_join(cons_tid, NULL);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond_not_empty);
    pthread_cond_destroy(&cond_not_full);

    return 0;
}

#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For sleep

#define NUM_THREADS 5
#define NUM_ITERATIONS 3

pthread_mutex_t barrier_mutex;
pthread_cond_t barrier_cond;
int threads_at_barrier = 0;
int total_threads = NUM_THREADS;

void *worker_thread_func(void *arg) {
    long tid = (long)arg;
    int i;

    for (i = 0; i < NUM_ITERATIONS; ++i) {
        // Simulate doing some work
        printf("Thread %ld: Starting iteration %d, doing work...\n", tid, i);
        sleep(rand() % 3 + 1); // Simulate variable work time
        printf("Thread %ld: Finished work for iteration %d.\n", tid, i);

        pthread_mutex_lock(&barrier_mutex);

        threads_at_barrier++;
        printf("Thread %ld: Reached barrier. %d/%d threads here.\n", tid, threads_at_barrier, total_threads);

        if (threads_at_barrier == total_threads) {
            // Last thread to arrive, signal all others
            printf("Thread %ld: Last thread arrived. Broadcasting to all waiting threads.\n", tid);
            threads_at_barrier = 0; // Reset for next iteration
            pthread_cond_broadcast(&barrier_cond);
        } else {
            // Not the last thread, wait for others
            // Use a while loop for spurious wakeups and to re-check condition
            while (threads_at_barrier != 0) { // Condition: wait until barrier is reset by the last thread
                pthread_cond_wait(&barrier_cond, &barrier_mutex);
            }
        }

        pthread_mutex_unlock(&barrier_mutex);
        printf("Thread %ld: Passed barrier, starting next task/iteration %d.\n", tid, i + 1);
    }

    printf("Thread %ld: All iterations completed. Exiting.\n", tid);
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    long i;

    // Initialize mutex and condition variable
    pthread_mutex_init(&barrier_mutex, NULL);
    pthread_cond_init(&barrier_cond, NULL);

    srand(time(NULL)); // Seed for random sleep

    // Create worker threads
    for (i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker_thread_func, (void *)i);
    }

    // Wait for all threads to complete
    for (i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("All threads finished. Main exiting.\n");

    // Destroy mutex and condition variable
    pthread_mutex_destroy(&barrier_mutex);
    pthread_cond_destroy(&barrier_cond);

    return 0;
}

