#include <stdio.h>
#include <pthread.h>
#include <unistd.h> // For sleep

#define NUM_WORKERS 5

pthread_mutex_t mutex;
pthread_cond_t cond;
int completed_workers = 0;

void *worker_function(void *arg) {
    long id = (long)arg;
    printf("Worker %ld: Starting task...\n", id);
    sleep(1 + (id % 3)); // Simulate work
    printf("Worker %ld: Task completed.\n", id);

    pthread_mutex_lock(&mutex);
    completed_workers++;
    printf("Worker %ld: completed_workers = %d\n", id, completed_workers);
    if (completed_workers == NUM_WORKERS) {
        pthread_cond_signal(&cond); // Signal only when the condition is met
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    pthread_t workers[NUM_WORKERS];
    long i;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    printf("Main thread: Launching worker threads...\n");
    for (i = 0; i < NUM_WORKERS; i++) {
        pthread_create(&workers[i], NULL, worker_function, (void *)i);
    }

    pthread_mutex_lock(&mutex);
    printf("Main thread: Waiting for all workers to complete...\n");
    // The crucial while loop
    while (completed_workers < NUM_WORKERS) {
        pthread_cond_wait(&cond, &mutex);
    }
    pthread_mutex_unlock(&mutex);

    printf("Main thread: All %d workers have completed. Final summary.\n", NUM_WORKERS);

    // Join workers (optional for this specific question, but good practice)
    for (i = 0; i < NUM_WORKERS; i++) {
        pthread_join(workers[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    return 0;
}

