#include <pthread.h>

class ResourceManager {
public:
    ResourceManager(int max_res) : MAX_RESOURCES(max_res), available_resources(max_res) {
        pthread_mutex_init(&mutex, NULL);
        pthread_cond_init(&cond_single_resource, NULL);
        pthread_cond_init(&cond_all_resources, NULL);
    }

    ~ResourceManager() {
        pthread_mutex_destroy(&mutex);
        pthread_cond_destroy(&cond_single_resource);
        pthread_cond_destroy(&cond_all_resources);
    }

    void acquire() {
        pthread_mutex_lock(&mutex);
        while (available_resources == 0) {
            pthread_cond_wait(&cond_single_resource, &mutex);
        }
        available_resources--;
        pthread_mutex_unlock(&mutex);
    }

    void release() {
        pthread_mutex_lock(&mutex);
        available_resources++;
        pthread_cond_signal(&cond_single_resource);
        pthread_mutex_unlock(&mutex);
    }

    void acquire_all() {
        pthread_mutex_lock(&mutex);
        while (available_resources != MAX_RESOURCES) {
            pthread_cond_wait(&cond_all_resources, &mutex);
        }
        available_resources = 0;
        pthread_mutex_unlock(&mutex);
    }

    void release_all() {
        pthread_mutex_lock(&mutex);
        available_resources = MAX_RESOURCES;
        pthread_cond_signal(&cond_single_resource);
        pthread_cond_signal(&cond_all_resources);
        pthread_mutex_unlock(&mutex);
    }

private:
    const int MAX_RESOURCES;
    int available_resources;
    pthread_mutex_t mutex;
    pthread_cond_t cond_single_resource;
    pthread_cond_t cond_all_resources;
};

solution.explanation:
### פתרון לשאלה 1

#### 1.1 זיהוי והסבר הבעיות במימוש המקורי:

1.  **הרעבה (Starvation) של חוטי 'Manager'**: 
    חוטים הקוראים ל-`acquire_all()` עשויים לסבול מהרעבה. אם ישנם חוטים רבים מסוג 'Worker' שקוראים ל-`acquire()` ו-`release()` ברצף, מספר המשאבים הפנויים (`available_resources`) עשוי לעולם לא להגיע ל-`MAX_RESOURCES` במצב יציב, או להגיע לשם רק לרגע קצר לפני שחוט 'Worker' אחר תופס משאב. במצב כזה, חוט 'Manager' הממתין ב-`cond_all_resources` עלול להמתין ללא סוף.

2.  **שימוש לא נכון ב-`pthread_cond_signal` ב-`release()`**: 
    כאשר חוט 'Worker' משחרר משאב ב-`release()`, הוא קורא ל-`pthread_cond_signal(&cond_single_resource)`. 
    *   **בעיה 1 (החמצת התעוררות של Manager)**: אם שחרור המשאב מוביל לכך ש-`available_resources` מגיע ל-`MAX_RESOURCES`, וחוט 'Manager' ממתין ב-`cond_all_resources`, ה-`signal` הנוכחי לא יעיר אותו. חוט ה-'Manager' ימשיך להמתין למרות שהתנאי שלו מתקיים.
    *   **בעיה 2 (יעילות והרעבה של Workers אחרים)**: אם מספר משאבים הופך לזמין (למשל, מ-0 ל-2), וחוטים מרובים מסוג 'Worker' ממתינים ב-`cond_single_resource`, ה-`signal` יעיר רק אחד מהם. שאר החוטים ימשיכו להמתין גם אם יש מספיק משאבים עבורם. במימוש `acquire()` הנוכחי, חוט שהתעורר יקח משאב אחד ואז ישחרר את המוטקס, אבל לא יהיה `signal` נוסף שיעיר את הממתינים האחרים. זה יכול להוביל להרעבה של חוטי Worker אחרים או לפחות ליעילות נמוכה.

3.  **שימוש לא נכון ב-`pthread_cond_signal` ב-`release_all()`**: 
    כאשר חוט 'Manager' משחרר את כל המשאבים ב-`release_all()`, הוא קורא לשני `pthread_cond_signal`ים. 
    *   **בעיה 1 (יעילות והרעבה של Workers)**: `pthread_cond_signal(&cond_single_resource)` יעיר רק חוט 'Worker' אחד, למרות שכל `MAX_RESOURCES` משאבים זמינים כעת ועשויים להיות הרבה חוטי 'Worker' שממתינים. שוב, זה פוגע ביעילות ויכול לגרום להרעבה.
    *   **בעיה 2 (יעילות והרעבה של Managers)**: `pthread_cond_signal(&cond_all_resources)` יעיר רק חוט 'Manager' אחד, למרות שאם היו מספר חוטי 'Manager' שממתינים, כולם היו יכולים (תיאורטית) להתעורר ולבדוק את התנאי (אם כי רק אחד מהם יצליח לתפוס את כולם). עדיף להשתמש ב-`broadcast` במקרה זה כדי לוודא שכל הממתינים הרלוונטיים מתעוררים ובודקים את התנאי מחדש.

4.  **חוסר שימוש ב-`while` לטיפול ב-spurious wakeups**: קוד ה-`acquire()` ו-`acquire_all()` משתמשים ב-`while` עבור תנאי ההמתנה, וזהו שימוש נכון וחשוב למניעת `spurious wakeups` ולוודא שהתנאי אכן מתקיים לאחר ההתעוררות. בנקודה זו אין בעיה במימוש הנוכחי.

#### 1.2 תיקונים נדרשים ומימוש מתוקן:

כדי לפתור את הבעיות, נצטרך: 
א. למנוע הרעבה של 'Manager' על ידי מתן עדיפות. 
ב. להשתמש ב-`pthread_cond_broadcast` במקום `signal` כאשר מספר חוטים עשויים להיות מעוניינים במשאבים. 
ג. לוודא שכל סוגי החוטים הממתינים מקבלים התראה כאשר התנאי שלהם מתקיים.

נוסיף משתנה בוליאני `manager_waiting` שיציין אם חוט 'Manager' ממתין לתפוס את כל המשאבים. 

```c++
#include <pthread.h>

class ResourceManager {
public:
    ResourceManager(int max_res) : MAX_RESOURCES(max_res), available_resources(max_res), manager_waiting(false) {
        pthread_mutex_init(&mutex, NULL);
        pthread_cond_init(&cond_single_resource, NULL);
        pthread_cond_init(&cond_all_resources, NULL);
    }

    ~ResourceManager() {
        pthread_mutex_destroy(&mutex);
        pthread_cond_destroy(&cond_single_resource);
        pthread_cond_destroy(&cond_all_resources);
    }

    void acquire() {
        pthread_mutex_lock(&mutex);
        // Worker threads wait if no resources are available OR if a Manager is waiting (to prevent Manager starvation)
        while (available_resources == 0 || manager_waiting) {
            pthread_cond_wait(&cond_single_resource, &mutex);
        }
        available_resources--;
        pthread_mutex_unlock(&mutex);
    }

    void release() {
        pthread_mutex_lock(&mutex);
        available_resources++;
        // If a Manager is waiting and all resources are now available, wake up the Manager.
        // Otherwise, if no Manager is waiting, wake up all Worker threads.
        if (manager_waiting && available_resources == MAX_RESOURCES) {
            pthread_cond_signal(&cond_all_resources); // Signal because only one Manager can acquire_all at a time
        } else if (!manager_waiting) {
            pthread_cond_broadcast(&cond_single_resource); // Broadcast to all waiting Worker threads
        }
        pthread_mutex_unlock(&mutex);
    }

    void acquire_all() {
        pthread_mutex_lock(&mutex);
        manager_waiting = true; // Indicate that a Manager is waiting for ALL resources
        while (available_resources != MAX_RESOURCES) {
            pthread_cond_wait(&cond_all_resources, &mutex);
        }
        available_resources = 0; // All resources acquired
        manager_waiting = false; // Manager is no longer waiting
        // Now that the Manager has acquired, allow Worker threads to proceed if resources become available later.
        // We broadcast to cond_single_resource here in case Worker threads were blocked by manager_waiting flag.
        pthread_cond_broadcast(&cond_single_resource);
        pthread_mutex_unlock(&mutex);
    }

    void release_all() {
        pthread_mutex_lock(&mutex);
        available_resources = MAX_RESOURCES; // All resources released
        manager_waiting = false; // Reset manager_waiting as the Manager has finished its task
        // All resources are free. Both types of threads could potentially proceed.
        // Broadcast to both condition variables to ensure all relevant waiting threads are woken.
        pthread_cond_broadcast(&cond_single_resource); // Wake up all waiting Worker threads
        pthread_cond_broadcast(&cond_all_resources);   // Wake up all waiting Manager threads (if any)
        pthread_mutex_unlock(&mutex);
    }

private:
    const int MAX_RESOURCES;
    int available_resources;
    bool manager_waiting; // New flag to prevent Manager starvation
    pthread_mutex_t mutex;
    pthread_cond_t cond_single_resource;
    pthread_cond_t cond_all_resources;
};
```

**הסבר לתיקונים:**

1.  **מניעת הרעבה של 'Manager'**: 
    *   הוספנו את המשתנה `bool manager_waiting`. חוט 'Manager' שקורא ל-`acquire_all()` מציב את `manager_waiting` ל-`true` לפני שהוא נכנס למצב המתנה. 
    *   בפונקציה `acquire()`, חוטי 'Worker' ימתינו לא רק כאשר `available_resources == 0` אלא גם כאשר `manager_waiting == true`. זה מבטיח שאם 'Manager' ממתין, חוטי 'Worker' לא יתפסו משאבים בודדים ויאפשרו ל-`available_resources` להגיע ל-`MAX_RESOURCES` עבור ה-'Manager'.
    *   לאחר שחוט 'Manager' תפס את כל המשאבים (ב-`acquire_all()`) או שחרר את כולם (ב-`release_all()`), הוא מאפס את `manager_waiting` ל-`false`. לאחר מכן, הוא קורא ל-`pthread_cond_broadcast(&cond_single_resource)` כדי להעיר את כל חוטי ה-'Worker' הממתינים, שיוכלו כעת להמשיך.

2.  **שימוש נכון ב-`pthread_cond_broadcast`**: 
    *   ב-`release()`: 
        *   אם `manager_waiting` נכון ו-`available_resources` הגיע ל-`MAX_RESOURCES`, אנו מעירים רק את חוט ה-'Manager' (באמצעות `signal`) מכיוון שרק הוא יכול לקחת את כל המשאבים. חוטי 'Worker' עדיין חסומים על ידי הדגל `manager_waiting`.
        *   אחרת (אם אין 'Manager' ממתין), אנו משתמשים ב-`pthread_cond_broadcast(&cond_single_resource)` כדי להעיר את כל חוטי ה-'Worker' הממתינים. זאת מכיוון שכאשר משאב משוחרר, ייתכן שיותר מחוט 'Worker' אחד יוכל כעת לתפוס משאב, ו-`broadcast` מבטיח שכולם יבדקו את התנאי מחדש.
    *   ב-`release_all()`: 
        *   כאשר כל המשאבים משוחררים, אנו קוראים ל-`pthread_cond_broadcast` עבור שתי ה-`cond_variable`ים. זה מבטיח שכל חוטי 'Worker' הממתינים (שיוכלו כעת לקחת משאב בודד) וכל חוטי 'Manager' הממתינים (שיוכלו כעת לקחת את כל המשאבים) יתעוררו ויבדקו את התנאים שלהם. זהו המנגנון הנכון ביותר ליעילות ומניעת הרעבה במצב זה.

התיקונים הללו מבטיחים נכונות, מונעים הרעבה של חוטי 'Manager' ומשפרים את היעילות על ידי העלאת מספר החוטים המתאימים לתנאי בכל פעם שמתאפשר.

