#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h> // For sleep

#define BUFFER_SIZE 5

int buffer[BUFFER_SIZE];
int count = 0;
int in = 0;
int out = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_empty = PTHREAD_COND_INITIALIZER; // Signaled when buffer becomes non-empty
pthread_cond_t cond_full = PTHREAD_COND_INITIALIZER;  // Signaled when buffer becomes non-full

void *producer(void *arg) {
    int item_produced = 0;
    while (1) {
        pthread_mutex_lock(&mutex);
        if (count == BUFFER_SIZE) { // Problem: Should be while, not if
            printf("Producer: Buffer full, waiting...\n");
            pthread_cond_wait(&cond_full, &mutex);
        }

        // Simulate production
        item_produced++;
        buffer[in] = item_produced;
        in = (in + 1) % BUFFER_SIZE;
        count++;
        printf("Producer: Produced %d, count = %d\n", item_produced, count);

        pthread_cond_signal(&cond_empty); // Signal consumers
        pthread_mutex_unlock(&mutex);
        sleep(1); // Simulate work outside critical section
    }
    return NULL;
}

void *consumer(void *arg) {
    int item_consumed;
    while (1) {
        pthread_mutex_lock(&mutex);
        if (count == 0) { // Problem: Should be while, not if
            printf("Consumer: Buffer empty, waiting...\n");
            pthread_cond_wait(&cond_empty, &mutex);
        }

        // Simulate consumption
        item_consumed = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count--;
        printf("Consumer: Consumed %d, count = %d\n", item_consumed, count);

        pthread_cond_signal(&cond_full); // Signal producers
        pthread_mutex_unlock(&mutex);
        sleep(2); // Simulate work outside critical section
    }
    return NULL;
}

int main() {
    pthread_t prod_thread, cons_thread;

    pthread_create(&prod_thread, NULL, producer, NULL);
    pthread_create(&cons_thread, NULL, consumer, NULL);

    pthread_join(prod_thread, NULL);
    pthread_join(cons_thread, NULL);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond_empty);
    pthread_cond_destroy(&cond_full);

    return 0;
}

solution.explanation:
הקוד המצורף מכיל שתי בעיות סנכרון מרכזיות, הנובעות משימוש שגוי במשתני תנאי:

1.  **שימוש ב-`if` במקום ב-`while` לבדיקת התנאי לפני המתנה**:
    *   **הסבר הבעיה**: בקוד הנוכחי, הבנקאי והצרכן משתמשים בפקודת `if` כדי לבדוק האם עליהם להמתין (הבנקאי אם התור מלא, הצרכן אם התור ריק). `pthread_cond_wait` יכולה לחזור (spurious wakeup) גם ללא קריאה ל-`pthread_cond_signal` או `pthread_cond_broadcast`, או שייתכן ש-`pthread_cond_signal` הופעלה אך התנאי המקורי השתנה שוב לפני שהחוט הממתין הצליח לרוץ (לדוגמה, במערכת עם מספר בנקאים/צרכנים, חוט אחר לקח את הפריט/מקום בתור). אם משתמשים ב-`if`, לאחר שהחוט התעורר הוא ימשיך בביצוע ללא בדיקה חוזרת של התנאי.
        *   **תרחיש לדוגמה (צרכן)**: נניח שהתור ריק. צרכן 1 נכנס לאזור הקריטי, בודק `if (count == 0)`, מוצא שהתור ריק, ומחליט להמתין. הוא קורא ל-`pthread_cond_wait(&cond_empty, &mutex)`. כעת, נניח שמתרחש "wakeup כוזב" (spurious wakeup) או שבנקאי אחר מפעיל `pthread_cond_signal` (למרות שהתור עדיין ריק). צרכן 1 יתעורר, ייצא מה-`if` וינסה לצרוך פריט מתור ריק, מה שיוביל לשגיאה או התנהגות בלתי צפויה.
        *   **תרחיש לדוגמה (בנקאי)**: דומה לצרכן, אם התור מלא, בנקאי עלול להתעורר מ-`pthread_cond_wait` בגלל wakeup כוזב, לצאת מה-`if` ולנסות להוסיף פריט לתור מלא.
    *   **בעיית "איתות אבוד" (Lost Signal)**: בעיה חמורה יותר עלולה להתרחש במצב מירוץ עדין. נניח שהתור ריק. צרכן 1 נכנס לאזור הקריטי, בודק `if (count == 0)`, מוצא שהתור ריק. לפני שהוא מספיק לקרוא ל-`pthread_cond_wait`, הוא נקטע. כעת, בנקאי רץ, מוסיף פריט לתור, וקורא ל-`pthread_cond_signal(&cond_empty)`. מכיוון שצרכן 1 לא היה עדיין במצב המתנה, האיתות "אובד". כאשר צרכן 1 יחזור לרוץ ויקרא ל-`pthread_cond_wait`, הוא ימתין באופן אינסופי, למרות שיש פריט בתור. שימוש ב-`while` מסייע להפחית את הסיכון הזה בכך שהוא מבטיח שהתנאי נבדק שוב ברגע שהחוט מתעורר, ואם הוא כבר השתנה, החוט לא ימתין לחינם.

2.  **פוטנציאל לקיפאון (Deadlock) או חוסר יעילות במצבים מורכבים יותר (אם היו מספר בנקאים/צרכנים)**:
    *   בעוד שבקוד הנתון עם בנקאי וצרכן יחידים, הבעיה העיקרית היא ה-`if` במקום `while`, חשוב לציין שבמערכות מרובות בנקאים ו/או מרובות צרכנים, שימוש ב-`pthread_cond_signal` במקום `pthread_cond_broadcast` במצבים מסוימים עלול לגרום לקיפאון. לדוגמה, אם כל הצרכנים ממתינים על `cond_empty` ובנקאי אחד מוסיף פריט וקורא ל-`pthread_cond_signal`, רק צרכן אחד יתעורר. אם צרכן זה אינו יכול להמשיך (לדוגמה, בגלל תנאי נוסף שלא מתקיים), ושאר הצרכנים נשארים רדומים, המערכת עלולה להיתקע. במקרה שלנו, `signal` מספיק מכיוון שיש רק בנקאי אחד וצרכן אחד שמעוניינים בפריט/מקום.

**פתרון מתוקן:**
התיקון העיקרי הוא להחליף את פקודות ה-`if` ב-`while` בתוך הפונקציות `producer` ו-`consumer` לפני הקריאה ל-`pthread_cond_wait`. זוהי הדרך הבטוחה והנכונה ביותר להשתמש במשתני תנאי.

