pthread_mutex_t buffer_mutex; // אתחול: 1 (pthread_mutex_init(&buffer_mutex, NULL);)
sem_t empty_slots;           // אתחול: N (sem_init(&empty_slots, 0, N);)
sem_t filled_slots;          // אתחול: 0 (sem_init(&filled_slots, 0, 0);)

void* producer(void* arg) {
    Item item;
    while (1) {
        item = produce_item();         // ייצור מוצר
        sem_wait(&empty_slots);        // המתן למקום פנוי
        pthread_mutex_lock(&buffer_mutex); // נעל את המחסן
        add_item_to_buffer(item);      // הוסף למחסן
        pthread_mutex_unlock(&buffer_mutex); // שחרר את המנעול
        sem_post(&filled_slots);       // אותת שיש מוצר חדש
    }
    return NULL;
}

void* consumer(void* arg) {
    Item item;
    while (1) {
        sem_wait(&filled_slots);       // המתן למוצר
        pthread_mutex_lock(&buffer_mutex); // נעל את המחסן
        item = remove_item_from_buffer(); // הוצא מהמחסן
        pthread_mutex_unlock(&buffer_mutex); // שחרר את המנעול
        sem_post(&empty_slots);        // אותת שיש מקום פנוי
        consume_item(item);            // צרוך את המוצר
    }
    return NULL;
}
```

