הפתרון לבעיית היצרן-צרכן הקלאסית משתמש בשלושה אובייקטי סנכרון:
1.  `pthread_mutex_t mutex`: מנעול הדדיות (mutex) המבטיח שרק חוט אחד (יצרן או צרכן) יוכל לגשת לחוצץ המשותף בכל רגע נתון, ובכך מונע תנאי מרוץ על הנתונים בחוצץ.
2.  `sem_t empty`: סמפור המייצג את מספר המקומות הריקים בחוצץ. הוא מאותחל לגודל החוצץ (N). יצרן ממתין על סמפור זה לפני הוספת פריט, וצרכן מאותת עליו לאחר הסרת פריט.
3.  `sem_t full`: סמפור המייצג את מספר המקומות המלאים בחוצץ (כלומר, מספר הפריטים הזמינים לצריכה). הוא מאותחל ל-0. צרכן ממתין על סמפור זה לפני הסרת פריט, ויצרן מאותת עליו לאחר הוספת פריט.

**מימוש:**
```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>

#define N 10 /* גודל החוצץ */

typedef int Item; /* לדוגמה, פריט הוא מספר שלם */

/* פונקציות עזר (אין צורך לממש אותן) */
/* (הערה: מימוש דמה לצורך קומפילציה, לא חלק מהפתרון הנדרש) */
Item produce_item() { static int count = 0; return count++; }
void consume_item(Item item) { printf("Consumed: %d\n", item); }
void add_item_to_buffer(Item item) { /* ... */ }
Item remove_item_from_buffer() { /* ... */ return 0; }

// משתנים גלובליים
sem_t empty;   // מספר מקומות ריקים בחוצץ, מאותחל ל-N
sem_t full;    // מספר פריטים מלאים בחוצץ, מאותחל ל-0
pthread_mutex_t mutex; // מנעול להגנה על הגישה לחוצץ, מאותחל למצב פתוח (unlocked)

void* producer(void* arg) {
    while (1) {
        Item item = produce_item(); // 1. ייצור פריט

        sem_wait(&empty);           // 2. המתן למקום ריק בחוצץ (אם החוצץ מלא, חכה)
        pthread_mutex_lock(&mutex); // 3. נעל גישה לחוצץ כדי למנוע גישה מקבילית

        add_item_to_buffer(item);   // 4. הוסף פריט לחוצץ
        // printf("Producer added: %d\n", item); // להדגמה בלבד

        pthread_mutex_unlock(&mutex); // 5. שחרר גישה לחוצץ
        sem_post(&full);            // 6. אותת שיש פריט מלא בחוצץ (הגדל את מונה הפריטים המלאים)
    }
    return NULL;
}

void* consumer(void* arg) {
    while (1) {
        sem_wait(&full);            // 1. המתן לפריט מלא בחוצץ (אם החוצץ ריק, חכה)
        pthread_mutex_lock(&mutex); // 2. נעל גישה לחוצץ כדי למנוע גישה מקבילית

        Item item = remove_item_from_buffer(); // 3. הוצא פריט מהחוצץ

        pthread_mutex_unlock(&mutex); // 4. שחרר גישה לחוצץ
        sem_post(&empty);           // 5. אותת שיש מקום ריק בחוצץ (הגדל את מונה המקומות הריקים)

        consume_item(item);         // 6. צרוך את הפריט
    }
    return NULL;
}

/* פונקציית main לדוגמה לצורך אתחול והרצת החוטים, לא נדרש כחלק מהפתרון לשאלה */
/*
int main() {
    // אתחול הסמפורים והמנעול
    sem_init(&empty, 0, N); // 0 = shared between threads of a process
    sem_init(&full, 0, 0);
    pthread_mutex_init(&mutex, NULL);

    pthread_t prod_tid, cons_tid;
    pthread_create(&prod_tid, NULL, producer, NULL);
    pthread_create(&cons_tid, NULL, consumer, NULL);

    pthread_join(prod_tid, NULL);
    pthread_join(cons_tid, NULL);

    sem_destroy(&empty);
    sem_destroy(&full);
    pthread_mutex_destroy(&mutex);

    return 0;
}
*/
```

