// Global semaphores (initialization values in comments)
sem_t empty;   // init to N (10)
sem_t full;    // init to 0
sem_t mutex;   // init to 1

// Function to initialize semaphores (would be called once at program start)
void init_semaphores() {
    sem_init(&empty, 0, N);
    sem_init(&full, 0, 0);
    sem_init(&mutex, 0, 1);
}

void* producer(void* arg) {
    while (1) {
        Item item = produce_item();

        sem_wait(&empty); // Wait for an empty slot
        sem_wait(&mutex); // Acquire lock for buffer access

        shared_buffer[in] = item;
        in = (in + 1) % N;
        printf("Produced item: %d (in=%d)\\n", item, in); // Added for clarity

        sem_post(&mutex); // Release lock
        sem_post(&full);  // Signal that a slot is full
    }
    return NULL;
}

void* consumer(void* arg) {
    while (1) {
        Item item;

        sem_wait(&full);  // Wait for an item to be available
        sem_wait(&mutex); // Acquire lock for buffer access

        item = shared_buffer[out];
        out = (out + 1) % N;
        printf("Removing item: %d (out=%d)\\n", item, out); // Added for clarity

        sem_post(&mutex); // Release lock
        sem_post(&empty); // Signal that a slot is empty

        consume_item(item);
    }
    return NULL;
}

content.code_snippet:
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define BUFFER_SIZE 5

int buffer[BUFFER_SIZE];
int count = 0;
int in = 0;
int out = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void *producer(void *arg) {
    int item;
    for (int i = 0; i < 10; i++) {
        item = i;

        // PROBLEM 1: Checking count without mutex lock - Race condition on 'count'
        // PROBLEM 2: Calling pthread_cond_wait without mutex locked by the caller
        while (count == BUFFER_SIZE) { 
            // pthread_cond_wait expects the mutex to be locked when called.
            // If not locked, it leads to undefined behavior or an error (e.g., EINVAL).
            pthread_cond_wait(&not_full, &mutex); 
        }

        // This mutex lock is too late for the condition check and the wait operation.
        pthread_mutex_lock(&mutex); 

        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        count++;
        printf("Producer produced: %d, count: %d\n", item, count);

        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&mutex);
        usleep(rand() % 100000);
    }
    return NULL;
}

// Consumer is assumed to be correct for this problem focus
void *consumer(void *arg) {
    int item;
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(&mutex);
        while (count == 0) {
            pthread_cond_wait(&not_empty, &mutex);
        }
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count--;
        printf("Consumer consumed: %d, count: %d\n", item, count);
        pthread_cond_signal(&not_full);
        pthread_mutex_unlock(&mutex);
        usleep(rand() % 100000);
    }
    return NULL;
}

int main() {
    pthread_t prod_thread, cons_thread;

    pthread_create(&prod_thread, NULL, producer, NULL);
    pthread_create(&cons_thread, NULL, consumer, NULL);

    pthread_join(prod_thread, NULL);
    pthread_join(cons_thread, NULL);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&not_full);
    pthread_cond_destroy(&not_empty);

    return 0;
}

solution.explanation:
הבעיות שעלולות להתעורר:

1.  **Race Condition (תנאי מירוץ):** אם היצרן בודק את התנאי `count == BUFFER_SIZE` ללא נעילת המוטקס, ערך המונה `count` יכול להשתנות על ידי צרכן (שמפנה מקום בחוצץ) בדיוק בין הבדיקה לבין ניסיון הנעילה (אם הייתה). כתוצאה מכך, היצרן עלול לקבל החלטה שגויה - לדוגמה, להמשיך לייצר פריט למרות שהחוצץ מלא, או לחילופין להיכנס למצב המתנה (wait) למרות שיש מקום פנוי, ובכך להחמיץ איתות (signal) שהגיע לפני שהספיק להיכנס למצב המתנה (Lost Wakeup).

2.  **Undefined Behavior / Error (התנהגות בלתי מוגדרת / שגיאה):** הפונקציה `pthread_cond_wait` דורשת שהמוטקס (הארגומנט השני שלה) יהיה נעול על ידי החוט הקורא בעת הקריאה אליה. היא נועדה לשחרר את המוטקס באופן אטומי, להמתין לאיתות, ולאחר מכן לנעול מחדש את המוטקס לפני החזרה. אם המוטקס אינו נעול בעת הקריאה ל-`pthread_cond_wait`, הפונקציה עלולה להיכשל (לדוגמה, להחזיר קוד שגיאה כמו `EINVAL`), או לגרום להתנהגות בלתי מוגדרת, מה שיוביל לקריסת התוכנית או לבעיות סנכרון חמורות.

**תיקון קטע הקוד:**
התיקון הנכון דורש שהיצרן ינעל את המוטקס *לפני* שהוא בודק את תנאי המלאות של החוצץ ולפני קריאה ל-`pthread_cond_wait`. הלולאה `while` מבטיחה שהתנאי נבדק שוב לאחר שהחוט התעורר מ-`pthread_cond_wait`, מכיוון שהחוט עשוי להתעורר מסיבות אחרות (Spurious Wakeup) או שהתנאי כבר לא תקף.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define BUFFER_SIZE 5

int buffer[BUFFER_SIZE];
int count = 0;
int in = 0;
int out = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void *producer(void *arg) {
    int item;
    for (int i = 0; i < 10; i++) {
        item = i;

        pthread_mutex_lock(&mutex); // Correct: Lock mutex before checking condition and waiting

        while (count == BUFFER_SIZE) { 
            pthread_cond_wait(&not_full, &mutex); // Correct: Mutex is locked here
        }

        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        count++;
        printf("Producer produced: %d, count: %d\n", item, count);

        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&mutex); // Unlock mutex after critical section
        usleep(rand() % 100000);
    }
    return NULL;
}

void *consumer(void *arg) {
    int item;
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(&mutex);
        while (count == 0) {
            pthread_cond_wait(&not_empty, &mutex);
        }
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count--;
        printf("Consumer consumed: %d, count: %d\n", item, count);
        pthread_cond_signal(&not_full);
        pthread_mutex_unlock(&mutex);
        usleep(rand() % 100000);
    }
    return NULL;
}

int main() {
    pthread_t prod_thread, cons_thread;

    pthread_create(&prod_thread, NULL, producer, NULL);
    pthread_create(&cons_thread, NULL, consumer, NULL);

    pthread_join(prod_thread, NULL);
    pthread_join(cons_thread, NULL);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&not_full);
    pthread_cond_destroy(&not_empty);

    return 0;
}
```

content.text:
בעיית המפיק-צרכן היא בעיה קלאסית בתחום מערכות ההפעלה הדנה בתיאום בין תהליכים (או תרדמים) המשתפים מאגר נתונים חסום. נתון קטע קוד C/C++ המממש את פונקציית הצרכן (consumer) תוך שימוש בסמפורים וב-mutex. קטע הקוד מכיל שגיאה לוגית שעלולה להוביל לקיפאון (deadlock).

```c
// Assume semaphores 'full', 'empty' and mutex 'mtx' are initialized
// BUFFER_SIZE, buffer, in, out are global/shared
// Item represents the data type

void consumer() {
    Item item;
    while (true) {
        pthread_mutex_lock(&mtx); // Acquire mutex first
        sem_wait(&full);          // Wait for an item

        // Critical section: remove item from buffer
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;

        pthread_mutex_unlock(&mtx); // Release mutex
        sem_post(&empty);         // Signal an empty slot

        // Consume the item
        consume_item(item);
    }
}
```

א. זהו את השגיאה בקטע הקוד והסבירו מדוע היא עלולה לגרום לקיפאון. פרטו את התרחיש שבו יתרחש הקיפאון.
ב. הציעו תיקון לשגיאה והציגו את קטע הקוד המתוקן.

solution.explanation:
חלק א': זיהוי השגיאה והסבר לקיפאון
השגיאה בקטע הקוד של הצרכן היא בסדר הפעולות: הצרכן נועל את ה-mutex (`pthread_mutex_lock(&mtx)`) *לפני* שהוא ממתין לסמפור `full` (`sem_wait(&full)`).

תרחיש לקיפאון:
1.  נניח שהמאגר ריק לחלוטין (ערך הסמפור `full` הוא 0).
2.  הצרכן מתחיל לרוץ. הוא נועל את ה-mutex `mtx` בהצלחה.
3.  הצרכן מנסה לבצע `sem_wait(&full)`. מכיוון שהמאגר ריק, הסמפור `full` הוא 0, ולכן הצרכן נכנס למצב המתנה (בלוקינג) על הסמפור `full`.
4.  בשלב זה, הצרכן מחזיק ב-mutex `mtx` אך ממתין לסמפור `full`.
5.  כעת, נניח שהמפיק (producer) מנסה להוסיף פריט למאגר. תהליך המפיק ינסה קודם כל לבצע `sem_wait(&empty)` (נניח שיש מקום פנוי, כלומר `empty` > 0), ואז ינסה לנעול את ה-mutex `mtx` כדי לגשת למאגר המשותף.
6.  המפיק יחסם בניסיון לנעול את ה-mutex `mtx`, מכיוון שהצרכן כבר מחזיק בו.
7.  המצב שנוצר הוא קיפאון: הצרכן ממתין למפיק שיסמן את `full` (על ידי הוספת פריט), אך המפיק אינו יכול להוסיף פריט מכיוון שהוא ממתין ל-mutex `mtx` שמוחזק על ידי הצרכן. אף אחד מהם לא יכול להתקדם, ונוצר קיפאון.

חלק ב': תיקון השגיאה
התיקון הוא לשנות את סדר הפעולות בצרכן, כך שההמתנה לסמפור `full` תתבצע *לפני* נעילת ה-mutex. באופן דומה, במפיק, ההמתנה לסמפור `empty` צריכה להתבצע לפני נעילת ה-mutex. ה-mutex צריך להגן רק על הגישה למאגר המשותף עצמו, ולא על פעולות ההמתנה/איתות של הסמפורים.

קטע הקוד המתוקן:
```c
// Assume semaphores 'full', 'empty' and mutex 'mtx' are initialized
// BUFFER_SIZE, buffer, in, out are global/shared
// Item represents the data type

void consumer() {
    Item item;
    while (true) {
        sem_wait(&full);          // 1. Wait for an item (blocks if buffer empty)
        pthread_mutex_lock(&mtx); // 2. Acquire mutex to access shared buffer

        // Critical section: remove item from buffer
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;

        pthread_mutex_unlock(&mtx); // 3. Release mutex
        sem_post(&empty);         // 4. Signal an empty slot

        // Consume the item
        consume_item(item);
    }
}
```
הסבר לתיקון:
בגרסה המתוקנת, הצרכן ממתין לפריט (`sem_wait(&full)`) לפני שהוא נועל את ה-mutex. אם המאגר ריק, הצרכן יחסם על `full` וישחרר את המעבד, אך ה-mutex `mtx` לא יהיה נעול. זה מאפשר למפיק להמשיך, להוסיף פריט למאגר (לאחר שיבצע `sem_wait(&empty)` וינעל את `mtx` בעצמו, יוסיף את הפריט וישחרר את `mtx`), ולבסוף לאותת ל`full` (`sem_post(&full)`). איתות זה ישחרר את הצרכן מההמתנה, והוא יוכל אז לנעול את ה-mutex ולגשת בבטחה למאגר. כך נמנע הקיפאון.

