solution.explanation:
הפתרון משתמש בארבעה סמפורים וב-mutex אחד (שמיושם כסמפור בינארי), בתוספת מבנה נתונים עבור התור:

**הגדרות ומשתנים גלובליים:**
```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For usleep

#define BUFFER_SIZE 5       // גודל תור ההדפסה המשותף
#define MAX_ACTIVE_JOBS 8   // מגבלת עבודות פעילות במערכת כולה (בתור או בהדפסה)

typedef struct {
    int id;
} Job;

// משתנים גלובליים (אתחול בסוגריים):
sem_t mutex;                     // מגן על הגישה לתור ההדפסה (אתחול ל-1)
sem_t queue_slots_available;     // סופר מקומות פנויים בתור (אתחול ל-BUFFER_SIZE)
sem_t jobs_available_in_queue;   // סופר עבודות שממתינות בתור (אתחול ל-0)
sem_t total_system_capacity;     // עוקב אחר מגבלת MAX_ACTIVE_JOBS (אתחול ל-MAX_ACTIVE_JOBS)

Job print_queue[BUFFER_SIZE];    // התור המשותף לעבודות הדפסה
int head = 0;                    // אינדקס להוצאת עבודות מהתור
int tail = 0;                    // אינדקס להכנסת עבודות לתור

// פונקציות עזר לדוגמה (לצורך הדמיית פעולה)
void produce_job(Job* job) {
    static int next_job_id = 0;
    job->id = __sync_fetch_and_add(&next_job_id, 1); // Increment job ID atomically
    printf("Producer produced job %d\n", job->id);
    usleep(rand() % 100000); // Simulate work
}

void process_job(Job job) {
    printf("Consumer processing job %d\n", job.id);
    usleep(rand() % 500000); // Simulate processing time
    printf("Consumer finished job %d\n", job.id);
}
```

**תיאור הפתרון:**
הפתרון משתמש בארבעה סמפורים וב-mutex אחד (שמיושם כסמפור בינארי).
1.  `mutex`: סמפור בינארי (מאותחל ל-1) המגן על הגישה לתור ההדפסה המשותף (`print_queue`) ולמשתני האינדקסים (`head`, `tail`). הוא מבטיח שרק חוט אחד יוכל לשנות את מצב התור בכל רגע נתון.
2.  `queue_slots_available`: סמפור ספירה (מאותחל ל-`BUFFER_SIZE`) המייצג את מספר המקומות הפנויים בתור ההדפסה. Producers ימתינו עליו לפני הוספת עבודה (באמצעות `sem_wait`), ו-Consumers יבצעו `sem_post` לאחר הוצאת עבודה, ובכך ישחררו מקום בתור.
3.  `jobs_available_in_queue`: סמפור ספירה (מאותחל ל-0) המייצג את מספר העבודות הממתינות בתור ההדפסה. Consumers ימתינו עליו לפני הוצאת עבודה (באמצעות `sem_wait`), ו-Producers יבצעו `sem_post` לאחר הוספת עבודה, ובכך יסמנו שיש עבודה חדשה בתור.
4.  `total_system_capacity`: סמפור ספירה (מאותחל ל-`MAX_ACTIVE_JOBS`) המייצג את המגבלה הכוללת על מספר העבודות הפעילות במערכת (בתור או בהדפסה). Producers יבצעו `sem_wait` עליו *לפני* שהם מוסיפים עבודה לתור, ובכך יוודאו שיש מקום במערכת כולה. Consumers יבצעו `sem_post` עליו *רק לאחר סיום הדפסת העבודה*, ובכך ישחררו את המגבלה עבור עבודה זו.

**קוד C/C++ עבור Producer:**
```c
void* producer(void* arg) {
    while (1) {
        Job new_job;
        produce_job(&new_job); // יצירת עבודה חדשה

        // 1. המתן למקום פנוי במערכת כולה (מגבלת MAX_ACTIVE_JOBS)
        sem_wait(&total_system_capacity);
        // 2. המתן למקום פנוי בתור ההדפסה עצמו
        sem_wait(&queue_slots_available);

        // 3. נועל את ה-mutex לגישה לתור
        sem_wait(&mutex);
        // 4. הוסף את העבודה לתור
        print_queue[tail] = new_job;
        tail = (tail + 1) % BUFFER_SIZE;
        printf("Producer added job %d to queue. Current queue state (tail: %d)\n", new_job.id, tail);
        // 5. שחרר את ה-mutex
        sem_post(&mutex);

        // 6. סמן שיש עבודה זמינה בתור
        sem_post(&jobs_available_in_queue);

        usleep(rand() % 200000); // הדמיית זמן לפני יצירת העבודה הבאה
    }
    return NULL;
}
```

**קוד C/C++ עבור Consumer:**
```c
void* consumer(void* arg) {
    while (1) {
        // 1. המתן לעבודה זמינה בתור
        sem_wait(&jobs_available_in_queue);

        // 2. נועל את ה-mutex לגישה לתור
        sem_wait(&mutex);
        // 3. הוצא את העבודה מהתור
        Job job_to_process = print_queue[head];
        head = (head + 1) % BUFFER_SIZE;
        printf("Consumer took job %d from queue. Current queue state (head: %d)\n", job_to_process.id, head);
        // 4. סמן שמקום בתור התפנה
        sem_post(&queue_slots_available);
        // 5. שחרר את ה-mutex
        sem_post(&mutex);

        // 6. בצע את פעולת הדפסת העבודה (מחוץ לאזור הקריטי)
        process_job(job_to_process);

        // 7. סמן שמקום במגבלת MAX_ACTIVE_JOBS התפנה (העבודה הושלמה)
        sem_post(&total_system_capacity);

        usleep(rand() % 100000); // הדמיית זמן לפני צריכת העבודה הבאה
    }
    return NULL;
}
```

סדר זה מבטיח שהמגבלה `MAX_ACTIVE_JOBS` נאכפת כראוי, ושהמערכת לא תיכנס למצב של עומס יתר, תוך שמירה על סנכרון נכון בין Producers ו-Consumers. הסמפורים הוגנים (כנדרש) ולכן לא תהיה רעב (starvation) של חוטים הממתינים.

