#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For usleep

#define BUFFER_SIZE 5 // Example buffer size

// Assume these are defined elsewhere for simplicity,
// and are thread-safe for their internal operations,
// but external synchronization is needed for buffer capacity.
typedef int data_item_t;

data_item_t buffer1[BUFFER_SIZE];
int in1 = 0, out1 = 0;

data_item_t buffer2[BUFFER_SIZE];
int in2 = 0, out2 = 0;

// Helper functions for buffer operations (assume thread-safe internally)
// In a real scenario, these would likely be part of a thread-safe data structure
void enqueue_buffer1(data_item_t item) {
    buffer1[in1] = item;
    in1 = (in1 + 1) % BUFFER_SIZE;
}

data_item_t dequeue_buffer1() {
    data_item_t item = buffer1[out1];
    out1 = (out1 + 1) % BUFFER_SIZE;
    return item;
}

void enqueue_buffer2(data_item_t item) {
    buffer2[in2] = item;
    in2 = (in2 + 1) % BUFFER_SIZE;
}

data_item_t dequeue_buffer2() {
    data_item_t item = buffer2[out2];
    out2 = (out2 + 1) % BUFFER_SIZE;
    return item;
}

// Global Semaphores (declaration and initialization for a complete runnable example)
sem_t empty1;   // init to BUFFER_SIZE
sem_t full1;    // init to 0
sem_t mutex1;   // init to 1

sem_t empty2;   // init to BUFFER_SIZE
sem_t full2;    // init to 0
sem_t mutex2;   // init to 1

void* producer_thread(void* arg) {
    int produced_count = 0;
    while (1) {
        data_item_t item = produced_count++; // Simulate producing data

        sem_wait(&empty1);  // Wait for an empty slot in buffer1
        sem_wait(&mutex1);  // Lock buffer1 for access

        enqueue_buffer1(item);
        printf("Producer produced: %d\n", item);

        sem_post(&mutex1);  // Unlock buffer1
        sem_post(&full1);   // Signal that buffer1 has a full slot
        usleep(100000); // Simulate work
    }
    return NULL;
}

void* intermediate_processor_thread(void* arg) {
    while (1) {
        // Consume from buffer1
        sem_wait(&full1);   // Wait for a full slot in buffer1
        sem_wait(&mutex1);  // Lock buffer1 for access

        data_item_t raw_item = dequeue_buffer1();
        printf("Intermediate Processor consumed raw: %d\n", raw_item);

        sem_post(&mutex1);  // Unlock buffer1
        sem_post(&empty1);  // Signal that buffer1 has an empty slot

        // Process item (simulate some work)
        data_item_t processed_item = raw_item * 2; // Simple processing
        usleep(150000); // Simulate processing time

        // Produce to buffer2
        sem_wait(&empty2);  // Wait for an empty slot in buffer2
        sem_wait(&mutex2);  // Lock buffer2 for access

        enqueue_buffer2(processed_item);
        printf("Intermediate Processor produced processed: %d\n", processed_item);

        sem_post(&mutex2);  // Unlock buffer2
        sem_post(&full2);   // Signal that buffer2 has a full slot
        usleep(100000); // Simulate work
    }
    return NULL;
}

void* consumer_thread(void* arg) {
    while (1) {
        sem_wait(&full2);   // Wait for a full slot in buffer2
        sem_wait(&mutex2);  // Lock buffer2 for access

        data_item_t final_item = dequeue_buffer2();
        printf("Consumer consumed final: %d\n", final_item);

        sem_post(&mutex2);  // Unlock buffer2
        sem_post(&empty2);  // Signal that buffer2 has an empty slot
        usleep(200000); // Simulate work
    }
    return NULL;
}

// Main function to demonstrate (not part of the required solution for the exam question)
int main() {
    // Initialize semaphores
    sem_init(&empty1, 0, BUFFER_SIZE);
    sem_init(&full1, 0, 0);
    sem_init(&mutex1, 0, 1);

    sem_init(&empty2, 0, BUFFER_SIZE);
    sem_init(&full2, 0, 0);
    sem_init(&mutex2, 0, 1);

    pthread_t p_tid, ip_tid, c_tid;

    pthread_create(&p_tid, NULL, producer_thread, NULL);
    pthread_create(&ip_tid, NULL, intermediate_processor_thread, NULL);
    pthread_create(&c_tid, NULL, consumer_thread, NULL);

    pthread_join(p_tid, NULL);
    pthread_join(ip_tid, NULL);
    pthread_join(c_tid, NULL);

    // Destroy semaphores
    sem_destroy(&empty1);
    sem_destroy(&full1);
    sem_destroy(&mutex1);
    sem_destroy(&empty2);
    sem_destroy(&full2);
    sem_destroy(&mutex2);

    return 0;
}
```

