#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // for sleep

#define BUFFER_SIZE 5

// Buffers and indices
int buffer_A[BUFFER_SIZE];
int buffer_B[BUFFER_SIZE];
int in_A = 0, out_A = 0;
int in_B = 0, out_B = 0;

// Semaphores
sem_t mutex_A;    // init to 1
sem_t mutex_B;    // init to 1
sem_t items_A;    // init to 0
sem_t items_B;    // init to 0
sem_t slots_A;    // init to BUFFER_SIZE
sem_t slots_B;    // init to BUFFER_SIZE

// Helper functions for buffer management (provided in question)
void put_part_A(int part) {
    buffer_A[in_A] = part;
    in_A = (in_A + 1) % BUFFER_SIZE;
}

int get_part_A() {
    int part = buffer_A[out_A];
    out_A = (out_A + 1) % BUFFER_SIZE;
    return part;
}

void put_part_B(int part) {
    buffer_B[in_B] = part;
    in_B = (in_B + 1) % BUFFER_SIZE;
}

int get_part_B() {
    int part = buffer_B[out_B];
    out_B = (out_B + 1) % BUFFER_SIZE;
    return part;
}

// Worker thread function
void* worker(void* arg) {
    int worker_id = *(int*)arg;
    int part_counter = 0;
    while (1) {
        sleep(rand() % 2); // Simulate work
        int part_type = rand() % 2; // 0 for PartA, 1 for PartB
        part_counter++;

        if (part_type == 0) { // Produce PartA
            sem_wait(&slots_A);
            sem_wait(&mutex_A);
            // Critical section for buffer_A
            put_part_A(part_counter);
            printf("Worker %d produced PartA #%d. Buffer A size: %d\n", worker_id, part_counter, (in_A - out_A + BUFFER_SIZE) % BUFFER_SIZE);
            sem_post(&mutex_A);
            sem_post(&items_A);
        } else { // Produce PartB
            sem_wait(&slots_B);
            sem_wait(&mutex_B);
            // Critical section for buffer_B
            put_part_B(part_counter);
            printf("Worker %d produced PartB #%d. Buffer B size: %d\n", worker_id, part_counter, (in_B - out_B + BUFFER_SIZE) % BUFFER_SIZE);
            sem_post(&mutex_B);
            sem_post(&items_B);
        }
    }
    return NULL;
}

// Assembler thread function
void* assembler(void* arg) {
    int assembler_id = *(int*)arg;
    int product_counter = 0;
    while (1) {
        // Strict order for acquiring counting semaphores to prevent deadlock
        // All assemblers must wait for items_A then items_B.
        sem_wait(&items_A); // Wait for a PartA to be available
        sem_wait(&items_B); // Wait for a PartB to be available

        // Now we know both are available. Acquire mutexes in strict order.
        // All assemblers must wait for mutex_A then mutex_B.
        sem_wait(&mutex_A);
        sem_wait(&mutex_B); 

        // Critical section for both buffers
        int part_a = get_part_A();
        int part_b = get_part_B();

        sem_post(&mutex_B); // Release mutexes in reverse order
        sem_post(&mutex_A);

        sem_post(&slots_A); // Signal a slot is now free in buffer_A
        sem_post(&slots_B); // Signal a slot is now free in buffer_B

        product_counter++;
        printf("Assembler %d assembled Product #%d using PartA #%d and PartB #%d. Buffer A size: %d, Buffer B size: %d\n", 
               assembler_id, product_counter, part_a, part_b, (in_A - out_A + BUFFER_SIZE) % BUFFER_SIZE, (in_B - out_B + BUFFER_SIZE) % BUFFER_SIZE);

        sleep(rand() % 3); // Simulate assembly time
    }
    return NULL;
}

/*
// Example main function to test (not part of the required solution output)
#define NUM_WORKERS 3
#define NUM_ASSEMBLERS 2

int main() {
    // Initialize semaphores
    sem_init(&mutex_A, 0, 1);
    sem_init(&mutex_B, 0, 1);
    sem_init(&items_A, 0, 0);
    sem_init(&items_B, 0, 0);
    sem_init(&slots_A, 0, BUFFER_SIZE);
    sem_init(&slots_B, 0, BUFFER_SIZE);

    pthread_t worker_threads[NUM_WORKERS];
    pthread_t assembler_threads[NUM_ASSEMBLERS];
    int worker_ids[NUM_WORKERS];
    int assembler_ids[NUM_ASSEMBLERS];

    for (int i = 0; i < NUM_WORKERS; i++) {
        worker_ids[i] = i + 1;
        pthread_create(&worker_threads[i], NULL, worker, &worker_ids[i]);
    }

    for (int i = 0; i < NUM_ASSEMBLERS; i++) {
        assembler_ids[i] = i + 1;
        pthread_create(&assembler_threads[i], NULL, assembler, &assembler_ids[i]);
    }

    for (int i = 0; i < NUM_WORKERS; i++) {
        pthread_join(worker_threads[i], NULL);
    }

    for (int i = 0; i < NUM_ASSEMBLERS; i++) {
        pthread_join(assembler_threads[i], NULL);
    }

    // Destroy semaphores
    sem_destroy(&mutex_A);
    sem_destroy(&mutex_B);
    sem_destroy(&items_A);
    sem_destroy(&items_B);
    sem_destroy(&slots_A);
    sem_destroy(&slots_B);

    return 0;
}
