void finish_car_frame(void* car_frame) { /* Simulate work */ }

// --- Global Variables (with initialization comments) ---

// Engine Buffer
void* engine_buffer[BUFFER_SIZE];
int engine_in = 0, engine_out = 0;
sem_t engine_mutex;         // init to 1
sem_t engine_empty_slots;   // init to BUFFER_SIZE
sem_t engine_full_slots;    // init to 0

// Chassis Buffer
void* chassis_buffer[BUFFER_SIZE];
int chassis_in = 0, chassis_out = 0;
sem_t chassis_mutex;        // init to 1
sem_t chassis_empty_slots;  // init to BUFFER_SIZE
sem_t chassis_full_slots;   // init to 0

// Car Frame Buffer
void* car_frame_buffer[BUFFER_SIZE];
int car_frame_in = 0, car_frame_out = 0;
sem_t car_frame_mutex;      // init to 1
sem_t car_frame_empty_slots;// init to BUFFER_SIZE
sem_t car_frame_full_slots; // init to 0

// --- Thread Functions ---

void* engine_producer_thread(void* arg) {
    while (1) {
        void* engine = produce_engine(); // Produce an engine

        sem_wait(&engine_empty_slots); // Wait for an empty slot in engine buffer
        sem_wait(&engine_mutex);       // Acquire mutex for engine buffer access

        // Add engine to buffer
        engine_buffer[engine_in] = engine;
        engine_in = (engine_in + 1) % BUFFER_SIZE;

        sem_post(&engine_mutex);       // Release mutex for engine buffer
        sem_post(&engine_full_slots);  // Signal a full slot in engine buffer
    }
    return NULL;
}

void* chassis_producer_thread(void* arg) {
    while (1) {
        void* chassis = produce_chassis(); // Produce a chassis

        sem_wait(&chassis_empty_slots); // Wait for an empty slot in chassis buffer
        sem_wait(&chassis_mutex);       // Acquire mutex for chassis buffer access

        // Add chassis to buffer
        chassis_buffer[chassis_in] = chassis;
        chassis_in = (chassis_in + 1) % BUFFER_SIZE;

        sem_post(&chassis_mutex);       // Release mutex for chassis buffer
        sem_post(&chassis_full_slots);  // Signal a full slot in chassis buffer
    }
    return NULL;
}

void* assembly_worker_thread(void* arg) {
    while (1) {
        // --- Acquire input resources (Engines and Chassis) ---
        // Crucial for deadlock avoidance: acquire in a consistent order across all assembly workers
        sem_wait(&engine_full_slots);  // Wait for an engine to be available
        sem_wait(&chassis_full_slots); // Wait for a chassis to be available

        // --- Consume engine from engine buffer ---
        sem_wait(&engine_mutex); // Acquire mutex for engine buffer
        void* engine = engine_buffer[engine_out];
        engine_out = (engine_out + 1) % BUFFER_SIZE;
        sem_post(&engine_mutex); // Release mutex for engine buffer
        sem_post(&engine_empty_slots); // Signal an empty slot in engine buffer

        // --- Consume chassis from chassis buffer ---
        sem_wait(&chassis_mutex); // Acquire mutex for chassis buffer
        void* chassis = chassis_buffer[chassis_out];
        chassis_out = (chassis_out + 1) % BUFFER_SIZE;
        sem_post(&chassis_mutex); // Release mutex for chassis buffer
        sem_post(&chassis_empty_slots); // Signal an empty slot in chassis buffer

        // --- Assemble car frame ---
        void* car_frame = assemble_car_frame(engine, chassis);

        // --- Produce car frame into car frame buffer ---
        sem_wait(&car_frame_empty_slots); // Wait for an empty slot in car frame buffer
        sem_wait(&car_frame_mutex);        // Acquire mutex for car frame buffer access

        // Add car frame to buffer
        car_frame_buffer[car_frame_in] = car_frame;
        car_frame_in = (car_frame_in + 1) % BUFFER_SIZE;

        sem_post(&car_frame_mutex);        // Release mutex for car frame buffer
        sem_post(&car_frame_full_slots);   // Signal a full slot in car frame buffer
    }
    return NULL;
}

void* finishing_worker_thread(void* arg) {
    while (1) {
        sem_wait(&car_frame_full_slots); // Wait for a car frame to be available
        sem_wait(&car_frame_mutex);       // Acquire mutex for car frame buffer access

        // Take car frame from buffer
        void* car_frame = car_frame_buffer[car_frame_out];
        car_frame_out = (car_frame_out + 1) % BUFFER_SIZE;

        sem_post(&car_frame_mutex);       // Release mutex for car frame buffer
        sem_post(&car_frame_empty_slots); // Signal an empty slot in car frame buffer

        finish_car_frame(car_frame); // Perform final finishing work
    }
    return NULL;
}

