// Constants for buffer and batch sizes
#define BUFFER_SIZE 10
#define MIN_BATCH_SIZE 5
#define MAX_BATCH_SIZE 8 // MAX_BATCH_SIZE must be <= BUFFER_SIZE

// Shared Buffer
int buffer[BUFFER_SIZE];
int in = 0;
int out = 0;

// Synchronization Primitives
sem_t mutex; // Protects buffer, buffer_item_count, batch_processor_waiting_count
sem_t empty_slots; // Counts available empty slots in buffer
sem_t batch_processor_gate; // Controls entry to the batch acquisition critical section (turnstile)
sem_t batch_ready_signal; // Batch processors wait here for a batch to be ready

// Shared Counters, protected by mutex
int buffer_item_count = 0; // Number of items currently in the buffer
int batch_processor_waiting_count = 0; // Number of batch processors waiting for >= MIN_BATCH_SIZE items

// Function to simulate item creation
int create_item() {
    // In a real scenario, this would create an actual item
    return rand() % 100; // Just a random integer for demonstration
}

// Function to simulate item processing (for batch)
void process_item(int item) {
    // In a real scenario, this would process the item
    // printf("Processing item: %d\n", item); // Uncomment for verbose output
}

// Producer thread function
void* ItemProducer(void* arg) {
    while (1) {
        int new_item = create_item();

        sem_wait(&empty_slots); // Wait for an empty slot in the buffer

        sem_wait(&mutex); // Enter critical section to modify shared state
        buffer[in] = new_item;
        in = (in + 1) % BUFFER_SIZE;
        buffer_item_count++;
        // printf("Producer added item %d. Buffer count: %d\n", new_item, buffer_item_count); // Uncomment for verbose output

        // If enough items for a batch AND there's a BatchProcessor waiting, signal one.
        // Otherwise, just release the mutex.
        if (buffer_item_count >= MIN_BATCH_SIZE && batch_processor_waiting_count > 0) {
            sem_post(&batch_ready_signal); // Signal one waiting batch processor
        }
        sem_post(&mutex); // Exit critical section

        usleep(rand() % 100000); // Simulate work outside critical section
    }
    return NULL;
}

// Consumer (BatchProcessor) thread function
void* BatchProcessor(void* arg) {
    while (1) {
        sem_wait(&batch_processor_gate); // Acquire gate to enter batch acquisition logic (turnstile)
        sem_wait(&mutex); // Acquire mutex to check/modify shared state

        // Loop while not enough items for a batch
        while (buffer_item_count < MIN_BATCH_SIZE) {
            batch_processor_waiting_count++;
            // printf("BatchProcessor waiting. Current buffer count: %d, waiting BPs: %d\n", buffer_item_count, batch_processor_waiting_count); // Uncomment for verbose output

            sem_post(&mutex); // Release mutex to allow producers to add items
            sem_post(&batch_processor_gate); // Release gate for other BPs to try

            sem_wait(&batch_ready_signal); // Wait for a producer to signal a batch is ready

            sem_wait(&batch_processor_gate); // Re-acquire gate after waking up
            sem_wait(&mutex); // Re-acquire mutex after waking up
            batch_processor_waiting_count--;
        }

        // At this point, mutex and gate are acquired, and buffer_item_count >= MIN_BATCH_SIZE
        // Determine how many items to take for the batch
        int num_to_take = (buffer_item_count < MAX_BATCH_SIZE) ? buffer_item_count : MAX_BATCH_SIZE;
        // printf("BatchProcessor taking %d items. Buffer count before: %d\n", num_to_take, buffer_item_count); // Uncomment for verbose output

        int batch[MAX_BATCH_SIZE]; // Local array to hold the batch of items
        for (int i = 0; i < num_to_take; i++) {
            batch[i] = buffer[out]; // Take item from buffer
            out = (out + 1) % BUFFER_SIZE; // Advance circular buffer pointer
            buffer_item_count--; // Decrement item count
        }
        // printf("BatchProcessor finished taking. Buffer count after: %d\n", buffer_item_count); // Uncomment for verbose output

        // Release mutex and gate
        sem_post(&mutex);
        sem_post(&batch_processor_gate);

        // Process the batch (outside critical sections)
        for (int i = 0; i < num_to_take; i++) {
            process_item(batch[i]);
        }

        // Signal empty slots created by taking items from the buffer
        for (int i = 0; i < num_to_take; i++) {
            sem_post(&empty_slots);
        }

        usleep(rand() % 200000); // Simulate work outside critical section
    }
    return NULL;
}

/*
// Main function for testing (not part of the solution, but useful for verification)
int main() {
    pthread_t producer_threads[2], consumer_threads[2];

    // Initialize semaphores
    sem_init(&mutex, 0, 1);
    sem_init(&empty_slots, 0, BUFFER_SIZE);
    sem_init(&batch_processor_gate, 0, 1);
    sem_init(&batch_ready_signal, 0, 0);

    // Create threads
    for (int i = 0; i < 2; i++) {
        pthread_create(&producer_threads[i], NULL, ItemProducer, NULL);
        pthread_create(&consumer_threads[i], NULL, BatchProcessor, NULL);
    }

    // Run for a while
    sleep(10);

    // Clean up (optional for a quick test, but good practice)
    for (int i = 0; i < 2; i++) {
        pthread_cancel(producer_threads[i]);
        pthread_join(producer_threads[i], NULL);
        pthread_cancel(consumer_threads[i]);
        pthread_join(consumer_threads[i], NULL);
    }

    sem_destroy(&mutex);
    sem_destroy(&empty_slots);
    sem_destroy(&batch_processor_gate);
    sem_destroy(&batch_ready_signal);

    return 0;
}
