// Producer function
void producer_func(SharedData *shm_ptr, int sem_id) {
    struct sembuf p_op, v_op;

    // Acquire mutex FIRST
    p_op.sem_num = 0; p_op.sem_op = -1; p_op.sem_flg = 0; // mutex--
    if (semop(sem_id, &p_op, 1) == -1) { perror("Producer semop mutex P"); exit(1); }

    // Wait for empty slot
    p_op.sem_num = 1; p_op.sem_op = -1; p_op.sem_flg = 0; // empty--
    if (semop(sem_id, &p_op, 1) == -1) { perror("Producer semop empty P"); exit(1); }

    // Critical section: produce item
    shm_ptr->buffer[shm_ptr->in] = rand();
    shm_ptr->in = (shm_ptr->in + 1) % 10;

    // Release mutex
    v_op.sem_num = 0; v_op.sem_op = 1; v_op.sem_flg = 0; // mutex++
    if (semop(sem_id, &v_op, 1) == -1) { perror("Producer semop mutex V"); exit(1); }

    // Signal full slot
    v_op.sem_num = 2; v_op.sem_op = 1; v_op.sem_flg = 0; // full++
    if (semop(sem_id, &v_op, 1) == -1) { perror("Producer semop full V"); exit(1); }
}

