    if (semop(sem_id, &p_op, 1) == -1) { perror("Consumer semop mutex P"); exit(1); }

    // Wait for full slot
    p_op.sem_num = 2; p_op.sem_op = -1; p_op.sem_flg = 0; // full--
    if (semop(sem_id, &p_op, 1) == -1) { perror("Consumer semop full P"); exit(1); }

    // Critical section: consume item
    int item = shm_ptr->buffer[shm_ptr->out];
    shm_ptr->out = (shm_ptr->out + 1) % 10;

    // Release mutex
    v_op.sem_num = 0; v_op.sem_op = 1; v_op.sem_flg = 0; // mutex++
    if (semop(sem_id, &v_op, 1) == -1) { perror("Consumer semop mutex V"); exit(1); }

    // Signal empty slot
    v_op.sem_num = 1; v_op.sem_op = 1; v_op.sem_flg = 0; // empty++
    if (semop(sem_id, &v_op, 1) == -1) { perror("Consumer semop empty V"); exit(1); }
}

/* קטע קוד עבור תהליך P1 (כותב) */
void P1_Writer() {
    // ... shmget, shmat, semget (semid initialized to 1) ...
    struct sembuf p_op = {0, -1, 0}; // P operation on semaphore 0
    struct sembuf v_op = {0, 1, 0};  // V operation on semaphore 0

    for (int i = 0; i < 5; ++i) {
        semop(semid, &p_op, 1); // Wait for shared memory access
        sprintf(shm_ptr, "Data item %d", i); // Write to shared memory
        printf("P1 wrote: %s\n", shm_ptr);
        semop(semid, &v_op, 1); // Release shared memory access
        sleep(1);
    }
    // ... shmdt, shmctl, semctl(IPC_RMID) ...
}

/* קטע קוד עבור תהליך P2 (קורא) */
void P2_Reader() {
    // ... shmget, shmat, semget ...
    struct sembuf p_op = {0, -1, 0}; // P operation on semaphore 0
    struct sembuf v_op = {0, 1, 0};  // V operation on semaphore 0

    for (int i = 0; i < 5; ++i) {
        semop(semid, &p_op, 1); // Wait for shared memory access
        printf("P2 read: %s\n", shm_ptr); // Read from shared memory
        semop(semid, &v_op, 1); // Release shared memory access
        sleep(1);
    }
    // ... shmdt ...
}

/* קטע קוד עבור תהליך היצרן */
void producer_process() {
    /* ... קוד אתחול ... */
    while (true) {
        // ייצור פריט
        sem_wait(mutex);      // (1)
        sem_wait(empty);      // (2)
        // הוספת פריט לחוצץ המשותף
        sem_post(full);       // (3)
        sem_post(mutex);      // (4)
    }
}

/* קטע קוד עבור תהליך הצרכן */
void consumer_process() {
    /* ... קוד אתחול ... */
    while (true) {
        sem_wait(mutex);      // (A)
        sem_wait(full);       // (B)
        // הסרת פריט מהחוצץ המשותף
        sem_post(empty);      // (C)
        sem_post(mutex);      // (D)
        // צריכת פריט
    }
}

// הגדרות והאתחול של זיכרון משותף וסמפורים בוצעו כראוי
// sem_t *mutex, *empty, *full;
// N הוא גודל הבאפר המשותף

// קוד היצרן (Producer)
void producer_task() {
    // ... קוד הכנסת נתונים לבאפר משותף ...
    sem_wait(mutex); // (1) תפיסת מנעול הדדי
    sem_wait(empty); // (2) המתנה למקום פנוי
    // הוספת פריט לבאפר
    // ...
    sem_post(full);  // (3) סימון מקום מלא
    sem_post(mutex); // (4) שחרור מנעול הדדי
}

// קוד הצרכן (Consumer)
void consumer_task() {
    // ... קוד הוצאת נתונים מהבאפר המשותף ...
    sem_wait(mutex); // (A) תפיסת מנעול הדדי
    sem_wait(full);  // (B) המתנה לפריט קיים
    // הוצאת פריט מהבאפר
    // ...
    sem_post(empty); // (C) סימון מקום פנוי
    sem_post(mutex); // (D) שחרור מנעול הדדי
}

