solution.explanation:
צינורות (pipes) הם מנגנון IPC פשוט המשמש לתקשורת חד-כיוונית בין תהליכים קשורים (בדרך כלל אב ובן). כאשר תהליך יוצר pipe באמצעות קריאת המערכת `pipe()`, נוצרים שני קצוות לקובץ: קצה אחד לכתיבה וקצה אחד לקריאה (לרוב `pipe_fd[1]` לכתיבה ו-`pipe_fd[0]` לקריאה). לאחר מכן, כאשר תהליך האב מבצע `fork()`, תהליך הבן יורש את כל ה-file descriptors הפתוחים, כולל אלה של ה-pipe. כדי לאפשר תקשורת חד-כיוונית, אחד התהליכים סוגר את קצה הכתיבה וקורא מקצה הקריאה, והתהליך השני סוגר את קצה הקריאה וכותב לקצה הכתיבה. הנתונים נכתבים לקצה הכתיבה ונקראים מקצה הקריאה בסדר FIFO (First-In, First-Out).

להלן דוגמת קוד פשוטה:
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <string.h>
#include <sys/wait.h> // For wait()

#define MSG_SIZE 256

int main() {
    int pipe_fd[2]; // pipe_fd[0] for reading, pipe_fd[1] for writing
    pid_t pid;
    char write_msg[MSG_SIZE] = "שלום מהאב לבן!";
    char read_msg[MSG_SIZE];

    // Create a pipe
    if (pipe(pipe_fd) == -1) {
        perror("pipe failed");
        exit(EXIT_FAILURE);
    }

    // Fork a child process
    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }

    if (pid > 0) { // Parent process
        close(pipe_fd[0]); // Close unused read end in parent
        printf("אב: שולח הודעה: \"%s\"\n", write_msg);
        // Write to the pipe
        write(pipe_fd[1], write_msg, strlen(write_msg) + 1);
        close(pipe_fd[1]); // Close write end in parent
        wait(NULL); // Wait for child to finish
        printf("אב: סיים.\n");
    } else { // Child process
        close(pipe_fd[1]); // Close unused write end in child
        // Read from the pipe
        read(pipe_fd[0], read_msg, MSG_SIZE);
        printf("בן: קיבל הודעה: \"%s\"\n", read_msg);
        close(pipe_fd[0]); // Close read end in child
        printf("בן: סיים.\n");
    }

    return 0;
}
```
שימו לב שבקוד ההדגמה, תהליך האב סוגר את קצה הקריאה (pipe_fd[0]) וכותב לקצה הכתיבה (pipe_fd[1]), בעוד שתהליך הבן סוגר את קצה הכתיבה (pipe_fd[1]) וקורא מקצה הקריאה (pipe_fd[0]).

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

#define NUM_INTEGERS 10

// Helper function to ensure all bytes are written
ssize_t write_all(int fd, const void *buf, size_t count) {
    size_t bytes_written = 0;
    while (bytes_written < count) {
        ssize_t res = write(fd, (const char *)buf + bytes_written, count - bytes_written);
        if (res == -1) {
            perror("write_all error");
            return -1;
        } else if (res == 0) {
            // Should not happen for pipes unless write end is closed
            break;
        }
        bytes_written += res;
    }
    return bytes_written;
}

// Helper function to ensure all bytes are read
ssize_t read_all(int fd, void *buf, size_t count) {
    size_t bytes_read = 0;
    while (bytes_read < count) {
        ssize_t res = read(fd, (char *)buf + bytes_read, count - bytes_read);
        if (res == -1) {
            perror("read_all error");
            return -1;
        } else if (res == 0) {
            // EOF
            break;
        }
        bytes_read += res;
    }
    return bytes_read;
}

int main() {
    int pipe_parent_to_child[2]; // pipe_parent_to_child[0] for read, [1] for write
    int pipe_child_to_parent[2]; // pipe_child_to_parent[0] for read, [1] for write
    pid_t pid;

    // Create first pipe (parent -> child)
    if (pipe(pipe_parent_to_child) == -1) {
        perror("pipe_parent_to_child failed");
        exit(EXIT_FAILURE);
    }

    // Create second pipe (child -> parent)
    if (pipe(pipe_child_to_parent) == -1) {
        perror("pipe_child_to_parent failed");
        exit(EXIT_FAILURE);
    }

    pid = fork();

    if (pid == -1) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        // Close unused pipe ends
        close(pipe_parent_to_child[1]); // Child doesn't write to this pipe
        close(pipe_child_to_parent[0]); // Child doesn't read from this pipe

        int received_num;
        long long sum = 0;
        printf("Child: Ready to receive numbers.\n");

        for (int i = 0; i < NUM_INTEGERS; ++i) {
            if (read_all(pipe_parent_to_child[0], &received_num, sizeof(int)) != sizeof(int)) {
                perror("Child: Failed to read all bytes or EOF before expected");
                break;
            }
            printf("Child: Received %d\n", received_num);
            sum += received_num;
        }
        printf("Child: Calculated sum: %lld\n", sum);

        // Write sum back to parent
        if (write_all(pipe_child_to_parent[1], &sum, sizeof(long long)) != sizeof(long long)) {
            perror("Child: Failed to write sum");
            exit(EXIT_FAILURE);
        }
        printf("Child: Sent sum to parent.\n");

        // Close remaining pipe ends
        close(pipe_parent_to_child[0]);
        close(pipe_child_to_parent[1]);

        exit(EXIT_SUCCESS);

    } else { // Parent process
        // Close unused pipe ends
        close(pipe_parent_to_child[0]); // Parent doesn't read from this pipe
        close(pipe_child_to_parent[1]); // Parent doesn't write to this pipe

        srand(time(NULL)); // Seed random number generator
        int numbers[NUM_INTEGERS];
        printf("Parent: Generating and sending numbers.\n");

        for (int i = 0; i < NUM_INTEGERS; ++i) {
            numbers[i] = rand() % 100 + 1; // Random numbers between 1 and 100
            if (write_all(pipe_parent_to_child[1], &numbers[i], sizeof(int)) != sizeof(int)) {
                perror("Parent: Failed to write all bytes");
                exit(EXIT_FAILURE);
            }
            printf("Parent: Sent %d\n", numbers[i]);
        }
        // Close the write end of pipe_parent_to_child to signal EOF to child
        close(pipe_parent_to_child[1]);
        printf("Parent: Finished sending numbers and closed write end of pipe_parent_to_child.\n");

        long long received_sum;
        // Read sum from child
        if (read_all(pipe_child_to_parent[0], &received_sum, sizeof(long long)) != sizeof(long long)) {
            perror("Parent: Failed to read sum from child");
            exit(EXIT_FAILURE);
        }
        printf("Parent: Received sum from child: %lld\n", received_sum);

        // Close remaining pipe ends
        close(pipe_child_to_parent[0]);

        // Wait for child to terminate
        wait(NULL);
        printf("Parent: Child terminated. Exiting.\n");

        exit(EXIT_SUCCESS);
    }

    return 0;
}
```

