/* Assume shared memory 'buffer' and size 'BUFFER_SIZE' exist.
 * Assume 'in' and 'out' pointers/indices for circular buffer exist in shared memory.
 *
 * Semaphores (initialized once, e.g., using sem_open):
 * semaphore_t mutex;      // Binary semaphore for mutual exclusion, initialized to 1
 * semaphore_t empty;      // Counting semaphore for empty slots, initialized to BUFFER_SIZE
 * semaphore_t full;       // Counting semaphore for full slots, initialized to 0
 */

// --- Producer Process Logic ---
void producer_process() {
    item_t item;
    while (true) {
        // 1. Produce an item
        produce_item(&item);

        // 2. Wait if buffer is full (empty slots semaphore)
        sem_wait(&empty); 

        // 3. Acquire lock for shared buffer (mutex semaphore)
        sem_wait(&mutex); 

        // 4. Add item to buffer
        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;

        // 5. Release lock
        sem_post(&mutex); 

        // 6. Signal that buffer has a full slot (full slots semaphore)
        sem_post(&full);  
    }
}

// --- Consumer Process Logic ---
void consumer_process() {
    item_t item;
    while (true) {
        // 1. Wait if buffer is empty (full slots semaphore)
        sem_wait(&full);  

        // 2. Acquire lock for shared buffer (mutex semaphore)
        sem_wait(&mutex); 

        // 3. Remove item from buffer
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;

        // 4. Release lock
        sem_post(&mutex); 

        // 5. Signal that buffer has an empty slot (empty slots semaphore)
        sem_post(&empty); 

        // 6. Consume the item
        consume_item(&item);
    }
}

solution.explanation:
הפתרון מדגים תקשורת דו-כיוונית בין תהליך אב לתהליך בן באמצעות שני צינורות (pipes) נפרדים.

1.  **יצירת צינורות**: תחילה, נוצרים שני צינורות באמצעות הפונקציה `pipe()`. כל קריאה ל-`pipe()` יוצרת שני קצוות: קצה קריאה (file descriptor 0) וקצה כתיבה (file descriptor 1). `pipe_p2c` משמש לתקשורת מהאב לבן, ו-`pipe_c2p` משמש לתקשורת מהבן לאב.
2.  **יצירת תהליך בן**: הפונקציה `fork()` משמשת ליצירת תהליך בן.
    *   **בתהליך האב (`pid > 0`)**: האב סוגר את הקצוות הלא-נחוצים: את קצה הקריאה של `pipe_p2c` ואת קצה הכתיבה של `pipe_c2p`. לאחר מכן, הוא כותב את המחרוזת המקורית ל-`pipe_p2c[WRITE_END]`, סוגר את קצה הכתיבה, קורא את המחרוזת המעובדת מ-`pipe_c2p[READ_END]`, מדפיס אותה וסוגר את קצה הקריאה. לבסוף, הוא ממתין לסיום ריצת התהליך הבן באמצעות `wait(NULL)`.
    *   **בתהליך הבן (`pid == 0`)**: הבן סוגר את הקצוות הלא-נחוצים: את קצה הכתיבה של `pipe_p2c` ואת קצה הקריאה של `pipe_c2p`. לאחר מכן, הוא קורא את המחרוזת מהאב מ-`pipe_p2c[READ_END]`, מעבד אותה (ממיר לאותיות גדולות באמצעות `to_uppercase` המשתמשת ב-`toupper`), כותב את המחרוזת המעובדת ל-`pipe_c2p[WRITE_END]`, סוגר את הקצוות ויוצא.
3.  **פונקציית `to_uppercase`**: פונקציה עזר זו עוברת על המחרוזת תו-תו וממירה כל תו לאות גדולה באמצעות `toupper()` מהספרייה `ctype.h`.
4.  **חשיבות סגירת הקצוות**: סגירת קצוות הצינורות שאינם בשימוש היא קריטית כדי למנוע מצב של deadlock (למשל, תהליך שמנסה לקרוא מצינור שקצה הכתיבה שלו עדיין פתוח אך אף תהליך לא יכתוב אליו יותר). כמו כן, זה משחרר משאבי מערכת.

להלן קוד לדוגמה:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>
#include <ctype.h> // For toupper

#define BUFFER_SIZE 256
#define READ_END 0
#define WRITE_END 1

void to_uppercase(char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        str[i] = toupper((unsigned char)str[i]);
    }
}

int main() {
    int pipe_p2c[2]; // Parent to Child
    int pipe_c2p[2]; // Child to Parent
    pid_t pid;
    char buffer[BUFFER_SIZE];
    const char *initial_message = "hello operating systems world";

    // Create pipes
    if (pipe(pipe_p2c) == -1) {
        perror("pipe_p2c failed");
        return 1;
    }
    if (pipe(pipe_c2p) == -1) {
        perror("pipe_c2p failed");
        return 1;
    }

    pid = fork();

    if (pid < 0) { // Error
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // Child process
        // Close unused ends
        close(pipe_p2c[WRITE_END]);
        close(pipe_c2p[READ_END]);

        // Read from parent
        read(pipe_p2c[READ_END], buffer, BUFFER_SIZE);
        printf("Child received: \"%s\"\n", buffer);

        // Process message
        to_uppercase(buffer);

        // Write to parent
        write(pipe_c2p[WRITE_END], buffer, strlen(buffer) + 1);
        printf("Child sent: \"%s\"\n", buffer);

        // Close remaining ends
        close(pipe_p2c[READ_END]);
        close(pipe_c2p[WRITE_END]);
        exit(0);
    } else { // Parent process
        // Close unused ends
        close(pipe_p2c[READ_END]);
        close(pipe_c2p[WRITE_END]);

        // Write to child
        write(pipe_p2c[WRITE_END], initial_message, strlen(initial_message) + 1);
        printf("Parent sent: \"%s\"\n", initial_message);

        // Close parent-to-child write end as it's done sending
        close(pipe_p2c[WRITE_END]);

        // Read from child
        read(pipe_c2p[READ_END], buffer, BUFFER_SIZE);
        printf("Parent received: \"%s\"\n", buffer);

        // Close child-to-parent read end
        close(pipe_c2p[READ_END]);

        // Wait for child to terminate
        wait(NULL);
        printf("Parent finished.\n");
    }

    return 0;
}

