#include <stdio.h>
#include <stdlib.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>

#define BUFFER_SIZE 10    // גודל המאגר
#define MUTEX_SEM_NUM 0   // מספר סמפור ה-mutex בקבוצה
#define EMPTY_SEM_NUM 1   // מספר סמפור ה-empty בקבוצה
#define FULL_SEM_NUM 2    // מספר סמפור ה-full בקבוצה

// מבנה הנתונים המשותף
typedef struct {
    int buffer[BUFFER_SIZE];
    int in;  // מצביע למקום הבא להכנסה
    int out; // מצביע למקום הבא לקריאה
} SharedData;

// פונקציות עזר לביצוע פעולות סמפור
void sem_wait(int sem_id, int sem_num) {
    struct sembuf sb = {sem_num, -1, 0}; // Decrement semaphore, wait if 0
    if (semop(sem_id, &sb, 1) == -1) {
        perror("semop wait");
        exit(EXIT_FAILURE);
    }
}

void sem_post(int sem_id, int sem_num) {
    struct sembuf sb = {sem_num, 1, 0}; // Increment semaphore
    if (semop(sem_id, &sb, 1) == -1) {
        perror("semop post");
        exit(EXIT_FAILURE);
    }
}

// קטע קוד המדגים את לוגיקת ה-Producer להכנסת פריט
// הנחה: 'sem_id' הוא ה-ID של קבוצת הסמפורים
// הנחה: 'shared_data' הוא מצביע לזיכרון המשותף
void producer_insert_item(int sem_id, SharedData *shared_data, int item_to_produce) {
    // 1. המתנה למקום פנוי במאגר (סמפור 'empty')
    sem_wait(sem_id, EMPTY_SEM_NUM);

    // 2. כניסה למקטע קריטי (הגנה על הגישה למאגר - סמפור 'mutex')
    sem_wait(sem_id, MUTEX_SEM_NUM);

    // 3. הכנסת הפריט למאגר
    shared_data->buffer[shared_data->in] = item_to_produce;
    shared_data->in = (shared_data->in + 1) % BUFFER_SIZE;
    // printf("Producer: Inserted item %d. Next 'in' index: %d\n", item_to_produce, shared_data->in); // ניתן להפעיל להדגמה

    // 4. יציאה מהמקטע הקריטי
    sem_post(sem_id, MUTEX_SEM_NUM);

    // 5. איתות שהמאגר מכיל פריט נוסף (סמפור 'full')
    sem_post(sem_id, FULL_SEM_NUM);
}

// הערה: ביישום מלא, יש צורך בקוד נוסף ליצירת זיכרון משותף וסמפורים, אתחולם,
// וכן לולאה שמייצרת פריטים וקוראת לפונקציה producer_insert_item.

/* מבנה הנתונים בזיכרון המשותף */
typedef struct {
    int data[10];
} shared_data_t;

/* פונקציה המדמה את תהליך P1 (הכותב) */
void process_p1(sem_t *empty_sem, sem_t *full_sem, shared_data_t *shm_ptr) {
    for (int i = 0; i < 5; ++i) { // לדוגמה: כתיבה של 5 בלוקים של נתונים
        sem_wait(empty_sem); // המתן אם הזיכרון המשותף מלא (P2 עדיין לא קרא)

        printf("P1: Writing data block %d\n", i);
        for (int j = 0; j < 10; ++j) {
            shm_ptr->data[j] = i * 100 + j; // כתיבת נתונים לזיכרון המשותף
        }

        sem_post(full_sem); // סמן שהזיכרון המשותף מלא (הנתונים מוכנים לקריאה ע"י P2)
        sleep(1); // הדמיית עבודה
    }
}

/* פונקציה המדמה את תהליך P2 (הקורא) */
void process_p2(sem_t *empty_sem, sem_t *full_sem, shared_data_t *shm_ptr) {
    for (int i = 0; i < 5; ++i) { // לדוגמה: קריאה של 5 בלוקים של נתונים
        sem_wait(full_sem); // המתן אם הזיכרון המשותף ריק (P1 עדיין לא כתב)

        printf("P2: Reading data block %d: [", i);
        for (int j = 0; j < 10; ++j) {
            printf("%d ", shm_ptr->data[j]); // קריאת נתונים מהזיכרון המשותף
        }
        printf("]\n");

        sem_post(empty_sem); // סמן שהזיכרון המשותף ריק (P2 סיים לקרוא)
        sleep(2); // הדמיית עבודה
    }
}

solution.explanation:
### פתרון מפורט:

#### 1.1 תכנון המבנה ומנגנוני IPC:

**מבנה הזיכרון המשותף (Shared Memory Structure):**
נזדקק למבנה שיכיל את החוצץ המעגלי עצמו, יחד עם משתנים שינהלו אותו:
```c
typedef struct {
    int buffer[BUFFER_SIZE]; // החוצץ המעגלי לאחסון מספרים שלמים
    int head;                // אינדקס התא הבא לקריאה (על ידי צרכן)
    int tail;                // אינדקס התא הבא לכתיבה (על ידי יצרן)
    // int count;            // ניתן לגזור מסמפורים, או להשתמש לצרכי דיבוג
} SharedBuffer;
```
-   `buffer`: מערך של מספרים שלמים בגודל `BUFFER_SIZE` שישמש כחוצץ המעגלי.
-   `head`: מצביע לאינדקס התא הראשון המכיל נתון שטרם נצרך. תהליכי צרכן קוראים מ-`head` ומקדמים אותו.
-   `tail`: מצביע לאינדקס התא הפנוי הבא לכתיבה. תהליכי יצרן כותבים ל-`tail` ומקדמים אותו.

**מנגנוני IPC:**
לפתרון בעיית יצרן-צרכן מרובה תהליכים באמצעות זיכרון משותף, נדרשים שלושה סמפורים (Named Semaphores הם הבחירה המתאימה לתקשורת בין תהליכים שאינם קשורים בהכרח בקשר הורה-ילד): 

1.  **`sem_t *mutex` (סמפור הדדיות - Mutual Exclusion):** 
    -   **מטרה:** להבטיח שרק תהליך אחד (יצרן או צרכן) יוכל לגשת ולשנות את המשתנים המשותפים (`head`, `tail`) ואת תוכן החוצץ המעגלי בו זמנית. זה מונע Race Conditions בגישה למבנה ה-`SharedBuffer`.
    -   **ערך התחלתי:** 1 (סמפור בינארי).

2.  **`sem_t *empty` (סמפור "ריק" - Empty Slots):**
    -   **מטרה:** לספור את מספר התאים הריקים הזמינים בחוצץ. יצרנים ממתינים לסמפור זה לפני שהם כותבים, כדי לוודא שיש מקום פנוי. כל פעולת כתיבה מקטינה את ערכו. 
    -   **ערך התחלתי:** `BUFFER_SIZE` (מספר התאים הכולל בחוצץ).

3.  **`sem_t *full` (סמפור "מלא" - Full Slots):**
    -   **מטרה:** לספור את מספר התאים המלאים בחוצץ המכילים נתונים. צרכנים ממתינים לסמפור זה לפני שהם קוראים, כדי לוודא שיש נתונים זמינים. כל פעולת קריאה מקטינה את ערכו. 
    -   **ערך התחלתי:** 0 (בתחילה החוצץ ריק).

**נימוק לבחירה:**
-   **זיכרון משותף (Shared Memory):** נבחר בזכות היותו מנגנון ה-IPC המהיר ביותר, שכן הוא מאפשר גישה ישירה לנתונים ללא צורך בהעתקה דרך הקרנל. מתאים למקרים בהם יש צורך בהעברת כמויות גדולות של נתונים או ביצועים גבוהים.
-   **סמפורים בעלי שם (Named Semaphores):** מתאימים לתקשורת בין תהליכים שאינם קשורים (לדוגמה, תהליכים שהופעלו בנפרד או שנוצרו על ידי `fork` אך צריכים לשתף משאבים). הם ניתנים לגישה לפי שם במערכת הקבצים הוירטואלית, מה שמקל על איתורם ושימושם על ידי תהליכים שונים.

#### 1.2 קוד C/C++:

**הגדרות וקוד Setup (ניתן לכלול בקובץ נפרד או כפונקציית אתחול):**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <semaphore.h>
#include <errno.h>

#define BUFFER_SIZE 10
#define SHM_NAME "/my_shared_buffer"
#define SEM_MUTEX_NAME "/sem_mutex"
#define SEM_EMPTY_NAME "/sem_empty"
#define SEM_FULL_NAME "/sem_full"

typedef struct {
    int buffer[BUFFER_SIZE];
    int head; // Index for consumers to read from
    int tail; // Index for producers to write to
} SharedBuffer;

SharedBuffer *shm_buffer = NULL;
sem_t *mutex = NULL;
sem_t *empty = NULL;
sem_t *full = NULL;

// פונקציה לאתחול זיכרון משותף וסמפורים
void init_shared_resources() {
    int shm_fd;

    // יצירה/פתיחה של מקטע זיכרון משותף
    shm_fd = shm_open(SHM_NAME, O_CREAT | O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("shm_open");
        exit(EXIT_FAILURE);
    }

    // הגדרת גודל הזיכרון המשותף
    if (ftruncate(shm_fd, sizeof(SharedBuffer)) == -1) {
        perror("ftruncate");
        exit(EXIT_FAILURE);
    }

    // מיפוי הזיכרון המשותף למרחב הכתובות של התהליך
    shm_buffer = (SharedBuffer *)mmap(NULL, sizeof(SharedBuffer), PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // אתחול החוצץ המשותף. חשוב שזה יקרה רק פעם אחת!
    // במערכת אמיתית, נהוג שיהיה תהליך אתחול ייעודי. 
    // לצורך הדגמה, נניח שזה נקרא ע"י התהליך הראשון שמתחיל.
    shm_buffer->head = 0;
    shm_buffer->tail = 0;

    // יצירה/פתיחה של סמפורים
    mutex = sem_open(SEM_MUTEX_NAME, O_CREAT, 0666, 1);
    if (mutex == SEM_FAILED) {
        perror("sem_open mutex");
        exit(EXIT_FAILURE);
    }

    empty = sem_open(SEM_EMPTY_NAME, O_CREAT, 0666, BUFFER_SIZE);
    if (empty == SEM_FAILED) {
        perror("sem_open empty");
        exit(EXIT_FAILURE);
    }

    full = sem_open(SEM_FULL_NAME, O_CREAT, 0666, 0);
    if (full == SEM_FAILED) {
        perror("sem_open full");
        exit(EXIT_FAILURE);
    }
}

// פונקציה לניקוי משאבים משותפים. יש לקרוא אותה מתהליך ייעודי בלבד.
void cleanup_shared_resources() {
    // סגירת מיפוי הזיכרון
    if (shm_buffer != NULL) {
        if (munmap(shm_buffer, sizeof(SharedBuffer)) == -1) {
            perror("munmap");
        }
    }
    // סגירת סמפורים
    if (mutex != NULL) sem_close(mutex);
    if (empty != NULL) sem_close(empty);
    if (full != NULL) sem_close(full);

    // מחיקת אובייקטי סמפור וזיכרון משותף מהמערכת
    // פעולות אלה צריכות להתבצע רק כאשר אף תהליך לא משתמש בהם יותר
    sem_unlink(SEM_MUTEX_NAME);
    sem_unlink(SEM_EMPTY_NAME);
    sem_unlink(SEM_FULL_NAME);
    shm_unlink(SHM_NAME);
}
```

**קוד תהליך יצרן (Producer Process Logic):**
```c
// פונקציה זו מייצגת שלב ייצור בודד
void produce_item(int item) {
    // המתן לתא ריק (מקטין את סמפור empty)
    // מבטיח שהיצרן ממתין אם החוצץ מלא
    if (sem_wait(empty) == -1) { perror("sem_wait empty (producer)"); exit(EXIT_FAILURE); }

    // קבלת מנעול הדדיות (mutex) (מבטיח גישה בלעדית לחוצץ המשותף)
    if (sem_wait(mutex) == -1) { perror("sem_wait mutex (producer)"); exit(EXIT_FAILURE); }

    // קטע קריטי: הוסף פריט לחוצץ
    shm_buffer->buffer[shm_buffer->tail] = item;
    shm_buffer->tail = (shm_buffer->tail + 1) % BUFFER_SIZE;
    printf("Producer added %d to buffer. Current tail: %d\n", item, shm_buffer->tail);

    // שחרור מנעול הדדיות (mutex)
    if (sem_post(mutex) == -1) { perror("sem_post mutex (producer)"); exit(EXIT_FAILURE); }

    // איתות שתא התמלא (מגדיל את סמפור full)
    if (sem_post(full) == -1) { perror("sem_post full (producer)"); exit(EXIT_FAILURE); }
}

// דוגמה לפונקציית main עבור יצרן (מפושטת)
int main() {
    init_shared_resources(); // נניח שתהליך זה הוא לא המאתחל הייעודי

    int data_to_produce = getpid(); // דוגמה: נתוני ייצור הם ה-PID של התהליך
    produce_item(data_to_produce);

    // cleanup_shared_resources(); // יש לקרוא רק מתהליך ניקוי ייעודי
    return 0;
}
```

**קוד תהליך צרכן (Consumer Process Logic):**
```c
// פונקציה זו מייצגת שלב צריכה בודד
int consume_item() {
    int item;

    // המתן לתא מלא (מקטין את סמפור full)
    // מבטיח שהצרכן ממתין אם החוצץ ריק
    if (sem_wait(full) == -1) { perror("sem_wait full (consumer)"); exit(EXIT_FAILURE); }

    // קבלת מנעול הדדיות (mutex) (מבטיח גישה בלעדית לחוצץ המשותף)
    if (sem_wait(mutex) == -1) { perror("sem_wait mutex (consumer)"); exit(EXIT_FAILURE); }

    // קטע קריטי: הסר פריט מהחוצץ
    item = shm_buffer->buffer[shm_buffer->head];
    shm_buffer->head = (shm_buffer->head + 1) % BUFFER_SIZE;
    printf("Consumer read %d from buffer. Current head: %d\n", item, shm_buffer->head);

    // שחרור מנעול הדדיות (mutex)
    if (sem_post(mutex) == -1) { perror("sem_post mutex (consumer)"); exit(EXIT_FAILURE); }

    // איתות שתא התפנה (מגדיל את סמפור empty)
    if (sem_post(empty) == -1) { perror("sem_post empty (consumer)"); exit(EXIT_FAILURE); }

    return item;
}

// דוגמה לפונקציית main עבור צרכן (מפושטת)
int main() {
    init_shared_resources(); // נניח שתהליך זה הוא לא המאתחל הייעודי

    int consumed_data = consume_item();
    printf("Consumer consumed item: %d\n", consumed_data);

    // cleanup_shared_resources(); // יש לקרוא רק מתהליך ניקוי ייעודי
    return 0;
}
```

#### 1.3 ניתוח סינכרון:

**הכרחיות הסמפורים:**
1.  **`mutex`:**
    -   **הכרחיות:** מונע Race Conditions בגישה למשתנים המשותפים `head`, `tail`, ותוכן ה-`buffer` עצמו. לדוגמה, אם שני יצרנים ינסו לכתוב בו-זמנית לאותו תא (או תאים סמוכים כאשר `tail` מתעדכן באופן לא אטומי), או אם יצרן וצרכן ינסו לגשת לאותם אינדקסים או לעדכן את `head`/`tail` בו-זמנית, הנתונים בחוצץ עלולים להיהרס או שהאינדקסים יהפכו לבלתי עקביים.
    -   **השלכות של השמטה/יישום שגוי (לדוגמה, השמטה):**
        -   **Race Conditions:** מספר תהליכים יגשו וישנו את `head`, `tail` או את תוכן המערך בו-זמנית, מה שיוביל לנתונים שגויים, דריסת נתונים, או מצב לא עקבי של החוצץ.
        -   **דוגמה:** יצרן קורא את `tail`, מחושב האינדקס לכתיבה. לפני שהוא כותב, יצרן אחר קורא גם הוא את `tail` (שלא עודכן עדיין), כותב לאותו אינדקס, מעדכן את `tail`. היצרן הראשון כותב שוב לאותו אינדקס (דורך על הנתון של היצרן השני) ומעדכן את `tail` שוב, מה שמוביל לאיבוד נתונים ולמצב לא עקבי.

2.  **`empty`:**
    -   **הכרחיות:** מבטיח שיצרן ימתין אם החוצץ מלא ואין מקום פנוי לכתיבה. הוא סופר את מספר התאים הריקים. `sem_wait(empty)` מקטין את הספירה; אם היא מגיעה ל-0, היצרן נחסם עד שצרכן משחרר תא.
    -   **השלכות של השמטה/יישום שגוי (לדוגמה, השמטה):**
        -   **דריסת נתונים (Buffer Overflow):** יצרנים ינסו לכתוב לחוצץ גם כשהוא מלא, ידחפו נתונים לתאים שכבר מכילים נתונים שטרם נצרכו, וידרסו אותם. זה יוביל לאיבוד נתונים ולמצב לא עקבי.
        -   **Deadlock (סדר פעולות שגוי):** אם יצרן מבצע `sem_wait(mutex)` לפני `sem_wait(empty)`, והחוצץ מלא, היצרן יחזיק את ה-`mutex` וייחסם ב-`sem_wait(empty)`. צרכנים יצטרכו את ה-`mutex` כדי לקרוא ולשחרר מקום, אך הם לא יוכלו להשיג אותו. זהו מצב של Deadlock. סדר הפעולות הנכון הוא קודם `sem_wait(empty)` ורק אז `sem_wait(mutex)`.

3.  **`full`:**
    -   **הכרחיות:** מבטיח שצרכן ימתין אם החoצץ ריק ואין נתונים לצריכה. הוא סופר את מספר התאים המלאים. `sem_wait(full)` מקטין את הספירה; אם היא מגיעה ל-0, הצרכן נחסם עד שיצרן כותב נתון.
    -   **השלכות של השמטה/יישום שגוי (לדוגמה, השמטה):**
        -   **קריאת נתונים שגויים/לא קיימים (Buffer Underflow):** צרכנים ינסו לקרוא מהחוצץ גם כשהוא ריק, מה שיוביל לקריאת נתונים זבל או נתונים שכבר נצרכו, ולשגיאות לוגיות.
        -   **Deadlock (סדר פעולות שגוי):** אם צרכן מבצע `sem_wait(mutex)` לפני `sem_wait(full)`, והחוצץ ריק, הצרכן יחזיק את ה-`mutex` וייחסם ב-`sem_wait(full)`. יצרנים יצטרכו את ה-`mutex` כדי לכתוב נתונים ולשחרר את הצרכן, אך הם לא יוכלו להשיג אותו. זהו מצב של Deadlock. סדר הפעולות הנכון הוא קודם `sem_wait(full)` ורק אז `sem_wait(mutex)`.

**סדר פעולות נכון (Producer):** `sem_wait(empty)` -> `sem_wait(mutex)` -> [Critical Section] -> `sem_post(mutex)` -> `sem_post(full)`.
**סדר פעולות נכון (Consumer):** `sem_wait(full)` -> `sem_wait(mutex)` -> [Critical Section] -> `sem_post(mutex)` -> `sem_post(empty)`.

#### 1.4 טיפול בשגיאות וניקוי משאבים:

**טיפול בשגיאות:**
-   **בדיקת ערכי החזרה:** כל קריאת מערכת (system call) כגון `shm_open`, `ftruncate`, `mmap`, `sem_open`, `sem_wait`, `sem_post`, `munmap`, `sem_close`, `sem_unlink`, `shm_unlink` מחזירה ערך המציין הצלחה או כישלון. יש לבדוק ערכים אלו (לרוב -1 במקרה של כישלון) ולהשתמש ב-`perror()` כדי להדפיף הודעת שגיאה מפורטת, וב-`exit(EXIT_FAILURE)` כדי לסיים את התהליך באופן נקי אם השגיאה קריטית.
-   **טיפול ב-`MAP_FAILED`:** עבור `mmap`, יש לבדוק אם הערך המוחזר הוא `MAP_FAILED` במקום -1.
-   **טיפול ב-`SEM_FAILED`:** עבור `sem_open`, יש לבדוק אם הערך המוחזר הוא `SEM_FAILED` במקום -1.
-   **סדר סגירה/שחרור משאבים במקרה שגיאה:** אם שגיאה מתרחשת באמצע אתחול, יש לוודא שמשאבים שכבר נפתחו (לדוגמה, קובץ זיכרון משותף או סמפורים) ייסגרו או ישוחררו לפני היציאה.

**ניקוי משאבים (Resource Cleanup):**
ניקוי משאבים חיוני כדי למנוע דליפות זיכרון וסמפורים מיותרים במערכת.
-   **`munmap(shm_buffer, sizeof(SharedBuffer))`:** משחרר את מיפוי הזיכרון המשותף ממרחב הכתובות של התהליך. כל תהליך שמיפה את הזיכרון המשותף צריך לבצע `munmap` לפני סיום.
-   **`sem_close(sem_t *sem)`:** סוגר את הסמפור עבור התהליך הקורא. כל תהליך שפתח סמפור באמצעות `sem_open` צריך לסגור אותו באמצעות `sem_close` לפני סיום.
-   **`shm_unlink(SHM_NAME)`:** מוחק את אובייקט הזיכרון המשותף מהמערכת. פעולה זו צריכה להתבצע רק כאשר אין יותר תהליכים המשתמשים בזיכרון המשותף. בדרך כלל, תהליך ייעודי (לדוגמה, ה-"מנהל" של המערכת או תהליך Cleanup נפרד) הוא שיבצע פעולה זו בסיום העבודה של כלל היצרנים והצרכנים.
-   **`sem_unlink(SEM_MUTEX_NAME)`, `sem_unlink(SEM_EMPTY_NAME)`, `sem_unlink(SEM_FULL_NAME)`:** מוחקים את אובייקטי הסמפורים מהמערכת. בדומה ל-`shm_unlink`, פעולות אלו צריכות להתבצע רק כאשר אין יותר תהליכים המשתמשים בסמפורים. תהליך ייעודי או תהליך ה-Cleanup יבצע אותן.

**במקרה של סיום לא רגיל (לדוגמה, קריסה של תהליך):**
-   זיכרון משותף וסמפורים בעלי שם נשארים במערכת הקבצים הוירטואלית גם לאחר סיום תהליך שפתח אותם, עד שהם משוחררים במפורש על ידי `shm_unlink` ו-`sem_unlink` או עד אתחול המערכת. זוהי יתרון וחיסרון כאחד: יתרון כי מאפשר לתהליכים אחרים להמשיך להשתמש בהם גם אם תהליך אחד קורס. חיסרון כי דורש טיפול מפורש בניקוי.
-   כדי להתמודד עם סיום לא רגיל, נהוג להשתמש במנגנונים כגון `atexit()` לרשום פונקציות ניקוי שיקראו אוטומטית ביציאה רגילה. עבור סיום לא רגיל (לדוגמה, קריסה כתוצאה מ-Segmentation Fault), פונקציות אלו לא יקראו. במקרים אלו, נהוג לכתוב סקריפט או תהליך "שומר" (watcher process) שיזהה קריסות ויבצע את הניקוי הנדרש, או להסתמך על תהליך אתחול שידאג לנקות משאבים "יתומים" (orphaned resources) בפתיחת המערכת.

