### 1.1 הסבר מנגנוני IPC

לפתרון בעיית המפיק-צרכן עם חוצץ משותף נדרשים שני מנגנוני IPC עיקריים:

*   **זיכרון משותף (Shared Memory):**
    *   **מטרה:** לאחסן את החוצץ המעגלי עצמו (מערך `buffer`), יחד עם משתני האינדקסים `in` ו-`out` המצביעים על המקום הבא להכנסה והמקום הבא להוצאה בהתאמה. אלו הם הנתונים המשותפים שכל התהליכים (מפיקים וצרכנים) צריכים לגשת אליהם.
    *   **אופן בנייה ושימוש:** הזיכרון המשותף ייווצר על ידי תהליך האב (או תהליך ייעודי לאתחול) באמצעות `shm_open` ו-`ftruncate`, ולאחר מכן ימופה למרחב הכתובות של התהליכים המעורבים באמצעות `mmap`. כל תהליך בן (מפיק או צרכן) יירש את מפת הזיכרון הזו או ימפה אותה מחדש. גישה לנתונים בזיכרון המשותף מתבצעת ישירות דרך מצביע.

*   **סמפורים (Semaphores):**
    *   **מטרה:** לסנכרן את הגישה לזיכרון המשותף ולנהל את המשאבים (מקומות ריקים/מלאים בחוצץ), ובכך למנוע תנאי מרוץ, גלישת חוצץ ותת-גלישת חוצץ.
    *   **אופן השימוש:** נדרשים שלושה סמפורים מסוג POSIX named semaphores:
        1.  `mutex` (סמפור בינארי):
            *   **מייצג:** מנעול הדרה הדדית (mutual exclusion lock) לגישה לחוצץ המשותף. מטרתו להבטיח שרק תהליך אחד יבצע פעולות קריאה/כתיבה על החuצץ בזמן נתון.
            *   **ערך התחלתי:** 1 (החוצץ פנוי לגישה).
            *   **שימוש:** לפני כניסה לקטע הקריטי (גישה לחוצץ), תהליך מבצע `sem_wait(mutex)`. לאחר היציאה מהקטע הקריטי, הוא מבצע `sem_post(mutex)`.
        2.  `empty` (סמפור סופר / counting semaphore):
            *   **מייצג:** את מספר המקומות הריקים הזמינים בחוצץ.
            *   **ערך התחלתי:** `BUFFER_SIZE` (בהתחלה כל המקומות ריקים).
            *   **שימוש:** מפיק מבצע `sem_wait(empty)` לפני הכנסת פריט (ממתין למקום ריק). אם אין מקומות ריקים, המפיק נחסם. צרכן מבצע `sem_post(empty)` לאחר הוצאת פריט (משחרר מקום ריק ומאותת למפיקים).
        3.  `full` (סמפור סופר / counting semaphore):
            *   **מייצג:** את מספר המקומות המלאים (פריטים זמינים) בחוצץ.
            *   **ערך התחלתי:** 0 (בהתחלה אין פריטים בחוצץ).
            *   **שימוש:** צרכן מבצע `sem_wait(full)` לפני הוצאת פריט (ממתין לפריט זמין). אם אין פריטים, הצרכן נחסם. מפיק מבצע `sem_post(full)` לאחר הכנסת פריט (מודיע על פריט חדש ומאותת לצרכנים).

### 1.2 קוד C/C++

להלן קוד C/C++ מלא המדגים את המבנה של מערכת מפיק-צרכן באמצעות זיכרון משותף וסמפורים בעלי שם (POSIX named semaphores). הקוד כולל יצירת תהליכים באמצעות `fork`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <semaphore.h>
#include <stdbool.h>
#include <time.h>

#define BUFFER_SIZE 5 // גודל החוצץ - הוקטן לדוגמה קצרה יותר
#define NUM_PRODUCERS 2
#define NUM_CONSUMERS 2
#define NUM_ITEMS_PER_PRODUCER 3 // כל מפיק מייצר 3 פריטים

// מבנה לזיכרון המשותף
typedef struct {
    int buffer[BUFFER_SIZE];
    int in;  // אינדקס להכנסה
    int out; // אינדקס להוצאה
} shared_data_t;

// שמות לסמפורים ולזיכרון המשותף
#define SEM_MUTEX_NAME "/my_mutex_sem"
#define SEM_FULL_NAME "/my_full_sem"
#define SEM_EMPTY_NAME "/my_empty_sem"
#define SHM_NAME "/my_shm"

// מצביעים לסמפורים ולזיכרון המשותף (גלובליים כדי שיהיו נגישים לתהליכים הבנים)
sem_t *mutex; 
sem_t *full;  
sem_t *empty; 
shared_data_t *shared_mem_ptr; 
int shm_fd; 

void producer(int id) {
    int item;
    srand(time(NULL) ^ getpid()); // אתחול מחולל מספרים אקראיים ייחודי לכל תהליך

    for (int i = 0; i < NUM_ITEMS_PER_PRODUCER; ++i) {
        item = (id * 100) + i; // פריט ייחודי למפיק

        sem_wait(empty); // המתן למקום ריק
        sem_wait(mutex); // קבל נעילה לגישה לחוצץ

        // קטע קריטי: הכנס פריט לחוצץ
        shared_mem_ptr->buffer[shared_mem_ptr->in] = item;
        shared_mem_ptr->in = (shared_mem_ptr->in + 1) % BUFFER_SIZE;
        printf("Producer %d produced item %d. Buffer state: in=%d, out=%d\n", id, item, shared_mem_ptr->in, shared_mem_ptr->out);
        fflush(stdout); // וודא שהפלט נכתב מיד

        sem_post(mutex); // שחרר נעילה
        sem_post(full);  // אותת שיש מקום מלא נוסף

        usleep(rand() % 100000); // הדמיית עבודה
    }
    printf("Producer %d finished producing %d items.\n", id, NUM_ITEMS_PER_PRODUCER);
}

void consumer(int id) {
    int item;
    srand(time(NULL) ^ getpid()); // אתחול מחולל מספרים אקראיים ייחודי לכל תהליך
    int total_items_to_consume = (NUM_ITEMS_PER_PRODUCER * NUM_PRODUCERS) / NUM_CONSUMERS;

    for (int i = 0; i < total_items_to_consume; ++i) {
        sem_wait(full);  // המתן לפריט זמין
        sem_wait(mutex); // קבל נעילה לגישה לחוצץ

        // קטע קריטי: הוצא פריט מהחוצץ
        item = shared_mem_ptr->buffer[shared_mem_ptr->out];
        shared_mem_ptr->out = (shared_mem_ptr->out + 1) % BUFFER_SIZE;
        printf("Consumer %d consumed item %d. Buffer state: in=%d, out=%d\n", id, item, shared_mem_ptr->in, shared_mem_ptr->out);
        fflush(stdout);

        sem_post(mutex); // שחרר נעילה
        sem_post(empty); // אותת שיש מקום ריק נוסף

        usleep(rand() % 150000); // הדמיית עבודה
    }
    printf("Consumer %d finished consuming %d items.\n", id, total_items_to_consume);
}

int main() {
    printf("Starting Producer-Consumer system...\n");

    // 1. יצירה ופתיחת זיכרון משותף
    shm_fd = shm_open(SHM_NAME, O_CREAT | O_EXCL | O_RDWR, 0666); // O_EXCL מבטיח יצירה חדשה
    if (shm_fd == -1) {
        perror("shm_open");
        // אם הקובץ קיים, ננסה לפתוח אותו בלעדי O_EXCL ולנקות משאבים קודמים
        shm_fd = shm_open(SHM_NAME, O_RDWR, 0666);
        if (shm_fd == -1) {
            perror("shm_open (retry)");
            exit(EXIT_FAILURE);
        }
        fprintf(stderr, "Warning: Shared memory '%s' already existed. Attempting to unlink previous resources.\n", SHM_NAME);
        shm_unlink(SHM_NAME); // ניקוי יזום
        shm_fd = shm_open(SHM_NAME, O_CREAT | O_EXCL | O_RDWR, 0666); // ניסיון יצירה חוזר
        if (shm_fd == -1) {
            perror("shm_open (final retry)");
            exit(EXIT_FAILURE);
        }
    }
    if (ftruncate(shm_fd, sizeof(shared_data_t)) == -1) {
        perror("ftruncate");
        exit(EXIT_FAILURE);
    }
    shared_mem_ptr = (shared_data_t *)mmap(NULL, sizeof(shared_data_t), PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shared_mem_ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    // אתחול הזיכרון המשותף
    shared_mem_ptr->in = 0;
    shared_mem_ptr->out = 0;
    printf("Shared memory '%s' created and initialized.\n", SHM_NAME);

    // 2. יצירה ואתחול סמפורים
    // ניקוי סמפורים קודמים במידה וקיימים
    sem_unlink(SEM_MUTEX_NAME);
    sem_unlink(SEM_FULL_NAME);
    sem_unlink(SEM_EMPTY_NAME);

    mutex = sem_open(SEM_MUTEX_NAME, O_CREAT | O_EXCL, 0666, 1); 
    full = sem_open(SEM_FULL_NAME, O_CREAT | O_EXCL, 0666, 0); 
    empty = sem_open(SEM_EMPTY_NAME, O_CREAT | O_EXCL, 0666, BUFFER_SIZE); 
    if (mutex == SEM_FAILED || full == SEM_FAILED || empty == SEM_FAILED) {
        perror("sem_open");
        exit(EXIT_FAILURE);
    }
    printf("Semaphores '%s', '%s', '%s' created and initialized.\n", SEM_MUTEX_NAME, SEM_FULL_NAME, SEM_EMPTY_NAME);

    // 3. יצירת תהליכי מפיקים
    pid_t pid;
    for (int i = 0; i < NUM_PRODUCERS; ++i) {
        pid = fork();
        if (pid == 0) { // תהליך בן (מפיק)
            producer(i + 1);
            exit(EXIT_SUCCESS);
        } else if (pid < 0) {
            perror("fork producer");
            exit(EXIT_FAILURE);
        }
    }

    // 4. יצירת תהליכי צרכנים
    for (int i = 0; i < NUM_CONSUMERS; ++i) {
        pid = fork();
        if (pid == 0) { // תהליך בן (צרכן)
            consumer(i + 1);
            exit(EXIT_SUCCESS);
        } else if (pid < 0) {
            perror("fork consumer");
            exit(EXIT_FAILURE);
        }
    }

    // 5. המתנה לסיום כל התהליכים
    for (int i = 0; i < NUM_PRODUCERS + NUM_CONSUMERS; ++i) {
        wait(NULL);
    }
    printf("All producers and consumers finished.\n");

    // 6. ניקוי משאבים
    if (munmap(shared_mem_ptr, sizeof(shared_data_t)) == -1) {
        perror("munmap");
    }
    if (shm_unlink(SHM_NAME) == -1) {
        perror("shm_unlink");
    }
    if (sem_close(mutex) == -1 || sem_close(full) == -1 || sem_close(empty) == -1) {
        perror("sem_close");
    }
    if (sem_unlink(SEM_MUTEX_NAME) == -1) {
        perror("sem_unlink mutex");
    }
    if (sem_unlink(SEM_FULL_NAME) == -1) {
        perror("sem_unlink full");
    }
    if (sem_unlink(SEM_EMPTY_NAME) == -1) {
        perror("sem_unlink empty");
    }
    printf("IPC resources cleaned up.\n");

    return 0;
}
```

### 1.3 ניתוח תקלות

יישום שגוי של סמפורים עלול להוביל לבעיות חמורות במערכות מקביליות, כגון קיפאון (Deadlock) או הרעבה (Starvation).

*   **קיפאון (Deadlock):**
    *   **הגדרה:** מצב שבו שני תהליכים או יותר ממתינים זה לזה למשאב שתפוס על ידי האחר, וכתוצאה מכך אף אחד מהם לא יכול להמשיך בביצוע. בבעיית המפיק-צרכן, קיפאון יכול להתרחש אם סדר פעולות ה-`sem_wait` וה-`sem_post` אינו נכון.
    *   **תרחיש לדוגמה (מפיק):** נניח שמפיק מבצע את הפעולות בסדר הבא:
        1.  `sem_wait(mutex)` (תופס את המנעול לחוצץ)
        2.  `sem_wait(empty)` (ממתין למקום ריק)
        אם החוצץ מלא, המפיק יחסם ב-`sem_wait(empty)`. כיוון שהמפיק מחזיק כעת את ה-`mutex`, אף צרכן לא יוכל לגשת לחוצץ כדי להוציא פריטים ולשחרר מקום (פעולת `sem_post(empty)`). כתוצאה מכך, המפיק נשאר חסום באופן קבוע, וכל הצרכנים שירצו לגשת לחוצץ יחסמו גם הם בניסיון לתפוס את ה-`mutex`. זוהי סיטואציה קלאסית של קיפאון.
    *   **תרחיש לדוגמה (צרכן):** באופן דומה, אם צרכן מבצע את הפעולות בסדר הבא:
        1.  `sem_wait(mutex)` (תופס את המנעול לחוצץ)
        2.  `sem_wait(full)` (ממתין לפריט זמין)
        אם החוצץ ריק, הצרכן יחסם ב-`sem_wait(full)`. כיוון שהצרכן מחזיק כעת את ה-`mutex`, אף מפיק לא יוכל לגשת לחוצץ כדי להכניס פריטים ולשחרר את הצרכן (פעולת `sem_post(full)`). הצרכן נשאר חסום באופן קבוע, וכל המפיקים יחסמו בניסיון לתפוס את ה-`mutex`. גם זו סיטואציה של קיפאון.

*   **הרעבה (Starvation):**
    *   **הגדרה:** מצב שבו תהליך מסוים נמנע באופן בלתי מוגבל מלקבל גישה למשאב או מביצוע פעולה, למרות שהמשאב זמין עבור תהליכים אחרים. הרעבה שונה מקיפאון בכך שהמערכת כולה ממשיכה לפעול, אך תהליך ספציפי אינו מתקדם.
    *   **תרחיש לדוגמה:** אם מנגנון התזמון של מערכת ההפעלה או יישום הסמפורים אינו הוגן (לא מבטיח סדר הגעה או עדיפות), ייתכן שתהליכים מסוימים יקבלו עדיפות באופן קבוע על פני אחרים. לדוגמה, אם יש קבוצה גדולה של מפיקים מהירים מאוד וקבוצה קטנה של צרכנים איטיים, ייתכן שמפיק מסוים תמיד יצליח לתפוס את ה-`mutex` או את מקום ה-`empty` לפני שמפיק אחר (פחות "בר מזל" או בעל עדיפות נמוכה יותר) יצליח לעשות זאת. כתוצאה מכך, מפיק אחד יכול להיתקע בהמתנה אינסופית לגישה לחוצץ, גם אם החוצץ אינו מלא באופן קבוע, פשוט כי תמיד יש מפיק אחר שזוכה בגישה לפניו. באופן דומה, צרכן יכול להיתקל בהרעבה אם יש תמיד צרכנים אחרים שזוכים להוציא פריטים לפניו. הרעבה פחות סבירה ביישומי POSIX semaphores הסטנדרטיים, הנוטים להיות הוגנים, אך היא עדיין סיכון תיאורטי ביישומים מורכבים יותר או עם תזמון לא אופטימלי.

פתרון מלא:

**1.1 עיצוב המערכת:**
*   **זיכרון משותף (Shared Memory):** ישמש לאחסון חוצץ מעגלי של משימות. מבנה הנתונים בזיכרון המשותף יכלול: 
    ```c
    #define BUFFER_SIZE 10 // גודל החוצץ
    struct Task {
        int id;           // מזהה ייחודי למשימה
        int input_value;  // ערך הקלט למשימה
    };

    struct SharedData {
        struct Task tasks[BUFFER_SIZE]; // מערך המשימות (החוצץ המעגלי)
        int head;                       // אינדקס לכתיבת משימה חדשה ע"י ה-master
        int tail;                       // אינדקס לקריאת משימה ע"י ה-workers
    };
    ```
*   **סמפורים (Semaphores):** ישמשו לסנכרון הגישה לזיכרון המשותף ולניהול מצב המלאי בחוצץ:
    *   `mutex`: סמפור בינארי, מאותחל ל-1. מגן על הגישה הקריטית למבנה `SharedData` (קריאה/כתיבה ל-`tasks`, עדכון `head` ו-`tail`).
    *   `empty`: סמפור מונה, מאותחל ל-`BUFFER_SIZE`. סופר את מספר המקומות הפנויים בחוצץ המשימות. ה-master מבצע `sem_wait` עליו לפני הכנסת משימה, וה-worker מבצע `sem_post` עליו לאחר לקיחת משימה.
    *   `full`: סמפור מונה, מאותחל ל-0. סופר את מספר המקומות התפוסים (משימות זמינות) בחוצץ המשימות. ה-worker מבצע `sem_wait` עליו לפני לקיחת משימה, וה-master מבצע `sem_post` עליו לאחר הכנסת משימה.
*   **תור הודעות (Message Queue):** ישמש להחזרת התוצאות מה-workers ל-master. כל worker ישלח הודעה לתור המכילה את מזהה המשימה ואת התוצאה. מבנה ההודעה:
    ```c
    struct Result {
        int task_id;      // מזהה המשימה אליה מתייחסת התוצאה
        int output_value; // תוצאת החישוב
    };

    struct MsgBuf {         // מבנה ההודעה לתור
        long mtype;         // סוג ההודעה (לדוגמה, 1)
        struct Result result; // מבנה התוצאה
    };
    ```
*   **זיהוי משימות ותוצאות:** ה-master יקצה `id` ייחודי לכל משימה. ה-worker יכלול את ה-`task_id` במבנה ה-`Result` שהוא שולח בתור ההודעות, ובכך ה-master יוכל לשייך כל תוצאה למשימה המקורית שלה.

**1.2 קוד תהליך ה-Master (הכנסת משימות):**
```c
// הגדרות ואיניציאליזציה (לדוגמה, shm_ptr, semaphores, msgid)
// ...

for (int i = 0; i < total_tasks; ++i) {
    struct Task newTask = { .id = i, .input_value = rand() % 100 };

    sem_wait(empty); // המתן למקום פנוי בחוצץ
    sem_wait(mutex); // כניסה לאזור קריטי - גישה לזיכרון המשותף

    shm_ptr->tasks[shm_ptr->head] = newTask;
    shm_ptr->head = (shm_ptr->head + 1) % BUFFER_SIZE;

    sem_post(mutex); // יציאה מהאזור הקריטי
    sem_post(full);  // סמן כי יש משימה חדשה בחוצץ

    printf("Master: Added task %d with input %d\n", newTask.id, newTask.input_value);
}

// לאחר שליחת כל המשימות, ה-master ימשיך לאסוף תוצאות מתור ההודעות
```

**1.3 קוד תהליך ה-Worker (לקיחת משימה והחזרת תוצאה):**
```c
// הגדרות ואיניציאליזציה (לדוגמה, shm_ptr, semaphores, msgid)
// ...

while (1) { // לולאת עבודה אינסופית עד לקבלת אות סיום
    sem_wait(full);  // המתן למשימה זמינה בחוצץ
    sem_wait(mutex); // כניסה לאזור קריטי - גישה לזיכרון המשותף

    struct Task taskToProcess = shm_ptr->tasks[shm_ptr->tail];
    shm_ptr->tail = (shm_ptr->tail + 1) % BUFFER_SIZE;

    sem_post(mutex); // יציאה מהאזור הקריטי
    sem_post(empty); // סמן כי מקום התפנה בחוצץ

    // אם קיימת משימת סיום מיוחדת (לדוגמה, taskToProcess.id == -1), יש לצאת מהלולאה
    // if (taskToProcess.id == TERMINATION_TASK_ID) break;

    printf("Worker %d: Processing task %d (input %d)\n", getpid(), taskToProcess.id, taskToProcess.input_value);

    // ביצוע העבודה בפועל (לדוגמה, העלאה בריבוע)
    sleep(1); // הדמיית עבודה
    int output = taskToProcess.input_value * taskToProcess.input_value;

    // הכנת התוצאה ושליחתה בתור ההודעות
    struct Result result = { .task_id = taskToProcess.id, .output_value = output };
    struct MsgBuf msg = { .mtype = 1, .result = result }; 

    if (msgsnd(msgid, &msg, sizeof(struct Result), 0) == -1) {
        perror("msgsnd");
        // טיפול בשגיאה: ייתכן שיש לנסות לשלוח שוב או לדווח ל-master
    }
    printf("Worker %d: Sent result for task %d (output %d)\n", getpid(), result.task_id, result.output_value);
}

exit(0); // יציאה מסודרת של ה-worker
```

**1.4 סיום וניקוי:**
*   **סיום עבודה מסודר (Graceful Shutdown):**
    1.  **סיום המשימות:** ה-master מייצר ושולח את כל `total_tasks` המשימות לחוצץ המשותף.
    2.  **איסוף תוצאות:** ה-master ממתין ומקבל `total_tasks` תוצאות מתור ההודעות. הוא יכול לשמור מונה של תוצאות שהתקבלו. 
    3.  **איתות סיום ל-workers:** לאחר שה-master אסף את כל התוצאות, הוא צריך לאותת ל-workers לסיים את עבודתם. דרך נפוצה היא לשלוח מספר משימות "מיוחדות" (לדוגמה, עם `task_id = -1`) לחוצץ המשותף, כמספר ה-workers הפעילים. כל worker, כאשר הוא מקבל משימת סיום זו, יוצא מלולאת העבודה שלו ומסיים את התהליך.
    4.  **המתנה ל-workers:** ה-master מבצע `waitpid()` עבור כל תהליכי ה-worker כדי לוודא שכולם סיימו ונאספו משאביהם.
*   **ניקוי משאבי IPC:** ה-master הוא האחראי לניקוי כל המשאבים:
    *   **זיכרון משותף:** `shm_unlink()` עבור הזיכרון המשותף (אם משתמשים ב-POSIX shared memory) או `shmctl(shmid, IPC_RMID, NULL)` (אם System V shared memory). פעולה זו מנתקת את הזיכרון ומסמנת אותו למחיקה לאחר שכל התהליכים ניתקו ממנו.
    *   **סמפורים:** `sem_unlink()` עבור כל סמפור (אם משתמשים ב-POSIX named semaphores) או `semctl(semid, 0, IPC_RMID)` (אם System V semaphores). פעולה זו משחררת את הסמפורים מהמערכת.
    *   **תור הודעות:** `msgctl(msgid, IPC_RMID, NULL)` עבור תור ההודעות. פעולה זו מסירה את התור מהמערכת.
*   **השלכות קריסת Worker:**
    *   **אובדן משימה:** אם worker קורס לאחר שלקח משימה מהחוצץ אך לפני ששלח תוצאה, המשימה עלולה ללכת לאיבוד (ה-master לא יקבל תוצאה עבורה) וה-`empty` סמפור לא יעודכן. 
    *   **נעילת סמפורים:** אם ה-worker קורס כשהוא מחזיק ב-`mutex` סמפור, המערכת תיכנס למצב של Deadlock, מכיוון שאף תהליך אחר לא יוכל להיכנס לאזור הקריטי. סמפורי POSIX named semaphores פחות רגישים לבעיה זו מאשר סמפורים לא-שמיים או System V ללא דגל `SEM_UNDO`.
    *   **זיהוי כשל:** ה-master יבחין בכשל בכך שלא יקבל את כל `total_tasks` התוצאות המצופות, או אם `waitpid()` ידווח על יציאה בלתי צפויה של worker. מערכות חזקות יותר כוללות מנגנוני Heartbeat או Timeout כדי לזהות workers שאינם מגיבים ולטפל במשימות שאבדו (לדוגמה, ע"י הקצאתן מחדש ל-worker אחר).

### 1.1 מבנה הזיכרון המשותף:
מבנה הנתונים בזיכרון המשותף צריך לכלול את החוצץ המעגלי עצמו, אינדקסים לראש ולזנב החוצץ, וכן סמפורים לסנכרון. נגדיר את המבנה הבא:

```c
#define MAX_LOG_MESSAGES 100
#define LOG_MESSAGE_SIZE 256
#define SHM_NAME "/log_shm"
#define SEM_MUTEX_NAME "/log_mutex"
#define SEM_EMPTY_NAME "/log_empty"
#define SEM_FULL_NAME "/log_full"

typedef struct {
    char buffer[MAX_LOG_MESSAGES][LOG_MESSAGE_SIZE]; // החוצץ המעגלי עצמו
    int head; // אינדקס הכתיבה הבא (producer)
    int tail; // אינדקס הקריאה הבא (consumer)
    // סמפורים לא יאוחסנו ישירות בזיכרון משותף ב-POSIX semaphores, אלא ינוהלו כשמותיים.
    // עם זאת, אם היינו משתמשים ב-System V semaphores או ב-POSIX unnamed semaphores בתוך ה-shm, היינו צריכים להוסיף אותם כאן.
    // לצורך שאלה זו, נתייחס לכך שהשמות של הסמפורים מאוחסנים ונגישים לכל התהליכים.
} shm_data_t;
```

**הסבר הרכיבים:**
*   `buffer[MAX_LOG_MESSAGES][LOG_MESSAGE_SIZE]`: זהו החוצץ המעגלי עצמו. הוא מכיל `MAX_LOG_MESSAGES` (100) הודעות, כאשר כל הודעה בגודל `LOG_MESSAGE_SIZE` (256 בתים). גודלו הכולל יהיה `100 * 256 = 25600` בתים.
*   `head`: אינדקס המצביע על המיקום הבא בחוצץ שבו יוכנס לוג על ידי producer. הוא מתקדם מ-0 עד `MAX_LOG_MESSAGES - 1` וחוזר ל-0 (פעולה מודולו).
*   `tail`: אינדקס המצביע על המיקום הבא בחוצץ שממנו יילקח לוג על ידי consumer. הוא מתקדם מ-0 עד `MAX_LOG_MESSAGES - 1` וחוזר ל-0 (פעולה מודולו).

**לגבי סמפורים:**
סמפורי POSIX בעלי שמות (named semaphores) אינם מאוחסנים ישירות בתוך הזיכרון המשותף, אלא נפתחים ונסגרים באמצעות שמות גלובליים. לכן, אין צורך לכלול אותם במבנה ה-`shm_data_t`. שלושת הסמפורים הנדרשים הם:
*   `mutex`: סמפור בינארי (ערך התחלתי 1) המשמש להגנה על הקטע הקריטי בעת גישה לחוצץ (עדכון `head`, `tail`, וכתיבה/קריאה בפועל). הוא מבטיח שרק תהליך אחד יגש לחוצץ בו-זמנית.
*   `empty`: סמפור סופר (ערך התחלתי `MAX_LOG_MESSAGES`) המציין את מספר המקומות הריקים בחוצץ. producer מבצע `sem_wait` עליו לפני כתיבה, ו-consumer מבצע `sem_post` עליו לאחר קריאה.
*   `full`: סמפור סופר (ערך התחלתי 0) המציין את מספר המקומות המלאים בחוצץ. consumer מבצע `sem_wait` עליו לפני קריאה, ו-producer מבצע `sem_post` עליו לאחר כתיבה.

### 1.2 אתחול וסנכרון:
תהליך ה-consumer (שירות הלוגים) יהיה אחראי ליצור ולאתחל את הזיכרון המשותף ואת הסמפורים. תהליכי ה-producer יפתחו אותם בהמשך.

```c
#include <fcntl.h>      // For O_CREAT, O_EXCL, etc.
#include <sys/stat.h>   // For mode constants
#include <sys/mman.h>   // For shm_open, mmap, munmap, shm_unlink
#include <semaphore.h>  // For sem_open, sem_close, sem_unlink
#include <unistd.h>     // For ftruncate
#include <stdio.h>      // For perror
#include <stdlib.h>     // For exit
#include <string.h>     // For memset

// (הגדרות MAX_LOG_MESSAGES, LOG_MESSAGE_SIZE, SHM_NAME, SEM_MUTEX_NAME, SEM_EMPTY_NAME, SEM_FULL_NAME מ-1.1)

typedef struct {
    char buffer[MAX_LOG_MESSAGES][LOG_MESSAGE_SIZE];
    int head;
    int tail;
} shm_data_t;

void initialize_ipc_resources() {
    int shm_fd;
    shm_data_t *shm_ptr;
    sem_t *mutex_sem, *empty_sem, *full_sem;
    size_t shm_size = sizeof(shm_data_t);

    // 1. יצירה ואתחול של זיכרון משותף
    shm_fd = shm_open(SHM_NAME, O_CREAT | O_EXCL | O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("shm_open failed");
        exit(EXIT_FAILURE);
    }

    if (ftruncate(shm_fd, shm_size) == -1) {
        perror("ftruncate failed");
        shm_unlink(SHM_NAME); // Clean up on failure
        exit(EXIT_FAILURE);
    }

    shm_ptr = (shm_data_t *)mmap(NULL, shm_size, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_ptr == MAP_FAILED) {
        perror("mmap failed");
        shm_unlink(SHM_NAME); // Clean up on failure
        exit(EXIT_FAILURE);
    }

    // אתחול נתוני הזיכרון המשותף
    memset(shm_ptr, 0, shm_size);
    shm_ptr->head = 0;
    shm_ptr->tail = 0;
    printf("Shared memory initialized. Size: %lu bytes\n", shm_size);

    // 2. יצירה ואתחול של סמפורים
    // Semaphores are created with O_CREAT and O_EXCL to ensure only one process initializes them.
    // Permissions 0666 for read/write by owner, group, others.

    mutex_sem = sem_open(SEM_MUTEX_NAME, O_CREAT | O_EXCL, 0666, 1);
    if (mutex_sem == SEM_FAILED) {
        perror("sem_open mutex failed");
        // Clean up shm as well
        munmap(shm_ptr, shm_size);
        shm_unlink(SHM_NAME);
        exit(EXIT_FAILURE);
    }
    printf("Mutex semaphore initialized with value 1.\n");

    empty_sem = sem_open(SEM_EMPTY_NAME, O_CREAT | O_EXCL, 0666, MAX_LOG_MESSAGES);
    if (empty_sem == SEM_FAILED) {
        perror("sem_open empty failed");
        // Clean up shm and mutex
        sem_close(mutex_sem); sem_unlink(SEM_MUTEX_NAME);
        munmap(shm_ptr, shm_size);
        shm_unlink(SHM_NAME);
        exit(EXIT_FAILURE);
    }
    printf("Empty semaphore initialized with value %d.\n", MAX_LOG_MESSAGES);

    full_sem = sem_open(SEM_FULL_NAME, O_CREAT | O_EXCL, 0666, 0);
    if (full_sem == SEM_FAILED) {
        perror("sem_open full failed");
        // Clean up shm, mutex, empty
        sem_close(mutex_sem); sem_unlink(SEM_MUTEX_NAME);
        sem_close(empty_sem); sem_unlink(SEM_EMPTY_NAME);
        munmap(shm_ptr, shm_size);
        shm_unlink(SHM_NAME);
        exit(EXIT_FAILURE);
    }
    printf("Full semaphore initialized with value 0.\n");

    // אין צורך לסגור או לבטל את הקישור לסמפורים כאן, מכיוון שהם יישארו פתוחים לשימוש התהליכים.
    // הם ייסגרו ויבוטלו בקישור בסיום התוכנית או אם מתרחשת שגיאה קריטית.
    // אבל חשוב לסגור את ה-shm_fd כי ה-mmap כבר מיפה אותו לזיכרון התהליך.
    close(shm_fd);

    printf("IPC resources successfully initialized.\n");
}
```

**הסבר:**
1.  **זיכרון משותף:**
    *   `shm_open`: יוצר אובייקט זיכרון משותף בשם `SHM_NAME`. `O_CREAT` יוצר אם לא קיים, `O_EXCL` מבטיח שהתהליך הוא היוצר היחיד (אם קיים, `shm_open` ייכשל), `O_RDWR` מאפשר קריאה וכתיבה, ו-`0666` נותן הרשאות קריאה וכתיבה לכולם.
    *   `ftruncate`: מגדיר את גודל אובייקט הזיכרון המשותף לגודל המבנה `shm_data_t`.
    *   `mmap`: ממפה את אובייקט הזיכרון המשותף למרחב הכתובות של התהליך. `MAP_SHARED` מבטיח שהשינויים יהיו גלויים לתהליכים אחרים הממפים את אותו אובייקט.
    *   `memset`: מאתחל את כל הזיכרון המשותף לאפס. `head` ו-`tail` מאותחלים ל-0, מה שמצביע על חוצץ ריק.
2.  **סמפורים:**
    *   `sem_open`: יוצר סמפור בעל שם. `O_CREAT | O_EXCL` מבטיח גם כאן יצירה חד-פעמית. ההרשאות `0666` מאפשרות גישה לכל התהליכים.
    *   **mutex_sem**: מאותחל ל-1, מכיוון שהוא סמפור בינארי המגן על קטע קריטי יחיד.
    *   **empty_sem**: מאותחל ל-`MAX_LOG_MESSAGES` (100), מכיוון שבתחילה החuצץ ריק לחלוטין ויש 100 מקומות פנויים.
    *   **full_sem**: מאותחל ל-0, מכיוון שבתחילה החוצץ ריק לחלוטין ואין בו הודעות לוג.

### 1.3 קוד Producer ו-Consumer:

**פונקציית Producer:**
```c
// (הגדרות ו-typedef מ-1.1)

void produce_log_message(const char* message) {
    int shm_fd;
    shm_data_t *shm_ptr;
    sem_t *mutex_sem, *empty_sem, *full_sem;
    size_t shm_size = sizeof(shm_data_t);

    // פתיחת זיכרון משותף (רק פתיחה, לא יצירה)
    shm_fd = shm_open(SHM_NAME, O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("Producer: shm_open failed");
        return;
    }
    shm_ptr = (shm_data_t *)mmap(NULL, shm_size, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_ptr == MAP_FAILED) {
        perror("Producer: mmap failed");
        close(shm_fd);
        return;
    }
    close(shm_fd); // סגירת ה-fd לאחר המיפוי

    // פתיחת סמפורים קיימים
    mutex_sem = sem_open(SEM_MUTEX_NAME, 0); // 0 means don't create
    if (mutex_sem == SEM_FAILED) { perror("Producer: sem_open mutex failed"); munmap(shm_ptr, shm_size); return; }
    empty_sem = sem_open(SEM_EMPTY_NAME, 0);
    if (empty_sem == SEM_FAILED) { perror("Producer: sem_open empty failed"); sem_close(mutex_sem); munmap(shm_ptr, shm_size); return; }
    full_sem = sem_open(SEM_FULL_NAME, 0);
    if (full_sem == SEM_FAILED) { perror("Producer: sem_open full failed"); sem_close(mutex_sem); sem_close(empty_sem); munmap(shm_ptr, shm_size); return; }

    // 1. המתן למקום פנוי (empty)
    sem_wait(empty_sem);

    // 2. המתן לנעילת הקטע הקריטי (mutex)
    sem_wait(mutex_sem);

    // קטע קריטי: כתיבה לחוצץ המשותף
    strncpy(shm_ptr->buffer[shm_ptr->head], message, LOG_MESSAGE_SIZE - 1);
    shm_ptr->buffer[shm_ptr->head][LOG_MESSAGE_SIZE - 1] = '\0'; // ודא סיום null
    shm_ptr->head = (shm_ptr->head + 1) % MAX_LOG_MESSAGES;
    printf("Producer produced: %s\n", message);

    // 3. שחרור נעילת הקטע הקריטי (mutex)
    sem_post(mutex_sem);

    // 4. אותת שיש מקום מלא (full)
    sem_post(full_sem);

    // סגירת סמפורים וזיכרון משותף בסיום השימוש (או בסיום התהליך)
    sem_close(mutex_sem);
    sem_close(empty_sem);
    sem_close(full_sem);
    munmap(shm_ptr, shm_size);
}
```

**הסבר Producer:**
*   **`sem_wait(empty_sem)`**: Producer ממתין כאן אם אין מקום פנוי בחוצץ (כלומר, `empty_sem` הוא 0). כאשר יש מקום, הוא מפחית את `empty_sem` באחד.
*   **`sem_wait(mutex_sem)`**: Producer ממתין כאן כדי לקבל גישה בלעדית לקטע הקריטי (החוצץ). הוא מפחית את `mutex_sem` באחד (ל-0), ובכך מונע מ-producer או consumer אחרים לגשת לחוצץ.
*   **כתיבה לחוצץ**: ההודעה מועתקת למיקום `head` בחוצץ. `head` מתקדם באופן מעגלי.
*   **`sem_post(mutex_sem)`**: Producer משחרר את הנעילה על הקטע הקריטי, ומגדיל את `mutex_sem` בחזרה ל-1.
*   **`sem_post(full_sem)`**: Producer מאותת ל-consumer שיש כעת הודעה נוספת בחוצץ, ומגדיל את `full_sem` באחד.

**פונקציית Consumer:**
```c
// (הגדרות ו-typedef מ-1.1)

void consume_log_message(char* message_buffer) {
    int shm_fd;
    shm_data_t *shm_ptr;
    sem_t *mutex_sem, *empty_sem, *full_sem;
    size_t shm_size = sizeof(shm_data_t);

    // פתיחת זיכרון משותף (רק פתיחה)
    shm_fd = shm_open(SHM_NAME, O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("Consumer: shm_open failed");
        return;
    }
    shm_ptr = (shm_data_t *)mmap(NULL, shm_size, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_ptr == MAP_FAILED) {
        perror("Consumer: mmap failed");
        close(shm_fd);
        return;
    }
    close(shm_fd); // סגירת ה-fd לאחר המיפוי

    // פתיחת סמפורים קיימים
    mutex_sem = sem_open(SEM_MUTEX_NAME, 0);
    if (mutex_sem == SEM_FAILED) { perror("Consumer: sem_open mutex failed"); munmap(shm_ptr, shm_size); return; }
    empty_sem = sem_open(SEM_EMPTY_NAME, 0);
    if (empty_sem == SEM_FAILED) { perror("Consumer: sem_open empty failed"); sem_close(mutex_sem); munmap(shm_ptr, shm_size); return; }
    full_sem = sem_open(SEM_FULL_NAME, 0);
    if (full_sem == SEM_FAILED) { perror("Consumer: sem_open full failed"); sem_close(mutex_sem); sem_close(empty_sem); munmap(shm_ptr, shm_size); return; }

    // 1. המתן למקום מלא (full)
    sem_wait(full_sem);

    // 2. המתן לנעילת הקטע הקריטי (mutex)
    sem_wait(mutex_sem);

    // קטע קריטי: קריאה מהחוצץ המשותף
    strncpy(message_buffer, shm_ptr->buffer[shm_ptr->tail], LOG_MESSAGE_SIZE - 1);
    message_buffer[LOG_MESSAGE_SIZE - 1] = '\0'; // ודא סיום null
    shm_ptr->tail = (shm_ptr->tail + 1) % MAX_LOG_MESSAGES;
    printf("Consumer consumed: %s\n", message_buffer);

    // 3. שחרור נעילת הקטע הקריטי (mutex)
    sem_post(mutex_sem);

    // 4. אותת שיש מקום פנוי (empty)
    sem_post(empty_sem);

    // סגירת סמפורים וזיכרון משותף בסיום השימוש (או בסיום התהליך)
    sem_close(mutex_sem);
    sem_close(empty_sem);
    sem_close(full_sem);
    munmap(shm_ptr, shm_size);
}
```

**הסבר Consumer:**
*   **`sem_wait(full_sem)`**: Consumer ממתין כאן אם אין הודעות לוג בחוצץ (כלומר, `full_sem` הוא 0). כאשר יש הודעה, הוא מפחית את `full_sem` באחד.
*   **`sem_wait(mutex_sem)`**: Consumer ממתין כאן כדי לקבל גישה בלעדית לקטע הקריטי (החוצץ). הוא מפחית את `mutex_sem` באחד (ל-0).
*   **קריאה מהחוצץ**: ההודעה מועתקת ממיקום `tail` בחוצץ. `tail` מתקדם באופן מעגלי.
*   **`sem_post(mutex_sem)`**: Consumer משחרר את הנעילה על הקטע הקריטי, ומגדיל את `mutex_sem` בחזרה ל-1.
*   **`sem_post(empty_sem)`**: Consumer מאותת ל-producer שיש כעת מקום פנוי נוסף בחוצץ, ומגדיל את `empty_sem` באחד.

### 1.4 סיום והתמודדות עם כשלים:

**סיום נקי (Graceful Shutdown):**
כדי לסיים את המערכת בצורה נקייה, ישנן מספר גישות:
1.  **"גלולת רעל" (Poison Pill Message):** ה-producers, כאשר אין להם יותר לוגים לייצר, יכולים לשלוח הודעה מיוחדת (למשל, מחרוזת מוגדרת כמו "SHUTDOWN") לחוצץ. ה-consumer, כאשר הוא קורא הודעה זו, מבין שהוא צריך לסיים את פעולתו. אם יש מספר producers, כל אחד יכול לשלוח גלולת רעל, או producer יחיד ייעודי יכול לשלוח מספר גלולות רעל כמספר ה-consumers (במקרה זה, consumer יחיד, אז גלולה אחת).
2.  **סמפור נוסף / דגל בזיכרון משותף:** ניתן להוסיף סמפור בינארי נוסף או דגל בזיכרון המשותף (`int shutdown_flag;`) שה-consumer בודק מעת לעת. כאשר ה-producers מסיימים, הם מציבים את הדגל. ה-consumer ימשיך לעבד הודעות קיימות בחוצץ, ולאחר מכן, כשהוא מזהה את הדגל ו-`full_sem` מגיע ל-0, הוא יסיים. גישה זו דורשת שה-consumer לא ייתקע ב-`sem_wait(full_sem)` לנצח, ולכן ייתכן שיהיה צורך ב-`sem_trywait` או בשימוש ב-`sem_timedwait` עם בדיקת הדגל לאחר מכן.
3.  **אותות (Signals):** תהליך חיצוני או אחד ה-producers יכול לשלוח אות (למשל `SIGTERM`) ל-consumer. ה-consumer יתפוס את האות, יסיים לעבד את שאר ההודעות בחוצץ, ויבצע ניקוי לפני יציאה.

לאחר שה-consumer מסיים את פעולתו, עליו לבצע ניקוי של משאבי ה-IPC:
*   `munmap()`: ניתוק הזיכרון המשותף ממרחב הכתובות של התהליך.
*   `shm_unlink()`: מחיקת אובייקט הזיכרון המשותף מהמערכת (הוא נמחק רק כאשר כל התהליכים ניתקו אותו).
*   `sem_close()`: סגירת כל הסמפורים הפתוחים.
*   `sem_unlink()`: מחיקת הסמפורים בעלי השמות מהמערכת.

**התמודדות עם כשלים (Process Crashes):**
קריסת תהליך יכולה להוביל למספר בעיות:

*   **קריסת Producer:**
    *   **השלכות:** אם producer קורס בזמן שהוא מחזיק את `mutex_sem` (כלומר, בתוך הקטע הקריטי), ה-`mutex_sem` יישאר נעול (ערכו יהיה 0). זה יגרום ל-deadlock, שכן אף producer או consumer אחר לא יוכל להיכנס לקטע הקריטי, והמערכת כולה תיתקע. הודעות לוג שכבר נכתבו לחוצץ על ידי producers אחרים לא יצרכו. אם producer קורס לפני שהוא מבצע `sem_post(full_sem)` לאחר כתיבה, ה-consumer לא ידע שיש הודעה חדשה, והודעה זו תישאר "בלתי נראית" ל-consumer.
    *   **התמודדות:**
        *   **Robust Mutexes:** סמפורים ב-Linux (PTHREAD_PROCESS_SHARED mutexes) יכולים להיות "robust", כלומר המערכת מזהה שתהליך המחזיק את המנעול קרס ומשחררת אותו, ומחזירה שגיאה לתהליך הבא שמנסה לנעול. POSIX named semaphores אינם תומכים בתכונה זו ישירות. לכן, יש לשקול שימוש ב-`pthread_mutex_t` עם `PTHREAD_PROCESS_SHARED` ו-`PTHREAD_MUTEX_ROBUST` אם הם מאוחסנים בזיכרון משותף.
        *   **Timeout:** ניתן להשתמש ב-`sem_timedwait` במקום `sem_wait` עם timeout קצר יחסית. אם ה-timeout פג, התהליך מניח שהסמפור נשאר נעול בגלל קריסה ומנסה להתאושש (למשל, על ידי ניסיון לאתחל מחדש את הסמפור, אם כי זה מסובך ויכול להוביל לבעיות עקביות).
        *   **תהליך ניטור (Monitor Process):** תהליך נפרד יכול לנטר את תהליכי ה-producer. אם producer קורס, תהליך הניטור יכול לנקות את הסמפורים (לדוגמה, על ידי קריאה ל-`sem_post` אם יודעים שהוא נשאר נעול, אבל זה מסוכן אם לא בטוחים). גישה זו מורכבת ליישום נכון.

*   **קריסת Consumer:**
    *   **השלכות:** אם ה-consumer קורס, אף אחד לא יצרוך יותר הודעות מהחוצץ. ה-producers ימשיכו לכתוב הודעות עד שהחוצץ יתמלא (`empty_sem` יגיע ל-0), ואז הם ייתקעו ב-`sem_wait(empty_sem)` וימתינו לנצח. הודעות הלוג שכבר נכתבו לחוצץ יאבדו אם ה-shared memory לא תנוטר ותיקרא על ידי consumer חדש.
    *   **התמודדות:**
        *   **תהליך ניטור:** תהליך חיצוני יכול לנטר את ה-consumer. אם ה-consumer קורס, תהליך הניטור יכול להפעיל מחדש את ה-consumer, אשר יפתח מחדש את ה-IPC resources וימשיך מנקודת הקריסה (ה-head וה-tail בזיכרון המשותף ישמרו את מצבם). יש לוודא שה-consumer החדש יתחיל לצרוך מהמקום הנכון בחוצץ. יש לנקות את הסמפורים שנותרו פתוחים על ידי ה-consumer הקודם (אם הם לא נסגרו כראוי).
        *   **Persistent Shared Memory:** מכיוון שאובייקטים של זיכרון משותף וסמפורים נשארים במערכת עד לביטול הקישור שלהם (`shm_unlink`, `sem_unlink`), קריסת תהליך לא תמחק אותם אוטומטית. זה מאפשר לתהליך חדש לפתוח אותם ולהמשיך לעבוד, אך דורש טיפול נכון בנעילות שנותרו.

בכל מקרה של קריסה, יש צורך במנגנוני ניטור ובדיקות עקביות כדי למנוע deadlock ולאפשר התאוששות מהירה ככל הניתן. ניקוי משאבים בסיום התהליך (גם בסיום נקי וגם במקרה של שגיאה) הוא קריטי למניעת זליגות משאבים ובעיות עקביות.

פתרון:

**1.1. עיצוב מבנה הנתונים והסנכרון:**
נשתמש במבנה נתונים בזיכרון משותף שיכלול את הבאפר המעגלי עצמו, אינדקסים לכתיבה וקריאה, וסמפורים לסנכרון. הבחירה בסמפורים מסוג POSIX (מובנים בתוך הזיכרון המשותף) מאפשרת סנכרון בין תהליכים שונים.

```c
#define BUFFER_SIZE 100

typedef struct {
    int buffer[BUFFER_SIZE]; // הבאפר המעגלי לאחסון מספרים שלמים
    int in;                   // אינדקס המצביע על המקום הבא לכתיבה על ידי היצרן
    int out;                  // אינדקס המצביע על המקום הבא לקריאה על ידי הצרכן
    sem_t mutex;              // סמפור בינארי להגנה על גישה לנתונים המשותפים (in, out, buffer)
    sem_t full;               // סמפור מונה המייצג את מספר המקומות הריקים בבאפר. היצרן ממתין אם 0.
    sem_t empty;              // סמפור מונה המייצג את מספר הפריטים המלאים בבאפר. הצרכנים ממתינים אם 0.
} shm_data_t;
```

**הסבר לבחירה:**
*   **`buffer[BUFFER_SIZE]`**: מערך בגודל קבוע לאחסון הנתונים.
*   **`in`, `out`**: אינדקסים למימוש באפר מעגלי. `in` מתקדם עם כתיבת היצרן, `out` מתקדם עם קריאת הצרכנים.
*   **`mutex`**: סמפור בינארי (ערך התחלתי 1). מגן על גישה הדדית לנתונים המשותפים (`in`, `out`, וגישה לתאי הבאפר עצמם). רק תהליך אחד יכול להחזיק ב-`mutex` בכל רגע נתון, ובכך למנוע מצבי מירוץ בעת עדכון האינדקסים או הגישה לבאפר.
*   **`full`**: סמפור מונה (ערך התחלתי `BUFFER_SIZE`). מספר את המקומות הפנויים בבאפר. היצרן מבצע `sem_wait` על `full` לפני כתיבה (ממתין אם הבאפר מלא), והצרכנים מבצעים `sem_post` על `full` לאחר קריאה (משחררים מקום).
*   **`empty`**: סמפור מונה (ערך התחלתי 0). מספר את הפריטים המלאים בבאפר. הצרכנים מבצעים `sem_wait` על `empty` לפני קריאה (ממתינים אם הבאפר ריק), והיצרן מבצע `sem_post` על `empty` לאחר כתיבה (מסמן שפריט חדש זמין).

**1.2. קוד יצרן (C/C++):**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <semaphore.h>

#define SHM_NAME "/my_shm_ipc_q"
#define BUFFER_SIZE 100

typedef struct {
    int buffer[BUFFER_SIZE];
    int in;     // Producer's index
    int out;    // Consumer's index
    sem_t mutex;  // Protects 'in', 'out', and buffer access
    sem_t full;   // Counts available slots for producer
    sem_t empty;  // Counts available items for consumers
} shm_data_t;

int main() {
    int shm_fd;
    shm_data_t *shm_ptr;

    // 1. יצירת אובייקט זיכרון משותף (או פתיחתו אם קיים)
    shm_fd = shm_open(SHM_NAME, O_CREAT | O_EXCL | O_RDWR, 0666); // O_EXCL מבטיח שהיצרן הוא היחיד שיוצר
    if (shm_fd == -1) {
        perror("shm_open (producer) - trying to unlink and retry");
        shm_unlink(SHM_NAME); // ניסיון לנקות משאב ישן וליצור מחדש
        shm_fd = shm_open(SHM_NAME, O_CREAT | O_RDWR, 0666);
        if (shm_fd == -1) {
            perror("shm_open (producer) - failed even after unlink");
            exit(EXIT_FAILURE);
        }
    }

    // 2. קביעת גודל אובייקט הזיכרון המשותף
    if (ftruncate(shm_fd, sizeof(shm_data_t)) == -1) {
        perror("ftruncate");
        shm_unlink(SHM_NAME); // ניקוי במקרה של כשל
        exit(EXIT_FAILURE);
    }

    // 3. מיפוי אובייקט הזיכרון המשותף למרחב הכתובות של התהליך
    shm_ptr = mmap(0, sizeof(shm_data_t), PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_ptr == MAP_FAILED) {
        perror("mmap");
        shm_unlink(SHM_NAME); // ניקוי במקרה של כשל
        exit(EXIT_FAILURE);
    }

    // 4. אתחול נתוני הזיכרון המשותף (רק פעם אחת על ידי היצרן)
    shm_ptr->in = 0;
    shm_ptr->out = 0;

    // 5. אתחול סמפורים (pshared = 1 מציין סמפורים בין-תהליכיים)
    if (sem_init(&shm_ptr->mutex, 1, 1) == -1) { perror("sem_init mutex"); munmap(shm_ptr, sizeof(shm_data_t)); shm_unlink(SHM_NAME); exit(EXIT_FAILURE); }
    if (sem_init(&shm_ptr->full, 1, BUFFER_SIZE) == -1) { perror("sem_init full"); sem_destroy(&shm_ptr->mutex); munmap(shm_ptr, sizeof(shm_data_t)); shm_unlink(SHM_NAME); exit(EXIT_FAILURE); }
    if (sem_init(&shm_ptr->empty, 1, 0) == -1) { perror("sem_init empty"); sem_destroy(&shm_ptr->mutex); sem_destroy(&shm_ptr->full); munmap(shm_ptr, sizeof(shm_data_t)); shm_unlink(SHM_NAME); exit(EXIT_FAILURE); }

    printf("Producer: Shared memory and semaphores initialized.\n");

    int item = 0;
    while (1) {
        // ייצור פריט
        printf("Producer: Producing item %d\n", item);
        sleep(1); // הדמיית עבודה

        // המתן למקום פנוי בבאפר
        sem_wait(&shm_ptr->full);
        // רכוש את ה-mutex לגישה לבאפר ולנתונים המשותפים
        sem_wait(&shm_ptr->mutex);

        // כתוב את הפריט לבאפר
        shm_ptr->buffer[shm_ptr->in] = item;
        shm_ptr->in = (shm_ptr->in + 1) % BUFFER_SIZE;

        printf("Producer: Wrote item %d, in = %d\n", item, shm_ptr->in);

        // שחרר את ה-mutex
        sem_post(&shm_ptr->mutex);
        // סמן שפריט זמין לקריאה
        sem_post(&shm_ptr->empty);

        item++;
    }

    // ניקוי (בתרחיש אמיתי, יטופל על ידי פונקציית ניקוי או מטפל אותות)
    sem_destroy(&shm_ptr->mutex);
    sem_destroy(&shm_ptr->full);
    sem_destroy(&shm_ptr->empty);
    munmap(shm_ptr, sizeof(shm_data_t));
    shm_unlink(SHM_NAME);

    return 0;
}
```

**1.3. קוד צרכן (C/C++):**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <semaphore.h>

#define SHM_NAME "/my_shm_ipc_q"
#define BUFFER_SIZE 100

typedef struct {
    int buffer[BUFFER_SIZE];
    int in;
    int out;
    sem_t mutex;
    sem_t full;
    sem_t empty;
} shm_data_t;

int main(int argc, char *argv[]) {
    int shm_fd;
    shm_data_t *shm_ptr;
    int consumer_id = (argc > 1) ? atoi(argv[1]) : getpid(); // מזהה צרכן, שימושי לניפוי באגים

    // 1. פתיחת אובייקט הזיכרון המשותף (חייב כבר להיות קיים)
    shm_fd = shm_open(SHM_NAME, O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("shm_open (consumer) - ensure producer is running");
        exit(EXIT_FAILURE);
    }

    // 2. מיפוי אובייקט הזיכרון המשותף למרחב הכתובות של התהליך
    shm_ptr = mmap(0, sizeof(shm_data_t), PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_ptr == MAP_FAILED) {
        perror("mmap (consumer)");
        exit(EXIT_FAILURE);
    }

    printf("Consumer %d: Attached to shared memory.\n", consumer_id);

    while (1) {
        // המתן לפריט זמין בבאפר
        sem_wait(&shm_ptr->empty);
        // רכוש את ה-mutex לגישה לבאפר ולנתונים המשותפים
        sem_wait(&shm_ptr->mutex);

        // קרא את הפריט מהבאפר
        int item = shm_ptr->buffer[shm_ptr->out];
        shm_ptr->out = (shm_ptr->out + 1) % BUFFER_SIZE;

        printf("Consumer %d: Read item %d, out = %d\n", consumer_id, item, shm_ptr->out);

        // שחרר את ה-mutex
        sem_post(&shm_ptr->mutex);
        // סמן שמקום התפנה בבאפר
        sem_post(&shm_ptr->full);

        sleep(2); // הדמיית עבודה
    }

    // ניקוי (צרכנים בדרך כלל לא מבצעים unlink או destroy לסמפורים)
    munmap(shm_ptr, sizeof(shm_data_t));
    // close(shm_fd); // ניתן לסגור את ה-fd לאחר munmap

    return 0;
}
