volatile sig_atomic_t signal_received_count = 0;

void handler(int signum) {
    signal_received_count++;
}

int main() {
    sigset_t block_mask, old_mask;
    struct sigaction sa;

    // 1. Block SIGUSR1
    sigemptyset(&block_mask);
    sigaddset(&block_mask, SIGUSR1);
    if (sigprocmask(SIG_BLOCK, &block_mask, &old_mask) == -1) {
        perror("sigprocmask block");
        return 1;
    }
    printf("Main: SIGUSR1 blocked. Old mask saved.\n");

    // 2. Set up signal handler for SIGUSR1
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask); // No additional signals blocked inside handler
    sa.sa_flags = 0; // Default behavior

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    printf("Main: SIGUSR1 handler set.\n");

    // 3. Simulate a signal arriving while SIGUSR1 is blocked
    printf("Main: Raising SIGUSR1 (it's blocked).\n");
    raise(SIGUSR1); // SIGUSR1 is now pending

    // 4. Call sigsuspend with the old_mask (which does *not* block SIGUSR1)
    printf("Main: Calling sigsuspend...\n");
    sigsuspend(&old_mask); // Temporarily unblocks SIGUSR1 and waits

    printf("Main: sigsuspend returned. Signal received count: %d\n", signal_received_count);

    // Restore original mask, although not strictly necessary for this example
    sigprocmask(SIG_SETMASK, &old_mask, NULL);

