        sigset_t suspend_mask;
        sigemptyset(&suspend_mask); // Empty mask means all signals (including SIGUSR1) are unblocked during suspend

        printf("[%d] Child: Calling sigsuspend...\n", getpid());
        sigsuspend(&suspend_mask); // Child waits for a signal

