solution.explanation:
הפתרון כולל פונקציית מטפל אותות (signal handler) עבור SIGINT. פונקציה זו, `sigint_handler`, תדפיס הודעה ותקרא ל-`exit(0)` כדי לסיים את התוכנית בצורה מסודרת.
בתוך הפונקציה הראשית `main`, נשתמש ב-`signal(SIGINT, sigint_handler)` כדי לרשום את המטפל עבור האות SIGINT. לאחר מכן, התוכנית תיכנס ללולאה אינסופית (תוך שימוש ב-`sleep` כדי למנוע צריכת מעבד גבוהה) ותמתין לקבלת האות. כאשר המשתמש ילחץ Ctrl+C (או ישלח את האות בדרך אחרת), המטפל יופעל והתוכנית תסיים את ריצתה.

```c
#include <stdio.h>
#include <signal.h>
#include <stdlib.h> // For exit()
#include <unistd.h> // For sleep()

// Signal handler for SIGINT
void sigint_handler(int signo) {
    if (signo == SIGINT) {
        printf("\nSIGINT received!\n");
        exit(0); // Terminate the program gracefully
    }
}

int main() {
    // Register the signal handler for SIGINT
    // signal() returns SIG_ERR on failure
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Cannot catch SIGINT");
        return 1;
    }

    printf("Waiting for SIGINT... (Press Ctrl+C to send SIGINT)\n");

    // Infinite loop to keep the program running and waiting for the signal
    while (1) {
        sleep(1); // Sleep for a second to reduce CPU usage
    }

    return 0; // This line will not be reached due to exit(0) in handler
}
```

8.1: כדי לטפל באות SIGINT, נשתמש בפונקציה `signal()` (או `sigaction()` לטיפול מתקדם יותר) כדי לרשום פונקציית טיפול (handler) שתופעל כאשר האות מתקבל. בתוך פונקציית הטיפול, נדפיס את ההודעה הרצויה. לולאה אינסופית עם `sleep()` או `pause()` תאפשר לתהליך להמתין לאות מבלי לסיים.

```c
#include <stdio.h>
#include <signal.h>
#include <unistd.h> // For sleep

void sigint_handler(int signum) {
    printf("Caught SIGINT!\n");
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    printf("Press Ctrl+C to send SIGINT. The process will catch it.\n");
    printf("Press Ctrl+\\ to send SIGQUIT and terminate the process.\n");

    // Loop indefinitely to keep the process running and waiting for signals
    while (1) {
        sleep(1); // Wait for 1 second
    }

    return 0;
}
```

8.2: שני אותות שלא ניתן ללכוד או להתעלם מהם הם:
1. SIGKILL (אות מספר 9): משמש לסיום תהליך באופן מיידי ולא ניתן לחסום או לטפל בו.
2. SIGSTOP (אות מספר 19 בדרך כלל): משמש להשהיית תהליך ולא ניתן לחסום או לטפל בו. (SIGCONT משחרר אותו מהשהייה).
מטרתם של אותות אלו היא לספק דרך אמינה לקרנל או לתהליכים מורשים לשלוט בתהליכים אחרים, גם אם הם מנסים לחסום או להתעלם מאותות אחרים.

הפתרון כולל הגדרת פונקציית מטפל לאות (signal handler) באמצעות הפונקציה `signal()` מהספרייה `signal.h`. כאשר המערכת מקבלת את האות `SIGINT` (לחיצת Ctrl+C), במקום לבצע את פעולת ברירת המחדל (סיום התהליך), היא קוראת לפונקציה `sigint_handler`. פונקציה זו מדפיסה הודעה וחוזרת, מה שמאפשר לתוכנית הראשית (הלולאה האינסופית) להמשיך לפעול. הפונקציה `sleep()` משמשת כדי שהתוכנית לא תצרוך את כל משאבי המעבד בזמן ההמתנה.

```c
#include <stdio.h>
#include <signal.h>
#include <unistd.h>

// Signal handler function for SIGINT
void sigint_handler(int signum) {
    printf("\nקיבלתי SIGINT! ממשיך לפעול...\n");
    // No exit here, so the program continues
}

int main() {
    // Register the signal handler for SIGINT
    // When SIGINT is received, sigint_handler will be called instead of default action
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Can't catch SIGINT");
        return 1;
    }

    printf("התוכנית רצה. לחץ Ctrl+C כדי לשלוח SIGINT.\n");

    // Infinite loop to demonstrate continuous operation
    while (1) {
        printf("התוכנית ממשיכה לפעול...\n");
        sleep(3); // Wait for 3 seconds
    }

    return 0;
}
```

כדי לטפל באותות, נשתמש בפונקציות מהספרייה `<signal.h>`. 
1.  **הגדרת פונקציית טיפול (Signal Handler):** ניצור פונקציה `sigint_handler` שתקבל את מספר האות כפרמטר ותבוצע כאשר `SIGINT` יתקבל. פונקציה זו תדפיס הודעה מתאימה.
2.  **רישום ה-Handler:** נשתמש ב-`signal(SIGINT, sigint_handler);` בתוך `main` כדי לרשום את `sigint_handler` כפונקציית הטיפול עבור `SIGINT`.
3.  **השארת התוכנית רצה:** כדי שהתוכנית לא תסיים את ריצתה מיד, נשתמש בלולאה אינסופית המכילה קריאה ל-`pause()`. הפונקציה `pause()` משעה את ביצוע התהליך עד לקבלת אות כלשהו.
4.  **טיפול ב-SIGQUIT:** כברירת מחדל, `SIGQUIT` גורם לסיום התהליך וליצירת קובץ core dump. אם לא נרשום handler מיוחד עבורו, הוא יפעל כרגיל ויאפשר יציאה מהתוכנית.

**קוד לדוגמה:**
```c
#include <stdio.h>
#include <signal.h>
#include <unistd.h> // for pause()

// פונקציית טיפול עבור SIGINT
void sigint_handler(int signum) {
    printf("\nCaught SIGINT (%d)! Press Ctrl+\\ to quit.\n", signum);
    // לאחר טיפול באות, התוכנית ממשיכה מנקודת הקריאה ל-pause().
}

int main() {
    printf("Program started. Try pressing Ctrl+C (SIGINT) to see the handler in action.\n");
    printf("To quit, press Ctrl+\\ (SIGQUIT).\n");

    // רישום פונקציית הטיפול עבור SIGINT
    signal(SIGINT, sigint_handler);

    // לולאה אינסופית שממתינה לאותות
    while (1) {
        pause(); // השהיית התהליך עד לקבלת אות
    }

    return 0; // קוד זה לעולם לא יגיע אליו אם יוצאים עם SIGQUIT
}
```

הפתרון כולל הגדרה של שני משתנים גלובליים מסוג `volatile`: מונה לקריאות `SIGINT` ודגל יציאה. שימוש ב-`volatile` הכרחי מכיוון שמשתנים אלה נגישים ומשתנים גם מהפונקציות המטפלות באותות וגם מהלולאה הראשית של התוכנית.

עבור כל אות (`SIGINT` ו-`SIGTERM`), נשתמש בפונקציה `sigaction` כדי להגדיר מטפל אותות (signal handler) ייעודי. `sigaction` עדיפה על `signal()` הישנה יותר מכיוון שהיא מספקת שליטה טובה יותר על התנהגות האותות ומונעת בעיות ניידות.

המטפל עבור `SIGINT` יגדיל את המונה `sigint_count`, ידפיס הודעה מתאימה, ויבדוק אם המונה הגיע ל-3. אם כן, הוא יגדיר את דגל היציאה `should_exit` ל-1. המטפל עבור `SIGTERM` פשוט יגדיר את `should_exit` ל-1, מה שיגרום לתוכנית לצאת מיד.

בלולאה הראשית, התוכנית תדפיס הודעה כל שנייה ותבדוק את הערך של `should_exit`. כאשר `should_exit` הופך ל-1, הלולאה תסתיים והתוכנית תצא בצורה מסודרת.

```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

// משתנים גלובליים שמשתנים על ידי מטפלי האותות והלולאה הראשית
volatile int sigint_count = 0;
volatile int should_exit = 0;

// מטפל באות SIGINT
void sigint_handler(int signum) {
    if (signum == SIGINT) {
        sigint_count++;
        printf("\nקיבלתי SIGINT! ממשיך לרוץ... (סה"כ %d)\n", sigint_count);
        if (sigint_count >= 3) {
            printf("קיבלתי SIGINT 3 פעמים, יוצא מהתוכנית.\n");
            should_exit = 1;
        }
    }
}

// מטפל באות SIGTERM
void sigterm_handler(int signum) {
    if (signum == SIGTERM) {
        printf("\nקיבלתי SIGTERM! יוצא מהתוכנית באופן מסודר.\n");
        should_exit = 1;
    }
}

int main() {
    struct sigaction sa_int, sa_term;

    // הגדרת מטפל עבור SIGINT
    sa_int.sa_handler = sigint_handler;
    sigemptyset(&sa_int.sa_mask);
    sa_int.sa_flags = 0; // אין צורך בדגלים מיוחדים למקרה זה
    if (sigaction(SIGINT, &sa_int, NULL) == -1) {
        perror("Error setting SIGINT handler");
        return 1;
    }

    // הגדרת מטפל עבור SIGTERM
    sa_term.sa_handler = sigterm_handler;
    sigemptyset(&sa_term.sa_mask);
    sa_term.sa_flags = 0; // אין צורך בדגלים מיוחדים למקרה זה
    if (sigaction(SIGTERM, &sa_term, NULL) == -1) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    printf("התוכנית רצה. PID: %d\n", getpid());
    printf("לחץ Ctrl+C (SIGINT) שלוש פעמים כדי לצאת, או שלח SIGTERM כדי לצאת מיד.\n");

    while (!should_exit) {
        printf("התוכנית עדיין רצה...\n");
        sleep(1);
    }

    printf("התוכנית הסתיימה בהצלחה.\n");
    return 0;
}
```

