volatile int sig_count = 0;

void signal_handler(int signum) {
    sig_count++;
    // הדפסה בתוך ה-signal handler
    printf("Received signal %d. Total signals: %d\n", signum, sig_count);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0; // ללא דגלים מיוחדים

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    printf("Process %d is running. Send SIGUSR1 to test.\n", getpid());

    while (1) {
        sleep(5); // מדמה עבודה אחרת
    }

    return 0;
