solution.explanation:
הבעיה המרכזית בקוד המצורף היא הקריאה לפונקציה `printf()` מתוך ה-signal handler (`signal_handler`). פונקציית `printf()` אינה פונקציה 'בטוחה לאותות אסינכרוניים' (async-signal-safe). המשמעות היא שאם אות מגיע בזמן שהתהליך הראשי (או כל חלק אחר בתוכנית) מבצע קריאה ל-`printf()` או לפונקציה אחרת שאינה בטוחה לאותות, ה-signal handler יקטע את הביצוע של `printf()`. כאשר ה-signal handler קורא שוב ל-`printf()`, הוא עלול לגשת למבני נתונים פנימיים של `printf()` שנמצאים במצב לא עקבי, מה שיכול להוביל לשגיאות, פלט משובש, קריסות של התוכנית (deadlocks או segfaults), או התנהגות בלתי צפויה אחרת.

פתרון מוצע:
יש להימנע משימוש בפונקציות שאינן async-signal-safe בתוך signal handlers. במקום זאת:
1. **לוגינג פשוט:** אם יש צורך בלוגינג בסיסי, ניתן להשתמש בפונקציות async-signal-safe כמו `write()` לכתיבה ל-`stderr`. לדוגמה, במקום `printf("...")`, ניתן להשתמש ב-`write(STDERR_FILENO, "...", strlen("..."))`.
2. **הגדרת דגל וטיפול מחוץ ל-handler:** דרך עדיפה יותר היא שה-signal handler יבצע את המינימום ההכרחי – לרוב, רק הגדרת דגל גלובלי (מסוג `volatile sig_atomic_t`) או עדכון משתנה אטומי. התהליך הראשי יבדוק מעת לעת את הדגל הזה ויבצע את הפעולות המורכבות יותר (כמו הדפסה, הקצאת זיכרון, או קריאה לפונקציות לא בטוחות) מחוץ ל-handler, בסביבה בטוחה.

לדוגמה, במקרה זה, ה-handler יכול רק להגדיל את `sig_count` ולהגדיר דגל שצריך לטפל באות, והלולאה הראשית תדפיס:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h> // For strlen

volatile sig_atomic_t sig_count = 0;
volatile sig_atomic_t signal_received_flag = 0; // New flag

void signal_handler(int signum) {
    sig_count++;
    signal_received_flag = 1; // Set flag
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    printf("Process %d is running. Send SIGUSR1 to test.\n", getpid());

    while (1) {
        sleep(1); // Check more frequently
        if (signal_received_flag) {
            // Handle the signal processing safely outside the handler
            printf("Received signal (handled outside). Total signals: %d\n", sig_count);
            signal_received_flag = 0; // Reset flag
        }
    }

    return 0;
}
```

הפתרון כולל הגדרת מטפל לאות SIGINT באמצעות `sigaction` והגנה על קטע קריטי באמצעות `sigprocmask`.

**הקוד המלא:**
```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h> // For sleep

volatile int sigint_count = 0;
volatile int main_loop_count = 0;

void sigint_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT! (Count: %d)\n", ++sigint_count);
    }
}

int main() {
    struct sigaction sa;
    sigset_t block_mask, old_mask;

    // 1. Setup SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask); // No additional signals blocked inside handler
    sa.sa_flags = 0; // No special flags
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Prepare a signal set to block SIGINT
    sigemptyset(&block_mask);
    sigaddset(&block_mask, SIGINT);

    printf("Program started. Press Ctrl+C to send SIGINT.\n");
    printf("Entering main loop...\n");

    while (1) {
        main_loop_count++;
        printf("Main loop iteration: %d\n", main_loop_count);

        // Simulate some work before critical section
        sleep(1);

        // --- Critical Section Start ---
        printf("  Entering critical section...\n");

        // Block SIGINT before entering critical section
        if (sigprocmask(SIG_BLOCK, &block_mask, &old_mask) == -1) {
            perror("sigprocmask BLOCK");
            exit(EXIT_FAILURE);
        }

        // Simulate critical work (should not be interrupted by SIGINT)
        printf("  Performing critical work...\n");
        sleep(3); // Long operation
        printf("  Critical work finished.\n");

        // Unblock SIGINT after exiting critical section
        if (sigprocmask(SIG_SETMASK, &old_mask, NULL) == -1) {
            perror("sigprocmask UNBLOCK");
            exit(EXIT_FAILURE);
        }
        printf("  Exited critical section.\n");
        // --- Critical Section End ---

        printf("Main loop continues...\n");
        sleep(1);
    }

    return 0;
}
```

**הסבר הקוד:**
1.  **מטפל האותות (`sigint_handler`):**
    *   פונקציה זו נקראת כאשר אות SIGINT מתקבל.
    *   היא מדפיסה הודעה ומגדילה את המונה הגלובלי `sigint_count`. המונה הוכרז כ-`volatile` כדי להבטיח שהקומפיילר לא יבצע אופטימיזציות שעלולות למנוע עדכון נכון של המשתנה על ידי המטפל.

2.  **הגדרת מטפל SIGINT (`main`):**
    *   משתמשים במבנה `struct sigaction` כדי להגדיר את המטפל. זוהי הדרך המודרנית והמומלצת לטיפול באותות, לעומת `signal()`, מכיוון שהיא מספקת שליטה רבה יותר (כמו הגדרת מסכת אותות נוספת במהלך ביצוע המטפל).
    *   `sa.sa_handler` מצביע לפונקציית המטפל שלנו (`sigint_handler`).
    *   `sigemptyset(&sa.sa_mask)` מבטיח שאף אות נוסף לא ייחסם באופן אוטומטי בזמן שהמטפל רץ (מלבד האות המטופל עצמו, SIGINT, שנחסם כברירת מחדל בזמן הטיפול בו).
    *   `sigaction(SIGINT, &sa, NULL)` רושם את המטפל שלנו עבור SIGINT.

3.  **הגנה על קטע קריטי (`main`):**
    *   **הכנת מסכה לחסימה:** יוצרים קבוצת אותות `block_mask` ומוסיפים אליה את SIGINT באמצעות `sigaddset`.
    *   **כניסה לקטע קריטי:** לפני הכניסה לקטע הקריטי, קוראים ל-`sigprocmask(SIG_BLOCK, &block_mask, &old_mask)`.
        *   `SIG_BLOCK` מציין שאנו רוצים להוסיף את האותות ב-`block_mask` למסכת האותות הנוכחית של התהליך.
        *   `&old_mask` משמש לשמירת מסכת האותות שהייתה פעילה לפני החסימה. זה חשוב כדי שנוכל לשחזר אותה במדויק ביציאה מהקטע הקריטי.
        *   בנקודה זו, SIGINT נחסם. אם אות SIGINT יגיע עכשיו, הוא לא יטופל מיד אלא יישאר ממתין (pending) וייטופל רק כאשר האות יבוטל חסימתו.
    *   **ביצוע עבודה קריטית:** מדמים עבודה ארוכה באמצעות `sleep(3)`.
    *   **יציאה מהקטע הקריטי:** לאחר סיום העבודה הקריטית, קוראים ל-`sigprocmask(SIG_SETMASK, &old_mask, NULL)`.
        *   `SIG_SETMASK` מציין שאנו רוצים להגדיר את מסכת האותות של התהליך למסכה ששמרנו ב-`old_mask`. פעולה זו מבטלת את חסימת SIGINT (ומחזירה את כל האותות למצבם המקורי לפני הכניסה לקטע הקריטי).
        *   אם SIGINT הגיע בזמן שהוא חסום, הוא יסופק כעת לתהליך ויטופל על ידי `sigint_handler`.

**לוגיקה:**
השימוש ב-`sigprocmask` מאפשר לנו ליצור "חלונות" קריטיים בתוכנית שבהם אנו לא רוצים שאותות ספציפיים יפריעו למהלך התקין של הביצוע. על ידי חסימת SIGINT לפני הכניסה לקטע הקריטי ושחרור החסימה ביציאה ממנו, אנו מבטיחים שפעולות רגישות לא יופרעו באופן אסינכרוני. אם אות מגיע בזמן שהוא חסום, הוא נשאר במצב "ממתין" (pending) ומועבר למטפל רק כאשר האות משוחרר מחסימה.

הפתרון משתמש בפונקציה `sigprocmask` כדי לנהל את מסכת האותות החסומים עבור התהליך.

להלן דוגמת קוד המממשת את הדרישות:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

void sigint_handler(int signo) {
    printf("\n[Handler] Received SIGINT. Exiting gracefully...\n");
    exit(0);
}

int main() {
    // 1. Register the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask); // Don't block any other signals while handler runs
    sa.sa_flags = 0; // No special flags
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    printf("Process started. SIGINT handler registered. Press Ctrl+C.\n");

    sigset_t block_mask, old_mask;

    // 2. Initialize a signal set to block SIGINT
    sigemptyset(&block_mask);
    sigaddset(&block_mask, SIGINT);

    while (1) {
        // Before critical section
        printf("Entering critical section in 3 seconds...\n");
        sleep(3);

        // --- BLOCK SIGINT ---
        // Block SIGINT and save the old mask
        if (sigprocmask(SIG_BLOCK, &block_mask, &old_mask) == -1) {
            perror("sigprocmask SIG_BLOCK");
            exit(EXIT_FAILURE);
        }
        printf("SIGINT is now BLOCKED.\n");

        // --- CRITICAL SECTION START ---
        printf("CRITICAL SECTION: Performing sensitive operations (5 seconds)...\n");
        sleep(5); // Simulate critical work
        printf("CRITICAL SECTION: Done.\n");
        // --- CRITICAL SECTION END ---

        // --- UNBLOCK SIGINT ---
        // Restore the old signal mask (which unblocks SIGINT)
        if (sigprocmask(SIG_SETMASK, &old_mask, NULL) == -1) {
            perror("sigprocmask SIG_SETMASK");
            exit(EXIT_FAILURE);
        }
        printf("SIGINT is now UNBLOCKED.\n");

        // After critical section
        printf("Exiting critical section. Waiting 2 seconds before re-entering.\n");
        sleep(2);
    }

    return 0;
}
```

**הסבר מפורט**:

1.  **הגדרת Handler**: ראשית, אנו מגדירים `sigint_handler` שיטפל באות `SIGINT`. Handler זה פשוט מדפיס הודעה ויוצא מהתהליך בצורה מסודרת. אנו משתמשים ב-`sigaction` במקום ב-`signal` הישנה מכיוון שהיא מציעה שליטה טובה יותר והיא הדרך המועדפת לטפל באותות ב-POSIX. הוספת `sigemptyset(&sa.sa_mask);` מבטיחה שאף אות נוסף לא ייחסם באופן אוטומטי בזמן שה-handler רץ.
2.  **יצירת מסכה לחסימה**: אנו יוצרים קבוצת אותות (`sigset_t`) בשם `block_mask` ומכניסים לתוכה את האות `SIGINT` באמצעות `sigemptyset` (לאתחול הקבוצה כריקה) ו-`sigaddset` (להוספת `SIGINT`). קבוצה זו תגדיר אילו אותות אנו רוצים לחסום.
3.  **חסימת אותות לפני קטע קריטי**: לפני הכניסה לקטע הקריטי, אנו קוראים ל-`sigprocmask` עם `SIG_BLOCK` ו-`block_mask`. פעולה זו מוסיפה את האותות המוגדרים ב-`block_mask` (במקרה זה `SIGINT`) למסכת האותות החסומים הנוכחית של התהליך. הפרמטר השלישי, `&old_mask`, משמש לשמירת המסכה הקודמת של התהליך. זה קריטי כדי שנוכל לשחזר את המצב הקודם מאוחר יותר. אם אות `SIGINT` נשלח בזמן שהוא חסום, הוא לא יימסר מיד (כלומר, ה-handler לא יופעל) אלא יישאר תלוי ועומד (pending) עד שהאות יבוטל חסימתו. אם אותו אות נשלח מספר פעמים בזמן החסימה, בדרך כלל רק מופע אחד שלו יישמר כ-pending ויימסר לאחר ביטול החסימה (בהתאם לסוג האות).
4.  **ביצוע קטע קריטי**: התהליך מבצע את הפעולות הרגישות בקטע הקריטי. במהלך 5 השניות הללו, אם Ctrl+C נלחץ, ה-handler של `SIGINT` לא יופעל מיד, והתהליך ימשיך בביצוע הקטע הקריטי.
5.  **ביטול חסימת אותות אחרי קטע קריטי**: לאחר שהתהליך סיים את הקטע הקריטי, אנו קוראים שוב ל-`sigprocmask`, הפעם עם `SIG_SETMASK` ו-`old_mask`. פעולה זו מחזירה את מסכת האותות של התהליך למצב שהיה לפני החסימה, ובכך מבטלת את חסימת `SIGINT`. אם אות `SIGINT` היה תלוי ועומד בזמן החסימה, הוא יימסר לתהליך מיד לאחר ביטול החסימה (כלומר, ה-handler יופעל).

**חשיבות המנגנון**:
המנגנון הזה קריטי כאשר ישנם קטעי קוד שבהם קבלת אות עלולה להוביל למצב לא עקבי של המערכת, לדוגמה, אם התהליך מעדכן מבני נתונים משותפים, משאבים חיוניים, או קבצים. חסימת האות מבטיחה שהקטע הקריטי יסתיים בשלמותו לפני שהאות יטופל. זה מונע הפסקות בלתי צפויות שיכולות להשאיר את הנתונים במצב חלקי או פגום, ובכך שומר על אמינות ושלמות הנתונים והמערכת.

הפתרון כולל שלושה מרכיבים עיקריים:

1.  **הגדרת מטפל אות (Signal Handler) עבור `SIGINT`**:
    *   פונקציית `sigint_handler` מוגדרת כמטפל האות. כאשר `SIGINT` מתקבל, פונקציה זו תופעל. היא מדפיסה הודעה ויוצאת מהתוכנית בצורה נקייה באמצעות `exit(0)`.
    *   הפונקציה `sigaction` משמשת להתקנת המטפל. אנו מאתחלים את המבנה `sa` עם הפונקציה שלנו (`sa.sa_handler = sigint_handler`), מרוקנים את מסכת האותות של המטפל (`sigemptyset(&sa.sa_mask)`) כדי שלא יחסום אותות נוספים בזמן הריצה שלו, ומגדירים את הדגל `SA_RESTART` כדי שמערכות קריאות שנקטעו על ידי האות יופעלו מחדש אוטומטית.

2.  **חסימת `SIGINT` לפני הקטע הקריטי**:
    *   לפני הכניסה לקטע הקריטי, אנו רוצים למנוע מ-`SIGINT` לקטוע את התהליך.
    *   אנו יוצרים סט אותות (`sigset_t blocked_signals`) ומוסיפים אליו את `SIGINT` באמצעות `sigaddset`.
    *   הפונקציה `sigprocmask` נקראת עם `SIG_BLOCK` כדי להוסיף את האותות בסט `blocked_signals` למסכת האותות של התהליך הנוכחי. כלומר, `SIGINT` נחסם כעת. אם `SIGINT` יתקבל בזמן זה, הוא לא יופעל מיד אלא יישאר במצב "ממתין" (pending).

3.  **שחרור חסימת `SIGINT` לאחר הקטע הקריטי**:
    *   לאחר שהקטע הקריטי מסתיים, אנו רוצים שהתוכנית תחזור להיות רגישה ל-`SIGINT`.
    *   שוב נקרא לפונקציה `sigprocmask`, הפעם עם `SIG_UNBLOCK`, כדי להסיר את `SIGINT` ממסכת האותות של התהליך.
    *   ברגע ש-`SIGINT` משוחרר מחסימה, אם הוא התקבל בזמן שהיה חסום (כלומר, היה "ממתין"), הוא יטופל מיד על ידי המטפל שהוגדר.
    *   התוכנית מדפיסה הודעות כדי להמחיש מתי היא נכנסת ויוצאת מהקטע הקריטי ומתי האותות נחסמים ומשוחררים. הלולאה הראשית מדפיסה "Working normally..." ומדי פעם נכנסת לקטע הקריטי.

הפתרון מדגים כיצד ניתן לשלוט על קבלת אותות באופן דינמי במהלך ריצת התוכנית, ובכך להגן על קטעים קריטיים מפני הפרעות לא רצויות תוך שמירה על יכולת תגובה לאותות בשאר זמני הריצה.

```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h> // For sleep

// Signal handler for SIGINT
void sigint_handler(int signo) {
    printf("\n[Handler] SIGINT received. Exiting gracefully.\n");
    exit(0);
}

int main() {
    struct sigaction sa;
    sigset_t blocked_signals; // Set for signals to block

    // 1. Set up the SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask); // Don't block any additional signals within the handler
    sa.sa_flags = SA_RESTART; // Restart interrupted system calls
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    printf("Program started. Press Ctrl+C to exit (outside critical section).\n");

    while (1) {
        // Normal operation loop
        printf("Working normally...\n");
        sleep(1);

        // Simulate entering a critical section every few seconds
        // Using a simple counter for demonstration, instead of rand()
        static int counter = 0;
        if (counter++ % 5 == 0) { // Enter critical section every 5 seconds
            printf("\n--- Entering CRITICAL SECTION ---\n");

            // 2. Block SIGINT before critical section
            sigemptyset(&blocked_signals);
            sigaddset(&blocked_signals, SIGINT);
            if (sigprocmask(SIG_BLOCK, &blocked_signals, NULL) == -1) {
                perror("sigprocmask SIG_BLOCK");
                exit(1);
            }
            printf("SIGINT is now BLOCKED.\n");

            // Critical operation (simulated with sleep)
            for (int i = 0; i < 5; ++i) {
                printf("Critical operation... %d/5\n", i + 1);
                sleep(1);
            }

            printf("SIGINT will now be UNBLOCKED.\n");
            // 3. Unblock SIGINT after critical section
            if (sigprocmask(SIG_UNBLOCK, &blocked_signals, NULL) == -1) {
                perror("sigprocmask SIG_UNBLOCK");
                exit(1);
            }
            printf("--- Exiting CRITICAL SECTION ---\n");
            printf("SIGINT is now UNBLOCKED. If pending, it will be delivered now.\n\n");
        }
    }

    return 0; // Should not be reached
}
```

