#include <errno.h>

volatile sig_atomic_t sigusr1_received = 0;

void handler(int signum) {
    if (signum == SIGUSR1) {
        sigusr1_received = 1;
        printf("Child: SIGUSR1 received!\n");
    }
}

void critical_work() {
    printf("Child: Performing critical work...\n");
    sleep(2); // Simulate critical work
    printf("Child: Critical work finished.\n");
}

void child_process() {
    printf("Child: PID %d started.\n", getpid());

    // TODO: Implement signal handling logic here
    // 1. Block SIGUSR1 initially.
    // 2. Perform critical_work().
    // 3. Wait for SIGUSR1 using sigprocmask and sigsuspend safely.
    // 4. Print "Child: Exiting."

    printf("Child: Exiting.\n");
}

void parent_process(pid_t child_pid) {
    printf("Parent: PID %d started. Child PID: %d\n", getpid(), child_pid);
    sleep(3); // Give child time to set up and do critical work
    printf("Parent: Sending SIGUSR1 to child %d\n", child_pid);
    if (kill(child_pid, SIGUSR1) == -1) {
        perror("kill");
        exit(EXIT_FAILURE);
    }
    printf("Parent: SIGUSR1 sent.\n");
    wait(NULL); // Wait for child to finish
    printf("Parent: Child finished, exiting.\n");
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0; // No SA_RESTART or SA_SIGINFO needed for this simple case

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process
        child_process();
    } else {
        // Parent process
        parent_process(pid);
    }

    return 0;
}

solution.explanation:
פתרון:

להלן קוד מלא ומתוקן עבור פונקציית `child_process`:

```c
void child_process() {
    printf("Child: PID %d started.\n", getpid());

    sigset_t oldmask, blockmask, suspend_mask;

    // 1. חסימת SIGUSR1 בתחילה:
    // יוצרים מסכה שתחסום את SIGUSR1.
    sigemptyset(&blockmask);
    sigaddset(&blockmask, SIGUSR1);
    // חוסמים את SIGUSR1 ושומרים את המסכה הקודמת ב-oldmask.
    if (sigprocmask(SIG_BLOCK, &blockmask, &oldmask) == -1) {
        perror("sigprocmask BLOCK");
        exit(EXIT_FAILURE);
    }
    printf("Child: SIGUSR1 blocked.\n");

    // 2. ביצוע העבודה הקריטית:
    // העבודה מתבצעת בזמן ש-SIGUSR1 חסום, כך שהוא לא יפריע.
    critical_work();

    // 3. הכנת המסכה עבור sigsuspend:
    // אנו רוצים ש-sigsuspend ימתין ל-SIGUSR1. לשם כך,
    // עלינו להעביר ל-sigsuspend מסכה שבה SIGUSR1 אינו חסום,
    // אך כל שאר האותות שכרגע חסומים יישארו חסומים.
    // נתחיל מהמסכה הנוכחית (שבה SIGUSR1 חסום)
    if (sigprocmask(SIG_SETMASK, NULL, &suspend_mask) == -1) { // קבל את המסכה הנוכחית
        perror("sigprocmask GET");
        exit(EXIT_FAILURE);
    }
    // ונבטל את חסימת SIGUSR1 במסכה זו.
    sigdelset(&suspend_mask, SIGUSR1);

    // 4. המתן ל-SIGUSR1 באופן בטוח באמצעות sigsuspend:
    // הלולאה מבטיחה שאם ה-handler נקרא (לדוגמה, אם האות הגיע לפני ה-sigsuspend
    // במקרה של מימוש אחר, או wakeups כוזבים), נצא.
    while (!sigusr1_received) {
        printf("Child: Waiting for SIGUSR1...\n");
        // sigsuspend מבצע שתי פעולות באופן אטומי:
        // א. משנה את מסכת האותות למסכה שהועברה (suspend_mask, שבה SIGUSR1 אינו חסום).
        // ב. משעה את התהליך עד לקבלת אות שאינו חסום.
        // לאחר שהאות מטופל וה-handler חוזר, sigsuspend משחזר את מסכת האותות
        // שהייתה פעילה *לפני* הקריאה ל-sigsuspend (כלומר, SIGUSR1 שוב חסום).
        if (sigsuspend(&suspend_mask) == -1 && errno != EINTR) {
             perror("sigsuspend");
             exit(EXIT_FAILURE);
        }
    }

    // שחזור מסכת האותות המקורית שהייתה בתחילת child_process.
    // זהו ה-oldmask ששמרנו כאשר חסמנו לראשונה את SIGUSR1.
    if (sigprocmask(SIG_SETMASK, &oldmask, NULL) == -1) {
        perror("sigprocmask SETMASK");
        exit(EXIT_FAILURE);
    }
    printf("Child: SIGUSR1 handled and mask restored.\n");

    printf("Child: Exiting.\n");
}
```

**הסבר:**

הפתרון מבטיח טיפול בטוח ונכון באות `SIGUSR1` על ידי שימוש בפעולות אטומיות למניעת תנאי מרוץ (Race Conditions).

1.  **חסימה ראשונית (`sigprocmask`):** בתחילה, `SIGUSR1` נחסם. זה מבטיח שאם תהליך האב ישלח את האות מוקדם מהצפוי (לדוגמה, לפני שהבן סיים את עבודתו הקריטית), האות לא יטופל מיד אלא יישאר ממתין (pending). כך, העבודה הקריטית של הבן תתבצע ללא הפרעה.
2.  **עבודה קריטית (`critical_work()`):** בזמן זה, `SIGUSR1` חסום, והתהליך הבן יכול לבצע את משימותיו בבטחה.
3.  **המתנה בטוחה (`sigsuspend`):** לאחר סיום העבודה הקריטית, התהליך הבן מוכן לקבל את האות. כאן טמונה הנקודה הקריטית ביותר:
    *   **בעיית תנאי מרוץ עם `sigprocmask` + `pause()`:** אם היינו משתמשים בגישה של `sigprocmask(SIG_UNBLOCK, ...)` ואחריה `pause()`, היה עלול להיווצר תנאי מרוץ. אם האות `SIGUSR1` היה מגיע *מיד לאחר* ביטול החסימה שלו (על ידי `sigprocmask`) אך *לפני* הקריאה ל-`pause()`, ה-handler היה מטפל באות, ו-`pause()` היה ממתין ללא הגבלת זמן לאות נוסף שלעולם לא יגיע. התהליך הבן היה נתקע (Deadlock).
    *   **הפתרון עם `sigsuspend()`:** הפונקציה `sigsuspend()` פותרת את תנאי המרוץ הזה על ידי ביצוע שתי פעולות באופן אטומי: היא משנה את מסכת האותות של התהליך למסכה שבה `SIGUSR1` אינו חסום (כפי שהוגדרה ב-`suspend_mask`), ואז משעה את התהליך. רק כאשר `SIGUSR1` (או כל אות אחר שאינו חסום במסכה החדשה) מתקבל, התהליך מתעורר, וה-handler נקרא. לאחר שה-handler חוזר, `sigsuspend()` משחזר באופן אוטומטי את מסכת האותות שהייתה פעילה *לפני* הקריאה ל-`sigsuspend` (כלומר, `SIGUSR1` שוב חסום). זה מבטיח שהאות לא יחמוק בין ביטול החסימה להשעיה.
4.  **שחזור מסכה (`sigprocmask`):** בסיום, אנו משחזרים את מסכת האותות למצבה המקורי לפני שכלל התחלנו לטפל ב-`SIGUSR1` בתוך `child_process`. זוהי פרקטיקה טובה לשמור על ניקיון סביבת האותות.

**חשיבות פעולות אטומיות:** תנאי המרוץ שתיארנו מדגיש את החשיבות הקריטית של פעולות אטומיות בהקשר של טיפול באותות ובסנכרון תהליכים. כאשר יש רצף של פעולות שצריכות להתבצע יחד כדי להבטיח נכונות (כמו ביטול חסימה והמתנה לאות), חייבים להשתמש במנגנונים המבטיחים שהן יתבצעו כיחידה בלתי ניתנת להפרעה, כדי למנוע מצבים בלתי צפויים או קיפאון. `sigsuspend` הוא דוגמה מצוינת לפעולה אטומית כזו.

הפתרון כולל טיפול זהיר באותות `SIGCHLD` ו-`SIGINT` באמצעות `sigaction`, `sigprocmask` ו-`sigsuspend`.

**הסבר מפורט:**

1.  **מניעת מרוצי תזמון (Race Conditions) ואיבוד אותות:**
    *   **חסימת אותות מראש:** לפני קריאה ל-`fork` ולאורך כל הלולאה הראשית של האב, האותות `SIGCHLD` ו-`SIGINT` נחסמים באמצעות `sigprocmask(SIG_BLOCK, &blocked_mask, NULL)`. זה מבטיח שאם הבן יסיים את פעולתו במהירות רבה מיד לאחר ה-`fork`, האות `SIGCHLD` לא יאבד לפני שהאב מוכן לטפל בו. במקום זאת, האות יישאר 'ממתין' (pending) ויימסר ברגע שהאות יבוטל חסימתו. באופן דומה, `SIGINT` נחסם כדי לאפשר לאב שליטה מלאה על מתי הוא מגיב לאות זה.
    *   **שימוש ב-`volatile sig_atomic_t`:** דגלים גלובליים (`child_exited`, `sigint_received`) משמשים לתקשורת בין מטפלי האותות ללולאה הראשית. הם מוגדרים כ-`volatile` כדי למנוע אופטימיזציות קומפיילר שגויות, וכ-`sig_atomic_t` כדי להבטיח שקריאה וכתיבה אליהם הן פעולות אטומיות (כלומר, לא יופרעו על ידי אות באמצע העדכון).

2.  **טיפול אטומי בהמתנה לאותות עם `sigsuspend`:**
    *   הלולאה הראשית של האב משתמשת ב-`sigsuspend(&empty_mask)` כדי להמתין לאותות. הפעולה `sigsuspend` היא קריטית מכיוון שהיא מבצעת שתי פעולות באופן אטומי:
        א.  היא מחליפה את מסכת האותות הנוכחית של התהליך במסכה הנתונה (במקרה זה, `empty_mask`, שאינה חוסמת אף אות), ובכך מאפשרת לאותות `SIGCHLD` ו-`SIGINT` להימסר.
        ב.  היא משעה את התהליך עד שאחד מהאותות המותרים נמסר.
    *   כאשר אות נמסר ומטפל האות מסיים את פעולתו (ומעדכן את הדגלים הגלובליים), `sigsuspend` חוזרת, ומסכת האותות המקורית (שחוסמת את `SIGCHLD` ו-`SIGINT`) משוחזרת. זה מבטיח שהבדיקה והטיפול בדגלים (`child_exited`, `sigint_received`) וקריאה ל-`waitpid` מתבצעות כאשר האותות הללו חסומים, ומונע מרוצי תזמון נוספים בזמן הטיפול.

3.  **סדר טיפול באותות:**
    *   הלוגיקה בלולאה הראשית בודקת קודם כל את הדגל `child_exited`. אם הוא מוגדר, האב קורא ל-`waitpid` כדי לקצור את הבן. רק לאחר שהבן נקצר (`child_reaped` הופך ל-`1`), האב בודק את הדגל `sigint_received`.
    *   אם `SIGINT` התקבל אך הבן עדיין לא נקצר, האב מדפיס הודעה וחוזר להמתין ב-`sigsuspend`. הדגל `sigint_received` נשאר מוגדר, מה שמבטיח שהאב יגיב ל-`SIGINT` ברגע שהבן יטופל. זה מונע מהאב לצאת בטרם עת כפי שנדרש בשאלה.
    *   בתוך מטפלי האותות, נחסמים אותות אחרים באופן זמני (למשל, `SIGINT` במטפל `SIGCHLD`), כדי למנוע הפרעות ובעיות כניסה חוזרת (reentrancy) אם שני אותות יגיעו בו-זמנית או בסמיכות גבוהה.

**קוד C:**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <string.h>

// דגלים גלובליים לתקשורת בין מטפלי האותות ללולאה הראשית
volatile sig_atomic_t child_exited = 0;
volatile sig_atomic_t sigint_received = 0;

// מטפל אות עבור SIGCHLD
void child_handler(int signum) {
    child_exited = 1;
    printf("\n[Handler] SIGCHLD received. Child exited flag set.\n");
}

// מטפל אות עבור SIGINT
void sigint_handler(int signum) {
    sigint_received = 1;
    printf("\n[Handler] SIGINT received. SIGINT flag set.\n");
}

int main() {
    struct sigaction sa_chld, sa_int;
    sigset_t blocked_mask, empty_mask;
    pid_t pid;
    int child_reaped = 0;

    // 1. הגדרת מסכות אותות
    // blocked_mask: חוסמת SIGCHLD ו-SIGINT
    sigemptyset(&blocked_mask);
    sigaddset(&blocked_mask, SIGCHLD);
    sigaddset(&blocked_mask, SIGINT);

    // empty_mask: אינה חוסמת אף אות (לשימוש עם sigsuspend)
    sigemptyset(&empty_mask);

    // 2. הגדרת מטפל אות עבור SIGCHLD
    memset(&sa_chld, 0, sizeof(sa_chld));
    sa_chld.sa_handler = child_handler;
    // חוסמים את SIGINT בתוך מטפל ה-SIGCHLD כדי למנוע הפרעות
    sigaddset(&sa_chld.sa_mask, SIGINT);
    if (sigaction(SIGCHLD, &sa_chld, NULL) == -1) {
        perror("sigaction SIGCHLD");
        exit(EXIT_FAILURE);
    }

    // 3. הגדרת מטפל אות עבור SIGINT
    memset(&sa_int, 0, sizeof(sa_int));
    sa_int.sa_handler = sigint_handler;
    // חוסמים את SIGCHLD בתוך מטפל ה-SIGINT כדי למנוע הפרעות
    sigaddset(&sa_int.sa_mask, SIGCHLD);
    if (sigaction(SIGINT, &sa_int, NULL) == -1) {
        perror("sigaction SIGINT");
        exit(EXIT_FAILURE);
    }

    // 4. חסימת SIGCHLD ו-SIGINT בתהליך האב לפני ה-fork
    // זה מונע איבוד אותות אם הבן יסיים מהר מדי.
    if (sigprocmask(SIG_BLOCK, &blocked_mask, NULL) == -1) {
        perror("sigprocmask BLOCK");
        exit(EXIT_FAILURE);
    }
    printf("Parent: SIGCHLD and SIGINT are blocked.\n");

    // 5. יצירת תהליך בן
    pid = fork();

    if (pid == -1) {
        perror("fork");
        // ביטול חסימת אותות לפני יציאה במקרה של שגיאה
        sigprocmask(SIG_UNBLOCK, &blocked_mask, NULL);
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // קוד הבן
        printf("Child (%d): Starting work for 3 seconds...\n", getpid());
        sleep(3);
        printf("Child (%d): Exiting.\n", getpid());
        exit(EXIT_SUCCESS);
    } else { // קוד האב
        printf("Parent (%d): Child created with PID %d.\n", getpid(), pid);

        while (1) {
            // 6. בדיקת דגלים וטיפול באותות כאשר SIGCHLD ו-SIGINT חסומים
            if (child_exited) {
                waitpid(pid, NULL, 0); // קצירת הבן
                printf("Parent: Child %d reaped.\n", pid);
                child_reaped = 1;
                child_exited = 0; // איפוס הדגל
            }

            if (child_reaped && sigint_received) {
                printf("Parent: SIGINT received AND child reaped. Exiting cleanly.\n");
                break; // יציאה מהלולאה
            } else if (sigint_received && !child_reaped) {
                printf("Parent: SIGINT received, but child not yet reaped. Continuing to wait for child.\n");
                // לא מאפסים את sigint_received. נמשיך לבדוק אותו עד שהבן יקצר.
            }

            printf("Parent: Waiting for signals (child_reaped=%d, sigint_received=%d)...\n", child_reaped, sigint_received);
            fflush(stdout);

            // 7. המתנה אטומית לאותות באמצעות sigsuspend
            // sigsuspend מחליפה באופן זמני את מסכת האותות הנוכחית ב-empty_mask
            // (המאפשרת את קבלת SIGCHLD ו-SIGINT), ומשעה את התהליך. כאשר אות נמסר,
            // המטפל שלו מופעל, ולאחר מכן מסכת האותות המקורית (blocked_mask) משוחזרת.
            sigsuspend(&empty_mask);
        }

        // 8. ביטול חסימת אותות לפני יציאה מסודרת
        if (sigprocmask(SIG_UNBLOCK, &blocked_mask, NULL) == -1) {
            perror("sigprocmask UNBLOCK");
            exit(EXIT_FAILURE);
        }
        printf("Parent: Unblocked SIGCHLD and SIGINT. Exiting.\n");
    }

    return 0;
}
```

