נתון קטע קוד C המממש תקשורת בין תהליך אב לתהליך בן. תהליך האב יוצר תהליך בן, והבן מבצע פעולה כלשהי (מודגמת על ידי `sleep`), שולח אות `SIGUSR1` לאב, ולאחר מכן יוצא. תהליך האב אמור לטפל באות `SIGUSR1` על ידי הגדלת מונה גלובלי, להמתין לסיום תהליך הבן, ולהדפיס את הערך הסופי של המונה.

הקוד הנתון אינו כתוב בצורה חסינה ויציבה, ועלול להציג התנהגות שגויה או לא צפויה במצבים מסוימים.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>

volatile int sig_count = 0; // מונה לקבלת אותות SIGUSR1

void sigusr1_handler(int signo) {
    sig_count++;
    printf("Parent: SIGUSR1 received! Current count: %d\n", sig_count); 
}

int main() {
    pid_t pid;

    // הגדרת מטפל לאות SIGUSR1
    signal(SIGUSR1, sigusr1_handler); 

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(1);
    } else if (pid == 0) { // תהליך הבן
        printf("Child (%d): Starting work...\n", getpid());
        sleep(2); // מדמה עבודה
        printf("Child (%d): Sending SIGUSR1 to parent (%d)...\n", getpid(), getppid());
        kill(getppid(), SIGUSR1);
        printf("Child (%d): Exiting.\n", getpid());
        exit(0);
    } else { // תהליך האב
        printf("Parent (%d): Child created with PID %d. Waiting for child...\n", getpid(), pid);

        int status;
        waitpid(pid, &status, 0); 

        printf("Parent (%d): Child %d terminated. Final SIGUSR1 count: %d\n", getpid(), pid, sig_count);
    }

    return 0;
}
```

**שאלות:**
1.  זהו ותארו לפחות שתי בעיות קריטיות בקוד הנתון, והסבירו מדוע הן בעייתיות.
2.  תקנו את הקוד כך שיפעל באופן אמין ונכון. יש להשתמש ב-`sigaction` ובדגלים המתאימים. הסבירו את התיקונים שביצעתם.

solution.explanation:
חלק א': זיהוי בעיות

1.  **שימוש ב-`signal()` במקום `sigaction()`:** הפונקציה `signal()` היא פונקציה מורשת (legacy) בעלת התנהגות לא אמינה ולא ניתנת לחיזוי במערכות יוניקס מודרניות. לדוגמה, במערכות מסוימות, לאחר קבלת אות, המטפל מתאפס (מוגדר מחדש כ-`SIG_DFL`), מה שמחייב הגדרה חוזרת של המטפל בתוך המטפל עצמו, וזה יוצר חלון זמן שבו אותות נוספים מאותו סוג לא יטופלו או יגרמו לסיום התהליך. `sigaction()` מספקת שליטה מדויקת יותר על התנהגות האות, כולל מסכות אותות בתוך המטפל, ודגלים כמו `SA_RESTART` ו-`SA_SIGINFO`, והיא הדרך המועדפת והאמינה לטיפול באותות.

2.  **קריאה ל-`printf()` בתוך מטפל אותות (Signal Handler):** הפונקציה `printf()` אינה "async-signal-safe". המשמעות היא שהיא אינה מובטחת לפעול בצורה תקינה ובטוחה כאשר היא נקראת מתוך מטפל אותות, במיוחד אם הקריאה לאות קוטעת קריאה אחרת ל-`printf()` או לפונקציית I/O אחרת במקביל בחוט הראשי. קריאה כזו עלולה להוביל למצבי מירוץ, לנעילה (deadlock) אם `printf` מנסה לרכוש מנעול שנתפס כבר על ידי החוט הראשי, או לפלט משובש/לא שלם. כלל אצבע הוא שמטפל אותות צריך לבצע את המינימום ההכרחי של פעולות, ורק כאלו שהן async-signal-safe (כמו הגדרת דגל `volatile sig_atomic_t` או כתיבה ל-pipe).

3.  **הפרעה לקריאת מערכת `waitpid()`:** קריאת המערכת `waitpid()` יכולה להיות מופרעת על ידי אות. אם אות `SIGUSR1` מגיע בזמן ש-`waitpid()` חוסמת, הפונקציה `waitpid()` תחזור עם ערך `EINTR` ב-`errno` (ותחזיר -1), במקום להמתין לסיום הבן. הקוד הנתון אינו מטפל במצב זה, ולכן אם `waitpid()` מופרעת, התהליך האב ימשיך הלאה כאילו הבן סיים (או ייתקע בתלות בהתנהגות ברירת המחדל של `signal`), מה שעלול להוביל להדפסת המונה לפני שהבן באמת סיים, או שהבן יהפוך ל"זומבי" אם האב לא יקרא ל-`waitpid` שוב. יש לטפל בהפרעות אלה באופן מפורש.

חלק ב': קוד מתוקן והסברים

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <errno.h> // נדרש עבור errno

// נשתמש ב-sig_atomic_t עבור משתנים שמשותפים בין מטפל אותות לחוט הראשי.
// זה מבטיח שהגישה למשתנה תהיה אטומית ולא תיקטע באמצע על ידי אות.
volatile sig_atomic_t sig_count = 0; 

void sigusr1_handler(int signo) {
    sig_count++;
    // נמנעים מקריאה ל-printf בתוך המטפל, מכיוון שזו אינה פונקציה async-signal-safe.
    // הפעולה היחידה הבטוחה כאן היא עדכון משתנה sig_atomic_t.
}

int main() {
    pid_t pid;
    struct sigaction sa;

    // 1. הגדרת מטפל לאות SIGUSR1 באמצעות sigaction()
    // זה מבטיח טיפול אמין באותות.
    sa.sa_handler = sigusr1_handler;
    sigemptyset(&sa.sa_mask); // מנקה את מסכת האותות - לא חוסם אותות נוספים בזמן הטיפול.
    sa.sa_flags = 0; // אין צורך בדגלים מיוחדים כמו SA_RESTART עבור מטפל זה,
                     // כיוון שהוא רק מעדכן מונה. (SA_RESTART רלוונטי יותר לקריאות מערכת)
    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction SIGUSR1 failed");
        exit(1);
    }

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(1);
    } else if (pid == 0) { // תהליך הבן
        printf("Child (%d): Starting work...\n", getpid());
        sleep(2); // מדמה עבודה
        printf("Child (%d): Sending SIGUSR1 to parent (%d)...\n", getpid(), getppid());
        kill(getppid(), SIGUSR1);
        printf("Child (%d): Exiting.\n", getpid());
        exit(0);
    } else { // תהליך האב
        printf("Parent (%d): Child created with PID %d. Waiting for child...\n", getpid(), pid);

        // 3. טיפול אמין בהפרעות לקריאת המערכת waitpid()
        // נשתמש בלולאה כדי להבטיח ש-waitpid() תמתין לילד עד לסיומו,
        // גם אם היא מופרעת על ידי אות (SIGUSR1 במקרה זה).
        int status;
        int result;
        do {
            result = waitpid(pid, &status, 0);
            if (result == -1 && errno == EINTR) {
                printf("Parent (%d): waitpid interrupted by signal, retrying...\n", getpid());
            } else if (result == -1) {
                perror("waitpid failed"); // שגיאה אמיתית שאינה EINTR
                exit(1);
            }
        } while (result == -1 && errno == EINTR);

        printf("Parent (%d): Child %d terminated. Final SIGUSR1 count: %d\n", getpid(), pid, sig_count);
    }

    return 0;
}
```

