#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/mman.h>

int main() {
    int* shared_data = (int*)mmap(NULL, sizeof(int) * 10, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (shared_data == MAP_FAILED) {
        perror("mmap failed");
        return 1;
    }

    for (int i = 0; i < 10; ++i) {
        shared_data[i] = i + 1; // Initialize with 1, 2, ..., 10
    }

    pid_t pid1 = fork();
    if (pid1 == -1) { perror("fork failed"); return 1; }

    if (pid1 == 0) { // Child 1
        shared_data[0] = 100; // Modify index 0
        exit(0);
    }

    pid_t pid2 = fork();
    if (pid2 == -1) { perror("fork failed"); return 1; }

    if (pid2 == 0) { // Child 2
        shared_data[1] = 200; // Modify index 1
        exit(0);
    }

    // Parent waits for children to complete
    waitpid(pid1, NULL, 0);
    waitpid(pid2, NULL, 0);

    printf("Parent process: shared_data[0]=%d, shared_data[1]=%d\n", shared_data[0], shared_data[1]);

    munmap(shared_data, sizeof(int) * 10);
    return 0;
}
```

