int compare_and_swap(int* val_ptr, int expected_val, int new_val) {
    if (*val_ptr == expected_val) {
        *val_ptr = new_val;
        return 1; // Success
    }
    return 0; // Failure
}

typedef struct _klock {
    int acquired_count; // המונה עבור תפיסות מוצלחות
    int K_limit;        // המספר המרבי של תפיסות מותרות
} KLock;

void init_k_lock(KLock *lock, int K_limit) {
    lock->acquired_count = 0;
    lock->K_limit = K_limit;
}

int lock_k(KLock *lock) {
    int current_val;
    do {
        current_val = lock->acquired_count; // קריאת הערך הנוכחי (לא אטומי, אך משמש כערך צפוי ל-CAS)
        if (current_val >= lock->K_limit) {
            return 0; // המונה כבר הגיע ל-K_limit או עבר אותו, לא ניתן לתפוס את המנעול
