        // נסה לקדם את המונה באופן אטומי אם הערך הנוכחי לא השתנה
    } while (!compare_and_swap(&lock->acquired_count, current_val, current_val + 1));

    return 1; // המנעול נתפס בהצלחה
}

void destroy_k_lock(KLock *lock) {
