int compare_and_swap_double(int* ptr1, int expected1, int new1, int* ptr2, int expected2, int new2) {
    // Atomically checks if *ptr1 == expected1 AND *ptr2 == expected2.
    // If true, sets *ptr1 = new1 and *ptr2 = new2, and returns 1.
    // If false, makes no changes and returns 0.
    // (This is a conceptual description for the atomic hardware instruction)
    if (*ptr1 == expected1 && *ptr2 == expected2) {
        *ptr1 = new1;
        *ptr2 = new2;
        return 1;
    }
    return 0;
}

