pthread_mutex_t mutex_A = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex_B = PTHREAD_MUTEX_INITIALIZER;

void* perform_task(void* arg) {
    int thread_id = *(int*)arg;

    if (thread_id % 2 == 0) { // Even threads acquire A then B
        pthread_mutex_lock(&mutex_A);
        printf("Thread %d acquired mutex_A\n", thread_id);
        // Simulate some work or delay
        // usleep(1000); // For demonstrating deadlock in real time
        pthread_mutex_lock(&mutex_B);
        printf("Thread %d acquired mutex_B\n", thread_id);
    } else { // Odd threads acquire B then A
        pthread_mutex_lock(&mutex_B);
        printf("Thread %d acquired mutex_B\n", thread_id);
        // Simulate some work or delay
        // usleep(1000); // For demonstrating deadlock in real time
        pthread_mutex_lock(&mutex_A);
        printf("Thread %d acquired mutex_A\n", thread_id);
    }

    printf("Thread %d acquired both resources. Performing task...\n", thread_id);
    // Critical section: Use Resource A and Resource B
    // ...
    printf("Thread %d finished task. Releasing resources.\n", thread_id);

    // Release in reverse order of acquisition for safety
    if (thread_id % 2 == 0) {
        pthread_mutex_unlock(&mutex_B);
        pthread_mutex_unlock(&mutex_A);
    } else {
        pthread_mutex_unlock(&mutex_A);
        pthread_mutex_unlock(&mutex_B);
    }
    return NULL;
}

solution.explanation:
א. כן, קיימת סכנה מובהקת לקיפאון (deadlock) במערכת. הקיפאון נובע מכך שחוטים רוכשים את המנעולים `mutex_A` ו-`mutex_B` בסדר לא עקבי. תנאי הקיפאון של Coffman (או Holt) מתקיימים:
1.  **מניעה הדדית (Mutual Exclusion):** כל מנעול מגן על משאב ורק חוט אחד יכול להחזיק בו בו-זמנית.
2.  **החזק והמתן (Hold and Wait):** חוט יכול להחזיק במנעול אחד (למשל `mutex_A`) ולהמתין למנעול אחר (למשל `mutex_B`).
3.  **אי-הפקעה (No Preemption):** מנעול שנרכש על ידי חוט לא יכול להילקח ממנו בכוח.
4.  **המתנה מעגלית (Circular Wait):** זהו התנאי המרכזי שמוביל לקיפאון במקרה זה.

**תרחיש תזמון ספציפי לקיפאון:**
נניח שיש לנו שני חוטים: `Thread 0` (מזהה זוגי) ו-`Thread 1` (מזהה אי-זוגי).
1.  `Thread 0` מתחיל לרוץ ורוכש את `mutex_A`.
    *   `printf("Thread 0 acquired mutex_A\n", 0);`
2.  בשלב זה, מתבצע מיתוג הקשר (context switch) ל-`Thread 1`.
3.  `Thread 1` מתחיל לרוץ ורוכש את `mutex_B`.
    *   `printf("Thread 1 acquired mutex_B\n", 1);`
4.  `Thread 1` מנסה כעת לרכוש את `mutex_A`. אך `mutex_A` מוחזק על ידי `Thread 0`. לכן, `Thread 1` נחסם וממתין לשחרור `mutex_A`.
5.  מתבצע מיתוג הקשר בחזרה ל-`Thread 0`.
6.  `Thread 0` מנסה כעת לרכוש את `mutex_B`. אך `mutex_B` מוחזק על ידי `Thread 1`. לכן, `Thread 0` נחסם וממתין לשחרור `mutex_B`.

בנקודה זו, `Thread 0` מחזיק ב-`mutex_A` וממתין ל-`mutex_B` (המוחזק על ידי `Thread 1`), בעוד ש-`Thread 1` מחזיק ב-`mutex_B` וממתין ל-`mutex_A` (המוחזק על ידי `Thread 0`). נוצרה שרשרת המתנה מעגלית, ושני החוטים חסומים לצמיתות – המערכת נמצאת בקיפאון.

ב. כדי למנוע קיפאון, יש לשבור את תנאי ההמתנה המעגלית. הדרך הנפוצה והפשוטה ביותר לעשות זאת היא לאכוף סדר רכישה עקבי של המנעולים על ידי כל החוטים. כלומר, כל החוטים ירכשו תמיד את `mutex_A` ואז את `mutex_B`, או לחלופין, את `mutex_B` ואז את `mutex_A`. כל עוד כולם מצייתים לאותו סדר, לא תיווצר המתנה מעגלית.

**פתרון מתוקן (אכיפת סדר רכישה: תמיד A ואז B):**
```c
#include <pthread.h>
#include <stdio.h>

pthread_mutex_t mutex_A = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex_B = PTHREAD_MUTEX_INITIALIZER;

void* perform_task_fixed(void* arg) {
    int thread_id = *(int*)arg;

    // All threads now acquire mutex_A first, then mutex_B
    pthread_mutex_lock(&mutex_A);
    printf("Thread %d acquired mutex_A\n", thread_id);
    pthread_mutex_lock(&mutex_B);
    printf("Thread %d acquired mutex_B\n", thread_id);

    printf("Thread %d acquired both resources. Performing task...\n", thread_id);
    // Critical section: Use Resource A and Resource B
    // ...
    printf("Thread %d finished task. Releasing resources.\n", thread_id);

    // Release in reverse order of acquisition
    pthread_mutex_unlock(&mutex_B);
    pthread_mutex_unlock(&mutex_A);
    return NULL;
}
```

**הסבר לתיקון:**
התיקון מבטל את התלות ב-`thread_id` לקביעת סדר רכישת המנעולים. כעת, כל חוט, ללא קשר למזהה שלו, ינסה לרכוש קודם את `mutex_A` ולאחר מכן את `mutex_B`. 
אם `Thread X` מחזיק ב-`mutex_A` וממתין ל-`mutex_B`, אף חוט אחר (`Thread Y`) לא יכול להחזיק ב-`mutex_B` ולהמתין ל-`mutex_A`, מכיוון ש-`Thread Y` ינסה קודם לרכוש את `mutex_A` (שמוחזק על ידי `Thread X`) וייחסם. לכן, לא יכולה להיווצר שרשרת המתנה מעגלית, והקיפאון נמנע.
פתרון זה פשוט ויעיל, ומבטיח שהמערכת תישאר חופשית מקיפאון.

