#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_RESOURCES_GLOBAL 100 // Maximum possible resources

// Global variables
int resource_state[MAX_RESOURCES_GLOBAL]; // 0 = free, 1 = locked
int NUM_RESOURCES; // Actual number of resources in use
pthread_mutex_t pool_mutex;
pthread_cond_t pool_cond;

// Atomic Compare And Swap (conceptual)
// Returns the value *before* the operation. If it matches 'expected', *ptr is updated to 'desired'.
int atomic_cas(int* ptr, int expected, int desired) {
    int actual_old_value = *ptr;
    if (actual_old_value == expected) {
        *ptr = desired;
    }
    return actual_old_value;
}

void init_resource_manager(int num_resources) {
    if (num_resources <= 0 || num_resources > MAX_RESOURCES_GLOBAL) {
        fprintf(stderr, "Invalid number of resources.\n");
        exit(EXIT_FAILURE);
    }
    NUM_RESOURCES = num_resources;
    for (int i = 0; i < NUM_RESOURCES; ++i) {
        resource_state[i] = 0; // All resources are initially free
    }
    pthread_mutex_init(&pool_mutex, NULL);
    pthread_cond_init(&pool_cond, NULL);
}

void acquire_resources(int k, int* acquired_indices) {
    if (k <= 0 || k > NUM_RESOURCES) {
        fprintf(stderr, "Invalid number of resources to acquire.\n");
        return;
    }

    int temp_acquired_indices[k]; // Temporarily store indices

    pthread_mutex_lock(&pool_mutex); // Lock for initial search and condition waiting

    while (true) {
        int found_indices[k];
        int found_count = 0;

        // 1. Find k free resources under the protection of pool_mutex
        for (int i = 0; i < NUM_RESOURCES && found_count < k; ++i) {
            if (resource_state[i] == 0) {
                found_indices[found_count++] = i;
            }
        }

        if (found_count < k) {
            // Not enough resources currently free. Wait.
            pthread_cond_wait(&pool_cond, &pool_mutex);
            continue; // Re-evaluate after waking up
        }

        // Enough potential resources found.
        // Release pool_mutex before attempting CAS to allow concurrency
        // and prevent deadlocks if CAS takes time or other threads need pool_mutex.
        pthread_mutex_unlock(&pool_mutex);

        // 2. Attempt to atomically lock the identified resources using CAS
        bool all_locked = true;
        int current_successful_cas = 0;
        for (int i = 0; i < k; ++i) {
            int resource_idx = found_indices[i];
            if (atomic_cas(&resource_state[resource_idx], 0, 1) == 0) {
                // Successfully locked this specific resource
                temp_acquired_indices[current_successful_cas++] = resource_idx;
            } else {
                // Failed to lock this resource (another thread acquired it between search and CAS)
                all_locked = false;
                break; // Stop trying to acquire more
            }
        }

        if (all_locked) {
            // All k resources successfully acquired.
            for (int i = 0; i < k; ++i) {
                acquired_indices[i] = temp_acquired_indices[i];
            }
            // No need to re-lock pool_mutex as we are done.
            // (The initial lock was released before CAS attempts).
            return; // Success
        } else {
            // Failed to acquire all k resources.
            // Release any resources that were successfully locked in this attempt.
            for (int i = 0; i < current_successful_cas; ++i) {
                atomic_cas(&resource_state[temp_acquired_indices[i]], 1, 0); // Release it
            }
            // Re-acquire pool_mutex to go back to the top of the loop and wait.
            pthread_mutex_lock(&pool_mutex);
            // This `pthread_cond_wait` is crucial for avoiding busy-waiting.
            pthread_cond_wait(&pool_cond, &pool_mutex);
            // After `pthread_cond_wait` returns, `pool_mutex` is re-acquired, loop continues.
        }
    } // End of while(true)
}

void release_resources(int k, int* released_indices) {
    if (k <= 0 || k > NUM_RESOURCES) {
        fprintf(stderr, "Invalid number of resources to release.\n");
        return;
    }

    for (int i = 0; i < k; ++i) {
        int resource_idx = released_indices[i];
        if (resource_idx < 0 || resource_idx >= NUM_RESOURCES) {
            fprintf(stderr, "Attempted to release invalid resource index %d.\n", resource_idx);
            continue;
        }
        // Atomically set resource state to free
        if (atomic_cas(&resource_state[resource_idx], 1, 0) != 1) {
            // This indicates a logical error, resource was not locked by this thread or was already free
            // In a real system, you might log this or assert, but for exam, it's a warning.
        }
    }

    pthread_mutex_lock(&pool_mutex); // Lock to signal safely
    pthread_cond_broadcast(&pool_cond); // Notify all waiting threads that resources might be available
    pthread_mutex_unlock(&pool_mutex);
}

