typedef struct _cl_lock {
    int k_limit; // Max concurrent holders
    int m_limit; // Max total acquisitions

    volatile int current_holders;
    volatile int total_acquisitions;
    volatile int broken_flag; // 1 if M_limit reached, 0 otherwise

    volatile int internal_lock_state; // 0: unlocked, 1: locked
} CLock;

void init(CLock* lock, int K, int M) {
    lock->k_limit = K;
    lock->m_limit = M;
    lock->current_holders = 0;
    lock->total_acquisitions = 0;
    lock->broken_flag = 0;
    lock->internal_lock_state = 0;
}

int lock(CLock* lock_obj) {
    // Acquire internal spinlock
    while (compare_and_swap(&lock_obj->internal_lock_state, 0, 1) == 0) {
        // Spin or yield (for real-world, might add sched_yield() or backoff)
    }

    // Check if the lock is already broken globally
    if (lock_obj->broken_flag == 1) {
        lock_obj->internal_lock_state = 0; // Release internal spinlock
        return 0;
    }

    // Check if total acquisitions limit has been reached or will be reached by this acquisition
    if (lock_obj->total_acquisitions >= lock_obj->m_limit) {
        lock_obj->broken_flag = 1; // Mark as broken
        lock_obj->internal_lock_state = 0; // Release internal spinlock
        return 0;
    }

    // Check if concurrent holders limit has been reached
    if (lock_obj->current_holders < lock_obj->k_limit) {
        // Acquire lock slot
        lock_obj->current_holders++;
        lock_obj->total_acquisitions++;

        // If this acquisition reached the total limit, mark as broken for future attempts
        if (lock_obj->total_acquisitions >= lock_obj->m_limit) {
            lock_obj->broken_flag = 1;
        }

        lock_obj->internal_lock_state = 0; // Release internal spinlock
        return 1; // Successfully acquired
    } else {
        // Concurrent limit reached, cannot acquire
        lock_obj->internal_lock_state = 0; // Release internal spinlock
        return 0; // Failed to acquire
    }
}

void unlock(CLock* lock_obj) {
    // Acquire internal spinlock
    while (compare_and_swap(&lock_obj->internal_lock_state, 0, 1) == 0) {
        // Spin or yield
    }

    // Decrement current holders, only if greater than 0 for safety
    if (lock_obj->current_holders > 0) {
        lock_obj->current_holders--;
    }

    lock_obj->internal_lock_state = 0; // Release internal spinlock
}

void destroy(CLock* lock) {
    // No dynamically allocated memory within the struct itself to free.
    // If the CLock object itself was dynamically allocated, it would be freed by the caller.
}

solution.explanation:
חלק 1: תרחיש קיפאון

קיפאון יכול להיווצר אם מתקיימים ארבעת התנאים הבאים בו-זמנית:
1.  **מניעה הדדית (Mutual Exclusion):** מתקיים. כל משאב יכול להיות מוחזק על ידי תהליכון אחד בלבד בכל רגע נתון.
2.  **החזק והמתן (Hold and Wait):** מתקיים. תהליכון יכול להחזיק במשאב אחד (או יותר) ולחכות למשאב נוסף.
3.  **אי-הפקעה (No Preemption):** מתקיים. משאבים אינם ניתנים להפקעה מתהליכון שמחזיק בהם; עליו לשחרר אותם מרצונו.
4.  **המתנה מעגלית (Circular Wait):** זהו התנאי שאנו יכולים ליצור כדי להוביל לקיפאון.

תרחיש לדוגמה:
נניח שיש לנו 3 תהליכונים (T1, T2, T3) ו-3 משאבים (R0, R1, R2).
*   T1 זקוק ל-R0 ו-R1.
*   T2 זקוק ל-R1 ו-R2.
*   T3 זקוק ל-R2 ו-R0.

רצף פעולות שיוביל לקיפאון:
1.  T1 רוכש את R0: `pthread_mutex_lock(&resources[0]);`
2.  T2 רוכש את R1: `pthread_mutex_lock(&resources[1]);`
3.  T3 רוכש את R2: `pthread_mutex_lock(&resources[2]);`
   (בשלב זה, כל תהליכון מחזיק משאב אחד ומוכן לבקש את השני).
4.  T1 מנסה לרכוש את R1: `pthread_mutex_lock(&resources[1]);` - T1 נחסם כי R1 מוחזק על ידי T2.
5.  T2 מנסה לרכוש את R2: `pthread_mutex_lock(&resources[2]);` - T2 נחסם כי R2 מוחזק על ידי T3.
6.  T3 מנסה לרכוש את R0: `pthread_mutex_lock(&resources[0]);` - T3 נחסם כי R0 מוחזק על ידי T1.

כעת נוצרה המתנה מעגלית: T1 מחכה ל-R1 שמוחזק על ידי T2, T2 מחכה ל-R2 שמוחזק על ידי T3, ו-T3 מחכה ל-R0 שמוחזק על ידי T1. אף תהליכון לא יכול להמשיך, וכל המערכת נמצאת בקיפאון.

חלק 2: מימוש למניעת קיפאון

כדי למנוע קיפאון, נשבור את תנאי "המתנה מעגלית" על ידי אכיפת סדר גלובלי לרכישת משאבים. גישה נפוצה היא להקצות סדר מספרי לכל המשאבים (שהוא כבר קיים במקרה זה - לפי מזהה המשאב), ולדרוש מכל התהליכונים לרכוש משאבים לפי סדר זה. כלומר, תהליכון תמיד ירכוש את המשאב בעל המזהה הקטן יותר תחילה, ורק לאחר מכן את המשאב בעל המזהה הגדול יותר.

מבנה הנתונים:
נצטרך מערך של mutexes, אחד לכל משאב.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h> // For min/max logic or just conditional assignment

// Assume M is defined globally or passed somehow
#define M 5 // Example: 5 resources

pthread_mutex_t resources[M]; // Array of mutexes, one for each resource

// Initialize all mutexes
void init_resource_system() {
    for (int i = 0; i < M; i++) {
        pthread_mutex_init(&resources[i], NULL);
    }
}

// Destroy all mutexes
void destroy_resource_system() {
    for (int i = 0; i < M; i++) {
        pthread_mutex_destroy(&resources[i]);
    }
}

// Function to acquire two distinct resources, preventing deadlocks
void acquire_two_resources(int res1_id, int res2_id) {
    if (res1_id == res2_id) {
        fprintf(stderr, "Error: Cannot acquire the same resource twice.\n");
        return;
    }
    if (res1_id < 0 || res1_id >= M || res2_id < 0 || res2_id >= M) {
        fprintf(stderr, "Error: Invalid resource ID.\n");
        return;
    }

    // Enforce an ordering: always acquire the resource with the smaller ID first
    int first_res = (res1_id < res2_id) ? res1_id : res2_id;
    int second_res = (res1_id > res2_id) ? res1_id : res2_id;

    pthread_mutex_lock(&resources[first_res]);
    pthread_mutex_lock(&resources[second_res]);
}

// Function to release two distinct resources
void release_two_resources(int res1_id, int res2_id) {
    if (res1_id == res2_id) {
        fprintf(stderr, "Error: Cannot release the same resource twice.\n");
        return;
    }
    if (res1_id < 0 || res1_id >= M || res2_id < 0 || res2_id >= M) {
        fprintf(stderr, "Error: Invalid resource ID.\n");
        return;
    }

    // Release in reverse order of acquisition for robustness, or any order once both are held
    int first_res = (res1_id < res2_id) ? res1_id : res2_id;
    int second_res = (res1_id > res2_id) ? res1_id : res2_id;

    pthread_mutex_unlock(&resources[second_res]);
    pthread_mutex_unlock(&resources[first_res]);
}
```

הסבר:
על ידי אכיפת הסדר הגלובלי (תמיד לרכוש קודם את המשאב בעל המזהה הקטן יותר), אנו מבטיחים שלא ייתכן מצב של המתנה מעגלית. אם תהליכון T1 מחכה למשאב Rj שמוחזק על ידי T2, ו-T2 מחכה למשאב Rk שמוחזק על ידי T3, וכן הלאה, הרי שבהכרח:
*   T1 רוכש Ri, ממתין ל-Rj. לפי הכלל, Ri < Rj.
*   T2 רוכש Rj, ממתין ל-Rk. לפי הכלל, Rj < Rk.
*   ...
*   Tn רוכש Rx, ממתין ל-Ry. לפי הכלל, Rx < Ry.
*   אם הייתה המתנה מעגלית, אז התהליכון האחרון בשרשרת היה צריך להמתין למשאב שמוחזק על ידי התהליכון הראשון. למשל, Tn ממתין ל-Ri שמוחזק על ידי T1. אבל אז היינו מקבלים Ry < Ri.
    הדבר יוצר סתירה: Ri < Rj < Rk < ... < Rx < Ry < Ri. 
    מכיוון שאי-שוויון זה בלתי אפשרי, המתנה מעגלית אינה יכולה להיווצר. 
    פתרון זה מאפשר מקסימום מקביליות, שכן תהליכונים יכולים להמשיך לעבוד כל עוד הם אינם מתחרים על אותו משאב או על משאבים שהסדר שלהם חוסם אותם.

content.text:
נתון מימוש (חלקי) של מנגנון סנכרון "קוראים-כותבים" (Readers-Writers Lock) בשפת C/C++, המיועד להגן על משאב משותף. המנגנון מאפשר למספר קוראים לגשת למשאב במקביל, אך רק לכותב אחד לגשת למשאב בבלעדיות בכל רגע נתון. המטרה העיקרית של מימוש זה היא למנוע הרעבה של כותבים (Writer Starvation), כלומר, להבטיח שכותבים הממתינים יזכו לגישה למשאב תוך זמן סביר.

```c
#include <pthread.h> // Assume pthreads library is available

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t readers_q;
    pthread_cond_t writers_q;
    int readers_active; // Number of active readers
    int writers_active; // 0 or 1
    int writers_waiting; // Number of writers waiting
} rw_lock_t;

void rw_init(rw_lock_t *rw) {
    pthread_mutex_init(&rw->lock, NULL);
    pthread_cond_init(&rw->readers_q, NULL);
    pthread_cond_init(&rw->writers_q, NULL);
    rw->readers_active = 0;
    rw->writers_active = 0;
    rw->writers_waiting = 0;
}

void rw_destroy(rw_lock_t *rw) {
    pthread_mutex_destroy(&rw->lock);
    pthread_cond_destroy(&rw->readers_q);
    pthread_cond_destroy(&rw->writers_q);
}

void rw_read_lock(rw_lock_t *rw) {
    pthread_mutex_lock(&rw->lock);
    while (rw->writers_active > 0 || rw->writers_waiting > 0) {
        pthread_cond_wait(&rw->readers_q, &rw->lock);
    }
    rw->readers_active++;
    pthread_mutex_unlock(&rw->lock);
}

void rw_read_unlock(rw_lock_t *rw) {
    pthread_mutex_lock(&rw->lock);
    rw->readers_active--;
    if (rw->readers_active == 0) {
        pthread_cond_signal(&rw->writers_q);
    }
    pthread_mutex_unlock(&rw->lock);
}

void rw_write_lock(rw_lock_t *rw) {
    pthread_mutex_lock(&rw->lock);
    rw->writers_waiting++;
    while (rw->readers_active > 0 || rw->writers_active > 0) {
        pthread_cond_wait(&rw->writers_q, &rw->lock);
    }
    rw->writers_waiting--;
    rw->writers_active = 1;
    pthread_mutex_unlock(&rw->lock);
}

void rw_write_unlock(rw_lock_t *rw) {
    pthread_mutex_lock(&rw->lock);
    rw->writers_active = 0;
    if (rw->writers_waiting > 0) {
        pthread_cond_signal(&rw->writers_q);
    } else {
        // שימו לב לשורה זו
        pthread_cond_signal(&rw->readers_q);
    }
    pthread_mutex_unlock(&rw->lock);
}
```

1.  האם המימוש מקיים מניעה הדדית (Mutual Exclusion) עבור כותבים? האם הוא מאפשר קריאה מקבילית? נמקו.
2.  האם המימוש חופשי מקיפאון (Deadlock-free)? נמקו.
3.  האם המימוש מבטיח אי-הרעבה (Starvation-free) לכותבים? נמקו.
4.  האם המימוש מבטיח אי-הרעבה (Starvation-free) לקוראים? נמקו.
5.  אם זיהיתם כשל כלשהו בסעיפים הקודמים (במיוחד בהיבטי אי-הרעבה או קיפאון), תקנו את המימוש באופן שיפתור את הכשל, תוך שמירה על המטרה המקורית למנוע הרעבה של כותבים, ונסחו מחדש את הקוד המתוקן.

solution.explanation:
1.  **מניעה הדדית וקריאה מקבילית:**
    *   **מניעה הדדית לכותבים:** כן, המימוש מבטיח מניעה הדדית לכותבים. המשתנה `writers_active` יכול להיות 0 או 1 בלבד, וכותב יכול להיכנס רק כאשר `writers_active` הוא 0 וגם `readers_active` הוא 0. כל כותב ממתין ב-`while (rw->readers_active > 0 || rw->writers_active > 0)` עד לתנאים אלה.
    *   **קריאה מקבילית:** כן, המימוש מאפשר למספר קוראים לגשת למשאב במקביל. קוראים מגדילים את `readers_active` ויכולים להיכנס כל עוד אין כותב פעיל (`writers_active == 0`) ואין כותבים ממתינים (`writers_waiting == 0`). אין מגבלה על מספר הקוראים הפעילים.

2.  **חופש מקיפאון (Deadlock-free):**
    *   כן, המימוש נראה חופשי מקיפאון.
        *   כותב לעולם לא יחזיק את המוטקס (`rw->lock`) בזמן שהוא ממתין על משתנה תנאי (`writers_q`). הוא משחרר את המוטקס לפני ההמתנה.
        *   קורא לעולם לא יחזיק את המוטקס בזמן שהוא ממתין על משתנה תנאי (`readers_q`). הוא משחרר את המוטקס לפני ההמתנה.
        *   הסדר שבו כותבים וקוראים ממתינים ומשוחררים מתוכנן כך שאין מעגל המתנה: קוראים ממתינים אם כותב פעיל או ממתין; כותבים ממתינים אם יש קוראים פעילים או כותב פעיל. קוראים משחררים כותבים, וכותבים משחררים קוראים או כותבים אחרים.
        *   הקפדה על שחרור המוטקס לפני המתנה מונעת מצב שבו תהליך אחד מחזיק את המוטקס וממתין למשהו שרק תהליך אחר יכול לשחרר, כאשר התהליך האחר חסום בעצמו על אותו מוטקס.
        *   אין מצב שבו כותב פעיל או קורא פעיל יחסום את שחרור המוטקס באופן קבוע.

3.  **אי-הרעבה לכותבים (Writer Starvation-free):**
    *   כן, המימוש מבטיח אי-הרעבה לכותבים.
        *   ברגע שכותב מגיע, הוא מגדיל את `writers_waiting`. קוראים חדשים לא יכולים להיכנס אם `writers_waiting > 0`. זה נותן עדיפות לכותבים.
        *   קוראים פעילים יסיימו בסופו של דבר את עבודתם, וכאשר הקורא האחרון מסיים (`readers_active == 0`), הוא מאותת לכותבים ממתינים (`pthread_cond_signal(&rw->writers_q)`). 
        *   לאחר שכותב מסיים, אם יש כותבים נוספים ממתינים (`rw->writers_waiting > 0`), הוא מאותת לאחד מהם (`pthread_cond_signal(&rw->writers_q)`).
        *   מנגנון זה מבטיח שכותבים מקבלים עדיפות על פני קוראים חדשים, וכותב תמיד יקבל גישה למשאב ברגע שיתפנה, לכן כותבים לא יורעבו.

4.  **אי-הרעבה לקוראים (Reader Starvation-free):**
    *   **לא, המימוש אינו מבטיח אי-הרעבה לקוראים.** זוהי נקודת הכשל העיקרית במימוש זה.
    *   הבעיה טמונה בשורה `pthread_cond_signal(&rw->readers_q);` בפעולה `rw_write_unlock`. כאשר כותב מסיים ואין כותבים נוספים הממתינים, הוא מאותת רק ל**קורא אחד** שממתין בתור.
    *   **תרחיש הרעבה:**
        1.  מספר רב של קוראים (לדוגמה: R1, R2, R3, R4) מגיעים וממתינים כי יש כותב פעיל או ממתין.
        2.  כותב (W1) מסיים את עבודתו. אין כותבים נוספים ממתינים.
        3.  `rw_write_unlock` מאותת ל-R1 בלבד. R1 מתעורר, נכנס ל-`rw_read_lock`, מגדיל את `readers_active` ומשחרר את המוטקס.
        4.  מיד לאחר מכן, כותב חדש (W2) מגיע וקורא ל-`rw_write_lock`. הוא רואה ש-R1 פעיל (`readers_active > 0`), ולכן הוא נכנס למצב המתנה, ומגדיל את `writers_waiting`.
        5.  R1 מסיים את עבודתו. `rw_read_unlock` מקטין את `readers_active` ל-0, ומאותת ל-W2.
        6.  W2 מתעורר, נכנס, מסיים את עבודתו.
        7.  `rw_write_unlock` מקטין את `writers_active` ל-0. אין כותבים נוספים ממתינים. הוא מאותת ל-R2 בלבד.
        8.  מחזור זה חוזר על עצמו. אם כותבים חדשים ממשיכים להגיע במהירות מספקת, לפני שכל הקוראים שהמתינו במקור מספיקים להיכנס, רק קורא אחד יוכל להיכנס בכל "חלון" שבו אין כותבים ממתינים, ומיד ייתפס המשאב על ידי כותב חדש. קוראים כמו R3 ו-R4 עלולים להמתין ללא הגבלת זמן.

5.  **תיקון המימוש:**
    *   כדי למנוע הרעבה של קוראים (תוך שמירה על עדיפות כותבים ואי-הרעבת כותבים), יש לשנות את ה-`pthread_cond_signal` ל-`pthread_cond_broadcast` כאשר כותב מסיים ואין כותבים ממתינים. זאת כדי להעיר את **כל** הקוראים הממתינים, ולאפשר להם להיכנס למשאב במקביל.

    ```c
    #include <pthread.h> // Assume pthreads library is available

    typedef struct {
        pthread_mutex_t lock;
        pthread_cond_t readers_q;
        pthread_cond_t writers_q;
        int readers_active; // Number of active readers
        int writers_active; // 0 or 1
        int writers_waiting; // Number of writers waiting
    } rw_lock_t;

    void rw_init(rw_lock_t *rw) {
        pthread_mutex_init(&rw->lock, NULL);
        pthread_cond_init(&rw->readers_q, NULL);
        pthread_cond_init(&rw->writers_q, NULL);
        rw->readers_active = 0;
        rw->writers_active = 0;
        rw->writers_waiting = 0;
    }

    void rw_destroy(rw_lock_t *rw) {
        pthread_mutex_destroy(&rw->lock);
        pthread_cond_destroy(&rw->readers_q);
        pthread_cond_destroy(&rw->writers_q);
    }

    void rw_read_lock(rw_lock_t *rw) {
        pthread_mutex_lock(&rw->lock);
        while (rw->writers_active > 0 || rw->writers_waiting > 0) {
            pthread_cond_wait(&rw->readers_q, &rw->lock);
        }
        rw->readers_active++;
        pthread_mutex_unlock(&rw->lock);
    }

    void rw_read_unlock(rw_lock_t *rw) {
        pthread_mutex_lock(&rw->lock);
        rw->readers_active--;
        if (rw->readers_active == 0) {
            pthread_cond_signal(&rw->writers_q);
        }
        pthread_mutex_unlock(&rw->lock);
    }

    void rw_write_lock(rw_lock_t *rw) {
        pthread_mutex_lock(&rw->lock);
        rw->writers_waiting++;
        while (rw->readers_active > 0 || rw->writers_active > 0) {
            pthread_cond_wait(&rw->writers_q, &rw->lock);
        }
        rw->writers_waiting--;
        rw->writers_active = 1;
        pthread_mutex_unlock(&rw->lock);
    }

    void rw_write_unlock(rw_lock_t *rw) {
        pthread_mutex_lock(&rw->lock);
        rw->writers_active = 0;
        if (rw->writers_waiting > 0) {
            pthread_cond_signal(&rw->writers_q);
        } else {
            // תיקון: שינוי מ-signal ל-broadcast
            pthread_cond_broadcast(&rw->readers_q);
        }
        pthread_mutex_unlock(&rw->lock);
    }
    ```

content.code_snippet:
pthread_mutex_t mutexA;
pthread_mutex_t mutexB;
pthread_mutex_t counter_mutex;
pthread_cond_t cond_can_start;
int active_tasks = 0;
const int K = 5; // Example threshold

void perform_task() {
    // Stage 1: Control concurrent task limit
    pthread_mutex_lock(&counter_mutex);
    while (active_tasks >= K) {
        pthread_cond_wait(&cond_can_start, &counter_mutex);
    }
    active_tasks++;
    pthread_mutex_unlock(&counter_mutex);

    // Stage 2: Acquire resources
    pthread_mutex_lock(&mutexA);
    pthread_mutex_lock(&mutexB);

    // Perform actual task work (critical section)
    // ... do some work ...

    // Stage 3: Release resources
    pthread_mutex_unlock(&mutexB);
    pthread_mutex_unlock(&mutexA);

    // Stage 4: Decrement active task counter and signal
    pthread_mutex_lock(&counter_mutex); 
    active_tasks--;
    pthread_cond_signal(&cond_can_start); // Or pthread_cond_broadcast
    pthread_mutex_unlock(&counter_mutex);
}

solution.explanation:
א. כן, המימוש המוצע עלול לגרום לקיפאון (Deadlock).

**תרחיש לקיפאון:**
1.  נניח ש-K חוטים (לדוגמה, חוטים T1...TK) מצליחים לעבור את שלב 1 (בקרת מגבלת משימות מקבילות). כל אחד מהם תופס את `counter_mutex`, מעדכן את `active_tasks`, ומשחרר את `counter_mutex`. כעת `active_tasks` שווה ל-K.
2.  החוטים T1...TK ממשיכים לשלב 2, תופסים את `mutexA` ולאחר מכן את `mutexB`, ומבצעים את עבודת המשימה.
3.  חוט נוסף, נניח T(K+1), מגיע ומתחיל לבצע את `perform_task`.
4.  חוט T(K+1) מגיע לשלב 1: הוא תופס בהצלחה את `counter_mutex`. הוא בודק את `active_tasks` ומוצא ש-`active_tasks == K`. לכן, הוא נכנס ללולאת ה-`while` וקורא ל-`pthread_cond_wait(&cond_can_start, &counter_mutex)`. קריאה זו משחררת אטומית את `counter_mutex` ומכניסה את חוט T(K+1) למצב שינה, בהמתנה לאות על `cond_can_start`.
5.  בינתיים, החוטים T1...TK מסיימים את עבודת המשימה שלהם ומשחררים את `mutexB` ואת `mutexA` (שלב 3).
6.  כעת, החוטים T1...TK מנסים להיכנס לשלב 4: לעדכן את המונה ולשגר אות. לשם כך, כל אחד מהם מנסה לתפוס את `counter_mutex`.
7.  אבל, `counter_mutex` נתפס על ידי חוט T(K+1) כאשר הוא יתעורר מ-`pthread_cond_wait` (הפעולה `pthread_cond_wait` משחררת את המנעול לפני הכניסה למצב שינה, אך תנסה לתפוס אותו בחזרה לפני שהיא חוזרת). כלומר, `counter_mutex` למעשה מוחזק על ידי חוט T(K+1) הממתין לאות, וחוטים T1...TK אינם יכולים לתפוס אותו.
8.  לכן, החוטים T1...TK נחסמים בהמתנה ל-`counter_mutex`.
9.  חוט T(K+1) ממתין לאות על `cond_can_start`. האות הזה יכול להישלח רק על ידי אחד מהחוטים T1...TK לאחר שישחררו את `counter_mutex`.
10. נוצר מצב של תלות מעגלית (circular wait): חוט T(K+1) ממתין לאות מ-T1...TK, והחוטים T1...TK ממתינים ל-`counter_mutex` שמוחזק על ידי T(K+1). זהו מצב של קיפאון.

ב. הפתרון לבעיה הוא לשחרר את `counter_mutex` מוקדם יותר, מיד לאחר עדכון `active_tasks` והיציאה משלב בקרת המגבלה, ורק לאחר שכל המשאבים האחרים שוחררו, לתפוס אותו שוב על מנת לעדכן את `active_tasks` ולשלוח אות. בצורה זו, אין חפיפה בין המנעולים.

**מימוש מתוקן של `perform_task`:**
```c
void perform_task_corrected() {
    // Stage 1: Control concurrent task limit
    pthread_mutex_lock(&counter_mutex);
    while (active_tasks >= K) {
        pthread_cond_wait(&cond_can_start, &counter_mutex);
    }
    active_tasks++;
    pthread_mutex_unlock(&counter_mutex); // Release counter_mutex early

    // Stage 2: Acquire resources
    pthread_mutex_lock(&mutexA);
    pthread_mutex_lock(&mutexB);

    // Perform actual task work (critical section)
    // ... do some work ...

    // Stage 3: Release resources
    pthread_mutex_unlock(&mutexB);
    pthread_mutex_unlock(&mutexA);

    // Stage 4: Decrement active task counter and signal
    pthread_mutex_lock(&counter_mutex); // Re-acquire counter_mutex
    active_tasks--;
    pthread_cond_signal(&cond_can_start); // Or pthread_cond_broadcast
    pthread_mutex_unlock(&counter_mutex);
}
```

**הסבר מדוע הפתרון מונע קיפאון:**
בפתרון המתוקן, `counter_mutex` משוחרר מיד לאחר שחוט קיבל אישור להתחיל במשימה (כלומר, `active_tasks` עודכן והחוט יצא מהלולאה). הדבר מבטיח ש-`counter_mutex` אינו מוחזק בזמן שהחוט מנסה לתפוס את `mutexA` ו-`mutexB`. וחשוב מכך, הוא אינו מוחזק בזמן שחוט ממתין על `cond_can_start`. כאשר חוטים מסיימים את המשימה שלהם, הם משחררים את `mutexA` ו-`mutexB` *לפני* שהם מנסים לתפוס מחדש את `counter_mutex`. באופן זה, אין מצב שבו חוט מחזיק ב-`counter_mutex` ונחסם בהמתנה למנעולים אחרים, או שחוט מחזיק במנעולים אחרים ונחסם בהמתנה ל-`counter_mutex` כדי לשחרר חוטים אחרים. כלומר, לא נוצרת תלות מעגלית בין המנעולים, והקיפאון נמנע.

