void* worker_thread(void* arg) {
    long thread_id = (long)arg;
    long resource1_idx = thread_id;
    long resource2_idx = (thread_id + 1) % N_THREADS;

    // Naive acquisition order
    pthread_mutex_lock(&resources[resource1_idx]);
    // For demonstration, a small delay might be added here to increase deadlock probability:
    // usleep(100);
    pthread_mutex_lock(&resources[resource2_idx]);

    // Perform work with both resources
    printf("Thread %ld acquired resources %ld and %ld. Performing work...\n", thread_id, resource1_idx, resource2_idx);
