#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For sleep

// Global semaphores for individual resources
sem_t desks_sem;     // Initialized to N
sem_t computers_sem; // Initialized to M

void init_library(int num_desks, int num_computers) {
    sem_init(&desks_sem, 0, num_desks);
    sem_init(&computers_sem, 0, num_computers);
    printf("Library initialized with %d desks and %d computers.\n", num_desks, num_computers);
}

void destroy_library() {
    sem_destroy(&desks_sem);
    sem_destroy(&computers_sem);
    printf("Library destroyed.\n");
}

void acquire_desk() {
    sem_wait(&desks_sem);
    // printf("Acquired a desk.\n");
}

void release_desk() {
    sem_post(&desks_sem);
    // printf("Released a desk.\n");
}

void acquire_computer() {
    sem_wait(&computers_sem);
    // printf("Acquired a computer.\n");
}

void release_computer() {
    sem_post(&computers_sem);
    // printf("Released a computer.\n");
}

// Student Type A: Needs Desk then Computer
void* student_type_A_task(void* arg) {
    printf("Student A: Attempting to acquire desk...\n");
    acquire_desk();
    printf("Student A: Desk acquired. Attempting to acquire computer...\n");
    // Simulate some work or delay
    sleep(1);
    acquire_computer();
    printf("Student A: Computer acquired. Using both resources...\n");
    // Simulate usage
    sleep(2);
    release_computer();
    printf("Student A: Computer released. Releasing desk...\n");
    release_desk();
    printf("Student A: Desk released. Task finished.\n");
    return NULL;
}

// Student Type B: Needs Computer then Desk
void* student_type_B_task(void* arg) {
    printf("Student B: Attempting to acquire computer...\n");
    acquire_computer();
    printf("Student B: Computer acquired. Attempting to acquire desk...\n");
    // Simulate some work or delay
    sleep(1);
    acquire_desk();
    printf("Student B: Desk acquired. Using both resources...\n");
    // Simulate usage
    sleep(2);
    release_desk();
    printf("Student B: Desk released. Releasing computer...\n");
    release_computer();
    printf("Student B: Computer released. Task finished.\n");
    return NULL;
}

solution.explanation:
א. כן, המימוש המוצג עלול להוביל לקיפאון. קיפאון יתרחש כאשר מתקיימים ארבעת התנאים של קופמן: מניעה הדדית (Mutual Exclusion), החזקה והמתנה (Hold and Wait), אי-הפקעה (No Preemption) והמתנה מעגלית (Circular Wait). במקרה זה:
*   **מניעה הדדית:** כל משאב (שולחן או מחשב) נתפס באופן בלעדי על ידי סטודנט אחד באמצעות הסמפורים (`sem_wait`).
*   **החזקה והמתנה:** סטודנט מסוג A יכול לתפוס שולחן ולהמתין למחשב, בעוד סטודנט מסוג B יכול לתפוס מחשב ולהמתין לשולחן. כלומר, חוט מחזיק במשאב אחד וממתין למשאב נוסף.
*   **אי-הפקעה:** לא ניתן להפקיע משאב מסטודנט שמחזיק בו; רק הסטודנט עצמו יכול לשחרר את המשאב באמצעות `sem_post`.
*   **המתנה מעגלית:** תרחיש קיפאון יכול להתרחש כך:
    1.  סטודנט A (מחלקה א') מתחיל: קורא ל-`acquire_desk()`, תופס שולחן. (נניח שולחן 1).
    2.  סטודנט B (מחלקה ב') מתחיל: קורא ל-`acquire_computer()`, תופס מחשב. (נניח מחשב 1).
    3.  סטודנט A ממשיך: קורא ל-`acquire_computer()`, אך מחשב 1 תפוס על ידי B. סטודנט A נחסם וממתין למחשב.
    4.  סטודנט B ממשיך: קורא ל-`acquire_desk()`, אך שולחן 1 תפוס על ידי A. סטודנט B נחסם וממתין לשולחן.
    בשלב זה, שני הסטודנטים חסומים באופן הדדי, ונוצרת המתנה מעגלית: A מחכה ל-B, ו-B מחכה ל-A. אף אחד מהם לא יכול להמשיך או לשחרר את המשאב שהוא מחזיק, והמערכת נכנסת למצב קיפאון.

ב. הפתרון המוצע מונע קיפאון על ידי שבירת תנאי ההמתנה המעגלית. הוא עושה זאת באמצעות הוספת מנעול גלובלי (mutex) בשם `pair_acquisition_mutex`, אשר מגן על הקטע הקריטי שבו סטודנט רוכש את *שני* המשאבים הנדרשים לו. הפתרון מאפשר לסטודנטים שצריכים רק משאב אחד (שולחן בלבד או מחשב בלבד) להמשיך לפעול באופן עצמאי.

כאשר סטודנט מסוג A או B זקוק לשולחן ולמחשב, עליו לרכוש תחילה את ה-`pair_acquisition_mutex`. מנעול זה מבטיח שרק סטודנט אחד יוכל להיות בשלב רכישת שני המשאבים (שולחן וגם מחשב) בכל רגע נתון. ברגע שהסטודנט מחזיק במנעול הגלובלי, הוא יכול לרכוש את השולחן והמחשב (בסדר המועדף עליו) בבטחה, מבלי לחשוש מקיפאון, כיוון שאף סטודנט אחר לא יכול להתחיל תהליך רכישת זוג משאבים במקביל. לאחר רכישת שני המשאבים, הסטודנט משחרר את ה-`pair_acquisition_mutex`, ומאפשר לסטודנטים אחרים לנסות לרכוש זוג משאבים.

הפתרון שומר על רמת מקביליות סבירה מכיוון שה-`pair_acquisition_mutex` נתפס רק לזמן קצר מאוד – רק לצורך רכישת שני הסמפורים. השימוש במשאבים עצמם (שולחן ומחשב) מתבצע במקביל, וסטודנטים הזקוקים רק למשאב בודד (שולחן או מחשב) אינם מושפעים כלל מהמנעול הגלובלי ויכולים לרכוש ולשחרר משאבים אלו באופן חופשי.

```c
#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For sleep

// Global semaphores for individual resources
sem_t desks_sem;     // Initialized to N
sem_t computers_sem; // Initialized to M

// Global mutex to protect the critical section of acquiring *both* resources
// This serializes the acquisition of pairs, preventing circular wait
pthread_mutex_t pair_acquisition_mutex;

void init_library_safe(int num_desks, int num_computers) {
    sem_init(&desks_sem, 0, num_desks);
    sem_init(&computers_sem, 0, num_computers);
    pthread_mutex_init(&pair_acquisition_mutex, NULL);
    printf("Library (safe) initialized with %d desks and %d computers.\n", num_desks, num_computers);
}

void destroy_library_safe() {
    sem_destroy(&desks_sem);
    sem_destroy(&computers_sem);
    pthread_mutex_destroy(&pair_acquisition_mutex);
    printf("Library (safe) destroyed.\n");
}

// Functions for single resource acquisition/release (for students needing only one)
// These are not changed as they don't cause deadlocks on their own.
void acquire_desk_single() { sem_wait(&desks_sem); printf("Acquired a desk (single).\n"); }
void release_desk_single() { sem_post(&desks_sem); printf("Released a desk (single).\n"); }
void acquire_computer_single() { sem_wait(&computers_sem); printf("Acquired a computer (single).\n"); }
void release_computer_single() { sem_post(&computers_sem); printf("Released a computer (single).\n"); }

// Student Type A: Needs Desk then Computer (SAFE)
void* student_type_A_task_safe(void* arg) {
    printf("Student A (safe): Attempting to acquire both resources...\n");
    pthread_mutex_lock(&pair_acquisition_mutex); // Acquire global lock for paired acquisition
    sem_wait(&desks_sem);                        // Acquire desk
    sem_wait(&computers_sem);                    // Acquire computer
    pthread_mutex_unlock(&pair_acquisition_mutex); // Release global lock

    printf("Student A (safe): Desk and Computer acquired. Using both resources...\n");
    // Simulate usage
    sleep(2);

    sem_post(&computers_sem);
    printf("Student A (safe): Computer released. Releasing desk...\n");
    sem_post(&desks_sem);
    printf("Student A (safe): Desk released. Task finished.\n");
    return NULL;
}

// Student Type B: Needs Computer then Desk (SAFE)
void* student_type_B_task_safe(void* arg) {
    printf("Student B (safe): Attempting to acquire both resources...\n");
    pthread_mutex_lock(&pair_acquisition_mutex); // Acquire global lock for paired acquisition
    sem_wait(&computers_sem);                    // Acquire computer
    sem_wait(&desks_sem);                        // Acquire desk
    pthread_mutex_unlock(&pair_acquisition_mutex); // Release global lock

    printf("Student B (safe): Computer and Desk acquired. Using both resources...\n");
    // Simulate usage
    sleep(2);

    sem_post(&desks_sem);
    printf("Student B (safe): Desk released. Releasing computer...\n");
    sem_post(&computers_sem);
    printf("Student B (safe): Computer released. Task finished.\n");
    return NULL;
}
