#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/wait.h>

#define INITIAL_THREADS 3 // מספר התהליכונים שנוצרים לפני ה-fork
#define POST_FORK_THREADS 2 // מספר התהליכונים שנוצרים אחרי ה-fork בכל תהליך
#define INCREMENTS_PER_THREAD 100000 // מספר הפעמים שכל תהליכון מגדיל את המונה

int global_counter = 0; // משתנה גלובלי משותף

// פונקציית התהליכון
void* thread_func(void* arg) {
    int i;
    int thread_logical_id = *(int*)arg; // מזהה לוגי לצורך הדפסה
    printf("Thread %d (PID %d) starting work.\n", thread_logical_id, getpid());
    for (i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        global_counter++; // פעולה לא מסונכרנת על משתנה משותף
    }
    printf("Thread %d (PID %d) finished work. Counter: %d\n", thread_logical_id, getpid(), global_counter);
    return NULL;
}

int main() {
    pthread_t initial_pthreads[INITIAL_THREADS];
    pthread_t post_fork_pthreads[POST_FORK_THREADS];
    int thread_ids[INITIAL_THREADS + POST_FORK_THREADS]; // מזהים לוגיים עבור התהליכונים
    int i;

    printf("Main process (PID: %d) starting. Initial global_counter: %d\n", getpid(), global_counter);

    // 1. יצירת תהליכונים ראשוניים בתהליך הראשי
    for (i = 0; i < INITIAL_THREADS; ++i) {
        thread_ids[i] = i + 1; // מזהים 1, 2, 3
        if (pthread_create(&initial_pthreads[i], NULL, thread_func, &thread_ids[i]) != 0) {
            perror("pthread_create initial failed");
            exit(1);
        }
    }

    // נותנים זמן קצר לתהליכונים הראשוניים להתחיל לרוץ
    usleep(10000); // 10ms

    printf("Main process (PID: %d) forking. Current global_counter: %d\n", getpid(), global_counter);
    pid_t pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(1);
    } else if (pid == 0) { // תהליך הבן
        printf("Child process (PID: %d, PPID: %d) after fork. Its global_counter copy: %d\n", getpid(), getppid(), global_counter);
        // בתהליך הבן, רק התהליכון שקרא ל-fork קיים.
        // משתנה global_counter שוכפל. התהליכונים הראשוניים של האב אינם קיימים בבן.

        // 2. יצירת תהליכונים נוספים בתהליך הבן
        for (i = 0; i < POST_FORK_THREADS; ++i) {
            thread_ids[INITIAL_THREADS + i] = 100 + i + 1; // מזהים 101, 102
            if (pthread_create(&post_fork_pthreads[i], NULL, thread_func, &thread_ids[INITIAL_THREADS + i]) != 0) {
                perror("pthread_create child failed");
                exit(1);
            }
        }

        // הבן ממתין רק לתהליכונים שהוא יצר (אלה שאחרי ה-fork)
        for (i = 0; i < POST_FORK_THREADS; ++i) {
            pthread_join(post_fork_pthreads[i], NULL);
        }
        printf("Child process (PID: %d): Final global_counter = %d\n", getpid(), global_counter);

    } else { // תהליך האב
        printf("Parent process (PID: %d) after fork. Child PID: %d. Its global_counter copy: %d\n", getpid(), pid, global_counter);

        // 2. יצירת תהליכונים נוספים בתהליך האב
        for (i = 0; i < POST_FORK_THREADS; ++i) {
            thread_ids[INITIAL_THREADS + i] = 200 + i + 1; // מזהים 201, 202
            if (pthread_create(&post_fork_pthreads[i], NULL, thread_func, &thread_ids[INITIAL_FORK_THREADS + i]) != 0) {
                perror("pthread_create parent failed");
                exit(1);
            }
        }

        // האב ממתין לכל התהליכונים שלו (הראשוניים ואלה שאחרי ה-fork)
        for (i = 0; i < INITIAL_THREADS; ++i) {
            pthread_join(initial_pthreads[i], NULL);
        }
        for (i = 0; i < POST_FORK_THREADS; ++i) {
            pthread_join(post_fork_pthreads[i], NULL);
        }

        wait(NULL); // האב ממתין לתהליך הבן
        printf("Parent process (PID: %d): Final global_counter = %d\n", getpid(), global_counter);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/wait.h>

#define NUM_ITERATIONS_PER_THREAD 5

int g_val = 0;
pthread_mutex_t m;

void* thread_func(void* arg) {
    long thread_id_arg = (long)arg;
    for (int i = 0; i < NUM_ITERATIONS_PER_THREAD; ++i) {
        pthread_mutex_lock(&m);
        g_val++;
        printf("PID %d, TID (pthread_self) %lu, g_val %d, arg_id %ld\n", getpid(), (unsigned long)pthread_self(), g_val, thread_id_arg);
        pthread_mutex_unlock(&m);
        usleep(10000); // 10ms
    }
    return NULL;
}

int main() {
    pthread_mutex_init(&m, NULL); // Default mutex (PTHREAD_PROCESS_PRIVATE)

    // Parent creates 2 threads
    pthread_t parent_tids[2];
    for (long i = 0; i < 2; ++i) {
        pthread_create(&parent_tids[i], NULL, thread_func, (void*)i);
    }

    usleep(50000); // Allow parent threads to run and potentially hold the mutex

    pid_t pid = fork();

    if (pid == -1) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        printf("Child (PID %d) started. Initial g_val: %d\n", getpid(), g_val);

        // Child creates 2 new threads
        pthread_t child_tids[2];
        for (long i = 0; i < 2; ++i) {
            pthread_create(&child_tids[i], NULL, thread_func, (void*)(i + 100)); // Use different IDs for child threads
        }

        // Child joins its own 2 threads
        for (int i = 0; i < 2; ++i) {
            pthread_join(child_tids[i], NULL);
        }
        printf("Child (PID %d) finished. Final g_val: %d\n", getpid(), g_val);

    } else { // Parent process
        printf("Parent (PID %d) continued. Initial g_val: %d\n", getpid(), g_val);

        // Parent joins its original 2 threads
        for (int i = 0; i < 2; ++i) {
            pthread_join(parent_tids[i], NULL);
        }
        wait(NULL); // Wait for the child process to finish
        printf("Parent (PID %d) finished. Final g_val: %d\n", getpid(), g_val);
    }

    pthread_mutex_destroy(&m);
    return 0;
}

