        exit(1);
    } else if (pid == 0) { // Child process
        printf("Child (PID %d) created.\n", getpid());

        // Attempt to lock the mutex in the child's main thread
        printf("Child (PID %d) main thread attempting to lock mutex after fork...\n", getpid());
        pthread_mutex_lock(&mutex); // This is the tricky part!
        printf("Child (PID %d) main thread locked mutex. Counter before: %d\n", getpid(), shared_counter);
        for (int i = 0; i < 3; ++i) {
            shared_counter++;
            usleep(10);
        }
        printf("Child (PID %d) main thread unlocking mutex. Counter after: %d\n", getpid(), shared_counter);
        pthread_mutex_unlock(&mutex);

        printf("Child (PID %d) final shared_counter: %d\n", getpid(), shared_counter);
        exit(0);
    } else { // Parent process
        printf("Parent (PID %d) continues after fork.\n", getpid());
        // Parent waits for its initial threads to finish.
        pthread_join(tids[0], NULL);
        pthread_join(tids[1], NULL);
