נתונה התוכנית הבאה המשתמשת בזיכרון משותף (shared memory) ובתהליכונים (threads).
קוד זה מנסה לספור סך הכל פעולות הגדלה על מונה משותף.

יש להניח שכל קריאות המערכת (system calls) והפונקציות של Pthreads מצליחות, ולא מתרחשות שגיאות.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <pthread.h>

#define NUM_THREADS 2
#define INCREMENTS_PER_THREAD 100000

// Global variable that will be mapped to shared memory
int *shared_counter = NULL;
const char *SHM_NAME = "/my_shared_counter";

void *thread_func(void *arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
        (*shared_counter)++;
    }
    return NULL;
}

int main() {
    // 1. Create and open shared memory object
    int fd = shm_open(SHM_NAME, O_CREAT | O_RDWR, 0666);
    if (fd == -1) {
        perror("shm_open");
        exit(EXIT_FAILURE);
    }

    // 2. Set the size of the shared memory object
    if (ftruncate(fd, sizeof(int)) == -1) {
        perror("ftruncate");
        exit(EXIT_FAILURE);
    }

    // 3. Map the shared memory object into the process's address space
    shared_counter = (int *)mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (shared_counter == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // 4. Initialize the shared counter
    *shared_counter = 0;

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // Child process
        printf("Child process (PID %d) starting threads...\n", getpid());
        pthread_t threads[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; ++i) {
            pthread_create(&threads[i], NULL, thread_func, NULL);
        }

        for (int i = 0; i < NUM_THREADS; ++i) {
            pthread_join(threads[i], NULL);
        }
        printf("Child process (PID %d) finished. Counter value: %d\n", getpid(), *shared_counter);
        munmap(shared_counter, sizeof(int));
        close(fd);
        exit(EXIT_SUCCESS);
    } else { // Parent process
        printf("Parent process (PID %d) starting threads...\n", getpid());
        pthread_t threads[NUM_THREADS];
        for (int i = 0; i < NUM_THREADS; ++i) {
            pthread_create(&threads[i], NULL, thread_func, NULL);
        }

        for (int i = 0; i < NUM_THREADS; ++i) {
            pthread_join(threads[i], NULL);
        }
        printf("Parent process (PID %d) finished. Counter value: %d\n", getpid(), *shared_counter);

        // Wait for the child process to finish
        wait(NULL);

        printf("Final shared counter value: %d\n", *shared_counter);

        // Clean up shared memory
        munmap(shared_counter, sizeof(int));
        close(fd);
        shm_unlink(SHM_NAME);
        exit(EXIT_SUCCESS);
    }

    return 0;
}
```

solution.explanation:
ניתוח כללי:
התוכנית יוצרת אובייקט זיכרון משותף בשם `/my_shared_counter` וממפה אותו לתוך מרחב הכתובות של התהליך הראשי. המונה `shared_counter` מאותחל ל-0. לאחר מכן, התהליך הראשי מבצע `fork()`. גם תהליך האב וגם תהליך הבן ממשיכים לנקודת ההתחלה של הקוד שלהם, אך כעת שניהם ממופים לאותו אזור זיכרון משותף (ולכן `shared_counter` מצביע על אותו מיקום פיזי בשניהם). כל אחד מהתהליכים (האב והבן) יוצר `NUM_THREADS` (שהוגדר כ-2) תהליכונים (threads). כל תהליכון מבצע `INCREMENTS_PER_THREAD` (שהוגדר כ-100,000) פעולות הגדלה על `*shared_counter`. סך הכל ישנם 4 תהליכונים (2 באב, 2 בבן) המבצעים כל אחד 100,000 הגדלות, כך שהערך הנכון הסופי אמור להיות 4 * 100,000 = 400,000.
עם זאת, אין כל מנגנון סנכרון (כמו mutex) סביב פעולת ההגדלה `(*shared_counter)++`. פעולה זו אינה אטומית; היא מורכבת מקריאה של הערך, הגדלתו, וכתיבת הערך החדש. כאשר מספר תהליכונים (ואף תהליכים) ניגשים למונה משותף ללא סנכרון, נוצר מצב מרוץ (race condition).

8.1. מהו הערך המקסימלי האפשרי?
הערך המקסימלי האפשרי הוא 400,000.
הערך המקסימלי יתקבל אם, במקרה, כל פעולות ההגדלה יבוצעו באופן סדרתי או שהמרוץ יתנהל כך שכל הגדלה תבוצע במלואה לפני שהגדלה אחרת תתחיל או תסיים. זהו המקרה האידיאלי שבו אין אובדן של פעולות הגדלה. למרות שזה לא סביר שיקרה באופן טבעי ללא סנכרון, זהו עדיין פלט אפשרי תיאורטית, המייצג את סך כל ההגדלות שתוכננו.

8.2. מהו הערך המינימלי האפשרי?
הערך המינימלי האפשרי הוא 1.
כדי להבין זאת, נתבונן בפעולת ההגדלה `(*shared_counter)++`. היא מתורגמת בדרך כלל לשלוש פעולות מכונה:
1.  קרא את הערך של `*shared_counter` לתוך רגיסטר.
2.  הגדל את הערך ברגיסטר ב-1.
3.  כתוב את הערך מהרגיסטר בחזרה ל-`*shared_counter`.

תרחיש קיצוני לערך מינימלי:
נניח שכל ארבעת התהליכונים מתחילים כמעט בו-זמנית, כאשר `*shared_counter` הוא 0. כל 400,000 פעולות ההגדלה יכולות להתבצע באופן הבא: כל ארבעת התהליכונים קוראים את הערך הנוכחי (0), מגדילים אותו ל-1 ברגיסטר שלהם, ואז בזה אחר זה כותבים 1 לזיכרון המשותף. האחרון שכותב הוא זה שקובע את הערך הסופי. אם סדר הפעולות הוא כזה שכל 4 התהליכונים קוראים `0`, מגדילים ל`1` (ברגיסטר שלהם), ואז כותבים `1` חזרה לזיכרון, זה אומר ש-4 פעולות הגדלה תרמו רק לשינוי של 1 במונה. תרחיש זה יכול לחזור על עצמו באופן תיאורטי לכל 400,000 ההגדלות, כך שהערך הסופי של המונה יהיה 1.

8.3. האם קיימת אפשרות שהפלט של "Child process finished. Counter value:" והפלט של "Parent process finished. Counter value:" יהיו זהים?
כן, בהחלט קיימת אפשרות כזו.
מכיוון שהמונה `shared_counter` הוא זיכרון משותף בין האב והבן (באמצעות `mmap` עם `MAP_SHARED`), שניהם רואים ומשנים את אותו מופע של המונה.
הפלט "Child process finished. Counter value: %d" והפלט "Parent process finished. Counter value: %d" מציגים את הערך של `*shared_counter` ברגע שהתהליך הספציפי מסיים את כל התהליכונים שלו ומגיע לשורת ההדפסה.
הסדר שבו התהליכים והתהליכונים רצים נקבע על ידי המתזמן של מערכת ההפעלה, והוא אינו מובטח. ייתכן מצב שבו תהליך הבן מסיים את כל עבודתו, מדפיס את הערך הסופי של המונה. לאחר מכן, תהליך האב מסיים גם הוא את כל עבודתו, ומדפיס את אותו ערך סופי. לדוגמה, אם תהליך הבן מסיים את כל 200,000 ההגדלות שלו ושל התהליכונים שלו, ואז תהליך האב מסיים את כל 200,000 ההגדלות שלו ושל התהליכונים שלו. בסופו של דבר, שניהם ידפיסו את הערך הסופי של המונה המשותף, לאחר שכל 400,000 ההגדלות (בתוספת האובדן עקב מרוץ) בוצעו.

8.4. הצעת פתרון לתיקון בעיית המרוץ:
כדי לפתור את בעיית המרוץ על `shared_counter` בין תהליכונים ותהליכים, יש להשתמש במנגנון סנכרון כמו mutex. מכיוון שה-mutex צריך להיות משותף בין תהליכים, יש להשתמש ב-mutex שיכול לפעול בין תהליכים (process-shared mutex).

שינויים נדרשים בקוד:
1.  **הגדרת מבנה נתונים משותף:**
    נשנה את הזיכרון המשותף כך שיכיל גם את המונה וגם את ה-mutex.
    ```c
    // Global structure for shared memory
    typedef struct {
        int counter;
        pthread_mutex_t mutex; // Mutex for inter-process and inter-thread synchronization
    } shared_data_t;

    shared_data_t *shared_data = NULL; // Pointer to the mapped shared memory
    const char *SHM_NAME = "/my_shared_counter";
    // ...
    // ב-main, נשנה את ה-ftruncate ואת ה-mmap:
    if (ftruncate(fd, sizeof(shared_data_t)) == -1) { /* ... */ }
    shared_data = (shared_data_t *)mmap(NULL, sizeof(shared_data_t), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (shared_data == MAP_FAILED) { /* ... */ }
    ```

2.  **אתחול ה-mutex:**
    ה-mutex צריך להיות מאותחל עם התכונה `PTHREAD_PROCESS_SHARED`. רק תהליך אחד (לרוב האב) צריך לאתחל אותו.
    ```c
    // ב-main, לפני ה-fork, נאתחל את תכונות ה-mutex:
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);

    pid_t pid = fork();
    // ...
    else if (pid == 0) { // Child process
        // הבן לא מאתחל את המונה או ה-mutex.
    } else { // Parent process
        // האב מאתחל את המונה וה-mutex
        shared_data->counter = 0;
        pthread_mutex_init(&(shared_data->mutex), &attr);
    }
    // ...
    // חשוב להרוס את תכונות ה-mutex לאחר השימוש בהן
    pthread_mutexattr_destroy(&attr);
    ```

3.  **שימוש ב-mutex בפונקציית התהליכון:**
    יש לנעול את ה-mutex לפני גישה למונה ולשחרר אותו לאחר מכן.
    ```c
    void *thread_func(void *arg) {
        for (int i = 0; i < INCREMENTS_PER_THREAD; ++i) {
            pthread_mutex_lock(&(shared_data->mutex)); // נעל את ה-mutex
            (shared_data->counter)++;
            pthread_mutex_unlock(&(shared_data->mutex)); // שחרר את ה-mutex
        }
        return NULL;
    }
    ```

4.  **שחרור ה-mutex:**
    יש להרוס את ה-mutex (רק פעם אחת, לרוב על ידי התהליך האחרון).
    ```c
    // ב-main, בתהליך האב, לפני munmap ו-shm_unlink:
    pthread_mutex_destroy(&(shared_data->mutex)); // הרס את ה-mutex
    ```
עם שינויים אלה, כל גישה למונה תהיה מוגנת על ידי ה-mutex, מה שיבטיח שההגדלות יהיו אטומיות והערך הסופי של המונה יהיה תמיד 400,000.

