#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/wait.h>

// Global mutex
pthread_mutex_t my_mutex;

// Thread function: locks the mutex and holds it
void* thread_func_locker(void* arg) {
    printf("Thread %ld: Trying to acquire mutex...\n", (long)pthread_self());
    pthread_mutex_lock(&my_mutex);
    printf("Thread %ld: Mutex acquired. Holding it for 2 seconds.\n", (long)pthread_self());
    sleep(2); // Hold the mutex
    printf("Thread %ld: Releasing mutex.\n", (long)pthread_self());
    pthread_mutex_unlock(&my_mutex);
    return NULL;
}

int main() {
    pthread_t tid;
    pid_t pid;

    pthread_mutex_init(&my_mutex, NULL);

    // Create a thread that locks the mutex
    pthread_create(&tid, NULL, thread_func_locker, NULL);

    // Give the thread a moment to acquire the mutex
    usleep(100000); // 100ms, likely enough for the thread to lock the mutex

    printf("Main process (PID %d): About to fork.\n", getpid());
    pid = fork();

    if (pid == -1) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // Child process
        printf("Child process (PID %d): Trying to acquire mutex...\n", getpid());
        // The child process tries to lock the mutex.
        // The mutex was locked by 'tid' in the parent.
        // In the child, 'tid' does not exist, and the mutex is in a locked state, but no thread in the child owns it.
        // This will likely lead to a deadlock in the child.
        pthread_mutex_lock(&my_mutex); // Child deadlocks here!
        printf("Child process (PID %d): Mutex acquired (this should not happen normally).\n", getpid());
        pthread_mutex_unlock(&my_mutex);
        exit(0);
    } else { // Parent process
        printf("Parent process (PID %d): Child created. Waiting for child to finish.\n", getpid());
        wait(NULL); // Wait for the child to finish (if it ever does)
        printf("Parent process (PID %d): Child finished. Joining thread.\n", getpid());
        pthread_join(tid, NULL); // Join the thread in the parent
        printf("Parent process (PID %d): Thread joined.\n", getpid());
    }

    pthread_mutex_destroy(&my_mutex);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/wait.h>

#define NUM_THREADS 3
#define ITERATIONS  2

int g_counter = 0; // Global variable
pthread_mutex_t mutex;

void *thread_func(void *arg) {
    long thread_id = (long)arg;
    for (int i = 0; i < ITERATIONS; ++i) {
        pthread_mutex_lock(&mutex);
        g_counter++;
        printf("PID: %d, TID: %ld, Counter: %d\n", getpid(), thread_id, g_counter);
        pthread_mutex_unlock(&mutex);
        usleep(100); // Simulate some work and increase interleaving opportunities
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    pid_t pid;
    long i;

    pthread_mutex_init(&mutex, NULL);

    printf("Main process (PID: %d) starting with g_counter = %d\n", getpid(), g_counter);

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(1);
    } else if (pid == 0) { // Child process
        printf("Child process (PID: %d) created, g_counter = %d\n", getpid(), g_counter);
        for (i = 0; i < NUM_THREADS; ++i) {
            pthread_create(&threads[i], NULL, thread_func, (void *)(i + 100)); // Child thread IDs start from 100
        }
        for (i = 0; i < NUM_THREADS; ++i) {
            pthread_join(threads[i], NULL);
        }
        printf("Child process (PID: %d) finished, final g_counter = %d\n", getpid(), g_counter);
        exit(0); // Child exits
    } else { // Parent process
        printf("Parent process (PID: %d) continuing, g_counter = %d\n", getpid(), g_counter);
        for (i = 0; i < NUM_THREADS; ++i) {
            pthread_create(&threads[i], NULL, thread_func, (void *)(i + 1)); // Parent thread IDs start from 1
        }
        for (i = 0; i < NUM_THREADS; ++i) {
            pthread_join(threads[i], NULL);
        }
        wait(NULL); // Wait for the child process to finish
        printf("Parent process (PID: %d) finished, final g_counter = %d\n", getpid(), g_counter);
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/wait.h>

int global_counter = 0;
pthread_mutex_t mutex;

void* thread_func(void* arg) {
    int thread_id = *(int*)arg;
    pthread_mutex_lock(&mutex);
    global_counter++;
    printf("PID: %d, TID: %lu, Counter: %d\n", getpid(), pthread_self(), global_counter);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    pthread_mutex_init(&mutex, NULL);
    pthread_t threads[2];
    int thread_args[2];

    printf("Main PID: %d (Initial)\n", getpid());

    // Parent creates 2 threads
    for (int i = 0; i < 2; i++) {
        thread_args[i] = i + 1;
        pthread_create(&threads[i], NULL, thread_func, &thread_args[i]);
    }

    // Wait for parent's initial threads to finish
    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], NULL);
    }

    pid_t pid = fork();

    if (pid == 0) { // Child process
        printf("Child PID: %d (After Fork)\n", getpid());
        // Child creates 2 new threads
        pthread_t child_threads[2];
        int child_thread_args[2];
        for (int i = 0; i < 2; i++) {
            child_thread_args[i] = i + 3; // Different IDs for child's threads
            pthread_create(&child_threads[i], NULL, thread_func, &child_thread_args[i]);
        }
        for (int i = 0; i < 2; i++) {
            pthread_join(child_threads[i], NULL);
        }
        exit(0);
    } else if (pid > 0) { // Parent process after fork
        wait(NULL); // Wait for child to finish
        printf("Parent PID: %d (After Fork)\n", getpid());
        // Parent creates 1 more thread after fork
        pthread_t parent_post_fork_threads[1];
        int parent_post_fork_thread_arg = 5;
        pthread_create(&parent_post_fork_threads[0], NULL, thread_func, &parent_post_fork_thread_arg);
