sem_t full;     // Counts full slots in buffer (counting semaphore)

// Helper function to add multiple items to the buffer
// Assumes mutex is held and enough empty slots are available
void add_items_to_buffer(int *items, int count) {
    for (int i = 0; i < count; i++) {
        buffer[in] = items[i];
        in = (in + 1) % BUFFER_SIZE;
    }
}

// Helper function to remove multiple items from the buffer
// Assumes mutex is held and enough full slots are available
void remove_items_from_buffer(int *items_removed, int count) {
    for (int i = 0; i < count; i++) {
        items_removed[i] = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
    }
}

// Producer thread function
void *producer(void *arg) {
    // int producer_id = *(int*)arg; // If distinguishing producers
    int items_to_produce = 3; // Example: producer wants to add 3 items at a time
    static int produced_value_counter = 0; // Static to generate unique values across calls

    while (1) {
        // Prepare items to add
        int items[items_to_produce];
        for (int i = 0; i < items_to_produce; i++) {
            items[i] = produced_value_counter++;
        }

        // Wait for enough empty slots for all 'items_to_produce' items
        for (int i = 0; i < items_to_produce; i++) {
            sem_wait(&empty);
        }

        sem_wait(&mutex); // Acquire mutex for exclusive buffer access

        add_items_to_buffer(items, items_to_produce);
        printf("Producer added %d items (from %d to %d).\n", items_to_produce, items[0], items[items_to_produce-1]);

        sem_post(&mutex); // Release mutex

