#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define BUFFER_SIZE 5

int buffer[BUFFER_SIZE];
int in = 0;
int out = 0;

sem_t mutex; // Controls access to the buffer
sem_t empty; // Counts empty slots in the buffer
sem_t full;  // Counts full slots in the buffer

void *producer(void *arg) {
    int item;
    while (1) {
        // Simulate producing an item
        item = rand() % 100;
        printf("Producer produced: %d\n", item);

        // Potential problem lines
        sem_wait(&mutex); // Acquire mutex first
        sem_wait(&empty); // Then wait for an empty slot

        // Critical section
        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        printf("Producer inserted %d. Buffer count: (not directly shown)\n", item);

        sem_post(&full);   // Signal that a slot is full
        sem_post(&mutex); // Release mutex
    }
    return NULL;
}

void *consumer(void *arg) {
    int item;
    while (1) {
        sem_wait(&full);  // Wait for a full slot
        sem_wait(&mutex); // Acquire mutex

        // Critical section
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        printf("Consumer removed %d. Buffer count: (not directly shown)\n", item);

        sem_post(&mutex); // Release mutex
        sem_post(&empty); // Signal that a slot is empty

        // Consume the item
        printf("Consumer consumed: %d\n", item);
    }
    return NULL;
}

int main() {
    pthread_t prod_tid, cons_tid;

    // Initialize semaphores
    sem_init(&mutex, 0, 1);           // Binary semaphore for mutual exclusion
    sem_init(&empty, 0, BUFFER_SIZE); // Counts empty slots, initially BUFFER_SIZE
    sem_init(&full, 0, 0);            // Counts full slots, initially 0

    // Create producer and consumer threads
    pthread_create(&prod_tid, NULL, producer, NULL);
    pthread_create(&cons_tid, NULL, consumer, NULL);

    // Join threads (in a real scenario, they might run indefinitely)
    pthread_join(prod_tid, NULL);
    pthread_join(cons_tid, NULL);

    // Destroy semaphores
    sem_destroy(&mutex);
    sem_destroy(&empty);
    sem_destroy(&full);

    return 0;
}

solution.explanation:
קיימת בעיה בקוד הנתון, והיא עלולה להוביל לקיפאון (deadlock).

**הסבר הבעיה:**
בפונקציית ה-`producer`, הסדר של קריאות ה-`sem_wait` שגוי. היצרן מנסה לרכוש את הסמפור `mutex` (שמגן על הגישה לחוצץ) *לפני* שהוא מנסה לרכוש את הסמפור `empty` (שמוודא שיש מקום פנוי בחוצץ).
אם החוצץ מתמלא (כלומר, `empty` מגיע ל-0), והיצרן הבא מנסה לייצר פריט, יקרה הדבר הבא:
1.  היצרן יבצע `sem_wait(&mutex)` ויצליח לרכוש את המנעול, מכיוון ש-`mutex` מאותחל ל-1.
2.  לאחר מכן, היצרן יבצע `sem_wait(&empty)`. מכיוון שהחוצץ מלא, `empty` הוא 0, והיצרן יחסם וימתין.
3.  במצב זה, היצרן מחזיק את המנעול `mutex` וחסום בהמתנה למקום פנוי.
4.  הצרכן, כדי לפנות מקום בחוצץ (וכך לאפשר ל-`empty` לעלות), זקוק גם הוא למנעול `mutex` (כפי שניתן לראות בפונקציית `consumer`: `sem_wait(&mutex)`).
5.  מכיוון שהיצרן מחזיק את `mutex` וחסום, הצרכן לא יוכל לרכוש את `mutex` ויחסם גם הוא.
זהו מצב של קיפאון: היצרן מחכה לצרכן שיפנה מקום, והצרכן מחכה ליצרן שישחרר את `mutex`.

**השורות הבעייתיות:**
בפונקציית `producer`, השורות:
```c
        sem_wait(&mutex); // שורה זו מבוצעת לפני sem_wait(&empty)
        sem_wait(&empty); // שורה זו מבוצעת אחרי sem_wait(&mutex)
```

**הקוד המתוקן:**
יש להחליף את הסדר של קריאות ה-`sem_wait` בפונקציית ה-`producer` כך שהיצרן ימתין למקום פנוי *לפני* שהוא רוכש את מנעול הגישה לחוצץ.

