int in = 0;
int out = 0;

sem_t mutex;    // For mutual exclusion on buffer access
sem_t full;     // Counts the number of items in the buffer
sem_t empty;    // Counts the number of empty slots in the buffer

void *producer(void *arg) {
    int item;
    while (1) {
        // Simulate item production
        item = rand() % 100;

        sem_wait(&empty); // Wait for an empty slot (critical for preventing deadlock)
        sem_wait(&mutex); // Acquire mutex for buffer access

        // Critical section
        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        printf("Producer produced: %d, in = %d\n", item, in);

        sem_post(&mutex); // Release mutex
        sem_post(&full);  // Signal that an item is available
    }
    return NULL;
}

void *consumer(void *arg) {
    int item;
    while (1) {
        sem_wait(&full);  // Wait for an item to be available (critical for preventing deadlock)
        sem_wait(&mutex); // Acquire mutex for buffer access

        // Critical section
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        printf("Consumer consumed: %d, out = %d\n", item, out);

        sem_post(&mutex); // Release mutex
        sem_post(&empty); // Signal that an empty slot is available
    }
    return NULL;
}

int main() {
    // Initialize semaphores
    sem_init(&mutex, 0, 1);
    sem_init(&full, 0, 0);
    sem_init(&empty, 0, BUFFER_SIZE);

    pthread_t prod_tid, cons_tid;

    // Create producer and consumer threads
    pthread_create(&prod_tid, NULL, producer, NULL);
    pthread_create(&cons_tid, NULL, consumer, NULL);

    // Wait for threads to finish (in a real scenario, they might run indefinitely)
    pthread_join(prod_tid, NULL);
    pthread_join(cons_tid, NULL);

    // Destroy semaphores
    sem_destroy(&mutex);
    sem_destroy(&full);
    sem_destroy(&empty);

    return 0;
}
```

בסדר המתוקן, המפיק ימתין למקום פנוי (`empty`) לפני שינסה לרכוש את ה-`mutex`. אם החוצץ מלא, הוא יחסם על `empty` מבלי להחזיק ב-`mutex`. באופן דומה, הצרכן ימתין לפריט קיים (`full`) לפני שינסה לרכוש את ה-`mutex`. זה מבטיח שאף חוט לא יחזיק את ה-`mutex` בזמן שהוא ממתין למשאב שחוט אחר (שגם הוא ממתין ל-`mutex`) יכול לשחרר, ובכך נמנע קיפאון.

