#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define BUFFER_SIZE 5

int buffer[BUFFER_SIZE];
int in = 0;
int out = 0;

sem_t mutex;    // Controls access to buffer
sem_t empty;    // Counts empty slots in buffer
sem_t full;     // Counts full slots in buffer

void *producer(void *param) {
    int item;
    for (int i = 0; i < 10; i++) {
        item = rand() % 100; // Produce a random item

        // BUG: Acquiring mutex before waiting for empty slot
        sem_wait(&mutex); // Acquire lock for buffer access
        sem_wait(&empty); // Wait for an empty slot

        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        printf("Producer produced: %d\n", item);

        sem_post(&full);  // Signal that a slot is full
        sem_post(&mutex); // Release lock
    }
    pthread_exit(0);
}

void *consumer(void *param) {
    int item;
    for (int i = 0; i < 10; i++) {
        sem_wait(&full);  // Wait for a full slot
        sem_wait(&mutex); // Acquire lock for buffer access

        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        printf("Consumer consumed: %d\n", item);

        sem_post(&mutex); // Release lock
        sem_post(&empty); // Signal that a slot is empty
    }
    pthread_exit(0);
}

int main() {
    pthread_t prod_tid, cons_tid;

    sem_init(&mutex, 0, 1);
    sem_init(&empty, 0, BUFFER_SIZE);
    sem_init(&full, 0, 0);

    pthread_create(&prod_tid, NULL, producer, NULL);
    pthread_create(&cons_tid, NULL, consumer, NULL);

    pthread_join(prod_tid, NULL);
    pthread_join(cons_tid, NULL);

    sem_destroy(&mutex);
    sem_destroy(&empty);
    sem_destroy(&full);

    return 0;
}

solution.explanation:
א. התקלה נמצאת בפונקציית המפיק (producer). הסדר של קריאות ה-`sem_wait` שגוי: המפיק קורא ל-`sem_wait(&mutex)` לפני קריאה ל-`sem_wait(&empty)`.

ב. הסבר התקלה:
במצב שבו החיץ מלא (כלומר, סמפור `empty` שווה ל-0), המפיק יבצע את הפעולות הבאות:
1.  יבצע `sem_wait(&mutex)` ויקבל את המנעול ההדדי.
2.  לאחר מכן יבצע `sem_wait(&empty)`. מכיוון שהחיץ מלא, הסמפור `empty` הוא 0, והמפיק יחסם וימתין שיתפנה מקום בחיץ.
הבעיה היא שהמפיק מחזיק במנעול ההדדי (`mutex`) בזמן שהוא חסום וממתין למקום פנוי. הצרכן, כדי לפנות מקום בחיץ, צריך לגשת לחיץ ולצרוך פריט. אך כדי לגשת לחיץ, הצרכן צריך לרכוש את המנעול ההדדי (`mutex`), אשר מוחזק כרגע על ידי המפיק החסום.
מצב זה יוצר קיפאון (deadlock): המפיק ממתין לצרכן שיפנה מקום, והצרכן ממתין למפיק שישחרר את המנעול. אף אחד מהם לא יכול להתקדם.

ג. קוד מתוקן עבור פונקציית המפיק (producer):
```c
void *producer(void *param) {
    int item;
    for (int i = 0; i < 10; i++) {
        item = rand() % 100; // Produce a random item

        // סדר מתוקן: ממתינים למקום פנוי לפני רכישת המנעול ההדדי
        sem_wait(&empty); // Wait for an empty slot
        sem_wait(&mutex); // Acquire lock for buffer access

        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        printf("Producer produced: %d\n", item);

        sem_post(&mutex); // Release lock
        sem_post(&full);  // Signal that a slot is full
    }
    pthread_exit(0);
}
```
הערה: הסדר של `sem_post(&mutex)` ואחריו `sem_post(&full)` נחשב לפרקטיקה מומלצת, שכן הוא משחרר את המנעול ההדדי מיד לאחר סיום הפעולה הקריטית, ובכך מאפשר לחוטים אחרים לגשת למשאב מוקדם יותר.

