```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

#define PAGE_SIZE 4096 // Typical page size
#define ARRAY_SIZE (PAGE_SIZE * 5) // An array spanning 5 pages

int main() {
    int *arr = (int *)malloc(ARRAY_SIZE);
    if (arr == NULL) {
        perror("malloc failed");
        return 1;
    }

    // Initialize the array (writes to all pages)
    for (int i = 0; i < ARRAY_SIZE / sizeof(int); ++i) {
        arr[i] = i;
    }

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // Child process
        printf("Child process (PID: %d) modifying data...\n", getpid());
        // Child modifies an element in the first page
        arr[0] = 100;
        // Child modifies an element in the third page
        arr[ARRAY_SIZE / sizeof(int) / 2] = 200;
        printf("Child: arr[0] = %d, arr[ARRAY_SIZE/sizeof(int)/2] = %d\n", arr[0], arr[ARRAY_SIZE / sizeof(int) / 2]);
        free(arr);
        exit(0);
    } else { // Parent process
        printf("Parent process (PID: %d) waiting for child...\n", getpid());
        wait(NULL); // Wait for child to finish

        printf("Parent process (PID: %d) modifying data...\n", getpid());
        // Parent modifies an element in the second page
        arr[PAGE_SIZE / sizeof(int)] = 300;
        printf("Parent: arr[PAGE_SIZE/sizeof(int)] = %d\n", arr[PAGE_SIZE / sizeof(int)]);
        free(arr);
        printf("Parent finished.\n");
    }

    return 0;
}
```

