#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

#define ARRAY_SIZE (1024 * 1024) // 1MB

int main() {
    int *arr = (int *)malloc(ARRAY_SIZE);
    if (arr == NULL) {
        perror("malloc failed");
        return 1;
    }

    // Initialize array - this will cause pages to be allocated and marked dirty
    for (int i = 0; i < ARRAY_SIZE / sizeof(int); i++) {
        arr[i] = 0;
    }

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // Child process
        // Child modifies a specific page
        arr[0] = 100; // Modifies the first page
        printf("Child modified arr[0]\n");
        exit(0);
    } else { // Parent process
        wait(NULL); // Wait for child to finish
        // Parent modifies a different specific page
        arr[ARRAY_SIZE / sizeof(int) - 1] = 200; // Modifies the last page
        printf("Parent modified arr[last_element]\n");
    }

    free(arr);
    return 0;
}

