        wait(NULL); // האב ממתין שהבן יסיים

        // לאחר שהבן סיים ויצא, האב משנה איבר בדף הראשון
        arr[1] = 3000;
        // האב משנה איבר בדף השני
        arr[NUM_INT_PER_PAGE + 1] = 4000;
    }

    free(arr);
    return 0;
}
