#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

#define ARRAY_SIZE (16 * 1024) // 16KB

int main() {
    int *buffer = (int *)malloc(ARRAY_SIZE);
    if (buffer == NULL) {
        perror("malloc failed");
        return 1;
    }

    // Initialize the buffer (all pages become resident and R/W)
    for (int i = 0; i < ARRAY_SIZE / sizeof(int); ++i) {
        buffer[i] = 0;
    }

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // Child process
        printf("Child process: Modifying buffer[0]\n");
        buffer[0] = 100; // This is on the first 4KB page (offset 0)
        exit(0);
    } else { // Parent process
        // Wait for child to finish, then modify
        wait(NULL);
        printf("Parent process: Modifying buffer[5000/sizeof(int)]\n");
        // Assuming sizeof(int) = 4, then 5000/4 = 1250. buffer[1250] is at offset 5000 bytes.
        // This is on the second 4KB page (4096 < 5000 < 8192)
        buffer[5000 / sizeof(int)] = 200;
    }

    // Assume the processes terminate cleanly, and we are interested in the peak physical page usage for 'buffer'
    // after both modifications are complete.
    // The buffer is guaranteed to be page-aligned.
    return 0;
}
```
