#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

#define NUM_THREADS 5
#define INCREMENTS_PER_THREAD 100000

long long global_counter = 0;

void* increment_counter(void* arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; i++) {
        global_counter++;
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, increment_counter, NULL);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Final counter value: %lld\n", global_counter);

    return 0;
}

solution.explanation:
7.1. הערך הצפוי של `global_counter` הוא `NUM_THREADS * INCREMENTS_PER_THREAD`, כלומר 5 * 100,000 = 500,000. עם זאת, בגלל תנאי מרוץ, הערך הסופי *לא* יהיה תמיד 500,000, ולרוב יהיה נמוך יותר. הסיבה היא שפעולת הקידום `global_counter++` אינה אטומית. היא מורכבת משלוש פעולות בסיסיות: 1. קריאת הערך הנוכחי של `global_counter` לרג'יסטר. 2. הגדלת הערך ברג'יסטר. 3. כתיבת הערך המעודכן מהרג'יסטר בחזרה לזיכרון. כאשר מספר תהליכונים מבצעים פעולה זו בו-זמנית, תהליכון אחד יכול לקרוא את הערך, ותהליכון אחר יכול לקדם ולכתוב ערך חדש לפני שהתהליכון הראשון יספיק לכתוב את הערך המעודכן שלו. כתוצאה מכך, חלק מהעדכונים הולכים לאיבוד.

7.2. תנאי המרוץ מתרחש סביב המשתנה המשותף `global_counter` ובמיוחד בפעולה `global_counter++`. הוא מתרחש מכיוון שמספר תהליכונים ניגשים ומשנים משאב משותף (המונה הגלובלי) ללא מנגנון סנכרון מתאים, מה שמוביל לתוצאות בלתי צפויות ולא עקביות. הקטע הקריטי בקוד הוא השורה `global_counter++;`.

7.3. כדי לפתור את תנאי המרוץ, יש להגן על הקטע הקריטי באמצעות mutex. יש לאתחל את ה-mutex לפני יצירת התהליכונים, לנעול אותו לפני הכניסה לקטע הקריטי, לשחרר אותו ביציאה מהקטע הקריטי, ולהשמיד אותו בסיום. להלן קטע הקוד המתוקן:
```c
// הגדרת המוטקס גלובלית
pthread_mutex_t counter_mutex;

void* increment_counter(void* arg) {
    for (int i = 0; i < INCREMENTS_PER_THREAD; i++) {
        pthread_mutex_lock(&counter_mutex);   // נעל את המוטקס לפני גישה למשאב המשותף
        global_counter++;
        pthread_mutex_unlock(&counter_mutex); // שחרר את המוטקס אחרי הגישה למשאב המשותף
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    pthread_mutex_init(&counter_mutex, NULL); // אתחל את המוטקס לפני יצירת התהליכונים

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, increment_counter, NULL);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("Final counter value: %lld\n", global_counter);

    pthread_mutex_destroy(&counter_mutex); // השמד את המוטקס בסיום
    return 0;
}
```
המוטקס מבטיח שבכל רגע נתון, רק תהליכון אחד יוכל להיכנס לקטע הקריטי ולשנות את `global_counter`. תהליכונים אחרים שינסו להיכנס יחסמו עד שהמוטקס ישוחרר. זה מבטיח שהפעולה `global_counter++` תבוצע באופן אטומי מנקודת מבטם של התהליכונים, וכל העדכונים יישמרו, מה שיוביל לערך סופי נכון ועקבי של 500,000.

