        if (pthread_create(&threads[i], NULL, incrementer, NULL) != 0) {
            perror("Failed to create thread");
            pthread_mutex_destroy(&mutex); // שחרור המוטקס במקרה של כשל
            return 1;
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            pthread_mutex_destroy(&mutex); // שחרור המוטקס במקרה של כשל
            return 1;
        }
    }

    pthread_mutex_destroy(&mutex); // שחרור המוטקס בסיום

    printf("Final counter value: %d\n", counter);

    return 0;
}
```

**השפעה על ביצועים:**
הוספת מנגנון סנכרון כמו mutex מבטיחה נכונות, אך בדרך כלל באה על חשבון ביצועים. כל פעם שתהליכון רוצה לגשת למשתנה 'counter', הוא צריך לנעול את המוטקס. אם המוטקס כבר נעול על ידי תהליכון אחר, התהליכון המבקש ייכנס למצב המתנה (blocking) עד שהמוטקס ישוחרר. זה גורם לטוריזציה (serialization) של הגישה לקטע הקריטי (critical section), שבו ה-`counter++` מתבצע. כתוצאה מכך, במקום שכל התהליכונים יבצעו את פעולותיהם באופן מקבילי לחלוטין (אך שגוי), הם ימתינו בתור לגישה למשתנה המשותף. זה יאט את זמן הריצה הכולל של התוכנית, במיוחד כאשר ישנם תהליכונים רבים או כאשר קטע הקריטי ארוך יחסית. במקרה זה, הפעולה `counter++` היא קצרה מאוד, כך שההאטה תהיה בעיקר בגלל התקורה של קריאות ה-lock/unlock עצמן ועלויות החלפת הקשר (context switching) בין תהליכונים הממתינים למוטקס. עם זאת, נכונות התוצאה חשובה יותר מביצועים במקרים רבים, ולכן השימוש במוטקס הכרחי כאן.

