#include <stdio.h>
#include <pthread.h>
#include <unistd.h> // For usleep (not strictly needed for race, but good for context switching demo)

#define NUM_THREADS 5
#define ITERATIONS_PER_THREAD 100000

long long counter = 0; // Global shared variable

void* increment_counter(void* arg) {
    for (int i = 0; i < ITERATIONS_PER_THREAD; ++i) {
        counter++;
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    printf("Initial counter value: %lld\n", counter);

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, increment_counter, NULL) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return 1;
        }
    }

    printf("Final counter value: %lld\n", counter);
    printf("Expected counter value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

    return 0;
}

solution.explanation:
7.1. כן, קיימת בתוכנית זו בעיית מרוץ (Race Condition). הפעולה הקריטית היא העדכון של המשתנה הגלובלי `counter` באמצעות `counter++`. פעולה זו אינה אטומית, אלא מורכבת משלושה שלבים:
   1. קריאת הערך הנוכחי של `counter` לתוך רגיסטר.
   2. הגדלת הערך ברגיסטר באחד.
   3. כתיבת הערך המעודכן מהרגיסטר בחזרה ל-`counter` בזיכרון.
   כאשר מספר תהליכונים מנסים לבצע פעולה זו במקביל, ייתכן שיתרחש שילוב לא רצוי של הפעולות (interleaving), כך שעדכונים של תהליכון אחד ידרסו על ידי עדכונים של תהליכון אחר, מה שיוביל לאובדן עדכונים.

7.2. הערך הסופי הצפוי של המונה הוא `NUM_THREADS * ITERATIONS_PER_THREAD = 5 * 100000 = 500000`. כן, ייתכן שהתוכנית תדפיס ערך שונה מהערך הצפוי, וברוב המקרים הוא יהיה נמוך יותר. תרחיש לדוגמה שיוביל לערך שגוי:
   1. `counter` שווה ל-100.
   2. תהליכון A קורא את `counter` (מקבל 100). לפני שהוא מספיק להגדיל ולכתוב, מתבצע מיתוג הקשר.
   3. תהליכון B קורא את `counter` (גם הוא מקבל 100).
   4. תהליכון B מגדיל את ערכו ל-101 וכותב אותו בחזרה ל-`counter`. כעת `counter` שווה 101.
   5. תהליכון A ממשיך מאיפה שהפסיק, מגדיל את ערכו (100) ל-101 וכותב אותו בחזרה ל-`counter`. כעת `counter` עדיין שווה 101.
   במקרה זה, שתי פעולות הגדלה בוצעו, אך `counter` גדל רק באחד, מה שמהווה אובדן של עדכון.

7.3. כדי לפתור את בעיית המרוץ, ניתן להשתמש במנעול (Mutex – Mutual Exclusion). מנעול מבטיח שרק תהליכון אחד יוכל להיכנס לקטע קריטי (critical section) בכל רגע נתון. העיקרון הוא כזה:
   1. לפני כל גישה למשתנה המשותף `counter` בתוך הקטע הקריטי, התהליכון מנסה לנעול את המוטקס (באמצעות `pthread_mutex_lock`).
   2. אם המוטקס פנוי, התהליכון נועל אותו וממשיך לבצע את הפעולות בקטע הקריטי.
   3. אם המוטקס נעול על ידי תהליכון אחר, התהליכון הנוכחי נחסם (מושהה) עד שהמוטקס ישוחרר.
   4. לאחר שהתהליכון מסיים את הפעולות בקטע הקריטי, הוא משחרר את המוטקס (באמצעות `pthread_mutex_unlock`), ובכך מאפשר לתהליכונים אחרים שניסו להיכנס לקטע הקריטי להמשיך.
   פעולה זו מבטיחה שכל עדכון ל-`counter` יתבצע באופן אטומי, ללא הפרעה מתהליכונים אחרים.

7.4. קטע הקוד המתוקן:
```c
#include <stdio.h>
#include <pthread.h>

#define NUM_THREADS 5
#define ITERATIONS_PER_THREAD 100000

long long counter = 0; // Global shared variable
pthread_mutex_t counter_mutex; // Declare a mutex

void* increment_counter(void* arg) {
    for (int i = 0; i < ITERATIONS_PER_THREAD; ++i) {
        pthread_mutex_lock(&counter_mutex); // Lock the mutex before accessing critical section
        counter++; // Critical section
        pthread_mutex_unlock(&counter_mutex); // Unlock the mutex after critical section
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    // Initialize the mutex
    if (pthread_mutex_init(&counter_mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        return 1;
    }

    printf("Initial counter value: %lld\n", counter);

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, increment_counter, NULL) != 0) {
            perror("Failed to create thread");
            // Clean up mutex before exiting on error
            pthread_mutex_destroy(&counter_mutex);
            return 1;
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            // Clean up mutex before exiting on error
            pthread_mutex_destroy(&counter_mutex);
            return 1;
        }
    }

    printf("Final counter value: %lld\n", counter);
    printf("Expected counter value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

    // Destroy the mutex after use
    pthread_mutex_destroy(&counter_mutex);

    return 0;
}
```

