#include <pthread.h>
#include <stdio.h>

// משתנים גלובליים
int counter1 = 0;
int counter2 = 0;
int total_sum = 0; // אמור תמיד להיות שווה ל- counter1 + counter2

// מנעולים
pthread_mutex_t mutex1;
pthread_mutex_t mutex2;

// פונקציות עזר לאתחול וניקוי
void init_system() {
    pthread_mutex_init(&mutex1, NULL);
    pthread_mutex_init(&mutex2, NULL);
}

void cleanup_system() {
    pthread_mutex_destroy(&mutex1);
    pthread_mutex_destroy(&mutex2);
}

// פונקציות לשינוי המונים
void increment_counter1() {
    pthread_mutex_lock(&mutex1);
    counter1++;
    total_sum++; // עדכון סכום כולל
    pthread_mutex_unlock(&mutex1);
}

void decrement_counter1() {
    pthread_mutex_lock(&mutex1);
    counter1--;
    total_sum--; // עדכון סכום כולל
    pthread_mutex_unlock(&mutex1);
}

void increment_counter2() {
    pthread_mutex_lock(&mutex2);
    counter2++;
    total_sum++; // עדכון סכום כולל
    pthread_mutex_unlock(&mutex2);
}

void decrement_counter2() {
    pthread_mutex_lock(&mutex2);
    counter2--;
    total_sum--; // עדכון סכום כולל
    pthread_mutex_unlock(&mutex2);
}

#include <stdio.h>
#include <pthread.h>

int g_counter = 0; // משתנה גלובלי משותף

void* thread_func_A(void* arg) {
    int N = *(int*)arg; // N יהיה 1 עבור השאלה
    for (int i = 0; i < N; ++i) {
        int local_val = g_counter;
        local_val = local_val * 2 + 1;
        g_counter = local_val;
    }
    return NULL;
}

void* thread_func_B(void* arg) {
    int N = *(int*)arg; // N יהיה 1 עבור השאלה
    for (int i = 0; i < N; ++i) {
        int local_val = g_counter;
        local_val = local_val + 3;
        g_counter = local_val;
    }
    return NULL;
}

int main() {
    pthread_t tid_A, tid_B;
    int N_val = 1;

    pthread_create(&tid_A, NULL, thread_func_A, &N_val);
    pthread_create(&tid_B, NULL, thread_func_B, &N_val);

    pthread_join(tid_A, NULL);
    pthread_join(tid_B, NULL);

    printf("Final g_counter: %d\n", g_counter);
    return 0;
}

solution.explanation:
8.1: עם N=1, המשתנה g_counter מאותחל ל-0. כל חוט מבצע פעולת קריאה-שינוי-כתיבה. להלן כל הערכים האפשריים וה-interleaving המובילים אליהם:

1.  **ערך סופי: 4**
    *   `g_counter` = 0 (התחלה)
    *   חוט A קורא: `local_val_A = 0`
    *   חוט A מחשב: `local_val_A = 0 * 2 + 1 = 1`
    *   חוט A כותב: `g_counter = 1`
    *   חוט B קורא: `local_val_B = 1`
    *   חוט B מחשב: `local_val_B = 1 + 3 = 4`
    *   חוט B כותב: `g_counter = 4`
    (חוט A מסיים את פעולתו לפני שחוט B מתחיל לקרוא את המשתנה המשותף)

2.  **ערך סופי: 7**
    *   `g_counter` = 0 (התחלה)
    *   חוט B קורא: `local_val_B = 0`
    *   חוט B מחשב: `local_val_B = 0 + 3 = 3`
    *   חוט B כותב: `g_counter = 3`
    *   חוט A קורא: `local_val_A = 3`
    *   חוט A מחשב: `local_val_A = 3 * 2 + 1 = 7`
    *   חוט A כותב: `g_counter = 7`
    (חוט B מסיים את פעולתו לפני שחוט A מתחיל לקרוא את המשתנה המשותף)

3.  **ערך סופי: 3**
    *   `g_counter` = 0 (התחלה)
    *   חוט A קורא: `local_val_A = 0`
    *   חוט B קורא: `local_val_B = 0`
    *   חוט A מחשב: `local_val_A = 1`
    *   חוט A כותב: `g_counter = 1`
    *   חוט B מחשב: `local_val_B = 3`
    *   חוט B כותב: `g_counter = 3`
    (שני החוטים קוראים את הערך הראשוני 0. חוט A כותב 1, אך מיד לאחר מכן חוט B כותב 3, ודורס את השינוי של חוט A. העדכון של חוט A אבד.)

4.  **ערך סופי: 1**
    *   `g_counter` = 0 (התחלה)
    *   חוט B קורא: `local_val_B = 0`
    *   חוט A קורא: `local_val_A = 0`
    *   חוט B מחשב: `local_val_B = 3`
    *   חוט B כותב: `g_counter = 3`
    *   חוט A מחשב: `local_val_A = 1`
    *   חוט A כותב: `g_counter = 1`
    (שני החוטים קוראים את הערך הראשוני 0. חוט B כותב 3, אך מיד לאחר מכן חוט A כותב 1, ודורס את השינוי של חוט B. העדכון של חוט B אבד.)

8.2: תופעת ה-Race Condition מתרחשת כאשר מספר חוטים ניגשים למשאב משותף (במקרה זה, המשתנה `g_counter`) בו-זמנית, ולפחות אחד מהם מבצע פעולת כתיבה, ללא מנגנון סנכרון מתאים. בקוד הנתון, כל חוט מבצע סדרת פעולות של קריאה (`local_val = g_counter`), שינוי (`local_val = ...`), וכתיבה (`g_counter = local_val`). סדר הפעולות אינו אטומי, כלומר, מערכת ההפעלה יכולה להחליף בין החוטים בכל נקודה. כאשר חוט אחד קורא את `g_counter` ולאחר מכן חוט אחר משנה וכותב ערך חדש ל-`g_counter` *לפני* שהחוט הראשון הספיק לכתוב את השינוי שלו, השינוי של אחד החוטים עלול להידרס ולהיאבד. הדבר מוביל לתוצאות בלתי צפויות ולא דטרמיניסטיות, כפי שמוצג בסעיף 8.1.

8.3: כדי למנוע את ה-Race Condition, יש להגן על הקטע הקריטי (הכולל את פעולות הקריאה, השינוי והכתיבה של `g_counter`) באמצעות מנעול (mutex). רק חוט אחד יוכל לתפוס את המנעול ולהיכנס לקטע הקריטי בכל רגע נתון. הנה הקוד המתוקן:

```c
#include <stdio.h>
#include <pthread.h>

int g_counter = 0; // משתנה גלובלי משותף
pthread_mutex_t counter_mutex; // מנעול להגנה על g_counter

void* thread_func_A_safe(void* arg) {
    int N = *(int*)arg;
    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&counter_mutex); // תפיסת מנעול
        int local_val = g_counter;
        local_val = local_val * 2 + 1;
        g_counter = local_val;
        pthread_mutex_unlock(&counter_mutex); // שחרור מנעול
    }
    return NULL;
}

void* thread_func_B_safe(void* arg) {
    int N = *(int*)arg;
    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&counter_mutex); // תפיסת מנעול
        int local_val = g_counter;
        local_val = local_val + 3;
        g_counter = local_val;
        pthread_mutex_unlock(&counter_mutex); // שחרור מנעול
    }
    return NULL;
}

int main() {
    pthread_t tid_A, tid_B;
    int N_val = 1;

    pthread_mutex_init(&counter_mutex, NULL); // אתחול המנעול

    pthread_create(&tid_A, NULL, thread_func_A_safe, &N_val);
    pthread_create(&tid_B, NULL, thread_func_B_safe, &N_val);

    pthread_join(tid_A, NULL);
    pthread_join(tid_B, NULL);

    printf("Final g_counter: %d\n", g_counter);

    pthread_mutex_destroy(&counter_mutex); // השמדת המנעול
    return 0;
}
```

לאחר התיקון עם המנעולים, לא יהיו יותר Race Conditions. עם זאת, מכיוון שפעולות החוטים אינן קומוטטיביות (כלומר, הסדר משנה), הערך הסופי של `g_counter` עדיין יהיה תלוי בסדר שבו החוטים יצליחו לתפוס את המנעול לראשונה. לכן, קיימים שני ערכים סופיים אפשריים, אך שניהם נכונים (לא אבדו עדכונים): 

1.  **אם חוט A תופס את המנעול ראשון, ואז חוט B:**
    *   `g_counter` מתחיל ב-0.
    *   חוט A משנה את `g_counter` ל-`0 * 2 + 1 = 1`.
    *   חוט B משנה את `g_counter` ל-`1 + 3 = 4`.
    *   **הערך הסופי יהיה 4.**

2.  **אם חוט B תופס את המנעול ראשון, ואז חוט A:**
    *   `g_counter` מתחיל ב-0.
    *   חוט B משנה את `g_counter` ל-`0 + 3 = 3`.
    *   חוט A משנה את `g_counter` ל-`3 * 2 + 1 = 7`.
    *   **הערך הסופי יהיה 7.**

שני הערכים (4 ו-7) הם תוצאות לגיטימיות של ריצה טורית של הפעולות, והמנעול מבטיח שרק אחת מהריצות הטוריות הללו תתרחש בפועל (במובן של סדר הגישה למשתנה המשותף), ללא איבוד נתונים.

