#include <stdio.h>
#include <pthread.h>
#include <stdbool.h>
#include <unistd.h> // for usleep

#define POOL_SIZE 3

bool resource_pool[POOL_SIZE]; // true if available, false if in use
pthread_mutex_t pool_mutex;
int available_resources = POOL_SIZE;

// Function to acquire a resource
int acquire_resource() {
    pthread_mutex_lock(&pool_mutex);
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (resource_pool[i]) {
            resource_pool[i] = false;
            available_resources--;
            printf("Acquired resource %d. Available: %d\n", i, available_resources);
            pthread_mutex_unlock(&pool_mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
    return -1; // No resource available
}

// Function to release a resource
void release_resource(int r_id) {
    if (r_id >= 0 && r_id < POOL_SIZE) {
        pthread_mutex_lock(&pool_mutex);
        if (!resource_pool[r_id]) { // Ensure it was actually in use
            resource_pool[r_id] = true;
            available_resources++;
            printf("Released resource %d. Available: %d\n", r_id, available_resources);
        } else {
            printf("Error: Attempted to release an unacquired resource %d.\n", r_id);
        }
        pthread_mutex_unlock(&pool_mutex);
    }
}

// Worker thread
void* worker_thread(void* arg) {
    for (int i = 0; i < 5; ++i) {
        int r = acquire_resource();
        if (r != -1) {
            printf("Worker %ld: Using resource %d...\n", (long)arg, r);
            usleep(20000 + (long)arg * 1000); // Simulate work with resource
            release_resource(r);
        } else {
            printf("Worker %ld: No resource available, waiting...\n", (long)arg);
            usleep(50000); // Wait and try again
        }
    }
    return NULL;
}

// Monitor thread - checks if `available_resources` matches the actual count
void* monitor_thread(void* arg) {
    for (int i = 0; i < 10; ++i) {
        usleep(30000); // Monitor periodically
        // Problematic check
        if (available_resources < POOL_SIZE) { // Check outside mutex
            int actual_in_use = 0;
            for (int j = 0; j < POOL_SIZE; ++j) {
                if (!resource_pool[j]) { // Accessing resource_pool without mutex
                    actual_in_use++;
                }
            }
            int actual_available = POOL_SIZE - actual_in_use;

            pthread_mutex_lock(&pool_mutex);
            printf("Monitor %ld: available_resources=%d, actual_available=%d. Mismatch? %s\n", 
                   (long)arg, available_resources, actual_available, 
                   (available_resources != actual_available) ? "YES!" : "No.");
            pthread_mutex_unlock(&pool_mutex);
        } else {
             pthread_mutex_lock(&pool_mutex);
             printf("Monitor %ld: All resources available (%d).\n", (long)arg, available_resources);
             pthread_mutex_unlock(&pool_mutex);
        }
    }
    return NULL;
}

int main() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        resource_pool[i] = true; // All resources initially available
    }
    pthread_mutex_init(&pool_mutex, NULL);

    pthread_t worker_tids[4];
    pthread_t mon_tid;

    for (long i = 0; i < 4; ++i) {
        pthread_create(&worker_tids[i], NULL, worker_thread, (void*)(i + 1));
    }
    pthread_create(&mon_tid, NULL, monitor_thread, (void*)99L);

    for (int i = 0; i < 4; ++i) {
        pthread_join(worker_tids[i], NULL);
    }
    pthread_join(mon_tid, NULL);

    printf("Final available resources: %d\n", available_resources);
    pthread_mutex_destroy(&pool_mutex);
    return 0;
}

#include <pthread.h>
#include <stdio.h>

// Shared data structure
typedef struct {
    int counter1;
    int counter2;
    pthread_mutex_t mutex_c1; // Protects counter1
    pthread_mutex_t mutex_c2; // Protects counter2
} SharedCounters;

SharedCounters global_data;

// Function to initialize shared data and mutexes
void init_shared_counters() {
    global_data.counter1 = 0;
    global_data.counter2 = 0;
    pthread_mutex_init(&global_data.mutex_c1, NULL);
    pthread_mutex_init(&global_data.mutex_c2, NULL);
}

// Function to clean up mutexes
void cleanup_shared_counters() {
    pthread_mutex_destroy(&global_data.mutex_c1);
    pthread_mutex_destroy(&global_data.mutex_c2);
}

// Thread function 1: Updates both counters
void* thread_updater(void* arg) {
    int iterations = *(int*)arg;
    for (int i = 0; i < iterations; ++i) {
        pthread_mutex_lock(&global_data.mutex_c1);
        global_data.counter1++;
        pthread_mutex_lock(&global_data.mutex_c2);
        global_data.counter2++;
        pthread_mutex_unlock(&global_data.mutex_c2);
        pthread_mutex_unlock(&global_data.mutex_c1);
    }
    return NULL;
}

// Thread function 2: Reads sum and conditionally resets
void* thread_monitor(void* arg) {
    int limit = *(int*)arg;
    for (int i = 0; i < 1000; ++i) { // Monitor multiple times
        pthread_mutex_lock(&global_data.mutex_c2); // Different order
        int current_c2 = global_data.counter2;
        pthread_mutex_lock(&global_data.mutex_c1);
        int current_c1 = global_data.counter1;

        if ((current_c1 + current_c2) > limit) {
            global_data.counter1 = 0;
            global_data.counter2 = 0;
        }
        pthread_mutex_unlock(&global_data.mutex_c1);
        pthread_mutex_unlock(&global_data.mutex_c2);
    }
    return NULL;
}

/* Example main function to run the threads:
int main() {
    init_shared_counters();
    pthread_t t1, t2;
    int iterations = 100000; // Large number to increase chance of issues
    int limit = 50;         // Reset limit

    pthread_create(&t1, NULL, thread_updater, &iterations);
    pthread_create(&t2, NULL, thread_monitor, &limit);

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    printf("Final counter1: %d, counter2: %d\n", global_data.counter1, global_data.counter2);
    cleanup_shared_counters();
    return 0;
}
*/

solution.explanation:
1. **בעיות סנכרון:**
    *   **קיפאון (Deadlock):** כן, קיים קיפאון. `thread_updater` מנסה לתפוס את `mutex_c1` ואז את `mutex_c2`. `thread_monitor` מנסה לתפוס את `mutex_c2` ואז את `mutex_c1`. אם `thread_updater` יתפוס את `mutex_c1` ו-`thread_monitor` יתפוס את `mutex_c2` בו זמנית, שניהם יחסמו בניסיון לתפוס את המנעול השני, מה שיוביל לקיפאון.
    *   **תנאי מירוץ (Race Condition):**
        *   **על סכום המונים:** במימוש הנתון, `thread_monitor` תופס את שני המנעולים לפני שהוא קורא את שני המונים. כל עוד שני המנעולים מוחזקים, אף חוט אחר לא יכול לשנות אף אחד מהמונים. לכן, הקריאה של `current_c1` ו-`current_c2` *בתוך* `thread_monitor` עצמה היא אטומית מבחינת הגישה למונים, ואין תנאי מירוץ על הסכום *בזמן החישוב שלו בתוך `thread_monitor`*. עם זאת, בשל הקיפאון, המערכת לא תגיע בהכרח למצב יציב.
        *   **על ערכים סופיים:** הערכים הסופיים של המונים אינם ניתנים לחיזוי מדויק. הם תלויים בסדר הריצה של החוטים ובתזמון האיפוס על ידי `thread_monitor`. זהו חוסר דטרמיניזם לגיטימי בהתאם למדיניות האיפוס, ולא תנאי מירוץ קלאסי במובן של נתונים שגויים, אך מצביע על כך שהמערכת אינה דטרמיניסטית מבחינת ערכי הסיום.

2. **עקביות תוצאות סופיות (בהנחה שאין קיפאון):**
    *   **סכום נצפה:** כן, הסכום של `counter1 + counter2` כפי שהוא נצפה על ידי `thread_monitor` הוא תמיד סכום של מונים עקביים. הסיבה היא ש-`thread_monitor` תופס את שני המנעולים (`mutex_c2` ואז `mutex_c1`) לפני שהוא קורא את שני המונים. כל עוד שני המנעולים מוחזקים, אף חוט אחר לא יכול לשנות אף אחד מהמונים, ובכך מובטחת עקביות של צמד הערכים הנקראים באותו רגע.
    *   **ערכים סופיים ניתנים לחיזוי:** לא, הערכים הסופיים של `counter1` ו-`counter2` אינם ניתנים לחיזוי מדויק. הם יהיו איפשהו בין 0 ל-`iterations` (הערך המקסימלי ללא איפוס), וזה תלוי במספר הפעמים ש-`thread_monitor` יבצע איפוס, ובאיזה שלב של הספירה הוא יבצע זאת. זהו מצב לא דטרמיניסטי לגיטימי של המערכת ולא תנאי מירוץ.

3. **תיקון הקוד:**
    הפתרון העיקרי למניעת קיפאון במצב כזה הוא להבטיח שכל החוטים התופסים מספר מנעולים יעשו זאת באותו סדר קנוני. במקרה זה, נבחר סדר `mutex_c1` ואז `mutex_c2`.
    כדי למנוע תנאי מירוץ על הסכום (אם הגישה הייתה מתבצעת ללא החזקת שני המנעולים בו-זמנית), יש לוודא שקריאת שני המונים (וכל פעולה תלויה בהם כמו איפוס) תתבצע תחת הגנה של שני המנעולים בו זמנית. במימוש הנתון, `thread_monitor` כבר מחזיק את שני המנעולים לפני חישוב הסכום, אך סדר תפיסת המנעולים שונה, וזהו מקור הקיפאון.

    **קוד מתוקן:**

    ```c
    // thread_updater מתוקן (ללא שינוי בסדר, אך חשוב שהסדר יהיה קנוני)
    void* thread_updater(void* arg) {
        int iterations = *(int*)arg;
        for (int i = 0; i < iterations; ++i) {
            pthread_mutex_lock(&global_data.mutex_c1); // תמיד קודם m1
            pthread_mutex_lock(&global_data.mutex_c2); // ואז m2
            global_data.counter1++;
            global_data.counter2++;
            pthread_mutex_unlock(&global_data.mutex_c2);
            pthread_mutex_unlock(&global_data.mutex_c1);
        }
        return NULL;
    }

    // thread_monitor מתוקן
    void* thread_monitor(void* arg) {
        int limit = *(int*)arg;
        for (int i = 0; i < 1000; ++i) {
            pthread_mutex_lock(&global_data.mutex_c1); // תמיד קודם m1
            pthread_mutex_lock(&global_data.mutex_c2); // ואז m2

            int current_c1 = global_data.counter1;
            int current_c2 = global_data.counter2;

            if ((current_c1 + current_c2) > limit) {
                global_data.counter1 = 0;
                global_data.counter2 = 0;
            }
            pthread_mutex_unlock(&global_data.mutex_c2);
            pthread_mutex_unlock(&global_data.mutex_c1);
        }
        return NULL;
    }
    ```

    התיקון מבטיח ששני החוטים תמיד ינסו לתפוס את המנעולים באותו סדר (`mutex_c1` ואז `mutex_c2`), ובכך מונע קיפאון. כמו כן, בתוך כל אחד מהקטעים הקריטיים, שני המונים מוגנים בו זמנית, מה שמבטיח עקביות של קריאה וכתיבה של צמדי המונים.

