#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// מבנה לצומת ברשימה
typedef struct Node {
    int data;
    struct Node* next;
} Node;

// מבנה לרשימה מקושרת משותפת
typedef struct List {
    Node* head;
    Node* tail;
    pthread_mutex_t head_lock;
    pthread_mutex_t tail_lock;
} List;

// אתחול הרשימה
void list_init(List* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->head_lock, NULL);
    pthread_mutex_init(&list->tail_lock, NULL);
}

// הוספת איבר לראש הרשימה
void list_add_head(List* list, int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate new node");
        exit(EXIT_FAILURE);
    }
    new_node->data = value;
    new_node->next = NULL;

    pthread_mutex_lock(&list->head_lock);
    if (list->head == NULL) { // הרשימה הייתה ריקה לפני ההוספה
        list->head = new_node;
        // נדרש לעדכן את list->tail, המוגן ע"י tail_lock
        pthread_mutex_lock(&list->tail_lock);
        list->tail = new_node;
        pthread_mutex_unlock(&list->tail_lock);
    } else {
        new_node->next = list->head;
        list->head = new_node;
    }
    pthread_mutex_unlock(&list->head_lock);
}

// הסרת איבר מסוף הרשימה
int list_remove_tail(List* list) {
    int value = -1; // ערך ברירת מחדל לכישלון

    pthread_mutex_lock(&list->tail_lock);

    if (list->head == NULL) { // הרשימה ריקה
        pthread_mutex_unlock(&list->tail_lock);
        return value;
    }

    if (list->head == list->tail) { // הרשימה מכילה איבר יחיד
        value = list->head->data;
        free(list->head);
        // נדרש לעדכן את list->head ל-NULL, המוגן ע"י head_lock
        pthread_mutex_lock(&list->head_lock);
        list->head = NULL;
        pthread_mutex_unlock(&list->head_lock);
        list->tail = NULL; // list->tail מוגן ע"י tail_lock
    } else {
        Node* current = list->head;
        while (current->next != list->tail) {
            current = current->next;
        }
        value = list->tail->data;
        free(list->tail);
        list->tail = current;
        list->tail->next = NULL;
    }
    pthread_mutex_unlock(&list->tail_lock);
    return value;
}

typedef struct {
    int balance;
    pthread_mutex_t mutex;
    int id; // For consistent locking order
} BankAccount;

// Global variables (assume initialized correctly by init_bank_system)
// BankAccount accounts[NUM_ACCOUNTS];
// int global_total_balance; // Sum of all accounts.balance
// pthread_mutex_t global_total_balance_mutex;

bool transfer_problematic(BankAccount* from_acc, BankAccount* to_acc, int amount) {
    if (from_acc == to_acc || amount <= 0) {
        return false; // Invalid transfer
    }

    // Acquire locks in a consistent order to prevent deadlock
    BankAccount *first_lock_acc = (from_acc->id < to_acc->id) ? from_acc : to_acc;
    BankAccount *second_lock_acc = (from_acc->id < to_acc->id) ? to_acc : from_acc;

    pthread_mutex_lock(&first_lock_acc->mutex);
    pthread_mutex_lock(&second_lock_acc->mutex);

    bool success = false;
    if (from_acc->balance >= amount) {
        from_acc->balance -= amount;
        // At this point, from_acc->balance has been updated, but to_acc->balance has not.
        // The sum of from_acc->balance and to_acc->balance is temporarily inconsistent.
        // The global_total_balance variable is not updated by this function
        // as a transfer is a zero-sum operation for the total system balance.
        to_acc->balance += amount;
        success = true;
    }

    pthread_mutex_unlock(&second_lock_acc->mutex);
    pthread_mutex_unlock(&first_lock_acc->mutex);

    return success;
}

solution.explanation:
פונקציית `transfer_problematic` אינה שומרת על האינווריאנט לפיו `global_total_balance` תמיד שווה לסכום היתרות של כל החשבונות במערכת, אם קיים חוט אחר המנסה לבדוק או לחשב את סכום היתרות הכולל של המערכת.

**תרחיש מירוץ (Race Condition):**
הבעיה נובעת מכך שהפונקציה מבצעת שני עדכונים נפרדים (הפחתה מחשבון המקור והוספה לחשבון היעד) כאשר ביניהם ישנו חלון זמן קריטי. למרות שהמנעולים של שני החשבונות נתפסים בו-זמנית (בסדר עקבי למניעת קיפאון), האינווריאנט הגלובלי (סכום כל החשבונות) מושפע באופן זמני. העברה היא פעולה סכום-אפס מבחינת סך הכסף במערכת, ולכן `global_total_balance` לא אמור להשתנות.

נניח שחוט (Thread A) מריץ `transfer_problematic(acc1, acc2, 10)`. נניח בהתחלה `acc1.balance = 100`, `acc2.balance = 100`, ו-`global_total_balance = 200`. 
1. Thread A תופס את המנעולים של `acc1` ו-`acc2` (בהתאם לסדר ה-ID שלהם).
2. Thread A מבצע `acc1->balance -= 10;` (כעת `acc1.balance = 90`).
3. **כאן נפתח חלון מירוץ:** אם בשלב זה חוט אחר (Thread B) מנסה לבדוק את האינווריאנט הגלובלי על ידי סכימת יתרות כל החשבונות (למשל, פונקציה כמו `get_total_system_balance_by_summing_accounts()` שתופסת מנעולים של חשבונות בודדים בזה אחר זה וסוכמת את יתרותיהם), הוא יראה את `acc1.balance = 90` ואת `acc2.balance = 100` (אם הוא קורא את `acc2.balance` לפני ש-Thread A מעדכן אותו). סכום היתרות שיחושב על ידי Thread B יהיה `90 + 100 = 190`, וזה אינו תואם את `global_total_balance` (שעדיין 200), וגם אינו הסכום הנכון של המערכת (שצריך להיות 200).
4. Thread A ממשיך ומבצע `to_acc->balance += 10;` (כעת `acc2.balance = 110`).
5. Thread A משחרר את המנעולים של `acc1` ו-`acc2`.

הבעיה היא שהאינווריאנט הגלובלי נשבר באופן זמני, וחוטים אחרים יכולים להבחין בכך ולקבל נתונים לא עקביים.

**פתרון מתוקן:**
כדי לשמור על האינווריאנט הגלובלי, יש צורך להגן על כל פעולה שמשנה את יתרות החשבונות (ובכך משפיעה על הסכום הכולל) באמצעות מנעול גלובלי, או להבטיח אטומיות ברמה גבוהה יותר. מכיוון שהעברה היא פעולה סכום-אפס, `global_total_balance` אינו משתנה, אך כדי למנוע מחוטים אחרים לראות מצב ביניים לא עקבי, יש לתפוס את המנעול הגלובלי `global_total_balance_mutex` לפני תפיסת מנעולי החשבונות, ולשחרר אותו רק לאחר סיום כל העדכונים.

```c
bool transfer_fixed(BankAccount* from_acc, BankAccount* to_acc, int amount) {
    if (from_acc == to_acc || amount <= 0) {
        return false;
    }

    // Acquire the global lock first to ensure system-wide atomicity for the invariant.
    // This prevents other threads from observing an inconsistent state
    // of the total sum of accounts during the transfer.
    pthread_mutex_lock(&global_total_balance_mutex);

    // Acquire account locks in a consistent order to prevent deadlock
    BankAccount *first_lock_acc = (from_acc->id < to_acc->id) ? from_acc : to_acc;
    BankAccount *second_lock_acc = (from_acc->id < to_acc->id) ? to_acc : from_acc;

    pthread_mutex_lock(&first_lock_acc->mutex);
    pthread_mutex_lock(&second_lock_acc->mutex);

    bool success = false;
    if (from_acc->balance >= amount) {
        from_acc->balance -= amount;
        to_acc->balance += amount;
        // global_total_balance does not change during a transfer, so no explicit update is needed here.
        // The global lock ensures that any read of global_total_balance or sum of accounts
        // will see a consistent state.
        success = true;
    }

    pthread_mutex_unlock(&second_lock_acc->mutex);
    pthread_mutex_unlock(&first_lock_acc->mutex);

    pthread_mutex_unlock(&global_total_balance_mutex);
    return success;
}
```

**הערה חשובה:** פתרון זה מונע את תרחיש המירוץ על האינווריאנט הגלובלי, אך הופך את `global_total_balance_mutex` לנקודת צוואר בקבוק (bottleneck) שעלולה לפגוע בביצועים, שכן כל פעולת העברה (ואולי גם פעולות אחרות שמשנות את סכום היתרות הכולל) תדרוש תפיסה של מנעול גלובלי זה. פתרונות מתקדמים יותר עשויים לכלול שימוש במנעולים לקריאה/כתיבה (Reader-Writer Locks) או גישות ללא מנעולים (lock-free) עבור סכימה גלובלית, אך אלו מורכבים יותר ליישום.

