```c
#include <stdio.h>
#include <pthread.h>
#include <unistd.h> // For sleep

pthread_mutex_t mutex;
pthread_cond_t cond;
int shared_resource_ready = 0; // Predicate for the condition variable

void* worker_thread(void* arg) {
    printf("Worker thread: Waiting for resource to be ready...\n");
    pthread_mutex_lock(&mutex);
    if (!shared_resource_ready) { // Potential issue here
        printf("Worker thread: Condition not met, waiting...\n");
        pthread_cond_wait(&cond, &mutex);
        printf("Worker thread: Woken up.\n");
    }
    printf("Worker thread: Resource is ready, processing data.\n");
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* producer_thread(void* arg) {
    printf("Producer thread: Preparing resource...\n");
    sleep(1); // Simulate work
    pthread_mutex_lock(&mutex);
    shared_resource_ready = 1;
    printf("Producer thread: Resource ready. Signaling worker.\n");
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    pthread_t producer_tid, worker_tid;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    pthread_create(&worker_tid, NULL, worker_thread, NULL);
    pthread_create(&producer_tid, NULL, producer_thread, NULL);

    pthread_join(worker_tid, NULL);
    pthread_join(producer_tid, NULL);

    printf("Main thread: All threads finished.\n");

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);
    return 0;
}
