#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h> // For usleep
#include <stdbool.h> // For bool type

#define NUM_WORKERS 3
#define BATCH_SIZE 5
#define TOTAL_BATCHES 2

pthread_mutex_t mutex;
pthread_cond_t worker_cond; // Workers wait for tasks
pthread_cond_t main_cond;   // Main waits for batch completion

int tasks_in_queue = 0;
int tasks_processed_in_batch = 0;
bool stop_threads = false;

void *worker_function(void *arg) {
    long id = (long)arg;
    printf("Worker %ld started.\n", id);

    pthread_mutex_lock(&mutex);
    while (!stop_threads) {
        // Wait for tasks
        while (tasks_in_queue == 0 && !stop_threads) {
            printf("Worker %ld waiting for tasks.\n", id);
            pthread_cond_wait(&worker_cond, &mutex);
        }

        if (stop_threads) {
            break; // Exit loop if signaled to stop
        }

        tasks_in_queue--;
        printf("Worker %ld processing task. Tasks remaining in queue: %d\n", id, tasks_in_queue);

        pthread_mutex_unlock(&mutex); // Unlock while doing "work"
        usleep(100 * 1000); // Simulate work
        pthread_mutex_lock(&mutex); // Lock again to update shared state

        tasks_processed_in_batch++;
        printf("Worker %ld completed task. Tasks processed in batch: %d\n", id, tasks_processed_in_batch);

        if (tasks_processed_in_batch == BATCH_SIZE) {
            printf("Worker %ld signaling main for batch completion.\n", id);
            pthread_cond_signal(&main_cond); // Signal main thread
        }
    }
    pthread_mutex_unlock(&mutex);
    printf("Worker %ld exiting.\n", id);
    return NULL;
}

int main() {
    pthread_t workers[NUM_WORKERS];
    long i;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&worker_cond, NULL);
    pthread_cond_init(&main_cond, NULL);

    for (i = 0; i < NUM_WORKERS; ++i) {
        pthread_create(&workers[i], NULL, worker_function, (void *)(i + 1));
    }

    for (int batch = 1; batch <= TOTAL_BATCHES; ++batch) {
        pthread_mutex_lock(&mutex);
        tasks_processed_in_batch = 0; // Reset for new batch
        tasks_in_queue = BATCH_SIZE;  // Add tasks for workers
        printf("\nMain: Dispatching Batch %d with %d tasks.\n", batch, BATCH_SIZE);
        pthread_cond_broadcast(&worker_cond); // Wake up all workers

        // Main waits for all tasks in the current batch to be processed
        while (tasks_processed_in_batch < BATCH_SIZE) {
            printf("Main: Waiting for Batch %d completion. Processed: %d/%d\n", batch, tasks_processed_in_batch, BATCH_SIZE);
            pthread_cond_wait(&main_cond, &mutex);
        }
        printf("Main: Batch %d completed. All %d tasks processed.\n", batch, BATCH_SIZE);
        pthread_mutex_unlock(&mutex);
    }

    // Signal workers to stop and join them
    pthread_mutex_lock(&mutex);
    stop_threads = true;
    printf("\nMain: Signaling workers to stop.\n");
    pthread_cond_broadcast(&worker_cond); // Wake up all workers to check stop_threads flag
    pthread_mutex_unlock(&mutex);

    for (i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(workers[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&worker_cond);
    pthread_cond_destroy(&main_cond);

    printf("Main: All workers joined. Exiting.\n");
    return 0;
}

