#define NUM_THREADS 3 // מספר תהליכי עובד לצורך דוגמה קצרה

pthread_mutex_t mutex = PTHREAD_MUTIALIZER;
pthread_cond_t start_cond = PTHREAD_COND_INITIALIZER; // משתנה תנאי לאות התחלה
pthread_cond_t done_cond = PTHREAD_COND_INITIALIZER;  // משתנה תנאי לאות סיום עבודה

int threads_ready = 0;          // מספר תהליכים מוכנים להתחלה
int threads_finished = 0;       // מספר תהליכים שסיימו עבודה
int start_signal_received = 0;  // דגל המציין אם אות ההתחלה נשלח

void *worker_thread(void *arg) {
    long id = (long)arg;

    // --- חלק 1: המתנה לאות התחלה ---
    pthread_mutex_lock(&mutex);
    threads_ready++;
    printf("תהליך עובד %ld: מוכן. סה\"כ מוכנים: %d\n", id, threads_ready);

    // אם כל העובדים מוכנים, סמן לתהליך הראשי
    if (threads_ready == NUM_THREADS) {
        pthread_cond_signal(&start_cond); // סמן לראשי שכולם מוכנים
    }

    // המתן לאות התחלה מהתהליך הראשי
    while (!start_signal_received) { // לולאה לטיפול בהתעוררויות שווא
        pthread_cond_wait(&start_cond, &mutex); // נכון: ממתין על start_cond
    }
    pthread_mutex_unlock(&mutex);

    // --- חלק 2: ביצוע עבודה ---
    printf("תהליך עובד %ld: מתחיל עבודה...\n", id);
    sleep(1); // הדמיית עבודה
    printf("תהליך עובד %ld: סיים עבודה.\n", id);

    // --- חלק 3: סימון סיום עבודה ---
    pthread_mutex_lock(&mutex);
    threads_finished++;
    printf("תהליך עובד %ld: סיים. סה\"כ סיימו: %d\n", id, threads_finished);

    if (threads_finished == NUM_THREADS) {
        pthread_cond_signal(&done_cond); // סמן לראשי שכולם סיימו
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    long i;

    // יצירת תהליכי עובד
    for (i = 0; i < NUM_THREADS; i++) {
