    }

    // --- התהליך הראשי ממתין שכל העובדים יהיו מוכנים ---
    pthread_mutex_lock(&mutex);
    printf("ראשי: ממתין שעובדים יהיו מוכנים...\n");
    while (threads_ready < NUM_THREADS) {
        pthread_cond_wait(&start_cond, &mutex);
    }
    printf("ראשי: כל העובדים מוכנים. שולח אות התחלה...\n");
    start_signal_received = 1;
    pthread_cond_broadcast(&done_cond); // !!! שגיאה: אמור להיות start_cond
    pthread_mutex_unlock(&mutex);

    // --- התהליך הראשי ממתין שכל העובדים יסיימו ---
    pthread_mutex_lock(&mutex);
    printf("ראשי: ממתין שעובדים יסיימו...\n");
