    }
    printf("ראשי: כל העובדים סיימו. יוצא.\n");
    pthread_mutex_unlock(&mutex);

    // הצטרפות לחוטים (לצורך ניקוי משאבים, לא קריטי לשאלה זו)
    for (i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&start_cond);
    pthread_cond_destroy(&done_cond);

    return 0;
}

#include <stdio.h>
#include <pthread.h>

#define NUM_WORKERS 5
#define THRESHOLD 3
#define CYCLES 2

int shared_counter = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t workers_wait_cond = PTHREAD_COND_INITIALIZER;
pthread_cond_t coordinator_signal_cond = PTHREAD_COND_INITIALIZER;

void *worker_thread(void *arg) {
    int id = *(int*)arg; // id is not used in the final logic but kept from original structure
    for (int i = 0; i < CYCLES; ++i) {
        pthread_mutex_lock(&mutex);
        shared_counter++;
        if (shared_counter == THRESHOLD) {
            pthread_cond_signal(&coordinator_signal_cond);
        }
        while (shared_counter != 0) {
            pthread_cond_wait(&workers_wait_cond, &mutex);
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void *coordinator_thread(void *arg) {
    for (int i = 0; i < CYCLES; ++i) {
        pthread_mutex_lock(&mutex);
        while (shared_counter < THRESHOLD) {
            pthread_cond_wait(&coordinator_signal_cond, &mutex);
        }
        printf("Coordinator: threshold met (%d), resetting counter and broadcasting to workers.\n", shared_counter);
        shared_counter = 0;
        pthread_cond_broadcast(&workers_wait_cond);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    pthread_t workers[NUM_WORKERS];
    pthread_t coordinator;
    int worker_ids[NUM_WORKERS];

    pthread_create(&coordinator, NULL, coordinator_thread, NULL);

    for (int i = 0; i < NUM_WORKERS; ++i) {
        worker_ids[i] = i + 1;
        pthread_create(&workers[i], NULL, worker_thread, &worker_ids[i]);
    }

    for (int i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(workers[i], NULL);
    }
    pthread_join(coordinator, NULL);

    return 0;
}

