#include <pthread.h>
#include <stdio.h>
#include <stdlib.h> // For exit

// Shared resources
int buffer = -1;
int count = 0; // 0: empty, 1: full
pthread_mutex_t mutex;
pthread_cond_t cond_producer; // Producer waits if buffer is full
pthread_cond_t cond_consumer; // Consumer waits if buffer is empty

void* producer(void* arg) {
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex);
        while (count == 1) { // Buffer is full, producer waits
            pthread_cond_wait(&cond_producer, &mutex);
        }
        buffer = i; // Produce item
        printf("Producer produced: %d\n", buffer);
        count = 1; // Mark buffer as full
        pthread_cond_signal(&cond_consumer); // Signal consumer that item is ready
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void* consumer(void* arg) {
    long sum = 0; // Use long for sum for safety with pointer casting
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex);
        while (count == 0) { // Buffer is empty, consumer waits
            pthread_cond_wait(&cond_consumer, &mutex);
        }
        sum += buffer; // Consume item
        printf("Consumer consumed: %d, current sum: %ld\n", buffer, sum);
        count = 0; // Mark buffer as empty
        pthread_cond_signal(&cond_producer); // Signal producer that buffer is empty
        pthread_mutex_unlock(&mutex);
    }
    printf("Final sum: %ld\n", sum);
    return (void*)sum; // Return sum as void*
}

int main() {
    setbuf(stdout, NULL); // Disable buffering for immediate output
    pthread_t prod_tid, cons_tid;

    // Initialize mutex and condition variables
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond_producer, NULL);
    pthread_cond_init(&cond_consumer, NULL);

    // Create threads
    pthread_create(&prod_tid, NULL, producer, NULL);
    pthread_create(&cons_tid, NULL, consumer, NULL);

    // Wait for threads to finish
    pthread_join(prod_tid, NULL);
    long final_sum_from_consumer;
    pthread_join(cons_tid, (void**)&final_sum_from_consumer);

    printf("Main thread received final sum: %ld\n", final_sum_from_consumer);

    // Destroy mutex and condition variables
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond_producer);
    pthread_cond_destroy(&cond_consumer);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h> // For sleep

#define NUM_THREADS 5

// משאבים משותפים
pthread_mutex_t mutex;
pthread_cond_t start_cond; // התהליכון הראשי מאותת לתהליכוני העבודה להתחיל
pthread_cond_t done_cond;  // תהליכוני העבודה מאותתים לתהליכון הראשי שסיימו
int ready_count = 0;       // כמה תהליכוני עבודה מוכנים להתחיל
int finished_count = 0;    // כמה תהליכוני עבודה סיימו
int start_work_flag = 0;   // דגל המציין שתהליכוני העבודה יכולים להתחיל

void *worker_thread(void *arg) {
    long id = (long)arg;

    pthread_mutex_lock(&mutex);
    ready_count++;
    printf("Worker %ld: Ready to start. (ready_count = %d)\n", id, ready_count);

    // המתן לאות מהתהליכון הראשי להתחיל
    while (!start_work_flag) {
        pthread_cond_wait(&start_cond, &mutex);
    }
    pthread_mutex_unlock(&mutex); // שחרור המנעול לפני ביצוע העבודה

    // הדמיית עבודה
    printf("Worker %ld: Starting work...\n", id);
    sleep(1 + (id % 2)); // הדמיית זמן עבודה משתנה
    printf("Worker %ld: Finished work.\n", id);

    pthread_mutex_lock(&mutex);
    finished_count++;
    printf("Worker %ld: Signaled done. (finished_count = %d)\n", id, finished_count);
    if (finished_count == NUM_THREADS) {
        pthread_cond_signal(&done_cond); // אות לתהליכון הראשי שכל העבודה הסתיימה
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    long i;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&start_cond, NULL);
    pthread_cond_init(&done_cond, NULL);

    // יצירת תהליכוני עבודה
    for (i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, worker_thread, (void *)i);
    }

    // התהליכון הראשי ממתין שכל תהליכוני העבודה יהיו מוכנים
    pthread_mutex_lock(&mutex);
    while (ready_count < NUM_THREADS) {
        pthread_mutex_unlock(&mutex); // שחרור המנעול כדי לאפשר לתהליכונים אחרים להתקדם
        usleep(10000); // המתנה קצרה
        pthread_mutex_lock(&mutex);
    }
    printf("Main: All workers are ready. Setting flag and signaling them to start.\n");
    start_work_flag = 1; // הגדרת הדגל
    pthread_cond_broadcast(&start_cond); // אות לכל תהליכוני העבודה להתחיל
    pthread_mutex_unlock(&mutex);

    // התהליכון הראשי ממתין שכל תהליכוני העבודה יסיימו
    pthread_mutex_lock(&mutex);
    while (finished_count < NUM_THREADS) {
        pthread_cond_wait(&done_cond, &mutex); // המתן עד שכל תהליכוני העבודה יסיימו
    }
    printf("Main: All workers have finished. Exiting.\n");
    pthread_mutex_unlock(&mutex);

    // צירוף תהליכונים
    for (i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&start_cond);
    pthread_cond_destroy(&done_cond);

    return 0;
}

#include <stdio.h>
