    if (arrived_count < NUM_THREADS) {
        // Wait for other threads to arrive
        pthread_cond_wait(&barrier_cond, &barrier_mutex);
        printf("Thread %ld: Woke up from barrier wait.\n", tid);
    } else {
        // Last thread arrived, signal all waiting threads
        printf("Thread %ld: Last thread arrived. Signaling ONE waiting thread.\n", tid);
        pthread_cond_signal(&barrier_cond); // INTENTIONAL ERROR: Should be broadcast
    }

    pthread_mutex_unlock(&barrier_mutex);

    printf("Thread %ld: Passed barrier and continuing.\n", tid);
    return NULL;
}

int main() {
