#define MAX_CONCURRENT_TASKS 3 // גודל קבוצה לדוגמא

// משתני סנכרון גלובליים
// ... יש למלא כאן ...

void* worker_task(void* arg) {
    // ... יש למלא כאן את לוגיקת חוט העבודה ...
    return NULL;
}

void* supervisor_thread(void* arg) {
