    return NULL;
}

int main() {
    // קוד אתחול ויצירת חוטים (לא נדרש למלא כחלק מהפתרון, אך חשוב להבנה)
    return 0;
}

solution.explanation:
הסבר הפתרון:

מטרת הפתרון היא לסנכרן בין חוטי עבודה (worker threads) לבין חוט מפקח (supervisor thread) כך ש:
1. לכל היותר MAX_CONCURRENT_TASKS חוטי עבודה ירוצו במקביל.
2. חוט המפקח יבצע פעולות איפוס וניקוי רק לאחר שכל חוטי העבודה בקבוצה הנוכחית סיימו את משימותיהם.
3. קבוצת משימות חדשה לא תתחיל לפני שחוט המפקח סיים את פעולותיו.

לצורך כך, אנו משתמשים במשתנים גלובליים הבאים:
- mutex: מנעול להגנה על משתנים משותפים (כמו active_tasks ו-batch_ready) מפני מצבי מירוץ.
- cond_task_can_start: משתנה תנאי שעליו ממתינים חוטי העבודה כאשר הם אינם יכולים להתחיל משימה חדשה (או בגלל שהגענו למספר המקסימלי של משימות במקביל, או בגלל שחוט המפקח מבצע איפוס).
- cond_supervisor_can_reset: משתנה תנאי שעליו ממתין חוט המפקח עד שכל חוטי העבודה בקבוצה הנוכחית יסיימו את משימותיהם.
- active_tasks: מונה את מספר המשימות הפעילות כרגע.
- batch_ready: דגל (flag) המציין האם קבוצת משימות חדשה יכולה להתחיל (1) או שחוט המפקח ממתין או מבצע איפוס (0).

קוד הפתרון:
```c
#include <pthread.h>
#include <stdio.h>
#include <unistd.h> // For sleep

#define MAX_CONCURRENT_TASKS 3 // Example batch size

// Global synchronization variables
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_task_can_start = PTHREAD_COND_INITIALIZER;
pthread_cond_t cond_supervisor_can_reset = PTHREAD_COND_INITIALIZER;

int active_tasks = 0;
int batch_ready = 1; // 1 means a new batch can start, 0 means supervisor is resetting or waiting

void* worker_task(void* arg) {
    long id = (long)arg;
    while (1) { // Simulate continuous work
        pthread_mutex_lock(&mutex);

        // Wait if max concurrent tasks reached or supervisor is resetting
        while (active_tasks >= MAX_CONCURRENT_TASKS || !batch_ready) {
            printf("Worker %ld: Waiting to start task (active_tasks=%d, batch_ready=%d)\n", id, active_tasks, batch_ready);
            pthread_cond_wait(&cond_task_can_start, &mutex);
        }

        active_tasks++;
        printf("Worker %ld: Started task. Active tasks: %d\n", id, active_tasks);

        pthread_mutex_unlock(&mutex);

        // Simulate work
        sleep(1 + (id % 2)); // Simulate varying task duration

        pthread_mutex_lock(&mutex);
        active_tasks--;
        printf("Worker %ld: Finished task. Active tasks: %d\n", id, active_tasks);

        // If this was the last task of the current batch and supervisor is waiting, signal the supervisor
        if (active_tasks == 0 && !batch_ready) {
            printf("Worker %ld: Last task of batch finished. Signaling supervisor.\n", id);
            pthread_cond_signal(&cond_supervisor_can_reset);
        }
        pthread_mutex_unlock(&mutex);
        sleep(1); // Small delay before trying next task
    }
    return NULL;
}

void* supervisor_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);

        // Indicate that a batch is no longer ready (prevent new tasks from starting)
        batch_ready = 0;
        printf("Supervisor: Batch not ready. Waiting for all tasks to finish (active_tasks=%d)\n", active_tasks);

        // Wait until all current tasks have finished
        while (active_tasks > 0) {
            pthread_cond_wait(&cond_supervisor_can_reset, &mutex);
        }

        printf("Supervisor: All tasks finished. Performing reset/cleanup.\n");
        pthread_mutex_unlock(&mutex);

        // Simulate reset/cleanup work
        sleep(2);

        pthread_mutex_lock(&mutex);
        // Reset state and allow new batch to start
        batch_ready = 1;
        printf("Supervisor: Reset complete. Signaling workers for new batch.\n");
        pthread_cond_broadcast(&cond_task_can_start); // Wake up all waiting workers
        pthread_mutex_unlock(&mutex);

        sleep(3); // Small delay before starting next batch cycle
    }
    return NULL;
}
```

מניעת מצבי מירוץ וקיפאון:
- מצבי מירוץ: כל הגישות למשתנים המשותפים (active_tasks, batch_ready) מוגנות על ידי המנעול mutex, מה שמונע מצבי מירוץ.
- קיפאון (Deadlock):
    - סדר נעילת המנעולים: יש רק מנעול אחד, כך שאין בעיה של סדר נעילה.
    - שחרור מנעול לפני המתנה: pthread_cond_wait משחרר את המנעול באופן אטומי לפני הכניסה למצב המתנה, ונועל אותו מחדש לאחר ההתעוררות. זה מונע קיפאון שבו חוט מחזיק מנעול וממתין לתנאי שחוט אחר יצר אך לא יכול לגשת למנעול כדי לאותת.
    - שימוש ב-while עבור תנאי ההמתנה: זה מבטיח שהחוט בודק מחדש את התנאי לאחר התעוררות, ומונע מצבים שבהם החוט ממשיך למרות שהתנאי כבר לא מתקיים (למשל, עקב התעוררות שווא או שינוי מהיר של המצב על ידי חוט אחר).

