#include <pthread.h>
#include <stdio.h>

#define MAX_RESOURCES 10

int available_resources = MAX_RESOURCES;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void acquire_resources(int count) {
    pthread_mutex_lock(&mutex);
    if (available_resources < count) {
        printf("Thread %lu waiting for %d resources. Available: %d\n", pthread_self(), count, available_resources);
        pthread_cond_wait(&cond, &mutex);
    }
    available_resources -= count;
    printf("Thread %lu acquired %d resources. Remaining: %d\n", pthread_self(), count, available_resources);
    pthread_mutex_unlock(&mutex);
}

void release_resources(int count) {
    pthread_mutex_lock(&mutex);
    available_resources += count;
    printf("Thread %lu released %d resources. Available: %d\n", pthread_self(), count, available_resources);
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

solution.explanation:
פתרון:

א. זיהוי וניתוח בעיות:
1.  **שימוש ב-`if` במקום ב-`while` ב-`acquire_resources`**: כאשר חוט מתעורר מ-`pthread_cond_wait`, ייתכנו שני מצבים שבהם התנאי שגרם לו להמתין עדיין אינו מתקיים:
    *   **התעוררות שווא (Spurious Wakeup)**: מערכת ההפעלה עשויה להעיר חוט ללא קשר לכך שהתנאי השתנה. אם החוט לא בודק מחדש את התנאי באמצעות לולאת `while`, הוא ימשיך בביצוע כאילו התנאי אכן התקיים, מה שיוביל למצב שגוי (לדוגמה, `available_resources` יהפוך לשלילי).
    *   **מרוץ (Race Condition) לאחר התעוררות**: גם אם חוט מתעורר כיוון שמשאבים שוחררו, ייתכן שחוט אחר (שהתעורר לפניו או שהיה פעיל) ירכוש את המשאבים הנדרשים *לפני* שהחוט הנוכחי יצליח לרכוש מחדש את המוטקס ולבדוק את התנאי. במצב כזה, אם החוט המקורי משתמש ב-`if`, הוא יתקדם בביצוע ללא בדיקה חוזרת של התנאי, וינסה לרכוש משאבים שאינם זמינים, מה שיוביל לחוסר תקינות.
    *   **דוגמה**: נניח `available_resources = 3`. חוט A צריך 5 משאבים וממתין. חוט B משחרר 5 משאבים, `available_resources` הופך ל-8. חוט A מתעורר. לפני שחוט A רוכש מחדש את המוטקס, חוט C רוכש 6 משאבים, ו-`available_resources` הופך ל-2. חוט A רוכש את המוטקס, אך בגלל ה-`if` הוא לא בודק מחדש את התנאי וממשיך לרכוש 5 משאבים, מה שיוביל ל-`available_resources = -3`.

2.  **שימוש ב-`pthread_cond_signal` במקום ב-`pthread_cond_broadcast` ב-`release_resources`**: כאשר משאבים משוחררים, ייתכן שיותר מחוט אחד מהחוטים הממתינים יוכל כעת להמשיך. שימוש ב-`pthread_cond_signal` מעיר רק חוט אחד. הדבר עלול להוביל ל:
    *   **רעב (Starvation) וחוסר יעילות**: אם החוט שהתעורר לא יכול עדיין להמשיך (לדוגמה, הוא צריך 7 משאבים, אך רק 5 התפנו), הוא יחזור להמתין. בינתיים, ייתכן שחוט אחר שהיה ממתין, וזקוק לכמות קטנה יותר של משאבים (לדוגמה, 2 משאבים), יכול היה להמשיך באופן מיידי. מכיוון שהוא לא התעורר, הוא נשאר רעב שלא לצורך, ומשאבים פנויים אינם מנוצלים ביעילות.
    *   **דוגמה**: `available_resources = 2`. חוט A צריך 5 משאבים וממתין. חוט B צריך 3 משאבים וממתין. חוט C משחרר 4 משאבים. `available_resources` הופך ל-6. `pthread_cond_signal` מעיר את חוט A. חוט A בודק (אפילו אם עם `while`), רואה שיש 6 משאבים, אך הוא צריך 5. הוא רוכש 5 משאבים, ו-`available_resources` הופך ל-1. חוט B עדיין ממתין, למרות שברגע ש-`available_resources` היה 6, הוא יכול היה לרכוש את 3 המשאבים שביקש. הוא ימשיך להמתין עד לאות נוסף.

ב. תיקונים והסבר:
1.  **תיקון ב-`acquire_resources`**: יש לשנות את ה-`if` ל-`while`:
    ```c
    void acquire_resources(int count) {
        pthread_mutex_lock(&mutex);
        while (available_resources < count) { // שינוי מ-if ל-while
            printf("Thread %lu waiting for %d resources. Available: %d\n", pthread_self(), count, available_resources);
            pthread_cond_wait(&cond, &mutex);
        }
        available_resources -= count;
        printf("Thread %lu acquired %d resources. Remaining: %d\n", pthread_self(), count, available_resources);
        pthread_mutex_unlock(&mutex);
    }
    ```
    **הסבר**: לולאת `while` מבטיחה שכל חוט שמתעורר יבדוק מחדש את התנאי (`available_resources < count`) *לפני* שהוא ממשיך בביצוע הקטע הקריטי. זה מונע מחוטים להמשיך כאשר התנאי אינו מתקיים עקב התעוררות שווא או שינוי במצב המשאבים על ידי חוט אחר, ובכך מבטיח את תקינות המערכת.

2.  **תיקון ב-`release_resources`**: יש לשנות את `pthread_cond_signal` ל-`pthread_cond_broadcast`:
    ```c
    void release_resources(int count) {
        pthread_mutex_lock(&mutex);
        available_resources += count;
        printf("Thread %lu released %d resources. Available: %d\n", pthread_self(), count, available_resources);
        pthread_cond_broadcast(&cond); // שינוי מ-pthread_cond_signal ל-pthread_cond_broadcast
        pthread_mutex_unlock(&mutex);
    }
    ```
    **הסבר**: שימוש ב-`pthread_cond_broadcast` מעיר את *כל* החוטים הממתינים על משתנה התנאי. לאחר מכן, כל חוט שהתעורר בודק את התנאי שלו באמצעות לולאת ה-`while` (כפי שתוקן בסעיף הקודם). זה מבטיח שכל חוט שיכול כעת לרכוש את המשאבים הנדרשים לו יתעורר וינסה לעשות זאת. זה מונע רעב של חוטים שיכולים היו להמשיך, ומאפשר ניצול יעיל יותר של המשאבים ברגע שהם מתפנים. אף על פי ש-`broadcast` עשוי לגרום ליותר החלפות הקשר (context switches) בטווח הקצר, הוא מבטיח הוגנות טובה יותר ומונע מצבי רעב במערכות מורכבות יותר שבהן מספר חוטים ממתינים לתנאים שונים שעשויים להתמלא על ידי אותה פעולת שחרור.

