class ReusableBarrier {
public:
    explicit ReusableBarrier(int count) :
        threshold(count),
        arrived_count(0),
        waiting_for_reset_count(0),
        current_phase(0) {}

    void wait() {
        std::unique_lock<std::mutex> lock(m);
        int my_phase = current_phase; // לכידת הפאזה הנוכחית של התהליכון

        arrived_count++;

        if (arrived_count < threshold) {
            // זהו אינו התהליכון האחרון שהגיע, המתן לאחרים להגיע לפאזה זו
            cv_arrival.wait(lock, [this, my_phase]{
                // התעורר אם הפאזה השתנתה (כלומר, המחסום עבר)
                // או אם התעוררות שווא והפאזה עדיין זהה (חזור להמתין)
                return my_phase != current_phase;
            });
        } else {
            // זהו התהליכון האחרון שהגיע עבור פאזה זו.
            // אפס את מונה ההגעה עבור הפאזה הבאה.
            arrived_count = 0;
            // קדם את מספר הפאזה כדי לסמן שהקבוצה הנוכחית עברה.
            current_phase++;
            // הער את כל התהליכונים שהמתינו להגעה.
            cv_arrival.notify_all();

            // כעת, התהליכון האחרון צריך להמתין שכל התהליכונים
            // מהפאזה הקודמת יאשרו שהם עברו את המחסום
            // לפני שקבוצה חדשה תוכל להתחיל.
            waiting_for_reset_count = threshold; // כל התהליכונים מקבוצה זו חייבים לאותת שסיימו
            cv_reset.wait(lock, [this]{
                // המתן עד שכל התהליכונים אישרו את האיפוס
                return waiting_for_reset_count == 0;
            });
        }

        // כל התהליכונים עברו את נקודת ההגעה.
        // כעת, כל תהליכון (למעט האחרון שהפעיל את notify_all ב-cv_reset)
        // צריך לאותת שהוא ראה את שינוי הפאזה ומוכן להמשיך,
        // כך שהתהליכון האחרון יוכל להמשיך.
        // יש לוודא שהתהליכון אכן היה חלק מהפאזה שהסתיימה זה עתה
        if (my_phase == current_phase - 1) {
            waiting_for_reset_count--;
            if (waiting_for_reset_count == 0) {
                // רק התהליכון האחרון שמאשר את האיפוס צריך להעיר את התהליכון האחרון שהמתין ב-cv_reset
                cv_reset.notify_one();
            }
        }
    }

private:
    std::mutex m;
    std::condition_variable cv_arrival; // עבור תהליכונים הממתינים שאחרים יגיעו
    std::condition_variable cv_reset;   // עבור התהליכון האחרון הממתין שאחרים יאשרו את האיפוס

    int threshold;              // מספר התהליכונים הנדרשים כדי לעבור את המחסום
    int arrived_count;          // מונה התהליכונים שהגיעו למחסום בפאזה הנוכחית
    int waiting_for_reset_count; // מונה התהליכונים שטרם אישרו את האיפוס לאחר מעבר המחסום
    int current_phase;          // מספר הפאזה הנוכחית, כדי להבחין בין מחזורי מחסום שונים
};

