typedef struct {
    unsigned long program_counter;  // PC - הכתובת של ההוראה הבאה לביצוע
    unsigned long stack_pointer;    // SP - מצביע לראש המחסנית
    unsigned long general_registers[16]; // רשמים כלליים (דוגמה)
    // ... רשמים נוספים (לדוגמה: רשמי מצב, רשמי נקודה צפה)
} ProcessContext;

// טבלת הקשרים של התהליכים במערכת (קונספטואלי)
ProcessContext process_contexts[10]; // לדוגמה, עד 10 תהליכים
int current_process_id = 0; // מזהה התהליך הנוכחי

// פונקציה קונספטואלית לקריאת רשם (במציאות, תלוי ארכיטקטורה ואסמבלר)
unsigned long read_register(int reg_idx) { /* ... */ return 0; }
void write_register(int reg_idx, unsigned long val) { /* ... */ }
unsigned long read_pc_register() { /* ... */ return 0; }
void write_pc_register(unsigned long val) { /* ... */ }
unsigned long read_sp_register() { /* ... */ return 0; }
void write_sp_register(unsigned long val) { /* ... */ }
int select_next_process_to_run() { /* ... */ return (current_process_id + 1) % 10; }

// פונקציה לשמירת הקשר של התהליך הרץ
void save_current_process_context(int pid) {
    // 1. שמירת ה-Program Counter (PC)
    //    (במערכות אמיתיות, זה לרוב נשמר אוטומטית ע"י החומרה או קוד ה-trap/interrupt)
    process_contexts[pid].program_counter = read_pc_register();

    // 2. שמירת ה-Stack Pointer (SP)
    process_contexts[pid].stack_pointer = read_sp_register();

    // 3. שמירת רשמים כלליים של המעבד
    for (int i = 0; i < 16; i++) {
        process_contexts[pid].general_registers[i] = read_register(i);
    }
    // ... שמירת רשמים נוספים
}

// פונקציה לשחזור הקשר של תהליך אחר
void restore_process_context(int pid) {
    // 1. שחזור רשמים כלליים של המעבד
    for (int i = 0; i < 16; i++) {
        write_register(i, process_contexts[pid].general_registers[i]);
    }

    // 2. שחזור ה-Stack Pointer (SP)
    write_sp_register(process_contexts[pid].stack_pointer);

    // 3. שחזור ה-Program Counter (PC)
    //    (זהו בדרך כלל הצעד האחרון, שמבצע קפיצה לכתובת השמורה ומעביר את השליטה
    //     לתהליך החדש בנקודה שבה הוא הופסק)
    write_pc_register(process_contexts[pid].program_counter);
}

// פונקציה קונספטואלית לתזמון והחלפת קשר
void scheduler_execute_context_switch() {
    int old_pid = current_process_id;

    // שמור את הקשר של התהליך שרץ כעת
    save_current_process_context(old_pid);

    // בחר את התהליך הבא לריצה (לדוגמה, ב-Round Robin)
    int new_pid = select_next_process_to_run(); 
    current_process_id = new_pid;

    // שחזר את הקשר של התהליך החדש
    restore_process_context(new_pid);

    // מכאן והלאה, התהליך החדש ממשיך את ריצתו
}

