    sleep(1); // מדמה עבודה או החלפת הקשר
    pthread_mutex_lock(&mutexB);
    printf("Thread 1 acquired Mutex B\n");
    // בצע עבודה קריטית
    pthread_mutex_unlock(&mutexB);
    pthread_mutex_unlock(&mutexA);
    return NULL;
