    }

    pid = fork();

    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        printf("Child %d: Waiting for input or signal...\n", getpid());
        bytes_read = read(STDIN_FILENO, buffer, sizeof(buffer) - 1);

        if (bytes_read == -1) {
            if (errno == EINTR) {
                printf("Child %d: read() was interrupted by a signal (errno=EINTR).\n", getpid());
            } else {
                perror("Child: read error");
            }
        } else if (bytes_read == 0) {
            printf("Child %d: read() returned 0 (EOF).\n", getpid());
        } else {
            buffer[bytes_read] = '\0';
            printf("Child %d: read() returned %zd bytes: '%s'\n", getpid(), bytes_read, buffer);
        }
        printf("Child %d: Exiting.\n", getpid());

    } else { // Parent process
        printf("Parent %d: Child PID is %d.\n", getpid(), pid);
        sleep(2);
        printf("Parent %d: Sending SIGUSR1 to child %d...\n", getpid(), pid);
        if (kill(pid, SIGUSR1) == -1) {
            perror("kill");
            exit(EXIT_FAILURE);
        }
        wait(NULL);
        printf("Parent %d: Child exited.\n", getpid());
    }

    return 0;
}

#include <unistd.h>
#include <stdio.h>
#include <signal.h>
#include <errno.h> // For EINTR

void handle_sigint(int sig) {
    printf("Signal %d received!\n", sig);
}

int main() {
    signal(SIGINT, handle_sigint);
    char buffer[256];
    printf("Process is about to call read(). Press Ctrl+C to send SIGINT.\n");
    ssize_t bytes_read = read(STDIN_FILENO, buffer, sizeof(buffer));
    if (bytes_read == -1) {
        if (errno == EINTR) {
            printf("read() was interrupted by a signal.\n");
        } else {
            perror("read failed");
        }
    } else {
        printf("read() completed successfully, %zd bytes.\n", bytes_read);
    }
    return 0;
}

#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h> // For strerror

void sig_handler(int signo) {
    printf("Signal %d received! Handler executing...\n", signo);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0; // Crucial: no SA_RESTART
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    char buffer[100];
    printf("Process trying to read from stdin (waiting for input)...\n");
    ssize_t bytes_read = read(STDIN_FILENO, buffer, sizeof(buffer)); // This is the call in question

    if (bytes_read == -1) {
        if (errno == EINTR) {
            printf("Read was interrupted by a signal (errno == EINTR).\n");
        } else {
            perror("read error");
        }
    } else if (bytes_read == 0) {
        printf("End of file (EOF) reached.\n");
    } else {
        printf("Read %zd bytes: %.*s\n", bytes_read, (int)bytes_read, buffer);
    }
    return 0;
}

solution.explanation:
**הסבר כללי:**
הפתרון כולל שני תהליכים: הורה וילד. ההורה יוצר את הילד ומשתמש באותות כדי לשלוט על מחזור העבודה שלו (השהיה, המשכה, סיום). הילד, מצידו, מטפל באותות אלו ומשתמש באותות אישור כדי ליידע את ההורה על מצבו. סנכרון בין התהליכים מושג באמצעות חסימת אותות ושימוש ב-`sigsuspend()` להמתנה יעילה.

**תהליך ההורה:**
1.  **יצירת ילד:** ההורה קורא ל-`fork()` ליצירת תהליך הילד.
2.  **טיפול באותות אישור:** ההורה מגדיר מטפל לאות `SIGUSR2` (האות שהילד שולח לאישור). המטפל פשוט מעלה דגל גלובלי (`child_ack_received`).
3.  **חסימת `SIGUSR2`:** ההורה חוסם את `SIGUSR2` בתחילה באמצעות `sigprocmask()` כדי לוודא שאינו מפספס אותות אישור מהילד לפני שהוא מוכן לטפל בהם, ובכדי ש-`sigsuspend()` יעבוד כהלכה. המסכה המקורית נשמרת לשחזור בסיום התהליך.
4.  **מחזור השהיה-המשכה:**
    *   ההורה שולח `SIGUSR1` לילד כדי להשהות אותו.
    *   ההורה מנקה את דגל האישור ומשתמש בלולאת `while` עם `sigsuspend()` כדי להמתין לאות `SIGUSR2` מהילד. `sigsuspend()` מבטל זמנית את חסימת `SIGUSR2` בזמן ההמתנה, וחוזר לחסום אותו לאחר קבלת האות. כדי להמתין רק ל-`SIGUSR2`, ה-`sigsuspend()` מופעל עם מסכה שחוסמת את כל האותות פרט ל-`SIGUSR2`.
    *   לאחר קבלת אישור ההשהיה, ההורה שולח שוב `SIGUSR1` לילד כדי להמשיך אותו.
    *   ההורה שוב מנקה את דגל האישור ומשתמש בלולאת `while` עם `sigsuspend()` להמתין לאות `SIGUSR2` מהילד.
5.  **סיום הילד:** לאחר מספר מחזורים, ההורה שולח `SIGTERM` לילד וממתין לסיומו באמצעות `waitpid()`.

**תהליך הילד:**
1.  **טיפול באותות:** הילד מגדיר מטפלים לאותות `SIGUSR1` ו-`SIGTERM`.
    *   **מטפל `SIGUSR1`:** מטפל זה משנה דגל גלובלי (`is_paused`) בין מצב 'מושהה' ל'רץ'. לאחר שינוי המצב, הוא שולח `SIGUSR2` להורה לאישור.
    *   **מטפל `SIGTERM`:** מטפל זה מדפיס הודעת סיום ויוצא מהתהליך באמצעות `_exit(0)`. חשוב להשתמש ב-`_exit()` ולא ב-`exit()` בתוך מטפל אותות כדי למנוע בעיות עם פלאשינג באפרים או קריאות לא בטוחות.
2.  **חסימת אותות:** הילד חוסם את `SIGUSR1` ו-`SIGTERM` בתחילה. זה חשוב כדי למנוע קבלת אותות לפני שהמטפלים הוגדרו, וכן כדי לשלוט מתי הילד יכול לקבל אותות אלו (לדוגמה, לא לקבל אותות השהיה/המשכה באמצע קטע קריטי אם היה כזה).
3.  **לולאת עבודה ראשית:**
    *   הלולאה מדפיסה הודעה וממתינה שניה.
    *   בכל איטרציה, לפני ביצוע העבודה בפועל, הילד בודק את הדגל `is_paused`.
    *   אם `is_paused` הוא `true`, הילד נכנס ללולאת המתנה: הוא משתמש ב-`sigsuspend()` כדי להמתין לאות `SIGUSR1` שישנה את מצב ה-`is_paused` בחזרה ל-`false`. `sigsuspend()` יבטל זמנית את חסימת `SIGUSR1` (ו-`SIGTERM` כדי לאפשר סיום גם במצב השהיה) בזמן ההמתנה. לאחר קבלת האות, המסכה המקורית (שחוסמת את `SIGUSR1` ו-`SIGTERM`) משוחזרת.
    *   לאחר שהילד יוצא ממצב השהיה, הוא ממשיך בלולאה. המסכה שחוסמת את `SIGUSR1` ו-`SIGTERM` משוחזרת כדי להגן על קטע העבודה.

**נקודות חשובות לפתרון בעיות סנכרון ומרוץ:**
*   **`sig_atomic_t`:** השימוש במשתנים מסוג `sig_atomic_t` עבור דגלים המשותפים בין הקוד הראשי למטפלי אותות מבטיח שגישה אליהם תהיה אטומית ולא תיפסק על ידי אות.
*   **`sigsuspend()`:** קריאת מערכת זו חיונית להמתנה יעילה לאותות. היא משנה את מסיכת האותות באופן אטומי, ממתינה לאות שאינו חסום, ואז משחזרת את המסיכה המקורית. זה מונע מצב של מרוץ שבו אות נשלח בדיוק בין בדיקת דגל לבין קריאה ל-`pause()`.
*   **חסימת אותות ראשונית:** חסימת האותות בתחילת שני התהליכים מבטיחה שהם לא יקבלו אותות לפני שהם מוכנים לטפל בהם, ובכך מונעת התנהגות בלתי צפויה.
*   **`_exit()` במטפל:** שימוש ב-`_exit()` במטפל של `SIGTERM` הוא קריטי כדי למנוע קריאות לפונקציות לא בטוחות בתוך מטפל אותות, מה שעלול להוביל ל-deadlocks או קריסות.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>

// Global flags for signal handling
volatile sig_atomic_t child_ack_received = 0; // Parent uses this to wait for child's ack
volatile sig_atomic_t is_paused = 0;          // Child uses this to toggle pause state

// Signal handler for parent (SIGUSR2 from child)
void parent_sigusr2_handler(int signum) {
    printf("[Parent] Received SIGUSR2 (ACK) from child.\n");
    child_ack_received = 1;
}

// Signal handler for child (SIGUSR1 from parent)
void child_sigusr1_handler(int signum) {
    if (is_paused) {
        printf("[Child] Received SIGUSR1 - Resuming work.\n");
        is_paused = 0; // Toggle to resume
    } else {
        printf("[Child] Received SIGUSR1 - Pausing work.\n");
        is_paused = 1; // Toggle to pause
    }
    // Send confirmation to parent
    kill(getppid(), SIGUSR2);
}

// Signal handler for child (SIGTERM from parent)
void child_sigterm_handler(int signum) {
    printf("[Child] Received SIGTERM - Terminating gracefully.\n");
    _exit(0); // Use _exit for signal handlers
}

int main() {
    pid_t pid;
    int i;
    int num_cycles = 3;

    // --- Setup signal handlers for parent --- 
    struct sigaction sa_parent_usr2;
    sa_parent_usr2.sa_handler = parent_sigusr2_handler;
    sigemptyset(&sa_parent_usr2.sa_mask);
    sa_parent_usr2.sa_flags = 0;
    if (sigaction(SIGUSR2, &sa_parent_usr2, NULL) == -1) {
        perror("sigaction parent SIGUSR2");
        exit(EXIT_FAILURE);
    }

    // Block SIGUSR2 in parent initially
    sigset_t parent_block_mask, old_parent_mask;
    sigemptyset(&parent_block_mask);
    sigaddset(&parent_block_mask, SIGUSR2);
    if (sigprocmask(SIG_BLOCK, &parent_block_mask, &old_parent_mask) == -1) {
        perror("sigprocmask parent initial block");
        exit(EXIT_FAILURE);
    }

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // Child process
        // --- Setup signal handlers for child ---
        struct sigaction sa_child_usr1, sa_child_term;

        // Handler for SIGUSR1 (pause/resume)
        sa_child_usr1.sa_handler = child_sigusr1_handler;
        sigemptyset(&sa_child_usr1.sa_mask);
        sa_child_usr1.sa_flags = 0;
        if (sigaction(SIGUSR1, &sa_child_usr1, NULL) == -1) {
            perror("sigaction child SIGUSR1");
            _exit(EXIT_FAILURE);
        }

        // Handler for SIGTERM (terminate)
        sa_child_term.sa_handler = child_sigterm_handler;
        sigemptyset(&sa_child_term.sa_mask);
        sa_child_term.sa_flags = 0;
        if (sigaction(SIGTERM, &sa_child_term, NULL) == -1) {
            perror("sigaction child SIGTERM");
            _exit(EXIT_FAILURE);
        }

        // Block SIGUSR1 and SIGTERM in child initially
        sigset_t child_block_mask;
        sigemptyset(&child_block_mask);
        sigaddset(&child_block_mask, SIGUSR1);
        sigaddset(&child_block_mask, SIGTERM);
        if (sigprocmask(SIG_BLOCK, &child_block_mask, NULL) == -1) {
            perror("sigprocmask child initial block");
            _exit(EXIT_FAILURE);
        }

        printf("[Child] Child process started (PID: %d). Parent PID: %d\n", getpid(), getppid());

        while (1) {
            // Prepare mask for sigsuspend: unblock SIGUSR1 and SIGTERM
            // This mask will temporarily replace the current mask during sigsuspend
            sigset_t suspend_unblock_mask;
            sigfillset(&suspend_unblock_mask); // Block all signals initially
            sigdelset(&suspend_unblock_mask, SIGUSR1); // Unblock SIGUSR1 to allow pause/resume
            sigdelset(&suspend_unblock_mask, SIGTERM); // Unblock SIGTERM to allow termination even while paused

            // Critical section: check if paused. If so, wait for SIGUSR1.
            while (is_paused) {
                printf("[Child] Paused. Waiting for resume/terminate signal...\n");
                sigsuspend(&suspend_unblock_mask); // Atomically replace mask and wait
            }

            // Re-block SIGUSR1 and SIGTERM while working, to avoid interruptions
            sigprocmask(SIG_BLOCK, &child_block_mask, NULL);

            printf("[Child] Working... (PID: %d)\n", getpid());
            sleep(1);
        }

    } else { // Parent process
        printf("[Parent] Parent process started (PID: %d). Child PID: %d\n", getpid(), pid);

        // Give child a moment to set up its signal handlers
        sleep(1); // Important for child to be ready to receive signals

        for (i = 0; i < num_cycles; i++) {
            printf("[Parent] Sending SIGUSR1 to child (PID: %d) to PAUSE.\n", pid);
            child_ack_received = 0; // Reset flag
            kill(pid, SIGUSR1);

            // Prepare mask for sigsuspend: unblock SIGUSR2
            // This mask will temporarily replace the current mask during sigsuspend
            sigset_t suspend_unblock_ack_mask;
            sigfillset(&suspend_unblock_ack_mask); // Block all signals initially
            sigdelset(&suspend_unblock_ack_mask, SIGUSR2); // Unblock SIGUSR2 to allow ACK

            // Wait for child's ACK (SIGUSR2)
            while (!child_ack_received) {
                printf("[Parent] Waiting for child to confirm PAUSE...\n");
                sigsuspend(&suspend_unblock_ack_mask); // Atomically replace mask and wait
            }
            printf("[Parent] Child confirmed PAUSE.\n");
            sleep(1); // Give some time for observation

            printf("[Parent] Sending SIGUSR1 to child (PID: %d) to RESUME.\n", pid);
            child_ack_received = 0; // Reset flag
            kill(pid, SIGUSR1);

            // Wait for child's ACK (SIGUSR2)
            while (!child_ack_received) {
                printf("[Parent] Waiting for child to confirm RESUME...\n");
                sigsuspend(&suspend_unblock_ack_mask); // Atomically replace mask and wait
            }
            printf("[Parent] Child confirmed RESUME.\n");
            sleep(1); // Give some time for observation
        }

        printf("[Parent] All pause/resume cycles completed. Sending SIGTERM to child (PID: %d).\n", pid);
        kill(pid, SIGTERM);

        // Wait for child to terminate
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            exit(EXIT_FAILURE);
        }

        if (WIFEXITED(status)) {
            printf("[Parent] Child (PID: %d) terminated with status %d.\n", pid, WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("[Parent] Child (PID: %d) terminated by signal %d.\n", pid, WTERMSIG(status));
        }

        // Restore original signal mask for parent (good practice)
        if (sigprocmask(SIG_SETMASK, &old_parent_mask, NULL) == -1) {
            perror("sigprocmask parent restore");
            exit(EXIT_FAILURE);
        }

        printf("[Parent] Parent process exiting.\n");
    }

    return 0;
}
```

פתרון זה מממש את הדרישות באמצעות שימוש ב-`fork()`, `exec()`, `kill()`, `waitpid()` ובמנגנוני טיפול באותות כמו `sigaction()` ו-`sigsuspend()`.

**הסבר מפורט:**

1.  **טיפול באות `SIGCHLD` בהורה (`sigchld_handler`):**
    *   ההורה משתמש ב-`sigaction()` כדי להגדיר מטפל אמין לאות `SIGCHLD`. `sigaction` עדיף על `signal()` מכיוון שהוא מספק שליטה טובה יותר על התנהגות האות (למשל, `SA_RESTART` ו-`SA_NOCLDSTOP`).
    *   בתוך המטפל, לולאת `while ((pid = waitpid(-1, &status, WNOHANG)) > 0)` חיונית. היא מבטיחה שכל תהליכי הילד שהסתיימו (גם אם מספר אותות `SIGCHLD` התמזגו לאחד) ייאספו (reaped) באופן מיידי. `WNOHANG` מונע מהמטפל להיחסם אם אין ילדים נוספים לאיסוף באותו רגע, ומאפשר לו לחזור במהירות. המונה `children_remaining` משמש למעקב אחר מספר הילדים הפעילים.

2.  **המתנה לאות `SIGUSR1` בילד (`sigusr1_handler` ו-`sigsuspend`):**
    *   הילד מגדיר מטפל לאות `SIGUSR1` (שבמקרה זה יכול להיות ריק, שכן מטרתו העיקרית היא לאפשר ל-`sigsuspend` לחזור). ה-`sigaction` עבור `SIGUSR1` מוגדר בהורה לפני ה-`fork`, והילד יורש את הגדרות המטפלים.
    *   לפני הקריאה ל-`sigsuspend()`, הילד חוסם באופן זמני את `SIGUSR1` באמצעות `sigprocmask(SIG_BLOCK, ...)`. זה מבטיח שהאות לא יגיע ויימסר לפני שהילד מוכן להמתין לו באופן אטומי.
    *   `sigsuspend(&suspend_mask)` הוא המפתח לסנכרון. הוא מבצע שתי פעולות באופן אטומי: משנה את מסכת האותות של התהליך למסכה שחוסמת את כל האותות למעט `SIGUSR1`, ולאחר מכן עוצר את התהליך. התהליך מתחדש רק כאשר אות לא חסום (כמו `SIGUSR1`) מגיע ומטופל. לאחר מכן, מסכת האותות המקורית משוחזרת. זה מבטיח שהילד יבצע `exec()` רק לאחר קבלת `SIGUSR1` מההורה.

3.  **יצירת ילדים ושליחת אותות בהורה:**
    *   ההורה יוצר `NUM_CHILDREN` תהליכי ילד באמצעות `fork()`, ושומר את ה-PIDs שלהם במערך.
    *   לאחר יצירת כל הילדים, ההורה עובר בלולאה ושולח `SIGUSR1` לכל ילד באמצעות `kill(pid, SIGUSR1)`, עם השהייה קצרה של שנייה אחת בין שליחה לשליחה באמצעות `sleep(1)`.

4.  **המתנה לסיום כל הילדים בהורה:**
    *   לאחר שליחת כל אותות ה-`SIGUSR1`, ההורה נכנס ללולאה שבה הוא קורא ל-`pause()` כל עוד המונה `children_remaining` גדול מ-0. `pause()` גורם להורה להמתין עד שכל אות מגיע (לדוגמה, `SIGCHLD` כאשר ילד מסיים). המטפל `sigchld_handler` יטפל בילדים המסתיימים, ויקטין את המונה. כאשר המונה מגיע ל-0, כל הילדים סיימו את ריצתם, וההורה יכול לצאת.

**עמידות בפני תרחישי מרוץ:**
*   אם ילד מסיים את ריצתו (לדוגמה, `exec` נכשל מיד או `/bin/sleep` מקבל ערך 0) לפני שההורה שולח לו `SIGUSR1`, או לפני שההורה התחיל את לולאת ה-`waitpid` הראשית, ה-`SIGCHLD` יימסר להורה. המטפל `sigchld_handler` יאסוף את הילד הזה באופן מיידי בזכות לולאת `waitpid(-1, &status, WNOHANG)` ויעדכן את `children_remaining`. כך, לא נוצרים תהליכי זומבי, וההורה מעודכן במצב.
*   השימוש ב-`sigsuspend` בילד מבטיח שהילד לא יפספס את `SIGUSR1` גם אם הוא נשלח בדיוק כשהילד מבצע הגדרה פנימית, ושהוא ימתין אך ורק לאות זה לפני המשך הריצה.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

#define NUM_CHILDREN 3
#define SLEEP_SECONDS 2 // משך השינה הבסיסי עבור /bin/sleep

pid_t child_pids[NUM_CHILDREN];
volatile int children_remaining = NUM_CHILDREN; // משתנה נדיף עבור בטיחות באותות

void sigchld_handler(int signum) {
    int status;
    pid_t pid;
    // לולאה לאיסוף כל הילדים שהסתיימו
    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        printf("[Parent] SIGCHLD handler: Child %d terminated with status %d\n", pid, WEXITSTATUS(status));
        children_remaining--;
    }
    // טיפול בשגיאות אפשריות מ-waitpid, אם כי WNOHANG מפחית את חשיבותן בתרחיש זה
    if (pid == -1 && errno != ECHILD) {
        perror("[Parent] SIGCHLD handler: waitpid error");
    }
}

void sigusr1_handler(int signum) {
    // מטפל זה יכול להיות ריק, מטרתו היא רק לבטל את חסימת sigsuspend
    printf("[Child %d] Received SIGUSR1. Proceeding with exec.\n", getpid());
}

int main() {
    struct sigaction sa_chld, sa_usr1;
    int i;

    // --- הגדרת מטפל SIGCHLD בהורה ---
    sa_chld.sa_handler = sigchld_handler;
    sigemptyset(&sa_chld.sa_mask);
    sa_chld.sa_flags = SA_RESTART | SA_NOCLDSTOP; // SA_RESTART עבור קריאות מערכת, SA_NOCLDSTOP לא לקבל אותות עבור ילדים שעצרו
    if (sigaction(SIGCHLD, &sa_chld, NULL) == -1) {
        perror("sigaction SIGCHLD");
        exit(EXIT_FAILURE);
    }
    printf("[Parent] SIGCHLD handler set up.\n");

    // --- הגדרת מטפל SIGUSR1 (עבור הילדים) ---
    sa_usr1.sa_handler = sigusr1_handler;
    sigemptyset(&sa_usr1.sa_mask);
    sa_usr1.sa_flags = 0; // אין צורך בדגלים מיוחדים עבור SIGUSR1
    if (sigaction(SIGUSR1, &sa_usr1, NULL) == -1) {
        perror("sigaction SIGUSR1");
        exit(EXIT_FAILURE);
    }
    printf("[Parent] SIGUSR1 handler prepared (for children).\n");

    // --- יצירת תהליכי ילד ---
    for (i = 0; i < NUM_CHILDREN; i++) {
        pid_t pid = fork();

        if (pid == -1) {
            perror("fork");
            exit(EXIT_FAILURE);
        } else if (pid == 0) { // תהליך ילד
            char sleep_duration_str[16];
            // כל ילד ישן קצת יותר זמן כדי להדגים סדר
            snprintf(sleep_duration_str, sizeof(sleep_duration_str), "%d", SLEEP_SECONDS + i);

            // חסימת SIGUSR1 באופן זמני כדי להבטיח ש-sigsuspend מוכן
            sigset_t block_mask, old_mask;
            sigemptyset(&block_mask);
            sigaddset(&block_mask, SIGUSR1);
            if (sigprocmask(SIG_BLOCK, &block_mask, &old_mask) == -1) {
                perror("[Child] sigprocmask BLOCK SIGUSR1");
                _exit(EXIT_FAILURE);
            }
            printf("[Child %d] Waiting for SIGUSR1...\n", getpid());

            // הכנת מסכה עבור sigsuspend: חוסמת את כל האותות למעט SIGUSR1
            sigset_t suspend_mask;
            sigfillset(&suspend_mask); // חוסם את כל האותות
            sigdelset(&suspend_mask, SIGUSR1); // מבטל חסימה של SIGUSR1

            // מבטל חסימה של SIGUSR1 באופן אטומי וממתין לכל אות (רצוי SIGUSR1)
            // sigsuspend יחזור כאשר SIGUSR1 יתקבל ויטופל
            sigsuspend(&suspend_mask);

            // שחזור מסכת האותות המקורית (אופציונלי, אך מומלץ)
            if (sigprocmask(SIG_SETMASK, &old_mask, NULL) == -1) {
                perror("[Child] sigprocmask SETMASK original");
                _exit(EXIT_FAILURE);
            }

            printf("[Child %d] SIGUSR1 received. Executing /bin/sleep %s\n", getpid(), sleep_duration_str);
            execl("/bin/sleep", "sleep", sleep_duration_str, (char *)NULL);
            perror("[Child] execl failed"); // execl חוזר רק במקרה של שגיאה
            _exit(EXIT_FAILURE); // השתמש ב-_exit בילד לאחר שגיאות fork/exec
        } else { // תהליך הורה
            child_pids[i] = pid;
            printf("[Parent] Forked child %d (PID: %d)\n", i + 1, pid);
        }
    }

    // --- ההורה שולח SIGUSR1 לילדים ---
    printf("[Parent] All children forked. Sending SIGUSR1 to them sequentially.\n");
    for (i = 0; i < NUM_CHILDREN; i++) {
        printf("[Parent] Sending SIGUSR1 to child %d (PID: %d)...\n", i + 1, child_pids[i]);
        if (kill(child_pids[i], SIGUSR1) == -1) {
            perror("kill SIGUSR1");
            // אם הילד כבר יצא, kill עלול להיכשל עם ESRCH. יש לטפל או להתעלם לפי הדרישות.
        }
        sleep(1); // השהייה קצרה בין שליחת אותות
    }

    // --- ההורה ממתין לכל הילדים שיסתיימו ---
    printf("[Parent] All SIGUSR1 signals sent. Waiting for remaining children to terminate...\n");
    // המטפל SIGCHLD מקטין את children_remaining. ההורה יכול פשוט להמתין שהמונה יגיע ל-0.
    while (children_remaining > 0) {
        pause(); // המתן לכל אות, כולל SIGCHLD
    }

    printf("[Parent] All children have terminated. Exiting.\n");

    return 0;
}
