solution.explanation:
הסבר:
1.  **הגדרת מטפל אותות (`sigaction`):**
    *   אנו משתמשים ב-`sigaction` במקום ב-`signal` מכיוון ש-`sigaction` מספק דרך אמינה וניידת יותר לטפל באותות. הוא מאפשר שליטה עדינה יותר על התנהגות האות, כולל חסימת אותות נוספים בזמן הטיפול באות הנוכחי.
    *   הדגל `volatile sig_atomic_t sigusr1_received` משמש כדי להבטיח גישה אטומית ובטוחה למשתנה זה הן מלולאת הריצה הראשית והן ממטפל האותות. `volatile` מונע אופטימיזציות של המהדר שעשויות למנוע עדכון נכון של המשתנה, ו-`sig_atomic_t` מבטיח שהגישה למשתנה היא אטומית (כלומר, לא ניתנת להפרעה).
    *   מטפל האותות עצמו פשוט מאוד: הוא רק קובע את הדגל `sigusr1_received` ל-1. זוהי פרקטיקה מומלצת למטפלי אותות כדי לשמור על בטיחות אסינכרונית (async-signal-safety). פעולות מורכבות יותר בתוך מטפל אותות עלולות להוביל למצבי מירוץ, קיפאון (deadlock) או התנהגות בלתי מוגדרת.

2.  **לוגיקת תהליך הבן:**
    *   תהליך הבן סוגר את קצה הכתיבה של הצינור (`pipefd[1]`) מכיוון שאינו משתמש בו.
    *   הוא מגדיר את מטפל האותות `SIGUSR1` באמצעות `sigaction`. לא השתמשנו בדגל `SA_RESTART` במבנה ה-`sigaction` כדי להדגים טיפול מפורש ב-`EINTR`.
    *   הלולאה הראשית `while (!sigusr1_received)` מנסה ברציפות לקרוא מהצינור באמצעות `read()`.
    *   **טיפול ב-`EINTR`:** קריאת המערכת `read()` עלולה להיקטע על ידי אות. אם היא מחזירה -1 ו-`errno` מוגדר ל-`EINTR`, זה אומר שמטפל האותות בוצע. במקרה זה, יש לנסות שוב את פעולת ה-`read`, אלא אם כן הדגל `sigusr1_received` כבר הוגדר (מה שיגרום ליציאה מהלולאה). זה מבטיח שהתהליך לא יפסיק לקרוא סתם בגלל אות שאינו אות סיום.
    *   לאחר קריאת הנתונים, התהליך מעבד אותם (בדוגמה, סופר תווים שאינם null).
    *   ברגע ש-`sigusr1_received` הופך ל-true (לאחר ביצוע מטפל האותות), הלולאה מסתיימת, קצה הקריאה של הצינור נסגר, ותהליך הבן יוצא.

3.  **לוגיקת תהליך האב:**
    *   תהליך האב סוגר את קצה הקריאה של הצינור (`pipefd[0]`) מכיוון שאינו משתמש בו.
    *   הוא מייצר בלוקים של נתונים אקראיים וכותב אותם לצינור באמצעות `write()`.
    *   לאחר כתיבת `NUM_BLOCKS` בלוקים, הוא שולח את האות `SIGUSR1` לתהליך הבן באמצעות `kill(pid, SIGUSR1)`.
    *   לאחר מכן, הוא סוגר את קצה הכתיבה של הצינור וממתין לתהליך הבן שיסיים את פעולתו באמצעות `wait(NULL)`.

**מושגים מרכזיים שהודגמו:**
*   תקשורת בין תהליכים (IPC) באמצעות צינורות.
*   יצירת תהליכים עם `fork()`.
*   טיפול אמין באותות עם `sigaction()`.
*   טיפול בקריאות מערכת שנקטעו (`EINTR`).
*   שימוש ב-`volatile sig_atomic_t` עבור דגלים המשתנים על ידי מטפלי אותות.
*   סיום תהליך בצורה מסודרת.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <errno.h>
#include <string.h>
#include <time.h> // For srand

#define BLOCK_SIZE 128
#define NUM_BLOCKS 10 // N blocks

// Flag to indicate if SIGUSR1 has been received
volatile sig_atomic_t sigusr1_received = 0;

// Signal handler for SIGUSR1
void handle_sigusr1(int sig) {
    if (sig == SIGUSR1) {
        printf("Child: Signal SIGUSR1 caught!\n");
        sigusr1_received = 1;
    }
}

int main(int argc, char *argv[]) {
    int pipefd[2];
    pid_t pid;

    // Create the pipe
    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // Fork a child process
    pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        close(pipefd[1]); // Close unused write end of the pipe

        // Set up SIGUSR1 handler using sigaction for reliable signal handling
        struct sigaction sa;
        memset(&sa, 0, sizeof(sa));
        sa.sa_handler = handle_sigusr1;
        sigemptyset(&sa.sa_mask); // No additional signals blocked inside handler
        // SA_RESTART is often used to automatically restart interrupted system calls.
        // For a hard question, we might want to explicitly handle EINTR, so we omit SA_RESTART here.
        // If SA_RESTART was used, read() would automatically restart unless sigusr1_received became true.
        // sa.sa_flags = SA_RESTART;
        if (sigaction(SIGUSR1, &sa, NULL) == -1) {
            perror("sigaction");
            exit(EXIT_FAILURE);
        }

        char buffer[BLOCK_SIZE];
        ssize_t bytes_read;
        int total_chars = 0;
        int block_count = 0;

        printf("Child: Starting to read from pipe...\n");
        while (!sigusr1_received) {
            bytes_read = read(pipefd[0], buffer, BLOCK_SIZE);

            if (bytes_read == -1) {
                if (errno == EINTR) {
                    // System call interrupted by a signal.
                    // Check if it was SIGUSR1. If so, loop will terminate.
                    // Otherwise, retry read.
                    printf("Child: read() interrupted by signal, retrying...\n");
                    continue; // Retry the read operation
                } else {
                    perror("read");
                    exit(EXIT_FAILURE);
                }
            } else if (bytes_read == 0) {
                // End of file (pipe closed by parent)
                printf("Child: Parent closed pipe, no more data.\n");
                break;
            } else {
                // Successfully read data
                block_count++;
                printf("Child: Read %zd bytes (block %d). Processing...\n", bytes_read, block_count);
                for (int i = 0; i < bytes_read; ++i) {
                    if (buffer[i] != '\0') { // Simple processing: count non-null chars
                        total_chars++;
                    }
                }
            }
        }

        printf("Child: SIGUSR1 received or pipe closed. Exiting loop. Total chars processed: %d\n", total_chars);
        close(pipefd[0]); // Close the read end of the pipe
        exit(EXIT_SUCCESS);

    } else { // Parent process
        close(pipefd[0]); // Close unused read end of the pipe
        srand(time(NULL)); // Seed for random data generation

        printf("Parent: Starting to write to pipe...\n");
        for (int i = 0; i < NUM_BLOCKS; ++i) {
            char buffer[BLOCK_SIZE];
            for (int j = 0; j < BLOCK_SIZE; ++j) {
                buffer[j] = (char)(33 + rand() % 94); // Printable ASCII chars
            }
            // Add a null terminator for string-like behavior if needed, though not strictly required for this problem.
            // buffer[BLOCK_SIZE-1] = '\0';

            printf("Parent: Writing block %d to pipe...\n", i + 1);
            if (write(pipefd[1], buffer, BLOCK_SIZE) == -1) {
                perror("write");
                exit(EXIT_FAILURE);
            }
            sleep(1); // Simulate some work/delay
        }

        printf("Parent: Finished writing %d blocks. Sending SIGUSR1 to child (PID: %d)...
", NUM_BLOCKS, pid);
        if (kill(pid, SIGUSR1) == -1) {
            perror("kill");
            exit(EXIT_FAILURE);
        }

        close(pipefd[1]); // Close the write end of the pipe
        printf("Parent: Waiting for child to terminate...\n");
        wait(NULL); // Wait for the child process to terminate
        printf("Parent: Child terminated. Exiting.\n");
        exit(EXIT_SUCCESS);
    }

    return 0; // Should not be reached
}

הפתרון דורש תיאום בין טיפול באותות (`SIGCHLD` ו-`SIGALRM`) לבין ניהול תהליכים (`fork`, `waitpid`, `kill`).

**1. הגדרת משתנים גלובליים:**
   - `children_remaining`: מונה את מספר הילדים שעדיין לא נאספו על ידי האב.
   - `timeout_expired`: דגל המציין אם פג הזמן הכולל.
   - `child_pids`: מערך לאחסון ה-PIDs של כל הילדים שנוצרו.
   - `child_exit_statuses`: מערך לאחסון סטטוסי היציאה של הילדים לאחר איסופם.
   - `child_reaped`: מערך דגלים למעקב אילו ילדים כבר נאספו.
   השימוש ב-`volatile` הכרחי למשתנים שמשותפים בין הקוד הראשי למטפלי אותות, כדי להבטיח שהמהדר לא יבצע אופטימיזציות שגויות.

**2. מטפל האותות `SIGCHLD` (`handle_sigchld`):**
   - תפקידו לאסוף ילדים מומתים כדי למנוע יצירת תהליכי זומבי.
   - הוא משתמש בלולאה עם `waitpid(-1, &status, WNOHANG)` כדי לאסוף את כל הילדים שסיימו את דרכם.
   - עבור כל ילד שנאסף, הוא מעדכן את מערכי ה-`child_exit_statuses` ו-`child_reaped` ומקטין את `children_remaining`.
   - אם כל הילדים נאספו, הוא מבטל את ה-`alarm` באמצעות `alarm(0)` כדי למנוע קבלת `SIGALRM` מיותר.

**3. מטפל האותות `SIGALRM` (`handle_sigalrm`):**
   - פשוט מציב את הדגל `timeout_expired` ל-1 ומבטל את ה-`alarm`.

**4. פונקציית `main`:**
   - **הגדרת מטפלי אותות:** משתמשים ב-`sigaction` (במקום `signal` הישנה והפחות אמינה) להגדרת המטפלים. דגלי `SA_RESTART` ו-`SA_NOCLDSTOP` מוגדרים עבור `SIGCHLD` כדי להבטיח שקריאות מערכת כמו `pause()` יופעלו מחדש לאחר הטיפול באות, ושלא נקבל אות על עצירה של ילד.
   - **חסימת `SIGCHLD` במהלך `fork`:** לפני יצירת הילדים, `SIGCHLD` נחסם זמנית באמצעות `sigprocmask`. זה מונע מצב מרוץ שבו ילד מסיים את דרכו מיד לאחר ה-`fork` אך לפני שהאב מספיק לאחסן את ה-PID שלו במערך ה-`child_pids`, מה שעלול לגרום לילד להיאסף על ידי המטפל לפני שהאב בכלל יודע עליו.
   - **יצירת ילדים:** לולאה יוצרת `NUM_CHILDREN` ילדים. כל ילד קורא ל-`sleep()` לזמן אקראי ויוצא עם קוד יציאה מתאים. האב מאחסן את ה-PIDs של הילדים.
   - **שחרור חסימת `SIGCHLD`:** לאחר יצירת כל הילדים, `SIGCHLD` משוחרר באמצעות `sigprocmask`. כעת, אם אותות `SIGCHLD` היו תלויים, הם יטופלו מיד.
   - **הפעלת טיימר:** `alarm(TOTAL_TIMEOUT)` מוגדר כדי להפעיל `SIGALRM` לאחר הזמן הכולל שנקבע.
   - **המתנה לאירועים:** האב נכנס ללולאה `while (children_remaining > 0 && !timeout_expired) { pause(); }`. הפונקציה `pause()` משעה את התהליך עד שיתקבל אות כלשהו (או `SIGCHLD` או `SIGALRM`).
   - **טיפול בפקיעת זמן:** אם `timeout_expired` הוא 1, האב עובר על כל הילדים. עבור כל ילד שטרם נאסף (`child_reaped[i] == 0`), הוא שולח `SIGKILL` כדי לסיים אותו בכוח.
   - **המתנה לאיסוף כל הילדים:** לאחר מכן, האב ממשיך להמתין באמצעות `while (children_remaining > 0) { pause(); }` עד שכל הילדים (כולל אלה שחוסלו זה עתה) ייאספו על ידי מטפל ה-`SIGCHLD`.
   - **הדפסת סיכום:** לבסוף, האב מדפיס את ה-PID וסטטוס היציאה של כל ילד, תוך הבחנה אם יצא באופן רגיל או חוסל על ידי אות.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <string.h> // For memset

#define NUM_CHILDREN 3
#define TOTAL_TIMEOUT 7 // seconds

// Global variables to be accessed by signal handlers and main
volatile int children_remaining = NUM_CHILDREN;
volatile int timeout_expired = 0;
pid_t child_pids[NUM_CHILDREN];
int child_exit_statuses[NUM_CHILDREN];
volatile int child_reaped[NUM_CHILDREN] = {0}; // 1 if reaped, 0 otherwise

// SIGCHLD signal handler
void handle_sigchld(int signum) {
    int status;
    pid_t pid;
    // Reap all terminated children to prevent zombies
    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        for (int i = 0; i < NUM_CHILDREN; i++) {
            if (child_pids[i] == pid) {
                child_exit_statuses[i] = status;
                if (child_reaped[i] == 0) { // Only decrement if not already reaped
                    children_remaining--;
                    child_reaped[i] = 1;
                }
                break;
            }
        }
    }

    if (children_remaining == 0) {
        alarm(0); // Cancel alarm if all children are reaped
    }
}

// SIGALRM signal handler
void handle_sigalrm(int signum) {
    timeout_expired = 1;
    alarm(0); // Ensure alarm is off
}

int main() {
    srand(time(NULL)); // Seed for random sleep times

    // 1. Set up signal handlers for SIGCHLD and SIGALRM
    struct sigaction sa_chld, sa_alrm;

    // SIGCHLD handler setup
    memset(&sa_chld, 0, sizeof(sa_chld));
    sa_chld.sa_handler = handle_sigchld;
    sigemptyset(&sa_chld.sa_mask); // No additional signals blocked inside handler
    sa_chld.sa_flags = SA_RESTART | SA_NOCLDSTOP; // Restart interrupted syscalls, don't get signal for stopped children
    if (sigaction(SIGCHLD, &sa_chld, NULL) == -1) {
        perror("sigaction SIGCHLD");
        exit(EXIT_FAILURE);
    }

    // SIGALRM handler setup
    memset(&sa_alrm, 0, sizeof(sa_alrm));
    sa_alrm.sa_handler = handle_sigalrm;
    sigemptyset(&sa_alrm.sa_mask); // No additional signals blocked inside handler
    sa_alrm.sa_flags = SA_RESTART; // Restart interrupted syscalls
    if (sigaction(SIGALRM, &sa_alrm, NULL) == -1) {
        perror("sigaction SIGALRM");
        exit(EXIT_FAILURE);
    }

    // 2. Block SIGCHLD temporarily during fork loop to prevent race conditions
    sigset_t block_chld, old_mask;
    sigemptyset(&block_chld);
    sigaddset(&block_chld, SIGCHLD);
    if (sigprocmask(SIG_BLOCK, &block_chld, &old_mask) == -1) {
        perror("sigprocmask SIG_BLOCK");
        exit(EXIT_FAILURE);
    }

    // 3. Fork children
    printf("Parent (PID %d) is creating %d children.\n", getpid(), NUM_CHILDREN);
    for (int i = 0; i < NUM_CHILDREN; i++) {
        pid_t pid = fork();

        if (pid == -1) {
            perror("fork");
            sigprocmask(SIG_SETMASK, &old_mask, NULL); // Unblock SIGCHLD on error
            exit(EXIT_FAILURE);
        } else if (pid == 0) { // Child process
            sigprocmask(SIG_SETMASK, &old_mask, NULL); // Restore original mask for child

            srand(getpid() ^ time(NULL)); // Re-seed for child
            int sleep_time = (rand() % 5) + 1; // Sleep 1 to 5 seconds
            printf("Child %d (PID %d) starting, will sleep for %d seconds.\n", i + 1, getpid(), sleep_time);
            sleep(sleep_time);
            printf("Child %d (PID %d) finished.\n", i + 1, getpid());
            exit(sleep_time); // Exit with sleep time as status
        } else { // Parent process
            child_pids[i] = pid;
            // child_reaped[i] initialized to 0 globally
        }
    }

    // 4. Unblock SIGCHLD now that all children are spawned and their PIDs recorded
    if (sigprocmask(SIG_SETMASK, &old_mask, NULL) == -1) {
        perror("sigprocmask SIG_SETMASK");
        exit(EXIT_FAILURE);
    }

    // 5. Start the global alarm
    printf("Parent setting alarm for %d seconds.\n", TOTAL_TIMEOUT);
    alarm(TOTAL_TIMEOUT);

    // 6. Parent waits for children to finish or timeout to expire
    // Use pause() to efficiently wait for signals
    while (children_remaining > 0 && !timeout_expired) {
        pause(); // Will be interrupted by SIGCHLD or SIGALRM
    }

    // 7. Handle timeout expiration
    if (timeout_expired) {
        printf("\nTimeout expired! Parent (PID %d) is terminating remaining children.\n", getpid());
        for (int i = 0; i < NUM_CHILDREN; i++) {
            if (child_reaped[i] == 0) { // If child hasn't been reaped yet
                printf("Killing child PID %d.\n", child_pids[i]);
                if (kill(child_pids[i], SIGKILL) == -1) {
                    perror("kill");
                }
            }
        }
        // After sending SIGKILL, wait for SIGCHLD to be delivered for these children
        // The SIGCHLD handler will eventually reap them.
        while (children_remaining > 0) {
            pause(); // Wait for all children to be reaped
        }
    } else {
        printf("\nAll children finished before timeout.\n");
    }

    // 8. Print summary of child process results
    printf("\n--- Child Process Summary ---\n");
    for (int i = 0; i < NUM_CHILDREN; i++) {
        printf("Child PID %d: ", child_pids[i]);
        if (child_reaped[i]) {
            if (WIFEXITED(child_exit_statuses[i])) {
                printf("Exited normally with status %d.\n", WEXITSTATUS(child_exit_statuses[i]));
            } else if (WIFSIGNALED(child_exit_statuses[i])) {
                printf("Terminated by signal %d (%s).\n", WTERMSIG(child_exit_statuses[i]),
                       (WTERMSIG(child_exit_statuses[i]) == SIGKILL ? "SIGKILL" : "other signal"));
            } else {
                printf("Unknown exit status.\n");
            }
        } else {
            // This case should ideally not be reached if the final `while (children_remaining > 0)` loop works
            printf("Still running or status not captured (error in logic).\n");
        }
    }

    return 0;
}
