#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <errno.h>

#define N_CHILDREN 3 // ניתן לשנות את מספר הבנים לבדיקה

// משתנים גלובליים לטיפול באותות
volatile sig_atomic_t children_done_count = 0;
pid_t children_pids[N_CHILDREN];
int pipefd[2]; // צינור לתקשורת

// מבנה לתוצאה הנשלחת דרך הצינור
struct ChildResult {
    pid_t pid;
    int index;
};

// מטפל אותות עבור SIGUSR2 בתהליך האב
void sigusr2_handler(int signum) {
    // בודק אם האות הוא אכן SIGUSR2
    if (signum == SIGUSR2) {
        children_done_count++;
    }
}

// מטפל אותות עבור SIGUSR1 בתהליך הבן
volatile sig_atomic_t child_received_sigusr1 = 0;
void child_sigusr1_handler(int signum) {
    if (signum == SIGUSR1) {
        child_received_sigusr1 = 1;
    }
}

// פונקציה לכתיבה בטוחה לצינור (מטפלת ב-EINTR)
ssize_t safe_write(int fd, const void *buf, size_t count) {
    ssize_t bytes_written = 0;
    ssize_t total_written = 0;
    while (total_written < count) {
        bytes_written = write(fd, buf + total_written, count - total_written);
        if (bytes_written == -1) {
            if (errno == EINTR) {
                continue; // הופרע, מנסים שוב
            } else {
                perror("write failed");
                return -1;
            }
        }
        total_written += bytes_written;
    }
    return total_written;
}

// פונקציה לקריאה בטוחה מהצינור (מטפלת ב-EINTR)
ssize_t safe_read(int fd, void *buf, size_t count) {
    ssize_t bytes_read = 0;
    ssize_t total_read = 0;
    while (total_read < count) {
        bytes_read = read(fd, buf + total_read, count - total_read);
        if (bytes_read == -1) {
            if (errno == EINTR) {
                continue; // הופרע, מנסים שוב
            } else {
                perror("read failed");
                return -1;
            }
        }
        if (bytes_read == 0) { // EOF - כל הכותבים סגרו את הצינור
            break;
        }
        total_read += bytes_read;
    }
    return total_read;
}

// לוגיקה של תהליך הבן
void child_proc(int child_idx) {
    // 1. הגדרת מטפל SIGUSR1
    struct sigaction sa_usr1;
    sa_usr1.sa_handler = child_sigusr1_handler;
    sigemptyset(&sa_usr1.sa_mask);
    sa_usr1.sa_flags = 0; // אין צורך ב-SA_RESTART עבור הגדרת דגל
    if (sigaction(SIGUSR1, &sa_usr1, NULL) == -1) {
        perror("Child sigaction SIGUSR1 failed");
        exit(1);
    }

    // חסימת SIGUSR1 זמנית כדי להבטיח שהמתנה תתבצע כראוי
    sigset_t blockmask, oldmask;
    sigemptyset(&blockmask);
    sigaddset(&blockmask, SIGUSR1);
    sigprocmask(SIG_BLOCK, &blockmask, &oldmask); // חוסם את SIGUSR1

    printf("Child %d (PID %d) waiting for SIGUSR1...\n", child_idx, getpid());

    // המתנה לאות SIGUSR1
    while (!child_received_sigusr1) {
        sigsuspend(&oldmask); // מבטל חסימה אטומית של SIGUSR1 וממתין לכל אות
    }
    printf("Child %d (PID %d) received SIGUSR1. Starting work...\n", child_idx, getpid());
    sigprocmask(SIG_SETMASK, &oldmask, NULL); // שחזור מסכת אותות מקורית

    // 2. דימוי עבודה
    sleep(child_idx + 1);

    // 3. כתיבת PID ואינדקס לצינור
    close(pipefd[0]); // בן סוגר את קצה הקריאה של הצינור
    struct ChildResult result = {getpid(), child_idx};
    if (safe_write(pipefd[1], &result, sizeof(result)) == -1) {
        fprintf(stderr, "Child %d (PID %d) failed to write to pipe.\n", child_idx, getpid());
        exit(1);
    }
    close(pipefd[1]); // בן סוגר את קצה הכתיבה של הצינור

    // 4. שליחת SIGUSR2 לאב
    if (kill(getppid(), SIGUSR2) == -1) {
        perror("Child failed to send SIGUSR2 to parent");
    }

    // 5. יציאה
    printf("Child %d (PID %d) finished work and exiting.\n", child_idx, getpid());
    exit(0);
}

// לוגיקה של תהליך האב
void parent_proc() {
    // 1. הגדרת מטפל SIGUSR2
    struct sigaction sa_usr2;
    sa_usr2.sa_handler = sigusr2_handler;
    sigemptyset(&sa_usr2.sa_mask);
    sa_usr2.sa_flags = SA_RESTART; // SA_RESTART כדי להפעיל מחדש קריאות מערכת שהופרעו
    if (sigaction(SIGUSR2, &sa_usr2, NULL) == -1) {
        perror("sigaction SIGUSR2 failed");
        exit(1);
    }

    // חסימת SIGCHLD זמנית כדי למנוע מצבי מירוץ עם בנים היוצאים מוקדם
    sigset_t block_chld, old_mask;
    sigemptyset(&block_chld);
    sigaddset(&block_chld, SIGCHLD);
    sigprocmask(SIG_BLOCK, &block_chld, &old_mask);

    // 2. יצירת N תהליכי בן
    for (int i = 0; i < N_CHILDREN; i++) {
        children_pids[i] = fork();
        if (children_pids[i] == -1) {
            perror("fork failed");
            // ניקוי בנים שכבר נוצרו
            for (int j = 0; j < i; ++j) {
                kill(children_pids[j], SIGTERM); // שולח אות סיום
                waitpid(children_pids[j], NULL, 0); // ממתין לסיום
            }
            exit(1);
        } else if (children_pids[i] == 0) {
            // תהליך הבן
            close(pipefd[1]); // בן סוגר את קצה הכתיבה של האב (הוא ישתמש בקצה שלו)
            // שחזור מסכת אותות מקורית לבן
            sigprocmask(SIG_SETMASK, &old_mask, NULL);
            child_proc(i);
            // לא אמור להגיע לכאן
            exit(1);
        }
    }

    // תהליך האב ממשיך
    close(pipefd[1]); // אב סוגר את קצה הכתיבה של הצינור

    printf("Parent (PID %d) forked %d children. Sending SIGUSR1...\n", getpid(), N_CHILDREN);

    // 4. שליחת SIGUSR1 לכל הבנים
    for (int i = 0; i < N_CHILDREN; i++) {
        if (kill(children_pids[i], SIGUSR1) == -1) {
            perror("Parent failed to send SIGUSR1 to child");
        }
    }

    // 5. האב ממתין שכל הבנים יסיימו (על ידי ספירת אותות SIGUSR2)
    printf("Parent waiting for all children to finish...\n");
    sigset_t empty_mask;
    sigemptyset(&empty_mask);

    while (children_done_count < N_CHILDREN) {
        sigsuspend(&empty_mask); // ממתין לכל אות לא חסום, כולל SIGUSR2
    }
    printf("Parent received completion signals from all %d children.\n", N_CHILDREN);

    // 6. קריאת תוצאות מהצינור
    printf("Parent reading results from pipe:\n");
    struct ChildResult result;
    for (int i = 0; i < N_CHILDREN; i++) {
        if (safe_read(pipefd[0], &result, sizeof(result)) == sizeof(result)) {
            printf("Child PID: %d, Child Index: %d\n", result.pid, result.index);
        } else {
            fprintf(stderr, "Parent failed to read result %d from pipe.\n", i);
        }
    }
    close(pipefd[0]); // אב סוגר את קצה הקריאה של הצינור

    // 7. המתנה לסיום כל הבנים (כדי למנוע זומבים)
    sigprocmask(SIG_SETMASK, &old_mask, NULL); // שחזור מסכת אותות מקורית כדי לבטל חסימת SIGCHLD
    for (int i = 0; i < N_CHILDREN; i++) {
        waitpid(children_pids[i], NULL, 0);
    }
    printf("Parent finished, all children reaped.\n");
}

int main() {
    if (pipe(pipefd) == -1) {
        perror("pipe failed");
        exit(1);
    }

    parent_proc();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>
#include <ctype.h> // For toupper

#define BUFFER_SIZE 256

int main() {
    int pipe_parent_to_child[2]; // Parent writes, Child reads
    int pipe_child_to_parent[2]; // Child writes, Parent reads
    pid_t pid;
    char write_msg[BUFFER_SIZE] = "Hello from parent!";
    char read_msg[BUFFER_SIZE];

    if (pipe(pipe_parent_to_child) == -1 || pipe(pipe_child_to_parent) == -1) {
        perror("pipe failed");
        exit(EXIT_FAILURE);
    }

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        // Child reads from parent_to_child pipe
        // Child writes to child_to_parent pipe

        read(pipe_parent_to_child[0], read_msg, BUFFER_SIZE);
        printf("Child received: %s\n", read_msg);

        // Convert to uppercase
        for (int i = 0; read_msg[i] != '\0'; i++) {
            read_msg[i] = toupper((unsigned char)read_msg[i]);
        }

        write(pipe_child_to_parent[1], read_msg, strlen(read_msg) + 1);
        printf("Child sent: %s\n", read_msg);

        exit(EXIT_SUCCESS);
    } else { // Parent process
        // Parent writes to parent_to_child pipe
        // Parent reads from child_to_parent pipe

        write(pipe_parent_to_child[1], write_msg, strlen(write_msg) + 1);
        printf("Parent sent: %s\n", write_msg);

        read(pipe_child_to_parent[0], read_msg, BUFFER_SIZE);
        printf("Parent received: %s\n", read_msg);

        wait(NULL); // Wait for child to terminate
        exit(EXIT_SUCCESS);
    }

    return 0;
}

solution.explanation:
10.1:
התוכנית תדפיס את ההודעות שהתהליכים שולחים, אך תהליך האב ייתקע (יתבצע חסימה) בקריאה מה-pipe השני. הסיבה לכך היא שתהליך האב מנסה לקרוא מ-`pipe_child_to_parent[0]` אך לא סגר את קצה הכתיבה שלו לאותו pipe, `pipe_child_to_parent[1]`. כל עוד קיים לפחות קצה כתיבה אחד פתוח ל-pipe, קריאה ממנו לא תחזיר EOF (סוף קובץ) גם אם אין נתונים זמינים. מכיוון שתהליך האב עצמו מחזיק את קצה הכתיבה, ה-`read()` שלו ייחסם לצמיתות, בציפייה שיום אחד האב אולי יכתוב לעצמו דרך ה-pipe הזה.
פלט צפוי (לפני התקיעה):
```
Parent sent: Hello from parent!
Child received: Hello from parent!
Child sent: HELLO FROM PARENT!
```

10.2:
כן, ישנן מספר בעיות:
1.  **חסימה (Deadlock/Blocking) של תהליך האב:** כפי שהוסבר לעיל, תהליך האב ייחסם בקריאה מ-`pipe_child_to_parent[0]` כי הוא לא סגר את קצה הכתיבה `pipe_child_to_parent[1]` של אותו pipe. ה-`read()` מצפה שכל קצוות הכתיבה ל-pipe ייסגרו כדי להחזיר EOF במקרה שאין נתונים נוספים, אך האב עצמו מחזיק קצה כתיבה פתוח.
2.  **מנהלי קבצים מיותרים (Unnecessary open file descriptors):** גם תהליך האב וגם תהליך הבן מחזיקים מנהלי קבצים פתוחים שאינם בשימוש. זוהי בזבוז משאבים ועלולה להוביל לבעיות מורכבות יותר בתוכניות גדולות יותר.
    *   האב לא משתמש ב-`pipe_parent_to_child[0]` (הוא רק כותב ל-pipe הזה).
    *   האב לא משתמש ב-`pipe_child_to_parent[1]` (הוא רק קורא מה-pipe הזה).
    *   הבן לא משתמש ב-`pipe_parent_to_child[1]` (הוא רק קורא מה-pipe הזה).
    *   הבן לא משתמש ב-`pipe_child_to_parent[0]` (הוא רק כותב ל-pipe הזה).

10.3:
התיקון העיקרי הוא סגירת קצוות ה-pipe שאינם בשימוש בכל אחד מהתהליכים מיד לאחר ה-`fork()`.

**קוד מתוקן:**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/wait.h>
#include <ctype.h> // For toupper

#define BUFFER_SIZE 256

int main() {
    int pipe_parent_to_child[2]; // Parent writes, Child reads
    int pipe_child_to_parent[2]; // Child writes, Parent reads
    pid_t pid;
    char write_msg[BUFFER_SIZE] = "Hello from parent!";
    char read_msg[BUFFER_SIZE];

    if (pipe(pipe_parent_to_child) == -1 || pipe(pipe_child_to_parent) == -1) {
        perror("pipe failed");
        exit(EXIT_FAILURE);
    }

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        // Close unused pipe ends in child
        close(pipe_parent_to_child[1]); // Child doesn't write to this pipe
        close(pipe_child_to_parent[0]); // Child doesn't read from this pipe

        // Child reads from parent_to_child pipe
        read(pipe_parent_to_child[0], read_msg, BUFFER_SIZE);
        printf("Child received: %s\n", read_msg);
        close(pipe_parent_to_child[0]); // Close read end after reading

        // Convert to uppercase
        for (int i = 0; read_msg[i] != '\0'; i++) {
            read_msg[i] = toupper((unsigned char)read_msg[i]);
        }

        // Child writes to child_to_parent pipe
        write(pipe_child_to_parent[1], read_msg, strlen(read_msg) + 1);
        printf("Child sent: %s\n", read_msg);
        close(pipe_child_to_parent[1]); // Close write end after writing

        exit(EXIT_SUCCESS);
    } else { // Parent process
        // Close unused pipe ends in parent
        close(pipe_parent_to_child[0]); // Parent doesn't read from this pipe
        close(pipe_child_to_parent[1]); // Parent doesn't write to this pipe

        // Parent writes to parent_to_child pipe
        write(pipe_parent_to_child[1], write_msg, strlen(write_msg) + 1);
        printf("Parent sent: %s\n", write_msg);
        close(pipe_parent_to_child[1]); // Close write end after writing

        // Parent reads from child_to_parent pipe
        read(pipe_child_to_parent[0], read_msg, BUFFER_SIZE);
        printf("Parent received: %s\n", read_msg);
        close(pipe_child_to_parent[0]); // Close read end after reading

        wait(NULL); // Wait for child to terminate
        exit(EXIT_SUCCESS);
    }

    return 0;
}
