        printf("Child (PID %d): Writing message...\n", getpid());
        write(pipefd[1], message, strlen(message) + 1);
        close(pipefd[1]); // Close write end
        printf("Child (PID %d): Message written and pipe closed.\n", getpid());
        exit(EXIT_SUCCESS);
