            printf("Parent (PID %d): Received message: \"%s\"\n", buffer);
        } else {
            printf("Parent (PID %d): First read returned %zd bytes.\n", getpid(), bytes_read);
        }

        printf("Parent (PID %d): Attempting to read again...\n", getpid());
        bytes_read = read(pipefd[0], buffer, MSG_SIZE); 
        if (bytes_read > 0) {
            printf("Parent (PID %d): Received second message: \"%s\"\n", buffer);
        } else if (bytes_read == 0) {
            printf("Parent (PID %d): Second read returned 0 bytes (EOF).\n", getpid());
        } else {
