פתרון 10.1:
להלן דוגמת קוד ב-C המממשת את התרחיש הנדרש:
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

#define NUM_COUNT 10 // מספר המספרים שההורה ישלח
#define BUFFER_SIZE sizeof(int)

int main() {
    int pipefd[2]; // pipefd[0] לקריאה, pipefd[1] לכתיבה
    pid_t pid;

    // יצירת הצינור
    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // יצירת תהליך ילד
    pid = fork();

    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // קוד רץ בתהליך הילד
        close(pipefd[1]); // הילד סוגר את קצה הכתיבה של הצינור - הוא רק קורא
        int number, sum = 0;
        printf("Child process (PID %d): Starting to receive numbers.\n", getpid());

        // קריאה מהצינור עד שההורה סוגר את קצה הכתיבה שלו
        while (read(pipefd[0], &number, BUFFER_SIZE) > 0) {
            sum += number;
            printf("Child process (PID %d): Received %d, current sum %d\n", getpid(), number, sum);
        }
        close(pipefd[0]); // הילד סוגר את קצה הקריאה שלו
        printf("Child process (PID %d): Final sum is %d\n", getpid(), sum);
        exit(EXIT_SUCCESS);
    } else { // קוד רץ בתהליך ההורה
        close(pipefd[0]); // ההורה סוגר את קצה הקריאה של הצינור - הוא רק כותב
        srand(time(NULL)); // אתחול מחולל המספרים האקראיים
        printf("Parent process (PID %d): Starting to send numbers.\n", getpid());

        // שליחת N מספרים אקראיים לילד
        for (int i = 0; i < NUM_COUNT; i++) {
            int random_num = rand() % 100; // מספר אקראי בין 0 ל-99
            write(pipefd[1], &random_num, BUFFER_SIZE);
            printf("Parent process (PID %d): Sent %d\n", getpid(), random_num);
            sleep(1); // הדמיית עבודה כלשהי
        }
        close(pipefd[1]); // ההורה סוגר את קצה הכתיבה שלו - מסמן לילד שאין עוד נתונים
        wait(NULL); // ההורה ממתין לסיום תהליך הילד
        printf("Parent process (PID %d): Child terminated. Exiting.\n", getpid());
        exit(EXIT_SUCCESS);
    }

    return 0;
}
```

