        perror("pipe failed");
        exit(EXIT_FAILURE);
    }

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        // Close unused pipe ends
        close(pipe_parent_to_child[1]); // Child doesn't write to this pipe
        close(pipe_child_to_parent[0]); // Child doesn't read from this pipe

        int num;
        int sum = 0;

        // Read numbers from parent and calculate sum
        // Loop until -1 is received or read fails
        while (read(pipe_parent_to_child[0], &num, sizeof(num)) > 0 && num != -1) {
            sum += num;
        }

        // Write sum back to parent
        write(pipe_child_to_parent[1], &sum, sizeof(sum));

        // Close remaining pipe ends
        close(pipe_parent_to_child[0]);
        close(pipe_child_to_parent[1]);

        exit(EXIT_SUCCESS);
    } else { // Parent process
        // Close unused pipe ends
        close(pipe_parent_to_child[0]); // Parent doesn't read from this pipe
        close(pipe_child_to_parent[1]); // Parent doesn't write to this pipe

        int numbers[] = {10, 20, 30, 40, 50, -1}; // Numbers to send, -1 signals end
        int i;
        int received_sum;

        // Write numbers to child
        for (i = 0; numbers[i] != -1; i++) {
            write(pipe_parent_to_child[1], &numbers[i], sizeof(numbers[i]));
        }
        // Send the termination signal (-1)
        write(pipe_parent_to_child[1], &numbers[i], sizeof(numbers[i])); 

        // Wait for child to finish
        wait(NULL);

        // Read sum from child
        read(pipe_child_to_parent[0], &received_sum, sizeof(received_sum));

        printf("Parent received sum from child: %d\n", received_sum);

        // Close remaining pipe ends
        close(pipe_parent_to_child[1]);
        close(pipe_child_to_parent[0]);
    }

    return 0;
}
