void acquire_two_resources(int res1_type, int res2_type) {
    // Ensure canonical order to prevent deadlock
    int first_res = std::min(res1_type, res2_type);
    int second_res = std::max(res1_type, res2_type);

    pthread_mutex_lock(&global_lock);

    // Acquire the first resource in canonical order
    while (available_instances[first_res] == 0) {
        pthread_cond_wait(&resource_cond[first_res], &global_lock);
    }
    available_instances[first_res]--;

    // Acquire the second resource in canonical order
    while (available_instances[second_res] == 0) {
        pthread_cond_wait(&resource_cond[second_res], &global_lock);
    }
    available_instances[second_res]--;

    pthread_mutex_unlock(&global_lock);
}

void release_two_resources(int res1_type, int res2_type) {
    pthread_mutex_lock(&global_lock);

    // Release res1_type and signal waiting threads
    available_instances[res1_type]++;
    pthread_cond_broadcast(&resource_cond[res1_type]);

    // Release res2_type and signal waiting threads
    available_instances[res2_type]++;
    pthread_cond_broadcast(&resource_cond[res2_type]);

    pthread_mutex_unlock(&global_lock);
}

