#include <stdio.h>
#include <pthread.h>
#include <stdlib.h> // For malloc, free

#define N_THREADS 5

int counter = 0;
pthread_mutex_t mutex;
pthread_cond_t cond; // A single condition variable for all threads

void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;
    free(arg); // Clean up dynamically allocated ID

    pthread_mutex_lock(&mutex);

    // Threads wait here until it's their turn (counter == thread_id)
    // The bug is in how they are signaled.
    while (counter != thread_id) {
        pthread_cond_wait(&cond, &mutex);
    }

    // Now it's this thread's turn.
    printf("Thread %d incrementing counter from %d to %d\n", thread_id, counter, counter + 1);
    counter++; // Increment the counter

    // Buggy signaling: Only one arbitrary thread is woken up.
    // If the wrong thread is woken, it goes back to wait, and the correct one might remain asleep.
    pthread_cond_signal(&cond); // THIS IS THE BUG

    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    pthread_t threads[N_THREADS];

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    for (int i = 0; i < N_THREADS; ++i) {
        int* thread_id = malloc(sizeof(int));
        if (thread_id == NULL) {
            perror("malloc failed");
            exit(EXIT_FAILURE);
        }
        *thread_id = i;
        pthread_create(&threads[i], NULL, worker_thread, (void*)thread_id);
    }

    // Initial signal to wake up thread 0 (or whoever is first).
    // This is necessary because counter starts at 0, and no thread will signal initially.
    pthread_mutex_lock(&mutex);
    pthread_cond_signal(&cond); 
    pthread_mutex_unlock(&mutex);

    for (int i = 0; i < N_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final counter value: %d\n", counter);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    return 0;
}

solution.explanation:
8.1: הבעיה המרכזית בקוד היא השימוש ב-`pthread_cond_signal` במקום `pthread_cond_broadcast` (או מערך של משתני תנאי). כאשר `pthread_cond_signal` נקרא, הוא מעיר חוט אחד בלבד (שרירותי) מבין החוטים הממתינים על משתנה התנאי `cond`.
אם החוט שהתעורר אינו החוט שערך ה-`thread_id` שלו תואם את ערך ה-`counter` הנוכחי (כלומר, `counter != thread_id`), הוא יבדוק מחדש את התנאי בלולאת ה-`while` ויחזור מיד למצב המתנה על `pthread_cond_wait`.
החוט ה"נכון" (זה ש-`thread_id` שלו שווה ל-`counter`) עלול להישאר במצב שינה ולא להתעורר לעולם, מכיוון שאין אף אחד שיעיר אותו ספציפית.
תרחיש זה עלול להוביל ל**קיפאון (Deadlock)**, שבו כל החוטים ממתינים ואין חוט שיכול להתקדם ולשלוח איתות נוסף. במקרה הטוב, המונה ייתקע על ערך נמוך מ-`N_THREADS` וכל החוטים שעדיין לא קידמו את המונה ייתקעו. במקרה הפחות טוב, גם אם חוטים מתעוררים, אם הם לא החוטים הנכונים, הם יחזרו לישון, וייתכן שחוטים רבים יבצעו פעולות התעוררות ובדיקה מיותרות מבלי להתקדם, מה שיכול להיחשב כ**לייבלוק (Livelock)** או פשוט כריצה שגויה ולא יעילה.

8.2: הפתרון הפשוט ביותר הוא להחליף את `pthread_cond_signal` ב-`pthread_cond_broadcast`. פעולה זו מעירה את כל החוטים הממתינים על `cond`. כל חוט יבדוק את התנאי `counter != thread_id`. רק החוט שערך ה-`thread_id` שלו שווה לערך ה-`counter` הנוכחי ימשיך בביצוע, בעוד שאר החוטים יחזרו למצב המתנה. זה מבטיח שהחוט הנכון תמיד יתקדם.

```c
void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;
    free(arg);

    pthread_mutex_lock(&mutex);

    while (counter != thread_id) {
        pthread_cond_wait(&cond, &mutex);
    }

    printf("Thread %d incrementing counter from %d to %d\n", thread_id, counter, counter + 1);
    counter++;

    pthread_cond_broadcast(&cond); // תיקון: שימוש ב-broadcast מעיר את כל החוטים הרלוונטיים

    pthread_mutex_unlock(&mutex);

    return NULL;
}
```

8.3: כדי להימנע משימוש ב-`pthread_cond_broadcast` ועדיין להבטיח התקדמות, ניתן להשתמש במערך של משתני תנאי, כאשר כל חוט ממתין על משתנה תנאי ספציפי משלו. כאשר חוט מסיים את תורו, הוא מאותת ספציפית לחוט הבא בתור.

**הגדרות גלובליות חדשות (בנוסף ל-`counter` ו-`mutex` הקיימים):**
```c
// pthread_cond_t cond; // יש להחליף את זה
pthread_cond_t turn_cond[N_THREADS]; // מערך של משתני תנאי, אחד לכל חוט
```

**פונקציית `worker_thread` מתוקנת:**
```c
void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;
    free(arg);

    pthread_mutex_lock(&mutex);

    // החוט ממתין על משתנה התנאי הספציפי שלו
    while (counter != thread_id) {
        pthread_cond_wait(&turn_cond[thread_id], &mutex);
    }

    printf("Thread %d incrementing counter from %d to %d\n", thread_id, counter, counter + 1);
    counter++;

    // מאותת ספציפית לחוט הבא בתור, אם קיים
    if (counter < N_THREADS) { // ודא שיש חוט הבא לאותת לו
        pthread_cond_signal(&turn_cond[counter]); // מאותת לחוט הבא
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}
```

**אתחול משתני התנאי ב-`main`:**
יש לאתחל את כל משתני התנאי במערך `turn_cond` ב-`main` בעזרת לולאה (במקום `pthread_cond_init(&cond, NULL)`):
`for (int i = 0; i < N_THREADS; ++i) { pthread_cond_init(&turn_cond[i], NULL); }`

**איתות התחלתי ב-`main`:**
לאחר יצירת כל החוטים, יש לשלוח איתות התחלתי לחוט 0 כדי להתחיל את השרשרת (במקום `pthread_cond_signal(&cond)`):
`pthread_mutex_lock(&mutex); pthread_cond_signal(&turn_cond[0]); pthread_mutex_unlock(&mutex);`

**ניקוי משאבים ב-`main`:**
יש להרוס את כל משתני התנאי במערך `turn_cond` בסיום הריצה (במקום `pthread_cond_destroy(&cond)`):
`for (int i = 0; i < N_THREADS; ++i) { pthread_cond_destroy(&turn_cond[i]); }`

