#define NUM_BARRIER_CYCLES 2 // מספר הפעמים שהמחסום ישמש

pthread_mutex_t barrier_mutex;
pthread_cond_t barrier_cond;
int arrived_count = 0;
int barrier_generation = 0; // מונה דורות המחסום

void barrier_wait() {
    pthread_mutex_lock(&barrier_mutex);

    int my_generation = barrier_generation; // כל חוט זוכר את הדור שאליו הוא שייך

    arrived_count++;
    if (arrived_count == NUM_THREADS) {
        // החוט האחרון שהגיע
        arrived_count = 0;         // איפוס המונה עבור הדור הבא
        barrier_generation++;      // קידום הדור (משחרר את כל החוטים מהדור הנוכחי)
        pthread_cond_broadcast(&barrier_cond); // מעיר את כל החוטים הממתינים
    } else {
        // לא החוט האחרון, מחכה שהדור שלו יתקדם
        while (my_generation == barrier_generation) { // תנאי המתנה חזק יותר
            pthread_cond_wait(&barrier_cond, &barrier_mutex);
        }
    }
    pthread_mutex_unlock(&barrier_mutex);
}

// שאר הקוד של main ו-thread_func נשאר זהה
```

