```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

#define PAGE_SIZE 4096 // 4KB
#define NUM_PAGES 1000 // Total 4MB

int main() {
    int *data = (int *)malloc(NUM_PAGES * PAGE_SIZE);
    if (data == NULL) {
        perror("malloc failed");
        return 1;
    }

    // Initialize some data in specific pages
    data[0] = 10; // Accesses the first page
    data[NUM_PAGES * (PAGE_SIZE / sizeof(int) - 1)] = 20; // Accesses the last page

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork failed");
        return 1;
    } else if (pid == 0) { // Child process
        // Child modifies its own copy of the first page
        data[0] = 100;
        // Child modifies its own copy of the last page
        data[NUM_PAGES * (PAGE_SIZE / sizeof(int) - 1)] = 200;
        printf("Child: data[0]=%d, data[last_page]=%d\n", data[0], data[NUM_PAGES * (PAGE_SIZE / sizeof(int) - 1)]);
        exit(0);
    } else { // Parent process
        wait(NULL); // Wait for child to finish
        printf("Parent: data[0]=%d, data[last_page]=%d\n", data[0], data[NUM_PAGES * (PAGE_SIZE / sizeof(int) - 1)]);
    }

    free(data);
    return 0;
}
```

