// File: prog_A.c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <string.h>

#define PAGE_SIZE 4096

void allocate_and_touch(int num_pages) {
    char *mem_block = (char*)malloc(num_pages * PAGE_SIZE);
    if (!mem_block) { perror("malloc failed"); exit(1); }
    for (int i = 0; i < num_pages; ++i) {
        mem_block[i * PAGE_SIZE] = 'X'; // Touch a byte in each page
    }
}

int main(int argc, char *argv[]) {
    // Original process P
    if (argc == 1) { // This is the initial run of prog_A
        allocate_and_touch(4); // P allocates 4 pages

        pid_t child1_pid = fork();
        if (child1_pid == 0) { // Child C1
            allocate_and_touch(2); // C1 allocates 2 pages
            char *args_b[] = {"./prog_B", NULL};
            execvp(args_b[0], args_b);
            perror("execvp prog_B failed"); exit(1);
        } else { // Parent P continues
            pid_t child2_pid = fork();
            if (child2_pid == 0) { // Child C2
                allocate_and_touch(3); // C2 allocates 3 pages
                char *args_a[] = {"./prog_A", "re_exec", NULL}; // Differentiate re-exec
                execvp(args_a[0], args_a);
                perror("execvp prog_A failed"); exit(1);
            } else { // Parent P waits
                waitpid(child1_pid, NULL, 0);
                waitpid(child2_pid, NULL, 0);
            }
        }
    }
    return 0;
}
