#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h>

#define MMAP_SIZE 4096 // A single page

int main() {
    int *shared_mem;
    pid_t pid;

    // Allocate a shared anonymous memory region
    shared_mem = mmap(NULL, MMAP_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (shared_mem == MAP_FAILED) {
        perror("mmap failed");
        exit(1);
    }

    *shared_mem = 100; // Initial value

    printf("Parent PID: %d, Initial shared value: %d\n", getpid(), *shared_mem);

    pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(1);
    } else if (pid == 0) { // Child process
        printf("Child PID: %d, Parent PID: %d, Before modification shared value: %d\n", getpid(), getppid(), *shared_mem);
        *shared_mem = 200; // Modify shared memory
        printf("Child PID: %d, After modification shared value: %d\n", getpid(), *shared_mem);

        char *args[] = {"./prog2", NULL};
        printf("Child PID: %d, Executing prog2...\n", getpid());
        execve(args[0], args, NULL);
        perror("execve failed"); // Should not reach here if execve succeeds
        exit(1);
    } else { // Parent process
        int local_var = 5;
        local_var++; // This modification to a local variable will cause COW on the parent's stack page.

        wait(NULL); // Wait for child to finish

        printf("Parent PID: %d, After child finished, shared value: %d\n", getpid(), *shared_mem);

        // Clean up shared memory
        if (munmap(shared_mem, MMAP_SIZE) == -1) {
            perror("munmap failed");
            exit(1);
        }
    }

    return 0;
}
