    printf("[%s] PID: %d, PPID: %d\n", label, getpid(), getppid());
    printf("  Global (data) var addr: %p, value: %d\n", &global_data, global_data);
    printf("  Global (bss) var addr: %p, value: %d\n", &bss_data, bss_data);
    printf("  Stack var addr: %p, value: %d\n", &local_stack_val, local_stack_val);
    if (heap_ptr) {
        printf("  Heap var addr: %p, value: %d\n", heap_ptr, *heap_ptr);
    } else {
        printf("  Heap var: not allocated/null\n");
    }
    printf("\n");
}

