    bss_data = 50;

    // Allocate on heap
    int* heap_data = (int*)malloc(sizeof(int));
    if (!heap_data) {
        perror("malloc failed");
        exit(1);
    }
    *heap_data = 300;

    // Local stack variable
    int stack_var = 200;

    print_memory_info("Initial (Before fork)", heap_data, stack_var);

    pid_t pid = fork();

    if (pid < 0) {
        perror("fork failed");
        exit(1);
    } else if (pid == 0) { // Child process
        // Child modifies its copies
        global_data += 10;
        bss_data += 5;
        *heap_data += 20;
        stack_var += 30; // Modify stack_var in child

        printf("--- Child Process (%d) ---\n", getpid());
        print_memory_info("Child (After modify)", heap_data, stack_var);

        // Child exits
        printf("Child %d exiting.\n", getpid());
        exit(0);
    } else { // Parent process
        // Parent modifies its copies
        global_data += 1;
        bss_data += 2;
        *heap_data += 2;
        stack_var += 3; // Modify stack_var in parent

        sleep(1); // Give child a chance to run and print
        printf("--- Parent Process (%d) ---\n", getpid());
        print_memory_info("Parent (After modify & Child done)", heap_data, stack_var);

        wait(NULL); // Wait for child to finish
        printf("Parent %d exiting.\n", getpid());
        free(heap_data); // Free parent's heap
    }

    return 0;
}

