void allocate_some_memory() {
    // Allocate some heap memory
    char* heap_ptr = (char*)malloc(4096); // 1 page
    if (heap_ptr) {
        memset(heap_ptr, 0, 4096); // Trigger copy-on-write for this page if forked
        printf("PID %d allocated and touched heap memory.\n", getpid());
    } else {
        printf("PID %d failed to allocate heap memory.\n", getpid());
    }
}

