    global_data[0] = getpid(); 

    allocate_some_memory(); // P0 allocates 1 heap page

    pid_t pid1 = fork();
    if (pid1 == 0) { // Child 1
        printf("Prog1 Child1: PID %d, PPID %d\n", getpid(), getppid());
        global_data[1] = getpid(); // Child 1 modifies global data, triggering COW
        allocate_some_memory(); // Child 1 allocates another heap page

        char* args[] = {"./prog2", NULL};
        execvp(args[0], args);
        perror("execvp failed"); // Should not be reached
        exit(1);
