        global_data[2] = getpid(); // Child 2 modifies global data, triggering COW
        // Child 2 does NOT exec, but continues running prog1
        allocate_some_memory(); // Child 2 allocates another heap page
        sleep(1); // Stay alive for the snapshot
        exit(0);
    }

    // Parent waits for children
    waitpid(pid1, NULL, 0);
    waitpid(pid2, NULL, 0);

    printf("Prog1 Parent: PID %d exiting.\n", getpid());
