int shared_counter = 0;
pthread_mutex_t counter_mutex;

void* thread_func(void* arg) {
    int iterations = *((int*)arg);

    for (int i = 0; i < iterations; ++i) {
        usleep(10); // מדמה עבודה כלשהי

        if (i % 2 == 0) { // תנאי המגן על המונה רק בחלק מהאיטרציות
            pthread_mutex_lock(&counter_mutex);
            shared_counter++;
            pthread_mutex_unlock(&counter_mutex);
        } else {
            shared_counter++; // כאן עלול להתרחש מצב מרוץ (race condition)
        }
    }
    return NULL;
}

int main() {
    pthread_t tid1, tid2;
    int iterations = 10000; 

    pthread_mutex_init(&counter_mutex, NULL);

    pthread_create(&tid1, NULL, thread_func, &iterations);
    pthread_create(&tid2, NULL, thread_func, &iterations);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    pthread_mutex_destroy(&counter_mutex);

    printf("Final counter value: %d\n", shared_counter);

    return 0;
}

