// פונקציית חוט המשתמשת ב-mutex
void* thread_with_mutex(void* arg) {
    for (int i = 0; i < INCREMENT_PER_THREAD; ++i) {
        pthread_mutex_lock(&counter_mutex);
        global_counter++;
        pthread_mutex_unlock(&counter_mutex);
    }
    return NULL;
}

// פונקציית חוט שאינה משתמשת ב-mutex
void* thread_without_mutex(void* arg) {
    for (int i = 0; i < INCREMENT_PER_THREAD; ++i) {
        global_counter++; // מצב מרוץ (race condition) כאן!
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    pthread_mutex_init(&counter_mutex, NULL);

    // יצירת 2 חוטים המוגנים באמצעות mutex
    pthread_create(&threads[0], NULL, thread_with_mutex, NULL);
    pthread_create(&threads[1], NULL, thread_with_mutex, NULL);

    // יצירת 2 חוטים שאינם מוגנים באמצעות mutex
    pthread_create(&threads[2], NULL, thread_without_mutex, NULL);
    pthread_create(&threads[3], NULL, thread_without_mutex, NULL);

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
