#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h> // For usleep

// Node structure for the linked list
typedef struct Node {
    int id;
    struct Node* next;
} Node;

// Global linked list head and its mutex
Node* head = NULL;
pthread_mutex_t list_mutex;

// Global counter for unique IDs and its mutex
int next_node_id = 0;
pthread_mutex_t id_mutex;

// Function 1: Adds a new node to the list
void add_node_to_list_path1() {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate new node");
        return;
    }

    pthread_mutex_lock(&list_mutex); // Lock list first
    usleep(10); // Simulate some work
    pthread_mutex_lock(&id_mutex);   // Then lock ID

    new_node->id = next_node_id++;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&id_mutex);
    pthread_mutex_unlock(&list_mutex);
}

// Function 2: A different operation that needs both resources, but locks in reverse order
void process_id_and_list_path2() {
    pthread_mutex_lock(&id_mutex);   // Lock ID first
    usleep(10); // Simulate some work
    pthread_mutex_lock(&list_mutex); // Then lock list

    // This function might perform some operation that requires both resources
    // For this example, we just increment next_node_id (protected by id_mutex)
    // and then release both mutexes.
    next_node_id++;

    pthread_mutex_unlock(&list_mutex);
    pthread_mutex_unlock(&id_mutex);
}

void* thread_func_1(void* arg) {
    int num_iterations = *((int*)arg);
    for (int i = 0; i < num_iterations; ++i) {
        add_node_to_list_path1();
        usleep(50); // Simulate some work
    }
    return NULL;
}

void* thread_func_2(void* arg) {
    int num_iterations = *((int*)arg);
    for (int i = 0; i < num_iterations; ++i) {
        process_id_and_list_path2();
        usleep(50); // Simulate some work
    }
    return NULL;
}

int main() {
    pthread_t threads[2];
    int num_iterations = 5;

    pthread_mutex_init(&list_mutex, NULL);
    pthread_mutex_init(&id_mutex, NULL);

    pthread_create(&threads[0], NULL, thread_func_1, &num_iterations);
    pthread_create(&threads[1], NULL, thread_func_2, &num_iterations);

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final List (IDs are not necessarily consecutive due to Path2 increments):\n");
    Node* current = head;
    while (current != NULL) {
        printf("Node ID: %d\n", current->id);
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list_mutex);
    pthread_mutex_destroy(&id_mutex);

    return 0;
}

solution.explanation:
א. הבעיה העיקרית בקוד היא Deadlock (מבוי סתום). ה-deadlock מתרחש כאשר שני תהליכונים או יותר מחזיקים במשאבים (mutex-ים במקרה זה) ומחכים למשאבים המוחזקים על ידי תהליכונים אחרים, וכתוצאה מכך אף אחד מהם אינו יכול להמשיך. במקרה זה, ישנם שני mutex-ים: `list_mutex` ו-`id_mutex`.

תרחיש ספציפי ל-deadlock:
1. תהליכון 1 (המריץ את `add_node_to_list_path1`) מבצע `pthread_mutex_lock(&list_mutex)` ומצליח לרכוש את `list_mutex`.
2. תהליכון 2 (המריץ את `process_id_and_list_path2`) מבצע `pthread_mutex_lock(&id_mutex)` ומצליח לרכוש את `id_mutex`.
3. תהליכון 1 מנסה כעת לבצע `pthread_mutex_lock(&id_mutex)` אך נחסם מכיוון ש-`id_mutex` מוחזק על ידי תהליכון 2.
4. תהליכון 2 מנסה כעת לבצע `pthread_mutex_lock(&list_mutex)` אך נחסם מכיוון ש-`list_mutex` מוחזק על ידי תהליכון 1.

כתוצאה מכך, שני התהליכונים חסומים זה לזה, אף אחד מהם לא יכול לשחרר את ה-mutex שהוא מחזיק, והמערכת נכנסת למצב של deadlock.

ב. כדי לפתור את בעיית ה-deadlock, יש להקפיד על סדר אחיד של רכישת mutex-ים בכל הפונקציות שבהן נדרשים מספר mutex-ים. נבחר, לדוגמה, לרכוש תמיד את `list_mutex` לפני `id_mutex`.

השינויים הנדרשים בקוד (שינוי `process_id_and_list_path2`): 
```c
// Function 1 (no change needed, already locks list_mutex then id_mutex)
void add_node_to_list_path1() {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate new node");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    usleep(10);
    pthread_mutex_lock(&id_mutex);

    new_node->id = next_node_id++;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&id_mutex);
    pthread_mutex_unlock(&list_mutex);
}

// Function 2: Modified to lock list_mutex first, then id_mutex
void process_id_and_list_path2() {
    pthread_mutex_lock(&list_mutex); // Lock list first (consistent order)
    usleep(10);
    pthread_mutex_lock(&id_mutex);   // Then lock ID

    next_node_id++;

    pthread_mutex_unlock(&id_mutex);
    pthread_mutex_unlock(&list_mutex);
}
```

ג. השינויים שהוצעו פותרים את בעיית ה-deadlock על ידי אכיפת סדר רכישת mutex-ים עקבי (consistent locking order) בכל התהליכונים. כאשר כל התהליכונים מנסים לרכוש את ה-mutex-ים באותו סדר (לדוגמה, תמיד `list_mutex` ואז `id_mutex`), מוסרת אחת מארבעת התנאים ההכרחיים ל-deadlock: תנאי ה'המתנה מעגלית' (Circular Wait). אם תהליכון 1 מחזיק ב-`list_mutex` ומחכה ל-`id_mutex`, ותהליכון 2 ינסה לרכוש את `list_mutex` קודם, הוא ייחסם עד שתהליכון 1 ישחרר אותו (לאחר שירכוש וישחרר גם את `id_mutex`). לא ייווצר מצב שבו תהליכון 1 מחכה למשאב שתהליכון 2 מחזיק בו, בעוד שתהליכון 2 מחכה למשאב שתהליכון 1 מחזיק בו. בכך, מובטח שכל תהליכון שרוכש את ה-mutex הראשון יוכל בסופו של דבר לרכוש גם את ה-mutex השני ולהשלים את פעולתו, ובכך למנוע את המבוי הסתום.

