#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// Shared resources
int shared_counter = 0;

typedef struct Node {
    int data;
    struct Node* next;
} Node;
Node* shared_list = NULL;

// Mutexes for shared resources
pthread_mutex_t mutex_counter;
pthread_mutex_t mutex_list;

// Function to add a node to the list
void add_to_list(int val) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate node");
        exit(EXIT_FAILURE);
    }
    new_node->data = val;
    new_node->next = shared_list;
    shared_list = new_node;
}

// Function to remove a node from the list
int remove_from_list() {
    if (shared_list == NULL) {
        return -1; // List is empty
    }
    Node* temp = shared_list;
    int val = temp->data;
    shared_list = shared_list->next;
    free(temp);
    return val;
}

// Thread A function: increments counter, then adds to list
void* thread_A_func(void* arg) {
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex_counter);
        shared_counter++;
        printf("Thread A: Counter incremented to %d\n", shared_counter);

        pthread_mutex_lock(&mutex_list);
        add_to_list(shared_counter);
        printf("Thread A: Added %d to list\n", shared_counter);
        pthread_mutex_unlock(&mutex_list);

        pthread_mutex_unlock(&mutex_counter);
        usleep(100000); // Simulate work
    }
    return NULL;
}

// Thread B function: removes from list, then decrements counter
void* thread_B_func(void* arg) {
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex_list);
        int val = remove_from_list();
        if (val != -1) {
            printf("Thread B: Removed %d from list\n", val);

            pthread_mutex_lock(&mutex_counter);
            shared_counter--;
            printf("Thread B: Counter decremented to %d\n", shared_counter);
            pthread_mutex_unlock(&mutex_counter);
        } else {
            printf("Thread B: List was empty, no decrement.\n");
        }
        pthread_mutex_unlock(&mutex_list);
        usleep(100000); // Simulate work
    }
    return NULL;
}

int main() {
    pthread_t threads[4];

    pthread_mutex_init(&mutex_counter, NULL);
    pthread_mutex_init(&mutex_list, NULL);

    // Create two Thread A and two Thread B
    pthread_create(&threads[0], NULL, thread_A_func, NULL);
    pthread_create(&threads[1], NULL, thread_A_func, NULL);
    pthread_create(&threads[2], NULL, thread_B_func, NULL);
    pthread_create(&threads[3], NULL, thread_B_func, NULL);

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Final Counter: %d\n", shared_counter);
    // Clean up remaining list nodes
    while (shared_list != NULL) {
        remove_from_list();
    }

    pthread_mutex_destroy(&mutex_counter);
    pthread_mutex_destroy(&mutex_list);

    return 0;
}

solution.explanation:
א. הבעיה המרכזית בתוכנית הנתונה היא פוטנציאל ל**קיפאון (Deadlock)**.

ב. **הסבר לבעיה ותנאים להופעתה:**
קיפאון יכול להתרחש במערכות מרובות חוטים המשתמשות במנעולים כאשר מתקיימים ארבעת התנאים ההכרחיים של הופעת קיפאון (תנאי קופמן):
1.  **הדדיות (Mutual Exclusion):** המנעולים (`mutex_counter`, `mutex_list`) מאפשרים רק לחוט אחד להחזיק בהם בכל רגע נתון. תנאי זה מתקיים.
2.  **החזק והמתן (Hold and Wait):** חוט יכול להחזיק במנעול אחד (או יותר) ובמקביל להמתין לרכישת מנעולים נוספים. תנאי זה מתקיים בקוד הנתון: חוט A רוכש את `mutex_counter` ומחזיק בו בזמן שהוא ממתין ל-`mutex_list`. חוט B רוכש את `mutex_list` ומחזיק בו בזמן שהוא ממתין ל-`mutex_counter`.
3.  **אי-הפקעה (No Preemption):** מנעול שנרכש על ידי חוט לא יכול להילקח ממנו בכוח; הוא חייב להיות משוחרר מרצון על ידי החוט המחזיק בו. תנאי זה מתקיים על ידי ה-mutexes של POSIX Threads.
4.  **המתנה מעגלית (Circular Wait):** קיימת שרשרת של שני חוטים או יותר, כאשר כל חוט בשרשרת ממתין למשאב שמוחזק על ידי החוט הבא בשרשרת. תנאי זה מתקיים בקוד הנתון:
    *   חוט A רוכש את `mutex_counter` ואז מנסה לרכוש את `mutex_list`.
    *   חוט B רוכש את `mutex_list` ואז מנסה לרכוש את `mutex_counter`.

    אם חוט A ירכוש את `mutex_counter` וחוט B ירכוש את `mutex_list` בו-זמנית (או בסמיכות זמנים), חוט A ימתין ל-`mutex_list` שמוחזק על ידי חוט B, וחוט B ימתין ל-`mutex_counter` שמוחזק על ידי חוט A. נוצר מעגל המתנה אינסופי, והתוכנית תיתקע.

ג. **פתרון מוצע ושינויים בקוד:**
הדרך הנפוצה והיעילה ביותר למנוע קיפאון כזה היא לשבור את תנאי "המתנה מעגלית" על ידי הבטחה שכל החוטים ירכשו את המנעולים תמיד באותו סדר קבוע. במקרה זה, נבחר סדר קבוע: קודם `mutex_counter` ואז `mutex_list` (ניתן גם לבחור בסדר ההפוך, העיקר שיהיה עקבי בכל המקומות בהם נדרשים שני המנעולים).

**שינויים נדרשים בפונקציית `thread_B_func`:**
יש לשנות את סדר רכישת המנעולים בפונקציית `thread_B_func` כך שתתאים לסדר בפונקציית `thread_A_func`. כלומר, תחילה לרכוש את `mutex_counter` ולאחר מכן את `mutex_list`. יש לשחרר את המנעולים בסדר הפוך לסדר רכישתם.

```c
// Thread B function: removes from list, then decrements counter (FIXED ORDER)
void* thread_B_func(void* arg) {
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex_counter); // Lock counter first (consistent order)
        pthread_mutex_lock(&mutex_list);    // Then lock list (consistent order)

        int val = remove_from_list(); // Access list while both mutexes are held
        if (val != -1) {
            printf("Thread B: Removed %d from list\n", val);
            shared_counter--; // Access counter while both mutexes are held
            printf("Thread B: Counter decremented to %d\n", shared_counter);
        } else {
            printf("Thread B: List was empty, no decrement.\n");
        }

        pthread_mutex_unlock(&mutex_list);    // Unlock list first (reverse order of locking)
        pthread_mutex_unlock(&mutex_counter); // Then unlock counter
        usleep(100000); // Simulate work
    }
    return NULL;
}
```

**הסבר לפתרון:**
על ידי אכיפת סדר רכישת מנעולים עקבי (לדוגמה, תמיד קודם `mutex_counter` ואז `mutex_list`), אנו מונעים את התנאי ההכרחי לקיפאון של "המתנה מעגלית". כעת, אם חוט A מחזיק ב-`mutex_counter` וממתין ל-`mutex_list`, אף חוט B לא יוכל לרכוש את `mutex_counter` (כי הוא כבר תפוס) ולכן ימתין בתור. ברגע שחוט A ישחרר את שני המנעולים, חוט B יוכל לרכוש את `mutex_counter` ורק אז לנסות לרכוש את `mutex_list`. באופן זה, לא יכול להיווצר מצב שבו חוט A ממתין למנעול שמוחזק על ידי חוט B, בזמן שחוט B ממתין למנעול שמוחזק על ידי חוט A. זה מבטיח שהתוכנית תתקדם ותימנע מקיפאון.

