    int id;
} Job;

Job job_queue[MAX_QUEUE_SIZE];
int head = 0;
int tail = 0;
int count = 0;

pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;

int global_completed_jobs = 0; // Shared counter, unprotected

void enqueue_job(Job job) {
    pthread_mutex_lock(&queue_mutex);
    while (count == MAX_QUEUE_SIZE) {
        pthread_cond_wait(&not_full, &queue_mutex);
    }
    job_queue[tail] = job;
    tail = (tail + 1) % MAX_QUEUE_SIZE;
    count++;
    printf("Producer: Enqueued Job %d, queue count: %d\n", job.id, count);
    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&queue_mutex);
}

Job dequeue_job() {
    pthread_mutex_lock(&queue_mutex);
    while (count == 0) {
        pthread_cond_wait(&not_empty, &queue_mutex);
    }
    Job job = job_queue[head];
    head = (head + 1) % MAX_QUEUE_SIZE;
    count--;
    printf("Consumer: Dequeued Job %d, queue count: %d\n", job.id, count);
    pthread_cond_signal(&not_full);
    pthread_mutex_unlock(&queue_mutex);
    return job;
}

void* producer(void* arg) {
    for (int i = 0; i < TOTAL_JOBS_TO_PROCESS; ++i) {
        Job new_job = { .id = i };
        enqueue_job(new_job);
        usleep(rand() % 100000); // Simulate work
    }
    return NULL;
}

void* worker(void* arg) {
    while (1) { 
        Job job = dequeue_job();

        // Simulate job processing
        usleep(rand() % 200000); 

        global_completed_jobs++; // RACE CONDITION HERE!

        printf("Worker %ld: Processed Job %d. Current completed: %d\n", (long)arg, job.id, global_completed_jobs);

        // Termination condition is also problematic due to race condition and blocking dequeue
        if (global_completed_jobs >= TOTAL_JOBS_TO_PROCESS) {
            break;
        }
    }
    return NULL;
}

int main() {
    pthread_t producer_thread;
    pthread_t worker_threads[NUM_WORKERS];

    srand(time(NULL));

    pthread_create(&producer_thread, NULL, producer, NULL);

    for (long i = 0; i < NUM_WORKERS; ++i) {
        pthread_create(&worker_threads[i], NULL, worker, (void*)i);
    }

    pthread_join(producer_thread, NULL);
    printf("Main: Producer finished producing all jobs.\n");

    // Main thread needs to wait for all workers to finish processing.
    // This part is currently not handled gracefully, workers might be stuck.
    for (int i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(worker_threads[i], NULL);
    }

    printf("Main: All workers finished. Final global_completed_jobs: %d\n", global_completed_jobs);

    pthread_mutex_destroy(&queue_mutex);
    pthread_cond_destroy(&not_empty);
    pthread_cond_destroy(&not_full);

    return 0;
}

solution.explanation:
הסבר ופתרון:

**1. זיהוי והסבר תנאי מירוץ (Race Conditions):**
   *   **`global_completed_jobs`**: המשתנה `global_completed_jobs` הוא מונה גלובלי המשותף לכל תהליכי ה-Worker. הפעולה `global_completed_jobs++` אינה אטומית; היא מורכבת מקריאת הערך, הגדלתו, וכתיבת הערך החדש. אם שני תהליכי Worker או יותר מנסים לבצע פעולה זו בו-זמנית, ייתכן מצב שבו הם קוראים את אותו ערך ישן, מבצעים הגדלה, ושניהם כותבים בחזרה את אותו ערך (או ערך שגוי) – מה שיוביל לכך שהמונה לא ישקף נכונה את מספר המשימות שהושלמו. לדוגמה, אם `global_completed_jobs` הוא 5, שני תהליכים קוראים 5, שניהם מגדילים ל-6, ושניהם כותבים 6 בחזרה, במקום שיהיה 7.
   *   **תנאי סיום של ה-Worker**: תנאי הסיום `if (global_completed_jobs >= TOTAL_JOBS_TO_PROCESS)` בתוך פונקציית ה-`worker` סובל אף הוא מתנאי מירוץ. בשל חוסר ההגנה על `global_completed_jobs`, ייתכן שתהליך אחד יקרא ערך מסוים, בעוד שתהליך אחר יעלה אותו, ורק לאחר מכן התהליך הראשון ישווה אותו. בנוסף, אם תהליך אחד מסיים ופורש (`break`), אחרים עדיין יכולים להישאר פעילים או לחכות לתור ריק, מה שיוביל ללוגיקת סיום לא עקבית ולא בטוחה.

**2. פוטנציאל לקיפאון (Deadlock) או רעב (Starvation):**
   *   **קיפאון**: בקוד הנתון, אין קיפאון מובהק (Classic Deadlock) מכיוון שמשתמשים רק ב-`queue_mutex` אחד, ואין חסימה הדדית על משאבים שונים. עם זאת, אם היינו מנסים לתקן את תנאי המירוץ על `global_completed_jobs` על ידי הוספת `mutex` נפרד (לדוגמה `counter_mutex`) ונועלים אותו בסדר שונה מ-`queue_mutex` (לדוגמה, תהליך Worker היה נועל את `queue_mutex` ואז מנסה לנעול את `counter_mutex`, בעוד שהתהליך הראשי היה מנסה לנעול את `counter_mutex` ואז את `queue_mutex` כדי לבדוק סיום), יכול היה להיווצר קיפאון. בקוד הנוכחי, בעיית הקיפאון אינה קיימת.
   *   **רעב (Starvation)**: בקוד הנתון, אין רעב מובהק. המשתנים התנאים (`not_empty`, `not_full`) בשילוב עם `pthread_cond_wait` ו-`pthread_cond_signal` (בתוך לולאות `while`) מבטיחים שתהליכים יקבלו את ההזדמנות להתקדם ברגע שהתנאים שלהם מתקיימים. עם זאת, במערכות גדולות יותר, אם יש הרבה מאוד תהליכים שמתחרים על אותו משאב, ייתכן שתהליך מסוים יקבל פחות זמן מעבד או יתעכב באופן עקבי, אך זה לא תרחיש ספציפי לקוד זה.

**3. פתרונות ושינויים בקוד (כולל סיום עבודה גרייספוּלי):**

כדי לתקן את הבעיות וליישם סיום עבודה גרייספוּלי, נבצע את השינויים הבאים:

א. **הגנה על `global_completed_jobs`**: נוסיף `mutex` ייעודי למשתנה זה וכן `condition variable` כדי שהתהליך הראשי יוכל להמתין לסיום כל המשימות.
ב. **מנגנון סיום עבודה גרייספוּלי**: נשתמש ב"גלולת רעל" (Poison Pill) – משימה מיוחדת שאינה מעובדת אלא מסמנת ל-Worker שאין עוד משימות לבצע ועליו לסיים. כל Worker שנתקל בגלולת רעל יעביר אותה הלאה (אם יש עוד Workers) ויסיים את פעולתו. בנוסף, נבטיח שהתהליך הראשי ממתין עד שכל המשימות הושלמו וכל ה-Workers סיימו.

**קוד מתוקן:**

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h> // For usleep

#define MAX_QUEUE_SIZE 5
#define NUM_WORKERS 3
#define TOTAL_JOBS_TO_PROCESS 10

typedef struct {
    int id;
    int is_poison_pill; // Flag for graceful termination
} Job;

Job job_queue[MAX_QUEUE_SIZE];
int head = 0;
int tail = 0;
int count = 0;

pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;

pthread_mutex_t completed_jobs_mutex = PTHREAD_MUTEX_INITIALIZER; // New mutex for global_completed_jobs
pthread_cond_t all_jobs_done = PTHREAD_COND_INITIALIZER; // New condition variable
int global_completed_jobs = 0;

void enqueue_job(Job job) {
    pthread_mutex_lock(&queue_mutex);
    while (count == MAX_QUEUE_SIZE) {
        pthread_cond_wait(&not_full, &queue_mutex);
    }
    job_queue[tail] = job;
    tail = (tail + 1) % MAX_QUEUE_SIZE;
    count++;
    printf("Producer: Enqueued Job %d (Poison: %d), queue count: %d\n", job.id, job.is_poison_pill, count);
    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&queue_mutex);
}

Job dequeue_job() {
    pthread_mutex_lock(&queue_mutex);
    while (count == 0) {
        pthread_cond_wait(&not_empty, &queue_mutex);
    }
    Job job = job_queue[head];
    head = (head + 1) % MAX_QUEUE_SIZE;
    count--;
    printf("Consumer: Dequeued Job %d (Poison: %d), queue count: %d\n", job.id, job.is_poison_pill, count);
    pthread_cond_signal(&not_full);
    pthread_mutex_unlock(&queue_mutex);
    return job;
}

void* producer(void* arg) {
    for (int i = 0; i < TOTAL_JOBS_TO_PROCESS; ++i) {
        Job new_job = { .id = i, .is_poison_pill = 0 };
        enqueue_job(new_job);
        usleep(rand() % 100000); // Simulate work
    }
    // Enqueue poison pills for each worker to signal termination
    for (int i = 0; i < NUM_WORKERS; ++i) {
        Job poison_pill = { .id = -1, .is_poison_pill = 1 };
        enqueue_job(poison_pill);
    }
    return NULL;
}

void* worker(void* arg) {
    while (1) { 
        Job job = dequeue_job();

        if (job.is_poison_pill) {
            // Propagate the poison pill for other workers
            enqueue_job(job); 
            break; // This worker exits
        }

        // Simulate job processing
        usleep(rand() % 200000); 

        // Protect global_completed_jobs
        pthread_mutex_lock(&completed_jobs_mutex);
        global_completed_jobs++;
        if (global_completed_jobs == TOTAL_JOBS_TO_PROCESS) {
            pthread_cond_signal(&all_jobs_done); // Signal main thread if all jobs are done
        }
        pthread_mutex_unlock(&completed_jobs_mutex);

        printf("Worker %ld: Processed Job %d. Current completed: %d\n", (long)arg, job.id, global_completed_jobs);
    }
    return NULL;
}

int main() {
    pthread_t producer_thread;
    pthread_t worker_threads[NUM_WORKERS];

    srand(time(NULL));

    pthread_create(&producer_thread, NULL, producer, NULL);

    for (long i = 0; i < NUM_WORKERS; ++i) {
        pthread_create(&worker_threads[i], NULL, worker, (void*)i);
    }

    pthread_join(producer_thread, NULL);
    printf("Main: Producer finished producing all jobs and sent poison pills.\n");

    // Main thread waits for all jobs to be completed
    pthread_mutex_lock(&completed_jobs_mutex);
    while (global_completed_jobs < TOTAL_JOBS_TO_PROCESS) {
        pthread_cond_wait(&all_jobs_done, &completed_jobs_mutex);
    }
    pthread_mutex_unlock(&completed_jobs_mutex);
    printf("Main: All %d jobs have been processed.\n", global_completed_jobs);

    // Now join worker threads. They should all have terminated due to poison pills.
    for (int i = 0; i < NUM_WORKERS; ++i) {
        pthread_join(worker_threads[i], NULL);
    }

    printf("Main: All workers finished. Final global_completed_jobs: %d\n", global_completed_jobs);

    pthread_mutex_destroy(&queue_mutex);
    pthread_cond_destroy(&not_empty);
    pthread_cond_destroy(&not_full);
    pthread_mutex_destroy(&completed_jobs_mutex);
    pthread_cond_destroy(&all_jobs_done);

    return 0;
}
```

**הסבר לשינויים:**

*   **`Job` struct**: הוספנו שדה `is_poison_pill` כדי לסמן משימות מיוחדות המשמשות לאיתות סיום.
*   **`completed_jobs_mutex` ו-`all_jobs_done`**: הוספנו `mutex` נפרד (`completed_jobs_mutex`) כדי להגן על `global_completed_jobs` ו-`condition variable` (`all_jobs_done`) כדי שהתהליך הראשי יוכל להמתין באופן יעיל לסיום כל המשימות מבלי לבצע ספין-לופ או לחסום משאבים אחרים. זה מונע את תנאי המירוץ על `global_completed_jobs`.
*   **`producer` function**: לאחר יצירת כל המשימות הרגילות, ה-Producer מוסיף `NUM_WORKERS` "גלולות רעל" לתור. כל גלולת רעל מיועדת לאותת ל-Worker אחד לסיים את פעולתו.
*   **`worker` function**: ה-Worker בודק האם המשימה שקיבל היא גלולת רעל. אם כן, הוא מעביר אותה הלאה לתור (באמצעות `enqueue_job`) כדי ש-Workers אחרים יוכלו לקבל אותה ולסיים, ויוצא מהלולאה שלו (`break`). פעולה זו מבטיחה שכל ה-Workers יקבלו את האות לסיים. העברת גלולת הרעל הלאה היא קריטית במקרה שיש יותר מ-Worker אחד, כדי שכולם יקבלו את האות.
*   **עדכון `global_completed_jobs`**: בתוך ה-Worker, ההגדלה של `global_completed_jobs` נעשית כעת בתוך קטע קריטי המוגן על ידי `completed_jobs_mutex`, מה שמונע את תנאי המירוץ. בנוסף, כאשר `global_completed_jobs` מגיע ל-`TOTAL_JOBS_TO_PROCESS`, נשלח `signal` ל-`all_jobs_done` כדי להעיר את התהליך הראשי.
*   **`main` function**: התהליך הראשי ממתין כעת על `all_jobs_done` בתוך לולאת `while` המוגנת על ידי `completed_jobs_mutex`. לאחר קבלת האות שכל המשימות הושלמו, הוא ממשיך לבצע `pthread_join` על כל ה-Workers, שכבר אמורים להיות בתהליך סיום עקב גלולות הרעל. סדר זה מבטיח סיום עבודה נכון וגרייספוּלי.
*   **ניקוי משאבים**: הוספנו קריאות ל-`pthread_mutex_destroy` ו-`pthread_cond_destroy` כדי לשחרר את המשאבים של המנעולים והמשתנים התנאים בסיום התוכנית.

