#include <pthread.h>
#include <stdio.h>
#include <stdlib.h> // For exit

#define NUM_THREADS 5
#define ITERATIONS_PER_THREAD 1000000

long long global_counter = 0;
pthread_mutex_t mutex;

void* thread_function(void* arg) {
    long long local_iterations = ITERATIONS_PER_THREAD;
    while (local_iterations > 0) {
        long long temp = global_counter; // BUG: Read outside lock
        pthread_mutex_lock(&mutex);
        global_counter = temp + 1;      // Write inside lock
        pthread_mutex_unlock(&mutex);
        local_iterations--;
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, NULL) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            exit(EXIT_FAILURE);
        }
    }

    printf("Final global counter value: %lld\n", global_counter);
    printf("Expected value: %lld\n", (long long)NUM_THREADS * ITERATIONS_PER_THREAD);

    pthread_mutex_destroy(&mutex);
    return 0;
}

solution.explanation:
א. הבעיה בקטע הקוד היא תנאי מרוץ (Race Condition) המוביל לאובדן עדכונים (Lost Updates) של המונה הגלובלי. פעולת ההגדלה של המונה, `global_counter++`, אינה פעולה אטומית בפועל ברמת המעבד. היא מורכבת משלושה שלבים עיקריים:
1.  קריאת הערך הנוכחי של `global_counter` לתוך רגיסטר (או משתנה זמני, במקרה זה `temp`).
2.  הגדלת הערך ברגיסטר באחד.
3.  כתיבת הערך המוגדל מהרגיסטר בחזרה ל`global_counter`.

בקטע הקוד הנתון, השלב הראשון (קריאת הערך לתוך `temp = global_counter;`) מתבצע מחוץ לאזור הקריטי המוגן על ידי המנעול. כלומר, תהליכון יכול לקרוא את הערך של `global_counter` לתוך המשתנה המקומי `temp`, ואז לפני שהוא מספיק לנעול את המנעול ולכתוב את הערך המוגדל בחזרה, תהליכון אחר יכול גם הוא לקרוא את אותו ערך ישן של `global_counter`. כאשר שני התהליכונים כותבים בחזרה את הערך המוגדל (כל אחד בתורו, בתוך אזור מוגן), אחד מהעדכונים יאבד מכיוון ששניהם התבססו על אותו ערך התחלתי שנקרא לפני שהמנעול נתפס.

ההשלכות הן שהמונה הגלובלי יכיל בסיום הרצת התוכנית ערך נמוך מהצפוי. ככל שמספר התהליכונים והאיטרציות גדול יותר, כך גדל הסיכוי לאובדן עדכונים, והפער בין הערך בפועל לערך הצפוי יגדל.

ב. הפתרון המתוקן דורש שהקריאה, ההגדלה והכתיבה של המונה הגלובלי יתבצעו כולן בתוך האזור הקריטי המוגן על ידי המנעול. הדרך הפשוטה והנכונה ביותר היא להשתמש באופרטור ההגדלה `++` בתוך האזור המוגן, מכיוון שהוא מייצג את כל שלושת השלבים של הפעולה.

```c
void* thread_function(void* arg) {
    long long local_iterations = ITERATIONS_PER_THREAD;
    while (local_iterations > 0) {
        pthread_mutex_lock(&mutex);
        global_counter++; // Corrected: All operations (read, increment, write) are inside the lock
        pthread_mutex_unlock(&mutex);
        local_iterations--;
    }
    return NULL;
}
```

הפתרון המתוקן מבטיח עבודה נכונה מכיוון שעתה כל שלושת השלבים של פעולת ההגדלה (קריאה, הגדלה, כתיבה) מוגנים על ידי המנעול. כאשר תהליכון אחד מחזיק את המנעול, אף תהליכון אחר אינו יכול להיכנס לאזור הקריטי ולגשת ל`global_counter`. זה מבטיח שאף קריאה לא תתבסס על ערך מיושן, ושאף עדכון לא יאבד. כל תהליכון שיבצע את ההגדלה יראה את הערך העדכני ביותר של המונה, ויגדיל אותו באופן בלעדי לפני שחרור המנעול ומאפשר לתהליכון הבא לגשת אליו. בכך נמנע תנאי המרוץ ונשמרת נכונות המונה הגלובלי.

