#include <iostream>
#include <vector>
#include <pthread.h>
#include <unistd.h> // For usleep

// Shared resources
int shared_counter = 0;
std::vector<int> shared_data;

// Mutexes
pthread_mutex_t counter_mutex;
pthread_mutex_t data_mutex;

void* producer_thread(void* arg) {
    for (int i = 0; i < 5; ++i) {
        // Producer acquires counter_mutex then data_mutex
        pthread_mutex_lock(&counter_mutex);
        pthread_mutex_lock(&data_mutex);

        shared_counter++;
        shared_data.push_back(shared_counter);
        std::cout << "Producer: Added " << shared_counter << ". Current size: " << shared_data.size() << std::endl;

        pthread_mutex_unlock(&data_mutex);
        pthread_mutex_unlock(&counter_mutex);
        usleep(100000); // Simulate work
    }
    return NULL;
}

void* consumer_thread(void* arg) {
    for (int i = 0; i < 5; ++i) {
        // Consumer acquires data_mutex then counter_mutex
        pthread_mutex_lock(&data_mutex);
        pthread_mutex_lock(&counter_mutex);

        if (!shared_data.empty()) {
            int value = shared_data.back();
            shared_data.pop_back();
            shared_counter--;
            std::cout << "Consumer: Removed " << value << ". Current size: " << shared_data.size() << std::endl;
        } else {
            std::cout << "Consumer: Data is empty." << std::endl;
        }

        pthread_mutex_unlock(&counter_mutex);
        pthread_mutex_unlock(&data_mutex);
        usleep(150000); // Simulate work
    }
    return NULL;
}

int main() {
    pthread_mutex_init(&counter_mutex, NULL);
    pthread_mutex_init(&data_mutex, NULL);

    pthread_t p_threads[2];
    pthread_t c_threads[2];

    for (int i = 0; i < 2; ++i) {
        pthread_create(&p_threads[i], NULL, producer_thread, NULL);
        pthread_create(&c_threads[i], NULL, consumer_thread, NULL);
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(p_threads[i], NULL);
        pthread_join(c_threads[i], NULL);
    }

    pthread_mutex_destroy(&counter_mutex);
    pthread_mutex_destroy(&data_mutex);

    std::cout << "Final counter: " << shared_counter << std::endl;
    std::cout << "Final data size: " << shared_data.size() << std::endl;

    return 0;
}

solution.explanation:
הבעיה הקריטית בקוד היא מצב קיפאון (Deadlock). 

**הסבר הבעיה:**
תהליכוני המפיק (producer_thread) מנסים לרכוש את המנעולים בסדר הבא: `counter_mutex` ולאחר מכן `data_mutex`. 
תהליכוני הצרכן (consumer_thread) מנסים לרכוש את המנעולים בסדר הפוך: `data_mutex` ולאחר מכן `counter_mutex`. 
אם תהליכון מפיק אחד רוכש את `counter_mutex` ובמקביל תהליכון צרכן אחד רוכש את `data_mutex`, שניהם ימתינו זה לזה באופן אינסופי כדי לרכוש את המנעול השני. המפיק ממתין ל-`data_mutex` שהצרכן מחזיק, והצרכן ממתין ל-`counter_mutex` שהמפיק מחזיק. מצב זה מוביל לקיפאון, שבו כל התהליכונים המעורבים מפסיקים להתקדם והתוכנית נתקעת.

**השפעה על המערכת:**
קיפאון גורם לכך שהתוכנית מפסיקה להגיב, לא מבצעת פעולות נוספות ומשאבים נשארים נעולים, מה שעלול להוביל לחוסר זמינות של שירותים או איבוד נתונים במערכות מורכבות יותר.

**פתרון מוצע:**
כדי למנוע קיפאון כתוצאה מסדר רכישת מנעולים שונה, יש להקפיד על סדר רכישה עקבי של המנעולים בכל התהליכונים. נבחר שכל התהליכונים ירכשו תמיד קודם את `counter_mutex` ולאחר מכן את `data_mutex`.

**קוד מתוקן (רק פונקציית `consumer_thread` משתנה):**
```c
void* consumer_thread(void* arg) {
    for (int i = 0; i < 5; ++i) {
        // Consumer now acquires counter_mutex then data_mutex (consistent order)
        pthread_mutex_lock(&counter_mutex);
        pthread_mutex_lock(&data_mutex);

        if (!shared_data.empty()) {
            int value = shared_data.back();
            shared_data.pop_back();
            shared_counter--;
            std::cout << "Consumer: Removed " << value << ". Current size: " << shared_data.size() << std::endl;
        } else {
            std::cout << "Consumer: Data is empty." << std::endl;
        }

        pthread_mutex_unlock(&data_mutex);
        pthread_mutex_unlock(&counter_mutex);
        usleep(150000); // Simulate work
    }
    return NULL;
}
```

**הסבר הפתרון:**
על ידי אכיפת סדר רכישת מנעולים אחיד (לדוגמה, תמיד `counter_mutex` ואז `data_mutex`), אנו מונעים את התנאי ההכרחי לקיפאון של "החזקה והמתנה מעגלית" (Circular Wait). כעת, אם תהליכון כלשהו מחזיק ב-`counter_mutex`, אף תהליכון אחר לא יוכל לרכוש אותו לפני שהתהליכון הראשון ישחרר אותו. רק לאחר רכישת `counter_mutex`, התהליכון ינסה לרכוש את `data_mutex`. כך, אין אפשרות למצב שבו תהליכון אחד מחזיק ב-A וממתין ל-B, בעוד תהליכון אחר מחזיק ב-B וממתין ל-A.

content.code_snippet:
#include <iostream>
#include <pthread.h>
#include <unistd.h> // For usleep

// Shared resources
int resource1 = 0;
int resource2 = 0;

// Mutexes for shared resources
pthread_mutex_t mutex1 = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex2 = PTHREAD_MUTEX_INITIALIZER;

// Thread function that acquires mutex1 then mutex2
void* thread_func_A(void* arg) {
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex1);
        pthread_mutex_lock(&mutex2);

        // Critical section
        resource1++;
        resource2++;
        std::cout << "Thread A: R1=" << resource1 << ", R2=" << resource2 << std::endl;

        pthread_mutex_unlock(&mutex2);
        pthread_mutex_unlock(&mutex1);
        usleep(100000); // Simulate some work
    }
    return NULL;
}

// Thread function that acquires mutex2 then mutex1
void* thread_func_B(void* arg) {
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex2);
        pthread_mutex_lock(&mutex1);

        // Critical section
        resource1--;
        resource2--;
        std::cout << "Thread B: R1=" << resource1 << ", R2=" << resource2 << std::endl;

        pthread_mutex_unlock(&mutex1);
        pthread_mutex_unlock(&mutex2);
        usleep(100000); // Simulate some work
    }
    return NULL;
}

int main() {
    pthread_t tid[4];

    // Create threads
    pthread_create(&tid[0], NULL, thread_func_A, NULL);
    pthread_create(&tid[1], NULL, thread_func_B, NULL);
    pthread_create(&tid[2], NULL, thread_func_A, NULL);
    pthread_create(&tid[3], NULL, thread_func_B, NULL);

    // Join threads
    for (int i = 0; i < 4; ++i) {
        pthread_join(tid[i], NULL);
    }

    // Destroy mutexes
    pthread_mutex_destroy(&mutex1);
    pthread_mutex_destroy(&mutex2);

    std::cout << "Final R1=" << resource1 << ", R2=" << resource2 << std::endl;

    return 0;
}

solution.explanation:
א. הבעיה המרכזית בקוד היא פוטנציאל לקיפאון (deadlock). קיפאון יכול להתרחש כאשר שני תהליכונים (או יותר) מנסים לרכוש מספר מנעולים (mutexes) בסדר הפוך. בקוד הנתון:
- `thread_func_A` רוכש קודם את `mutex1` ואז את `mutex2`.
- `thread_func_B` רוכש קודם את `mutex2` ואז את `mutex1`.
תרחיש קיפאון אפשרי הוא כדלקמן: תהליכון A מתחיל ורוכש את `mutex1`. במקביל, תהליכון B מתחיל ורוכש את `mutex2`. כעת, תהליכון A מנסה לרכוש את `mutex2` (שמוחזק על ידי B) ונכנס למצב המתנה. במקביל, תהליכון B מנסה לרכוש את `mutex1` (שמוחזק על ידי A) ונכנס גם הוא למצב המתנה. שני התהליכונים ממתינים זה לזה באופן אינסופי, והתוכנית נתקעת (deadlocked).
אין כאן בעיית race condition על `resource1` או `resource2` כשלעצמן, כיוון שכל גישה למשאבים אלו מוגנת על ידי רכישה של שני המנעולים. הבעיה היא בסדר רכישת המנעולים.

ב. כדי למנוע קיפאון, יש להבטיח שכל התהליכונים ירכשו את המנעולים באותו סדר קבוע. הדרך הפשוטה ביותר לפתור את הבעיה היא לשנות את `thread_func_B` כך שירכוש את המנעולים באותו סדר כמו `thread_func_A`, כלומר קודם `mutex1` ואז `mutex2`.

הקוד המתוקן ייראה כך:
```c
#include <iostream>
#include <pthread.h>
#include <unistd.h> // For usleep

// Shared resources
int resource1 = 0;
int resource2 = 0;

// Mutexes for shared resources
pthread_mutex_t mutex1 = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex2 = PTHREAD_MUTEX_INITIALIZER;

// Thread function that acquires mutex1 then mutex2
void* thread_func_A(void* arg) {
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex1);
        pthread_mutex_lock(&mutex2);

        // Critical section
        resource1++;
        resource2++;
        std::cout << "Thread A: R1=" << resource1 << ", R2=" << resource2 << std::endl;

        pthread_mutex_unlock(&mutex2);
        pthread_mutex_unlock(&mutex1);
        usleep(100000); // Simulate some work
    }
    return NULL;
}

// Corrected thread function: acquires mutex1 then mutex2 (same order as A)
void* thread_func_B_corrected(void* arg) {
    for (int i = 0; i < 5; ++i) {
        pthread_mutex_lock(&mutex1); // Changed order
        pthread_mutex_lock(&mutex2); // Changed order

        // Critical section
        resource1--;
        resource2--;
        std::cout << "Thread B (corrected): R1=" << resource1 << ", R2=" << resource2 << std::endl;

        pthread_mutex_unlock(&mutex2);
        pthread_mutex_unlock(&mutex1);
        usleep(100000); // Simulate some work
    }
    return NULL;
}

int main() {
    pthread_t tid[4];

    // Create threads
    pthread_create(&tid[0], NULL, thread_func_A, NULL);
    pthread_create(&tid[1], NULL, thread_func_B_corrected, NULL); // Use corrected function
    pthread_create(&tid[2], NULL, thread_func_A, NULL);
    pthread_create(&tid[3], NULL, thread_func_B_corrected, NULL); // Use corrected function

    // Join threads
    for (int i = 0; i < 4; ++i) {
        pthread_join(tid[i], NULL);
    }

    // Destroy mutexes
    pthread_mutex_destroy(&mutex1);
    pthread_mutex_destroy(&mutex2);

    std::cout << "Final R1=" << resource1 << ", R2=" << resource2 << std::endl;

    return 0;
}
```
על ידי הקפדה על סדר אחיד לרכישת מנעולים (לדוגמה, תמיד קודם `mutex1` ואז `mutex2`), אנו מבטלים את התנאי הרביעי מבין ארבעת התנאים ההכרחיים לקיפאון – תנאי ההמתנה המעגלית (Circular Wait). כעת, אם תהליכון אחד מחזיק ב-`mutex1` וממתין ל-`mutex2`, שום תהליכון אחר לא יוכל להחזיק ב-`mutex2` ולחכות ל-`mutex1` בו זמנית, מכיוון שכולם מנסים לרכוש את `mutex1` קודם. זה מבטיח שהתוכנית תרוץ ללא חשש מקיפאון כתוצאה מסדר רכישת המנעולים.

content.code_snippet:
#include <iostream>
#include <thread>
#include <mutex>
#include <vector>
#include <chrono>

class SharedCounter {
private:
    int value;
    std::mutex mtx;

public:
    SharedCounter() : value(0) {}

    void increment() {
        std::lock_guard<std::mutex> lock(mtx);
        value++;
    }

    void decrement() {
        mtx.lock();
        value--;
        mtx.unlock();
    }

    int get_value() {
        return value;
    }

    void reset() {
        value = 0;
    }

    int add_and_get(int val) {
        mtx.lock();
        value += val;
        mtx.unlock();
        return value;
    }

    bool swap_if_greater(int old_val, int new_val) {
        std::lock_guard<std::mutex> lock(mtx);
        int current_val = get_value();
        if (current_val > old_val) {
            value = new_val;
            return true;
        }
        return false;
    }
};

solution.explanation:
הקדמה:
הקוד הנתון מנסה ליישם מונה משותף (SharedCounter) בטוח לשימוש בתהליכונים, אך הוא מכיל מספר בעיות סנכרון חמורות שעלולות להוביל לשגיאות לוגיות, נתונים לא עקביים ואף למבוי סתום (deadlock). הבעיות נובעות בעיקר משימוש שגוי או חסר במנגנוני נעילה.

פירוט הבעיות והפתרונות:

1.  **בעיה בפונקציה `decrement()`:**
    *   **תיאור הבעיה:** הפונקציה משתמשת בנעילה ובשחרור ידניים של המנעול (`mtx.lock()`, `mtx.unlock()`) במקום להשתמש במנגנון RAII כמו `std::lock_guard`. אם הפעולה `value--` תזרוק חריגה (exception) מסיבה כלשהי, השורה `mtx.unlock()` לא תתבצע. כתוצאה מכך, המנעול יישאר נעול לצמיתות, וכל תהליכון אחר שינסה לגשת למונה באמצעות נעילה ייכנס למצב של מבוי סתום (deadlock) ולא יוכל להתקדם.
    *   **פתרון:** יש להשתמש ב-`std::lock_guard<std::mutex>` כדי להבטיח שהמנעול ישוחרר אוטומטית כאשר הפונקציה יוצאת, בין אם באופן רגיל ובין אם עקב חריגה.
    *   **קוד מתוקן:**
        ```cpp
        void decrement() {
            std::lock_guard<std::mutex> lock(mtx);
            value--;
        }
        ```

2.  **בעיה בפונקציה `get_value()`:**
    *   **תיאור הבעיה:** הפונקציה מחזירה את ערך המונה (`value`) ללא כל נעילה. זוהי דוגמה קלאסית ל**מצב מרוץ (race condition)**. אם תהליכון אחד קורא את הערך באמצעות `get_value()` באותו זמן שתהליכון אחר משנה אותו (למשל, באמצעות `increment()`, `decrement()`, `reset()`, `add_and_get()` או `swap_if_greater()`), התהליכון הקורא עלול לקבל ערך חלקי, לא עקבי או מיושן. הקריאה אינה אטומית ביחס לשינויים אחרים.
    *   **פתרון:** יש להגן על קריאת הערך באמצעות המנעול, בדיוק כמו פעולות הכתיבה.
    *   **קוד מתוקן:**
        ```cpp
        int get_value() {
            std::lock_guard<std::mutex> lock(mtx);
            return value;
        }
        ```

3.  **בעיה בפונקציה `reset()`:**
    *   **תיאור הבעיה:** הפונקציה מאפסת את ערך המונה (`value = 0`) ללא כל נעילה. זוהי גם דוגמה ל**מצב מרוץ (race condition)**. אם תהליכון אחד מנסה לאפס את המונה בעוד תהליכון אחר משנה אותו, פעולת האיפוס עלולה להיקטע או לדרוס שינויים אחרים, מה שיוביל לערך סופי שגוי ולא צפוי.
    *   **פתרון:** יש להגן על פעולת האיפוס באמצעות המנעול.
    *   **קוד מתוקן:**
        ```cpp
        void reset() {
            std::lock_guard<std::mutex> lock(mtx);
            value = 0;
        }
        ```

4.  **בעיות בפונקציה `add_and_get(int val)`:**
    *   **תיאור הבעיה (חלק א' - נעילה):** בדומה ל-`decrement()`, הפונקציה משתמשת בנעילה ושחרור ידניים (`mtx.lock()`, `mtx.unlock()`). אם `value += val` תזרוק חריגה, המנעול לא ישוחרר ויווצר מצב של מבוי סתום.
    *   **תיאור הבעיה (חלק ב' - ערך מוחזר):** גם לאחר תיקון בעיית הנעילה הידנית, ישנו מצב מרוץ עדין הקשור לערך המוחזר. הכוונה של "add_and_get" היא בדרך כלל להוסיף ערך למונה ולהחזיר את ערכו *מיד לאחר* ההוספה, כחלק בלתי נפרד מהפעולה האטומית. בקוד המקורי, המנעול משוחרר לפני ש-`value` מוחזר. המשמעות היא שבין השחרור של המנעול לבין השורה `return value;`, תהליכון אחר יכול לשנות את `value`. כתוצאה מכך, הערך שיוחזר עלול להיות שונה מהערך שהיה למונה מיד לאחר ההוספה שבוצעה על ידי התהליכון הקורא.
    *   **פתרון:**
        *   חלק א': יש להשתמש ב-`std::lock_guard`.
        *   חלק ב': כדי להבטיח שהערך המוחזר הוא הערך שהיה למונה מיד לאחר ההוספה האטומית, יש להחזיר את `value` כאשר המנעול עדיין מוחזק. ה-`std::lock_guard` מבטיח זאת באופן טבעי.
    *   **קוד מתוקן:**
        ```cpp
        int add_and_get(int val) {
            std::lock_guard<std::mutex> lock(mtx);
            value += val;
            return value; // הערך מוחזר כאשר המנעול עדיין מוחזק
        }
        ```

5.  **בעיה בפונקציה `swap_if_greater(int old_val, int new_val)`:**
    *   **תיאור הבעיה:** הפונקציה משתמשת ב-`std::lock_guard` כראוי כדי להגן על הקטע הקריטי שלה. עם זאת, בתוך הקטע הקריטי המוגן, היא קוראת לפונקציה `get_value()`. כפי שצוין בבעיה 2, הפונקציה `get_value()` אינה מוגנת על ידי מנעול.
        *   **השלכה ראשונה:** קריאה ל-`get_value()` לא מוגן מתוך פונקציה מוגנת יוצרת חור אבטחה בסנכרון. למרות ש-`swap_if_greater` מחזיקה את המנעול `mtx`, הרי ש-`get_value()` קוראת ישירות ל-`value` ללא נעילה נוספת. אם תהליכונים אחרים (שאינם מוגנים כראוי, כמו `reset()` המקורי או `get_value()` שנקרא מבחוץ) ניגשים ל-`value` במקביל, הנתונים הנקראים על ידי `get_value()` יכולים להיות לא עקביים או שגויים, למרות ש-`swap_if_greater` אמורה להיות מוגנת.
        *   **השלכה שנייה (פוטנציאל למבוי סתום אם `get_value` הייתה נעולה):** אם `get_value()` הייתה מיושמת באופן שבו היא מנסה לרכוש את אותו מנעול (`mtx`) (לדוגמה, אם היה בה `std::lock_guard<std::mutex> lock2(mtx);`), קריאה כזו מתוך `swap_if_greater` (שכבר מחזיקה את `mtx`) הייתה גורמת ל**מבוי סתום (deadlock)**. הסיבה היא ש-`std::mutex` אינו מנעול רה-כניס (non-recursive), ותהליכון אינו יכול לרכוש אותו פעמיים.
    *   **פתרון:** כאשר פונקציה כבר מחזיקה מנעול, היא צריכה לגשת ישירות למשתנים המוגנים על ידי אותו מנעול, או לקרוא לפונקציות עזר פנימיות שבהן מניחים שהמנעול כבר מוחזק (ולא מנסות לרכוש אותו שוב). במקרה זה, `swap_if_greater` כבר מחזיקה את המנעול, ולכן יכולה לגשת ישירות ל-`value`.
    *   **קוד מתוקן:**
        ```cpp
        bool swap_if_greater(int old_val, int new_val) {
            std::lock_guard<std::mutex> lock(mtx);
            // גישה ישירה ל-value מכיוון שהמנעול כבר מוחזק
            if (value > old_val) {
                value = new_val;
                return true;
            }
            return false;
        }
        ```

