#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define BUFFER_SIZE 5
#define NUM_PRODUCERS 2
#define NUM_CONSUMERS 2
#define MAX_ITEMS_PER_THREAD 10

int buffer[BUFFER_SIZE];
int count = 0;
int in = 0;
int out = 0;

pthread_mutex_t mutex;
pthread_cond_t cond_buffer_not_full;  // Signaled when buffer is not full
pthread_cond_t cond_buffer_not_empty; // Signaled when buffer is not empty

void* producer(void* arg) {
    int item;
    for (int i = 0; i < MAX_ITEMS_PER_THREAD; ++i) {
        item = rand() % 100;
        pthread_mutex_lock(&mutex);
        while (count == BUFFER_SIZE) {
            pthread_cond_wait(&cond_buffer_not_full, &mutex);
        }
        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        count++;
        printf("Producer %ld produced: %d, count: %d\n", (long)arg, item, count);
        pthread_cond_signal(&cond_buffer_not_full); // BUG: Should signal cond_buffer_not_empty
        pthread_mutex_unlock(&mutex);
        usleep(100000);
    }
    return NULL;
}

void* consumer(void* arg) {
    int item;
    for (int i = 0; i < MAX_ITEMS_PER_THREAD; ++i) {
        pthread_mutex_lock(&mutex);
        while (count == 0) {
            pthread_cond_wait(&cond_buffer_not_empty, &mutex);
        }
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count--;
        printf("Consumer %ld consumed: %d, count: %d\n", (long)arg, item, count);
        pthread_cond_signal(&cond_buffer_not_empty); // BUG: Should signal cond_buffer_not_full
        pthread_mutex_unlock(&mutex);
        usleep(150000);
    }
    return NULL;
}

int main() {
    pthread_t producers[NUM_PRODUCERS];
    pthread_t consumers[NUM_CONSUMERS];

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond_buffer_not_full, NULL);
    pthread_cond_init(&cond_buffer_not_empty, NULL);

    srand(time(NULL));

    for (long i = 0; i < NUM_PRODUCERS; ++i) {
        pthread_create(&producers[i], NULL, producer, (void*)i);
    }

    for (long i = 0; i < NUM_CONSUMERS; ++i) {
        pthread_create(&consumers[i], NULL, consumer, (void*)i);
    }

    for (int i = 0; i < NUM_PRODUCERS; ++i) {
        pthread_join(producers[i], NULL);
    }

    for (int i = 0; i < NUM_CONSUMERS; ++i) {
        pthread_join(consumers[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond_buffer_not_full);
    pthread_cond_destroy(&cond_buffer_not_empty);

    return 0;
}

solution.explanation:
הקוד הנתון מכיל שגיאת סנכרון קריטית בשימוש במשתני התנאי, שעלולה להוביל לקיפאון (deadlock) מוחלט של התוכנית.

**זיהוי והסבר הבעיה:**
1.  **שימוש שגוי ב-`pthread_cond_signal` ב-`producer`:** לאחר שהתהליכון היצרן (producer) מוסיף פריט לחוצץ, הוא מאותת למשתנה התנאי `cond_buffer_not_full`. משתנה תנאי זה נועד עבור היצרנים *להמתין* עליו כאשר החוצץ מלא. איתות למשתנה זה מעיר יצרן אחר (אם יש), אך אינו עוזר לצרכנים שממתינים לפריטים חדשים בחוצץ. היצרן צריך לאותת למשתנה התנאי `cond_buffer_not_empty` כדי להודיע לצרכנים שהחוצץ אינו ריק יותר ויש פריטים לצרוך.
2.  **שימוש שגוי ב-`pthread_cond_signal` ב-`consumer`:** באופן דומה, לאחר שהתהליכון הצרכן (consumer) מסיר פריט מהחוצץ, הוא מאותת למשתנה התנאי `cond_buffer_not_empty`. משתנה תנאי זה נועד עבור הצרכנים *להמתין* עליו כאשר החוצץ ריק. איתות למשתנה זה מעיר צרכן אחר (אם יש), אך אינו עוזר ליצרנים שממתינים למקום פנוי בחוצץ. הצרכן צריך לאותת למשתנה התנאי `cond_buffer_not_full` כדי להודיע ליצרנים שהחוצץ אינו מלא יותר ויש מקום פנוי.

**ההשלכות – קיפאון:**
שגיאות אלו מובילות לקיפאון. ברגע שהיצרנים ממלאים את החוצץ, הם כולם ימתינו על `cond_buffer_not_full`. מכיוון שהיצרנים מאותתים רק ל-`cond_buffer_not_full`, אף אחד לא יעיר את הצרכנים שממתינים על `cond_buffer_not_empty`. כתוצאה מכך, הצרכנים לעולם לא יתחילו לצרוך פריטים, והיצרנים לעולם לא יתעוררו מכיוון שהחוצץ יישאר מלא. מצב דומה יקרה אם הצרכנים ירוקנו את החוצץ והם ימתינו על `cond_buffer_not_empty`, כאשר היצרנים ימתינו על `cond_buffer_not_full` ולא יאותתו ל-`cond_buffer_not_full`.

**קוד מתוקן:**
כדי לתקן את הבעיה, יש להחליף את קריאות ה-`pthread_cond_signal` בין התהליכונים:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define BUFFER_SIZE 5
#define NUM_PRODUCERS 2
#define NUM_CONSUMERS 2
#define MAX_ITEMS_PER_THREAD 10

int buffer[BUFFER_SIZE];
int count = 0;
int in = 0;
int out = 0;

pthread_mutex_t mutex;
pthread_cond_t cond_buffer_not_full;  // Signaled when buffer is not full
pthread_cond_t cond_buffer_not_empty; // Signaled when buffer is not empty

void* producer(void* arg) {
    int item;
    for (int i = 0; i < MAX_ITEMS_PER_THREAD; ++i) {
        item = rand() % 100;
        pthread_mutex_lock(&mutex);
        while (count == BUFFER_SIZE) {
            pthread_cond_wait(&cond_buffer_not_full, &mutex);
        }
        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        count++;
        printf("Producer %ld produced: %d, count: %d\n", (long)arg, item, count);
        pthread_cond_signal(&cond_buffer_not_empty); // CORRECTED: Signal consumers
        pthread_mutex_unlock(&mutex);
        usleep(100000);
    }
    return NULL;
}

void* consumer(void* arg) {
    int item;
    for (int i = 0; i < MAX_ITEMS_PER_THREAD; ++i) {
        pthread_mutex_lock(&mutex);
        while (count == 0) {
            pthread_cond_wait(&cond_buffer_not_empty, &mutex);
        }
        item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count--;
        printf("Consumer %ld consumed: %d, count: %d\n", (long)arg, item, count);
        pthread_cond_signal(&cond_buffer_not_full); // CORRECTED: Signal producers
        pthread_mutex_unlock(&mutex);
        usleep(150000);
    }
    return NULL;
}

int main() {
    pthread_t producers[NUM_PRODUCERS];
    pthread_t consumers[NUM_CONSUMERS];

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond_buffer_not_full, NULL);
    pthread_cond_init(&cond_buffer_not_empty, NULL);

    srand(time(NULL));

    for (long i = 0; i < NUM_PRODUCERS; ++i) {
        pthread_create(&producers[i], NULL, producer, (void*)i);
    }

    for (long i = 0; i < NUM_CONSUMERS; ++i) {
        pthread_create(&consumers[i], NULL, consumer, (void*)i);
    }

    for (int i = 0; i < NUM_PRODUCERS; ++i) {
        pthread_join(producers[i], NULL);
    }

    for (int i = 0; i < NUM_CONSUMERS; ++i) {
        pthread_join(consumers[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond_buffer_not_full);
    pthread_cond_destroy(&cond_buffer_not_empty);

    return 0;
}
```

**הסבר על השינויים:**
*   בפונקציה `producer`, השורה `pthread_cond_signal(&cond_buffer_not_full);` הוחלפה ב-`pthread_cond_signal(&cond_buffer_not_empty);`. היצרן, לאחר שהוסיף פריט, רוצה להעיר צרכן פוטנציאלי שממתין לפריטים.
*   בפונקציה `consumer`, השורה `pthread_cond_signal(&cond_buffer_not_empty);` הוחלפה ב-`pthread_cond_signal(&cond_buffer_not_full);`. הצרכן, לאחר שפינה מקום בחוצץ, רוצה להעיר יצרן פוטנציאלי שממתין למקום פנוי.

