class BankAccount {
public:
    int balance;
    std::mutex mtx; // Each account has its own mutex
    int id;         // For identification

    BankAccount(int initial_balance, int account_id) : balance(initial_balance), id(account_id) {}

    // Methods that assume the caller has already locked the account's mutex
    void unsafe_deposit(int amount) {
        balance += amount;
    }

    bool unsafe_withdraw(int amount) {
        if (balance >= amount) {
            balance -= amount;
            return true;
        }
        return false;
    }
};

// Function to transfer money between two accounts
void transfer(BankAccount* from, BankAccount* to, int amount) {
    // Acquire locks for both accounts
    from->mtx.lock(); // Lock 'from' account
    // std::this_thread::sleep_for(std::chrono::milliseconds(1)); // Simulate work/context switch
    to->mtx.lock();   // Lock 'to' account

    if (from->unsafe_withdraw(amount)) {
        to->unsafe_deposit(amount);
        std::cout << "Transfer " << amount << " from " << from->id << " to " << to->id << " successful. "
                  << "Balances: " << from->id << "=" << from->balance << ", " << to->id << "=" << to->balance << std::endl;
    } else {
        std::cout << "Transfer " << amount << " from " << from->id << " to " << to->id << " failed (insufficient funds)." << std::endl;
    }

    to->mtx.unlock();   // Unlock 'to' account
    from->mtx.unlock(); // Unlock 'from' account
}

solution.explanation:
הבעיה המרכזית בקוד הנתון היא פוטנציאל לקיפאון (deadlock). קיפאון יתרחש כאשר שני תהליכונים ינסו לבצע העברות כספים בין אותם שני חשבונות, אך בסדר הפוך. לדוגמה, תהליכון A מנסה להעביר כסף מחשבון 1 לחשבון 2, ותהליכון B מנסה להעביר כסף מחשבון 2 לחשבון 1.

**תרחיש קיפאון (Deadlock Scenario):**
1.  תהליכון A מתחיל לבצע `transfer(&acc1, &acc2, 100)` ונועל את המנעול של חשבון `acc1` (`acc1.mtx.lock()`).
2.  מתרחש מיתוג הקשר (context switch), ותהליכון B מתחיל לבצע `transfer(&acc2, &acc1, 50)`.
3.  תהליכון B נועל את המנעול של חשבון `acc2` (`acc2.mtx.lock()`).
4.  תהליכון B מגיע לשורה `from->mtx.lock()` (שבמקרה זה היא `acc1.mtx.lock()`), ומנסה לנעול את המנעול של חשבון `acc1`. אך המנעול כבר נעול על ידי תהליכון A, ולכן תהליכון B נחסם וממתין.
5.  מתרחש מיתוג הקשר בחזרה לתהליכון A. תהליכון A מגיע לשורה `to->mtx.lock()` (שבמקרה זה היא `acc2.mtx.lock()`), ומנסה לנעול את המנעול של חשבון `acc2`. אך המנעול כבר נעול על ידי תהליכון B, ולכן תהליכון A נחסם וממתין.
כתוצאה מכך, שני התהליכונים חסומים זה לזה (כל אחד ממתין למנעול שהשני מחזיק) ואינם יכולים להמשיך, מה שמוביל לקיפאון.

**פתרון מתוקן:**
כדי למנוע קיפאון, יש להבטיח שכל המנעולים הנדרשים נרכשים בסדר קבוע ועקבי (global ordering), או באמצעות מנגנון שמאפשר רכישה אטומית של מספר מנעולים. ב-C++, הפונקציה `std::lock` נועדה בדיוק למטרה זו. היא מקבלת מספר מנעולים ורוכשת אותם באופן שמונע קיפאון על ידי אלגוריתם חכם (לרוב על ידי ניסיון לרכוש את כולם, וביצוע נסיגה וניסיון חוזר אם לא ניתן לרכוש את כולם בבת אחת).

פתרון מתוקן באמצעות `std::lock` ו-`std::lock_guard` עם `std::adopt_lock`:
`std::lock` רוכש את המנעולים `from->mtx` ו-`to->mtx` באופן בטוח מפני קיפאון. לאחר מכן, `std::lock_guard` משמשים לניהול שחרור המנעולים באופן אוטומטי (RAII - Resource Acquisition Is Initialization) כאשר הם יוצאים מהסקופ של הפונקציה. `std::adopt_lock` מציין ל-`lock_guard` שהמנעול כבר נרכש על ידי `std::lock` ורק צריך לאמץ אותו ולנהל את שחרורו.

יש גם צורך לטפל במקרה קצה שבו מנסים להעביר כסף לחשבון עצמו (כלומר `from == to`), כדי למנוע נעילה כפולה של אותו מנעול או התנהגות בלתי צפויה מ-`std::lock`.

```cpp
void transfer(BankAccount* from, BankAccount* to, int amount) {
    // Handle self-transfer explicitly to avoid locking the same mutex twice
    if (from == to) {
        std::lock_guard<std::mutex> lock(from->mtx);
        if (from->unsafe_withdraw(amount)) {
            to->unsafe_deposit(amount); // 'to' is the same as 'from'
            std::cout << "Transfer " << amount << " from " << from->id << " to itself successful. "
                      << "Balance: " << from->id << "=" << from->balance << std::endl;
        } else {
            std::cout << "Transfer " << amount << " from " << from->id << " to itself failed (insufficient funds)." << std::endl;
        }
        return;
    }

    // Use std::lock to acquire both mutexes without deadlock
    // std::lock ensures that if it fails to acquire all locks, it releases already acquired ones
    std::lock(from->mtx, to->mtx);

    // Use std::lock_guard with std::adopt_lock to manage mutexes automatically
    std::lock_guard<std::mutex> lock1(from->mtx, std::adopt_lock);
    std::lock_guard<std::mutex> lock2(to->mtx, std::adopt_lock);

    if (from->unsafe_withdraw(amount)) {
        to->unsafe_deposit(amount);
        std::cout << "Transfer " << amount << " from " << from->id << " to " << to->id << " successful. "
                  << "Balances: " << from->id << "=" << from->balance << ", " << to->id << "=" << to->balance << std::endl;
    } else {
        std::cout << "Transfer " << amount << " from " << from->id << " to " << to->id << " failed (insufficient funds)." << std::endl;
    }
    // Mutexes are automatically unlocked when lock1 and lock2 go out of scope
}
```

**פתרון חלופי (Global Ordering):**
פתרון נוסף למניעת קיפאון הוא להטיל סדר גלובלי (global ordering) על המשאבים (במקרה זה, חשבונות הבנק). לדוגמה, תמיד לנעול את החשבון בעל ה-ID הקטן יותר תחילה, ולאחר מכן את החשבון בעל ה-ID הגדול יותר. זה מבטיח שכל התהליכונים ינסו לרכוש את המנעולים באותו סדר, ובכך ימנע קיפאון.

```cpp
void transfer_ordered(BankAccount* from, BankAccount* to, int amount) {
    if (from == to) {
        std::lock_guard<std::mutex> lock(from->mtx);
        // ... (same logic as above for self-transfer)
        return;
    }

    // Determine which mutex to lock first based on ID
    // To avoid issues if from->id == to->id (which is handled above), use memory addresses if IDs can be same for different accounts
    // For simplicity, assuming unique IDs for distinct accounts or handling from == to already
    BankAccount* first_account = (from->id < to->id) ? from : to;
    BankAccount* second_account = (from->id < to->id) ? to : from;

    // Lock mutexes in a consistent order
    std::lock_guard<std::mutex> lock1(first_account->mtx);
    std::lock_guard<std::mutex> lock2(second_account->mtx);

    // Now that both are locked, perform the transfer operation on original 'from' and 'to'
    if (from->unsafe_withdraw(amount)) {
        to->unsafe_deposit(amount);
        std::cout << "Transfer " << amount << " from " << from->id << " to " << to->id << " successful. "
                  << "Balances: " << from->id << "=" << from->balance << ", " << to->id << "=" << to->balance << std::endl;
    } else {
        std::cout << "Transfer " << amount << " from " << from->id << " to " << to->id << " failed (insufficient funds)." << std::endl;
    }
}
```

פתרון `std::lock` הוא עדיף בדרך כלל מכיוון שהוא מופשט יותר ופחות נוטה לטעויות מאשר ניהול סדר ידני, במיוחד במערכות מורכבות יותר עם מספר רב של משאבים או יחסי תלות דינמיים.

