    sem_post(&s2);
    return NULL;
}

int main() {
    sem_init(&s1, 0, 1); // סמפור בינארי
    sem_init(&s2, 0, 1); // סמפור בינארי
    pthread_t t1, t2;
    pthread_create(&t1, NULL, thread1_func, NULL);
    pthread_create(&t2, NULL, thread2_func, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    sem_destroy(&s1);
    sem_destroy(&s2);
    return 0;
}

