// שני סמפורים המשמשים כמנעולים
sem_t S1;
sem_t S2;

void *thread_func_A(void *arg) {
    printf("Thread A: Trying to acquire S1...\n");
    sem_wait(&S1);
    printf("Thread A: Acquired S1. Trying to acquire S2...\n");
    usleep(100000); // 100ms
    sem_wait(&S2);
    printf("Thread A: Acquired S2. Critical section A...\n");
    // Critical section work
    usleep(50000); // 50ms
    sem_post(&S2);
    printf("Thread A: Released S2.\n");
    sem_post(&S1);
    printf("Thread A: Released S1. Exiting.\n");
    return NULL;
}

void *thread_func_B(void *arg) {
    printf("Thread B: Trying to acquire S2...\n");
    sem_wait(&S2);
    printf("Thread B: Acquired S2. Trying to acquire S1...\n");
    usleep(100000); // 100ms
    sem_wait(&S1);
    printf("Thread B: Acquired S1. Critical section B...\n");
    // Critical section work
    usleep(50000); // 50ms
    sem_post(&S1);
    printf("Thread B: Released S1.\n");
    sem_post(&S2);
    printf("Thread B: Released S2. Exiting.\n");
    return NULL;
}

int main() {
    sem_init(&S1, 0, 1); // משותף בין תהליכונים של תהליך, ערך אתחול 1
    sem_init(&S2, 0, 1); // משותף בין תהליכונים של תהליך, ערך אתחול 1

    pthread_t tid[2];

    printf("Main: Creating Thread A...\n");
    pthread_create(&tid[0], NULL, thread_func_A, NULL);
    printf("Main: Creating Thread B...\n");
    pthread_create(&tid[1], NULL, thread_func_B, NULL);

    pthread_join(tid[0], NULL);
    pthread_join(tid[1], NULL);

    sem_destroy(&S1);
    sem_destroy(&S2);

    printf("Main: All threads finished. Exiting.\n");
    return 0;
}

solution.explanation:
10.1. כן, קיימת בתוכנית זו אפשרות לקיפאון (deadlock).

**תיאור מצב ריצה לקיפאון:**
1.  **Thread A** מתחיל לרוץ ומבצע `sem_wait(&S1)`. הוא מצליח לרכוש את S1.
2.  הקשר עובר ל-**Thread B**. הוא מתחיל לרוץ ומבצע `sem_wait(&S2)`. הוא מצליח לרכוש את S2.
3.  הקשר חוזר ל-**Thread A**. הוא מנסה לבצע `sem_wait(&S2)`. מכיוון ש-S2 מוחזק על ידי Thread B, Thread A נחסם וממתין לשחרור S2.
4.  הקשר עובר ל-**Thread B**. הוא מנסה לבצע `sem_wait(&S1)`. מכיוון ש-S1 מוחזק על ידי Thread A, Thread B נחסם וממתין לשחרור S1.
בשלב זה, שני התהליכונים חסומים זה לזה וממתינים למשאב שמוחזק על ידי השני, וכך נוצר קיפאון.

**הסבר מדוע ארבעת התנאים לקיפאון מתקיימים:**
*   **הדרה הדדית (Mutual Exclusion):** תנאי זה מתקיים מכיוון ש-S1 ו-S2 הם סמפורים בינאריים (או מנעולים), ורק תהליכון אחד יכול להחזיק כל סמפור נתון בזמן נתון. המשאבים (הסמפורים) אינם ניתנים לשיתוף במקביל.
*   **החזקה והמתנה (Hold and Wait):** תנאי זה מתקיים. Thread A מחזיק ב-S1 וממתין ל-S2. Thread B מחזיק ב-S2 וממתין ל-S1. כל תהליכון מחזיק במשאב אחד לפחות וממתין למשאב נוסף.
*   **אי-דריסה (No Preemption):** תנאי זה מתקיים. לא ניתן לקחת סמפור מתהליכון בכוח. תהליכון חייב לשחרר את הסמפורים באופן יזום באמצעות `sem_post`.
*   **המתנה מעגלית (Circular Wait):** תנאי זה מתקיים. קיים מעגל של תהליכונים הממתינים זה לזה. Thread A ממתין ל-S2 שמוחזק על ידי Thread B, ו-Thread B ממתין ל-S1 שמוחזק על ידי Thread A.

10.2. הפתרון הנפוץ למניעת קיפאון מסוג זה הוא הטלת סדר קבוע על רכישת המשאבים. כל התהליכונים המשתמשים במשאבים המשותפים חייבים לרכוש אותם באותו סדר. במקרה זה, על שני התהליכונים לרכוש תמיד את S1 ולאחר מכן את S2.

**הקוד המתוקן:**
```c
