    printf("Thread A: Acquired s2. Both resources acquired.\n");
    // Use resources
    printf("Thread A: Releasing s2.\n");
    sem_post(&s2);
    printf("Thread A: Releasing s1.\n");
    sem_post(&s1);
    printf("Thread A: Done.\n");
