#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <unistd.h> // For sleep

sem_t sem_A; // Protects Resource A
sem_t sem_B; // Protects Resource B

void* thread_func1(void* arg) {
    printf("Thread 1: Trying to acquire sem_A...\n");
    sem_wait(&sem_A);
    printf("Thread 1: Acquired sem_A. Trying to acquire sem_B...\n");
    // Simulate some work or delay to increase deadlock probability
    sleep(1); 
    sem_wait(&sem_B);
    printf("Thread 1: Acquired sem_B. Critical section...\n");
    // Critical section
    sem_post(&sem_B);
    printf("Thread 1: Released sem_B.\n");
    sem_post(&sem_A);
    printf("Thread 1: Released sem_A.\n");
    return NULL;
}

void* thread_func2(void* arg) {
    printf("Thread 2: Trying to acquire sem_B...\n");
    sem_wait(&sem_B);
    printf("Thread 2: Acquired sem_B. Trying to acquire sem_A...\n");
    // Simulate some work or delay
    sleep(1);
    sem_wait(&sem_A);
    printf("Thread 2: Acquired sem_A. Critical section...\n");
    // Critical section
    sem_post(&sem_A);
    printf("Thread 2: Released sem_A.\n");
    sem_post(&sem_B);
    printf("Thread 2: Released sem_B.\n");
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    sem_init(&sem_A, 0, 1); // Initialize sem_A to 1 (binary semaphore)
    sem_init(&sem_B, 0, 1); // Initialize sem_B to 1 (binary semaphore)

    pthread_create(&tid1, NULL, thread_func1, NULL);
    pthread_create(&tid2, NULL, thread_func2, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    sem_destroy(&sem_A);
    sem_destroy(&sem_B);

    printf("Main: Program finished.\n");
    return 0;
}

solution.explanation:
חלק 1: ניתוח קיפאון

כן, קיים סיכוי לקיפאון (deadlock) בתוכנית זו. קיפאון יכול להתרחש כאשר ארבעת התנאים של קופמן מתקיימים:
1.  **הדרה הדדית (Mutual Exclusion):** לכל משאב (מוגן על ידי סמפור) יש גישה בלעדית. רק תהליכון אחד יכול לתפוס סמפור בינארי (ערכו 1) בכל רגע נתון. תנאי זה מתקיים.
2.  **החזקה והמתנה (Hold and Wait):** תהליכון מחזיק במשאב אחד לפחות (תפס סמפור) וממתין למשאב נוסף שתפוס על ידי תהליכון אחר.
    *   תהליכון 1 תופס את `sem_A` וממתין ל-`sem_B`.
    *   תהליכון 2 תופס את `sem_B` וממתין ל-`sem_A`.
    תנאי זה מתקיים.
3.  **אין דריסה (No Preemption):** משאבים לא ניתנים לדריסה; הם יכולים להשתחרר רק באופן יזום על ידי התהליכון שמחזיק בהם. תנאי זה מתקיים עם סמפורים.
4.  **המתנה מעגלית (Circular Wait):** קיימת שרשרת של תהליכונים, כאשר כל תהליכון בשרשרת ממתין למשאב המוחזק על ידי התהליכון הבא בשרשרת.
    *   תהליכון 1 מחזיק ב-`sem_A` וממתין ל-`sem_B`.
    *   תהליכון 2 מחזיק ב-`sem_B` וממתין ל-`sem_A`.
    נוצרת המתנה מעגלית: T1 ממתין ל-T2, ו-T2 ממתין ל-T1. תנאי זה מתקיים.

**תרחיש קיפאון ספציפי:**
1.  **תהליכון 1** מתחיל וקורא `sem_wait(&sem_A)`. הוא תופס בהצלחה את `sem_A`.
2.  **תהליכון 2** מתחיל וקורא `sem_wait(&sem_B)`. הוא תופס בהצלחה את `sem_B`.
3.  **תהליכון 1** מנסה כעת לקרוא `sem_wait(&sem_B)`. אך `sem_B` תפוס על ידי תהליכון 2, ולכן תהליכון 1 נחסם.
4.  **תהליכון 2** מנסה כעת לקרוא `sem_wait(&sem_A)`. אך `sem_A` תפוס על ידי תהליכון 1, ולכן תהליכון 2 נחסם.

שני התהליכונים חסומים כעת באופן הדדי וממתינים זה לזה לשחרר את המשאבים שהם צריכים. זהו מצב קיפאון.

חלק 2: תיקון למניעת קיפאון

כדי למנוע קיפאון, יש לשבור לפחות אחד מתנאי קופמן. הדרך הנפוצה והיעילה ביותר במקרים כאלה היא למנוע המתנה מעגלית על ידי הטלת סדר כולל (total ordering) על תפיסת המשאבים. כלומר, כל התהליכונים חייבים לתפוס את המשאבים באותו סדר.

**קוד מתוקן:**
```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <unistd.h> // For sleep

sem_t sem_A; // Protects Resource A
sem_t sem_B; // Protects Resource B

void* thread_func1_fixed(void* arg) {
    printf("Thread 1: Trying to acquire sem_A...\n");
    sem_wait(&sem_A);
    printf("Thread 1: Acquired sem_A. Trying to acquire sem_B...\n");
    sleep(1); 
    sem_wait(&sem_B);
    printf("Thread 1: Acquired sem_B. Critical section...\n");
    // Critical section
    sem_post(&sem_B);
    printf("Thread 1: Released sem_B.\n");
    sem_post(&sem_A);
    printf("Thread 1: Released sem_A.\n");
    return NULL;
}

void* thread_func2_fixed(void* arg) {
    printf("Thread 2: Trying to acquire sem_A...\n"); // Changed order
    sem_wait(&sem_A); // Changed order
    printf("Thread 2: Acquired sem_A. Trying to acquire sem_B...\n"); // Changed order
    sleep(1);
    sem_wait(&sem_B);
    printf("Thread 2: Acquired sem_B. Critical section...\n");
    // Critical section
    sem_post(&sem_B);
    printf("Thread 2: Released sem_B.\n");
    sem_post(&sem_A);
    printf("Thread 2: Released sem_A.\n");
    return NULL;
}

int main_fixed() { // main_fixed to distinguish from original main
    pthread_t tid1, tid2;

    sem_init(&sem_A, 0, 1);
    sem_init(&sem_B, 0, 1);

    pthread_create(&tid1, NULL, thread_func1_fixed, NULL);
    pthread_create(&tid2, NULL, thread_func2_fixed, NULL); 

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    sem_destroy(&sem_A);
    sem_destroy(&sem_B);

    printf("Main: Program finished (fixed).\n");
    return 0;
}
```

**הסבר על התיקון:**
התיקון מתבצע על ידי שינוי סדר תפיסת הסמפורים ב-`thread_func2_fixed` כך שתהליכון זה יתפוס גם הוא את `sem_A` לפני `sem_B`, בדומה ל-`thread_func1_fixed`.
על ידי כך, אנו מטילים סדר גלובלי על תפיסת המשאבים: כל תהליכון שזקוק לשני המשאבים יתפוס תמיד את `sem_A` ולאחר מכן את `sem_B`.
מצב של המתנה מעגלית לא יכול להתרחש יותר:
*   אם תהליכון 1 תופס את `sem_A`, ותהליכון 2 ינסה לתפוס את `sem_A`, הוא יחסם עד שתהליכון 1 ישחרר אותו (לאחר שסיים את הקטע הקריטי ושיחרר את `sem_B` ו-`sem_A`).
*   תהליכון 1 לעולם לא ימתין ל-`sem_B` כאשר `sem_B` מוחזק על ידי תהליכון 2, אם תהליכון 2 עצמו ממתין ל-`sem_A` (שמוחזק על ידי תהליכון 1). תהליכון 2 יצטרך לתפוס את `sem_A` קודם, וכך לא יוכל להחזיק ב-`sem_B` ולחסום את תהליכון 1 בעת ובעונה אחת.
התיקון שובר את תנאי "המתנה מעגלית", ובכך מונע קיפאון.

content.code_snippet:
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For sleep

sem_t semA; // Semaphore for Resource A
sem_t semB; // Semaphore for Resource B

void* thread_X(void* arg) {
    printf("Thread X: Attempting to acquire Resource A...\n");
    sem_wait(&semA);
    printf("Thread X: Acquired Resource A. Attempting to acquire Resource B...\n");
    sleep(1); // Simulate work or contention
    sem_wait(&semB);
    printf("Thread X: Acquired Resource B. Working...\n");
    // Critical section
    sleep(2);
    printf("Thread X: Releasing Resource B...\n");
    sem_post(&semB);
    printf("Thread X: Releasing Resource A...\n");
    sem_post(&semA);
    printf("Thread X: Finished.\n");
    return NULL;
}

void* thread_Y(void* arg) {
    printf("Thread Y: Attempting to acquire Resource B...\n");
    sem_wait(&semB);
    printf("Thread Y: Acquired Resource B. Attempting to acquire Resource A...\n");
    sleep(1); // Simulate work or contention
    sem_wait(&semA);
    printf("Thread Y: Acquired Resource A. Working...\n");
    // Critical section
    sleep(2);
    printf("Thread Y: Releasing Resource A...\n");
    sem_post(&semA);
    printf("Thread Y: Releasing Resource B...\n");
    sem_post(&semB);
    printf("Thread Y: Finished.\n");
    return NULL;
}

int main() {
    pthread_t tidX, tidY;

    // Initialize semaphores
    sem_init(&semA, 0, 1); // Binary semaphore, initial value 1
    sem_init(&semB, 0, 1); // Binary semaphore, initial value 1

    printf("Main: Creating Thread X and Thread Y...\n");

    pthread_create(&tidX, NULL, thread_X, NULL);
    pthread_create(&tidY, NULL, thread_Y, NULL);

    pthread_join(tidX, NULL);
    pthread_join(tidY, NULL);

    printf("Main: All threads finished.\n");

    // Destroy semaphores
    sem_destroy(&semA);
    sem_destroy(&semB);

    return 0;
}

solution.explanation:
8.1:
כן, קיימת סכנה לקיפאון בתוכנית הנתונה. קיפאון יתרחש כאשר כל אחד מהתהליכים (Thread X ו-Thread Y) יתפוס משאב אחד וינסה לתפוס את המשאב השני, אך המשאב השני כבר תפוס על ידי התהליך האחר. אף אחד מהתהליכים לא יוכל להמשיך, ושניהם יישארו חסומים לנצח.

תרחיש ספציפי לקיפאון:
1.  Thread X מתחיל ומבצע `sem_wait(&semA)` בהצלחה. כעת, Thread X מחזיק ב-`semA`.
2.  Thread Y מתחיל (או מקבל את המעבד) ומבצע `sem_wait(&semB)` בהצלחה. כעת, Thread Y מחזיק ב-`semB`.
3.  Thread X ממשיך ומנסה לבצע `sem_wait(&semB)`. הוא נחסם מכיוון ש-`semB` תפוס על ידי Thread Y.
4.  Thread Y ממשיך ומנסה לבצע `sem_wait(&semA)`. הוא נחסם מכיוון ש-`semA` תפוס על ידי Thread X.

בשלב זה, שני התהליכים חסומים וכל אחד מהם מחכה למשאב שהשני מחזיק בו, מה שמוביל לקיפאון.

נימוק בהתייחס לתנאים ההכרחיים לקיפאון:
*   **הדרה הדדית (Mutual Exclusion)**: מתקיימת. כל סמפור בינארי מאפשר רק לחוט אחד להחזיק בו זמנית (ערכו 0 או 1).
*   **החזקה והמתנה (Hold and Wait)**: מתקיימת. Thread X מחזיק ב-`semA` וממתין ל-`semB`. Thread Y מחזיק ב-`semB` וממתין ל-`semA`.
*   **אי-נשללות (No Preemption)**: מתקיימת. משאבים (סמפורים) לא ניתנים לשלילה בכוח מחוט שמחזיק בהם; הם משוחררים רק מרצון על ידי החוט המחזיק.
*   **המתנה מעגלית (Circular Wait)**: מתקיימת. Thread X ממתין ל-`semB` שמוחזק על ידי Thread Y, ו-Thread Y ממתין ל-`semA` שמוחזק על ידי Thread X. נוצר מעגל המתנה.

8.2:
הדרך הנפוצה למנוע קיפאון במקרה זה היא על ידי אכיפת סדר היררכי (Ordering) בתפיסת המשאבים. כל התהליכים יתפסו את המשאבים באותו סדר.

קוד מתוקן (Thread Y משנה את סדר תפיסת המשאבים):
```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For sleep

sem_t semA; // Semaphore for Resource A
sem_t semB; // Semaphore for Resource B

void* thread_X_fixed(void* arg) {
    printf("Thread X: Attempting to acquire Resource A...\n");
    sem_wait(&semA);
    printf("Thread X: Acquired Resource A. Attempting to acquire Resource B...\n");
    sleep(1);
    sem_wait(&semB);
    printf("Thread X: Acquired Resource B. Working...\n");
    sleep(2);
    printf("Thread X: Releasing Resource B...\n");
    sem_post(&semB);
    printf("Thread X: Releasing Resource A...\n");
    sem_post(&semA);
    printf("Thread X: Finished.\n");
    return NULL;
}

void* thread_Y_fixed(void* arg) {
    // Thread Y now acquires resources in the same order as Thread X: A then B
    printf("Thread Y: Attempting to acquire Resource A...\n"); // Changed order
    sem_wait(&semA); // Changed order
    printf("Thread Y: Acquired Resource A. Attempting to acquire Resource B...\n"); // Changed order
    sleep(1);
    sem_wait(&semB); // Changed order
    printf("Thread Y: Acquired Resource B. Working...\n"); // Changed order
    sleep(2);
    printf("Thread Y: Releasing Resource B...\n"); // Changed order
    sem_post(&semB); // Changed order
    printf("Thread Y: Releasing Resource A...\n"); // Changed order
    sem_post(&semA); // Changed order
    printf("Thread Y: Finished.\n");
    return NULL;
}

int main() {
    pthread_t tidX, tidY;

    sem_init(&semA, 0, 1);
    sem_init(&semB, 0, 1);

    printf("Main: Creating Thread X and Thread Y (fixed version)...\n");

    pthread_create(&tidX, NULL, thread_X_fixed, NULL);
    pthread_create(&tidY, NULL, thread_Y_fixed, NULL); // Use fixed version

    pthread_join(tidX, NULL);
    pthread_join(tidY, NULL);

    printf("Main: All threads finished.\n");

    sem_destroy(&semA);
    sem_destroy(&semB);

    return 0;
}
```

הסבר מדוע התיקון מונע קיפאון:
על ידי אכיפת סדר עקבי בתפיסת המשאבים (לדוגמה, תמיד לתפוס את `semA` לפני `semB`), אנו מונעים את תנאי ה'המתנה המעגלית'. אם Thread X תופס את `semA` ו-Thread Y מנסה גם הוא לתפוס את `semA`, Thread Y ייחסם עד ש-Thread X ישחרר את `semA`. כאשר Thread X ישחרר את `semA` (לאחר שסיים עם `semB`), Thread Y יוכל לתפוס אותו ולהמשיך. לא ייתכן מצב שבו Thread X מחזיק ב-`semA` וממתין ל-`semB`, בעוד Thread Y מחזיק ב-`semB` וממתין ל-`semA`, מכיוון ששניהם ינסו לתפוס את `semA` קודם. מי שיצליח לתפוס את `semA` ראשון ימשיך לתפוס את `semB` וישחרר את שניהם, ובכך יאפשר לחוט השני להתקדם.

