#include <semaphore.h>
#include <unistd.h> // For sleep

sem_t resource1_sem;
sem_t resource2_sem;

void* thread_func_A(void* arg) {
    printf("Thread A: Trying to acquire Resource 1...\n");
    sem_wait(&resource1_sem);
    printf("Thread A: Acquired Resource 1. Trying to acquire Resource 2...\n");
    sleep(1); // Simulate work or context switch
    sem_wait(&resource2_sem);
    printf("Thread A: Acquired Resource 2. Using resources...\n");
    // Critical section
    sleep(2);
    printf("Thread A: Releasing Resource 2...\n");
    sem_post(&resource2_sem);
    printf("Thread A: Releasing Resource 1...\n");
    sem_post(&resource1_sem);
    printf("Thread A: Finished.\n");
    return NULL;
}

void* thread_func_B(void* arg) {
    printf("Thread B: Trying to acquire Resource 2...\n");
    sem_wait(&resource2_sem);
    printf("Thread B: Acquired Resource 2. Trying to acquire Resource 1...\n");
    sleep(1); // Simulate work or context switch
    sem_wait(&resource1_sem);
    printf("Thread B: Acquired Resource 1. Using resources...\n");
    // Critical section
    sleep(2);
    printf("Thread B: Releasing Resource 1...\n");
    sem_post(&resource1_sem);
    printf("Thread B: Releasing Resource 2...\n");
    sem_post(&resource2_sem);
    printf("Thread B: Finished.\n");
    return NULL;
}

int main() {
    sem_init(&resource1_sem, 0, 1);
    sem_init(&resource2_sem, 0, 1);

    pthread_t tidA, tidB;

    pthread_create(&tidA, NULL, thread_func_A, NULL);
    pthread_create(&tidB, NULL, thread_func_B, NULL);

    pthread_join(tidA, NULL);
    pthread_join(tidB, NULL);

    sem_destroy(&resource1_sem);
    sem_destroy(&resource2_sem);

    printf("Main: All threads finished.\n");
    return 0;
}

solution.explanation:
1.  **כן, קיים סיכון לקיפאון (deadlock) בתוכנית זו.** קיפאון יכול להתרחש כאשר מתקיימים ארבעת התנאים של קיפאון: מניעה הדדית (Mutual Exclusion), החזקה והמתנה (Hold and Wait), אי-דריסה (No Preemption), והמתנה מעגלית (Circular Wait). במקרה זה, המתנה מעגלית היא הגורם המרכזי.

    **רצף אירועים לדוגמה שיוביל לקיפאון:**
    *   **תהליכון A** מתחיל ומבצע `sem_wait(&resource1_sem);` ומשיג את `Resource 1`. (Resource 1 = 0)
    *   מתרחש מיתוג הקשר (context switch).
    *   **תהליכון B** מתחיל ומבצע `sem_wait(&resource2_sem);` ומשיג את `Resource 2`. (Resource 2 = 0)
    *   מתרחש מיתוג הקשר.
    *   **תהליכון A** ממשיך, ולאחר ה-`sleep(1);` הוא מבצע `sem_wait(&resource2_sem);`. `Resource 2` כרגע מוחזק על ידי תהליכון B, ולכן תהליכון A נחסם וממתין לשחרורו.
    *   מתרחש מיתוג הקשר.
    *   **תהליכון B** ממשיך, ולאחר ה-`sleep(1);` הוא מבצע `sem_wait(&resource1_sem);`. `Resource 1` כרגע מוחזק על ידי תהליכון A, ולכן תהליכון B נחסם וממתין לשחרורו.

    בשלב זה, תהליכון A מחזיק ב-Resource 1 וממתין ל-Resource 2, בעוד שתהליכון B מחזיק ב-Resource 2 וממתין ל-Resource 1. נוצרה המתנה מעגלית, ושני התהליכונים חסומים לנצח – קיפאון.

2.  **תיקון הקוד למניעת קיפאון:**
    כדי למנוע קיפאון, יש לשבור את תנאי ההמתנה המעגלית. הדרך הנפוצה והפשוטה ביותר לעשות זאת במקרה זה היא לכפות סדר עקבי של רכישת משאבים על כל התהליכונים. כלומר, כל התהליכונים ינסו לרכוש את המשאבים באותו סדר (לדוגמה, תמיד Resource 1 ואז Resource 2).

    **קוד מתוקן (רק הפונקציות הרלוונטיות):**
    ```c
