#include <pthread.h>
#include <semaphore.h>
#include <unistd.h> // For sleep

extern sem_t resource1_sem;
extern sem_t resource2_sem;

void* thread_func_A(void* arg) {
    printf("Thread A: Trying to acquire Resource 1...\n");
    sem_wait(&resource1_sem);
    printf("Thread A: Acquired Resource 1. Trying to acquire Resource 2...\n");
    sleep(1); // Simulate work or context switch
    sem_wait(&resource2_sem);
    printf("Thread A: Acquired Resource 2. Using resources...\n");
    // Critical section
    sleep(2);
    printf("Thread A: Releasing Resource 2...\n");
    sem_post(&resource2_sem);
    printf("Thread A: Releasing Resource 1...\n");
    sem_post(&resource1_sem);
    printf("Thread A: Finished.\n");
    return NULL;
}

void* thread_func_B(void* arg) {
    printf("Thread B: Trying to acquire Resource 1...\n"); // Changed order: acquire R1 first
    sem_wait(&resource1_sem);
    printf("Thread B: Acquired Resource 1. Trying to acquire Resource 2...\n");
    sleep(1); // Simulate work or context switch
    sem_wait(&resource2_sem);
    printf("Thread B: Acquired Resource 2. Using resources...\n");
    // Critical section
    sleep(2);
    printf("Thread B: Releasing Resource 2...\n");
    sem_post(&resource2_sem);
    printf("Thread B: Releasing Resource 1...\n");
    sem_post(&resource1_sem);
    printf("Thread B: Finished.\n");
    return NULL;
}
    ```

    **הסבר מדוע התיקון מונע קיפאון:**
    על ידי אכיפת סדר רכישת משאבים עקבי (תמיד Resource 1 ואז Resource 2) עבור כל התהליכונים, אנו מבטיחים שלא ייווצר מצב של המתנה מעגלית. אם תהליכון A יחזיק ב-Resource 1 וימתין ל-Resource 2, ותהליכון B יצטרך גם הוא את Resource 1, הוא ימתין עד שתהליכון A ישחרר אותו (לאחר שרכש ושחרר את Resource 2). לעולם לא יקרה מצב שבו תהליכון אחד מחזיק ב-Resource X וממתין ל-Resource Y, בעוד שתהליכון אחר מחזיק ב-Resource Y וממתין ל-Resource X, מכיוון ששניהם ינסו לרכוש את Resource X ראשון. הדבר מונע את תנאי ההמתנה המעגלית ובכך מונע קיפאון.

