#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ROWS 4096 // 4096 שורות
#define COLS 4096 // 4096 עמודות

int main() {
    static int matrix[ROWS][COLS]; // מערך סטטי גדול

    // דפוס גישה 1: סדר שורה-אחרי-שורה (Row-major)
    printf("Accessing in row-major order...\n");
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            matrix[i][j] = i + j; // גישת כתיבה
        }
    }

    // דפוס גישה 2: סדר עמודה-אחרי-עמודה (Column-major)
    printf("Accessing in column-major order...\n");
    for (int j = 0; j < COLS; j++) {
        for (int i = 0; i < ROWS; i++) {
            matrix[i][j] = i * j; // גישת כתיבה
        }
    }

    return 0;
}

content.text:
נתונה מערכת הפעלה המשתמשת בזיכרון וירטואלי עם כתובות וירטואליות בגודל 32 ביט וגודל עמוד (page size) של 4KB. מערכת טבלאות העמודים היא דו-מפלסית (two-level page table), כאשר כל רמת טבלה יכולה להכיל 1024 כניסות. כל כניסת טבלה (PTE - Page Table Entry) היא בגודל 4 בתים.
למערכת יש גם TLB (Translation Lookaside Buffer) עם 8 כניסות, הפועל בשיטת אסוציאטיביות מלאה (fully associative) ומדיניות החלפה LRU (Least Recently Used). ה-TLB מאחסן מיפויים של כתובות וירטואליות לכתובות פיזיות עבור דפי נתונים ועבור דפי טבלאות עמודים (PTEs).

נתונה תוכנית C המבצעת את הקוד הבא:

```c
#define N 1024
int matrix[N][N]; // 4MB total size

void access_matrix_row_major() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            matrix[i][j] = i + j;
        }
    }
}

void access_matrix_col_major() {
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < N; i++) {
            matrix[i][j] = i + j;
        }
    }
}
```

הניחו כי המטריצה `matrix` מתחילה בכתובת וירטואלית מיושרת לעמוד (page-aligned). לפני תחילת כל אחת מהפונקציות (`access_matrix_row_major` ו-`access_matrix_col_major`), ה-TLB והזיכרון הפיזי ריקים לחלוטין (כלומר, אין עמודים טעונים לזיכרון הפיזי ואין כניסות ב-TLB). יש להתעלם מהשפעת הקוד עצמו (instruction pages) על הזיכרון.

יש לחשב עבור כל אחת מהפונקציות:
1.  מספר ה-Page Faults הכולל.
2.  מספר ה-TLB Misses הכולל.

הסבירו את חישוביכם לכל סעיף.

