#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <signal.h>
#include <string.h>

#define PAGE_SIZE 4096

volatile int sigsegv_count = 0;
char *fault_page = NULL;

void sigsegv_handler(int signum, siginfo_t *info, void *context) {
    printf("SIGSEGV handler invoked! Fault address: %p\n", info->si_addr);
    sigsegv_count++;

    // Change page permissions to read-write
    if (mprotect(fault_page, PAGE_SIZE, PROT_READ | PROT_WRITE) == -1) {
        perror("mprotect in handler failed");
        exit(EXIT_FAILURE);
    }
    printf("Page permissions changed to R/W.\n");
    // Returning from the handler will cause the faulting instruction to be re-executed.
}

int main() {
    struct sigaction sa;
    sa.sa_flags = SA_SIGINFO; // Use sa_sigaction for the handler
    sa.sa_sigaction = sigsegv_handler;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGSEGV, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Allocate a page of memory
    fault_page = (char *)mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (fault_page == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    printf("Page allocated at address: %p\n", fault_page);

    // Initialize the page
    *fault_page = 'A';
    printf("Initial write to page successful: %c\n", *fault_page);

    // Set page permissions to read-only
    if (mprotect(fault_page, PAGE_SIZE, PROT_READ) == -1) {
        perror("mprotect to read-only");
        exit(EXIT_FAILURE);
    }
    printf("Page permissions set to PROT_READ.\n");

    printf("Attempting to write to read-only page...\n");
    // This write will cause a SIGSEGV
    *fault_page = 'B'; // This is the faulting instruction

    printf("Write after first fault successful: %c\n", *fault_page);

    printf("Attempting another write to page...\n");
    // This write should succeed without a SIGSEGV
    *(fault_page + 1) = 'C';
    printf("Second write successful. Content: %c%c\n", *fault_page, *(fault_page + 1));

    printf("Total SIGSEGV handler invocations: %d\n", sigsegv_count);

    if (munmap(fault_page, PAGE_SIZE) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }

    return 0;
}

