typedef unsigned long addr_t;

// Simplified Page Table Entry
typedef struct {
    bool present;
    bool writable;
    bool dirty;
    addr_t physical_frame_number; // Stores the base physical address of the frame
} pte_t;

// Global (simulated) page table.
// In a real system, this would be per-process and multi-level.
// For simplicity, assume a direct mapping for a small virtual address space.
#define MAX_VIRTUAL_PAGES 1024 // Covers 4MB virtual space
pte_t page_table[MAX_VIRTUAL_PAGES];

// Global counter for allocating new physical frames
addr_t next_free_physical_frame_base = 0x100000; // Start at 1MB

// Helper to get Virtual Page Number (VPN)
addr_t get_vpn(addr_t va) {
    return va >> PAGE_SHIFT;
}

// Helper to get offset within page
addr_t get_offset(addr_t va) {
    return va & (PAGE_SIZE - 1);
}

// Helper to get PTE for a given VA
pte_t* get_pte(addr_t va) {
    addr_t vpn = get_vpn(va);
    if (vpn >= MAX_VIRTUAL_PAGES) {
        return NULL; // Invalid VA
    }
    return &page_table[vpn];
}

// Function to simulate a page fault handler
// This function is intended to map a virtual page to a physical frame
// and set appropriate permissions and flags.
void handle_page_fault(addr_t va, bool is_write_access) {
    pte_t* pte = get_pte(va);

    if (pte == NULL) {
        fprintf(stderr, "Error: Invalid virtual address %lx during page fault.\n", va);
        exit(1);
    }

    if (!pte->present) {
        // Page is not present, allocate a new frame
        pte->physical_frame_number = next_free_physical_frame_base;
        next_free_physical_frame_base += PAGE_SIZE;

        pte->present = true;
        pte->writable = is_write_access; // <--- LINE A: Potential logical flaw
        pte->dirty = is_write_access;     // <--- LINE B: Potential logical flaw
        printf("Page fault for VA %lx: Mapped to PA %lx. Writable: %d, Dirty: %d\n",
               va, pte->physical_frame_number, pte->writable, pte->dirty);
    } else {
        // Page is present, but perhaps a protection fault (e.g., write to read-only)
        if (is_write_access && !pte->writable) {
            fprintf(stderr, "Protection fault: Write to read-only page at VA %lx.\n", va);
            exit(1);
        }
        // If it's a write access, and page is writable, mark dirty
        if (is_write_access) {
            pte->dirty = true;
        }
        printf("Page already present and accessible for VA %lx. Writable: %d, Dirty: %d\n",
               va, pte->writable, pte->dirty);
    }
}

// Function to translate a virtual address to a physical address
// This function simulates the MMU logic, including page fault handling.
addr_t translate_virtual_to_physical(addr_t va, bool is_write_access) {
    pte_t* pte = get_pte(va);

    if (pte == NULL) {
        fprintf(stderr, "Error: Invalid virtual address %lx.\n", va);
        exit(1);
    }

    // Check for page fault or protection fault
    if (!pte->present || (is_write_access && !pte->writable)) {
        handle_page_fault(va, is_write_access);
        // After handling, the PTE should be updated. Re-fetch it to ensure state.
        pte = get_pte(va);
    }

    // At this point, the page must be present and accessible
    // Update dirty bit if it's a write access
    if (is_write_access) {
        pte->dirty = true;
    }

    return pte->physical_frame_number + get_offset(va);
}

