#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h> // For usleep
#include <time.h>   // For srand

#define NUM_THREADS 4
#define NODES_PER_THREAD 5

typedef struct Node {
    int data;
    struct Node *next;
} Node;

Node *head = NULL;
int global_counter = 0; // Shared counter for node data

pthread_mutex_t list_lock;    // Mutex for list modifications
pthread_mutex_t counter_lock; // Mutex for global_counter
pthread_cond_t add_cond;      // Condition variable for ordered addition (used in Q1.5 solution)

int expected_id_to_add; // Used in Q1.5 solution

// Function to add a node to the beginning of the list
void add_node_to_list(int data) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;

    new_node->next = head;
    head = new_node;
}

void* worker_thread(void* arg) {
    for (int i = 0; i < NODES_PER_THREAD; ++i) {
        int my_id;

        // Step 1: Get a unique ID
        pthread_mutex_lock(&counter_lock);
        my_id = global_counter++;
        pthread_mutex_unlock(&counter_lock);

        // Simulate some processing time before adding to list
        usleep(100 + (rand() % 100)); // Random delay between 100-199 microseconds

        // Step 2: Add node to the list
        pthread_mutex_lock(&list_lock);
        add_node_to_list(my_id);
        pthread_mutex_unlock(&list_lock);
    }
    return NULL;
}

void print_list() {
    Node *current = head;
    printf("List (from head to tail): ");
    while (current != NULL) {
        printf("%d -> ", current->data);
        current = current->next;
    }
    printf("NULL\n");
}

void free_list() {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    pthread_mutex_init(&list_lock, NULL);
    pthread_mutex_init(&counter_lock, NULL);
    // pthread_cond_init(&add_cond, NULL); // Initialized for Q1.5 solution

    srand(time(NULL)); // Seed random for usleep variation

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("All threads finished. Total nodes: %d\n", NUM_THREADS * NODES_PER_THREAD);
    print_list();

    free_list();
    pthread_mutex_destroy(&list_lock);
    pthread_mutex_destroy(&counter_lock);
    // pthread_cond_destroy(&add_cond); // Destroyed for Q1.5 solution

    return 0;
}

solution.explanation:
1.1: המספר הכולל של הצמתים ברשימה יהיה תוצר המכפלה של NUM_THREADS * NODES_PER_THREAD. במקרה זה, 4 * 5 = 20 צמתים. כל חוט מריץ את הלולאה NODES_PER_THREAD פעמים, ובכל פעם הוא מוסיף צומת אחד לרשימה. מכיוון שאין מחיקות או כשלים ביצירת צמתים (הנחת השאלה), כל הצמתים שנוצרו יתווספו לרשימה.

1.2: כן, כל ערכי ה-`data` בצמתים ברשימה מובטחים להיות ייחודיים. הסיבה לכך היא שהמשתנה הגלובלי `global_counter` מוגן על ידי `counter_lock` (מנעול). בכל פעם שחוט רוצה לקבל ID, הוא נועל את המנעול, קורא את הערך הנוכחי של `global_counter`, מקדם אותו, ורק אז משחרר את המנעול. זה מבטיח שכל חוט יקבל ערך ייחודי מהמונה, ושהמונה יתקדם בצורה אטומית, ללא איבוד עדכונים או קריאת ערכים שגויים.

1.3: כן, הרשימה מובטחת להיות נקייה משחיתות. המנעול `list_lock` מגן על כל הגישה והשינויים למבנה הרשימה המקושרת (הצבעה ל-`head` ועדכון מצביעי `next` בתוך `add_node_to_list`). כאשר חוט נועל את `list_lock`, הוא מבטיח ששום חוט אחר לא יוכל לשנות את הרשימה במקביל. זה מונע מצבי מרוץ (race conditions) שעלולים להוביל למצביעים שגויים, איבוד צמתים, או מבנה רשימה לקוי.

1.4: לא, הרשימה אינה מובטחת להיות ממוינת לפי ערכי ה-`data`. למרות שכל מזהה (`my_id`) מובטח להיות ייחודי ומתקבל בסדר עולה (0, 1, 2, ...), ישנו השהיה אקראית (`usleep`) בין השלב שבו חוט מקבל את ה-ID שלו לבין השלב שבו הוא מוסיף את הצומת לרשימה. מכיוון ש-`add_node_to_list` מוסיפה צמתים לראש הרשימה, הסדר הסופי של הצמתים ברשימה תלוי בסדר שבו החוטים השונים מצליחים לנעול את `list_lock` ולהוסיף את הצומת שלהם לאחר ההשהיה. 

תרחיש לדוגמה המוביל לרשימה לא ממוינת (בסדר עולה או יורד):
נניח NUM_THREADS=2, NODES_PER_THREAD=1.
1. חוט A מקבל `my_id = 0`. הוא נכנס ל-`usleep`.
2. חוט B מקבל `my_id = 1`. הוא נכנס ל-`usleep`.
3. חוט B מסיים את ה-`usleep` שלו לפני חוט A. הוא נועל את `list_lock`, קורא ל-`add_node_to_list(1)`.
   הרשימה כעת: `1 -> NULL`.
4. חוט B משחרר את `list_lock` ומסיים.
5. חוט A מסיים את ה-`usleep` שלו. הוא נועל את `list_lock`, קורא ל-`add_node_to_list(0)`.
   הרשימה כעת: `0 -> 1 -> NULL`.
בדוגמה זו, הרשימה ממוינת בסדר עולה. אך תרחיש הפוך אפשרי באותה מידה:
1. חוט A מקבל `my_id = 0`. נכנס ל-`usleep`.
2. חוט B מקבל `my_id = 1`. נכנס ל-`usleep`.
3. חוט A מסיים את ה-`usleep` שלו לפני חוט B. הוא נועל את `list_lock`, קורא ל-`add_node_to_list(0)`.
   הרשימה כעת: `0 -> NULL`.
4. חוט A משחרר את `list_lock` ומסיים.
5. חוט B מסיים את ה-`usleep` שלו. הוא נועל את `list_lock`, קורא ל-`add_node_to_list(1)`.
   הרשימה כעת: `1 -> 0 -> NULL`.
בדוגמה זו, הרשימה אינה ממוינת בסדר עולה וגם לא בסדר יורד לחלוטין. זה מדגים את חוסר הדטרמיניזם בסדר.

1.5: כדי להבטיח שהרשימה תהיה ממוינת בסדר עולה (0 -> 1 -> ... -> N-1 -> NULL) כאשר `add_node_to_list` מוסיפה לראש הרשימה, יש להבטיח שהצומת עם ה-ID הגבוה ביותר יתווסף ראשון לרשימה, אחריו הצומת עם ה-ID השני בגודלו, וכן הלאה, עד שהצומת עם ה-ID הנמוך ביותר (0) יתווסף אחרון. לשם כך נשתמש במשתנה תנאי (condition variable) ובמונה עזר גלובלי שיציין איזה ID צפוי להתווסף לרשימה כעת (בסדר יורד של ה-ID-ים).

**שינויים נדרשים:**
1.  **הוספת משתנים גלובליים:**
    `pthread_cond_t add_cond;`
    `int expected_id_to_add; // יש לאתחל ב-main ל-(NUM_THREADS * NODES_PER_THREAD) - 1`

2.  **אתחול וניקוי ב-`main`:**
    יש להוסיף אתחול ל-`expected_id_to_add` לפני יצירת החוטים:
    `expected_id_to_add = (NUM_THREADS * NODES_PER_THREAD) - 1;`
    יש לאתחל ולנקות את משתנה התנאי:
    `pthread_cond_init(&add_cond, NULL);`
    `pthread_cond_destroy(&add_cond);`

3.  **שינוי הפונקציה `worker_thread`:**
    ```c
    void* worker_thread(void* arg) {
        for (int i = 0; i < NODES_PER_THREAD; ++i) {
            int my_id;

            // Step 1: Get a unique ID (unchanged)
            pthread_mutex_lock(&counter_lock);
            my_id = global_counter++;
            pthread_mutex_unlock(&counter_lock);

            // Simulate some processing time (unchanged)
            usleep(100 + (rand() % 100)); 

            // Step 2: Add node to the list, but only when it's this ID's turn
            pthread_mutex_lock(&list_lock); // Use list_lock to protect expected_id_to_add and add_cond
            while (my_id != expected_id_to_add) {
                // Wait until it's this thread's turn to add its node
                pthread_cond_wait(&add_cond, &list_lock);
            }
            // Now my_id == expected_id_to_add, so it's this thread's turn
            add_node_to_list(my_id);
            expected_id_to_add--; // Decrement to signal the next expected ID (smaller one)
            pthread_cond_broadcast(&add_cond); // Wake up all waiting threads to recheck their IDs
            pthread_mutex_unlock(&list_lock);
        }
        return NULL;
    }
    ```

**הסבר:**
השינוי מבטיח שהצמתים יתווספו לרשימה בסדר יורד של ה-ID-ים שלהם (ה-ID הגדול ביותר ראשון, הקטן ביותר אחרון). מכיוון שפונקציית `add_node_to_list` מוסיפה לראש הרשימה, הוספה של 19, ואז 18, ואז 17, וכו', תוביל לרשימה סופית מהצורה `0 -> 1 -> 2 -> ... -> 19 -> NULL`, שהיא ממוינת בסדר עולה. `expected_id_to_add` ו-`add_cond` משמשים כמנגנון תזמון קפדני בין החוטים, כך שכל חוט ימתין בסבלנות עד שה-ID שלו יהיה הבא בתור להתווסף לרשימה.

