        pthread_mutex_lock(&mutex);
        tasks_completed_in_batch++;
        printf("Worker %ld: Finished task in batch %d. Total completed: %d\n", worker_id, batch, tasks_completed_in_batch);

        if (tasks_completed_in_batch == NUM_WORKERS) {
            printf("Worker %ld: All workers done for batch %d. Signaling manager.\n", worker_id, batch);
            pthread_cond_signal(&all_workers_done_cond);
        }
        pthread_mutex_unlock(&mutex);

        // Wait for manager to signal start of next batch
        pthread_mutex_lock(&mutex);
        while (tasks_completed_in_batch > 0) { // Condition: wait until manager resets tasks_completed_in_batch to 0
            printf("Worker %ld: Waiting for new batch signal (batch %d). Current completed: %d\n", worker_id, batch, tasks_completed_in_batch);
            pthread_cond_wait(&new_batch_ready_cond, &mutex);
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void* manager_thread(void* arg) {
    for (int batch = 0; batch < NUM_BATCHES; ++batch) {
        pthread_mutex_lock(&mutex);
        printf("Manager: Waiting for all workers to finish batch %d...\n", batch);
        while (tasks_completed_in_batch < NUM_WORKERS) {
            pthread_cond_wait(&all_workers_done_cond, &mutex);
        }
        printf("Manager: All workers finished batch %d. Resetting for next batch.\n", batch);
        tasks_completed_in_batch = 0; // Reset for next batch
        pthread_cond_signal(&new_batch_ready_cond); // BUG: Should be broadcast
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
