#include <pthread.h>
#include <stdio.h>
#include <unistd.h> // For usleep

pthread_mutex_t resource1_mutex;
pthread_mutex_t resource2_mutex;
pthread_mutex_t coordinator_mutex; // A mutex to coordinate access to resource pairs

int data1 = 0;
int data2 = 0;

// Function that needs to modify both data1 and data2
void update_both_resources(int thread_id, int type) {
    if (type == 0) { // Standard order: coordinator -> resource1 -> resource2
        pthread_mutex_lock(&coordinator_mutex);
        printf("Thread %d acquired coordinator_mutex (type 0)\n", thread_id);
        usleep(50);

        pthread_mutex_lock(&resource1_mutex);
        printf("Thread %d acquired resource1_mutex (type 0)\n", thread_id);
        usleep(50);

        pthread_mutex_lock(&resource2_mutex);
        printf("Thread %d acquired resource2_mutex (type 0)\n", thread_id);

        data1++;
        data2++;
        printf("Thread %d: data1=%d, data2=%d\n", thread_id, data1, data2);

        pthread_mutex_unlock(&resource2_mutex);
        pthread_mutex_unlock(&resource1_mutex);
        pthread_mutex_unlock(&coordinator_mutex);
    } else { // Reversed order (mistake): resource1 -> coordinator -> resource2
        pthread_mutex_lock(&resource1_mutex);
        printf("Thread %d acquired resource1_mutex (type 1)\n", thread_id);
        usleep(50);

        pthread_mutex_lock(&coordinator_mutex); // This is the problematic part
        printf("Thread %d acquired coordinator_mutex (type 1)\n", thread_id);
        usleep(50);

        pthread_mutex_lock(&resource2_mutex);
        printf("Thread %d acquired resource2_mutex (type 1)\n", thread_id);

        data1--;
        data2--;
        printf("Thread %d: data1=%d, data2=%d\n", thread_id, data1, data2);

        pthread_mutex_unlock(&resource2_mutex);
        pthread_mutex_unlock(&coordinator_mutex);
        pthread_mutex_unlock(&resource1_mutex);
    }
}

void* thread_task_A(void* arg) {
    for (int i = 0; i < 3; ++i) {
        update_both_resources(1, 0); // Type 0: coordinator -> resource1 -> resource2
        usleep(100);
    }
    return NULL;
}

void* thread_task_B(void* arg) {
    for (int i = 0; i < 3; ++i) {
        update_both_resources(2, 1); // Type 1: resource1 -> coordinator -> resource2
        usleep(100);
    }
    return NULL;
}

int main() {
    pthread_t tid_A, tid_B;

    pthread_mutex_init(&resource1_mutex, NULL);
    pthread_mutex_init(&resource2_mutex, NULL);
    pthread_mutex_init(&coordinator_mutex, NULL);

    pthread_create(&tid_A, NULL, thread_task_A, NULL);
    pthread_create(&tid_B, NULL, thread_task_B, NULL);

    pthread_join(tid_A, NULL);
    pthread_join(tid_B, NULL);

    pthread_mutex_destroy(&resource1_mutex);
    pthread_mutex_destroy(&resource2_mutex);
    pthread_mutex_destroy(&coordinator_mutex);

    printf("Final data1: %d, Final data2: %d\n", data1, data2);
    return 0;
}

solution.explanation:
8.1: תרחיש קיפאון אפשרי:
1. חוט A (thread_task_A) מתחיל את הקריאה ל-update_both_resources עם type = 0.
2. חוט A תופס את `coordinator_mutex`.
3. חוט A מדפיס: "Thread 1 acquired coordinator_mutex (type 0)".
4. חוט B (thread_task_B) מתחיל את הקריאה ל-update_both_resources עם type = 1.
5. חוט B תופס את `resource1_mutex`.
6. חוט B מדפיס: "Thread 2 acquired resource1_mutex (type 1)".
7. חוט A מנסה לתפוס את `resource1_mutex`, אך הוא חסום מכיוון שחוט B מחזיק בו.
8. חוט B מנסה לתפוס את `coordinator_mutex`, אך הוא חסום מכיוון שחוט A מחזיק בו.
בשלב זה, חוט A ממתין ל-`resource1_mutex` שמוחזק על ידי חוט B, וחוט B ממתין ל-`coordinator_mutex` שמוחזק על ידי חוט A. נוצר מצב של קיפאון.

8.2: התנאים ההכרחיים לקיפאון המתקיימים בתרחיש:
*   **מניעה הדדית (Mutual Exclusion):** כל המנעולים (mutexes) הם אובייקטים המבטיחים מניעה הדדית; רק חוט אחד יכול להחזיק מנעול נתון בזמן נתון.
*   **החזקה והמתנה (Hold and Wait):** חוט A מחזיק ב-`coordinator_mutex` וממתין ל-`resource1_mutex`. חוט B מחזיק ב-`resource1_mutex` וממתין ל-`coordinator_mutex`.
*   **אי-דריסה (No Preemption):** המנעולים אינם ניתנים לדריסה. חוט לא יכול להכריח חוט אחר לשחרר מנעול שהוא מחזיק.
*   **המתנה מעגלית (Circular Wait):** קיים מעגל המתנה: חוט A ממתין למשאב שמוחזק על ידי חוט B, וחוט B ממתין למשאב שמוחזק על ידי חוט A.

8.3: תיקון פונקציית update_both_resources:
כדי למנוע קיפאון, יש להקפיד על סדר תפיסת מנעולים עקבי עבור כל החוטים המשתמשים במשאבים משותפים. במקרה זה, הסדר הקנוני צריך להיות: `coordinator_mutex` -> `resource1_mutex` -> `resource2_mutex`.

```c
void update_both_resources_fixed(int thread_id, int type) {
    // Always acquire in the same order: coordinator -> resource1 -> resource2
    pthread_mutex_lock(&coordinator_mutex);
    printf("Thread %d acquired coordinator_mutex\n", thread_id);
    usleep(50);

    pthread_mutex_lock(&resource1_mutex);
    printf("Thread %d acquired resource1_mutex\n", thread_id);
    usleep(50);

    pthread_mutex_lock(&resource2_mutex);
    printf("Thread %d acquired resource2_mutex\n", thread_id);

    // Critical section - functionality remains the same
    if (type == 0) {
        data1++;
        data2++;
    } else { // type == 1
        data1--;
        data2--;
    }
    printf("Thread %d: data1=%d, data2=%d\n", thread_id, data1, data2);

    pthread_mutex_unlock(&resource2_mutex);
    pthread_mutex_unlock(&resource1_mutex);
    pthread_mutex_unlock(&coordinator_mutex);
}
```

**הסבר לתיקון:**
התיקון מונע קיפאון על ידי אכיפת סדר עקבי לתפיסת המנעולים עבור כל החוטים. כאשר כל החוטים מנסים לתפוס את המנעולים באותו סדר (לדוגמה: `coordinator_mutex` ואז `resource1_mutex` ואז `resource2_mutex`), לא יכול להיווצר מעגל המתנה. חוטים עשויים לחכות למנעולים, אך לא ייווצר מצב בו חוט A מחכה למנעול שחוט B מחזיק, וחוט B מחכה למנעול שחוט A מחזיק, מאחר שכל חוט ינסה לתפוס את המנעולים באותה היררכיה. הדבר מבטל את תנאי ה"המתנה מעגלית" ובכך מונע קיפאון.

