#include <pthread.h>
#include <stdio.h>
#include <unistd.h> // for usleep

// Global resources and their mutexes
int buffer1 = 10;
int buffer2 = 0;

pthread_mutex_t mutex1; // Protects buffer1
pthread_mutex_t mutex2; // Protects buffer2

// Simulate some work to increase the chance of interleaving
void simulate_work() {
    usleep(10000); // 10 milliseconds
}

// Thread function 1: Transfers data from buffer1 to buffer2
void* transfer_thread_1(void* arg) {
    printf("Thread 1: Attempting to lock mutex1...\n");
    pthread_mutex_lock(&mutex1);
    printf("Thread 1: Locked mutex1. Attempting to lock mutex2...\n");
    simulate_work(); // Simulate work while holding mutex1
    pthread_mutex_lock(&mutex2);
    printf("Thread 1: Locked mutex2. Transferring data from buffer1 to buffer2.\n");

    // Critical section
    buffer2 += buffer1;
    buffer1 = 0;
    printf("Thread 1: Transfer complete. buffer1 = %d, buffer2 = %d\n", buffer1, buffer2);

    pthread_mutex_unlock(&mutex2);
    printf("Thread 1: Unlocked mutex2.\n");
    pthread_mutex_unlock(&mutex1);
    printf("Thread 1: Unlocked mutex1.\n");
    return NULL;
}

// Thread function 2: Transfers data from buffer2 to buffer1
void* transfer_thread_2(void* arg) {
    printf("Thread 2: Attempting to lock mutex2...\n");
    pthread_mutex_lock(&mutex2);
    printf("Thread 2: Locked mutex2. Attempting to lock mutex1...\n");
    simulate_work(); // Simulate work while holding mutex2
    pthread_mutex_lock(&mutex1);
    printf("Thread 2: Locked mutex1. Transferring data from buffer2 to buffer1.\n");

    // Critical section
    buffer1 += buffer2;
    buffer2 = 0;
    printf("Thread 2: Transfer complete. buffer1 = %d, buffer2 = %d\n", buffer1, buffer2);

    pthread_mutex_unlock(&mutex1);
    printf("Thread 2: Unlocked mutex1.\n");
    pthread_mutex_unlock(&mutex2);
    printf("Thread 2: Unlocked mutex2.\n");
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_mutex_init(&mutex1, NULL);
    pthread_mutex_init(&mutex2, NULL);

    printf("Initial state: buffer1 = %d, buffer2 = %d\n", buffer1, buffer2);

    pthread_create(&tid1, NULL, transfer_thread_1, NULL);
    pthread_create(&tid2, NULL, transfer_thread_2, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    pthread_mutex_destroy(&mutex1);
    pthread_mutex_destroy(&mutex2);

    printf("Final state: buffer1 = %d, buffer2 = %d\n", buffer1, buffer2);

    return 0;
}

solution.explanation:
1. הבעיה העיקרית שיכולה להתרחש בתוכנית היא קיפאון (Deadlock). קיפאון מתרחש כאשר שני חוטים או יותר נחסמים באופן אינסופי וממתינים למשאבים שמוחזקים על ידי חוטים אחרים באותה קבוצה. במקרה זה, חוט 1 דורש את mutex1 ואז את mutex2, בעוד שחוט 2 דורש את mutex2 ואז את mutex1. אם כל חוט תופס את המנעול הראשון שלו בו זמנית (חוט 1 תופס את mutex1 וחוט 2 תופס את mutex2), הם יחסמו אחד את השני בניסיון לתפוס את המנעול השני, ולא יוכלו להתקדם.

2. תרחיש ריצה המוביל לקיפאון:
   א. חוט 1 מבצע: `pthread_mutex_lock(&mutex1);` - חוט 1 תופס את mutex1.
   ב. חוט 2 מבצע: `pthread_mutex_lock(&mutex2);` - חוט 2 תופס את mutex2.
   ג. חוט 1 ממשיך לבצע: `simulate_work();` - מבצע עבודה כלשהי תוך כדי שהוא מחזיק ב-mutex1.
   ד. חוט 2 ממשיך לבצע: `simulate_work();` - מבצע עבודה כלשהי תוך כדי שהוא מחזיק ב-mutex2.
   ה. חוט 1 מנסה לבצע: `pthread_mutex_lock(&mutex2);` - חוט 1 נחסם, מכיוון ש-mutex2 מוחזק על ידי חוט 2.
   ו. חוט 2 מנסה לבצע: `pthread_mutex_lock(&mutex1);` - חוט 2 נחסם, מכיוון ש-mutex1 מוחזק על ידי חוט 1.
   בנקודה זו, שני החוטים חסומים באופן הדדי ואינסופי, ממתינים למשאב שהשני מחזיק, ונוצר קיפאון.

3. הפתרון הנפוץ והיעיל ביותר למניעת קיפאון מסוג זה הוא אכיפת סדר נעילה קבוע (Locking Order) עבור כל המשאבים. כל החוטים שדורשים גישה למספר מנעולים חייבים לתפוס אותם באותו סדר מוגדר מראש. במקרה זה, נגדיר שכל החוטים יתפסו תמיד קודם את `mutex1` ולאחר מכן את `mutex2`.

**קוד מתוקן:**
```c
// Thread function 1: Transfers data from buffer1 to buffer2
void* transfer_thread_1(void* arg) {
    // Always lock mutex1 then mutex2
    printf("Thread 1: Attempting to lock mutex1...\n");
    pthread_mutex_lock(&mutex1);
    printf("Thread 1: Locked mutex1. Attempting to lock mutex2...\n");
    simulate_work();
    pthread_mutex_lock(&mutex2);
    printf("Thread 1: Locked mutex2. Transferring data from buffer1 to buffer2.\n");

    buffer2 += buffer1;
    buffer1 = 0;
    printf("Thread 1: Transfer complete. buffer1 = %d, buffer2 = %d\n", buffer1, buffer2);

    pthread_mutex_unlock(&mutex2);
    printf("Thread 1: Unlocked mutex2.\n");
    pthread_mutex_unlock(&mutex1);
    printf("Thread 1: Unlocked mutex1.\n");
    return NULL;
}

// Thread function 2: Transfers data from buffer2 to buffer1
void* transfer_thread_2(void* arg) {
    // Enforce the same locking order: always mutex1 then mutex2
    printf("Thread 2: Attempting to lock mutex1...\n"); // Changed from mutex2
    pthread_mutex_lock(&mutex1); // Changed from mutex2
    printf("Thread 2: Locked mutex1. Attempting to lock mutex2...\n");
    simulate_work();
    pthread_mutex_lock(&mutex2);
    printf("Thread 2: Locked mutex2. Transferring data from buffer2 to buffer1.\n");

    buffer1 += buffer2;
    buffer2 = 0;
    printf("Thread 2: Transfer complete. buffer1 = %d, buffer2 = %d\n", buffer1, buffer2);

    pthread_mutex_unlock(&mutex2);
    printf("Thread 2: Unlocked mutex2.\n");
    pthread_mutex_unlock(&mutex1);
    printf("Thread 2: Unlocked mutex1.\n");
    return NULL;
}
```
**הסבר:**
על ידי אכיפת סדר נעילה עקבי (mutex1 ואז mutex2) עבור שני החוטים, אנו מבטלים את התנאי של "המתנה מעגלית" (Circular Wait), שהוא אחד מארבעת התנאים ההכרחיים לקיפאון. כעת, אם חוט 1 מחזיק ב-mutex1 וממתין ל-mutex2, חוט 2 לא יוכל לתפוס את mutex2 לפני ש-mutex1 ישוחרר (מכיוון שגם הוא צריך לתפוס את mutex1 קודם). במילים אחרות, חוט אחד יתפוס את שני המנעולים ויסיים את עבודתו לפני שהשני יוכל להתחיל לתפוס את שניהם, ובכך נמנע קיפאון.

