typedef struct {
    int id;
    int balance;
    pthread_mutex_t mutex;
} Account;

void transfer(Account *from, Account *to, int amount) {
    // תפיסת מנעול החשבון ממנו מעבירים
    pthread_mutex_lock(&from->mutex);

    // תפיסת מנעול החשבון אליו מעבירים
    // (ייתכן כאן מיתוג הקשר)
    pthread_mutex_lock(&to->mutex);

    // בדיקת יתרה וביצוע ההעברה
    if (from->balance >= amount) {
        from->balance -= amount;
        to->balance += amount;
        printf("Transfer successful: %d from account %d to account %d. New balances: %d (acc %d), %d (acc %d)\n",
               amount, from->id, to->id, from->balance, from->id, to->balance, to->id);
    } else {
        printf("Transfer failed: Insufficient funds in account %d for transfer of %d.\n", from->id, amount);
    }

    // שחרור מנעולים
    pthread_mutex_unlock(&to->mutex);
    pthread_mutex_unlock(&from->mutex);
}

solution.explanation:
### פתרון:

**8.1. הבעיה ותיאור תרחיש קיפאון:**

הבעיה שעלולה להתרחש במימוש הנתון היא **קיפאון (Deadlock)**. קיפאון מתרחש כאשר שני חוטים או יותר חוסמים זה את זה באופן הדדי, כאשר כל חוט ממתין למשאב שמוחזק על ידי חוט אחר, וכל אחד מהם לא יכול להמשיך את ריצתו.

**תרחיש לדוגמה המדגים קיפאון:**

נניח שיש לנו שני חשבונות בנק, `accountA` (עם `id=1`) ו-`accountB` (עם `id=2`), ושני חוטים, `T1` ו-`T2`.

1.  **חוט `T1`** מתחיל לבצע העברה: `transfer(&accountA, &accountB, 100)`. הוא תופס בהצלחה את המנעול של `accountA` (`pthread_mutex_lock(&accountA->mutex)`).
2.  מיד לאחר מכן, מתרחש **מיתוג הקשר (context switch)** לחוט `T2`.
3.  **חוט `T2`** מתחיל לבצע העברה הפוכה: `transfer(&accountB, &accountA, 50)`. הוא תופס בהצלחה את המנעול של `accountB` (`pthread_mutex_lock(&accountB->mutex)`).
4.  חוט `T2` מנסה כעת לתפוס את המנעול של `accountA` (`pthread_mutex_lock(&accountA->mutex)`). מכיוון שמנעול זה מוחזק על ידי `T1`, חוט `T2` **נחסם** בהמתנה.
5.  מתרחש **מיתוג הקשר** בחזרה לחוט `T1`.
6.  חוט `T1` מנסה כעת לתפוס את המנעול של `accountB` (`pthread_mutex_lock(&accountB->mutex)`). מכיוון שמנעול זה מוחזק על ידי `T2`, חוט `T1` **נחסם** בהמתנה.

בשלב זה, `T1` ממתין ל-`accountB->mutex` שמוחזק על ידי `T2`, ו-`T2` ממתין ל-`accountA->mutex` שמוחזק על ידי `T1`. שניהם חסומים ולא יכולים להתקדם, מה שמוביל למצב של קיפאון.

**8.2. פתרון ותיקון הקוד:**

כדי למנוע קיפאון במקרה זה, יש לאכוף **סדר קבוע ומוגדר מראש לתפיסת המנעולים**. דרך נפוצה ויעילה לעשות זאת היא לתפוס את המנעול של האובייקט בעל הכתובת הנמוכה יותר בזיכרון קודם, ולאחר מכן את המנעול של האובייקט בעל הכתובת הגבוהה יותר. זה מבטיח שכל החוטים ינסו לתפוס את המנעולים באותו סדר, ובכך נמנע מעגל המתנה הדדי.

**קוד הפונקציה `transfer` המתוקן:**
```c
typedef struct {
    int id;
    int balance;
    pthread_mutex_t mutex;
} Account;

void transfer(Account *from, Account *to, int amount) {
    // טיפול במקרה של העברה עצמית כדי למנוע נעילה כפולה של אותו מנעול
    if (from == to) {
        if (from->balance >= amount) {
            from->balance -= amount;
            printf("Self-transfer successful: %d from account %d. New balance: %d (acc %d)\n",
                   amount, from->id, from->balance, from->id);
        } else {
            printf("Self-transfer failed: Insufficient funds in account %d for transfer of %d.\n", from->id, amount);
        }
        return;
    }

    pthread_mutex_t *first_mutex, *second_mutex;
    Account *first_acc_ptr, *second_acc_ptr;

    // קביעת סדר תפיסת מנעולים עקבי על בסיס כתובות האובייקטים בזיכרון.
    // תמיד ננעל את המנעול של החשבון בעל הכתובת הנמוכה יותר בזיכרון ראשון.
    if (from < to) { // השוואת כתובות של מצביעים (pointers)
        first_mutex = &from->mutex;
        second_mutex = &to->mutex;
        first_acc_ptr = from;
        second_acc_ptr = to;
    } else { // from > to (מכיוון שהמקרה from == to טופל כבר למעלה)
        first_mutex = &to->mutex;
        second_mutex = &from->mutex;
        first_acc_ptr = to;
        second_acc_ptr = from;
    }

    // תפיסת המנעול הראשון (לפי סדר הכתובות)
    printf("Trying to lock account %d (first, address %p)\n", first_acc_ptr->id, (void*)first_acc_ptr);
    pthread_mutex_lock(first_mutex);
    printf("Locked account %d (first)\n", first_acc_ptr->id);

    // תפיסת המנעול השני (לפי סדר הכתובות)
    printf("Trying to lock account %d (second, address %p)\n", second_acc_ptr->id, (void*)second_acc_ptr);
    pthread_mutex_lock(second_mutex);
    printf("Locked account %d (second)\n", second_acc_ptr->id);

    // לאחר שתפסנו את שני המנעולים בסדר עקבי, אנו יכולים לבצע את הלוגיקה בבטחה.
    // הלוגיקה הפנימית של ההעברה נשארת זהה, תוך שימוש במצביעים המקוריים from ו-to.
    if (from->balance >= amount) {
        from->balance -= amount;
        to->balance += amount;
        printf("Transfer successful: %d from account %d to account %d. New balances: %d (acc %d), %d (acc %d)\n",
               amount, from->id, to->id, from->balance, from->id, to->balance, to->id);
    } else {
        printf("Transfer failed: Insufficient funds in account %d for transfer of %d.\n", from->id, amount);
    }

    // שחרור מנעולים בסדר הפוך מסדר התפיסה (חשוב למנוע מצבי מירוץ)
    printf("Unlocking account %d (second)\n", second_acc_ptr->id);
    pthread_mutex_unlock(second_mutex);
    printf("Unlocking account %d (first)\n", first_acc_ptr->id);
    pthread_mutex_unlock(first_mutex);
}
```

**נימוק לתיקון:**

על ידי השוואת כתובות האובייקטים `from` ו-`to` (או לחלופין, כתובות המנעולים שלהם), אנו מבטיחים שכל החוטים, ללא קשר לסדר שבו הם קיבלו את הפרמטרים `from` ו-`to` בקריאה המקורית לפונקציה, ינסו לתפוס את המנעולים של שני החשבונות באותו סדר גלובלי (לדוגמה, תמיד קודם את המנעול של החשבון בעל הכתובת הנמוכה יותר בזיכרון, ואז את המנעול של החשבון בעל הכתובת הגבוהה יותר). זה שובר את תנאי ה'המתנה מעגלית' (Circular Wait) מתוך ארבעת התנאים ההכרחיים לקיפאון (תנאי קופמן), ובכך מונע את הקיפאון. במקרה ש-`from` ו-`to` מצביעים על אותו חשבון, אין צורך בנעילת מנעולים כלל, וזהו מקרה קצה שיש לטפל בו בנפרד כדי למנוע ניסיון נעילה כפולה של אותו מנעול או נעילה עצמית.

