#include <unistd.h> // For sleep

pthread_mutex_t mutexA;
pthread_mutex_t mutexB;

void* thread1_func(void* arg) {
    printf("Thread 1: Trying to acquire mutexA...\n");
    pthread_mutex_lock(&mutexA);
    printf("Thread 1: Acquired mutexA, trying to acquire mutexB...\n");
    sleep(1); // Simulate work or delay
    pthread_mutex_lock(&mutexB);
    printf("Thread 1: Acquired mutexA and mutexB. Doing critical work.\n");
    // Critical section
    pthread_mutex_unlock(&mutexB);
    pthread_mutex_unlock(&mutexA);
    printf("Thread 1: Released mutexA and mutexB.\n");
    return NULL;
}

void* thread2_func(void* arg) {
    printf("Thread 2: Trying to acquire mutexB...\n");
    pthread_mutex_lock(&mutexB);
    printf("Thread 2: Acquired mutexB, trying to acquire mutexA...\n");
    sleep(1); // Simulate work or delay
    pthread_mutex_lock(&mutexA);
    printf("Thread 2: Acquired mutexB and mutexA. Doing critical work.\n");
    // Critical section
    pthread_mutex_unlock(&mutexA);
    pthread_mutex_unlock(&mutexB);
    printf("Thread 2: Released mutexB and mutexA.\n");
    return NULL;
}

int main() {
    pthread_t tid1, tid2;

    pthread_mutex_init(&mutexA, NULL);
    pthread_mutex_init(&mutexB, NULL);

    pthread_create(&tid1, NULL, thread1_func, NULL);
    pthread_create(&tid2, NULL, thread2_func, NULL);

    pthread_join(tid1, NULL);
    pthread_join(tid2, NULL);

    pthread_mutex_destroy(&mutexA);
    pthread_mutex_destroy(&mutexB);

    return 0;
}

