pthread_mutex_t mutex_2 = PTHREAD_MUTEX_INITIALIZER;

void* thread_A_func(void* arg) {
    printf("Thread A: Attempting to acquire mutex_1...\n");
    pthread_mutex_lock(&mutex_1);
    printf("Thread A: Acquired mutex_1. Attempting to acquire mutex_2...\n");
    sleep(1); // Simulate work
    pthread_mutex_lock(&mutex_2);
    printf("Thread A: Acquired mutex_2. Critical section A...\n");
    // Critical section A
    pthread_mutex_unlock(&mutex_2);
    printf("Thread A: Released mutex_2.\n");
    pthread_mutex_unlock(&mutex_1);
    printf("Thread A: Released mutex_1. Exiting.\n");
    return NULL;
}

void* thread_B_func(void* arg) {
    printf("Thread B: Attempting to acquire mutex_2...\n");
    pthread_mutex_lock(&mutex_2);
    printf("Thread B: Acquired mutex_2. Attempting to acquire mutex_1...\n");
    sleep(1); // Simulate work
    pthread_mutex_lock(&mutex_1);
    printf("Thread B: Acquired mutex_1. Critical section B...\n");
    // Critical section B
    pthread_mutex_unlock(&mutex_1);
    printf("Thread B: Released mutex_1.\n");
    pthread_mutex_unlock(&mutex_2);
    printf("Thread B: Released mutex_2. Exiting.\n");
    return NULL;
}

int main() {
    pthread_t tid_A, tid_B;

    pthread_create(&tid_A, NULL, thread_A_func, NULL);
    pthread_create(&tid_B, NULL, thread_B_func, NULL);

    pthread_join(tid_A, NULL);
    pthread_join(tid_B, NULL);

    pthread_mutex_destroy(&mutex_1);
    pthread_mutex_destroy(&mutex_2);

