    if (pid < 0) {
        perror("fork failed");
        exit(1);
    } else if (pid == 0) { // Child process
        signal(SIGUSR1, handle_sigusr1); // Set up signal handler
        printf("Child %d: Going to sleep for 10 seconds...\n", getpid());
        unsigned int remaining = sleep(10);
        printf("Child %d: sleep() returned %u\n", getpid(), remaining);
        if (remaining > 0) {
            printf("Child %d: Sleep was interrupted.\n", getpid());
        }
        exit(0);
    } else { // Parent process
        printf("Parent %d: Child PID is %d\n", getpid(), pid);
        sleep(5); // Wait 5 seconds
        printf("Parent %d: Sending SIGUSR1 to child %d\n", getpid(), pid);
        kill(pid, SIGUSR1);
        wait(NULL); // Wait for child to terminate
        printf("Parent %d: Child terminated.\n", getpid());
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>

volatile sig_atomic_t signal_handled = 0;

void user_signal_handler(int signum) {
    if (signum == SIGUSR1) {
        printf("Parent: SIGUSR1 handler invoked.\n");
        signal_handled = 1;
    }
}

int main() {
    pid_t pid;

    struct sigaction sa;
    sa.sa_handler = user_signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0; // No SA_RESTART for sleep() interruption

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    printf("Parent: PID is %d\n", getpid());

    pid = fork();

    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) { // Child process
        printf("Child: PID is %d. Sending SIGUSR1 to parent in 1 second.\n", getpid());
        sleep(1); 
        kill(getppid(), SIGUSR1);
        printf("Child: SIGUSR1 sent. Exiting.\n");
        exit(EXIT_SUCCESS);
    } else { // Parent process
        printf("Parent: Forked child %d. Going to sleep for 5 seconds.\n", pid);
        unsigned int remaining_sleep = sleep(5); // sleep() can be interrupted by signals

        if (remaining_sleep > 0) {
            printf("Parent: sleep() was interrupted after %u seconds.\n", 5 - remaining_sleep);
        } else {
            printf("Parent: sleep() completed its full duration.\n");
        }

        if (signal_handled) {
            printf("Parent: SIGUSR1 was handled.\n");
        } else {
            printf("Parent: SIGUSR1 was NOT handled.\n");
        }

        int status;
        waitpid(pid, &status, 0); // Clean up child process
        printf("Parent: Child %d reaped. Parent exiting.\n", pid);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <signal.h>
#include <errno.h>
#include <time.h> // For srand/rand
#include <sys/wait.h> // For wait/waitpid

#define NUM_CHILDREN 5
#define SHM_KEY 1234
#define SEM_KEY 5678

// Union for semctl (required by some systems)
union semun {
    int val;
    struct semid_ds *buf;
    unsigned short *array;
    struct seminfo *__buf;
};

struct SharedData {
    int results[NUM_CHILDREN];
    int completed_children_count;
};

// Global variables for signal handlers and IPC IDs
int shm_id = -1;
int sem_id = -1;
struct SharedData *shared_data = NULL;
pid_t child_pids[NUM_CHILDREN];
volatile sig_atomic_t parent_should_exit = 0;
volatile sig_atomic_t child_should_exit = 0;

// Semaphore operations wrapper
void sem_op(int semid, int sem_num, int op) {
    struct sembuf sb = {sem_num, op, 0};
    while (semop(semid, &sb, 1) == -1) {
        if (errno == EINTR) {
            // Interrupted by signal, recheck exit flag if child
            if (getpid() != getppid() && child_should_exit) {
                fprintf(stderr, "Child %d: semop interrupted, exiting due to SIGUSR1.\n", getpid());
                exit(EXIT_FAILURE); // Exit immediately if told to
            }
            continue; // Retry semop if EINTR and not exiting
        } else {
            perror("semop failed");
            exit(EXIT_FAILURE);
        }
    }
}

// Cleanup function for parent process
void cleanup_parent() {
    printf("Parent: Cleaning up IPC resources.\n");
    if (shared_data != (void*)-1 && shared_data != NULL) {
        if (shmdt(shared_data) == -1) {
            perror("parent shmdt failed during cleanup");
        }
        shared_data = (void*)-1;
    }
    if (shm_id != -1 && shmctl(shm_id, IPC_RMID, NULL) == -1) {
        perror("shmctl IPC_RMID failed");
    }
    shm_id = -1;
    if (sem_id != -1 && semctl(sem_id, 0, IPC_RMID) == -1) { // 0 is sem_num, ignored for IPC_RMID
        perror("semctl IPC_RMID failed");
    }
    sem_id = -1;
    printf("Parent: Cleanup complete.\n");
}

// Signal handler for parent (SIGINT)
void parent_sigint_handler(int signum) {
    printf("Parent (PID: %d): Received SIGINT. Initiating graceful shutdown...\n", getpid());
    parent_should_exit = 1;
    for (int i = 0; i < NUM_CHILDREN; ++i) {
        if (child_pids[i] > 0) {
            printf("Parent: Sending SIGUSR1 to child %d (PID: %d).\n", i, child_pids[i]);
            kill(child_pids[i], SIGUSR1); // Tell children to exit
        }
    }
}

// Signal handler for child (SIGUSR1)
void child_sigusr1_handler(int signum) {
    printf("Child (PID: %d): Received SIGUSR1. Setting exit flag.\n", getpid());
    child_should_exit = 1;
}

void child_process(int child_idx) {
    // Attach to shared memory
    shared_data = (struct SharedData *)shmat(shm_id, NULL, 0);
    if (shared_data == (void *)-1) {
        perror("child shmat failed");
        exit(EXIT_FAILURE);
    }

    // Setup SIGUSR1 handler
    struct sigaction sa_child;
    sa_child.sa_handler = child_sigusr1_handler;
    sigemptyset(&sa_child.sa_mask);
    sa_child.sa_flags = 0; // No SA_RESTART to ensure semop can be interrupted
    if (sigaction(SIGUSR1, &sa_child, NULL) == -1) {
        perror("child sigaction SIGUSR1 failed");
        exit(EXIT_FAILURE);
    }

    srand(getpid() * time(NULL)); // Seed random number generator

    printf("Child %d (PID: %d) started.\n", child_idx, getpid());

    // Simulate work
    sleep(rand() % 3 + 1); // Simulate some work before writing

    if (child_should_exit) {
        printf("Child %d (PID: %d): Exiting before writing due to SIGUSR1.\n", child_idx, getpid());
        if (shmdt(shared_data) == -1) { perror("child shmdt failed on early exit"); }
        exit(EXIT_SUCCESS);
    }

    // Acquire semaphore for critical section (incrementing count, writing result)
    sem_op(sem_id, 0, -1); // Decrement semaphore 0 (mutex)

    if (child_should_exit) { // Check again after acquiring sem, in case signal arrived during wait
        printf("Child %d (PID: %d): Exiting after acquiring sem due to SIGUSR1.\n", child_idx, getpid());
        sem_op(sem_id, 0, 1); // Release semaphore before exiting
        if (shmdt(shared_data) == -1) { perror("child shmdt failed on early exit after semop"); }
        exit(EXIT_SUCCESS);
    }

    // Write result to shared memory
    int random_num = rand() % 100 + 1;
    shared_data->results[child_idx] = random_num;
    shared_data->completed_children_count++;
    printf("Child %d (PID: %d) wrote %d. Completed: %d/%d\n",
           child_idx, getpid(), random_num, shared_data->completed_children_count, NUM_CHILDREN);

    // Release semaphore
    sem_op(sem_id, 0, 1); // Increment semaphore 0 (mutex)

    // Detach from shared memory
    if (shmdt(shared_data) == -1) {
        perror("child shmdt failed");
    }
    printf("Child %d (PID: %d) finished and exiting.\n", child_idx, getpid());
    exit(EXIT_SUCCESS);
}

int main() {
    // Create shared memory
    shm_id = shmget(SHM_KEY, sizeof(struct SharedData), IPC_CREAT | 0666);
    if (shm_id == -1) {
        perror("shmget failed");
        exit(EXIT_FAILURE);
    }

    // Attach to shared memory
    shared_data = (struct SharedData *)shmat(shm_id, NULL, 0);
    if (shared_data == (void *)-1) {
        perror("parent shmat failed");
        cleanup_parent();
        exit(EXIT_FAILURE);
    }
    // Initialize shared data
    shared_data->completed_children_count = 0;
    for (int i = 0; i < NUM_CHILDREN; ++i) {
        shared_data->results[i] = 0; // Initialize results
    }

    // Create semaphores (1 semaphore for mutex on completed_children_count)
    sem_id = semget(SEM_KEY, 1, IPC_CREAT | 0666);
    if (sem_id == -1) {
        perror("semget failed");
        cleanup_parent();
        exit(EXIT_FAILURE);
    }

    // Initialize semaphore 0 (mutex) to 1
    union semun arg;
    arg.val = 1;
    if (semctl(sem_id, 0, SETVAL, arg) == -1) {
        perror("semctl SETVAL failed");
        cleanup_parent();
        exit(EXIT_FAILURE);
    }

    // Setup SIGINT handler for parent
    struct sigaction sa_parent;
    sa_parent.sa_handler = parent_sigint_handler;
    sigemptyset(&sa_parent.sa_mask);
    sa_parent.sa_flags = 0; // No SA_RESTART to ensure waitpid can be interrupted if needed
    if (sigaction(SIGINT, &sa_parent, NULL) == -1) {
        perror("parent sigaction SIGINT failed");
        cleanup_parent();
        exit(EXIT_FAILURE);
    }

    printf("Parent (PID: %d) started. Forking %d children...\n", getpid(), NUM_CHILDREN);

    for (int i = 0; i < NUM_CHILDREN; ++i) {
        pid_t pid = fork();
        if (pid == -1) {
            perror("fork failed");
            // Attempt to clean up already forked children and IPC
            for (int j = 0; j < i; ++j) {
                if (child_pids[j] > 0) {
                    kill(child_pids[j], SIGUSR1); // Tell children to exit
                }
            }
            cleanup_parent();
            exit(EXIT_FAILURE);
        } else if (pid == 0) {
            // Child process
            child_process(i);
            // Should not reach here, child_process exits directly
            exit(EXIT_FAILURE); 
        } else {
            // Parent process
            child_pids[i] = pid;
        }
    }

    printf("Parent: All children forked. Waiting for them to complete...\n");

    // Parent waits for all children to complete their work or for SIGINT
    int children_exited_count = 0;
    while (children_exited_count < NUM_CHILDREN) {
        if (parent_should_exit) {
            printf("Parent: SIGINT received, breaking wait loop.\n");
            break;
        }

        // Parent checks completed_children_count in shared memory
        // Must protect access to shared_data->completed_children_count
        sem_op(sem_id, 0, -1); // Acquire mutex
        int current_completed = shared_data->completed_children_count;
        sem_op(sem_id, 0, 1); // Release mutex

        if (current_completed == NUM_CHILDREN) {
            printf("Parent: All children reported completion via shared memory.\n");
            break;
        }

        // Wait for any child to exit, or for a signal
        // Using waitpid with WNOHANG and a short sleep to avoid busy-waiting
        pid_t terminated_pid;
        int status;
        while ((terminated_pid = waitpid(-1, &status, WNOHANG)) > 0) {
            children_exited_count++;
            printf("Parent: Child %d exited (status: %d). Total exited: %d\n", terminated_pid, status, children_exited_count);
        }
        sleep(1); // Small delay to avoid busy-waiting
    }

    // If SIGINT arrived, ensure all children are terminated before cleanup
    if (parent_should_exit) {
        int remaining_children = NUM_CHILDREN - children_exited_count;
        if (remaining_children > 0) {
            printf("Parent: Waiting for %d remaining children to terminate after SIGINT...\n", remaining_children);
            for (int i = 0; i < NUM_CHILDREN; ++i) {
                if (child_pids[i] > 0) {
                    int status;
                    // Use waitpid without WNOHANG to block until child exits
                    if (waitpid(child_pids[i], &status, 0) == -1 && errno != ECHILD) {
                        perror("waitpid during SIGINT cleanup failed");
                    } else {
                        printf("Parent: Child %d confirmed terminated.\n", child_pids[i]);
                    }
                }
            }
        }
    } else {
        // Normal completion: wait for any children that might still be running (e.g., if they didn't finish fast enough)
        printf("Parent: All children completed their work. Waiting for all to terminate.\n");
        int status;
        while (wait(&status) > 0); // Wait for all children to terminate
    }

    if (!parent_should_exit) {
        // Calculate sum only if not interrupted by SIGINT
        printf("Parent: All children completed. Calculating sum...\n");
        int total_sum = 0;
        for (int i = 0; i < NUM_CHILDREN; ++i) {
            total_sum += shared_data->results[i];
        }
        printf("Parent: Total sum of results from children: %d\n", total_sum);
    } else {
        printf("Parent: Sum calculation skipped due to SIGINT.\n");
    }

    // Clean up IPC resources
    cleanup_parent();

    return 0;
}

solution.explanation:
להלן פירוט הרכיבים הנדרשים לפתרון והסבר מפורט לטיפול באותות וקריאות מערכת.

**מבנה הזיכרון המשותף (Shared Memory Structure):**
נצטרך להגדיר מבנה שיכלול את החיץ המעגלי, מצביעים (head, tail), מוני גישות עבור היצרן והצרכן, וכן את שמות הסמפורים (כדי שיהיה קל לנקות אותם).

```c
#define BUFFER_SIZE 10
#define SHM_NAME "/my_shm"
#define SEM_FULL_NAME "/sem_full"
#define SEM_EMPTY_NAME "/sem_empty"
#define SEM_MUTEX_NAME "/sem_mutex"

typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int tail;
    volatile int producer_counter;
    volatile int consumer_counter;
    pid_t producer_pid; // To send signals
    pid_t consumer_pid; // To send signals
    int producer_active; // Flag to indicate if producer is still alive
    int consumer_active; // Flag to indicate if consumer is still alive
} shared_data_t;

shared_data_t *shared_mem_ptr = NULL;
sem_t *sem_full = NULL;
sem_t *sem_empty = NULL;
sem_t *sem_mutex = NULL;
```

**פונקציית ניקוי משאבים (Cleanup Function):**
יש ליצור פונקציה שתטפל בניקוי הזיכרון המשותף והסמפורים. פונקציה זו תקרא באמצעות `atexit` או מתוך ה-signal handlers עבור `SIGINT` ו-`SIGTERM`.
חשוב שהניקוי יבוצע רק פעם אחת, רצוי על ידי תהליך האב (המנטר) או התהליך האחרון שיוצא.

```c
void cleanup() {
    if (shared_mem_ptr) {
        if (getpid() == shared_mem_ptr->producer_pid) {
            shared_mem_ptr->producer_active = 0;
        } else if (getpid() == shared_mem_ptr->consumer_pid) {
            shared_mem_ptr->consumer_active = 0;
        }

        // Only the last active process (or monitor if both children died) performs unlink
        if (shared_mem_ptr->producer_active == 0 && shared_mem_ptr->consumer_active == 0) {
            printf("[%d] All children inactive, performing final cleanup.\n", getpid());
            if (sem_full) sem_unlink(SEM_FULL_NAME);
            if (sem_empty) sem_unlink(SEM_EMPTY_NAME);
            if (sem_mutex) sem_unlink(SEM_MUTEX_NAME);
            shm_unlink(SHM_NAME);
        }
        munmap(shared_mem_ptr, sizeof(shared_data_t));
    }
    if (sem_full) sem_close(sem_full);
    if (sem_empty) sem_close(sem_empty);
    if (sem_mutex) sem_close(sem_mutex);
    printf("[%d] Resources cleaned up.\n", getpid());
}
```

**טיפול באותות `SIGINT` ו-`SIGTERM`:**
כל תהליך יגדיר handler עבור אותות אלו, שיקרא לפונקציית הניקוי ויסיים את פעולתו.

```c
void term_handler(int signum) {
    printf("[%d] Received signal %d. Exiting.\n", getpid(), signum);
    cleanup();
    exit(0);
}

// In main function of each process:
struct sigaction sa_term;
memset(&sa_term, 0, sizeof(sa_term));
sa_term.sa_handler = term_handler;
sigaction(SIGINT, &sa_term, NULL);
sigaction(SIGTERM, &sa_term, NULL);
atexit(cleanup); // Ensure cleanup on normal exit as well
```

**טיפול באות `SIGUSR1` (ב-Producer ו-Consumer):**
ה-handler פשוט ידפיס הודעה. החלק הקריטי הוא איך התהליך ממשיך לפעול אם הוא נקטע בזמן `sem_wait`.

```c
void usr1_handler(int signum) {
    printf("[%d] SIGUSR1 received! Attempting to resume operation...\n", getpid());
    // No complex logic here, rely on main loop to retry interrupted system calls.
}

// In main function of Producer/Consumer:
struct sigaction sa_usr1;
memset(&sa_usr1, 0, sizeof(sa_usr1));
sa_usr1.sa_handler = usr1_handler;
// sa_usr1.sa_flags = SA_RESTART; // Could be used, but not guaranteed for sem_wait
sigaction(SIGUSR1, &sa_usr1, NULL);
```

**הסבר על השפעת `SIGUSR1` על `sem_wait` וטיפול ב-`EINTR`:**
כאשר אות כמו `SIGUSR1` נקלט, הוא יכול לקטוע קריאות מערכת איטיות כמו `sem_wait`. במקרה כזה, `sem_wait` יחזיר -1 ומשתנה הכללי `errno` יוגדר ל-`EINTR` (Interrupted system call). כדי להבטיח שהתהליך ימשיך את פעולתו כרגיל לאחר הטיפול באות, יש שתי גישות עיקריות:

1.  **שימוש ב-`SA_RESTART`**: בעת הגדרת ה-`sigaction` לאות, ניתן להגדיר את הדגל `SA_RESTART` במבנה `sa_flags`. דגל זה גורם למערכת לנסות להפעיל מחדש באופן אוטומטי חלק מקריאות המערכת שנקטעו. עם זאת, לא כל קריאות המערכת ניתנות להפעלה מחדש אוטומטית (לדוגמה, `read` ו-`write` לרוב כן, אך `sem_wait` אינה מובטחת להיכלל בהן בכל מערכות ה-UNIX/Linux). הסתמכות על `SA_RESTART` עבור `sem_wait` אינה פורטבילית או אמינה מספיק.

2.  **לולאת ניסיון חוזר (Manual Retry Loop)**: הגישה הבטוחה והפורטבילית יותר היא לבדוק את ערך ה-`errno` לאחר ש-`sem_wait` נכשל. אם `errno` שווה ל-`EINTR`, יש לנסות שוב את הקריאה ל-`sem_wait` בתוך לולאה. לדוגמה:
    ```c
    int ret;
    do {
        ret = sem_wait(sem_empty);
    } while (ret == -1 && errno == EINTR);
    if (ret == -1) {
        perror("sem_wait failed (not EINTR)");
        exit(1);
    }
    // Continue with critical section
    ```
    במקרה זה, ה-`SIGUSR1` handler פשוט יבצע את פעולתו (הדפסה) ויחזיר שליטה, והלולאה הראשית תנסה שוב את `sem_wait`. זוהי הדרך המומלצת לטפל בקטיעות על ידי אותות בקריאות חסימה.

**לוגיקת המנטר (Monitor Logic):**
המנטר (תהליך האב) יצור את היצרן והצרכן. הוא ישמור את ה-PID שלהם. בלולאה, הוא ימתין 5 שניות, ואז יבדוק את מוני הגישות בזיכרון המשותף. אם מונה כלשהו לא השתנה, הוא ישלח `SIGUSR1` לתהליך המתאים. המנטר גם ימתין לסיום הילדים (`waitpid`).

```c
// Monitor process (parent)
pid_t producer_pid, consumer_pid;
// ... fork() calls to create producer and consumer

shared_mem_ptr->producer_pid = producer_pid;
shared_mem_ptr->consumer_pid = consumer_pid;
shared_mem_ptr->producer_active = 1;
shared_mem_ptr->consumer_active = 1;

int prev_prod_count = 0;
int prev_cons_count = 0;

while (shared_mem_ptr->producer_active || shared_mem_ptr->consumer_active) {
    sleep(5);

    if (shared_mem_ptr->producer_active) {
        if (shared_mem_ptr->producer_counter == prev_prod_count) {
            printf("[Monitor] Producer seems stuck, sending SIGUSR1 to %d\n", producer_pid);
            kill(producer_pid, SIGUSR1);
        } else {
            prev_prod_count = shared_mem_ptr->producer_counter;
        }
    }

    if (shared_mem_ptr->consumer_active) {
        if (shared_mem_ptr->consumer_counter == prev_cons_count) {
            printf("[Monitor] Consumer seems stuck, sending SIGUSR1 to %d\n", consumer_pid);
            kill(consumer_pid, SIGUSR1);
        } else {
            prev_cons_count = shared_mem_ptr->consumer_counter;
        }
    }

    // Check if children have terminated
    int status;
    pid_t terminated_pid;
    while ((terminated_pid = waitpid(-1, &status, WNOHANG)) > 0) {
        if (terminated_pid == producer_pid) {
            printf("[Monitor] Producer (%d) terminated.\n", producer_pid);
            shared_mem_ptr->producer_active = 0;
        } else if (terminated_pid == consumer_pid) {
            printf("[Monitor] Consumer (%d) terminated.\n", consumer_pid);
            shared_mem_ptr->consumer_active = 0;
        }
    }
}
printf("[Monitor] Both children terminated. Performing final cleanup.\n");
cleanup(); // Final cleanup by the monitor
```

**לוגיקת היצרן (Producer Logic):**

```c
// Producer process
int item = 0;
while (1) {
    // Manual retry loop for sem_wait
    int ret;
    do {
        ret = sem_wait(sem_empty);
    } while (ret == -1 && errno == EINTR);
    if (ret == -1) { perror("Producer sem_empty failed"); break; }

    do {
        ret = sem_wait(sem_mutex);
    } while (ret == -1 && errno == EINTR);
    if (ret == -1) { perror("Producer sem_mutex failed"); break; }

    shared_mem_ptr->buffer[shared_mem_ptr->head] = item;
    shared_mem_ptr->head = (shared_mem_ptr->head + 1) % BUFFER_SIZE;
    shared_mem_ptr->producer_counter++;
    printf("[Producer %d] Produced: %d, counter: %d\n", getpid(), item, shared_mem_ptr->producer_counter);
    item++;

    sem_post(sem_mutex);
    sem_post(sem_full);
    sleep(1); // Simulate work
}
```

**לוגיקת הצרכן (Consumer Logic):**

```c
// Consumer process
while (1) {
    // Manual retry loop for sem_wait
    int ret;
    do {
        ret = sem_wait(sem_full);
    } while (ret == -1 && errno == EINTR);
    if (ret == -1) { perror("Consumer sem_full failed"); break; }

    do {
        ret = sem_wait(sem_mutex);
    } while (ret == -1 && errno == EINTR);
    if (ret == -1) { perror("Consumer sem_mutex failed"); break; }

    int consumed_item = shared_mem_ptr->buffer[shared_mem_ptr->tail];
    shared_mem_ptr->tail = (shared_mem_ptr->tail + 1) % BUFFER_SIZE;
    shared_mem_ptr->consumer_counter++;
    printf("[Consumer %d] Consumed: %d, counter: %d\n", getpid(), consumed_item, shared_mem_ptr->consumer_counter);

    sem_post(sem_mutex);
    sem_post(sem_empty);
    sleep(2); // Simulate work
}
```

**סיכום לפתרון מלא:**
הפתרון המלא יכלול קובץ C בודד עם פונקציית `main` שתבצע אתחול משאבים, תיצור את היצרן והצרכן באמצעות `fork()`, ותריץ את לוגיקת המנטר. לוגיקת היצרן והצרכן תהיה בפונקציות נפרדות שנקראות בתהליכים הצאצאים. כל התהליכים יגדירו signal handlers מתאימים ופונקציית ניקוי משאבים שתופעל בסיום. הדגש הוא על הטיפול הנכון ב-`EINTR` סביב קריאות `sem_wait` כדי להבטיח עמידות לאותות.

הפתרון המוצע מדגים שימוש מתקדם במנגנוני IPC ואותות לסנכרון ותקשורת בין תהליכי אב ובן. להלן עיקרי הקוד והאתגרים שהוא פותר:

**קוד המקור (C/C++):**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/wait.h>
#include <time.h>
#include <errno.h>

#define NUM_CHILDREN 5
#define THRESHOLD 50

typedef struct {
    pid_t pid;
    int number;
    int pipe_fd[2]; // for child to parent communication
} child_info_t;

child_info_t children_info[NUM_CHILDREN];
volatile sig_atomic_t children_reaped = 0; // for parent to count reaped children

// Signal handler for SIGCHLD in parent
void sigchld_handler(int signum) {
    int status;
    pid_t p;
    while ((p = waitpid(-1, &status, WNOHANG)) > 0) {
        children_reaped++;
        // printf("Parent: Reaped child %d\n", p); // Optional logging
    }
}

// Signal handler for SIGUSR1 in child
void sigusr1_handler(int signum) {
    printf("Child %d (PID %d): Received SIGUSR1. Continuing to wait.\n", getpid(), getpid());
}

// Signal handler for SIGTERM in child
void sigterm_handler(int signum) {
    printf("Child %d (PID %d): Received SIGTERM. Exiting.\n", getpid(), getpid());
    exit(0);
}

// Helper function to safely read/write, handling EINTR
ssize_t safe_write(int fd, const void *buf, size_t count) {
    ssize_t res;
    while ((res = write(fd, buf, count)) == -1 && errno == EINTR);
    return res;
}

ssize_t safe_read(int fd, void *buf, size_t count) {
    ssize_t res;
    while ((res = read(fd, buf, count)) == -1 && errno == EINTR);
    return res;
}

void child_process(int child_idx, int write_fd) {
    // Set up signal handlers for SIGUSR1 and SIGTERM
    struct sigaction sa_usr1, sa_term;

    sa_usr1.sa_handler = sigusr1_handler;
    sigemptyset(&sa_usr1.sa_mask);
    sa_usr1.sa_flags = SA_RESTART; // Restart interrupted syscalls
    if (sigaction(SIGUSR1, &sa_usr1, NULL) == -1) {
        perror("sigaction SIGUSR1 child");
        exit(1);
    }

    sa_term.sa_handler = sigterm_handler;
    sigemptyset(&sa_term.sa_mask);
    sa_term.sa_flags = SA_RESTART; // Restart interrupted syscalls
    if (sigaction(SIGTERM, &sa_term, NULL) == -1) {
        perror("sigaction SIGTERM child");
        exit(1);
    }

    // Block SIGUSR1 and SIGTERM temporarily while writing to pipe
    // This prevents the parent from sending a signal before the child is ready to suspend.
    sigset_t block_mask, old_mask;
    sigemptyset(&block_mask);
    sigaddset(&block_mask, SIGUSR1);
    sigaddset(&block_mask, SIGTERM);
    if (sigprocmask(SIG_BLOCK, &block_mask, &old_mask) == -1) {
        perror("sigprocmask block child");
        exit(1);
    }

    // Generate random number
    srand(time(NULL) ^ getpid()); // Seed with PID and time for better randomness
    int num = rand() % 100 + 1; // Number between 1 and 100
    printf("Child %d (PID %d): Generated number %d\n", child_idx, getpid(), num);

    // Write number to parent via pipe
    if (safe_write(write_fd, &num, sizeof(num)) != sizeof(num)) {
        perror("Child: failed to write to pipe");
        exit(1);
    }
    close(write_fd); // Close write end in child after sending

    // Unblock SIGUSR1 and SIGTERM, and then wait for signals using sigsuspend
    printf("Child %d (PID %d): Sent number %d, now waiting for signal...\n", child_idx, getpid(), num);

    sigset_t empty_mask;
    sigemptyset(&empty_mask); // An empty mask means no signals are blocked when suspended

    // Restore the original signal mask (unblocking SIGUSR1/SIGTERM) and then suspend
    if (sigprocmask(SIG_SETMASK, &old_mask, NULL) == -1) { // Restore old mask BEFORE suspending
        perror("sigprocmask unblock child before suspend");
        exit(1);
    }

    while(1) {
        // sigsuspend atomically sets the process's signal mask to empty_mask and waits for a signal.
        // Upon signal delivery and handler return, the original mask is restored.
        // This ensures that SIGUSR1/SIGTERM are unblocked while waiting, and race conditions are avoided.
        sigsuspend(&empty_mask);
    }
}

int main() {
    // Set up SIGCHLD handler in parent
    struct sigaction sa_chld;
    sa_chld.sa_handler = sigchld_handler;
    sigemptyset(&sa_chld.sa_mask);
    sa_chld.sa_flags = SA_RESTART | SA_NOCLDSTOP; // Restart interrupted syscalls, don't get signals for stopped children
    if (sigaction(SIGCHLD, &sa_chld, NULL) == -1) {
        perror("sigaction SIGCHLD parent");
        exit(1);
    }

    // Block SIGUSR1 and SIGTERM in parent (parent is not expected to handle these specific signals from children)
    sigset_t parent_block_mask;
    sigemptyset(&parent_block_mask);
    sigaddset(&parent_block_mask, SIGUSR1);
    sigaddset(&parent_block_mask, SIGTERM);
    if (sigprocmask(SIG_BLOCK, &parent_block_mask, NULL) == -1) {
        perror("sigprocmask block parent");
        exit(1);
    }

    // Create children and pipes
    for (int i = 0; i < NUM_CHILDREN; ++i) {
        if (pipe(children_info[i].pipe_fd) == -1) {
            perror("pipe");
            exit(1);
        }

        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            exit(1);
        }

        if (pid == 0) { // Child process
            close(children_info[i].pipe_fd[0]); // Close read end in child
            // Close all other write ends that belong to other children's pipes
            for (int j = 0; j < NUM_CHILDREN; ++j) {
                if (j != i) { // This child doesn't need other children's pipes
                    close(children_info[j].pipe_fd[0]); // Read end of other pipes
                    close(children_info[j].pipe_fd[1]); // Write end of other pipes
                }
            }
            child_process(i, children_info[i].pipe_fd[1]);
            exit(0); // Should exit via sigterm_handler, but safety net
        } else { // Parent process
            children_info[i].pid = pid;
            close(children_info[i].pipe_fd[1]); // Close write end in parent
        }
    }

    // Parent reads numbers from children
    printf("Parent (PID %d): Reading numbers from children...\n", getpid());
    for (int i = 0; i < NUM_CHILDREN; ++i) {
        if (safe_read(children_info[i].pipe_fd[0], &(children_info[i].number), sizeof(int)) != sizeof(int)) {
            perror("Parent: failed to read from pipe");
            children_info[i].number = -1; // Indicate failure
        }
        close(children_info[i].pipe_fd[0]); // Close read end after reading
        printf("Parent: Received %d from child %d (PID %d)\n", children_info[i].number, i, children_info[i].pid);
    }

    // Sort children_info based on numbers (simple bubble sort for example)
    for (int i = 0; i < NUM_CHILDREN - 1; ++i) {
        for (int j = 0; j < NUM_CHILDREN - 1 - i; ++j) {
            if (children_info[j].number > children_info[j+1].number) {
                child_info_t temp = children_info[j];
                children_info[j] = children_info[j+1];
                children_info[j+1] = temp;
            }
        }
    }

    printf("Parent: Sorted numbers and PIDs:\n");
    for (int i = 0; i < NUM_CHILDREN; ++i) {
        printf("  Child PID %d: Number %d\n", children_info[i].pid, children_info[i].number);
    }

    // Send signals based on threshold
    printf("Parent: Sending signals to children...\n");
    for (int i = 0; i < NUM_CHILDREN; ++i) {
        if (children_info[i].number > THRESHOLD) {
            printf("Parent: Sending SIGTERM to child PID %d (number %d > %d)\n", children_info[i].pid, children_info[i].number, THRESHOLD);
            kill(children_info[i].pid, SIGTERM);
        } else {
            printf("Parent: Sending SIGUSR1 to child PID %d (number %d <= %d)\n", children_info[i].pid, children_info[i].number, THRESHOLD);
            kill(children_info[i].pid, SIGUSR1);
        }
    }

    // Wait for all children to be reaped
    printf("Parent: Waiting for all children to exit...\n");
    while (children_reaped < NUM_CHILDREN) {
        sleep(1); // Wait and let SIGCHLD handler do its work
    }

    printf("Parent: All children reaped. Parent exiting.\n");

    return 0;
}
```

**הסבר מפורט וניתוח אתגרים:**

1.  **טיפול באותות באמצעות `sigaction`**: במקום הפונקציה הישנה `signal()`, נעשה שימוש ב-`sigaction()`. זוהי הדרך המודרנית והמומלצת לטפל באותות מכיוון שהיא מספקת שליטה רבה יותר על התנהגות האות. לדוגמה:
    *   `sa_handler`: מציין את הפונקציה שתטפל באות.
    *   `sigemptyset(&sa.sa_mask)`: מבטיח ששום אות לא יהיה חסום אוטומטית בזמן שהמטפל באות פועל (ניתן גם להוסיף אותות ספציפיים למסכה זו).
    *   `SA_RESTART`: דגל זה גורם לקריאות מערכת איטיות (כמו `read`, `write`) שהופרעו על ידי אות, להתחיל מחדש באופן אוטומטי במקום להיכשל עם `EINTR`. זה משפר את עמידות הקוד.
    *   `SA_NOCLDSTOP` (עבור `SIGCHLD`): מונע מהמערכת לשלוח `SIGCHLD` כאשר תהליך בן נעצר (לדוגמה, עם `SIGSTOP`), אלא רק כאשר הוא מסיים את פעולתו (exit).

2.  **מניעת תנאי מרוץ וסנכרון (`sigprocmask`, `sigsuspend`)**:
    *   **בצד הבן**: לפני שהבן כותב את המספר שלו לצינור, הוא חוסם באופן זמני את האותות `SIGUSR1` ו-`SIGTERM` באמצעות `sigprocmask(SIG_BLOCK, ...)`. זה מבטיח שהאב לא יוכל לשלוח אות לבן לפני שהבן סיים את פעולתו הקריטית של כתיבה לצינור. רק לאחר שהמספר נשלח והבן מוכן להיכנס למצב המתנה, הוא משחרר את חסימת האותות ומשתמש ב-`sigsuspend(&empty_mask)` כדי להמתין לאות. `sigsuspend` היא פונקציה אטומית: היא משנה את מסכת האותות של התהליך למסכה הריקה שניתנה לה (כלומר, מאפשרת קבלת כל האותות), ואז משעה את התהליך עד לקבלת אות. כשהאות מטופל והמטפל חוזר, `sigsuspend` משחזרת את מסכת האותות המקורית. זה מונע מצב שבו אות נשלח בדיוק בין שחרור החסימה לבין כניסה למצב המתנה (window of vulnerability).
    *   **בצד האב**: האב חוסם את `SIGUSR1` ו-`SIGTERM` מכיוון שאינו מצפה לטפל בהם בעצמו. זהו נוהג מומלץ כדי למנוע קבלת אותות לא רצויים.

3.  **טיפול ב-`EINTR` (קריאות מערכת שנקטעו)**: למרות השימוש ב-`SA_RESTART`, קריאות מערכת מסוימות (או גרסאות ישנות יותר של ספריות) עדיין עלולות להיקטע על ידי אות ולחזור עם `errno == EINTR`. הפונקציות `safe_read()` ו-`safe_write()` מטפלות במצב זה באופן מפורש על ידי ניסיון חוזר של הפעולה עד להשלמתה בהצלחה או לכישלון מסיבה אחרת.

4.  **מניעת תהליכי זומבי (`SIGCHLD`, `waitpid`)**:
    *   תהליך זומבי נוצר כאשר תהליך בן מסיים את פעולתו אך תהליך האב שלו לא קרא את סטטוס היציאה שלו באמצעות `wait()` או `waitpid()`. תהליכי זומבי צורכים משאבי מערכת (בעיקר ערך בטבלת התהליכים).
    *   הפתרון מטפל בזה על ידי הגדרת מטפל לאות `SIGCHLD` בתהליך האב. מטפל זה מופעל בכל פעם שתהליך בן משנה סטטוס (לדוגמה, מסיים). בתוך המטפל, קריאה ל-`waitpid(-1, &status, WNOHANG)` בלולאה מבטיחה שכל הבנים שסיימו את פעולתם (גם אם מספר בנים סיימו בבת אחת) ייאספו (reaped) באופן מיידי, ובכך נמנעת יצירת תהליכי זומבי.

5.  **סגירת קצוות צינורות מיותרים**: כל תהליך (אב ובן) סוגר את קצוות הצינורות שאינם רלוונטיים עבורו. הבן סוגר את קצה הקריאה של הצינור שלו ואת שני קצוות הצינורות של שאר הבנים. האב סוגר את קצה הכתיבה של כל הצינורות. זה חשוב כדי למנוע מצבי קיפאון (deadlocks) וכדי שהקריאה מהצינור תדע מתי לסיים (EOF) כאשר כל קצוות הכתיבה נסגרו.

