#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h> // For non-blocking pipe read
#include <sys/select.h> // For select()

#define NUM_CHILDREN 3
#define BUFFER_SIZE 256

// Global flags for signal handling in children
volatile sig_atomic_t is_paused = 0;
volatile sig_atomic_t child_id_global = -1; // To store child ID for logging

// Signal handler for SIGUSR1 (pause)
void sigusr1_handler(int signum) {
    is_paused = 1;
    // printf("Child %d: Received SIGUSR1 - PAUSING.\n", child_id_global);
}

// Signal handler for SIGUSR2 (resume)
void sigusr2_handler(int signum) {
    is_paused = 0;
    // printf("Child %d: Received SIGUSR2 - RESUMING.\n", child_id_global);
}

// Signal handler for SIGCHLD (parent)
void sigchld_handler(int signum) {
    int status;
    pid_t pid;
    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        if (WIFEXITED(status)) {
            printf("Parent: Child PID %d exited normally with status %d.\n", pid, WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("Parent: Child PID %d terminated by signal %d.\n", pid, WTERMSIG(status));
        }
    }
}

// Child process function
void child_task(int child_id, int write_pipe_fd) {
    child_id_global = child_id; // Set global ID for signal handler logging
    int counter = 0;
    char buffer[BUFFER_SIZE];

    // Setup signal handlers for SIGUSR1 and SIGUSR2
    struct sigaction sa_usr1, sa_usr2;
    memset(&sa_usr1, 0, sizeof(sa_usr1));
    sa_usr1.sa_handler = sigusr1_handler;
    sa_usr1.sa_flags = SA_RESTART; // Restart interrupted system calls
    sigemptyset(&sa_usr1.sa_mask); // No signals blocked inside handler
    if (sigaction(SIGUSR1, &sa_usr1, NULL) == -1) {
        perror("sigaction SIGUSR1");
        exit(EXIT_FAILURE);
    }

    memset(&sa_usr2, 0, sizeof(sa_usr2));
    sa_usr2.sa_handler = sigusr2_handler;
    sa_usr2.sa_flags = SA_RESTART;
    sigemptyset(&sa_usr2.sa_mask);
    if (sigaction(SIGUSR2, &sa_usr2, NULL) == -1) {
        perror("sigaction SIGUSR2");
        exit(EXIT_FAILURE);
    }

    // Close the read end of the pipe in child
    close(0); // Close stdin for child

    while (1) {
        // Check if paused
        while (is_paused) {
            // Sleep to avoid busy-waiting while paused
            sleep(1); 
        }

        counter++;
        snprintf(buffer, BUFFER_SIZE, "Child %d: counter = %d\n", child_id, counter);

        // Write to pipe
        if (write(write_pipe_fd, buffer, strlen(buffer)) == -1) {
            if (errno == EPIPE) { // Parent closed read end
                printf("Child %d: Pipe closed by parent. Exiting.\n", child_id);
            } else {
                perror("Child write to pipe");
            }
            break; // Exit loop if pipe write fails
        }

        sleep(1); // Simulate work
    }

    close(write_pipe_fd);
    printf("Child %d: Exiting.\n", child_id);
    exit(EXIT_SUCCESS);
}

int main() {
    pid_t children_pids[NUM_CHILDREN];
    int pipe_fds[2]; // pipe_fds[0] for read, pipe_fds[1] for write

    // Create the pipe
    if (pipe(pipe_fds) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    // Set the read end of the pipe to non-blocking
    if (fcntl(pipe_fds[0], F_SETFL, O_NONBLOCK) == -1) {
        perror("fcntl O_NONBLOCK");
        exit(EXIT_FAILURE);
    }

    // Setup SIGCHLD handler in parent
    struct sigaction sa_chld;
    memset(&sa_chld, 0, sizeof(sa_chld));
    sa_chld.sa_handler = sigchld_handler;
    sa_chld.sa_flags = SA_RESTART | SA_NOCLDSTOP; // SA_NOCLDSTOP prevents SIGCHLD on child stop/continue
    sigemptyset(&sa_chld.sa_mask);
    if (sigaction(SIGCHLD, &sa_chld, NULL) == -1) {
        perror("sigaction SIGCHLD");
        exit(EXIT_FAILURE);
    }

    // Block SIGUSR1 and SIGUSR2 in parent to avoid unexpected behavior
    // The parent only sends these, doesn't handle them for itself.
    sigset_t block_mask;
    sigemptyset(&block_mask);
    sigaddset(&block_mask, SIGUSR1);
    sigaddset(&block_mask, SIGUSR2);
    if (sigprocmask(SIG_BLOCK, &block_mask, NULL) == -1) {
        perror("sigprocmask block SIGUSR1/2");
        exit(EXIT_FAILURE);
    }

    // Fork children
    for (int i = 0; i < NUM_CHILDREN; ++i) {
        pid_t pid = fork();

        if (pid == -1) {
            perror("fork");
            // Clean up already forked children and exit
            for (int j = 0; j < i; ++j) {
                kill(children_pids[j], SIGTERM);
            }
            exit(EXIT_FAILURE);
        } else if (pid == 0) { // Child process
            close(pipe_fds[0]); // Child closes read end of pipe
            child_task(i, pipe_fds[1]);
            // child_task will exit
        } else { // Parent process
            children_pids[i] = pid;
            printf("Parent: Forked child %d with PID %d.\n", i, pid);
        }
    }

    // Parent closes write end of the pipe
    close(pipe_fds[1]);

    printf("Parent: Enter command (e.g., 'p 0' to pause child 0, 'r 1' to resume child 1, 'q' to quit):\n");

    char command[BUFFER_SIZE];
    fd_set read_fds;
    int max_fd = pipe_fds[0]; // Max file descriptor for select

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(STDIN_FILENO, &read_fds);
        FD_SET(pipe_fds[0], &read_fds);

        struct timeval tv;
        tv.tv_sec = 1; // Wait up to 1 second
        tv.tv_usec = 0;

        int retval = select(max_fd + 1, &read_fds, NULL, NULL, &tv);

        if (retval == -1) {
            if (errno == EINTR) continue; // Interrupted by signal, retry
            perror("select");
            break;
        } else if (retval == 0) {
            // Timeout, no data to read, continue loop
        } else {
            // Data available
            if (FD_ISSET(STDIN_FILENO, &read_fds)) {
                // Command from user
                if (fgets(command, BUFFER_SIZE, stdin) == NULL) {
                    perror("fgets");
                    break;
                }
                char cmd_char;
                int child_idx;
                if (sscanf(command, "%c %d", &cmd_char, &child_idx) == 2) {
                    if (child_idx >= 0 && child_idx < NUM_CHILDREN) {
                        if (cmd_char == 'p') {
                            kill(children_pids[child_idx], SIGUSR1);
                            printf("Parent: Sent SIGUSR1 to child %d (PID %d).\n", child_idx, children_pids[child_idx]);
                        } else if (cmd_char == 'r') {
                            kill(children_pids[child_idx], SIGUSR2);
                            printf("Parent: Sent SIGUSR2 to child %d (PID %d).\n", child_idx, children_pids[child_idx]);
                        } else {
                            printf("Unknown command: %s", command);
                        }
                    } else {
                        printf("Invalid child ID.\n");
                    }
                } else if (strcmp(command, "q\n") == 0) {
                    printf("Parent: Quitting. Terminating children.\n");
                    for (int i = 0; i < NUM_CHILDREN; ++i) {
                        if (children_pids[i] > 0) { // If child is still alive
                            kill(children_pids[i], SIGTERM);
                        }
                    }
                    break;
                } else {
                    printf("Invalid input format. Use 'p <child_id>', 'r <child_id>' or 'q'.\n");
                }
            }

            if (FD_ISSET(pipe_fds[0], &read_fds)) {
                // Data from pipe
                ssize_t bytes_read;
                while ((bytes_read = read(pipe_fds[0], buffer, BUFFER_SIZE - 1)) > 0) {
                    buffer[bytes_read] = '\0';
                    printf("Parent (Pipe): %s", buffer);
                }
                if (bytes_read == -1 && errno != EWOULDBLOCK) {
                    perror("Parent read from pipe");
                    // Potentially break here, or handle specific errors
                }
            }
        }
    }

    // Wait for all children to terminate (if not already handled by SIGCHLD and exit)
    for (int i = 0; i < NUM_CHILDREN; ++i) {
        if (children_pids[i] > 0) { // Only wait for children that were successfully forked
            waitpid(children_pids[i], NULL, 0);
        }
    }

    close(pipe_fds[0]);
    printf("Parent: All children terminated. Exiting.\n");
    return 0;
}

solution.explanation:
הפתרון כולל קוד C המממש את הדרישות באמצעות זיכרון משותף (Shared Memory) וסמפורים (System V Semaphores) לתקשורת וסנכרון בין תהליך אב לבן, וטיפול באות `SIGINT` לסיום עבודה אלגנטי וניקוי משאבים.

**מבנה הזיכרון המשותף:**
הזיכרון המשותף מוגדר כמבנה `shared_data_t` המכיל:
*   מערך `buffer` המשמש כבָּפֶר מעגלי עבור מספרים שלמים.
*   אינדקסים `in` ו-`out` למעקב אחר מיקום הכתיבה והקריאה בבָּפֶר.
*   דגל `terminate_flag` מסוג `volatile sig_atomic_t`, המשמש לאיתות סיום עבודה לשני התהליכים בעקבות קבלת `SIGINT`. השימוש ב-`volatile` מבטיח שהקומפיילר לא יבצע אופטימיזציות שימנעו קריאה עדכנית של הדגל, ו-`sig_atomic_t` מבטיח שהגישה אליו אטומית ובטוחה מתוך Signal Handler.

**הסמפורים:**
נעשה שימוש בשלושה סמפורים של System V, המנוהלים כקבוצת סמפורים:
1.  `empty`: סמפור מונה (counting semaphore) המציין את מספר המקומות הפנויים בבָּפֶר. מאותחל לגודל הבָּפֶר (`BUFFER_SIZE`). האב מבצע עליו `sem_wait` לפני כתיבה, והבן מבצע עליו `sem_post` לאחר קריאה.
2.  `full`: סמפור מונה המציין את מספר הפריטים המלאים בבָּפֶר. מאותחל ל-0. הבן מבצע עליו `sem_wait` לפני קריאה, והאב מבצע עליו `sem_post` לאחר כתיבה.
3.  `mutex`: סמפור בינארי (binary semaphore / mutex) להבטחת גישה הדדית בלעדית (mutual exclusion) לאינדקסים `in`, `out` ולמערך `buffer` עצמו. מאותחל ל-1. שני התהליכים מבצעים עליו `sem_wait` לפני גישה לאזור הקריטי ו-`sem_post` לאחר מכן.

**תהליך העבודה:**
1.  **יצירת משאבים:** תהליך האב יוצר את קטע הזיכרון המשותף ואת קבוצת הסמפורים באמצעות `shmget` ו-`semget` בהתאמה. הוא מאתחל את הסמפורים ואת מבנה הנתונים בזיכרון המשותף.
2.  **יצירת תהליכים:** האב יוצר את תהליך הבן באמצעות `fork()`.
3.  **הצמדת זיכרון משותף:** שני התהליכים מצמידים את קטע הזיכרון המשותף למרחב הכתובות שלהם באמצעות `shmat`.
4.  **Signal Handling:** בשני התהליכים, מוגדר Signal Handler עבור `SIGINT` באמצעות `sigaction`. ה-handler פשוט מעדכן את `terminate_flag` בזיכרון המשותף ל-1. חשוב לציין שפעולות מורכבות (כמו ניקוי משאבים) אינן בטוחות לביצוע בתוך Signal Handler, ולכן רק דגל אטומי מעודכן.
5.  **לולאות עבודה:**
    *   **אב (Producer):** בלולאה אינסופית, האב ממתין לסמפור `empty`, מבצע `sem_wait` על `mutex`, כותב מספר לזיכרון המשותף, מעדכן את `in`, מבצע `sem_post` על `mutex`, ומבצע `sem_post` על `full`. הוא בודק את `terminate_flag` באופן מחזורי, ואם הוא מוגדר, הוא יוצא מהלולאה.
    *   **בן (Consumer):** בלולאה אינסופית, הבן ממתין לסמפור `full`, מבצע `sem_wait` על `mutex`, קורא מספר מהזיכרון המשותף, מעדכן את `out`, מבצע `sem_post` על `mutex`, ומבצע `sem_post` על `empty`. הוא בודק את `terminate_flag` באופן מחזורי, ואם הוא מוגדר, הוא יוצא מהלולאה.
    *   חשוב לציין כי קריאות `sem_wait` עשויות להיות מופסקות על ידי אותות (עם `errno == EINTR`). במקרה כזה, התוכנית בודקת את `terminate_flag` לפני ניסיון חוזר או יציאה. כמו כן, אם תהליך מסיים בזמן שהוא מחזיק בסמפור (למשל, `mutex` או `empty`/`full` לאחר ביצוע `sem_wait` עליהם), הוא משחרר אותם לפני היציאה מהלולאה כדי למנוע מצב של חסימת תהליכים אחרים.

**סיום עבודה וניקוי משאבים:**
1.  כאשר אחד התהליכים מקבל `SIGINT` (או שניהם), ה-handler מעדכן את `terminate_flag` בזיכרון המשותף. כתוצאה מכך, שני התהליכים יבחינו בדגל ויצאו מלולאות העבודה שלהם.
2.  כל תהליך מנתק את קטע הזיכרון המשותף ממרחב הכתובות שלו באמצעות `shmdt()`.
3.  תהליך האב ממתין לסיום תהליך הבן באמצעות `waitpid()`. זה מבטיח שהבן הספיק לנתק את הזיכרון המשותף לפני שהאב מנסה להשמיד אותו.
4.  לאחר שהבן סיים, האב אחראי להשמיד את המשאבים המשותפים: הוא משתמש ב-`shmctl(..., IPC_RMID)` להשמדת קטע הזיכרון המשותף וב-`semctl(..., IPC_RMID)` להשמדת קבוצת הסמפורים. פעולות אלה מבטיחות שאין "זבל" של משאבים משותפים במערכת לאחר סיום התוכנית.

**התמודדות עם אתגרים:**
*   **סנכרון:** הסמפורים `empty`, `full`, `mutex` מטפלים באופן קלאסי בבעיית יצרן-צרכן, מונעים גישה במקביל לאזור קריטי ומבטיחים שהיצרן לא יכתוב לבָּפֶר מלא והצרכן לא יקרא מבָּפֶר ריק.
*   **טיפול באותות:** שימוש בדגל אטומי בזיכרון משותף מאפשר תקשורת בטוחה של אות הסיום בין ה-Signal Handler ללולאות הראשיות של שני התהליכים, תוך הימנעות מפעולות לא בטוחות בתוך ה-Handler. דגל זה מאפשר גם לצאת מקריאות חוסמות של סמפורים במקרה של קבלת אות.
*   **ניקוי משאבים:** הגישה לפיה האב ממתין לבן ורק אז משמיד את המשאבים, מבטיחה שכל התהליכים סיימו להשתמש במשאבים לפני שהם נמחקים. זה מונע שגיאות ודליפות זיכרון במערכת ההפעלה.

