#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <signal.h>
#include <errno.h>
#include <time.h> // For sleep/nanosleep, and random seed
#include <sys/wait.h> // For waitpid

#define SHM_KEY 1234
#define SEM_KEY 5678
#define BUFFER_SIZE 10 // Size of the circular buffer

// Structure for shared memory
typedef struct {
    int buffer[BUFFER_SIZE];
    int in;  // Producer index
    int out; // Consumer index
    volatile sig_atomic_t terminate_flag; // Flag for graceful termination
} shared_data_t;

// Semaphore union for semctl (required by POSIX, but for System V IPC it's part of the standard usage)
union semun {
    int              val;    /* Value for SETVAL */
    struct semid_ds *buf;    /* Buffer for IPC_STAT, IPC_SET */
    unsigned short  *array;  /* Array for GETALL, SETALL */
    struct seminfo  *__buf;  /* Buffer for IPC_INFO (Linux specific) */
};

// Global variables for IPC IDs and shared memory pointer
int shmid;
int semid;
shared_data_t *shm_ptr = NULL;

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT) {
        if (shm_ptr != NULL) {
            shm_ptr->terminate_flag = 1;
        }
        fprintf(stderr, "\nProcess %d received SIGINT. Setting termination flag.\n", getpid());
    }
}

// Function to perform a semaphore operation
// Returns 0 on success, -1 on failure (e.g., interrupted by signal and terminate_flag is set)
int sem_op(int sem_num, int op) {
    struct sembuf sb;
    sb.sem_num = sem_num;
    sb.sem_op = op;
    sb.sem_flg = 0; // No flags, blocking operation

    // Loop to handle EINTR (interrupted system call)
    while (semop(semid, &sb, 1) == -1) {
        if (errno == EINTR) {
            if (shm_ptr != NULL && shm_ptr->terminate_flag) {
                // If termination flag is set, break the loop and exit
                return -1;
            }
            // Otherwise, retry the semaphore operation
            continue;
        } else {
            perror("semop failed");
            exit(EXIT_FAILURE);
        }
    }
    return 0;
}

// Function to initialize semaphores
void init_semaphores() {
    union semun arg;
    unsigned short values[3];

    // sem_num 0: empty slots (initially BUFFER_SIZE)
    // sem_num 1: full slots (initially 0)
    // sem_num 2: mutex for shared buffer access (initially 1)
    values[0] = BUFFER_SIZE; // empty
    values[1] = 0;           // full
    values[2] = 1;           // mutex

    arg.array = values;
    if (semctl(semid, 0, SETALL, arg) == -1) {
        perror("semctl SETALL failed");
        exit(EXIT_FAILURE);
    }
    printf("Semaphores initialized: empty=%d, full=%d, mutex=%d\n", values[0], values[1], values[2]);
}

// Parent process (Producer)
void producer_process() {
    printf("Producer (PID %d) started.\n", getpid());
    srand(time(NULL) ^ getpid()); // Seed random number generator

    while (!shm_ptr->terminate_flag) {
        int item = rand() % 100;

        // P(empty)
        if (sem_op(0, -1) == -1) break; // Decrement empty count

        // P(mutex)
        if (sem_op(2, -1) == -1) {
            // If terminated while waiting for mutex, release empty and exit
            sem_op(0, 1); // Increment empty count back
            break;
        }

        // Critical section: write to shared buffer
        shm_ptr->buffer[shm_ptr->in] = item;
        printf("Producer (PID %d) produced item: %d at index %d\n", getpid(), item, shm_ptr->in);
        shm_ptr->in = (shm_ptr->in + 1) % BUFFER_SIZE;

        // V(mutex)
        sem_op(2, 1); // Release mutex

        // V(full)
        sem_op(1, 1); // Increment full count

        // Simulate some work
        usleep(rand() % 500000 + 100000); // 100ms - 600ms
    }
    printf("Producer (PID %d) exiting loop.\n", getpid());
}

// Child process (Consumer)
void consumer_process() {
    printf("Consumer (PID %d) started.\n", getpid());
    srand(time(NULL) ^ getpid()); // Seed random number generator

    while (!shm_ptr->terminate_flag) {
        // P(full)
        if (sem_op(1, -1) == -1) break; // Decrement full count

        // P(mutex)
        if (sem_op(2, -1) == -1) {
            // If terminated while waiting for mutex, release full and exit
            sem_op(1, 1); // Increment full count back
            break;
        }

        // Critical section: read from shared buffer
        int item = shm_ptr->buffer[shm_ptr->out];
        printf("Consumer (PID %d) consumed item: %d from index %d\n", getpid(), item, shm_ptr->out);
        shm_ptr->out = (shm_ptr->out + 1) % BUFFER_SIZE;

        // V(mutex)
        sem_op(2, 1); // Release mutex

        // V(empty)
        sem_op(0, 1); // Increment empty count

        // Simulate some work
        usleep(rand() % 500000 + 100000); // 100ms - 600ms
    }
    printf("Consumer (PID %d) exiting loop.\n", getpid());
}

// Cleanup function
void cleanup_resources(pid_t child_pid) { // Pass child_pid to cleanup
    if (shm_ptr != (shared_data_t *)-1 && shm_ptr != NULL) { // Check for valid shm_ptr
        if (shmdt(shm_ptr) == -1) {
            perror("shmdt failed");
        } else {
            printf("Process %d detached shared memory.\n", getpid());
        }
    }

    // Only the parent process (the one that forked child_pid) should destroy IPC resources
    if (child_pid > 0) { // This is the parent process
        // Wait for child to ensure it has detached
        int status;
        if (waitpid(child_pid, &status, 0) == -1) { // Use waitpid to wait for specific child
            perror("waitpid failed");
        }
        printf("Parent (PID %d) waited for child (PID %d) to terminate.\n", getpid(), child_pid);

        if (shmctl(shmid, IPC_RMID, NULL) == -1) {
            perror("shmctl IPC_RMID failed");
        } else {
            printf("Shared memory segment %d destroyed by parent.\n", shmid);
        }

        if (semctl(semid, 0, IPC_RMID) == -1) {
            perror("semctl IPC_RMID failed");
        } else {
            printf("Semaphore set %d destroyed by parent.\n", semid);
        }
    }
}


int main() {
    struct sigaction sa;
    // Set up the signal handler for SIGINT
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART; // Restart interrupted system calls by default, but our sem_op handles EINTR explicitly

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction failed");
        exit(EXIT_FAILURE);
    }

    // 1. Create shared memory segment
    shmid = shmget(SHM_KEY, sizeof(shared_data_t), IPC_CREAT | 0666);
    if (shmid == -1) {
        perror("shmget failed");
        exit(EXIT_FAILURE);
    }
    printf("Shared memory segment %d created.\n", shmid);

    // 2. Attach shared memory segment
    shm_ptr = (shared_data_t *)shmat(shmid, NULL, 0);
    if (shm_ptr == (shared_data_t *)-1) {
        perror("shmat failed");
        // Attempt to remove shared memory if attachment failed
        shmctl(shmid, IPC_RMID, NULL); 
        exit(EXIT_FAILURE);
    }
    printf("Shared memory attached at %p.\n", shm_ptr);

    // 3. Initialize shared data
    shm_ptr->in = 0;
    shm_ptr->out = 0;
    shm_ptr->terminate_flag = 0;

    // 4. Create semaphore set
    semid = semget(SEM_KEY, 3, IPC_CREAT | 0666); // 3 semaphores: empty, full, mutex
    if (semid == -1) {
        perror("semget failed");
        // Attempt to remove shared memory if semaphore creation failed
        shmdt(shm_ptr);
        shmctl(shmid, IPC_RMID, NULL);
        exit(EXIT_FAILURE);
    }
    printf("Semaphore set %d created.\n", semid);

    // 5. Initialize semaphores
    init_semaphores();

    pid_t pid = fork();

    if (pid == -1) {
        perror("fork failed");
        // Clean up everything if fork fails
        shmdt(shm_ptr);
        shmctl(shmid, IPC_RMID, NULL);
        semctl(semid, 0, IPC_RMID);
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // Child process
        consumer_process();
    } else { // Parent process
        producer_process();
    }

    // Cleanup resources (both parent and child will call this)
    cleanup_resources(pid);

    return 0;
}
