    shm_ptr = (shm_data_t *)shmat(shmid, NULL, 0);
    if (shm_ptr == (shm_data_t *)-1) { perror("shmat"); exit(1); }

    semid = semget(SEM_KEY, 1, IPC_CREAT | 0666);
    if (semid == -1) { perror("semget"); exit(1); }

    // Initialize semaphore to 1 (mutex)
    if (semctl(semid, 0, SETVAL, 1) == -1) { perror("semctl SETVAL"); exit(1); }

    // Initialize shared data
    shm_ptr->next_task_index = 0;
    shm_ptr->shutdown_flag = 0;
    for (int i = 0; i < NUM_WORKERS; ++i) {
        shm_ptr->status[i] = 0; // 0 = idle, 1 = working, 2 = finished
    }

    printf("Parent (PID %d) created shared memory and semaphores.\n", getpid());

    // Fork child processes
    for (int i = 0; i < NUM_WORKERS; ++i) {
        pids[i] = fork();
        if (pids[i] == -1) {
