            // Child inherits shm_ptr. No need to re-attach unless explicitly desired.

            int worker_id = i;
            while (!child_should_exit) { // Loop until shutdown requested
                // Acquire semaphore - needs to handle EINTR
                while (semop(semid, &acquire_sem, 1) == -1) {
                    if (errno == EINTR) {
                        if (child_should_exit) { // Re-check shutdown flag after EINTR
                            goto end_child_loop; // Exit gracefully
                        }
                        continue; // Try again if interrupted by non-shutdown signal
                    }
                    perror("semop acquire");
                    cleanup_child();
                    exit(1);
                }

                // Critical section: Access shared memory
                if (child_should_exit) { // Re-check after acquiring semaphore
                    semop(semid, &release_sem, 1); // Release before exiting
                    goto end_child_loop;
                }

                // Simulate task processing
                int current_task = shm_ptr->next_task_index++;
                if (current_task >= 10) { // Example: only 10 tasks available
                    semop(semid, &release_sem, 1);
                    goto end_child_loop; // No more tasks, child can exit even without shutdown signal
                }
                printf("Worker %d (PID %d) processing task %d.\n", worker_id, getpid(), current_task);
                shm_ptr->status[worker_id] = 1; // Working

                // Release semaphore immediately after updating shared state
                semop(semid, &release_sem, 1);

                sleep(1 + (rand() % 2)); // Simulate work outside critical section

                // If status update is critical, it needs its own critical section or part of the existing one.
                // For simplicity, let's say the status '1' (working) is temporary.
            }
        end_child_loop:
            cleanup_child();
            exit(0);
        }
    }

    // Parent's main loop (manager)
    // Simulate parent doing other work and then initiating shutdown
    sleep(5);
    printf("Parent initiating shutdown for workers.\n");
    // Parent sets a global flag in shared memory (optional, but can be used for other logic)
    shm_ptr->shutdown_flag = 1; 

    for (int i = 0; i < NUM_WORKERS; ++i) {
        if (pids[i] > 0) {
            printf("Parent sending SIGUSR1 to worker %d (PID %d).\n", i, pids[i]);
            kill(pids[i], SIGUSR1);
        }
    }

    // Parent waits for all children to terminate
    // The SIGCHLD handler should take care of reaping, but parent still needs to wait
    // for all children to ensure they've all exited before cleaning up IPC.
    for (int i = 0; i < NUM_WORKERS; ++i) {
        int status;
        pid_t waited_pid;
        while ((waited_pid = waitpid(pids[i], &status, 0)) == -1 && errno == EINTR) {
            // Interrupted, try again
        }
        if (waited_pid == -1) {
            perror("waitpid");
        }
        printf("Parent collected worker %d (PID %d) with status %d.\n", i, pids[i], status);
    }

    cleanup_parent();

    return 0;
}
```

solution.explanation:
הפתרון מציג תוכנית C המממשת את התרחיש הנדרש באמצעות שילוב של `fork()`, `pipe()` וטיפול באותות (`signals`).

**קוד מקור:**
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>

#define N_CHILDREN 3

// Global variables for signal handlers
volatile sig_atomic_t children_completed_count = 0;
volatile sig_atomic_t sigint_received = 0;
pid_t child_pids[N_CHILDREN]; // To map PIDs to indices

// Signal handler for SIGUSR1
void handle_sigusr1(int sig, siginfo_t *info, void *ucontext) {
    (void)sig; // Unused parameter
    (void)ucontext; // Unused parameter

    pid_t sender_pid = info->si_pid;
    for (int i = 0; i < N_CHILDREN; ++i) {
        if (child_pids[i] == sender_pid) {
            children_completed_count++;
            break;
        }
    }
}

// Signal handler for SIGCHLD
void handle_sigchld(int sig) {
    (void)sig; // Unused parameter
    int status;
    pid_t pid;
    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        // Child reaped
    }
}

// Signal handler for SIGINT
void handle_sigint(int sig) {
    (void)sig; // Unused parameter
    sigint_received = 1;
    fprintf(stderr, "\nהורה: התקבלה בקשת סיום (SIGINT). מסיים פעולה.\n");
}

int main() {
    // pipes[i][0] for read, pipes[i][1] for write
    int p2c_pipes[N_CHILDREN][2]; // Parent to Child
    int c2p_pipes[N_CHILDREN][2]; // Child to Parent

    // Set up signal handlers
    struct sigaction sa_usr1, sa_chld, sa_int;

    // SIGUSR1 handler
    sa_usr1.sa_sigaction = handle_sigusr1;
    sigemptyset(&sa_usr1.sa_mask);
    sa_usr1.sa_flags = SA_RESTART | SA_SIGINFO; // SA_SIGINFO to get sender PID
    if (sigaction(SIGUSR1, &sa_usr1, NULL) == -1) {
        perror("sigaction SIGUSR1");
        exit(EXIT_FAILURE);
    }

    // SIGCHLD handler
    sa_chld.sa_handler = handle_sigchld;
    sigemptyset(&sa_chld.sa_mask);
    sa_chld.sa_flags = SA_RESTART | SA_NOCLDSTOP; // SA_NOCLDSTOP to not get signals for stopped children
    if (sigaction(SIGCHLD, &sa_chld, NULL) == -1) {
        perror("sigaction SIGCHLD");
        exit(EXIT_FAILURE);
    }

    // SIGINT handler
    sa_int.sa_handler = handle_sigint;
    sigemptyset(&sa_int.sa_mask);
    sa_int.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa_int, NULL) == -1) {
        perror("sigaction SIGINT");
        exit(EXIT_FAILURE);
    }

    // Create pipes and fork children
    for (int i = 0; i < N_CHILDREN; ++i) {
        if (pipe(p2c_pipes[i]) == -1) {
            perror("pipe p2c");
            exit(EXIT_FAILURE);
        }
        if (pipe(c2p_pipes[i]) == -1) {
            perror("pipe c2p");
            exit(EXIT_FAILURE);
        }

        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            exit(EXIT_FAILURE);
        } else if (pid == 0) { // Child process
            // Close unused pipe ends
            for (int j = 0; j < N_CHILDREN; ++j) {
                if (j == i) {
                    close(p2c_pipes[j][1]); // Child doesn't write to its p2c pipe
                    close(c2p_pipes[j][0]); // Child doesn't read from its c2p pipe
                } else {
                    close(p2c_pipes[j][0]);
                    close(p2c_pipes[j][1]);
                    close(c2p_pipes[j][0]);
                    close(c2p_pipes[j][1]);
                }
            }

            // Child logic
            int received_id;
            if (read(p2c_pipes[i][0], &received_id, sizeof(received_id)) == -1) {
                perror("child read from p2c pipe");
                exit(EXIT_FAILURE);
            }
            close(p2c_pipes[i][0]); // Close read end after reading

            printf("ילד %d (PID %d): קיבל את המזהה %d. מעבד...\n", i, getpid(), received_id);
            int result = received_id + 1;

            if (write(c2p_pipes[i][1], &result, sizeof(result)) == -1) {
                perror("child write to c2p pipe");
                exit(EXIT_FAILURE);
            }
            close(c2p_pipes[i][1]); // Close write end after writing

            // Send SIGUSR1 to parent
            if (kill(getppid(), SIGUSR1) == -1) {
                perror("child kill SIGUSR1");
                exit(EXIT_FAILURE);
            }

            printf("ילד %d (PID %d): סיים ושלח תוצאה %d ואות SIGUSR1 להורה.\n", i, getpid(), result);
            exit(EXIT_SUCCESS);
        } else { // Parent process
            child_pids[i] = pid; // Store child PID for SIGUSR1 handler
            // Close unused pipe ends
            close(p2c_pipes[i][0]); // Parent doesn't read from its p2c pipe
            close(c2p_pipes[i][1]); // Parent doesn't write to its c2p pipe
        }
    }

    // Parent writes initial IDs to children
    for (int i = 0; i < N_CHILDREN; ++i) {
        if (sigint_received) break;
        if (write(p2c_pipes[i][1], &i, sizeof(i)) == -1) {
            perror("parent write to p2c pipe");
            exit(EXIT_FAILURE);
        }
        close(p2c_pipes[i][1]); // Close write end after writing
    }

    // Parent waits for all children to complete and reads results
    int results[N_CHILDREN];
    printf("הורה (PID %d): ממתין לתוצאות מ-%d ילדים...\n", getpid(), N_CHILDREN);

    // Block SIGINT temporarily to prevent premature exit during critical section
    sigset_t block_mask, old_mask;
    sigemptyset(&block_mask);
    sigaddset(&block_mask, SIGINT);
    if (sigprocmask(SIG_BLOCK, &block_mask, &old_mask) == -1) {
        perror("sigprocmask block");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < N_CHILDREN; ++i) {
        if (sigint_received) break;
        if (read(c2p_pipes[i][0], &results[i], sizeof(results[i])) == -1) {
            if (errno == EINTR && sigint_received) { // Check if interrupted by SIGINT
                fprintf(stderr, "הורה: קריאה מצינור הופרעה על ידי SIGINT.\n");
                break;
            }
            perror("parent read from c2p pipe");
            exit(EXIT_FAILURE);
        }
        close(c2p_pipes[i][0]); // Close read end after reading
        printf("הורה: קיבל תוצאה %d מילד %d.\n", results[i], i);
    }

    // Restore original signal mask
    if (sigprocmask(SIG_SETMASK, &old_mask, NULL) == -1) {
        perror("sigprocmask unblock");
        exit(EXIT_FAILURE);
    }

    // Wait for all children to send SIGUSR1 (if not already received)
    while (children_completed_count < N_CHILDREN && !sigint_received) {
        pause(); // Wait for any signal
    }

    if (!sigint_received) {
        printf("הורה: כל הילדים סימנו סיום ושלחו תוצאות. סיכום:\n");
        for (int i = 0; i < N_CHILDREN; ++i) {
            printf("  תוצאה מילד %d: %d\n", i, results[i]);
        }
    } else {
        fprintf(stderr, "הורה: סיום עקב SIGINT לפני השלמת כל המשימות.\n");
        // Clean up remaining children if any
        for (int i = 0; i < N_CHILDREN; ++i) {
            // Send SIGTERM to any child that might still be running
            if (child_pids[i] > 0 && kill(child_pids[i], SIGTERM) == -1 && errno != ESRCH) {
                perror("kill SIGTERM");
            }
        }
    }

    // Ensure all children are reaped
    int status;
    pid_t reaped_pid;
    while ((reaped_pid = wait(&status)) > 0) {
        // Child reaped
    }
    if (reaped_pid == -1 && errno != ECHILD) {
        perror("wait");
    }

    return sigint_received ? EXIT_FAILURE : EXIT_SUCCESS;
}
```

**הסבר מפורט:**
הפתרון מציג תוכנית C המממשת את התרחיש הנדרש באמצעות שילוב של `fork()`, `pipe()` וטיפול באותות (`signals`).

**יצירת תהליכים ותקשורת (IPC)**:
1.  **`fork()`**: ההורה יוצר שלושה תהליכי ילד באמצעות קריאות חוזרות ל-`fork()`. כל ילד מקבל מזהה ייחודי (0, 1, 2) בהתאם לסדר היצירה. ה-PID של כל ילד נשמר במערך `child_pids` בהורה לצורך זיהוי מאוחר יותר על ידי מטפל האותות.
2.  **`pipe()`**: לכל תהליך ילד מוקצים שני צינורות ייעודיים:
    *   `p2c_pipes[i][2]`: צינור תקשורת מההורה לילד `i`. ההורה כותב לצינור זה (`p2c_pipes[i][1]`) והילד `i` קורא ממנו (`p2c_pipes[i][0]`).
    *   `c2p_pipes[i][2]`: צינור תקשורת מהילד `i` להורה. הילד `i` כותב לצינור זה (`c2p_pipes[i][1]`) וההורה קורא ממנו (`c2p_pipes[i][0]`).
    *   **ניהול יעיל של קצוות הצינורות**: כל תהליך (הורה או ילד) סוגר את הקצוות הלא נחוצים של הצינורות מיד לאחר ה-`fork()` כדי למנוע דליפות משאבים או חסימות מיותרות. לדוגמה, ההורה סוגר את קצוות הקריאה של צינורות `p2c` ואת קצוות הכתיבה של צינורות `c2p`. הילד סוגר את קצוות הכתיבה של צינורות `p2c` ואת קצוות הקריאה של צינורות `c2p`, וכן את כל קצוות הצינורות של ילדים אחרים.

**טיפול באותות (Signals)**:
נעשה שימוש בפונקציה `sigaction()` לטיפול באותות, המאפשרת טיפול מודרני ואמין יותר מאשר `signal()`.
1.  **`SIGUSR1`**:
    *   **מטרה**: ילד שסיים את משימתו שולח אות `SIGUSR1` להורה כדי ליידע אותו.
    *   **טיפול בהורה**: פונקציית הטיפול `handle_sigusr1` מוגדרת עם הדגל `SA_SIGINFO`, המאפשר לקבל מידע נוסף על האות, כולל ה-PID של התהליך השולח (`info->si_pid`). ההורה משתמש במידע זה כדי לזהות איזה ילד שלח את האות (על ידי השוואה ל-`child_pids`) ולעדכן מונה גלובלי `children_completed_count`. זה מאפשר להורה לעקוב כמה ילדים סיימו.
    *   **טיפול בילד**: הילד שולח `SIGUSR1` להורה באמצעות `kill(getppid(), SIGUSR1)`.
2.  **`SIGCHLD`**:
    *   **מטרה**: אות זה נשלח להורה כאשר תהליך ילד משנה את מצבו (לדוגמה, מסיים פעולה).
    *   **טיפול בהורה**: פונקציית הטיפול `handle_sigchld` קוראת ל-`waitpid(-1, NULL, WNOHANG)` בלולאה. שימוש ב-`WNOHANG` מבטיח שהקריאה אינה חוסמת את ההורה אם אין ילדים שסיימו, והלולאה מבטיחה שכל הילדים ששינו מצב ייאספו (reaped) כדי למנוע תהליכי Zombie.
3.  **`SIGINT`**:
    *   **מטרה**: סיום התוכנית על ידי המשתמש (לרוב באמצעות Ctrl+C).
    *   **טיפול בהורה**: פונקציית הטיפול `handle_sigint` מגדירה דגל גלובלי `sigint_received` ל-1. ההורה בודק דגל זה בלולאה הראשית שלו. אם הדגל פעיל, ההורה מדפיס הודעת סיום, שולח אות `SIGTERM` לכל הילדים שעדיין פועלים (כדי לנסות לסיים אותם באופן יזום), ורק אז מסיים את פעולתו תוך ניקוי משאבים.

**מניעת תנאי מירוץ וסיום נאות**:
*   **נתונים מצינורות מול אותות**: ההורה מתוכנן לקרוא את התוצאות מכל צינור `c2p_pipes[i][0]` באופן חוסם. כלומר, ההורה ימתין לנתונים מכל ילד בנפרד. מכיוון שהילד כותב את התוצאה לצינור *לפני* שליחת ה-`SIGUSR1`, מובטח שהנתונים יהיו זמינים להורה כאשר הוא יקרא. ה-`SIGUSR1` משמש כאן יותר כאישור נוסף לסיום המשימה, והמונה `children_completed_count` מאפשר להורה לדעת כמה ילדים *הבטיחו* שסיימו.
*   **חסימת `SIGINT` בקטעים קריטיים**: ההורה חוסם זמנית את אות `SIGINT` באמצעות `sigprocmask()` לפני תחילת קריאת התוצאות מהילדים. זאת כדי למנוע מצב שבו `read()` מופרע על ידי `SIGINT` לפני השלמת קריאת הנתונים, מה שעלול להשאיר את המערכת במצב לא עקבי. לאחר הקריאה מכל הצינורות, המסכה המקורית של האותות משוחזרת. אם ה-`read()` בכל זאת מופרע על ידי `SIGINT` (למרות הדגל `SA_RESTART`), הקוד בודק את `errno == EINTR` יחד עם `sigint_received` ומטפל בכך בהתאם.
*   **ניקוי ילדים (Reaping Children)**: פונקציית הטיפול ב-`SIGCHLD` מבטיחה שכל ילד שמסיים פעולה ייקלט על ידי ההורה, ובכך נמנעים תהליכי Zombie. בנוסף, בסיום התוכנית, ההורה מבצע לולאת `wait()` אחרונה (לאחר הקריאות החוסמות מהצינורות) כדי לוודא שכל הילדים נאספו, גם אם ה-`SIGCHLD` handler לא הספיק לטפל בכולם, או במקרה של סיום עקב `SIGINT`.
*   **סיום חלקי עקב `SIGINT`**: אם `SIGINT` מתקבל, ההורה מזהה זאת, מדפיס הודעה, מנסה לשלוח `SIGTERM` לכל הילדים שעדיין רשומים כפעילים (באמצעות ה-PIDs שנשמרו), ורק אז מסיים את עצמו. זהו ניסיון לסגור את התוכנית בצורה נקייה ככל האפשר גם במקרה של הפרעה.

