#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

#define NUM_TO_SEND 100

int pipe_fd[2];
pid_t child1_pid, child2_pid;
volatile int sigusr1_received = 0; // Flag for signal handler

void sigusr1_handler(int signum) {
    sigusr1_received = 1;
    fprintf(stderr, "Child %d: SIGUSR1 received!\n", getpid());
}

void child_process_func(int child_id) {
    close(pipe_fd[1]); // Close write end in children
    int num;
    long long sum = 0;

    if (child_id == 1) {
        // Child 1 sets up SIGUSR1 handler
        signal(SIGUSR1, sigusr1_handler); // Using signal() for initial draft
    }

    while (read(pipe_fd[0], &num, sizeof(int)) > 0) {
        if (child_id == 1 && sigusr1_received) {
            fprintf(stderr, "Child 1 (%d): Stopping read due to SIGUSR1. Current sum: %lld\n", getpid(), sum);
            break; // Exit loop if SIGUSR1 was received
        }
        sum += num;
    }
    close(pipe_fd[0]); // Close read end

    printf("Child %d (%d) final sum: %lld\n", child_id, getpid(), sum);
    exit(0);
}

int main() {
    if (pipe(pipe_fd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    child1_pid = fork();
    if (child1_pid == -1) {
        perror("fork child 1");
        exit(EXIT_FAILURE);
    } else if (child1_pid == 0) {
        child_process_func(1);
    }

    child2_pid = fork();
    if (child2_pid == -1) {
        perror("fork child 2");
        exit(EXIT_FAILURE);
    } else if (child2_pid == 0) {
        child_process_func(2);
    }

    // Parent process
    close(pipe_fd[0]); // Close read end in parent

    for (int i = 1; i <= NUM_TO_SEND; ++i) {
        if (i == NUM_TO_SEND / 2 + 1) { // After writing 50 numbers (1-50)
            printf("Parent (%d): Sending SIGUSR1 to Child 1 (%d)\n", getpid(), child1_pid);
            if (kill(child1_pid, SIGUSR1) == -1) {
                perror("kill SIGUSR1");
            }
        }
        if (write(pipe_fd[1], &i, sizeof(int)) == -1) {
            perror("write to pipe");
            break;
        }
    }
    close(pipe_fd[1]); // Close write end, signaling EOF to children

    int status;
    waitpid(child1_pid, &status, 0);
    printf("Parent: Child 1 (%d) exited with status %d\n", child1_pid, WEXITSTATUS(status));
    waitpid(child2_pid, &status, 0);
    printf("Parent: Child 2 (%d) exited with status %d\n", child2_pid, WEXITSTATUS(status));

    return 0;
}

